e: number, pageSize?: number): AxiosPromise {\n    return this.instance.get(\n      `/api/admin/forms/?page=${page}${pageSize ? `&pageSize=${pageSize}` : ''}`\n    );\n  }\n\n  public createForm(form: any): AxiosPromise {\n    return this.instance.post(\n      `/api/admin/forms/`, form\n    );\n  }\n\n  public updateForm(form: any): AxiosPromise {\n    return this.instance.patch(\n      `/api/admin/forms/${form._id}/`, form\n    );\n  }\n\n  public deleteForm(form: any): AxiosPromise {\n    return this.instance.delete(\n      `/api/admin/forms/${form._id}/`\n    );\n  }\n\n  public getInventoryCarFiles(inventoryCarId: string): AxiosPromise {\n    return this.instance.get(\n      `/api/inventory-car/files/${inventoryCarId}/`\n    );\n  }\n\n  public deleteInventoryCarFile(inventoryFileId: string): AxiosPromise {\n    return this.instance.delete(\n      `/api/inventory-car/files/${inventoryFileId}/`\n    );\n  }\n\n  public validateContectaID(conectaID: string): AxiosPromise {\n    return this.instance.post(\n      `/requests/vehicles/validate-conecta/`, { conectaID }\n    );\n  }\n\n  public getMyStudiosDashboards(type? : string) : AxiosPromise {\n    return this.instance.get(`/api/stats/my-studio/${type ? `?type=${type}` : ''}`)\n  }\n\n  public getStudiosDashboards(type? : string) : AxiosPromise {\n    return this.instance.get(`/api/stats/studios/${type ? `?type=${type}` : ''}`)\n  }\n\n  public deleteStudio(id: String): AxiosPromise {\n    return this.instance.delete(\n      `/api/stats/studios/${id}/`\n    );\n  }\n\n  public getStudioUsers(): AxiosPromise {\n    return this.instance.get(\n      '/api/stats/users/'\n    )\n  }\n\n  public createStudio(studio: ITempStudio): AxiosPromise {\n    return this.instance.post(\n      `/api/stats/studios/`, {studio}\n    );\n  }\n\n  public updateStudio(studio: ITempStudio): AxiosPromise {\n    return this.instance.patch(\n      `/api/stats/studios/${studio._id}/`, {studio}\n    );\n  }\n}\n","import { IUser } from '../../../../../src/app/interfaces/user.interface';\nimport { IWindow } from '../interfaces/window';\nimport * as queryString from 'query-string';\n\ndeclare let window: IWindow;\n\nexport function parseReplicableURL(url: string): string {\n  let query = queryString.parse(window.location.search);\n  const hastQueryURL = url.split('?');\n  if (hastQueryURL.length > 1) {\n    let text = window.location.search;\n    if (window.location.search) {\n      if (text?.length) {\n        text = `${text}&${hastQueryURL[hastQueryURL.length - 1]}`;\n      } else {\n        text = `?${hastQueryURL[hastQueryURL.length - 1]}`;\n      }\n    } else {\n      text = `?${hastQueryURL[hastQueryURL.length - 1]}`;\n    }\n    query = queryString.parse(text);\n  }\n  /* process here actions by parameters in query param */\n  return `${url.split('?')[0]}?${queryString.stringify(query)}`;\n}\n\nexport function getExtension(name: string): string {\n  const descomposition = name.split('.');\n  if (descomposition.length) {\n    return descomposition[descomposition.length - 1].toLowerCase();\n  }\n  return '';\n}\n\nexport function getIconFromExtension(extension: string): string {\n  // https://en.wikipedia.org/wiki/List_of_Microsoft_Office_filename_extensions\n  const word = ['doc', 'docx', 'docm', 'dotx'];\n  const excel = ['xls', 'xlsx', 'xlsm', 'xltx', 'csv'];\n  const pdf = ['pdf'];\n  const image = ['jpeg', 'gif', 'jpg', 'png'];\n  extension = extension.toLowerCase();\n  if (word.includes(extension)) {\n    return 'word';\n  } else if (excel.includes(extension)) {\n    return 'excel';\n  } else if (pdf.includes(extension)) {\n    return 'pdf';\n  } else if (image.includes(extension)) {\n    return extension;\n  } else {\n    return 'file';\n  }\n}\n\nexport function getDistFromBottom(): number {\n  const scrollPosition: number = window.pageYOffset;\n  const windowSize: number = window.innerHeight;\n  const bodyHeight: number = document.body.offsetHeight;\n\n  return Math.max(bodyHeight - (scrollPosition + windowSize), 0);\n}\n\nexport function maxText(text: string, max: number): string {\n  if (text && text.length > max) {\n    return `${text.slice(0, max)}...`;\n  }\n  return text;\n}\n\nexport function updateTooltip() {\n  $('[data-toggle=\"tooltip\"]').tooltip();\n}\n\ninterface IMixpanelProps {\n  [index: string]: any;\n}\n\nexport function statusFooterButttonsModal(status: boolean) {\n  $('.modal-footer button').attr({\n    disabled: status\n  });\n}\n\nexport function showModal(show: boolean) {\n  ($('#andesModal') as any).modal(show ? 'show' : 'hide');\n}\n\nexport function goToSection(id: string) {\n  const $id = $(id);\n  const distance = ($id as any).offset().top - ($('.main-header') as any).height() - 50;\n  if ($id && $id.length) {\n    $('html, body').stop().animate({\n      scrollTop: distance\n    }, 500);\n  }\n}\n\nexport function reactTrackMixpanel(event: string, props: IMixpanelProps): void {\n  if (typeof (window.mixpanel) === 'object') {\n    mixpanel.register({\n      // team: window.user.teamName,\n      // team_id: window.user.teamID,\n      // role: window.user.roleID,\n      // role_id: window.user.roleName,\n      // venue: window.user.venueName,\n      // venue_id: window.user.venueID,\n      // department: window.user.departmentName,\n      // department_id: window.user.departmentID\n    });\n    mixpanel.identify(window.user._id);\n    mixpanel.people.set({\n      // $first_name: window.user.first_name,\n      // $last_name: window.user.last_name,\n      // $email: window.user.email,\n      // team: window.user.teamName,\n      // team_id: window.user.teamID,\n      // role: window.user.roleID,\n      // role_id: window.user.roleName,\n      // venue: window.user.venueName,\n      // venue_id: window.user.venueID,\n      // department: window.user.departmentName,\n      // department_id: window.user.departmentID\n    });\n    window.mixpanel.track(event, props);\n  }\n}\n\n// https://stackoverflow.com/questions/19999388/check-if-user-is-using-ie-with-jquery\nexport function isIntenertExplorer() {\n  const ua = window.navigator.userAgent;\n\n  const msie = ua.indexOf('MSIE ');\n  if (msie > 0) {\n    // IE 10 or older => return version number\n    return parseInt(ua.substring(msie + 5, ua.indexOf('.', msie)), 10);\n  }\n\n  const trident = ua.indexOf('Trident/');\n  if (trident > 0) {\n    // IE 11 => return version number\n    const rv = ua.indexOf('rv:');\n    return parseInt(ua.substring(rv + 3, ua.indexOf('.', rv)), 10);\n  }\n\n  const edge = ua.indexOf('Edge/');\n  if (edge > 0) {\n    // Edge (IE 12+) => return version number\n    return parseInt(ua.substring(edge + 5, ua.indexOf('.', edge)), 10);\n  }\n  // other browser\n  return false;\n}\n\nexport function hasPermission(user: IUser, permission: string) {\n  if (window.user && window.user.userPermissions && window.user.userPermissions.length && permission && permission.length) {\n    return window.user.userPermissions.some((p) => p.codeName === permission);\n  }\n  return false;\n}\n\nexport function isDercoDercocenter(object?: any) {\n  let user: IUser = window.user;\n  const dercocenterID = '5c1a80f84fba86565186a757';\n  return object && object.hasOwnProperty('company') ?\n    object.company === dercocenterID : user.company._id === dercocenterID;\n}\n","module.exports = swal;","import * as React from 'react';\nimport { IWindow } from '../../interfaces/window';\nimport MixpanelTracker from './MixpanelTracker';\n\ndeclare let window: IWindow;\n\nabstract class TrackingBasePage<PropsType, StateType> extends React.Component<PropsType, StateType>{\n  abstract title : string;\n\n  protected constructor(props: PropsType) {\n    super(props);\n    this.trackPage = this.trackPage.bind(this);\n    this.registerUser = this.registerUser.bind(this);\n    this.shouldTrack = this.shouldTrack.bind(this);\n    this.componentDidMount = this.componentDidMount.bind(this);\n    this.trackClick = this.trackClick.bind(this);\n  }\n\n  public componentDidMount() : void {\n    // set the title of the page\n    document.title = `OSA Andes | ${this.title}`;\n    this.registerUser();\n    this.trackPage();\n  }\n\n  trackPage() : void {\n    if (this.shouldTrack())\n      MixpanelTracker.getInstance().trackAction(this.title);\n  }\n\n  trackClick(title: string, properties: any = {}) : void {\n    if (this.shouldTrack())\n      MixpanelTracker.getInstance().trackAction(`${this.title} - ${title}`, properties);\n  }\n\n  public shouldTrack() : boolean {\n    return !window.user.email.includes('@osacontrol.com');\n  }\n\n  private registerUser() : void {\n    if (this.shouldTrack() && !window.isTracked) {\n      MixpanelTracker.getInstance().identifyUser(window.user);\n      window.isTracked = true;\n    }\n  }\n}\n\n export default TrackingBasePage;\n","import * as PropTypes from 'prop-types';\nimport * as React from 'react';\nimport BreadcrumbApp from './BreadcrumbApp';\nimport FooterApp from './FooterApp';\nimport HeaderApp from './HeadeApp';\nimport MenuApp from './MenuApp';\nimport { IInventoryState } from '../actions/inventory.actions';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport moment = require('moment');\n// import {Dispatch} from 'react-redux';\n// import {RouteComponentProps} from \"react-router\";\n\n// interface IPropsType extends RouteComponentProps<{ ticket: number }> {\ninterface IPropsType extends RouteComponentProps<{}> {\n  children: JSX.Element;\n  router: any;\n  title: string;\n  cMenu: string;\n  cSubMenu: string;\n  cAction?: string;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass AppContainer extends React.Component<IPropsType, IStateType> {\n\n  static propTypes = {\n    title: PropTypes.string.isRequired,\n    cMenu: PropTypes.string.isRequired,\n    cSubMenu: PropTypes.string.isRequired,\n    cAction: PropTypes.string\n  };\n\n  componentDidMount() {\n    const { location: { query } } = this.props.router;\n    if (query?.integration === 'webview') {\n      const $body = $('body');\n      $body\n        .removeClass('skin-purple')\n        .css({ 'background-color': '#ecf0f5' });\n      $body.append( `<div class=\"text-muted text-center\" style=\"position: absolute; height: 30px; width: 100%;\">Copyright (c) ${moment().format('YYYY')} <a href=\"http://www.osacontrol.com\" target=\"_blank\">OSA SPA</a>. All rights reserved.</div>` );\n\n    }\n  }\n\n  public render() {\n    const { title, cMenu, cSubMenu, cAction } = this.props;\n    const { location: { query } } = this.props.router;\n    if (query?.integration === 'webview') {\n      return (\n        <React.Fragment>\n          {this.props.children}\n        </React.Fragment>\n      );\n    }\n    return (\n      <React.Fragment>\n        <HeaderApp />\n        <MenuApp cMenu={cMenu} cSubMenu={cSubMenu} />\n        <div className='content-wrapper' style={{ minHeight: `${window.innerHeight - 51}px` }}>\n          <section className='content-header'>\n            <h1>{title ? title : '\\u00A0'}</h1>\n            <BreadcrumbApp cMenu={cMenu} cSubMenu={cSubMenu} cAction={cAction} />\n          </section>\n          {this.props.children}\n        </div>\n        <FooterApp />\n      </React.Fragment>\n    );\n  }\n}\n\nconst mapStateToProps = (state: { router: any }) => {\n  return {\n    router: state.router\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType | any>(mapStateToProps, mapDispatchToProps)(AppContainer);\n","module.exports = moment;","import * as React from 'react';\n\ninterface IPropsType {\n  condition: boolean;\n  children?: React.ReactNode;\n  alternative?: React.ReactNode;\n}\n\nconst ShowIf: React.FunctionComponent<IPropsType> = (props: IPropsType) => {\n  if (props.condition) {\n    return (\n      <>{props.children}</>\n    );\n  }\n  if (props.alternative) {\n    return (\n      <>{props.alternative}</>\n    );\n  }\n  return null;\n};\n\nexport default ShowIf;\n","// import * as PropTypes from 'prop-types';\nimport * as React from 'react';\nimport {connect} from 'react-redux';\nimport {Dispatch} from 'redux';\nimport {IModalState, ModalReduxAction} from '../../actions/modal.actions';\nimport {IUsersState} from '../../actions/users.actions';\n\ninterface IPropsType {\n  dispatch?: Dispatch<ModalReduxAction>;\n  modal?: IModalState;\n  modalLarge?: boolean;\n}\n\ninterface IStateType {\n  error: Error | null;\n  show: boolean;\n}\n\nclass ModalView extends React.Component<IPropsType, IStateType> {\n\n  // static propTypes = {\n  //   modal: PropTypes.object.isRequired,\n  //   dispatch: PropTypes.func.isRequired\n  // };\n\n  render() {\n    const {modal, modalLarge} = this.props;\n    return (\n      <div className=\"modal fade\" role=\"dialog\" id=\"andesModal\" tabIndex={-1}>\n        <div className={`modal-dialog ${modalLarge ? 'modal-lg' : ''}`} role=\"document\">\n          <div className=\"modal-content\">\n            <div className=\"modal-header\">\n              <button type=\"button\" className=\"close\" data-dismiss=\"modal\" aria-label=\"Close\"><span aria-hidden=\"true\">&times;</span></button>\n              <h4 className=\"modal-title\">{modal ? modal.title : ''}</h4>\n            </div>\n            <div className=\"modal-body\">\n              {modal ? modal.body : ''}\n            </div>\n            {\n              modal && modal.footer ?\n              <div className=\"modal-footer\">\n                {modal && modal.footer ? modal.footer : <button type=\"button\" className=\"btn btn-default\" data-dismiss=\"modal\">Cerrar</button>}\n              </div> : null\n            }\n          </div>\n        </div>\n      </div>\n    );\n  }\n}\n\nconst mapStateToProps = (state: { modal: IModalState, users: IUsersState }) => {\n  return {\n    modal: state.modal,\n    users: state.users\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(ModalView);\n","import * as PropTypes from 'prop-types';\nimport * as React from 'react';\n\ninterface IPropsType {\n  page: number;\n  pages: number;\n  changePage: (page: number) => void;\n}\n\nconst Paginator: React.FunctionComponent<IPropsType> = (props) => {\n  const {page, pages, changePage} = props;\n  return (\n    <ul className=\"pagination pagination-sm\">\n      {\n        new Array(pages).fill(1).map((item, index) => {\n          const key = index + 1;\n          const onClick = key !== page ? () => changePage(key) : undefined;\n          if ((key > page - 3 && key < page + 3) || (key === 1 || key === pages)) {\n            return (\n              <li className={`page-item ${key === page ? 'active' : ''}`} key={key}>\n                <a className=\"page-link\" href=\"javascript:void(0)\" onClick={onClick}>{key}</a>\n              </li>\n            );\n          }\n          if (key >= page + 3 && key === pages - 1) {\n            return (\n              <li className={`page-item disabled`} key={key}>\n                <a className=\"page-link\" href=\"javascript:void(0)\">...</a>\n              </li>\n            );\n          } else if (key <= page - 3 && key === 2) {\n            return (\n              <li className={`page-item disabled`} key={key}>\n                <a className=\"page-link\" href=\"javascript:void(0)\">...</a>\n              </li>\n            );\n          } else {\n            return null;\n          }\n        })\n      }\n    </ul>\n  );\n};\n\nPaginator.propTypes = {\n  page: PropTypes.number.isRequired,\n  pages: PropTypes.number.isRequired,\n  changePage: PropTypes.func.isRequired\n};\n\nexport default Paginator;\n","\nexport interface IModalState {\n  title: string;\n  body: JSX.Element| null;\n  footer: JSX.Element| null;\n}\n\ninterface ILoadData {\n  type: '/MODAL/LOAD_DATA';\n  payload: {\n    title: string;\n    body: JSX.Element | null;\n    footer?: JSX.Element | null;\n  };\n}\n\nexport function loadDataAction(title: string, body: JSX.Element, footer?: JSX.Element): ILoadData {\n  return {\n    type: '/MODAL/LOAD_DATA',\n    payload: {\n      title,\n      body,\n      footer\n    }\n  };\n}\n\ninterface IClear {\n  type: '/MODAL/CLEAR';\n}\n\nexport type ModalReduxAction =\n  ILoadData |\n  IClear;\n","const inputStringRequired = (value: string) => (value && value.toString().trim().length ? undefined : 'Este campo es requerido');\nconst validEmailRequired = (value: string) => /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,4}$/i.test(value) ? undefined : 'Este email no es valido';\nconst maxNumber = (max: number) => (value: number) => max < value ? `Debe ser menor a ${max}` : undefined;\nexport {\n  inputStringRequired,\n  validEmailRequired,\n  maxNumber\n};\n","import * as React from 'react';\nimport { InputHTMLAttributes } from 'react';\n\ninterface IPropsType {\n  input: InputHTMLAttributes<any>;\n  label: string;\n  labelOff?: boolean;\n  readOnly?: boolean;\n  onChange?: any;\n  type: string;\n  help: string;\n  placeholder: string;\n  meta: {\n    touched: boolean;\n    error: string;\n    warning: string;\n  };\n}\n\nconst InputField: React.FunctionComponent<IPropsType> = ({\n   input,\n   label,\n   labelOff,\n   placeholder,\n   type,\n   onChange,\n   readOnly,\n   help,\n   meta: { touched, error, warning }\n  }: IPropsType) => (\n  <div className={`form-group ${touched && error ? 'has-error' : warning ? 'has-warning' : ''}`}>\n    {!labelOff ? <label className='control-label text-ellipsis'>{label}</label> : null}\n    <input\n      {...input}\n      readOnly={readOnly}\n      onChange={onChange ? onChange : input.onChange}\n      className={`form-control input-sm`}\n      placeholder={placeholder}\n      type={type}\n    />\n    {\n      help ?\n        <small id='passwordHelpBlock' className='form-text text-muted'>\n          {help}\n        </small>\n        : null\n    }\n    {\n      touched &&\n      ((error && <span className='help-block text-ellipsis'>{error}</span>) ||\n        (warning && <span className='help-block text-ellipsis'>{warning}</span>)) || <span className='help-block'>&nbsp;</span>\n    }\n  </div>\n);\n\nexport default InputField;\n","import * as React from 'react';\n\ninterface IPropsType {\n  className?: string;\n  children?: React.ReactNode;\n  style?: React.CSSProperties;\n}\n\nconst Row: React.FunctionComponent<IPropsType> = (props: IPropsType) => {\n  return (\n    <div\n      className={`row${props.className && props.className.length ? ` ${props.className}` : ''}`}\n      style={props.style ? props.style : {}}\n    >\n      {props.children}\n    </div>\n  );\n};\n\nexport default Row;\n","import {ITransmittal} from '../../../../../src/distribution/interfaces/transmittal.interface';\nimport {\n  CANCEL_REQUEST_TRANSMITTAL,\n  CHANGE_ORDER_TRANSMITTAL,\n  CREATE_TRANSMITTAL_ITEM_TRANSMITTAL,\n  DELETE_TRANSMITTAL_ITEM_TRANSMITTAL,\n  DELETE_TRANSMITTAL_TRANSMITTAL,\n  FILTER_REQUEST_ITEMS_TRANSMITTAL,\n  IRequestItemsFilters,\n  ITransmittalActionTypes,\n  ITransmittalState,\n  LOAD_CARRIERS_TRANSMITTAL,\n  LOAD_DRIVERS_TRANSMITTAL, LOAD_MILESTONE_TYPES_TRANSMITTAL,\n  LOAD_REQUEST_ITEMS_TRANSMITTAL,\n  LOAD_TRANSMITTAL,\n  LOAD_VENUES_TRANSMITTAL,\n  LOADING_REQUEST_ITEMS_TRANSMITTAL,\n  LOADING_TRANSMITTAL,\n  TOOGLE_TAB_TRANSMITTAL,\n  UPDATE_TRANSMITTAL_ITEM_TRANSMITTAL,\n  UPDATE_TRANSMITTAL_TRANSMITTAL,\n  TRANSPORT_MILESTONE_LOAD_STATUS,\n} from './transmittal.types';\nimport ApiService from \"../utils/axios\";\nimport Axios, {AxiosError, AxiosResponse, CancelTokenSource} from \"axios\";\nimport {ThunkDispatch} from \"redux-thunk\";\nimport {IVenueModel} from '../../../../../src/app/models/venue.model';\nimport {ICarrierModel} from '../../../../../src/app/models/carrier.model';\nimport {arrayPush, autofill, FormAction, submit} from \"redux-form\";\nimport {IUserModel} from '../../../../../src/app/models/user.model';\nimport {IRequestItem} from '../../../../../src/request/interfaces/requestItem.interface';\nimport {ITransmittalItemModel} from '../../../../../src/distribution/models/transmittalItem.model';\nimport { IMilestoneType } from '../../../../../src/distribution/interfaces/milestoneType.interface';\nimport {IMilestone} from \"../../../../../src/distribution/interfaces\";\n\nexport default class TransmittalActions {\n  private api: ApiService;\n\n  public formName: string = 'transmittalForm';\n\n  constructor(\n    private dispatch: ThunkDispatch<{ transmittal: ITransmittalState }, {}, ITransmittalActionTypes | FormAction>\n  ) {\n    this.api = new ApiService();\n  }\n\n  public loadingAction(loading: boolean): void {\n    this.dispatch({\n      type: LOADING_TRANSMITTAL,\n      payload: {\n        loading\n      }\n    });\n  }\n\n  public loadAction(data: ITransmittal[], count: number, pages: number, page: number): void {\n    this.dispatch({\n      type: LOAD_TRANSMITTAL,\n      payload: {\n        data,\n        count,\n        pages,\n        page\n      }\n    });\n  }\n\n  public cancelRequestAction(source: CancelTokenSource): void {\n    this.dispatch({\n      type: CANCEL_REQUEST_TRANSMITTAL,\n      payload: {\n        source\n      }\n    });\n  }\n\n  public changeOrderAction(orderBy: string, orderType: string): void {\n    this.dispatch({\n      type: CHANGE_ORDER_TRANSMITTAL,\n      payload: {\n        orderBy,\n        orderType\n      }\n    });\n  }\n\n  public loadCarriers(carriers:  ICarrierModel[]): void {\n    this.dispatch({\n      type: LOAD_CARRIERS_TRANSMITTAL,\n      payload: {\n        carriers,\n      }\n    });\n  }\n\n  public loadDrivers(drivers: IUserModel[]): void {\n    this.dispatch({\n      type: LOAD_DRIVERS_TRANSMITTAL,\n      payload: {\n        drivers,\n      }\n    });\n  }\n\n  public loadMilestoneTypes(milestoneTypes: IMilestoneType[]): void {\n    this.dispatch({\n      type: LOAD_MILESTONE_TYPES_TRANSMITTAL,\n      payload: {\n        milestoneTypes,\n      }\n    });\n  }\n\n  public loadVenues(venues:  IVenueModel[]): void {\n    this.dispatch({\n      type: LOAD_VENUES_TRANSMITTAL,\n      payload: {\n        venues,\n      }\n    });\n  }\n\n  public toogleTab(transmittalId:  string): void {\n    this.dispatch({\n      type: TOOGLE_TAB_TRANSMITTAL,\n      payload: {\n        transmittalId,\n      }\n    });\n  }\n\n  public submit(form: string) {\n    this.dispatch(submit(form));\n  }\n\n  public autofill(field: string, value: any) {\n    this.dispatch(\n      autofill(this.formName, field, value),\n    );\n  }\n\n  public pushItem(value: any) {\n    this.dispatch(\n      arrayPush(this.formName, 'items', value)\n    );\n  }\n\n  public updateTransmittalAction(transmittal: Partial<ITransmittal>){\n    this.dispatch({\n      type: UPDATE_TRANSMITTAL_TRANSMITTAL,\n      payload: {\n        transmittal\n      }\n    })\n  }\n\n  public updateTransmittalThunkAction(transmittal: any) {\n    this.dispatch((dispatch) => {\n      const transmittalActions = new TransmittalActions(dispatch);\n      this.api.updateTransmittal(transmittal)\n        .then((response: AxiosResponse) => {\n          transmittalActions.updateTransmittalAction(response.data.data);\n        })\n        .catch((err: AxiosError) => {\n          this.api.errorHandler(err);\n        });\n    });\n  }\n\n  public deleteTransmittalAction(transmittal: Partial<ITransmittal>){\n    this.dispatch({\n      type: DELETE_TRANSMITTAL_TRANSMITTAL,\n      payload: {\n        transmittal\n      }\n    })\n  }\n\n  public deleteTransmittalItemAction(transmittalItem: Partial<ITransmittalItemModel>){\n    this.dispatch({\n      type: DELETE_TRANSMITTAL_ITEM_TRANSMITTAL,\n      payload: {\n        transmittalItem\n      }\n    })\n  }\n\n  public createTransmittalItemAction(transmittalItem: Partial<ITransmittal>){\n    this.dispatch({\n      type: CREATE_TRANSMITTAL_ITEM_TRANSMITTAL,\n      payload: {\n        transmittalItem\n      }\n    })\n  }\n\n  public updateTransmittalItemAction(transmittalItem: Partial<ITransmittal>){\n    this.dispatch({\n      type: UPDATE_TRANSMITTAL_ITEM_TRANSMITTAL,\n      payload: {\n        transmittalItem\n      }\n    })\n  }\n\n  public loadMilestoneAction(milestones: IMilestone[]): void {\n    this.dispatch( {\n      type: TRANSPORT_MILESTONE_LOAD_STATUS,\n      payload: {\n        milestones\n      }\n    });\n  }\n\n  public updateTransmittalItemThunkAction(transmitallItem: any) {\n    this.dispatch((dispatch) => {\n      const transmittalActions = new TransmittalActions(dispatch);\n      this.api.updateTransmittalItem(transmitallItem)\n        .then((response: AxiosResponse) => {\n          transmittalActions.updateTransmittalItemAction(response.data.data);\n        })\n        .catch((err: AxiosError) => {\n          this.api.errorHandler(err);\n        });\n    });\n  }\n\n  public getFormBaseData(): void {\n    this.dispatch((dispatch) => {\n      const transmittalActions = new TransmittalActions(dispatch);\n      transmittalActions.loadingAction(true);\n      Axios\n        .all([\n          this.api.getVenues({ page: 1, pageSize: 200, noPopulate: true }),\n          this.api.getCarriers(1, 200),\n          this.api.getDrivers(1, 200),\n          this.api.getMilestoneTypes({ page: 1, pageSize: 200 })\n        ])\n        .then(Axios.spread((venues, carriers, drivers,milestones) => {\n          transmittalActions.loadVenues(venues.data.results);\n          transmittalActions.loadCarriers(carriers.data.results);\n          transmittalActions.loadDrivers(drivers.data.results);\n          transmittalActions.loadMilestoneTypes(milestones.data.results);\n          transmittalActions.loadingAction(false);\n        }))\n        .catch((err: AxiosError): void => {\n          transmittalActions.loadingAction(false);\n          this.api.errorHandler(err);\n        });\n    })\n  }\n\n  public getTransmittalsThunkAction({\n  nextPage, orderBy, orderType, hideLoading, number\n}:{\n    nextPage: number,\n    orderBy: string,\n    orderType: string,\n    number?: string\n    hideLoading?: boolean\n}): void {\n    this.dispatch((dispatch, getState) => {\n      const state = getState();\n      const transmittalActions = new TransmittalActions(dispatch);\n      const page = nextPage ? nextPage : state.transmittal.pagination.page;\n      transmittalActions.loadingAction(!hideLoading);\n      transmittalActions.changeOrderAction(orderBy, orderType);\n      transmittalActions.cancelRequestAction(this.api.getSource());\n      Axios\n        .all([\n          this.api.getTransmittals({page, orderBy, orderType, number}),\n          this.api.getVenues({ page: 1, pageSize: 200, noPopulate: true }),\n          this.api.getCarriers(1, 200),\n          this.api.getDrivers(1, 200),\n          this.api.getMilestoneTypes({ page: 1, pageSize: 200 }),\n          this.api.getMilestones({ page: 1, pageSize: 200 })\n        ])\n        .then(Axios.spread((transmittals,venues, carriers, drivers, milestoneTypes, milestones) => {\n          const {data} = transmittals;\n          transmittalActions.loadAction(data.results, data.count, data.pages, page);\n          transmittalActions.loadVenues(venues.data.results);\n          transmittalActions.loadCarriers(carriers.data.results);\n          transmittalActions.loadDrivers(drivers.data.results);\n          transmittalActions.loadDrivers(drivers.data.results);\n          transmittalActions.loadMilestoneTypes(milestoneTypes.data.results);\n          transmittalActions.loadMilestoneAction(milestones.data.results)\n          transmittalActions.loadingAction(false);\n        }))\n        .catch((err: AxiosError) => {\n          transmittalActions.loadingAction(false);\n          this.api.errorHandler(err);\n        });\n    });\n  }\n\n  public loadingRequestItemAction(requestItemsLoading: boolean): void {\n    this.dispatch({\n      type: LOADING_REQUEST_ITEMS_TRANSMITTAL,\n      payload: {\n        requestItemsLoading,\n      }\n    });\n  }\n\n  public filterRequestItemAction(key: keyof IRequestItemsFilters, value: any | any[]): void {\n    this.dispatch({\n      type: FILTER_REQUEST_ITEMS_TRANSMITTAL,\n      payload: {\n        key,\n        value\n      }\n    });\n  }\n\n  public loadRequestItemAction(requestItems: IRequestItem[], count: number, pages: number, page: number): void {\n    this.dispatch({\n      type: LOAD_REQUEST_ITEMS_TRANSMITTAL,\n      payload: {\n        requestItems,\n        count,\n        pages,\n        page\n      }\n    });\n  }\n\n  public getRequestItemThunkAction(nextPage: number, hideLoading?: boolean) {\n    this.dispatch((dispatch, getState) => {\n      const state = getState();\n      const transmittalActions = new TransmittalActions(dispatch);\n      const page = nextPage ? nextPage : state.transmittal.requestItemsPagination.page;\n      transmittalActions.loadingRequestItemAction(!hideLoading);\n      transmittalActions.cancelRequestAction(this.api.getSource());\n      this.api.getRequestItems({\n        page,\n        pageSize: 20,\n        orderBy: \"request.number\",\n        orderType: \"descending\",\n        filters: {\n          ...state.transmittal.requestItemsfilters,\n          transmitttalModule: true\n        },\n      })\n        .then((response: AxiosResponse) => {\n          const {data} = response;\n          transmittalActions.loadRequestItemAction(data.results, data.count, data.pages, page);\n          transmittalActions.loadingRequestItemAction(false);\n        })\n        .catch((err: AxiosError) => {\n          transmittalActions.loadingRequestItemAction(false);\n          this.api.errorHandler(err);\n        });\n    });\n  }\n\n}\n","import * as React from 'react';\nimport * as unorm from 'unorm';\nimport {RefObject} from 'react';\n\ninterface IOption {\n  value: string;\n  text: any;\n  className?: string;\n}\n\ninterface IPropsType {\n  options: IOption[];\n  selected: string[];\n  className?: string;\n  displayItems?: number;\n  onClick: any;\n  selectAll?: any;\n  noneSelectedText?: string;\n  selectedText?: string;\n  separator?: string;\n  allOption?: boolean;\n  autoClouse?: boolean;\n  search?: boolean;\n  sm?: boolean;\n  displayHandler?: (value: boolean) => void;\n  notHideOnClickOutside?: boolean\n}\n\ninterface IStateType {\n  open: boolean;\n  searchText: string;\n}\n\nclass BootstrapSelect extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    open: false,\n    searchText: ''\n  };\n\n  readonly input: RefObject<HTMLInputElement>;\n  readonly dropdown: RefObject<HTMLInputElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.handlerOpen = this.handlerOpen.bind(this);\n    this.search = this.search.bind(this);\n    this.input = React.createRef();\n    this.dropdown = React.createRef();\n  }\n\n  componentDidMount() {\n    const {notHideOnClickOutside, autoClouse} = this.props;\n    if (notHideOnClickOutside && !autoClouse) {\n      $('.osa-dropwdown-button').on('click', (event) => {\n        $('.osa-dropdown').toggleClass('open');\n      });\n    }\n  }\n\n  componentWillUnmount() {\n    const {notHideOnClickOutside, autoClouse} = this.props;\n    if (notHideOnClickOutside && !autoClouse) {\n      $('.osa-dropwdown-button').remove('click')\n    }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      sm, options, selected, onClick, displayItems, noneSelectedText, selectedText, separator, allOption, search, autoClouse, selectAll, notHideOnClickOutside\n    } = this.props;\n    const  {searchText} = this.state;\n    const selectedItems = options.filter((option) => (selected.includes(option.value)));\n\n    return (\n      <div\n        ref={this.dropdown}\n        className={`osa-dropdown dropdown bootstrap-select form-control show-tick ${autoClouse ? '' : 'keep-inside-clicks-open'} ${sm?'bootstrap-select-sm':''}`}>\n        <button\n          type=\"button\"\n          className={`osa-dropwdown-button btn dropdown-toggle bs-placeholder btn-filter btn-default`}\n          data-toggle={notHideOnClickOutside && !autoClouse ? '' : \"dropdown\"}\n          style={{borderRadius: '0px'}}\n          onClick={this.handlerOpen}\n        >\n          <div className=\"filter-option\">\n            <div className=\"filter-option-inner\">\n              <div className=\"filter-option-inner-inner\">\n                {\n                  selectedItems.length ?\n                    displayItems && selectedItems.length > displayItems ?\n                      <span style={{color: '#555'}}>{`${selectedItems.length} ${selectedText ? selectedText : 'items seleccionados.'}`}</span> :\n                      selectedItems\n                        .map((option, index) => (\n                          <React.Fragment key={index}>\n                            <span\n                              className={option.className ? option.className : ''}\n                              style={{color: '#555'}}\n                            >{option.text}</span> {selectedItems.length > index + 1 ? separator ? `${separator}` : ', ' : null}\n                          </React.Fragment>\n                        ))\n                    : noneSelectedText ? <span style={{color: '#999'}}> {noneSelectedText}</span> : <span style={{color: '#999'}}> Todos </span>\n                }\n              </div>\n            </div>\n          </div>\n          <span className=\"bs-caret\">\n            <span className=\"caret\" />\n          </span>\n        </button>\n        <div className=\"dropdown-menu\" style={{borderRadius: '0px'}}>\n          {\n            search ?\n              <div className=\"bs-searchbox\">\n                <input\n                  ref={this.input}\n                  type=\"text\"\n                  className=\"form-control input-sm\"\n                  autoComplete=\"off\"\n                  value={this.state.searchText}\n                  onChange={\n                    (e: React.ChangeEvent<HTMLInputElement>) => this.search(e.target.value)\n                  }\n                />\n              </div> : null\n          }\n          {\n            allOption ?\n              <div className=\"bs-actionsbox\">\n                <div className=\"btn-group btn-group-sm btn-block\">\n                  <button\n                    onClick={() => selectAll(true)}\n                    type=\"button\" className=\"actions-btn bs-select-all btn btn-default\">Seleccionar todo\n                  </button>\n                  <button\n                    onClick={() => selectAll(false)}\n                    type=\"button\" className=\"actions-btn bs-deselect-all btn btn-default\">Deseleccionar todo\n                  </button>\n                </div>\n              </div> : null\n          }\n          <div\n            className=\"inner open\"\n            aria-expanded=\"false\"\n            tabIndex={-1}\n          >\n            <ul className=\"dropdown-menu inner\" style={{maxHeight: '30vh', overflowY: 'auto'}}>\n              {\n                options.filter((option) => {\n                  if (!searchText || !searchText.length) {\n                    return true;\n                  }\n                  return unorm.nfd(option.text)\n                    .replace(/[\\u0300-\\u036f]/g, '')\n                    .toLowerCase()\n                    .includes(searchText.toLowerCase());\n                }).map((option) => {\n                  const isSelected = selected.includes(option.value);\n                  return (\n                    <li key={option.value} className={`${isSelected ? 'selected' : ''}`} onClick={() => onClick(option.value)}>\n                      <a role=\"option\" tabIndex={0} className={`${isSelected ? 'selected' : ''}`} style={{background: '#FFF'}}>\n                        <span className=\"glyphicon glyphicon-ok check-mark\" />\n                        <span className={option.className ? option.className : ''}>{option.text}</span>\n                      </a>\n                    </li>\n                  );\n                })\n              }\n            </ul>\n          </div>\n        </div>\n      </div>\n    );\n  }\n\n  private handlerOpen() {\n    // https://codepen.io/qpqinc/pen/yLyPVMJ\n    if (this.props.displayHandler != null){\n      this.props.displayHandler(!this.state.open);\n    }\n    if(this.input.current){\n      this.input.current.focus()\n    }\n    this.setState({\n        open: !this.state.open\n      }, () => {\n        if (!this.state.open) {\n          this.search('');\n        }\n      }\n    );\n  }\n\n  private search(searchText: string) {\n    this.setState({\n      searchText: unorm.nfd(searchText).replace(/[\\u0300-\\u036f]/g, '')\n    });\n  }\n}\n\nexport default BootstrapSelect;\n","module.exports = ReactDOM;","import {AxiosError, AxiosResponse, CancelTokenSource, default as Axios} from 'axios';\nimport * as moment from 'moment';\nimport * as React from 'react';\nimport {Dispatch} from 'redux';\nimport {ICar} from '../../../../../src/app/interfaces/car.interface';\nimport {\n  IParticipant,\n  IParticipantSection\n} from '../../../../../src/form/interfaces/participant.interface';\nimport ImageLazyLoad from '../components/Utils/ImageLazyLoad';\nimport ApiService from '../utils/axios';\nimport {loadDataAction} from './modal.actions';\nimport ShowIf from '../components/Utils/ShowIf';\nimport {IForm} from \"../../../../../src/form/interfaces/form.interface\";\nimport { loadDashboardCleaningAction } from './dashboardDerco.actions';\n\nexport interface IDashboardState {\n  forms: IForm[];\n  searchForms: string[],\n  loading: boolean;\n  source: CancelTokenSource | null;\n  participants: any[];\n  requests: any[];\n  companies: any[];\n  car: ICar | null;\n  carEvents: any;\n  participantsReceivedPerDate: any[];\n  participantsSentPerDate: any[];\n  carsPerDate: any[];\n  planningPerDate: any[];\n  planningProcessPerDate: any[];\n  carsByVenue: any[];\n  searchText: string;\n  searchFrom: string,\n  searchTo: string,\n  participantPerRange: any[];\n  loadingParticipant: string | null;\n  totalCars: number;\n  venueStats: any[] | null;\n  revisionStats: any;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface IIsLoading {\n  type: '/DASHBOARD/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/DASHBOARD/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface ICancelRequest {\n  type: '/DASHBOARD/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/DASHBOARD/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface ILoadRevisions {\n  type: '/DASHBOARD/LOAD_PARTICIPANTS';\n  payload: {\n    participants: IParticipant[];\n    count: number;\n    pages: number\n  };\n}\n\nexport function loadCarsAction(participants: IParticipant[], count: number, pages: number): ILoadRevisions {\n  return {\n    type: '/DASHBOARD/LOAD_PARTICIPANTS',\n    payload: {\n      participants,\n      count,\n      pages\n    }\n  };\n}\n\ninterface ILoadParticipantInCar {\n  type: '/DASHBOARD/LOAD_PARTICIPANT_IN_CAR';\n  payload: {\n    participant: IParticipant;\n  };\n}\n\ninterface ILoadRequestsInCar {\n  type: '/DASHBOARD/LOAD_REQUESTS_IN_CAR';\n  payload: {\n    requests: any;\n  };\n}\n\nexport function loadParticipantInCarAction(participant: IParticipant): ILoadParticipantInCar {\n  return {\n    type: '/DASHBOARD/LOAD_PARTICIPANT_IN_CAR',\n    payload: {\n      participant\n    }\n  };\n}\n\nexport function loadRequestsInCarAction(requests: any): ILoadRequestsInCar {\n  return {\n    type: '/DASHBOARD/LOAD_REQUESTS_IN_CAR',\n    payload: {\n      requests\n    }\n  };\n}\n\ninterface ILoadCar {\n  type: '/DASHBOARD/LOAD_CAR';\n  payload: {\n    car: ICar;\n  };\n}\n\nexport function loadCarAction(car: ICar): ILoadCar {\n  return {\n    type: '/DASHBOARD/LOAD_CAR',\n    payload: {\n      car\n    }\n  };\n}\n\ninterface IChangePage {\n  type: '/DASHBOARD/CHANGE_PAGE';\n  payload: {\n    page: number;\n  };\n}\n\nexport function changePageAction(page: number): IChangePage {\n  return {\n    type: '/DASHBOARD/CHANGE_PAGE',\n    payload: {\n      page\n    }\n  };\n}\n\ninterface IChangeSearchDashboard {\n  type: '/DASHBOARD/CHANGE_SEARCH';\n  payload: {\n    searchText: string;\n  };\n}\n\nexport function changeSearchDashboardAction(searchText: string): IChangeSearchDashboard {\n  return {\n    type: '/DASHBOARD/CHANGE_SEARCH',\n    payload:\n      {\n      searchText\n    }\n  };\n}\n\ninterface IChangeRangeDashboard {\n  type: '/DASHBOARD/CHANGE_RANGE';\n  payload: {\n    from: string,\n    to: string,\n  };\n}\n\nexport function changeRangeDashboardAction(from: string, to: string): IChangeRangeDashboard\n{\n  return {\n    type: '/DASHBOARD/CHANGE_RANGE',\n    payload: {\n      from,\n      to\n    }\n  }\n}\n\ninterface IChangeFormsSearchDashboard {\n  type: '/DASHBOARD/CHANGE_FORM_SEARCH';\n  payload: {\n    searchForms: string[];\n  };\n}\n\nexport function changeFormsSearchDashboardAction(searchForms: string[]): IChangeFormsSearchDashboard {\n  return {\n    type: '/DASHBOARD/CHANGE_FORM_SEARCH',\n    payload: {\n      searchForms\n    }\n  };\n}\n\ninterface ILoadingForms {\n  type: '/DASHBOARD/LOAD_FORMS';\n  payload: {\n    forms: IForm[];\n  };\n}\n\nexport function loadForms(forms: IForm[]): ILoadingForms {\n  return {\n    type: '/DASHBOARD/LOAD_FORMS',\n    payload: {\n      forms\n    }\n  };\n}\n\nexport function getRevisionsThunkAction(nextPage: number, loading: boolean, search?: string, from?: string, to?: string, onlyControls : Boolean = true) {\n  return (dispatch: Dispatch<DashboardReduxAction>, getState: () => {dashboard: IDashboardState}) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(cancelRequestAction(api.getSource()));\n    if (loading) {\n      dispatch(isLoadingAction(true));\n    }\n    const page = nextPage ? nextPage : state.dashboard.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n    const { searchText, searchFrom, searchTo, searchForms } = state.dashboard;\n    Axios\n      .all([\n        api.getRevisions(onlyControls, page, searchText, searchFrom, searchTo, searchForms),\n        api.getForms(1, 100)\n      ])\n      .then(Axios.spread((response, forms) => {\n        dispatch(loadCarsAction(response.data.results, response.data.count, response.data.pages));\n        dispatch(loadForms(forms.data.results));\n        if (loading) {\n          dispatch(isLoadingAction(false));\n        }\n      }))\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          if (loading) {\n            dispatch(isLoadingAction(true));\n          }\n        } else {\n          if (loading) {\n            dispatch(isLoadingAction(false));\n          }\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\n\nexport function getRevisionsAction(nextPage: number, loading: boolean, search?: string, from?: string, to?: string, onlyControls : Boolean = true) {\n  return (dispatch: Dispatch<DashboardReduxAction>, getState: () => {dashboard: IDashboardState}) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(cancelRequestAction(api.getSource()));\n    if (loading) {\n      dispatch(isLoadingAction(true));\n    }\n    const page = nextPage ? nextPage : state.dashboard.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n    const { searchText, searchFrom, searchTo, searchForms } = state.dashboard;\n    api.getRevisions(onlyControls, page, searchText, searchFrom, searchTo, searchForms)\n      .then((response: AxiosResponse) => {\n        dispatch(loadCarsAction(response.data.results, response.data.count, response.data.pages));\n        if (loading) {\n          dispatch(isLoadingAction(false));\n        }\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          if (loading) {\n            dispatch(isLoadingAction(true));\n          }\n        } else {\n          if (loading) {\n            dispatch(isLoadingAction(false));\n          }\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\ninterface ILoadingParticipant {\n  type: '/DASHBOARD/LOADING_PARTICIPANT';\n  payload: {\n    loadingParticipant: string | null;\n  };\n}\n\nexport function loadingParticipantAction(loadingParticipant: string | null): ILoadingParticipant {\n  return {\n    type: '/DASHBOARD/LOADING_PARTICIPANT',\n    payload: {\n      loadingParticipant\n    }\n  };\n}\n\nexport function getParticipant(id: string) {\n  return (dispatch: Dispatch<DashboardReduxAction>) => {\n    const api: ApiService = new ApiService();\n    dispatch(cancelRequestAction(api.getSource()));\n    dispatch(loadingParticipantAction(id));\n    api.getParticipant(id)\n      .then((response: AxiosResponse) => {\n        const data = response.data.data;\n        dispatch(loadDataAction(\n          data.name,\n          <div id=\"form-detail\">\n            <table style={{width: '100%'}}>\n              <tbody>\n              <tr>\n                <td style={{width: '40%'}}><strong>Supervisor</strong></td>\n                <td>{data.user ? data.user.firstName : ''} {data.user ? data.user.lastName : ''}</td>\n              </tr>\n              <tr>\n                <td style={{width: '40%'}}><strong>Fecha</strong></td>\n                <td>{moment(data.createdAt).format('LLL')}</td>\n              </tr>\n              {/* <tr>\n                <td style={{width: '40%'}}><strong>Calificación</strong></td>\n                <td>{Math.round(data.qualification)}%</td>\n              </tr> */}\n              {\n                data.receptionText && data.receptionText.length ?\n                  <tr>\n                    <td style={{width: '40%'}}>\n                      <strong>Recepcionado</strong>\n                    </td>\n                    <td>{data.receptionConfirmation ? <i className=\"fa fa-check text-success\" /> : <i className=\"fa fa-close text-danger\" />}</td>\n                  </tr> : null\n              }\n              {\n                data.receptionText && data.receptionText.length && data.receptionImages.length ?\n                  <tr>\n                    <td style={{width: '40%'}}>\n                    </td>\n                    <td>{\n                      <div className=\"row special-question images\">\n                        {\n                          data.receptionImages.map((image: any) => {\n                            return (\n                              <div className=\"col-md-2 col-sm-2 col-xs-2 text-center\" key={image._id}>\n                                <a href={image.file.url} data-toggle=\"lightbox\" data-gallery={'reception'}>\n                                  <ImageLazyLoad\n                                    url={image.file.url}\n                                    small={true}\n                                    height={'50px'}\n                                  />\n                                </a>\n                              </div>\n                            );\n                          })\n                        }\n                      </div>\n                    }</td>\n                  </tr> : null\n              }\n              {\n                data.receiveFrom ?\n                  <tr>\n                    <td style={{width: '40%'}}>\n                      <strong>Recepcionado desde</strong>\n                    </td>\n                    <td>{data.receiveFrom.name}</td>\n                  </tr> : null\n              }\n              {\n                data.sendTo ?\n                  <tr>\n                    <td style={{width: '40%'}}>\n                      <strong>Enviado a</strong>\n                    </td>\n                    <td>{data.sendTo.name}</td>\n                  </tr> : null\n              }\n              {\n                data.carrier && data.carrierBy ?\n                  <tr>\n                    <td style={{width: '40%'}}>\n                      <strong>Transportista</strong>\n                    </td>\n                    <td>{data.carrierBy.name}</td>\n                  </tr> : null\n              }\n              {\n                data.shippingText && data.shippingText.length ?\n                  <tr>\n                    <td style={{width: '40%'}}>\n                      <strong>Enviado</strong>\n                    </td>\n                    <td>{data.shipping ? <i className=\"fa fa-check text-success\" /> : <i className=\"fa fa-close text-danger\" />}</td>\n                  </tr> : null\n              }\n              {\n                data.shippingText && data.shippingText.length && data.shippingImages.length ?\n                  <tr>\n                    <td style={{width: '40%'}}>\n                    </td>\n                    <td>{\n                      <div className=\"row special-question images\">\n                        {\n                          data.shippingImages.map((image: any) => {\n                            return (\n                              <div className=\"col-md-2 col-sm-2 col-xs-2 text-center\" key={image._id}>\n                                <a href={image.file.url} data-toggle=\"lightbox\" data-gallery={'shipping'}>\n                                  <ImageLazyLoad\n                                    url={image.file.url}\n                                    small={true}\n                                    height={'50px'}\n                                  />\n                                </a>\n                              </div>\n                            );\n                          })\n                        }\n                      </div>\n                    }</td>\n                  </tr> : null\n              }\n              {\n                data.conciliationText && data.conciliationText.length ?\n                  <tr>\n                    <td style={{width: '40%'}}>\n                      <strong>Conciliado</strong>\n                    </td>\n                    <td>{data.conciliation ? <i className=\"fa fa-check text-success\" /> : <i className=\"fa fa-close text-danger\" />}</td>\n                  </tr> : null\n              }\n              {\n                data.conciliationText && data.conciliationText.length && data.conciliationImages.length ?\n                  <tr>\n                    <td style={{width: '40%'}}>\n                    </td>\n                    <td>{\n                      <div className=\"row special-question images\">\n                        {\n                          data.conciliationImages.map((image: any) => {\n                            return (\n                              <div className=\"col-md-2 col-sm-2 col-xs-2 text-center\" key={image._id}>\n                                <a href={image.file.url} data-toggle=\"lightbox\" data-gallery={'conciliation'}>\n                                  <ImageLazyLoad\n                                    url={image.file.url}\n                                    small={true}\n                                    height={'50px'}\n                                  />\n                                </a>\n                              </div>\n                            );\n                          })\n                        }\n                      </div>\n                    }</td>\n                  </tr> : null\n              }\n              </tbody>\n            </table>\n            {\n              data.sections.map((section: IParticipantSection, index: number) => {\n                return (\n                  <div className=\"section\" key={index}>\n                    <h4>{section.name} <small>{Math.round(section.qualification)}%</small></h4>\n                      {\n                        section.answers.map((answer: any) => {\n                          const selectChoice = answer.scale ? answer.scale.choices.find((choice: any) => choice._id === answer.answer) : undefined;\n                          const kinds: any = answer.damages && answer.damages.hasOwnProperty('kinds') ? answer.damages.kinds.reduce((acc: any, cur: any) => {\n                            acc[cur._id] = cur.name;\n                            return acc;\n                          }, {}) : {};\n                          const parts: any = answer.damages && answer.damages.hasOwnProperty('parts') ? answer.damages.parts.reduce((acc: any, cur: any) => {\n                            acc[cur._id] = cur.name;\n                            return acc;\n                          }, {}) : {};\n                          const positions: any = answer.damages && answer.damages.hasOwnProperty('positions') ? answer.damages.positions.reduce((acc: any, cur: any) => {\n                            acc[cur._id] = cur.name;\n                            return acc;\n                          }, {}) : {};\n                          // no show conciliation questions if no require\n                          if (answer.conciliation && !selectChoice) {\n                            return null;\n                          }\n                          const accesorySeletedIds = answer.accesoriesAnswered ? answer.accesoriesAnswered.map((accesory:any) => accesory.item) : [];\n                          const items = answer.accessories ? answer.accessories.items.filter((item:any) => accesorySeletedIds.includes(item._id)) : [];\n                          return (\n                            <div className=\"question\" key={answer._id}>\n                              <p><strong>{answer.order} {answer.question} {!answer.optional ? <span className=\"red text-bold\">*</span> : null }</strong>\n                              {answer.hint && answer.hint !== \"\" ? <small><br/>{answer.hint}</small> : null}</p>\n                              {\n                                answer.scale ?\n                                  <div className=\"flex\" role=\"group\" aria-label=\"...\" key={answer._id}>\n                                    {\n                                      answer.scale.choices.map((choice: any) => {\n                                        const btnDefault = 'btn-default';\n                                        const optionsClass: any = {\n                                          blue: 'btn-primary',\n                                          green: 'btn-success',\n                                          yellow: 'btn-warning',\n                                          red: 'btn-danger'\n                                        };\n                                        const btnClass = optionsClass.hasOwnProperty(choice.backgroundColor) ? optionsClass[choice.backgroundColor] : btnDefault;\n                                        return (\n                                          <button\n                                            key={choice._id}\n                                            type=\"button\"\n                                            className={`btn flex-row-item text-wrap ${choice._id === answer.answer ? btnClass : btnDefault}`}\n                                            style={{margin: '2px'}}\n                                            disabled={true}\n                                          >{choice.choice}</button>\n                                        );\n                                      })\n                                    }\n                                  </div>\n                                  : null\n                              }\n                              {\n                                // TODO: validate by kind question\n                                answer.damagesSelected && answer.damagesSelected.length ?\n                                  <div className=\"row\" style={{marginTop: '10px'}}>\n                                    {\n                                      answer.damagesSelected.map((ds: any, index: number) => (\n                                        <div className=\"col-md-12 damage\" key={index}>\n                                          <div className=\"damage-detail\">\n                                            <p className=\"damage-description\">\n                                              <strong className=\"title\">{parts.hasOwnProperty(ds.part) ? parts[ds.part] : '-'}</strong><br/>\n                                              <strong>Daño</strong> {kinds.hasOwnProperty(ds.kind) ? kinds[ds.kind] : '-'}{' '}\n                                              <strong>Posición</strong> {positions.hasOwnProperty(ds.position) ? positions[ds.position] : '-'}\n                                            </p>\n                                            <ShowIf\n                                              condition={!!ds.images.length}\n                                              alternative={\n                                                <p style={{ padding: '0 5px' }} className=\"text-muted\">\n                                                  No se reportaron imágenes.\n                                                </p>\n                                              }\n                                            >\n                                              <div className='row images'>\n                                                {\n                                                  ds.images.map((image: any) => {\n                                                    return (\n                                                      <div\n                                                        className='col-md-3 col-sm-4 col-xs-4 text-center'\n                                                        key={image._id}\n                                                        data-toggle='tooltip'\n                                                        data-placement='bottom'\n                                                        title={image.file.name}\n                                                      >\n                                                        <a\n                                                          href={image.file.url}\n                                                          data-toggle='lightbox'\n                                                          className='zoom-in'\n                                                          data-gallery={ds._id}\n                                                          data-title={parts.hasOwnProperty(ds.part) ? parts[ds.part] : '-'}\n                                                        >\n                                                          <ImageLazyLoad\n                                                            url={image.file.url}\n                                                            height={'100px'}\n                                                          />\n                                                        </a>\n                                                        {/*<p*/}\n                                                        {/*  className={'text-ellipsis'}*/}\n                                                        {/*  data-toggle='tooltip'*/}\n                                                        {/*  data-placement='top'*/}\n                                                        {/*  title={image.file.name}*/}\n                                                        {/*>*/}\n                                                        {/*  {image.file.name}*/}\n                                                        {/*</p>*/}\n                                                      </div>\n                                                    );\n                                                  })\n                                                }\n                                              </div>\n                                            </ShowIf>\n                                          </div>\n                                        </div>\n                                      ))\n                                    }\n                                  </div>\n                                  : answer.damages && answer.damages.hasOwnProperty('parts') ? 'No se han seleccionado daños.' : null\n                              }\n                              {\n                                selectChoice && selectChoice.requireAccesories && answer.accessories && answer.accessories.items.length ?\n                                  <div className=\"row\" style={{marginTop: '10px'}}>\n                                    <div className=\"col-md-12\">\n                                      <p><strong>{answer.accessories.question}</strong></p>\n                                      {\n                                        items.length ? items.map((item:any) => {\n                                          return (\n                                            <p key={item._id}\n                                              // className={answer.accesoriesAnswered.includes(item._id) ? 'text-green' : 'text-red'}\n                                            >\n                                              {\n                                                /*\n                                                answer.accesoriesSelected.includes(item._id) ?\n                                                  <i className=\"fa fa-check\" style={{marginRight: '5px'}}/> :\n                                                  <i className=\"fa fa-times\" style={{marginRight: '5px', width: '14px'}}/>\n                                                 */\n                                              } - {item.item} {item.amount ? `(${answer.accesoriesAnswered.find((accesory:any) => accesory.item === item._id).amount})` : ''}\n                                            </p>\n                                          );\n                                        }) : 'No se seleccionaron items.'\n                                      }\n                                    </div>\n                                  </div>\n                                  : null\n                              }\n                              {\n                                ((selectChoice && selectChoice.requireImage) || answer.kind === 'image') && answer.images && answer.images.length ?\n                                  <div className=\"row images\">\n                                    {\n                                      answer.images.map((image: any) => {\n                                        return (\n                                          <div className=\"col-md-3 col-sm-4 col-xs-4 text-center\" key={image._id}>\n                                            <a\n                                              href={image.file.url}\n                                              className=\"zoom-in\"\n                                              data-toggle=\"lightbox\"\n                                              data-gallery={answer._id}\n                                            >\n                                              <ImageLazyLoad\n                                                url={image.file.url}\n                                                height={'100px'}\n                                              />\n                                            </a>\n                                            <p\n                                              className={'text-ellipsis'}\n                                              data-toggle=\"tooltip\"\n                                              data-placement=\"top\"\n                                              title={image.file.name}\n                                            >\n                                              {image.file.name}\n                                            </p>\n                                          </div>\n                                        );\n                                      })\n                                    }\n                                  </div>\n                                : null\n                              }\n                              {\n                                (answer.kind === 'text' || selectChoice && selectChoice.requireComment) && answer.comment && answer.comment.length ?\n                                  <div className=\"row\" style={{marginTop: '10px'}}>\n                                    <div className=\"col-md-12\">\n                                      <p><strong>Comentario</strong>: <span className=\"text-muted\">{answer.comment}</span></p>\n                                    </div>\n                                  </div>\n                                : null\n                              }\n\n                              {\n                                (answer.kind === 'numeric-scale') && answer.score != -1  ?\n                                  <div className=\"row\" style={{marginTop: '10px'}}>\n                                    <div className=\"col-md-12\">\n                                      <p><strong>Evaluación</strong>: <span className=\"text-muted\">{answer.score} (Del {answer.minValue} al {answer.maxValue})</span></p>\n                                    </div>\n                                  </div>\n                                  : null\n                              }\n                            </div>\n                          );\n                        })\n                      }\n                  </div>\n                );\n              })\n            }\n            <small>Las preguntas marcadas con <span className=\"red text-bold\">*</span> son obligatorias.</small>\n          </div>\n          ) as any);\n        dispatch(loadingParticipantAction(null));\n        ($('[data-toggle=\"tooltip\"]') as any).tooltip();\n      })\n      .catch((err: AxiosError) => {\n        if (Axios.isCancel(err)) {\n          dispatch(loadingParticipantAction(null));\n        } else {\n          dispatch(loadingParticipantAction(null));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\ninterface ILoadParticipantsPerDate {\n  type: '/DASHBOARD/LOAD_PARTICIPANTS_PER_DATE';\n  payload: {\n    companies: any[];\n    participantsReceivedPerDate: any;\n    participantsSentPerDate: any;\n    carsPerDate: any;\n    planningPerDate: any;\n    planningProcessPerDate: any;\n    carsByVenue: any;\n    totalCars: number;\n    participantPerRange: any;\n  };\n}\n\nexport function loadParticipantsPerDateAction(companies: any[], participantsReceivedPerDate: any, participantsSentPerDate:any, carsPerDate: any, planningPerDate: any, planningProcessPerDate:any, totalCars: number, carsByVenue: any, participantPerRange: any): ILoadParticipantsPerDate {\n  return {\n    type: '/DASHBOARD/LOAD_PARTICIPANTS_PER_DATE',\n    payload: {\n      companies,\n      participantsReceivedPerDate,\n      participantsSentPerDate,\n      carsPerDate,\n      planningPerDate,\n      planningProcessPerDate,\n      carsByVenue,\n      totalCars,\n      participantPerRange\n    }\n  };\n}\n\nexport function getParticipantsPerDateAction(companies?:string, onlyControls: boolean = true) {\n  return (dispatch: Dispatch<DashboardReduxAction>) => {\n    const api: ApiService = new ApiService();\n    dispatch(cancelRequestAction(api.getSource()));\n    dispatch(isLoadingAction(true));\n    api.getParticipantsPerDate(onlyControls, companies)\n      .then((response: AxiosResponse) => {\n        dispatch(loadParticipantsPerDateAction(response.data.companies, response.data.participantsReceived, response.data.participantsSent, response.data.cars, response.data.planning, response.data.planningProcess, response.data.totalCars, response.data.carsByVenue, response.data.participantPerRange));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(true));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\nexport function getCarAction(id: string) {\n  return (dispatch: Dispatch<DashboardReduxAction>) => {\n    const api: ApiService = new ApiService();\n    dispatch(cancelRequestAction(api.getSource()));\n    dispatch(isLoadingAction(true));\n    Axios.all([\n      api.getCar(id),\n      api.getRequestsByCar(id)\n    ]).then(Axios.spread((car, requests) => {\n      // dispatch(loadDashboardCleaningAction(dashboard.data));\n      document.title = `OSA Andes | Detalle VIN ${car.data.data.vin}`;\n      dispatch(loadCarAction(car.data.data));\n      dispatch(loadRequestsInCarAction(requests.data));\n      dispatch(isLoadingAction(false));\n    }))\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(true));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\ninterface ILoadingVenuesStats {\n  type: '/DASHBOARD/LOAD_VENUES_STATS';\n  payload: {\n    venuesStats: any[];\n  };\n}\n\nexport function loadVenuesStats(venuesStats: any[]): ILoadingVenuesStats {\n  return {\n    type: '/DASHBOARD/LOAD_VENUES_STATS',\n    payload: {\n      venuesStats\n    }\n  };\n}\n\nexport function getVenuesStats(from: number, to: number){\n  return (dispatch: Dispatch<DashboardReduxAction>) => {\n    const api: ApiService = new ApiService();\n    dispatch(cancelRequestAction(api.getSource()));\n    api.getVenuesStats(from, to)\n      .then((response: AxiosResponse) => {\n        dispatch(loadVenuesStats(response.data as any[]));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n        } else {\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\ninterface ILoadingRevisionsStats {\n  type: '/DASHBOARD/LOAD_REVISION_STATS';\n  payload: {\n    revisionStats: any;\n  };\n}\n\nexport function loadRevisionsStats(revisionStats: any[]): ILoadingRevisionsStats {\n  return {\n    type: '/DASHBOARD/LOAD_REVISION_STATS',\n    payload: {\n      revisionStats\n    }\n  };\n}\n\nexport function getRevisionStats(){\n  return (dispatch: Dispatch<DashboardReduxAction>) => {\n    const api: ApiService = new ApiService();\n    dispatch(cancelRequestAction(api.getSource()));\n    dispatch(isLoadingAction(true));\n    api.getRevisionsStats()\n      .then((response: AxiosResponse) => {\n        dispatch(loadRevisionsStats(response.data));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(true));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\n\nexport type DashboardReduxAction =\n  IIsLoading |\n  ICancelRequest |\n  ILoadRevisions |\n  IChangeSearchDashboard |\n  IChangeRangeDashboard |\n  ILoadCar |\n  ILoadParticipantsPerDate |\n  ILoadingParticipant |\n  IChangePage |\n  ILoadParticipantInCar |\n  ILoadRequestsInCar |\n  ILoadingVenuesStats |\n  ILoadingRevisionsStats |\n  ILoadingForms |\n  IChangeFormsSearchDashboard;\n","module.exports = XLSX;","import * as React from 'react';\nimport {\n  CSSProperties,\n  RefObject\n} from 'react';\n\ninterface IPropsType {\n  url: string;\n  height: string;\n  small?: boolean;\n  style?: React.CSSProperties;\n  replaceLoading?: any;\n}\n\ninterface IStateType {\n  loading: boolean;\n  inViewPort: boolean;\n  error: boolean;\n  eventRuning: boolean;\n  bounding: any;\n  height: any;\n}\n\nclass ImageLazyLoad extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    loading: true,\n    eventRuning: false,\n    inViewPort: false,\n    error: false,\n    bounding: null,\n    height: null\n  };\n\n  private element: RefObject<HTMLDivElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.element = React.createRef();\n    this.handleImageLoaded = this.handleImageLoaded.bind(this);\n    this.isInViewport = this.isInViewport.bind(this);\n    this.addEventListener = this.addEventListener.bind(this);\n    this.removeEventListener = this.removeEventListener.bind(this);\n    this.error = this.error.bind(this);\n  }\n\n  public componentDidMount() {\n    this.addEventListener();\n  }\n\n  public componentWillUnmount() {\n    this.removeEventListener();\n  }\n\n  public render() {\n    const { loading, inViewPort } = this.state;\n    const { url, height, small, style, replaceLoading } = this.props;\n\n    let imageStyle: CSSProperties = {};\n    if (loading) {\n      imageStyle.display = 'none';\n    } else if (style) {\n      imageStyle = style;\n    }\n\n    return (\n      <React.Fragment>\n        {\n          inViewPort ?\n            <img\n              src={url}\n              onLoad={this.handleImageLoaded}\n              onError={this.error}\n              style={imageStyle}\n            /> : null\n        }\n        {\n          loading ?\n            replaceLoading ?\n              <span ref={this.element}>{replaceLoading}</span> :\n              <div\n                style={{\n                  height,\n                  display: 'table-cell',\n                  verticalAlign: 'middle'\n                }}\n                className={'text-center'}\n                ref={this.element}\n              >\n                {\n                  small\n                    ? (\n                      <i className={'fa fa-circle-o-notch fa-spin'} />\n                    )\n                    : (\n                      <i className={'fa fa-circle-o-notch fa-spin fa-2x'} />\n                    )\n                }\n              </div> : null\n        }\n\n      </React.Fragment>\n    );\n  }\n\n  private error() {\n    this.setState({\n      error: true\n    });\n  }\n\n  private handleImageLoaded() {\n    const { url } = this.props;\n    sessionStorage.setItem(url, 'true');\n    this.setState({\n      loading: false\n    });\n  }\n\n  private isInViewport() {\n    if (!this.state.inViewPort && this.element.current) {\n      const bounding = this.element.current.getBoundingClientRect();\n      // start load distance\n      const distance = 300;\n      const clientHeight: number = document && document.documentElement ? document.documentElement.clientHeight : 0;\n      const height = window.innerHeight || clientHeight;\n      const isInViewPort = (\n        bounding.top >= 0 &&\n        bounding.left >= 0 &&\n        (bounding.bottom - distance) <= height\n      );\n\n      if (isInViewPort) {\n        this.removeEventListener();\n        this.setState({\n          inViewPort: true\n        });\n      }\n    }\n  }\n\n  private addEventListener() {\n    this.setState({\n      eventRuning: true\n    });\n    // const modal = document.getElementById('andesModal');\n    let modal = ($('#andesModal').data('bs.modal') || {}).isShown;\n    if (modal) {\n      modal = document.getElementById('andesModal');\n      modal.addEventListener('scroll', this.isInViewport, false);\n      modal.addEventListener('rezise', this.isInViewport, false);\n      setTimeout(() => {\n        this.isInViewport();\n      }, 1000);\n    } else {\n      window.addEventListener('scroll', this.isInViewport, false);\n      window.addEventListener('rezise', this.isInViewport, false);\n      this.isInViewport();\n    }\n  }\n\n  private removeEventListener() {\n    this.setState({\n      eventRuning: false\n    });\n    // const modal = document.getElementById('andesModal');\n    let modal = ($('#andesModal').data('bs.modal') || {}).isShown;\n    if (modal) {\n      modal = document.getElementById('andesModal');\n      modal.removeEventListener('scroll', this.isInViewport, false);\n      modal.removeEventListener('rezise', this.isInViewport, false);\n    } else {\n      window.removeEventListener('scroll', this.isInViewport, false);\n      window.removeEventListener('rezise', this.isInViewport, false);\n    }\n  }\n}\n\nexport default ImageLazyLoad;\n","import axios from 'axios';\nimport * as React from 'react';\nimport { ChangeEvent, DragEvent, ErrorInfo, RefObject } from 'react';\nimport * as uuid from 'uuid';\nimport { getExtension, getIconFromExtension } from '../../utils/common';\nimport Raven = require('raven-js');\nimport ShowIf from './ShowIf';\nimport ApiService from '../../utils/axios';\nimport * as swal from 'sweetalert';\n\n\ninterface IPropsType {\n  onChange: (e: any) => void;\n  deleteCalback?: (e: any) => void;\n  className?: string;\n  body?: any;\n  files: any[];\n  url: string;\n  listMode?: boolean;\n}\n\ninterface IStateType {\n  error: Error | null;\n  canDrop: boolean;\n}\n\nexport enum imageStatus {\n  pending = 'pending',\n  inProgress = 'inProgress',\n  complete = 'complete'\n}\n\nclass MultiUploadFiles extends React.Component<IPropsType, IStateType> {\n\n  readonly inputFile: RefObject<HTMLInputElement>;\n  readonly api: ApiService;\n  readonly state = {\n    error: null,\n    canDrop: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.handleChangeInputFile = this.handleChangeInputFile.bind(this);\n    this.processFile = this.processFile.bind(this);\n    this.handleDrop = this.handleDrop.bind(this);\n    this.clickUploadFile = this.clickUploadFile.bind(this);\n    this.dragOverHandler = this.dragOverHandler.bind(this);\n    this.dragEndHandler = this.dragEndHandler.bind(this);\n    this.dragLeaveHandler = this.dragLeaveHandler.bind(this);\n    this.uploadImages = this.uploadImages.bind(this);\n    this.deleteFile = this.deleteFile.bind(this);\n    this.getSizeText = this.getSizeText.bind(this);\n    this.downloadFile = this.downloadFile.bind(this);\n    this.inputFile = React.createRef();\n    this.api = new ApiService();\n  }\n\n  public downloadFile(file: any) {\n    window.open(file.url, \"_blank\")\n    // this.api.getInstance()({\n    //   url: file.url,\n    //   method: 'GET',\n    //   responseType: 'blob'\n    // })\n    //   .then((response) => {\n    //     const url = window.URL\n    //       .createObjectURL(new Blob([response.data]));\n    //     const link = document.createElement('a');\n    //     link.href = url;\n    //     link.setAttribute('download', file.name);\n    //     document.body.appendChild(link);\n    //     link.click();\n    //     document.body.removeChild(link);\n    //   });\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: IPropsType): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public render() {\n    const { files, listMode, className } = this.props;\n    return (\n      <div className={`multi-upload ${listMode ? 'list-mode' : ''} ${className}`}>\n        <ShowIf condition={!listMode}>\n          {\n            files.map((file) => (\n              <div className='item-container multi-upload-item' key={file?._id ||file.tmpID}>\n                <div\n                  className='delete-button pointer'\n                  onClick={() => this.deleteFile(file?._id ||file.tmpID)}\n                >\n                  <i className='fa fa-minus-circle' />\n                </div>\n                {\n                  file.isImage ?\n                    <img\n                      src={file.url}\n                      className='image-item'\n                      style={file.status !== imageStatus.complete ? { opacity: 0.5, filter: 'grayscale(100%)' } : undefined}\n                    /> :\n                    <div className='item'>\n                      <div\n                        className={`icon-file ${getIconFromExtension(getExtension(file.name))}`}\n                        style={file.status !== imageStatus.complete ? { opacity: 0.5, filter: 'grayscale(100%)' } : undefined}\n                      />\n                      <p\n                        className='text-description'\n                        data-toggle='tooltip'\n                        data-placement='top'\n                        title={file.name}\n                        style={{\n                          paddingBottom: 0\n                        }}\n                      >\n                        {file.name}\n                      </p>\n                      <p\n                        className='text-description'\n                        style={{\n                          color: '#9e9e9e',\n                          paddingTop: 0\n                        }}\n                      >{this.getSizeText(file.size)}</p>\n                    </div>\n                }\n                {\n                  file.status === imageStatus.inProgress ?\n                    <div className='multi-upload-progress-bar'>\n                      <div className='multi-progress' style={{ width: `${file.progress}%` }} />\n                    </div> : null\n                }\n              </div>\n            ))\n          }\n        </ShowIf>\n        <ShowIf condition={!!listMode}>\n          <div className='border-bottom'>\n            {\n              files.map((file) => (\n                <React.Fragment key={file._id || file?._id ||file.tmpID}>\n                  <div className='row border' style={{margin: 0}}>\n                    {/*<div*/}\n                    {/*  className='delete-button pointer'*/}\n                    {/*  onClick={() => this.deleteFile(file.tmpID)}*/}\n                    {/*>*/}\n                    {/*  <i className='fa fa-minus-circle' />*/}\n                    {/*</div>*/}\n                    {\n                      file.isImage ?\n                        <div className='col-md-2'>\n                          <img\n                            src={file.url}\n                            className='image-item'\n                            style={file.status !== imageStatus.complete ? { opacity: 0.5, filter: 'grayscale(100%)' } : undefined}\n                          />\n                        </div> :\n                        <div className='col-md-2'>\n                          <div className='item'>\n                            <div\n                              className={`icon-file ${getIconFromExtension(getExtension(file.name))}`}\n                              style={file.status !== imageStatus.complete ? { opacity: 0.5, filter: 'grayscale(100%)' } : undefined}\n                            />\n                          </div>\n                        </div>\n                    }\n                    <div className='col-md-8' style={{ paddingTop: '20px' }}>\n                      {file.name} <br />\n                      <span className={'text-muted text-sm'}>{this.getSizeText(file.size)}</span>\n                    </div>\n                    <div\n                      className='col-md-1 text-right pointer'\n                      onClick={()=> this.downloadFile(file)}\n                      style={{paddingTop: \"25px\"}}>\n                      <i className='fa fa-download text-primary pointer' />\n                    </div>\n                    <div className='col-md-1 text-right pointer' style={{paddingTop: \"25px\"}}  onClick={() => this.deleteFile(file?._id ||file.tmpID)}>\n                      <i className='fa fa-minus-circle text-red' />\n                    </div>\n                    <div className='row'>\n                      <div className='col-md-12'>\n                        {\n                          file.status === imageStatus.inProgress ?\n                            <div className='multi-upload-progress-bar'>\n                              <div className='multi-progress' style={{ width: `${file.progress}%` }} />\n                            </div> : null\n                        }\n                      </div>\n                    </div>\n                  </div>\n                </React.Fragment>\n              ))\n            }\n          </div>\n        </ShowIf>\n        <div\n          className='add-item pointer multi-upload-item'\n          onClick={this.clickUploadFile}\n          onDrop={this.handleDrop}\n          onDragOver={this.dragOverHandler}\n          onDragEnd={this.dragEndHandler}\n          onDragLeave={this.dragLeaveHandler}\n        >\n          <i className='fa fa-2x fa-cloud-upload' /><br />\n          AÑADIR ARCHIVOS\n        </div>\n        <input\n          type='file'\n          ref={this.inputFile}\n          style={{ display: 'none' }}\n          onChange={(e) => this.handleChangeInputFile(e)}\n          accept='.jpeg, .jpg, .png, .doc, .docx, .xls, .xlsx, .pdf'\n          multiple={true}\n        />\n      </div>\n    );\n  }\n\n  private processFile(file: File | any): Promise<any> {\n    const { onChange, files } = this.props;\n    return new Promise((resolve) => {\n      file.tmpID = uuid.v4();\n      file.progress = 0;\n      file.isImage = this.isImage(file.type);\n      file.status = imageStatus.pending;\n      onChange([...files, file]);\n      this.uploadImages();\n      resolve({});\n    });\n  }\n\n  private getSizeText(bytes: number): string {\n    let text = '';\n    if (bytes < 1000000) {\n      text = Math.floor(bytes / 1000) + 'KB';\n    } else {\n      text = Math.floor(bytes / 1000000) + 'MB';\n    }\n    return text;\n  }\n\n  private deleteFile(id: string) {\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el archivo adjunto.`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete: any) => {\n      if (willDelete) {\n        const { onChange, files, deleteCalback } = this.props;\n        onChange([...files].filter(file => file.tmpID !== id && file._id !== id));\n        if (deleteCalback) {\n          deleteCalback(id);\n        }\n      }\n    });\n  }\n\n  private uploadImages() {\n    const { onChange, files, url, body} = this.props;\n    const pendingImages: any[] = [];\n    const inProcessImages: any[] = [];\n    if (files.length) {\n      files.forEach((file) => {\n        if (file.status === imageStatus.pending) {\n          pendingImages.push(file);\n        } else if (file.status === imageStatus.inProgress) {\n          inProcessImages.push(file);\n        }\n      });\n    }\n    if (!inProcessImages.length && pendingImages.length) {\n      const imageToUpload = pendingImages[0];\n      let lastPercentage = 0;\n      onChange([...this.props.files].map((file) => {\n        if (file.tmpID === imageToUpload.tmpID) {\n          file.status = imageStatus.inProgress;\n        }\n        return file;\n      }));\n      const instance = axios.create({\n        timeout: 360000,\n        headers: {\n          'Content-Type': 'multipart/form-data'\n        },\n        onUploadProgress: (progressEvent) => {\n          const percentage = (100 / progressEvent.total) * progressEvent.loaded;\n          if (lastPercentage < percentage) {\n            lastPercentage = percentage + 5;\n            // TODO Fix this\n            onChange([...this.props.files].map((file) => {\n              if (file.tmpID === imageToUpload.tmpID) {\n                file.status = imageStatus.inProgress;\n                file.progress = percentage;\n              }\n              return file;\n            }));\n          }\n        }\n      });\n      let attempt = 1;\n      const timeout = 1000;\n      const data = new FormData();\n      data.append('file', imageToUpload);\n      if (body) {\n        Object.keys(body).forEach(key => {\n          data.append(key, body[key]);\n        });\n      }\n      instance\n        .post(url, data)\n        .then(response => {\n          onChange([...this.props.files].map((file) => {\n            if (file.tmpID === imageToUpload.tmpID) {\n              file._id = response.data.data._id;\n              file.progress = 100;\n              file.url = decodeURIComponent(response.data.data.file.url);\n              file.status = imageStatus.complete;\n            }\n            return file;\n          }));\n          // dispatch(updateImage(imageToUpload.tempID, 100, statusImages.completed, response.data.id, 1));\n          // dispatch(uploadImages());\n          this.uploadImages();\n        })\n        .catch(err => {\n          Raven.captureMessage(JSON.stringify(err.response), {\n            level: 'info'\n          });\n          if (!axios.isCancel(err)) {\n            Raven.captureException(JSON.stringify(err.response));\n            const waitTime = Math.pow(2, attempt) * timeout;\n            if (waitTime < 16000) attempt = attempt + 1;\n            else attempt = 1;\n            // dispatch(updateImage(imageToUpload.tempID, 0, statusImages.pending, null, attempt));\n            onChange([...this.props.files].map((file) => {\n              if (file.tmpID === imageToUpload.tmpID) {\n                file.status = imageStatus.pending;\n              }\n              return file;\n            }));\n            setTimeout(() => {\n              this.uploadImages();\n            }, waitTime);\n          }\n        });\n    }\n  }\n\n  private isImage(type: string): boolean {\n    const accepted = ['image/jpg', 'image/jpeg', 'image/png'];\n    return accepted.includes(type);\n  }\n\n  private async handleChangeInputFile(e: ChangeEvent<HTMLInputElement>) {\n    const { files } = e.target;\n    if (files && files.length) {\n      // tslint:disable-next-line: prefer-for-of\n      for (let i = 0; i < files.length; i++) {\n        // const file: File | null = dt.items[i].getAsFile();\n        const file: any = files[i];\n        if (file) {\n          const reader = new FileReader();\n          reader.onload = async (e) => {\n            file.url = e.target!.result;\n            await this.processFile(file);\n          };\n          reader.readAsDataURL(file);\n        }\n      }\n    }\n    // clear input file\n    this.inputFile.current!.value = '';\n  }\n\n  private handleDrop(e: DragEvent<HTMLDivElement>) {\n    e.preventDefault();\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      if (dt.items.length) {\n        // Use  interface to access the file(s)\n        // tslint:disable-next-line: prefer-for-of\n        for (let i = 0; i < dt.items.length; i++) {\n          // const file: File | null = dt.items[i].getAsFile();\n          const file: any = dt.items[i].getAsFile();\n          if (file) {\n            const reader = new FileReader();\n            reader.onload = async (e) => {\n              file.url = e.target!.result;\n              await this.processFile(file);\n            };\n            reader.readAsDataURL(file);\n          }\n        }\n      }\n    } else {\n      // tslint:disable-next-line: prefer-for-of\n      for (let i = 0; i < dt.files.length; i++) {\n        const file: any = dt.files[i];\n        if (file) {\n          const reader = new FileReader();\n          reader.onload = async (e) => {\n            file.url = e.target!.result;\n            await this.processFile(file);\n          };\n          reader.readAsDataURL(file);\n        }\n      }\n    }\n    // clear input file\n    this.inputFile.current!.value = '';\n  }\n\n  private dragOverHandler(e: DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    this.setState({\n      canDrop: true\n    });\n  }\n\n  private dragLeaveHandler(): void {\n    this.setState({\n      canDrop: false\n    });\n  }\n\n  private dragEndHandler(e: DragEvent<HTMLDivElement>): void {\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      // Use DataTransferItemList interface to remove the drag data\n      // tslint:disable-next-line: prefer-for-of\n      for (let i = 0; i < dt.items.length; i++) {\n        dt.items.remove(i);\n      }\n    } else {\n      // Use DataTransfer interface to remove the drag data\n      e.dataTransfer.clearData();\n    }\n  }\n\n  private clickUploadFile() {\n    if (this.inputFile.current) {\n      this.inputFile.current.click();\n    }\n  }\n}\n\nexport default MultiUploadFiles;\n","import * as React from 'react';\n// import {CSSProperties} from 'react';\n\ninterface IPropsType {\n  color?: string;\n  active?: boolean;\n  action: any;\n  classes?: string;\n  style?: React.CSSProperties;\n}\n\ninterface IStateType {\n  hover: boolean;\n}\n\nclass Checkbox extends React.Component<IPropsType, IStateType> {\n\n  state = {\n    hover: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.mouseOver = this.mouseOver.bind(this);\n    this.mouseOut = this.mouseOut.bind(this);\n  }\n\n  private mouseOver(): void {\n    this.setState({\n      hover: true\n    });\n  }\n\n  private mouseOut(): void {\n    this.setState({\n      hover: false\n    });\n  }\n\n  render(): React.ReactElement<IPropsType> {\n    const {hover} = this.state;\n    const {color, active, action, classes, style} = this.props;\n    const classIcheck: string[] = [];\n\n    // set color\n    if (color) {\n      classIcheck.push(`icheckbox_square-${color}`);\n    } else {\n      classIcheck.push('icheckbox_square-blue');\n    }\n\n    // if mouse hover\n    if (hover) {\n      classIcheck.push('hover');\n    }\n\n    if (classes) {\n      classIcheck.push(classes);\n    }\n\n    // if checked\n    if (active) {\n      classIcheck.push('checked');\n    }\n\n    return (\n      <div\n        className={classIcheck.join(' ')}\n        onMouseOver={this.mouseOver}\n        onMouseOut={this.mouseOut}\n        onClick={action}\n        style={style ? style : {}}\n      >\n      </div>\n    );\n  }\n}\n\nexport default Checkbox;\n","export const requestSettings = {\n  brand: false,\n  brandReadOnly: false,\n  color: false,\n  colorReadOnly: false,\n  colorRequired: false,\n  denomination: false,\n  denominationReadOnly: false,\n  denominationRequired: false,\n  internalNumber: false,\n  internalNumberRequired: false,\n  internalNumberText: 'Número interno',\n  material: false,\n  materialRequired: false,\n  materialReadOnly: false,\n  reason: false,\n  entry: false,\n  sellerText: false,\n  ticket: false,\n  priority: false,\n  conectaID: false,\n  secondColorOption: false,\n  thirdColorOption: false,\n\n};\n","import * as React from 'react';\nimport {RefObject} from 'react';\nimport * as unorm from 'unorm';\nimport {WrappedFieldProps} from \"redux-form/lib/Field\";\n\ninterface IOption {\n  value: string;\n  text: any;\n  className?: string;\n}\n\ninterface IPropsType extends WrappedFieldProps {\n  options: IOption[];\n  labelOff?:boolean;\n  className?: string;\n  disabled?:boolean;\n  right?:boolean;\n  displayItems?: number;\n  onClick: (value: string) => void;\n  selectAll?: any;\n  noneSelectedText?: string;\n  selectedText?: string;\n  separator?: string;\n  allOption?: boolean;\n  autoClouse?: boolean;\n  search?: boolean;\n  sm?: boolean;\n  label: string;\n}\n\ninterface IStateType {\n  open: boolean;\n  searchText: string;\n}\n\nclass BootstrapSelectField extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    open: false,\n    searchText: ''\n  };\n\n  readonly input: RefObject<HTMLInputElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.handlerOpen = this.handlerOpen.bind(this);\n    this.search = this.search.bind(this);\n    this.input = React.createRef();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      sm,\n      options,\n      onClick,\n      displayItems,\n      noneSelectedText,\n      selectedText,\n      separator,\n      allOption,\n      search,\n      autoClouse,\n      selectAll,\n      label,\n      disabled,\n      right,\n      input,\n      labelOff,\n      meta: {touched, error, warning}\n    } = this.props;\n    const {searchText} = this.state;\n    const selectedItems = options.filter((option) => (input.value.includes(option.value)));\n    // console.log('onClick', onClick)\n    return (\n      <div className={`form-group ${touched && error ? \"has-error\" : \"\"} ${touched && warning ? \"has-warning\" : \"\"}`}>\n        {!labelOff?<label className=\"control-label text-ellipsis\">{label}</label>: null}\n        <div\n          className={`dropdown bootstrap-select form-control show-tick ${autoClouse ? '' : 'keep-inside-clicks-open'} ${sm ? 'bootstrap-select-sm' : ''}`} >\n          <button\n            type=\"button\"\n            className={`btn dropdown-toggle bs-placeholder btn-filter btn-default`}\n            data-toggle=\"dropdown\"\n            disabled={disabled}\n            style={{borderRadius: '0px', borderColor: touched && error ? '#dd4b39' : '', padding: '6px 12px 5px 5px'}}\n            onClick={this.handlerOpen}\n          >\n            <div className=\"filter-option\">\n              <div className=\"filter-option-inner\">\n                <div className=\"filter-option-inner-inner text-ellipsis\">\n                  {\n                    selectedItems.length ?\n                      displayItems && selectedItems.length > displayItems ?\n                        <span style={{color: '#555'}}>{`${selectedItems.length} ${selectedText ? selectedText : 'items seleccionados.'}`}</span> :\n                        selectedItems\n                          .map((option, index) => (\n                            <React.Fragment key={index}>\n                            <span\n                              className={option.className ? option.className : ''}\n                              style={{color: '#555'}}\n                            >{option.text}</span> {selectedItems.length > index + 1 ? separator ? `${separator}` : ', ' : null}\n                            </React.Fragment>\n                          ))\n                      : noneSelectedText ?\n                      <span style={{color: touched && error ? \"#dd4b39\" : '#999'}}> {noneSelectedText}</span> : <span style={{color: '#999'}}> Todos </span>\n                  }\n                </div>\n              </div>\n            </div>\n            <span className=\"bs-caret\" style={{color: touched && error ? \"#dd4b39\" : undefined}}>\n            <span className=\"caret\"/>\n          </span>\n          </button>\n          <div className={`dropdown-menu ${right?'dropdown-menu-right':''}`} style={{borderRadius: '0px'}}>\n            {\n              search ?\n                <div className=\"bs-searchbox\">\n                  <input\n                    ref={this.input}\n                    type=\"text\"\n                    className=\"form-control input-sm\"\n                    autoComplete=\"off\"\n                    value={this.state.searchText}\n                    onChange={\n                      (e: React.ChangeEvent<HTMLInputElement>) => this.search(e.target.value)\n                    }\n                  />\n                </div> : null\n            }\n            {\n              allOption ?\n                <div className=\"bs-actionsbox\">\n                  <div className=\"btn-group btn-group-sm btn-block\">\n                    <button\n                      onClick={() => selectAll(true)}\n                      type=\"button\" className=\"actions-btn bs-select-all btn btn-default\">Seleccionar todo\n                    </button>\n                    <button\n                      onClick={() => selectAll(false)}\n                      type=\"button\" className=\"actions-btn bs-deselect-all btn btn-default\">Deseleccionar todo\n                    </button>\n                  </div>\n                </div> : null\n            }\n            <div\n              className=\"inner open\"\n              aria-expanded=\"false\"\n              tabIndex={-1}\n            >\n              <ul className=\"dropdown-menu inner\" style={{maxHeight: '20vh', overflowY: 'auto'}}>\n                {\n                  options.filter((option) => {\n                    if (!searchText || !searchText.length) {\n                      return true;\n                    }\n                    return unorm.nfd(option.text)\n                      .replace(/[\\u0300-\\u036f]/g, '')\n                      .toLowerCase()\n                      .includes(searchText.toLowerCase());\n                  }).map((option) => {\n                    const isSelected = input.value.includes(option.value);\n                    return (\n                      <li key={option.value} className={`${isSelected ? 'selected' : ''}`} onClick={() => onClick(option.value)}>\n                        <a role=\"option\" tabIndex={0} className={`${isSelected ? 'selected' : ''}`} style={{background: '#FFF'}}>\n                          <span className=\"glyphicon glyphicon-ok check-mark\"/>\n                          <span className={option.className ? option.className : ''}>{option.text}</span>\n                        </a>\n                      </li>\n                    );\n                  })\n                }\n              </ul>\n            </div>\n          </div>\n        </div>\n        {\n          touched &&\n          ((error && <span className=\"help-block text-ellipsis\">{error}</span>) ||\n            (warning && <span className=\"help-block text-ellipsis\">{warning}</span>)) || <span className=\"help-block\">&nbsp;</span>\n        }\n      </div>\n    );\n  }\n\n  private handlerOpen() {\n    // if (this.input.current) {\n    //   this.input.current.focus()\n    // }\n    this.setState({\n        open: !this.state.open\n      }, () => {\n        if (!this.state.open) {\n          this.search('');\n        }\n      }\n    );\n  }\n\n  private search(searchText: string) {\n    this.setState({\n      searchText: unorm.nfd(searchText).replace(/[\\u0300-\\u036f]/g, '')\n    });\n  }\n}\n\nexport default BootstrapSelectField;\n","import * as React from 'react';\n\ninterface IPropsType {\n  checked: boolean;\n  onChange: any;\n  color?: string;\n}\n\nclass BootstrapSwitch extends React.Component<IPropsType, {}> {\n\n  state = {\n    hover: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n  render(): React.ReactElement<IPropsType> {\n    const {checked, onChange, color} = this.props;\n    return (\n      <label className={`switch ${color ? `switch-${color}` : ''}`}>\n        <input type=\"checkbox\" className=\"switch\" checked={checked} onChange={onChange}/>\n        <span className=\"slider round\"/>\n      </label>\n    );\n  }\n}\n\nexport default BootstrapSwitch;\n","import * as React from 'react';\nimport {RefObject} from 'react';\n\ninterface IPropsType {\n  value: string;\n\n  items: any[];\n  inputClass?: string;\n\n  renderItem(item: any, index: any): React.ReactElement<any>;\n  onChange(e: React.ChangeEvent<HTMLInputElement>): void;\n  onSelect(item: any): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  open: boolean;\n}\n\nclass AutoCompleteInput extends React.Component<IPropsType, IStateType>{\n\n  readonly state = {\n    error: null,\n    open: false\n  };\n  readonly autocompleteElement: RefObject<HTMLInputElement>;\n  readonly items: RefObject<HTMLInputElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.changeOpen = this.changeOpen.bind(this);\n    this.close = this.close.bind(this);\n    this.outsideClick = this.outsideClick.bind(this);\n    this.renderItem = this.renderItem.bind(this);\n    this.autocompleteElement = React.createRef();\n    this.items = React.createRef();\n  }\n\n  public componentDidMount(): void {\n    document.addEventListener('keydown', this.close, true);\n    document.addEventListener('click', this.outsideClick, true);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { onChange, value, items, inputClass } = this.props;\n    return (\n      <div className=\"autocomplete\" ref={this.autocompleteElement} >\n        <input\n          type=\"text\"\n          className={`form-control ${inputClass ? inputClass : ''}`}\n          onChange={(e) => {\n            if (this.items.current) {\n              this.items.current.scrollTop = 0;\n            }\n            this.setState({\n              open: true\n            });\n            onChange(e);\n          }}\n          value={value}\n          onClick={this.changeOpen}\n          autoComplete={'off'}\n        />\n        {\n          this.state.open ?\n            <div className=\"items\" ref={this.items}>\n              {\n                items.map((item, index) => (\n                  this.renderItem(item, index)\n                ))\n              }\n            </div>\n            : null\n        }\n      </div>\n    );\n  }\n\n  private renderItem(item: any, index: any) {\n    const element = this.props.renderItem(item, index);\n    return React.cloneElement(element, {\n      onClick: () => {\n        this.props.onSelect(item);\n        this.changeOpen();\n      }\n    });\n  }\n\n  public componentWillUnmount(): void {\n    document.removeEventListener('keydown', this.close, true);\n    document.removeEventListener('click', this.outsideClick, true);\n  }\n\n  private close(e: any): void {\n    // if ((e.key === 'Escape' || e.key === 'Esc' || e.keyCode === 27) && (e.target.nodeName === 'BODY')) {\n    if (e.key === 'Escape' || e.key === 'Esc' || e.keyCode === 27) {\n      e.preventDefault();\n      this.setState({\n        open: false\n      });\n    }\n  }\n\n  private outsideClick(e: any): void{\n    if(!this.autocompleteElement.current!.contains(e.target)){\n      this.setState({\n        open: false\n      });\n    }\n  }\n\n  private changeOpen(): void {\n    const {open} = this.state;\n    this.setState({\n      open: !open\n    });\n  }\n}\n\nexport default AutoCompleteInput;\n","import Axios, { AxiosError, AxiosResponse, CancelTokenSource } from 'axios';\nimport { Dispatch } from 'redux';\nimport { debounce } from 'throttle-debounce';\nimport { ICarrier } from '../../../../../src/app/interfaces/carrier.interface';\nimport { IReason } from '../../../../../src/request/interfaces/reason.interface';\nimport { IRequest } from '../../../../../src/request/interfaces/request.interface';\nimport { IRequestItem } from '../../../../../src/request/interfaces/requestItem.interface';\nimport { IRequestItemStatus } from '../../../../../src/request/interfaces/requestItemStatus.interface';\nimport ApiService from '../utils/axios';\nimport {\n  ICancelRequest,\n  IChangeOrderRequest,\n  ICreateRequestItemInDetail,\n  ICreateRequestItemInList,\n  IDeleteRequestInList,\n  IDeleteRequestItemInDetail,\n  IDeleteRequestItemInList,\n  IIsLoadingRequest,\n  ILoadCarriersRequest,\n  ILoadSettingsRequest,\n  ILoadReasonsRequest,\n  ILoadRequest,\n  ILoadRequestItemStatus,\n  ILoadRequests,\n  IRequestsState,\n  ITabStatusRequest,\n  IUpdateRequestItemInDetail,\n  IUpdateRequestItemInList,\n  RequestsReduxActions,\n  REQUEST_CANCEL_REQUEST,\n  REQUEST_CHANGE_ORDER,\n  REQUEST_CREATE_REQUEST_ITEM_IN_DETAIL,\n  REQUEST_CREATE_REQUEST_ITEM_IN_LIST,\n  REQUEST_DELETE_REQUEST_IN_LIST,\n  REQUEST_DELETE_REQUEST_ITEM_IN_DETAIL,\n  REQUEST_DELETE_REQUEST_ITEM_IN_LIST,\n  REQUEST_IS_LOADING,\n  REQUEST_LOAD_CARRIERS,\n  REQUEST_LOAD_REASONS,\n  REQUEST_LOAD_REQUEST,\n  REQUEST_LOAD_REQUESTS,\n  REQUEST_LOAD_REQUEST_ITEM_STATUS,\n  REQUEST_TAB_STATUS,\n  REQUEST_UDPATE_REQUEST_ITEM_IN_DETAIL,\n  REQUEST_UDPATE_REQUEST_ITEM_IN_LIST,\n  REQUEST_LOAD_SETTINGS, ILoadItemsRequest, REQUEST_LOAD_ITEMS\n} from './requests.types';\nimport { IRequestSetting } from '../../../../../src/app/interfaces';\n\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: REQUEST_CANCEL_REQUEST,\n    payload: {\n      source\n    }\n  };\n}\n\nexport function isLoadingRequestAction(loading: boolean): IIsLoadingRequest {\n  return {\n    type: REQUEST_IS_LOADING,\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function loadReasonsRequestAction(reasons: IReason[]): ILoadReasonsRequest {\n  return {\n    type: REQUEST_LOAD_REASONS,\n    payload: {\n      reasons\n    }\n  };\n}\n\nexport function loadCarriersRequestAction(carriers: ICarrier[]): ILoadCarriersRequest {\n  return {\n    type: REQUEST_LOAD_CARRIERS,\n    payload: {\n      carriers\n    }\n  };\n}\n\nexport function loadRequestItemsStatusRequestAction(requestItemStatus: IRequestItemStatus[], min: number, max: number): ILoadRequestItemStatus {\n  return {\n    type: REQUEST_LOAD_REQUEST_ITEM_STATUS,\n    payload: {\n      requestItemStatus,\n      min,\n      max\n    }\n  };\n}\n\nexport function loadRequestItemsSettingsAction(requestSettings: IRequestSetting): ILoadSettingsRequest {\n  return {\n    type: REQUEST_LOAD_SETTINGS,\n    payload: {\n      requestSettings\n    }\n  };\n}\n\nexport function loadRequestsAction(requests: any[], count: number, pages: number, page: number): ILoadRequests {\n  return {\n    type: REQUEST_LOAD_REQUESTS,\n    payload: {\n      requests,\n      count,\n      pages,\n      page\n    }\n  };\n}\n\nexport function loadRequestAction(request: IRequest): ILoadRequest {\n  return {\n    type: REQUEST_LOAD_REQUEST,\n    payload: {\n      request\n    }\n  };\n}\n\nexport function createRequestItemActionInList(idRequest: string, item: IRequestItem): ICreateRequestItemInList {\n  return {\n    type: REQUEST_CREATE_REQUEST_ITEM_IN_LIST,\n    payload: {\n      idRequest,\n      item\n    }\n  };\n}\n\nexport function updateRequestItemActionInList(request: string, item: IRequestItem): IUpdateRequestItemInList {\n  return {\n    type: REQUEST_UDPATE_REQUEST_ITEM_IN_LIST,\n    payload: {\n      request,\n      item\n    }\n  };\n}\n\nexport function deleteRequestItemActionInList(idRequest: string, item: IRequestItem): IDeleteRequestItemInList {\n  return {\n    type: REQUEST_DELETE_REQUEST_ITEM_IN_LIST,\n    payload: {\n      idRequest,\n      item\n    }\n  };\n}\n\nexport function createRequestItemActionInDetail(item: IRequestItem): ICreateRequestItemInDetail {\n  return {\n    type: REQUEST_CREATE_REQUEST_ITEM_IN_DETAIL,\n    payload: {\n      item\n    }\n  };\n}\n\nexport function updateRequestItemActionInDetail(item: IRequestItem): IUpdateRequestItemInDetail {\n  return {\n    type: REQUEST_UDPATE_REQUEST_ITEM_IN_DETAIL,\n    payload: {\n      item\n    }\n  };\n}\n\nexport function deleteRequestItemActionInDetail(item: IRequestItem): IDeleteRequestItemInDetail {\n  return {\n    type: REQUEST_DELETE_REQUEST_ITEM_IN_DETAIL,\n    payload: {\n      item\n    }\n  };\n}\n\nexport function changeTabStatusAction(request: string): ITabStatusRequest {\n  return {\n    type: REQUEST_TAB_STATUS,\n    payload: {\n      request\n    }\n  };\n}\n\nexport function loadItemsAction(request: string, items: any): ILoadItemsRequest {\n  return {\n    type: REQUEST_LOAD_ITEMS,\n    payload: {\n      request,\n      items\n    }\n  };\n}\n\nexport function tabStatusAction(request: string) {\n  return (dispatch: Dispatch<RequestsReduxActions>, getState: () => { requests: IRequestsState }) => {\n    const state = getState();\n    const isOpen = state.requests.requestOpen.includes(request);\n    const hasItems = state.requests.requestItemsById.hasOwnProperty(request);\n    dispatch(changeTabStatusAction(request));\n    if (!isOpen && !hasItems) {\n      const api: ApiService = new ApiService();\n      api.getRequest(request)\n        .then((response: AxiosResponse) => {\n          dispatch(loadItemsAction(request, response.data.items));\n        });\n    }\n  };\n}\n\nexport function deleteRequestActionInList(id: string): IDeleteRequestInList {\n  return {\n    type: REQUEST_DELETE_REQUEST_IN_LIST,\n    payload: {\n      id\n    }\n  };\n}\n\nexport function changeOrderRequestAction(orderBy: string, orderType: string): IChangeOrderRequest {\n  return {\n    type: REQUEST_CHANGE_ORDER,\n    payload: {\n      orderBy,\n      orderType\n    }\n  };\n}\n\nexport function getRequestsThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) {\n  return (dispatch: Dispatch<RequestsReduxActions>, getState: () => { requests: IRequestsState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(isLoadingRequestAction(hideLoading ? false : true));\n    const page = nextPage ? nextPage : state.requests.pagination.page;\n    dispatch(changeOrderRequestAction(orderBy, orderType));\n    dispatch(cancelRequestAction(api.getSource()));\n    Axios\n      .all([\n        api.getRequests({page, orderBy, orderType}),\n        api.getReasons({ page: 1, pageSize: 200 }),\n        api.getRequestItemsStatus({ page: 1, pageSize: 200 }),\n        api.getTeamSettings()\n        // api.getCarriers(1, 200)\n      ])\n      .then(Axios.spread((requests, reasons, requestItemStatus, teamsettings /*, carriers*/) => {\n        const {data} = requests;\n        dispatch(loadRequestsAction(data.results, data.count, data.pages, page));\n        dispatch(loadReasonsRequestAction(reasons.data.results));\n        dispatch(loadRequestItemsStatusRequestAction(requestItemStatus.data.results, requestItemStatus.data.min, requestItemStatus.data.max));\n        dispatch(loadRequestItemsSettingsAction(teamsettings.data.request));\n        // dispatch(loadCarriersRequestAction(carriers.data.results));\n        dispatch(isLoadingRequestAction(false));\n      }))\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingRequestAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function getRequestThunkAction(id: string) {\n  return (dispatch: Dispatch<RequestsReduxActions>) => {\n    const api: ApiService = new ApiService();\n    dispatch(isLoadingRequestAction(true));\n    dispatch(cancelRequestAction(api.getSource()));\n    Axios\n      .all([\n        api.getRequest(id),\n        api.getReasons({ page: 1, pageSize: 200 }),\n        api.getRequestItemsStatus({ page: 1, pageSize: 200 }),\n        api.getTeamSettings()\n        // api.getCarriers(1, 200)\n      ])\n      .then(Axios.spread((request, reasons, requestItemStatus, teamsettings /*, carriers*/) => {\n        const { data } = request;\n        dispatch(loadRequestAction(data));\n        dispatch(loadReasonsRequestAction(reasons.data.results));\n        dispatch(loadRequestItemsStatusRequestAction(requestItemStatus.data.results, requestItemStatus.data.min, requestItemStatus.data.max));\n        dispatch(loadRequestItemsSettingsAction(teamsettings.data.request));\n        // dispatch(loadCarriersRequestAction(carriers.data.results));\n        dispatch(isLoadingRequestAction(false));\n      }))\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingRequestAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function updateRequestItemInListThunkAction(idRequest: string, item: IRequestItem) {\n  return (dispatch: Dispatch<RequestsReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.updateRequestItem(item._id, item)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateRequestItemActionInList(idRequest, data));\n      });\n  };\n}\n\nexport function deleteRequestItemThunkAction(item: IRequestItem) {\n  return (dispatch: Dispatch<RequestsReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.deleteRequestItem(item._id)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateRequestItemActionInList(idRequest, data));\n      });\n  };\n}\n\nconst debounceUpdateRequestItem = debounce(500, (item) => {\n  const api: ApiService = new ApiService();\n  api.updateRequestItem(item._id, item)\n    // tslint:disable-next-line: no-empty\n    .then((response: AxiosResponse) => { });\n});\nexport function updateRequestItemInDetailThunkAction({ item, debounce }: { item: IRequestItem, debounce?: boolean}) {\n  return (dispatch: Dispatch<RequestsReduxActions>) => {\n    dispatch(updateRequestItemActionInDetail(item));\n    if (debounce) {\n      debounceUpdateRequestItem(item);\n    } else {\n      const api: ApiService = new ApiService();\n      api.updateRequestItem(item._id, item)\n        // tslint:disable-next-line: no-empty\n        .then((response: AxiosResponse) => { });\n    }\n  };\n}\n\nexport function deleteRequestThunkAction(id: string) {\n  return (dispatch: Dispatch<RequestsReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.deleteRequest(id)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateRequestItemActionInList(idRequest, data));\n      });\n  };\n}\n","import * as React from 'react';\nimport { SelectHTMLAttributes } from 'react';\n\ninterface IPropsType {\n  input: SelectHTMLAttributes<any>;\n  label: string;\n  children: React.ReactNode;\n  disabled?: boolean;\n  labelOff?: boolean;\n  meta: {\n    touched: boolean;\n    error: string;\n    warning: string;\n  };\n}\n\nconst SelectField: React.FunctionComponent<IPropsType> = ({\n  input,\n  label,\n  children,\n  disabled,\n  labelOff,\n  meta: { touched, error, warning }\n}: IPropsType) => {\n  return (\n    <div className={`form-group ${touched && error ? 'has-error' : ''} ${touched && warning ? 'has-warning' : ''}`}>\n      {!labelOff ? <label className='control-label'>{label}</label> : null}\n      <select\n        {...input}\n        className={`form-control input-sm ${touched && error ? 'is-invalid' : warning ? 'is-warning' : ''}`}\n        disabled={disabled}\n        placeholder={label}\n      >\n        {children}\n      </select>\n      {\n        touched &&\n        ((error && <span className='help-block'>{error}</span>) ||\n          (warning && <span className='help-block'>{warning}</span>)) || <span className=\"help-block\">&nbsp;</span>\n      }\n    </div>\n  );\n};\n\nexport default SelectField;\n","import {AxiosError, AxiosResponse, CancelTokenSource, default as Axios} from 'axios';\nimport {Dispatch} from 'redux';\nimport {ICar} from '../../../../../src/app/interfaces/car.interface';\nimport ApiService from '../utils/axios';\n\nexport interface ICarsState {\n  cars: ICar[];\n  car: ICar | null;\n  carEvents: any;\n  loading: boolean;\n  source: CancelTokenSource | null;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface ICancelRequest {\n  type: '/CARS/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/CARS/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/CARS/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/CARS/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IChangePage {\n  type: '/CARS/CHANGE_PAGE';\n  payload: {\n    page: number;\n  };\n}\n\nexport function changePageAction(page: number): IChangePage {\n  return {\n    type: '/CARS/CHANGE_PAGE',\n    payload: {\n      page\n    }\n  };\n}\n\ninterface ILoadCars {\n  type: '/CARS/LOAD_CARS';\n  payload: {\n    cars: any;\n    count: number;\n    pages: number\n  };\n}\n\nexport function loadCarsAction(cars: any, count: number, pages: number): ILoadCars {\n  return {\n    type: '/CARS/LOAD_CARS',\n    payload: {\n      cars,\n      count,\n      pages\n    }\n  };\n}\n\ninterface ILoadCar {\n  type: '/CARS/LOAD_CAR';\n  payload: {\n    car: ICar;\n  };\n}\n\nexport function loadCarAction(car: ICar): ILoadCar {\n  return {\n    type: '/CARS/LOAD_CAR',\n    payload: {\n      car\n    }\n  };\n}\n\nexport function getCarAction(id: string) {\n  return (dispatch: Dispatch<CarReduxAction>) => {\n    const api: ApiService = new ApiService();\n    dispatch(cancelRequestAction(api.getSource()));\n    dispatch(isLoadingAction(true));\n    api.getCar(id)\n      .then((response: AxiosResponse) => {\n        document.title = `OSA Andes | Detalle VIN ${response.data.data.vin}`;\n        dispatch(loadCarAction(response.data.data));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\nexport function getCarsAction(nextPage: number, search?: string) {\n  return (dispatch: Dispatch<CarReduxAction>, getState: () => {cars: ICarsState}) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    if (nextPage && nextPage !== state.cars.pagination.page) {\n      dispatch(isLoadingAction(true));\n    }\n    dispatch(cancelRequestAction(api.getSource()));\n    const page = nextPage ? nextPage : state.cars.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n    api.getAdminCars(page, search)\n      .then((response: AxiosResponse) => {\n        dispatch(loadCarsAction(response.data.results, response.data.count, response.data.pages));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\nexport type CarReduxAction =\n  ICancelRequest |\n  IIsLoading |\n  IChangePage |\n  ILoadCars |\n  ILoadCar;\n","import * as React from \"react\";\nimport {InputHTMLAttributes} from \"react\";\ninterface IPropsType {\n  input: InputHTMLAttributes<any>\n  checked: boolean;\n  label: string;\n  type: string;\n  help: string;\n  meta: {\n    touched: boolean;\n    error: string;\n    warning: string;\n  };\n}\nconst BootstrapSwitchField: React.FunctionComponent<IPropsType> = ({\n  input,\n  label,\n  checked,\n  help,\n  meta: { touched, error, warning }\n}:IPropsType) => (\n  <div className=\"form-group-switch\">\n    <label className={`switch switch-blue`}>\n      <input type='checkbox' className='switch' {...input} checked={checked} />\n      <span className=\"slider round\" />\n    </label>\n    <label className=\"switch-label\">{label}</label>\n    {\n      help ?\n        <small id=\"passwordHelpBlock\" className=\"form-text text-muted\">\n          {help}\n        </small>\n        : null\n    }\n    {\n      touched &&\n      ((error && <span className=\"error invalid-feedback\">{error}</span>) ||\n        (warning && <span className=\"warning warning-feedback\">{warning}</span>))\n    }\n  </div>\n);\n\nexport default BootstrapSwitchField;\n\n\n\n","import {AxiosError, AxiosResponse, CancelTokenSource, default as Axios} from 'axios';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport {IInventoryCar} from '../../../../../src/inventory/interfaces/inventory.interface';\nimport {IInventorySetting} from '../../../../../src/app/interfaces/teamSetting.interface';\nimport {IInventoryComment} from '../../../../../src/inventory/interfaces/inventoryComment.interface';\nimport {IInventoryLabel} from '../../../../../src/inventory/interfaces/inventoryLabel.interface';\nimport {IFilterCar} from '../reducers/inventory.reducer';\nimport ApiService from '../utils/axios';\n\nexport interface IInventorySummaryResult {\n  pending: number;\n  found: number;\n  leftover: number;\n  reported: number;\n  missing: number;\n}\n\nexport interface IInventorySummary {\n  _id: string;\n  name: string;\n  createdBy?: {\n    lastName: string;\n    firstName: string;\n    fullName: string;\n  };\n  results?: IInventorySummaryResult;\n  status: string;\n  createdAt: Date | null;\n  finalizedAt: Date | null;\n}\n\nexport interface IDetailByVenue {\n  _id: string;\n  name: string;\n  results: {\n    pending: number;\n    found: number;\n    leftover: number;\n    missing: number;\n    reported: number;\n  };\n}\n\nexport interface IDetailByBrand {\n  name: string;\n  results: {\n    pending: number;\n    found: number;\n    missing: number;\n    leftover: number;\n    reported: number;\n  };\n}\n\nexport interface IInventoryState {\n  inventories: any[];\n  inventorySettings: IInventorySetting;\n  loading: boolean;\n  inventoryCar: IInventoryCar | null;\n  source: CancelTokenSource | null;\n  loadingDetail: boolean;\n  fetchingDetail: boolean;\n  summary: IInventorySummary;\n  detail: any | null;\n  detailByVenue: IDetailByVenue[];\n  labels: IInventoryLabel[];\n  detailByBrand: IDetailByBrand[];\n  carsTable: any[];\n  cardTypes: string[];\n  cardProperties: string[];\n  selectedItems: {\n    [key: string]: any\n  };\n  filter: IFilterCar;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface IUpdateInventoryCar {\n  type: '/INVENTORIES/UPDATE_INVENTORY_CAR';\n  payload: {\n    inventoryCar: IInventoryCar;\n  };\n}\n\nexport function updateInventoryCarAction(inventoryCar: IInventoryCar): IUpdateInventoryCar {\n  return {\n    type: '/INVENTORIES/UPDATE_INVENTORY_CAR',\n    payload: {\n      inventoryCar\n    }\n  };\n}\n\ninterface IAddComment {\n  type: '/INVENTORIES/ADD_COMMENT';\n  payload: {\n    inventoryComment: IInventoryComment;\n  };\n}\n\nexport function addCommentAction(inventoryComment: IInventoryComment): IAddComment {\n  return {\n    type: '/INVENTORIES/ADD_COMMENT',\n    payload: {\n      inventoryComment\n    }\n  };\n}\n\ninterface ICancelRequest {\n  type: '/INVENTORIES/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/INVENTORIES/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/INVENTORIES/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/INVENTORIES/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface ILoadInventories {\n  type: '/INVENTORIES/LOAD_DATA';\n  payload: {\n    inventories: any[];\n    inventorySettings: any;\n    count: number;\n    pages: number;\n    page: number\n  };\n}\n\nexport function loadInventoriesAction(inventories: any[], inventorySettings: any, count: number, pages: number, page: number): ILoadInventories {\n  return {\n    type: '/INVENTORIES/LOAD_DATA',\n    payload: {\n      inventories,\n      inventorySettings,\n      count,\n      pages,\n      page\n    }\n  };\n}\n\nexport function getInventoriesAction(loading: boolean, nextPage: number,) {\n  return (dispatch: Dispatch<InventoryReduxAction>, getState: () => {inventories: IInventoryState}) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    if (loading) {\n      window.scrollTo(0, 0);\n      dispatch(isLoadingAction(true));\n    }\n    const page = nextPage ? nextPage : state.inventories.pagination.page;\n    dispatch(cancelRequestAction(api.getSource()));\n    api.getInventories(page)\n      .then((response: AxiosResponse) => {\n        const data = response.data;\n        dispatch(loadInventoriesAction(data.inventories, data.inventorySettings, data.count, data.pages, page));\n        if (loading) {\n          dispatch(isLoadingAction(false));\n        }\n      })\n      .catch((err: AxiosError) => {\n        if (loading) {\n          dispatch(isLoadingAction(false));\n        }\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function finishInventoryAction(id: string) {\n  return (dispatch: Dispatch<InventoryReduxAction>, getState: () => {inventories: IInventoryState}) => {\n    const state = getState();\n    const api: ApiService = new ApiService();\n    api.finishInventory(id)\n      .then((response: AxiosResponse) => {\n        const data = response.data;\n        dispatch(getInventoriesAction(false, state.inventories.pagination.page) as any);\n        swal('Inventarios', data.message, 'success');\n      })\n      .catch((err: AxiosError) => {\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function deleteInventoryAction(id: string) {\n  return (dispatch: Dispatch<InventoryReduxAction>, getState: () => {inventories: IInventoryState}) => {\n    const state = getState();\n    const api: ApiService = new ApiService();\n    api.deleteInventory(id)\n      .then((response: AxiosResponse) => {\n        $(`#inventory-${id}`)\n          .addClass('deleted-item');\n        const data = response.data;\n        swal('Inventarios', data.message, 'success');\n        setTimeout(() => {\n          dispatch(getInventoriesAction(false, state.inventories.pagination.page) as any);\n        }, 500);\n      })\n      .catch((err: AxiosError) => {\n        api.errorHandler(err);\n      });\n  };\n}\n\ninterface ILoadingDetailInventory {\n  type: '/INVENTORIES/LOADING_INVENTORY_DETAIL';\n  payload: {\n    loadingDetail: boolean;\n  };\n}\n\nexport function loadingInventoryDetaillAction(loadingDetail: boolean): ILoadingDetailInventory {\n  return {\n    type: '/INVENTORIES/LOADING_INVENTORY_DETAIL',\n    payload: {\n      loadingDetail\n    }\n  };\n}\n\ninterface IFetchingDetailInventory {\n  type: '/INVENTORIES/FETCHING_INVENTORY_DETAIL';\n  payload: {\n    fetchingDetail: boolean;\n  };\n}\n\nexport function fetchingnventoryDetaillAction(fetchingDetail: boolean): IFetchingDetailInventory {\n  return {\n    type: '/INVENTORIES/FETCHING_INVENTORY_DETAIL',\n    payload: {\n      fetchingDetail\n    }\n  };\n}\n\ninterface IDetailInventorySelected {\n  type: '/INVENTORIES/CHANGE_SELECTED';\n  payload: {\n    item: string;\n  };\n}\n\nexport function inventoryDetailChangeSelected(item: string): IDetailInventorySelected {\n  return {\n    type: '/INVENTORIES/CHANGE_SELECTED',\n    payload: {\n      item\n    }\n  };\n}\n\ninterface IDetailChangeFilter {\n  type: '/INVENTORIES/CHANGE_FILTER';\n  payload: {\n    filter: IFilterCar\n  };\n  meta: {\n    debounce: {\n      time: number\n    }\n  };\n}\n\nexport function inventoryDetailChangeFilter(filter: IFilterCar): IDetailChangeFilter {\n  return {\n    type: '/INVENTORIES/CHANGE_FILTER',\n    payload: {\n      filter\n    },\n    meta: {\n      debounce: {\n        time: 0\n      }\n    }\n  };\n}\n\nexport function inventoryDetailChangeFilterText(filter: IFilterCar): IDetailChangeFilter {\n  return {\n    type: '/INVENTORIES/CHANGE_FILTER',\n    payload: {\n      filter\n    },\n    meta: {\n      debounce: {\n        time: 300\n      }\n    }\n  };\n}\n\ninterface ILoadInventory {\n  type: '/INVENTORIES/LOAD_INVENTORY_DATA';\n  payload: {\n    summary: IInventorySummary;\n    inventorySettings: any;\n    detailByVenue: IDetailByVenue[];\n    detailByBrand: IDetailByBrand[];\n    labels: IInventoryLabel[],\n    detail: any;\n    resetFilter: boolean;\n  };\n}\n\nexport function loadInventoryAction(\n  summary: IInventorySummary,\n  inventorySettings: any,\n  detailByVenue: IDetailByVenue[],\n  detailByBrand: IDetailByBrand[],\n  labels: IInventoryLabel[],\n  detail: any,\n  resetFilter: boolean\n): ILoadInventory {\n  return {\n    type: '/INVENTORIES/LOAD_INVENTORY_DATA',\n    payload: {\n      resetFilter: !resetFilter,\n      summary,\n      inventorySettings,\n      detailByVenue,\n      detailByBrand,\n      labels,\n      detail\n    }\n  };\n}\n\nlet preventRepeatGetInventoryDetail: any;\nexport function getInventoryDetailAction(id: string, update: boolean) {\n  return (dispatch: Dispatch<InventoryReduxAction>, getState: () => { inventories: IInventoryState }) => {\n    const state = getState();\n    if (state.inventories.fetchingDetail) {\n      clearTimeout(preventRepeatGetInventoryDetail);\n      preventRepeatGetInventoryDetail = setTimeout(() => (dispatch as any)(getInventoryDetailAction(id, update)), 1000);\n    } else {\n      dispatch(fetchingnventoryDetaillAction(true));\n      if (!update) {\n        dispatch(loadingInventoryDetaillAction(true));\n      }\n      const api: ApiService = new ApiService();\n      dispatch(cancelRequestAction(api.getSource()));\n      api.getInventory(id)\n        .then((response: AxiosResponse) => {\n          const {data} = response;\n          dispatch(loadInventoryAction(\n            data.summary,\n            data.inventorySettings,\n            data.detailByVenue,\n            data.detailByBrand,\n            data.labels,\n            data.detail,\n            update\n          ));\n          dispatch(fetchingnventoryDetaillAction(false));\n          dispatch(loadingInventoryDetaillAction(false));\n          if (!update) {\n            $('.count').each(function() {\n              $(this).prop('Counter', 0).animate({\n                Counter: $(this).text()\n              }, {\n                duration: 1500,\n                easing: 'swing',\n                step: function(now) {\n                  $(this).text(Math.ceil(now));\n                }\n              });\n            });\n          }\n        })\n        .catch((err: AxiosError) => {\n          console.log('err', err);\n          if (!Axios.isCancel(err)) {\n            api.errorHandler(err);\n          }\n          dispatch(loadingInventoryDetaillAction(false));\n          dispatch(fetchingnventoryDetaillAction(false));\n        });\n    }\n  };\n}\n\nexport function sendCommentAction(carId: string, comment: string) {\n  return (dispatch: Dispatch<InventoryReduxAction>, getState: () => {inventories: IInventoryState}) => {\n    const state = getState();\n    const api: ApiService = new ApiService();\n    api.addComment(state.inventories.detail._id, carId, comment)\n      .catch((err: AxiosError) => {\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function actionSetLabel(inventory: string, car: string, carID: string, label: IInventoryLabel) {\n  return (dispatch: Dispatch<InventoryReduxAction>) => {\n    const api: ApiService = new ApiService();\n    if (label.requireCustomText) {\n      (swal as any)('Agregar datos adicionales:', {\n        content: 'input'\n      }).then((custom: string) => {\n        if (custom && custom.trim().length) {\n          api.setLabel(inventory, car, carID, label._id, custom)\n            .then((response: AxiosResponse) => {\n              swal(response.data.message, {\n                icon: 'success'\n              });\n              setTimeout(() => {\n                (swal as any).close();\n              }, 1000);\n            })\n            .catch((err: AxiosError) => {\n              api.errorHandler(err);\n            });\n        } else {\n          swal('Operación cancelada', {\n            icon: 'error'\n          });\n        }\n      });\n    } else {\n      api.setLabel(inventory, car, carID, label._id)\n        .then((response: AxiosResponse) => {\n          swal(response.data.message, {\n            icon: 'success'\n          });\n          setTimeout(() => {\n            (swal as any).close();\n          }, 1500);\n        })\n        .catch((err: AxiosError) => {\n          api.errorHandler(err);\n        });\n    }\n  };\n}\n\nexport type InventoryReduxAction =\n  ICancelRequest |\n  IIsLoading |\n  ILoadInventories |\n  ILoadInventory |\n  ILoadingDetailInventory |\n  IUpdateInventoryCar |\n  IAddComment |\n  IDetailChangeFilter |\n  IDetailInventorySelected |\n  IFetchingDetailInventory;\n","import * as React from 'react';\nimport {InputHTMLAttributes} from 'react';\ninterface IPropsType {\n  input: InputHTMLAttributes<any>\n  checked: boolean;\n  label: string;\n  type: string;\n  help: string;\n  style: any;\n  meta: {\n    touched: boolean;\n    error: string;\n    warning: string;\n  };\n}\nconst CheckBoxField: React.FunctionComponent<IPropsType> = ({\n  input,\n  label,\n  checked,\n  style={},\n  type,\n  help,\n  meta: { touched, error, warning }\n}:IPropsType) => (\n  <div className=\"form-group\" style={style}>\n    <div className=\"form-check\">\n      <input type={type} className=\"form-check-input\" checked={checked} {...input}  />\n      <label className=\"form-check-label\" style={{marginLeft: '5px'}}> {label}</label>\n    </div>\n    {\n      help ?\n        <small id=\"passwordHelpBlock\" className=\"form-text text-muted\">\n          {help}\n        </small>\n        : null\n    }\n    {\n      touched &&\n      ((error && <span className=\"error invalid-feedback\">{error}</span>) ||\n        (warning && <span className=\"warning warning-feedback\">{warning}</span>))\n    }\n  </div>\n);\n\nexport default CheckBoxField;\n\n\n\n","import * as moment from 'moment-timezone';\nimport * as React from 'react';\nimport { CSSProperties, RefObject } from 'react';\n\ninterface IPropsType {\n  onChange?: (e: moment.Moment | null) => void;\n  className?: string;\n  format?: string;\n  style?: CSSProperties;\n  value?: any;\n  startDate?: any\n  todayHighlight?: boolean\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass DateRangePicker extends React.Component<IPropsType, IStateType> {\n\n  readonly input: RefObject<HTMLInputElement>;\n  readonly inputGroup: RefObject<HTMLInputElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.input = React.createRef();\n    this.inputGroup = React.createRef();\n    this.clickCalendar = this.clickCalendar.bind(this);\n  }\n\n  public componentDidMount() {\n    const { format } = this.props;\n    $(this.input.current!).datepicker({\n      autoclose: true,\n      language: 'es',\n      todayHighlight: !!this.props.todayHighlight,\n      orientation: 'bottom auto',\n      clearBtn: true,\n      startDate: this.props.startDate,\n      format: {\n        toDisplay: (date) => {\n          return moment(date).utc().format(format ?? 'DD-MM-YY');\n        },\n        toValue: (date) => {\n          return moment(date, format ?? 'DD-MM-YY').utc().toDate();\n        }\n      }\n    });\n    $(this.input.current!).on('changeDate', () => {\n      if (typeof (this.props.onChange) === 'function') {\n        const date = moment(this.input.current!.value, format ?? 'DD-MM-YY', true);\n        if (date.isValid()) {\n          this.props.onChange(date);\n        } else {\n          this.props.onChange(null);\n        }\n      }\n    });\n  }\n\n  public componentWillUnmount() {\n    $(this.input.current!).datepicker('destroy');\n  }\n\n  private clickCalendar() {\n    $(this.input.current!).datepicker('show');\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { format, value } = this.props;\n    return (\n      <div className='input-group'>\n        <input\n          ref={this.input}\n          type=\"text\"\n          value={value?.toString().length ? moment(value).format(format ?? 'DD-MM-YY') : ''}\n          className={`form-control ${this.props.className ?? ''}`}\n          onChange={() => {\n          }}\n          style={{ ...this.props.style }}\n        />\n        <span className='input-group-addon pointer' onClick={this.clickCalendar}>\n          <i className='fa fa-calendar' />\n        </span>\n      </div>\n    );\n  }\n}\n\nexport default DateRangePicker;\n","import {IWindow} from '../interfaces/window';\nimport {hasPermission, parseReplicableURL} from './common';\n\ndeclare let window: IWindow;\n\nconst menus: any[] = [];\n\n/* *****************\n* 1. Dashboard\n*****************/\nconst dashboardItems = [{\n  id: '1.1',\n  icon: 'fa-circle-o',\n  text: 'General',\n  url: '/'\n}, {\n  id: '1.2',\n  icon: 'fa-circle-o',\n  text: 'Revisiones',\n  url: '/cars/'\n}, {\n  id: '1.3',\n  icon: 'fa-circle-o',\n  text: 'Reporte revisiones',\n  url: '/revision-report/'\n}];\n\nif (hasPermission(window.user, 'viewDashboardDamages')) {\n  dashboardItems.push({\n    id: '1.4',\n    icon: 'fa-circle-o',\n    text: 'Daños',\n    url: '/dashboard/damages/'\n  });\n}\n\nif (hasPermission(window.user, 'viewDashboardTiming')) {\n  dashboardItems.push({\n    id: '1.5',\n    icon: 'fa-circle-o',\n    text: 'Tiempos de traslado',\n    url: '/dashboard/timing/'\n  });\n}\n\nif (hasPermission(window.user, 'viewDashboardDerco')) {\n  dashboardItems.push({\n    id: '1.6',\n    icon: 'fa-circle-o',\n    text: 'Derco',\n    url: '/dashboard/derco/'\n  });\n}\n\nif (hasPermission(window.user, 'viewChecklistStudio')) {\n  dashboardItems.push({\n    id: '1.7',\n    icon: 'fa-circle-o',\n    text: 'Análisis',\n    url: '/dashboard/studio/'\n  });\n}\n\nif (window.user.isAdmin) {\n  dashboardItems.push({\n    id: '1.10',\n    icon: 'fa-circle-o',\n    text: 'Ajustes',\n    url: '/forms/settings/forms/'\n  });\n}\n\nif (dashboardItems.length) {\n  menus.push({\n    id: '1',\n    text: 'Control Unidades',\n    icon: 'fa-dashboard',\n    url: dashboardItems[0].url,\n    items: dashboardItems\n  });\n}\n\n/* *****************\n* 3. Request and Distribution\n*****************/\nconst distributionItems = [];\n\nif (hasPermission(window.user, 'viewRequest')) {\n  distributionItems.push({\n    id: '3.1',\n    icon: 'fa-circle-o',\n    text: 'Solicitudes',\n    url: parseReplicableURL('/requests/')\n  });\n  distributionItems.push({\n    id: '3.2',\n    icon: 'fa-circle-o',\n    text: 'Unidades',\n    url: parseReplicableURL('/requests/vehicles/')\n  });\n}\n\nif (hasPermission(window.user, 'viewTransmittal')) {\n  distributionItems.push({\n    id: '3.4',\n    icon: 'fa-circle-o',\n    text: 'Transporte',\n    url: parseReplicableURL('/transmittals/')\n  });\n}\n\nif (hasPermission(window.user, 'adminRequest')) {\n  distributionItems.push({\n    id: '3.3',\n    icon: 'fa-circle-o',\n    text: 'Ajustes',\n    url: parseReplicableURL('/requests/settings/reasons/')\n  });\n}\n\nif (hasPermission(window.user, 'viewDistributionStudio')) {\n  distributionItems.push({\n    id: '3.5',\n    icon: 'fa-circle-o',\n    text: 'Análisis',\n    url: '/requests/studio/'\n  });\n}\n\nif (distributionItems.length) {\n  menus.push({\n    id: '3',\n    text: 'Distribución',\n    icon: 'fa-cubes',\n    url: distributionItems[0].url,\n    items: distributionItems\n  });\n}\n\n/* *****************\n* 2. Inventory\n*****************/\nconst inventoryItems = [];\nif (hasPermission(window.user, 'currentStock')) {\n  inventoryItems.push({\n    id: '2.4',\n    icon: 'fa-circle-o',\n    text: 'Stock Actual',\n    url: '/stock/'\n  });\n}\n\nif (hasPermission(window.user, 'viewInventoryDashboard')) {\n  inventoryItems.push({\n    id: '2.3',\n    icon: 'fa-circle-o',\n    text: 'Dashboard',\n    url: '/inventory/dashboard/'\n  });\n}\n\nif (hasPermission(window.user, 'viewInventory')) {\n  inventoryItems.push({\n    id: '2.1',\n    icon: 'fa-circle-o',\n    text: 'Gestión',\n    url: '/inventory/'\n  });\n}\n\nif (hasPermission(window.user, 'viewLabel')) {\n  inventoryItems.push({\n    id: '2.2',\n    icon: 'fa-circle-o',\n    text: 'Etiquetas',\n    url: '/settings/labels/'\n  });\n}\n\nif (hasPermission(window.user, 'viewInventoryStudio')) {\n  inventoryItems.push({\n    id: '2.5',\n    icon: 'fa-circle-o',\n    text: 'Análisis',\n    url: '/inventory/studio/'\n  });\n}\n\nif (inventoryItems.length) {\n  menus.push({\n    id: '2',\n    text: 'Inventario',\n    icon: 'fa-book',\n    url: inventoryItems[0].url,\n    items: inventoryItems\n  });\n}\n\n\n/* *****************\n* 3. Planning\n*****************/\nconst planningItems = [];\nif (hasPermission(window.user, 'viewPlanning')) {\n  planningItems.push({\n    id: '4.1',\n    icon: 'fa-circle-o',\n    text: 'Detalle',\n    url: '/planning/'\n  });\n}\n\nif (hasPermission(window.user, 'viewPlanning')) {\n  planningItems.push({\n    id: '4.2',\n    icon: 'fa-circle-o',\n    text: 'Importar',\n    url: '/planning/import/'\n  });\n}\n\nif (hasPermission(window.user, 'viewPlanificationStudio')) {\n  planningItems.push({\n    id: '4.3',\n    icon: 'fa-circle-o',\n    text: 'Análisis',\n    url: '/planning/studio/'\n  });\n}\n\n\nif (planningItems.length) {\n  menus.push({\n    id: '4',\n    text: 'Planificación',\n    icon: 'fa-calendar-check-o',\n    url: '/planning/',\n    items: planningItems\n  });\n}\n\n/* *****************\n* 10. Settings\n*****************/\nconst settingItems = [/*{\n  id: '10.1',\n  icon: 'fa-circle-o',\n  text: 'Alertas',\n  url: '/settings/alerts/'\n}*/];\n\nif (hasPermission(window.user, 'viewCar')) {\n  settingItems.push({\n    id: '10.2',\n    icon: 'fa-circle-o',\n    text: 'Autos',\n    url: '/settings/cars/'\n  });\n}\n\nif (hasPermission(window.user, 'viewCompany')) {\n  settingItems.push({\n    id: '10.3',\n    icon: 'fa-circle-o',\n    text: 'Empresas',\n    url: '/settings/companies/'\n  });\n}\n\nif (hasPermission(window.user, 'viewVenue')) {\n  settingItems.push({\n    id: '10.4',\n    icon: 'fa-circle-o',\n    text: 'Sucursales',\n    url: '/settings/venues/'\n  });\n}\n\nif (hasPermission(window.user, 'viewVenue')) {\n  settingItems.push({\n    id: '10.9',\n    icon: 'fa-circle-o',\n    text: 'Regiones',\n    url: '/settings/regions/'\n  });\n}\n\n\nif (hasPermission(window.user, 'viewCarrier')) {\n  settingItems.push({\n    id: '10.6',\n    icon: 'fa-circle-o',\n    text: 'Transportistas',\n    url: '/settings/carriers/'\n  });\n}\n\nif (hasPermission(window.user, 'viewUser')) {\n  settingItems.push({\n    id: '10.5',\n    icon: 'fa-circle-o',\n    text: 'Usuarios',\n    url: '/settings/users/'\n  });\n}\n\nif (hasPermission(window.user, 'viewVersion')) {\n  settingItems.push({\n    id: '10.7',\n    icon: 'fa-circle-o',\n    text: 'Versiones',\n    url: '/settings/versions/'\n  });\n}\n\nif (hasPermission(window.user, 'viewBilling')) {\n  settingItems.push({\n    id: '10.8',\n    icon: 'fa-circle-o',\n    text: 'Billing',\n    url: '/settings/billing/'\n  });\n}\n\nif (hasPermission(window.user, 'viewColor')) {\n  settingItems.push({\n    id: '10.10',\n    icon: 'fa-circle-o',\n    text: 'Colores',\n    url: '/settings/colors/'\n  });\n}\n\nif (hasPermission(window.user, 'viewStatsDashboard')) {\n  settingItems.push({\n    id: '10.11',\n    icon: 'fa-circle-o',\n    text: 'Estádisticas',\n    url: '/settings/stats/'\n  });\n}\n\nif (settingItems.length) {\n  menus.push({\n    id: '10',\n    text: 'Configuración',\n    icon: 'fa-cog',\n    url: settingItems[0].url,\n    items: settingItems\n  });\n}\n\n/* *****************\n* 3. Planning\n*****************/\nconst accountItems = [{\n  id: '100.1',\n  icon: 'fa-circle-o',\n  text: 'Información',\n  url: '/my-account/'\n}];\n\nif (process.env.NODE_ENV === 'development' && accountItems.length) {\n  menus.push({\n    id: '100',\n    text: 'Mi Cuenta',\n    icon: 'fa-user',\n    url: '/my-account/',\n    items: planningItems\n  });\n}\n\nexport default menus;\n","import {\n  AxiosError,\n  AxiosResponse,\n  CancelTokenSource,\n  default as Axios\n} from 'axios';\nimport {\n  Dispatch\n} from 'redux';\nimport * as swal from 'sweetalert';\nimport {\n  IBaseCarrier,\n  ICarrier\n} from '../../../../../src/app/interfaces/carrier.interface';\nimport ApiService from '../utils/axios';\nimport {showModal, statusFooterButttonsModal} from '../utils/common';\n\nexport interface ICarriersState {\n  carriers: ICarrier[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  tempCarrier: IBaseCarrier;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface ICancelRequest {\n  type: '/CARRIERS/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/CARRIERS/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/CARRIERS/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/CARRIERS/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IChangePage {\n  type: '/CARRIERS/CHANGE_PAGE';\n  payload: {\n    page: number;\n  };\n}\n\nexport function changePageAction(page: number): IChangePage {\n  return {\n    type: '/CARRIERS/CHANGE_PAGE',\n    payload: {\n      page\n    }\n  };\n}\n\ninterface IChangeTempCarrier {\n  type: '/CARRIERS/CHANGE_TEMP_CARRIER';\n  payload: {\n    carrier: IBaseCarrier;\n  };\n  meta: {\n    debounce: {\n      time: number\n    }\n  };\n}\n\nexport function changeTempCarrierAction(carrier: IBaseCarrier, delay?: boolean): IChangeTempCarrier {\n  return {\n    type: '/CARRIERS/CHANGE_TEMP_CARRIER',\n    payload: {\n      carrier\n    },\n    meta: {\n      debounce: {\n        time: delay ? 300 : 0\n      }\n    }\n  };\n}\n\ninterface ILoadCarriers {\n  type: '/CARRIERS/LOAD_CARRIERS';\n  payload: {\n    carriers: any;\n    count: number;\n    pages: number\n  };\n}\n\nexport function loadCarriersAction(carriers: any, count: number, pages: number): ILoadCarriers {\n  return {\n    type: '/CARRIERS/LOAD_CARRIERS',\n    payload: {\n      carriers,\n      count,\n      pages\n    }\n  };\n}\n\nexport function getCarriersAction(nextPage: number) {\n  return (dispatch: Dispatch<CarrierReduxAction>, getState: () => { carriers: ICarriersState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n\n    if (nextPage && nextPage !== state.carriers.pagination.page) {\n      dispatch(isLoadingAction(true));\n    }\n    dispatch(cancelRequestAction(api.getSource()));\n    const page = nextPage ? nextPage : state.carriers.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n    api.getCarriers(page)\n      .then((response: AxiosResponse) => {\n        dispatch(loadCarriersAction(response.data.results, response.data.count, response.data.pages));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\nexport function createCarrierAction() {\n  return (dispatch: Dispatch<CarrierReduxAction>, getState: () => {carriers: ICarriersState}) => {\n    dispatch(isLoadingAction(true));\n    const state = getState();\n    const {tempCarrier} = state.carriers;\n    const api: ApiService = new ApiService();\n    api.createCarrier(tempCarrier)\n      .then((response: AxiosResponse) => {\n        dispatch(getCarriersAction(state.carriers.pagination.page) as any);\n        statusFooterButttonsModal(false);\n        showModal(false);\n        swal(response.data.message, {\n          icon: 'success'\n        });\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function updateCarrierAction() {\n  return (dispatch: Dispatch<CarrierReduxAction>, getState: () => {carriers: ICarriersState}) => {\n    const state = getState();\n    const {tempCarrier} = state.carriers;\n    const $carrier = $(`#carrier-${tempCarrier._id}`);\n    const api: ApiService = new ApiService();\n    api.updateCarrier(tempCarrier)\n      .then((response: AxiosResponse) => {\n        $carrier.addClass('editing-item');\n        dispatch(getCarriersAction(state.carriers.pagination.page) as any);\n        statusFooterButttonsModal(false);\n        showModal(false);\n        swal(response.data.message, {\n          icon: 'success'\n        });\n        setTimeout(() => {\n          $carrier.removeClass('editing-item');\n        }, 1000);\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function deleteCarrierAction(id: string) {\n  return (dispatch: Dispatch<CarrierReduxAction>, getState: () => {carriers: ICarriersState}) => {\n    const state = getState();\n    const api: ApiService = new ApiService();\n    api.deleteCarrier(id)\n      .then((response: AxiosResponse): void => {\n        // effect when removing user\n        swal(response.data.message, {\n          icon: 'success'\n        });\n        $(`#carrier-${id}`).addClass('deleted-item');\n        setTimeout(() => {\n          dispatch(getCarriersAction(state.carriers.pagination.page) as any);\n        }, 500);\n      })\n      .catch((err: AxiosError): void => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport type CarrierReduxAction =\n  ICancelRequest |\n  IIsLoading |\n  IChangeTempCarrier |\n  ILoadCarriers |\n  IChangePage;\n","import { CancelTokenSource } from 'axios';\nimport { ISalesChannel } from '../../../../../src/request/interfaces/salesChannel.interface';\n\nexport const REQUEST_CANCEL_CHANNEL = '/REQUEST/CANCEL_CHANNEL';\nexport const REQUEST_IS_LOADING = '/REQUEST/IS_LOADING';\nexport const REQUEST_LOAD_CHANNEL = '/REQUEST/LOAD_CHANNEL';\nexport const REQUEST_CREATE_CHANNEL = '/REQUEST/CREATE_CHANNEL';\nexport const REQUEST_UDPATE_CHANNEL = '/REQUEST/UDPATE_CHANNEL';\nexport const REQUEST_DELETE_CHANNEL = '/REQUEST/DELETE_CHANNEL';\nexport const REQUEST_CHANGE_ORDER = '/REQUEST/CHANGE_ORDER';\n\nexport interface ISalesChannelState {\n  channels: ISalesChannel[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  options: {\n    orderBy: string;\n    orderType: string;\n  };\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\nexport interface ICancelRequestChannel {\n  type: typeof REQUEST_CANCEL_CHANNEL;\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport interface IIsLoadingRequestChannel {\n  type: typeof REQUEST_IS_LOADING;\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport interface ILoadRequestChannel {\n  type: typeof REQUEST_LOAD_CHANNEL;\n  payload: {\n    channels: ISalesChannel[];\n    count: number;\n    pages: number\n    page: number\n  };\n}\n\nexport interface ICreateRequestChannel {\n  type: typeof REQUEST_CREATE_CHANNEL;\n  payload: {\n    reason: ISalesChannel\n  };\n}\n\nexport interface IUpdateRequestChannel {\n  type: typeof REQUEST_UDPATE_CHANNEL;\n  payload: {\n    reason: ISalesChannel\n  };\n}\n\nexport interface IDeleteRequestChannel {\n  type: typeof REQUEST_DELETE_CHANNEL;\n  payload: {\n    reason: ISalesChannel\n  };\n}\n\nexport interface IChangeOrderRequestChannel {\n  type: typeof REQUEST_CHANGE_ORDER;\n  payload: {\n    orderBy: string;\n    orderType: string;\n  };\n}\n\nexport type RequestChannelReduxActions =\n  ICancelRequestChannel |\n  IIsLoadingRequestChannel |\n  ICreateRequestChannel |\n  IUpdateRequestChannel |\n  IDeleteRequestChannel |\n  IChangeOrderRequestChannel |\n  ILoadRequestChannel;\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { Field, InjectedFormProps, reduxForm } from 'redux-form';\nimport InputField from '../Utils/forms/InputField';\nimport { inputStringRequired } from '../Utils/forms/validations';\nimport { ISalesChannelState } from '../../actions/requestChannel.types';\n\ninterface IPropsType extends InjectedFormProps {\n  update: boolean;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass Form extends React.Component<IPropsType, IStateType> {\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n  public render(): React.ReactElement<IPropsType> {\n    const { handleSubmit, valid , submitFailed} = this.props;\n    return (\n      <form onSubmit={handleSubmit}>\n        <div className=\"row\">\n          <div className=\"col-md-12\">\n            <Field\n              name=\"name\"\n              label=\"Nombre *\"\n              placeholder=\"Nombre\"\n              type=\"text\"\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>\n          {\n            submitFailed && !valid &&\n            <div className=\"col-md-12\">\n              <div\n                className=\"alert alert-danger\"\n                style={{marginTop: '20px'}}\n              >\n                Todos los campos con * son obligatorios\n              </div>\n            </div>\n          }\n        </div>\n      </form>\n    );\n  }\n}\n\nconst ChannelForm = reduxForm({\n  form: 'channelForm'\n})(Form);\n\nconst mapStateToProps = (state: { requestChannel: ISalesChannelState }) => {\n  return {\n    requestChannel: state.requestChannel\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{ requestChannel: ISalesChannelState }, { dispatch: any }, IPropsType | {}>(mapStateToProps, mapDispatchToProps)(ChannelForm);\n","import { CancelTokenSource } from 'axios';\nimport { IPaymentMethod } from '../../../../../src/request/interfaces/paymentMethod.interface';\n\nexport const PAYMENT_METHOD_CANCEL = '/PAYMENT_METHOD/CANCEL';\nexport const PAYMENT_METHOD_IS_LOADING = '/PAYMENT_METHOD/IS_LOADING';\nexport const PAYMENT_METHOD_LOAD = '/PAYMENT_METHOD/LOAD';\nexport const PAYMENT_METHOD_CREATE = '/PAYMENT_METHOD/CREATE';\nexport const PAYMENT_METHOD_UDPATE = '/PAYMENT_METHOD/UDPATE';\nexport const PAYMENT_METHOD_DELETE = '/PAYMENT_METHOD/DELETE';\nexport const PAYMENT_METHOD_CHANGE_ORDER = '/PAYMENT_METHOD/CHANGE_ORDER';\n\nexport interface IPaymentMethodState {\n  paymentMethods: IPaymentMethod[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  options: {\n    orderBy: string;\n    orderType: string;\n  };\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\nexport interface ICancelPaymentMethod {\n  type: typeof PAYMENT_METHOD_CANCEL;\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport interface IIsLoadingPaymentMethod {\n  type: typeof PAYMENT_METHOD_IS_LOADING;\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport interface ILoadPaymentMethod {\n  type: typeof PAYMENT_METHOD_LOAD;\n  payload: {\n    paymentMethods: IPaymentMethod[];\n    count: number;\n    pages: number\n    page: number\n  };\n}\n\nexport interface ICreatePaymentMethod {\n  type: typeof PAYMENT_METHOD_CREATE;\n  payload: {\n    reason: IPaymentMethod\n  };\n}\n\nexport interface IUpdatePaymentMethod {\n  type: typeof PAYMENT_METHOD_UDPATE;\n  payload: {\n    reason: IPaymentMethod\n  };\n}\n\nexport interface IDeletePaymentMethod {\n  type: typeof PAYMENT_METHOD_DELETE;\n  payload: {\n    reason: IPaymentMethod\n  };\n}\n\nexport interface IChangeOrderPaymentMethod {\n  type: typeof PAYMENT_METHOD_CHANGE_ORDER;\n  payload: {\n    orderBy: string;\n    orderType: string;\n  };\n}\n\nexport type PaymentMethodReduxActions =\n  ICancelPaymentMethod |\n  IIsLoadingPaymentMethod |\n  ICreatePaymentMethod |\n  IUpdatePaymentMethod |\n  IDeletePaymentMethod |\n  IChangeOrderPaymentMethod |\n  ILoadPaymentMethod;\n","import { CancelTokenSource } from 'axios';\nimport { IRequestStatus } from '../../../../../src/request/interfaces/requestStatus.interface';\n\nexport const REQUEST_CANCEL_STATUS = '/REQUEST/CANCEL_STATUS';\nexport const REQUEST_IS_LOADING = '/REQUEST/IS_LOADING';\nexport const REQUEST_LOAD_STATUS = '/REQUEST/LOAD_STATUS';\nexport const REQUEST_CREATE_STATUS = '/REQUEST/CREATE_STATUS';\nexport const REQUEST_UDPATE_STATUS = '/REQUEST/UDPATE_STATUS';\nexport const REQUEST_DELETE_STATUS = '/REQUEST/DELETE_STATUS';\nexport const REQUEST_CHANGE_ORDER = '/REQUEST/CHANGE_ORDER';\n\nexport interface IRequestStatusState {\n  status: IRequestStatus[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  options: {\n    orderBy: string;\n    orderType: string;\n  };\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\nexport interface ICancelRequestStatus {\n  type: typeof REQUEST_CANCEL_STATUS;\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport interface IIsLoadingRequestStatus {\n  type: typeof REQUEST_IS_LOADING;\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport interface ILoadRequestStatus {\n  type: typeof REQUEST_LOAD_STATUS;\n  payload: {\n    status: IRequestStatus[];\n    count: number;\n    pages: number\n    page: number\n  };\n}\n\nexport interface ICreateRequestStatus {\n  type: typeof REQUEST_CREATE_STATUS;\n  payload: {\n    reason: IRequestStatus\n  };\n}\n\nexport interface IUpdateRequestStatus {\n  type: typeof REQUEST_UDPATE_STATUS;\n  payload: {\n    reason: IRequestStatus\n  };\n}\n\nexport interface IDeleteRequestStatus {\n  type: typeof REQUEST_DELETE_STATUS;\n  payload: {\n    reason: IRequestStatus\n  };\n}\n\nexport interface IChangeOrderRequestStatus {\n  type: typeof REQUEST_CHANGE_ORDER;\n  payload: {\n    orderBy: string;\n    orderType: string;\n  };\n}\n\nexport type RequestStatusReduxActions =\n  ICancelRequestStatus |\n  IIsLoadingRequestStatus |\n  ICreateRequestStatus |\n  IUpdateRequestStatus |\n  IDeleteRequestStatus |\n  IChangeOrderRequestStatus |\n  ILoadRequestStatus;\n","import {AxiosError, AxiosResponse, CancelTokenSource, default as Axios} from 'axios';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport {IBaseCompany} from '../../../../../src/app/interfaces/company.interface';\nimport ApiService from '../utils/axios';\nimport {showModal, statusFooterButttonsModal} from '../utils/common';\n\nexport interface ICompaniesState {\n  companies: IBaseCompany[];\n  tempCompany: IBaseCompany;\n  loading: boolean;\n  source: CancelTokenSource | null;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface ICancelRequest {\n  type: '/COMPANIES/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/COMPANIES/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/COMPANIES/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/COMPANIES/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IChangePage {\n  type: '/COMPANIES/CHANGE_PAGE';\n  payload: {\n    page: number;\n  };\n}\n\nexport function changePageAction(page: number): IChangePage {\n  return {\n    type: '/COMPANIES/CHANGE_PAGE',\n    payload: {\n      page\n    }\n  };\n}\n\ninterface IChangeTempCompany {\n  type: '/COMPANIES/CHANGE_TEMP_COMPANY';\n  payload: {\n    company: IBaseCompany;\n  };\n  meta: {\n    debounce: {\n      time: number\n    }\n  };\n}\n\nexport function changeTempCompanyAction(company: IBaseCompany): IChangeTempCompany {\n  return {\n    type: '/COMPANIES/CHANGE_TEMP_COMPANY',\n    payload: {\n      company\n    },\n    meta: {\n      debounce: {\n        time: 300\n      }\n    }\n  };\n}\n\ninterface ILoadCompanies {\n  type: '/COMPANIES/LOAD_COMPANIES';\n  payload: {\n    companies: any;\n    count: number;\n    pages: number\n  };\n}\n\nexport function loadCompaniesAction(companies: any, count: number, pages: number): ILoadCompanies {\n  return {\n    type: '/COMPANIES/LOAD_COMPANIES',\n    payload: {\n      companies,\n      count,\n      pages\n    }\n  };\n}\n\nexport function getCompaniesAction(nextPage: number) {\n  return (dispatch: Dispatch<CompaniesReduxAction>, getState: () => {companies: ICompaniesState}) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n\n    if (nextPage && nextPage !== state.companies.pagination.page) {\n      dispatch(isLoadingAction(true));\n    }\n    dispatch(cancelRequestAction(api.getSource()));\n    const page = nextPage ? nextPage : state.companies.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n    api.getCompanies(page)\n      .then((response: AxiosResponse) => {\n        dispatch(loadCompaniesAction(response.data.results, response.data.count, response.data.pages));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\nexport function createCompanyAction() {\n  return (dispatch: Dispatch<CompaniesReduxAction>, getState: () => {companies: ICompaniesState}) => {\n    const state = getState();\n    const {tempCompany} = state.companies;\n    const api: ApiService = new ApiService();\n    dispatch(isLoadingAction(true));\n    statusFooterButttonsModal(true);\n    api.createCompany(tempCompany)\n      .then((response: AxiosResponse) => {\n        statusFooterButttonsModal(false);\n        showModal(false);\n        dispatch(getCompaniesAction(1) as any);\n        swal(response.data.message, {\n          icon: 'success'\n        });\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\ninterface IChangeCompany {\n  type: '/COMPANIES/CHANGE_COMPANY';\n  payload: {\n    company: IBaseCompany;\n  };\n}\n\nexport function changeCompanyAction(company: IBaseCompany): IChangeCompany {\n  return {\n    type: '/COMPANIES/CHANGE_COMPANY',\n    payload: {\n      company\n    }\n  };\n}\n\nexport function updateCompanyAction() {\n  return (dispatch: Dispatch<CompaniesReduxAction>, getState: () => {companies: ICompaniesState}) => {\n    const state = getState();\n    const {tempCompany} = state.companies;\n    statusFooterButttonsModal(true);\n    const $company = $(`#company-${tempCompany._id}`);\n    const api: ApiService = new ApiService();\n    api.updateCompany(tempCompany)\n      .then((response: AxiosResponse) => {\n        statusFooterButttonsModal(false);\n        showModal(false);\n        dispatch(changeCompanyAction(response.data.company));\n        $company.addClass('editing-item');\n        swal(response.data.message, {\n          icon: 'success'\n        });\n        setTimeout(() => {\n          $company.removeClass('editing-item');\n        }, 1000);\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n        $company.removeClass('editing-item');\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\ninterface IDeleteCompany {\n  type: '/COMPANIES/DELETE_COMPANY';\n  payload: {\n    id: string;\n  };\n}\n\nexport function processDeleteCompanyAction(id: string): IDeleteCompany {\n  return {\n    type: '/COMPANIES/DELETE_COMPANY',\n    payload: {\n      id\n    }\n  };\n}\n\nexport function deleteCompanyAction(id: string) {\n  return (dispatch: Dispatch<CompaniesReduxAction>) => {\n    const api: ApiService = new ApiService();\n    api.deleteCompany(id)\n      .then((response: AxiosResponse): void => {\n        // effect when removing user\n        swal(response.data.message, {\n          icon: 'success'\n        });\n        $(`#company-${id}`)\n          .addClass('deleted-item');\n        setTimeout(() => {\n          dispatch(processDeleteCompanyAction(id));\n        }, 500);\n      })\n      .catch((err: AxiosError): void => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport type CompaniesReduxAction =\n  ICancelRequest |\n  IIsLoading |\n  IChangePage |\n  ILoadCompanies |\n  IChangeTempCompany |\n  IChangeCompany |\n  IDeleteCompany;\n","import * as React from 'react';\nimport { createRef, RefObject } from 'react';\n\ninterface IPropsType {\n  options: daterangepicker.Options,\n  startDate: Date,\n  endDate: Date,\n  onChange: (from: Date, to: Date) => void,\n}\n\ninterface IStateType {\n  from: Date,\n  to: Date\n}\n\nclass DateRangeInput extends React.Component<IPropsType, IStateType> {\n\n  readonly state: IStateType = {\n    from: this.props.startDate,\n    to: this.props.startDate\n  };\n  pickerRef: RefObject<HTMLInputElement> = createRef();\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.onChange = this.onChange.bind(this);\n  }\n\n  componentDidMount(): void {\n    const { options, startDate, endDate } = this.props;\n    $(this.pickerRef.current!).daterangepicker({ ...options, startDate, endDate }, (from: any, to: any) => {\n      this.onChange(from, to);\n    });\n  }\n\n  onChange = (from: Date, to: Date) => {\n    this.setState({\n      from,\n      to\n    }, () => {\n      this.props.onChange(from, to);\n    });\n  };\n\n  render() {\n    return <div className='input-group input-group-sm' style={{ padding: '10px 5px' }}>\n      <input type='text' className='form-control input-sm' ref={this.pickerRef} />\n      <div className='input-group-btn'>\n        <button className='btn btn-default' onClick={() => {\n          ($(this.pickerRef.current!) as any).click();\n        }}>\n          <i className='fa fa-calendar' /></button>\n      </div>\n    </div>;\n  }\n\n}\n\nexport default DateRangeInput;\n","import {AxiosError, AxiosResponse, CancelTokenSource, default as Axios} from 'axios';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport {\n  IInventoryLabel\n} from '../../../../../src/inventory/interfaces/inventoryLabel.interface';\nimport {IInventorySetting} from '../../../../../src/app/interfaces/teamSetting.interface';\nimport ApiService from '../utils/axios';\nimport {showModal, statusFooterButttonsModal} from '../utils/common';\n\nexport interface ILabelsState {\n  labels: IInventoryLabel[];\n  inventorySettings: IInventorySetting;\n  loading: boolean;\n  tempLabel: IInventoryLabel;\n  source: CancelTokenSource | null;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface ICancelRequest {\n  type: '/LABELS/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/LABELS/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/LABELS/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/LABELS/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IChangePage {\n  type: '/LABELS/CHANGE_PAGE';\n  payload: {\n    page: number;\n  };\n}\n\nexport function changePageAction(page: number): IChangePage {\n  return {\n    type: '/LABELS/CHANGE_PAGE',\n    payload: {\n      page\n    }\n  };\n}\n\ninterface IChangeTempLabel {\n  type: '/LABELS/CHANGE_TEMP_LABEL';\n  payload: {\n    tempLabel: IInventoryLabel;\n  };\n  meta: {\n    debounce: {\n      time: number\n    }\n  };\n}\n\nexport function changeTempLabelAction(tempLabel: IInventoryLabel, debounce?: number): IChangeTempLabel {\n  return {\n    type: '/LABELS/CHANGE_TEMP_LABEL',\n    payload: {\n      tempLabel\n    },\n    meta: {\n      debounce: {\n        time: debounce ? debounce : 0\n      }\n    }\n  };\n}\n\ninterface ICreateLabel {\n  type: '/LABELS/CREATE_LABEL';\n  payload: {\n    label: IInventoryLabel;\n  };\n}\n\nexport function createLabel(label: IInventoryLabel): ICreateLabel {\n  return {\n    type: '/LABELS/CREATE_LABEL',\n    payload: {\n      label\n    }\n  };\n}\n\nexport function createLabelAction(label: IInventoryLabel) {\n  return (dispatch: Dispatch<LabelsReduxAction>) => {\n    const api: ApiService = new ApiService();\n    api.createLabel(label)\n      .then((response: AxiosResponse) => {\n        showModal(false);\n        dispatch(createLabel(response.data.label));\n        statusFooterButttonsModal(false);\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n        const $label = $(`#label-${response.data.label._id}`);\n        $label.addClass('editing-item');\n        setTimeout(() => {\n          $label.removeClass('editing-item');\n        }, 1000);\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\ninterface ILoadLabels {\n  type: '/LABELS/LOAD_LABELS';\n  payload: {\n    labels: any;\n    inventorySettings: IInventorySetting;\n    count: number;\n    pages: number\n  };\n}\n\nexport function loadLabelsAction(labels: any, inventorySettings: IInventorySetting, count: number, pages: number): ILoadLabels {\n  return {\n    type: '/LABELS/LOAD_LABELS',\n    payload: {\n      labels,\n      inventorySettings,\n      count,\n      pages\n    }\n  };\n}\n\nexport function getLabelsAction(nextPage: number) {\n  return (dispatch: Dispatch<LabelsReduxAction>, getState: () => {labels: ILabelsState}) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    if (nextPage && nextPage !== state.labels.pagination.page) {\n      dispatch(isLoadingAction(true));\n    }\n    dispatch(cancelRequestAction(api.getSource()));\n    const page = nextPage ? nextPage : state.labels.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n    api.getLabels(page)\n      .then((response: AxiosResponse) => {\n        dispatch(loadLabelsAction(response.data.results, response.data.inventorySettings, response.data.count, response.data.pages));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\ninterface IChangeLabel {\n  type: '/LABELS/CHANGE_LABEL';\n  payload: {\n    label: IInventoryLabel;\n  };\n}\n\nexport function changeLabel(label: IInventoryLabel): IChangeLabel {\n  return {\n    type: '/LABELS/CHANGE_LABEL',\n    payload: {\n      label\n    }\n  };\n}\n\nexport function changeLabelAction(label: IInventoryLabel, message?: boolean) {\n  return (dispatch: Dispatch<LabelsReduxAction>) => {\n    const api: ApiService = new ApiService();\n    api.updateLabel(label)\n      .then((response: AxiosResponse) => {\n        if (message) {\n          statusFooterButttonsModal(false);\n          showModal(false);\n          const $label = $(`#label-${label._id}`);\n          $label.addClass('editing-item');\n          setTimeout(() => {\n            $label.removeClass('editing-item');\n          }, 1000);\n          swal!(response.data.message, {\n            icon: 'success'\n          });\n        }\n        dispatch(changeLabel(label));\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\ninterface IDeleteLabel {\n  type: '/LABELS/DELETE_LABEL';\n  payload: {\n    id: string;\n  };\n}\n\nexport function processDeleteLabelAction(id: string): IDeleteLabel {\n  return {\n    type: '/LABELS/DELETE_LABEL',\n    payload: {\n      id\n    }\n  };\n}\n\nexport function deleteLabelAction(id: string) {\n  return (dispatch: Dispatch<LabelsReduxAction>) => {\n    const api: ApiService = new ApiService();\n    api.deleteLabel(id)\n      .then((response: AxiosResponse): void => {\n        // effect when removing user\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n        $(`#label-${id}`)\n          .addClass('deleted-item');\n        setTimeout(() => {\n          dispatch(processDeleteLabelAction(id));\n        }, 500);\n      })\n      .catch((err: AxiosError): void => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport type LabelsReduxAction =\n  ICancelRequest |\n  IIsLoading |\n  IChangePage |\n  ILoadLabels |\n  IChangeTempLabel |\n  IChangeLabel |\n  IDeleteLabel |\n  ICreateLabel;\n","import { CancelTokenSource } from 'axios';\nimport { IReason } from '../../../../../src/request/interfaces/reason.interface';\n\nexport const REASON_CANCEL_REASON = '/REASONS/CANCEL_REASON';\nexport const REASON_IS_LOADING = '/REASONS/IS_LOADING';\nexport const REASON_LOAD_REASONS = '/REASONS/LOAD_REASONS';\nexport const REASON_CREATE_REASON = '/REASONS/CREATE_REASON';\nexport const REASON_UDPATE_REASON = '/REASONS/UDPATE_REASON';\nexport const REASON_DELETE_REASON = '/REASONS/DELETE_REASON';\nexport const REASON_CHANGE_ORDER = '/REASONS/CHANGE_ORDER';\n\nexport interface IReasonsState {\n  reasons: IReason[];\n  reason: Partial<IReason> | IReason;\n  loading: boolean;\n  source: CancelTokenSource | null;\n  options: {\n    orderBy: string;\n    orderType: string;\n  };\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\nexport interface ICancelReason {\n  type: typeof REASON_CANCEL_REASON;\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport interface IIsLoadingReason {\n  type: typeof REASON_IS_LOADING;\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport interface ILoadReasons {\n  type: typeof REASON_LOAD_REASONS;\n  payload: {\n    reasons: IReason[];\n    count: number;\n    pages: number\n    page: number\n  };\n}\n\nexport interface ICreateReason {\n  type: typeof REASON_CREATE_REASON;\n  payload: {\n    reason: IReason\n  };\n}\n\nexport interface IUpdateReason {\n  type: typeof REASON_UDPATE_REASON;\n  payload: {\n    reason: IReason\n  };\n}\n\nexport interface IDeleteReason {\n  type: typeof REASON_DELETE_REASON;\n  payload: {\n    reason: IReason\n  };\n}\n\nexport interface IChangeOrderReason {\n  type: typeof REASON_CHANGE_ORDER;\n  payload: {\n    orderBy: string;\n    orderType: string;\n  };\n}\n\nexport type ReasonsReduxActions =\n  ICancelReason |\n  IIsLoadingReason |\n  ICreateReason |\n  IUpdateReason |\n  IDeleteReason |\n  IChangeOrderReason |\n  ILoadReasons;\n","import {\n  AxiosError,\n  AxiosResponse,\n  CancelTokenSource,\n  default as Axios\n} from 'axios';\nimport {\n  Dispatch\n} from 'redux';\nimport * as swal from 'sweetalert';\nimport {\n  IBaseRegion,\n  IRegion\n} from '../../../../../src/app/interfaces/region.interface';\nimport ApiService from '../utils/axios';\nimport {showModal, statusFooterButttonsModal} from '../utils/common';\n\nexport interface IRegionsState {\n  regions: IRegion[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  tempRegion: IBaseRegion;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface ICancelRequest {\n  type: '/REGIONS/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/REGIONS/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/REGIONS/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/REGIONS/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IChangePage {\n  type: '/REGIONS/CHANGE_PAGE';\n  payload: {\n    page: number;\n  };\n}\n\nexport function changePageAction(page: number): IChangePage {\n  return {\n    type: '/REGIONS/CHANGE_PAGE',\n    payload: {\n      page\n    }\n  };\n}\n\ninterface IChangeTempRegion {\n  type: '/REGIONS/CHANGE_TEMP_REGION';\n  payload: {\n    region: IBaseRegion;\n  };\n  meta: {\n    debounce: {\n      time: number\n    }\n  };\n}\n\nexport function changeTempRegionAction(region: IBaseRegion, delay?: boolean): IChangeTempRegion {\n  return {\n    type: '/REGIONS/CHANGE_TEMP_REGION',\n    payload: {\n      region\n    },\n    meta: {\n      debounce: {\n        time: delay ? 300 : 0\n      }\n    }\n  };\n}\n\ninterface ILoadRegion {\n  type: '/REGIONS/LOAD_REGIONS';\n  payload: {\n    regions: any;\n    count: number;\n    pages: number\n  };\n}\n\nexport function loadRegionsAction(regions: any, count: number, pages: number): ILoadRegion {\n  return {\n    type: '/REGIONS/LOAD_REGIONS',\n    payload: {\n      regions,\n      count,\n      pages\n    }\n  };\n}\n\nexport function getRegionsAction(nextPage: number) {\n  return (dispatch: Dispatch<RegionReduxAction>, getState: () => { regions: IRegionsState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n\n    if (nextPage && nextPage !== state.regions.pagination.page) {\n      dispatch(isLoadingAction(true));\n    }\n    dispatch(cancelRequestAction(api.getSource()));\n    const page = nextPage ? nextPage : state.regions.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n    api.getRegions(page)\n      .then((response: AxiosResponse) => {\n        dispatch(loadRegionsAction(response.data.results, response.data.count, response.data.pages));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\nexport function createRegionAction() {\n  return (dispatch: Dispatch<RegionReduxAction>, getState: () => {regions: IRegionsState}) => {\n    dispatch(isLoadingAction(true));\n    const state = getState();\n    const {tempRegion} = state.regions;\n    const api: ApiService = new ApiService();\n    api.createRegion(tempRegion)\n      .then((response: AxiosResponse) => {\n        dispatch(getRegionsAction(state.regions.pagination.page) as any);\n        statusFooterButttonsModal(false);\n        showModal(false);\n        swal(response.data.message, {\n          icon: 'success'\n        });\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function updateRegionAction() {\n  return (dispatch: Dispatch<RegionReduxAction>, getState: () => {regions: IRegionsState}) => {\n    const state = getState();\n    const {tempRegion} = state.regions;\n    const $region = $(`#region-${tempRegion._id}`);\n    const api: ApiService = new ApiService();\n    api.updateRegion(tempRegion)\n      .then((response: AxiosResponse) => {\n        $region.addClass('editing-item');\n        dispatch(getRegionsAction(state.regions.pagination.page) as any);\n        statusFooterButttonsModal(false);\n        showModal(false);\n        swal(response.data.message, {\n          icon: 'success'\n        });\n        setTimeout(() => {\n          $region.removeClass('editing-item');\n        }, 1000);\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function deleteRegionAction(id: string) {\n  return (dispatch: Dispatch<RegionReduxAction>, getState: () => {regions: IRegionsState}) => {\n    const state = getState();\n    const api: ApiService = new ApiService();\n    api.deleteRegion(id)\n      .then((response: AxiosResponse): void => {\n        // effect when removing user\n        swal(response.data.message, {\n          icon: 'success'\n        });\n        $(`#region-${id}`).addClass('deleted-item');\n        setTimeout(() => {\n          dispatch(getRegionsAction(state.regions.pagination.page) as any);\n        }, 500);\n      })\n      .catch((err: AxiosError): void => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport type RegionReduxAction =\n  ICancelRequest |\n  IIsLoading |\n  IChangeTempRegion |\n  ILoadRegion |\n  IChangePage;\n","import { CancelTokenSource } from 'axios';\nimport { ICarrier } from '../../../../../src/app/interfaces/carrier.interface';\nimport { IReason } from '../../../../../src/request/interfaces/reason.interface';\nimport { IRequest } from '../../../../../src/request/interfaces/request.interface';\nimport { IRequestItem } from '../../../../../src/request/interfaces/requestItem.interface';\nimport { IRequestItemStatus } from '../../../../../src/request/interfaces/requestItemStatus.interface';\nimport { IRequestSetting } from '../../../../../src/app/interfaces/teamSetting.interface';\n\nexport const REQUEST_CANCEL_REQUEST = '/REQUESTS/CANCEL_REQUEST';\nexport const REQUEST_IS_LOADING = '/REQUESTS/IS_LOADING';\nexport const REQUEST_LOAD_SETTINGS = '/REQUESTS/REQUEST_LOAD_SETTINGS';\nexport const REQUEST_LOAD_REASONS = '/REQUESTS/LOAD_REASONS';\nexport const REQUEST_LOAD_REQUEST_ITEM_STATUS = '/REQUESTS/LOAD_REQUEST_ITEM_STATUS';\nexport const REQUEST_LOAD_CARRIERS = '/REQUESTS/LOAD_CARRIERS';\nexport const REQUEST_LOAD_REQUESTS = '/REQUESTS/LOAD_REQUESTS';\nexport const REQUEST_LOAD_REQUEST = '/REQUESTS/LOAD_REQUEST';\nexport const REQUEST_CREATE_REQUEST_ITEM_IN_LIST = '/REQUESTS/CREATE_REQUEST_ITEM_IN_LIST';\nexport const REQUEST_UDPATE_REQUEST_ITEM_IN_LIST = '/REQUESTS/UDPATE_REQUEST_ITEM_IN_LIST';\nexport const REQUEST_DELETE_REQUEST_ITEM_IN_LIST = '/REQUESTS/DELETE_REQUEST_ITEM_IN_LIST';\nexport const REQUEST_UDPATE_REQUEST_ITEM_IN_DETAIL = '/REQUESTS/UDPATE_REQUEST_ITEM_IN_DETAIL';\nexport const REQUEST_DELETE_REQUEST_ITEM_IN_DETAIL = '/REQUESTS/DELETE_REQUEST_ITEM_IN_DETAIL';\nexport const REQUEST_CREATE_REQUEST_ITEM_IN_DETAIL = '/REQUESTS/CREATE_REQUEST_ITEM_IN_DETAIL';\nexport const REQUEST_DELETE_REQUEST_IN_LIST = '/REQUESTS/DELETE_REQUEST_IN_LIST';\nexport const REQUEST_TAB_STATUS = '/REQUESTS/TAB_STATUS';\nexport const REQUEST_LOAD_ITEMS = '/REQUESTS/LOAD_ITEMS';\nexport const REQUEST_CHANGE_ORDER = '/REQUESTS/CHANGE_ORDER';\n\nexport interface IRequestsState {\n  requests: IRequest[];\n  requestItems: IRequestItem[];\n  reasons: IReason[];\n  carriers: ICarrier[];\n  requestOpen: string[];\n  requestItemsById: any;\n  requestItemStatus: IRequestItemStatus[];\n  requestItemStatusMin: number;\n  requestItemStatusMax: number;\n  request: Partial<IRequest> | IRequest;\n  loading: boolean;\n  source: CancelTokenSource | null;\n  requestSettings: IRequestSetting;\n  options: {\n    orderBy: string;\n    orderType: string;\n  };\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\nexport interface ICancelRequest {\n  type: typeof REQUEST_CANCEL_REQUEST;\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport interface IIsLoadingRequest {\n  type: typeof REQUEST_IS_LOADING;\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport interface ILoadReasonsRequest {\n  type: typeof REQUEST_LOAD_REASONS;\n  payload: {\n    reasons: IReason[];\n  };\n}\n\nexport interface ILoadRequestItemStatus {\n  type: typeof REQUEST_LOAD_REQUEST_ITEM_STATUS;\n  payload: {\n    requestItemStatus: IRequestItemStatus[];\n    min: number;\n    max: number;\n  };\n}\n\nexport interface ILoadSettingsRequest {\n  type: typeof REQUEST_LOAD_SETTINGS;\n  payload: {\n    requestSettings: IRequestSetting;\n  };\n}\n\nexport interface ILoadCarriersRequest {\n  type: typeof REQUEST_LOAD_CARRIERS;\n  payload: {\n    carriers: ICarrier[];\n  };\n}\n\nexport interface ILoadRequests {\n  type: typeof REQUEST_LOAD_REQUESTS;\n  payload: {\n    requests: IRequest[];\n    count: number;\n    pages: number\n    page: number\n  };\n}\n\nexport interface ICreateRequestItemInList {\n  type: typeof REQUEST_CREATE_REQUEST_ITEM_IN_LIST;\n  payload: {\n    idRequest: string;\n    item: IRequestItem\n  };\n}\n\nexport interface IUpdateRequestItemInList {\n  type: typeof REQUEST_UDPATE_REQUEST_ITEM_IN_LIST;\n  payload: {\n    request: string;\n    item: IRequestItem\n  };\n}\n\nexport interface IDeleteRequestItemInList {\n  type: typeof REQUEST_DELETE_REQUEST_ITEM_IN_LIST;\n  payload: {\n    idRequest: string;\n    item: IRequestItem\n  };\n}\n\nexport interface IUpdateRequestItemInDetail {\n  type: typeof REQUEST_UDPATE_REQUEST_ITEM_IN_DETAIL;\n  payload: {\n    item: IRequestItem\n  };\n}\n\nexport interface ICreateRequestItemInDetail {\n  type: typeof REQUEST_CREATE_REQUEST_ITEM_IN_DETAIL;\n  payload: {\n    item: IRequestItem\n  };\n}\n\nexport interface IDeleteRequestItemInDetail {\n  type: typeof REQUEST_DELETE_REQUEST_ITEM_IN_DETAIL;\n  payload: {\n    item: IRequestItem\n  };\n}\n\nexport interface IDeleteRequestInList {\n  type: typeof REQUEST_DELETE_REQUEST_IN_LIST;\n  payload: {\n    id: string;\n  };\n}\n\nexport interface ILoadRequest {\n  type: typeof REQUEST_LOAD_REQUEST;\n  payload: {\n    request: IRequest;\n  };\n}\n\nexport interface ITabStatusRequest {\n  type: typeof REQUEST_TAB_STATUS;\n  payload: {\n    request: string;\n  };\n}\n\nexport interface ILoadItemsRequest {\n  type: typeof REQUEST_LOAD_ITEMS;\n  payload: {\n    request: string;\n    items: any;\n  };\n}\n\nexport interface IChangeOrderRequest {\n  type: typeof REQUEST_CHANGE_ORDER;\n  payload: {\n    orderBy: string;\n    orderType: string;\n  };\n}\n\nexport type RequestsReduxActions =\n  ICancelRequest |\n  IIsLoadingRequest |\n  ILoadRequest |\n  ILoadItemsRequest |\n  ICreateRequestItemInList |\n  IUpdateRequestItemInList |\n  IDeleteRequestItemInList |\n  IDeleteRequestInList |\n  ILoadSettingsRequest |\n  ICreateRequestItemInDetail |\n  IUpdateRequestItemInDetail |\n  IDeleteRequestItemInDetail |\n  ILoadRequestItemStatus |\n  IChangeOrderRequest |\n  ILoadReasonsRequest |\n  ILoadCarriersRequest |\n  ITabStatusRequest |\n  ILoadRequests;\n","import * as React from 'react';\nimport { RefObject } from 'react';\nimport * as Rx from 'rxjs';\nimport { debounceTime, switchMap } from 'rxjs/operators';\nimport { ajax } from 'rxjs/ajax';\nimport { IRequestItem } from '../../../../../../src/request/interfaces';\nimport ApiService from '../../utils/axios';\nimport { AxiosError, AxiosResponse } from 'axios';\nimport { parseReplicableURL } from '../../utils/common';\nimport ShowIf from './ShowIf';\n\ninterface IPropsType {\n  defaultValue: string;\n  inputClass?: string;\n  item: IRequestItem;\n\n  renderItem(item: any, index: any): React.ReactElement<any>;\n}\n\ninterface IStateType {\n  error: Error | null;\n  open: boolean;\n  canEdit: boolean;\n  value: string;\n  VINRecommends: any[];\n}\n\nclass AutoCompleteVinInput extends React.Component<IPropsType, IStateType> {\n  readonly $subjectVINRecommends = new Rx.Subject<any>();\n  readonly api: ApiService;\n  readonly autocompleteElement: RefObject<HTMLInputElement>;\n  readonly items: RefObject<HTMLInputElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.changeOpen = this.changeOpen.bind(this);\n    this.close = this.close.bind(this);\n    this.outsideClick = this.outsideClick.bind(this);\n    this.renderItem = this.renderItem.bind(this);\n    this.searchVin = this.searchVin.bind(this);\n    this.updateVin = this.updateVin.bind(this);\n    this.openVehicle = this.openVehicle.bind(this);\n    this.autocompleteElement = React.createRef();\n    this.api = new ApiService();\n    this.items = React.createRef();\n    this.state = {\n      error: null,\n      open: false,\n      value: this.props.defaultValue,\n      canEdit: false,\n      VINRecommends: []\n    };\n    this.$subjectVINRecommends.pipe(\n      debounceTime(300),\n      switchMap(({ vin, material }: { vin: string, material: string }) => {\n        return ajax({\n          url: `/api/v1/requests/search-vin/?vin=${vin}&material=${material}`,\n          headers: {\n            'Content-Type': 'application/json;charset=UTF-8'\n          },\n          method: 'GET'\n        });\n      })\n    ).subscribe((response) => {\n      this.setState({\n        VINRecommends: response.response.data\n      });\n    });\n  }\n\n  public componentWillReceiveProps(nextProps: Readonly<IPropsType>, nextContext: any) {\n    if (nextProps.defaultValue !== this.props.defaultValue) {\n      this.setState({\n        value: nextProps.defaultValue\n      });\n    }\n  }\n\n  public componentDidMount(): void {\n    document.addEventListener('keydown', this.close, true);\n    document.addEventListener('click', this.outsideClick, true);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { defaultValue, inputClass, item } = this.props;\n    const { VINRecommends, canEdit, value } = this.state;\n    return (\n      <div className='autocomplete' ref={this.autocompleteElement}>\n        <div\n          className='input-group input-group-sm'\n        >\n          {\n            !canEdit ?\n              <ShowIf condition={item.car.vin?.length > 0}>\n              <span\n                className='input-group-addon pointer'\n                style={{ padding: '5px' }}\n                onClick={this.openVehicle}\n              >\n                <i className='fa fa-fw fa-external-link-square' />\n              </span>\n              </ShowIf>\n              : <span\n                className='input-group-addon pointer bg-red'\n                style={{ padding: '5px' }}\n                onClick={() => {\n                  this.setState({\n                    value: defaultValue || '',\n                    canEdit: false\n                  });\n                }}\n              >\n                <i className='fa fa-fw fa-close' />\n              </span>\n          }\n          <input\n            type='text'\n            className={`form-control ${inputClass ? inputClass : ''}`}\n            onChange={(e) => {\n              const { value } = e.target;\n              if (this.items.current) {\n                this.items.current.scrollTop = 0;\n              }\n              this.setState({\n                open: true,\n                value\n              });\n              this.searchVin(value, item.car.material);\n            }}\n            style={{ padding: '5px' }}\n            disabled={!canEdit}\n            value={value}\n            onClick={this.changeOpen}\n            autoComplete={'off'}\n          />\n          <div\n            className={`input-group-addon pointer ${canEdit ? 'bg-green' : ''}`}\n            onClick={() => {\n              if (canEdit) {\n                this.updateVin(value);\n              } else {\n                this.setState({\n                  canEdit: true\n                });\n              }\n            }}\n          >\n            <i className={`fa ${canEdit ? 'fa fa-save' : 'fa fa-pencil'}`} />\n          </div>\n        </div>\n        {\n          this.state.open ?\n            <div className='items' ref={this.items}>\n              {\n                VINRecommends.map((item, index) => (\n                  this.renderItem(item, index)\n                ))\n              }\n            </div>\n            : null\n        }\n      </div>\n    );\n  }\n\n  private renderItem(item: any, index: any) {\n    const element = this.props.renderItem(item, index);\n    return React.cloneElement(element, {\n      onClick: () => {\n        this.setState({\n          value: item.vin\n        });\n        this.changeOpen();\n      }\n    });\n  }\n\n  public componentWillUnmount(): void {\n    document.removeEventListener('keydown', this.close, true);\n    document.removeEventListener('click', this.outsideClick, true);\n  }\n\n  private close(e: any): void {\n    if (e.key === 'Escape' || e.key === 'Esc' || e.keyCode === 27) {\n      e.preventDefault();\n      this.setState({\n        open: false\n      });\n    }\n  }\n\n  private updateVin(vin: string) {\n    const { item } = this.props;\n    this.api.uppdateRequestItemVin(item, vin)\n      .then((response: AxiosResponse) => {\n        console.log('responde', response);\n        this.setState({\n          canEdit: false\n        });\n        // transmittalActions.updateTransmittalAction(response.data.data);\n      })\n      .catch((err: AxiosError) => {\n        this.api.errorHandler(err);\n      });\n  }\n\n  openVehicle() {\n    const { item } = this.props;\n    window.open(parseReplicableURL(`/settings/cars/${item.car._id}/`), '_blank');\n  }\n\n\n  private searchVin(vin: string, material: string): void {\n    this.$subjectVINRecommends.next({ vin, material });\n  }\n\n  private outsideClick(e: any): void {\n    if (!this.autocompleteElement.current!.contains(e.target)) {\n      this.setState({\n        open: false\n      });\n    }\n  }\n\n  private changeOpen(): void {\n    const { open } = this.state;\n    this.setState({\n      open: !open\n    });\n  }\n}\n\nexport default AutoCompleteVinInput;\n","import Axios, { AxiosError, AxiosResponse, CancelTokenSource } from 'axios';\nimport { Dispatch } from 'redux';\nimport * as Rx from 'rxjs';\nimport { of } from 'rxjs';\nimport { ajax } from 'rxjs/ajax';\nimport { debounceTime, switchMap } from 'rxjs/operators';\nimport { ICarrier } from '../../../../../src/app/interfaces/carrier.interface';\nimport { IReason } from '../../../../../src/request/interfaces/reason.interface';\nimport { IRequestItem } from '../../../../../src/request/interfaces/requestItem.interface';\nimport { IRequestItemStatus } from '../../../../../src/request/interfaces/requestItemStatus.interface';\nimport { IVenue } from '../../../../../src/app/interfaces/venue.interface';\nimport ApiService from '../utils/axios';\nimport {\n  ICancelRequestItems,\n  IChangeFilterRequestItems,\n  IChangeOrderRequestItems,\n  ICreateRequestItems,\n  IDeleteRequestItems,\n  IIsLoadingRequestItems,\n  ILoadCarriersRequestItems,\n  ILoadPropertiesRequestItems,\n  ILoadReasonsRequestItems,\n  ILoadRequestItems,\n  ILoadRequestItemStatus,\n  ILoadSettingsRequestItems,\n  ILoadVenuesRequestItems,\n  IRequestItemsFilters,\n  IRequestItemsState,\n  IUpdateRequestItems,\n  REQUEST_ITEMS_CANCEL_REQUEST,\n  REQUEST_ITEMS_CHANGE_FILTER,\n  REQUEST_ITEMS_CHANGE_ORDER,\n  REQUEST_ITEMS_CREATE_ITEM,\n  REQUEST_ITEMS_DELETE_ITEM,\n  REQUEST_ITEMS_IS_LOADING,\n  REQUEST_ITEMS_LOAD_CARRIERS,\n  REQUEST_ITEMS_LOAD_ITEM_STATUS,\n  REQUEST_ITEMS_LOAD_PROPERTIES,\n  REQUEST_ITEMS_LOAD_REASONS,\n  REQUEST_ITEMS_LOAD_REQUESTS_ITEMS,\n  REQUEST_ITEMS_LOAD_SETTINGS, REQUEST_ITEMS_LOAD_USERS,\n  REQUEST_ITEMS_LOAD_VENUES,\n  REQUEST_ITEMS_UPDATE_ITEM,\n  RequestItemsReduxActions,\n  ILoadUsersRequestItems\n} from './requestItems.types';\nimport { IRequestSetting } from '../../../../../src/app/interfaces/teamSetting.interface';\nimport { IUser } from '../../../../../src/app/interfaces';\n\nexport function cancelRequestItemsAction(source: CancelTokenSource): ICancelRequestItems {\n  return {\n    type: REQUEST_ITEMS_CANCEL_REQUEST,\n    payload: {\n      source\n    }\n  };\n}\n\nexport function isLoadingRequestItemsAction(loading: boolean): IIsLoadingRequestItems {\n  return {\n    type: REQUEST_ITEMS_IS_LOADING,\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function loadReasonsRequestItemsAction(reasons: IReason[]): ILoadReasonsRequestItems {\n  return {\n    type: REQUEST_ITEMS_LOAD_REASONS,\n    payload: {\n      reasons\n    }\n  };\n}\n\n// export function loadCarriersRequestItemsAction(carriers: ICarrier[]): ILoadCarriersRequestItems {\n//   return {\n//     type: REQUEST_ITEMS_LOAD_CARRIERS,\n//     payload: {\n//       carriers\n//     }\n//   };\n// }\n\nexport function loadUsersRequestItemsAction(users: IUser[]): ILoadUsersRequestItems {\n  return {\n    type: REQUEST_ITEMS_LOAD_USERS,\n    payload: {\n      users\n    }\n  };\n}\n\nexport function loadVenuesRequestItemsAction(venues: IVenue[]): ILoadVenuesRequestItems {\n  return {\n    type: REQUEST_ITEMS_LOAD_VENUES,\n    payload: {\n      venues\n    }\n  };\n}\n\nexport function loadPropertiesRequestItemsAction(properties: ICarrier[]): ILoadPropertiesRequestItems {\n  return {\n    type: REQUEST_ITEMS_LOAD_PROPERTIES,\n    payload: {\n      properties\n    }\n  };\n}\n\nexport function loadRequestItemsStatusRequestAction(requestItemStatus: IRequestItemStatus[], min: number, max: number): ILoadRequestItemStatus {\n  return {\n    type: REQUEST_ITEMS_LOAD_ITEM_STATUS,\n    payload: {\n      requestItemStatus,\n      min,\n      max\n    }\n  };\n}\n\nexport function loadRequestsItemsAction(requestItems: IRequestItem[], count: number, pages: number, page: number): ILoadRequestItems {\n  return {\n    type: REQUEST_ITEMS_LOAD_REQUESTS_ITEMS,\n    payload: {\n      requestItems,\n      count,\n      pages,\n      page\n    }\n  };\n}\n\nexport function changeOrderRequestAction(orderBy: string, orderType: string): IChangeOrderRequestItems {\n  return {\n    type: REQUEST_ITEMS_CHANGE_ORDER,\n    payload: {\n      orderBy,\n      orderType\n    }\n  };\n}\n\nexport function changeFilterRequestAction(key: keyof IRequestItemsFilters, value: any | any[]): IChangeFilterRequestItems {\n  return {\n    type: REQUEST_ITEMS_CHANGE_FILTER,\n    payload: {\n      key,\n      value\n    }\n  };\n}\n\nexport function createRequestItemAction(item: IRequestItem): ICreateRequestItems {\n  return {\n    type: REQUEST_ITEMS_CREATE_ITEM,\n    payload: {\n      item\n    }\n  };\n}\n\nexport function updateRequestItemAction(item: IRequestItem): IUpdateRequestItems {\n  return {\n    type: REQUEST_ITEMS_UPDATE_ITEM,\n    payload: {\n      item\n    }\n  };\n}\n\nexport function deleteRequestItemAction(item: IRequestItem): IDeleteRequestItems {\n  return {\n    type: REQUEST_ITEMS_DELETE_ITEM,\n    payload: {\n      item\n    }\n  };\n}\n\nexport function loadRequestSettingsAction(requestSettings: IRequestSetting): ILoadSettingsRequestItems {\n  return {\n    type: REQUEST_ITEMS_LOAD_SETTINGS,\n    payload: {\n      requestSettings\n    }\n  };\n}\n\nexport function getRequestItemsThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) {\n  return (dispatch: Dispatch<RequestItemsReduxActions>, getState: () => { requestItems: IRequestItemsState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(isLoadingRequestItemsAction(!hideLoading));\n    const page = nextPage ? nextPage : state.requestItems.pagination.page;\n    dispatch(changeOrderRequestAction(orderBy, orderType));\n    dispatch(cancelRequestItemsAction(api.getSource()));\n    Axios\n      .all([\n        api.getRequestItems({ page, orderBy, orderType, pageSize: 20, filters: state.requestItems.filters }),\n        api.getReasons({ page: 1, pageSize: 200 }),\n        api.getRequestItemsStatus({ page: 1, pageSize: 200 }),\n        api.getVenues({ page: 1, pageSize: 200, noPopulate: true, filted: true }),\n        api.getUsers(1, \"\", undefined, true, 200),\n        api.getProperties(),\n        api.getTeamSettings()\n      ])\n      .then(Axios.spread((requests, reasons, requestItemStatus/*, carriers*/, venues, users, properties, teamsettings) => {\n        const { data } = requests;\n        dispatch(loadRequestsItemsAction(data.results, data.count, data.pages, page));\n        dispatch(loadReasonsRequestItemsAction(reasons.data.results));\n        dispatch(loadRequestItemsStatusRequestAction(requestItemStatus.data.results, requestItemStatus.data.min, requestItemStatus.data.max));\n        dispatch(loadUsersRequestItemsAction(users.data.results));\n        dispatch(loadVenuesRequestItemsAction(venues.data.results));\n        dispatch(loadPropertiesRequestItemsAction(properties.data));\n        dispatch(isLoadingRequestItemsAction(false));\n        dispatch(loadRequestSettingsAction(teamsettings.data.request));\n      }))\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingRequestItemsAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nconst $updateRequestItem = new Rx.Subject<any>();\n\n$updateRequestItem.pipe(\n  debounceTime(2000),\n  switchMap((item: any) => {\n    return item ? ajax({\n      url: `/api/v1/requests-item/${item._id}/`,\n      headers: {\n        'Content-Type': 'application/json;charset=UTF-8'\n      },\n      method: 'PATCH',\n      body: item\n    }) : of();\n  })\n).subscribe();\nexport function updateRequestItemsThunkAction({ item, debounce }: { item: IRequestItem, debounce?: boolean}) {\n  return (dispatch: Dispatch<RequestItemsReduxActions>) => {\n    dispatch(updateRequestItemAction(item));\n    if (debounce) {\n      // debounceUpdateRequestItem(item);\n      $updateRequestItem.next(item);\n    } else {\n      const api: ApiService = new ApiService();\n      $updateRequestItem.next(null);\n      api.updateRequestItem(item._id, item)\n        // tslint:disable-next-line: no-empty\n        .then((response: AxiosResponse) => {});\n    }\n  };\n}\n\nexport function deleteRequestItemsThunkAction(id: string) {\n  return (dispatch: Dispatch<RequestItemsReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.deleteRequestItem(id)\n      // tslint:disable-next-line: no-empty\n      .then((response: AxiosResponse) => {});\n  };\n}\n","import { CancelTokenSource } from 'axios';\nimport { ICarrier } from '../../../../../src/app/interfaces/carrier.interface';\nimport { IReason } from '../../../../../src/request/interfaces/reason.interface';\nimport { IRequestItem } from '../../../../../src/request/interfaces/requestItem.interface';\nimport { IRequestItemStatus } from '../../../../../src/request/interfaces/requestItemStatus.interface';\nimport { IVenue } from '../../../../../src/app/interfaces/venue.interface';\nimport { IUser } from '../../../../../src/app/interfaces/user.interface';\nimport { IRequestSetting } from '../../../../../src/app/interfaces/teamSetting.interface';\n\nexport const REQUEST_ITEMS_CANCEL_REQUEST = '/REQUESTS_ITEMS/CANCEL_REQUEST';\nexport const REQUEST_ITEMS_IS_LOADING = '/REQUESTS_ITEMS/IS_LOADING';\nexport const REQUEST_ITEMS_LOAD_REASONS = '/REQUESTS_ITEMS/LOAD_REASONS';\nexport const REQUEST_ITEMS_LOAD_CARRIERS = '/REQUESTS_ITEMS/LOAD_CARRIERS';\nexport const REQUEST_ITEMS_LOAD_VENUES = '/REQUESTS_ITEMS/LOAD_VENUES';\nexport const REQUEST_ITEMS_LOAD_USERS = '/REQUESTS_ITEMS/LOAD_USERS';\nexport const REQUEST_ITEMS_LOAD_PROPERTIES = '/REQUESTS_ITEMS/LOAD_PROPERTIES';\nexport const REQUEST_ITEMS_LOAD_REQUESTS_ITEMS = '/REQUESTS_ITEMS/LOAD_REQUESTS_ITEMS';\nexport const REQUEST_ITEMS_LOAD_ITEM_STATUS = '/REQUESTS_ITEMS/LOAD_ITEM_STATUS';\nexport const REQUEST_ITEMS_CHANGE_ORDER = '/REQUESTS_ITEMS/CHANGE_ORDER';\nexport const REQUEST_ITEMS_CHANGE_FILTER = '/REQUESTS_ITEMS/CHANGE_FILTER';\nexport const REQUEST_ITEMS_CREATE_ITEM = '/REQUESTS_ITEMS/CREATE_ITEM';\nexport const REQUEST_ITEMS_UPDATE_ITEM = '/REQUESTS_ITEMS/UPDATE_ITEM';\nexport const REQUEST_ITEMS_DELETE_ITEM = '/REQUESTS_ITEMS/DELETE_ITEM';\nexport const REQUEST_ITEMS_LOAD_SETTINGS = '/REQUESTS_ITEMS/LOAD_SETTINGS';\n\nexport interface IRequestItemsFilters {\n  text: string;\n  sellerText: string;\n  ticket: string;\n  request: string;\n  entry: string;\n  venues: any[];\n  users: any[];\n  properties: any[];\n  status: any[];\n  from: any;\n  to: any;\n}\n\nexport interface IRequestItemsState {\n  requestItems: IRequestItem[];\n  reasons: IReason[];\n  carriers: ICarrier[];\n  properties: ICarrier[];\n  venues: IVenue[];\n  users: IUser[];\n  requestItemStatus: IRequestItemStatus[];\n  requestSettings: IRequestSetting;\n  requestItemStatusMin: number;\n  requestItemStatusMax: number;\n  loading: boolean;\n  source: CancelTokenSource | null;\n  filters: IRequestItemsFilters;\n  options: {\n    orderBy: string;\n    orderType: string;\n  };\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\nexport interface ICancelRequestItems {\n  type: typeof REQUEST_ITEMS_CANCEL_REQUEST;\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport interface IIsLoadingRequestItems {\n  type: typeof REQUEST_ITEMS_IS_LOADING;\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport interface ILoadReasonsRequestItems {\n  type: typeof REQUEST_ITEMS_LOAD_REASONS;\n  payload: {\n    reasons: IReason[];\n  };\n}\n\nexport interface ILoadCarriersRequestItems {\n  type: typeof REQUEST_ITEMS_LOAD_CARRIERS;\n  payload: {\n    carriers: ICarrier[];\n  };\n}\n\nexport interface ILoadUsersRequestItems {\n  type: typeof REQUEST_ITEMS_LOAD_USERS;\n  payload: {\n    users: IUser[];\n  };\n}\n\nexport interface ILoadVenuesRequestItems {\n  type: typeof REQUEST_ITEMS_LOAD_VENUES;\n  payload: {\n    venues: IVenue[];\n  };\n}\n\nexport interface ILoadPropertiesRequestItems {\n  type: typeof REQUEST_ITEMS_LOAD_PROPERTIES;\n  payload: {\n    properties: ICarrier[];\n  };\n}\n\nexport interface ILoadRequestItemStatus {\n  type: typeof REQUEST_ITEMS_LOAD_ITEM_STATUS;\n  payload: {\n    requestItemStatus: IRequestItemStatus[];\n    min: number;\n    max: number;\n  };\n}\n\nexport interface ILoadRequestItems {\n  type: typeof REQUEST_ITEMS_LOAD_REQUESTS_ITEMS;\n  payload: {\n    requestItems: IRequestItem[];\n    count: number;\n    pages: number;\n    page: number;\n  };\n}\n\nexport interface IChangeOrderRequestItems {\n  type: typeof REQUEST_ITEMS_CHANGE_ORDER;\n  payload: {\n    orderBy: string;\n    orderType: string;\n  };\n}\n\nexport interface IChangeFilterRequestItems {\n  type: typeof REQUEST_ITEMS_CHANGE_FILTER;\n  payload: {\n    key: keyof IRequestItemsFilters;\n    value: any | any[];\n  };\n}\n\nexport interface ICreateRequestItems {\n  type: typeof REQUEST_ITEMS_CREATE_ITEM;\n  payload: {\n    item: IRequestItem;\n  };\n}\n\nexport interface IUpdateRequestItems {\n  type: typeof REQUEST_ITEMS_UPDATE_ITEM;\n  payload: {\n    item: IRequestItem;\n  };\n}\n\nexport interface IDeleteRequestItems {\n  type: typeof REQUEST_ITEMS_DELETE_ITEM;\n  payload: {\n    item: IRequestItem;\n  };\n}\n\nexport interface ILoadSettingsRequestItems {\n  type: typeof REQUEST_ITEMS_LOAD_SETTINGS;\n  payload: {\n    requestSettings: IRequestSetting;\n  };\n}\n\nexport type RequestItemsReduxActions =\n  ICancelRequestItems |\n  ILoadReasonsRequestItems |\n  ILoadRequestItemStatus |\n  ILoadRequestItems |\n  ILoadCarriersRequestItems |\n  ILoadUsersRequestItems |\n  ILoadVenuesRequestItems |\n  ILoadPropertiesRequestItems |\n  IChangeOrderRequestItems |\n  IChangeFilterRequestItems |\n  ICreateRequestItems |\n  IUpdateRequestItems |\n  IDeleteRequestItems |\n  ILoadSettingsRequestItems |\n  IIsLoadingRequestItems;\n","import {AxiosError, AxiosResponse, CancelTokenSource} from \"axios\";\nimport {IInventoryCar} from '../../../../../src/inventory/interfaces/inventory.interface';\nimport {Dispatch} from \"redux\";\nimport ApiService from \"../utils/axios\";\nimport {IFilterStock} from \"../reducers/stock.reducer\";\n\nexport interface IStockState {\n  cars: IInventoryCar[];\n  carsTable: any[];\n  filter: IFilterStock;\n  dataFilters: {\n    venues: any[];\n    colors: any[];\n    brands: any[];\n    denominations: any[];\n    types: any[];\n    properties: any[];\n  };\n  vinInStock: any;\n  searching: boolean;\n  message: string;\n  loading: boolean;\n  source: CancelTokenSource | null;\n}\n\ninterface ICancelRequest {\n  type: '/STOCK/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/STOCK/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/STOCK/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/STOCK/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface ILoadStock {\n  type: '/STOCK/LOAD';\n  payload: {\n    cars: IInventoryCar[];\n    message: string;\n  };\n}\n\nexport function loadStockAction(cars: IInventoryCar[], message: string): ILoadStock {\n  return {\n    type: '/STOCK/LOAD',\n    payload: {\n      cars,\n      message\n    }\n  };\n}\n\ninterface IChangeFilter {\n  type: '/STOCK/CHANGE_FILTER';\n  payload: {\n    filter: IFilterStock\n  };\n  meta: {\n    debounce: {\n      time: number\n    }\n  };\n}\n\nexport function changeFilterText(filter: IFilterStock): IChangeFilter {\n  return {\n    type: '/STOCK/CHANGE_FILTER',\n    payload: {\n      filter\n    },\n    meta: {\n      debounce: {\n        time: 300\n      }\n    }\n  };\n}\n\nexport function changeFilter(filter: IFilterStock): IChangeFilter {\n  return {\n    type: '/STOCK/CHANGE_FILTER',\n    payload: {\n      filter\n    },\n    meta: {\n      debounce: {\n        time: 0\n      }\n    }\n  };\n}\n\nexport function getStockAction() {\n  return (dispatch: Dispatch<StockReducerAction>) => {\n    dispatch(isLoadingAction(true));\n    const api: ApiService = new ApiService();\n    dispatch(cancelRequestAction(api.getSource()));\n    api.getStock()\n      .then((response: AxiosResponse) => {\n        dispatch(loadStockAction(response.data.cars, response.data.message));\n        dispatch(isLoadingAction(false));\n        // swal(response.data.message, {\n        //   icon: 'success'\n        // });\n      })\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport type StockReducerAction =\n  ICancelRequest |\n  IChangeFilter |\n  ILoadStock |\n  IIsLoading;\n","import { AxiosError, AxiosResponse, CancelTokenSource, default as Axios } from 'axios';\nimport { Dispatch } from 'redux';\nimport * as swal from 'sweetalert';\nimport { ICarrier } from '../../../../../src/app/interfaces/carrier.interface';\nimport { ICompany } from '../../../../../src/app/interfaces/company.interface';\nimport { IRegion } from '../../../../../src/app/interfaces/region.interface';\nimport { IBaseVenue, IVenue } from '../../../../../src/app/interfaces/venue.interface';\nimport ApiService from '../utils/axios';\nimport { showModal, statusFooterButttonsModal } from '../utils/common';\nimport {IUser} from \"../../../../../src/app/interfaces\";\n\nexport interface IVenuesState {\n  venues: IVenue[];\n  allVenues: IVenue[];\n  companies: ICompany[];\n  regions: IRegion[];\n  carriers: ICarrier[];\n  users: IUser[];\n  loading: boolean;\n  tempVenue: IBaseVenue;\n  source: CancelTokenSource | null;\n  searchText: string;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface ICancelRequest {\n  type: '/VENUES/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/VENUES/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/VENUES/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/VENUES/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IChangePage {\n  type: '/VENUES/CHANGE_PAGE';\n  payload: {\n    page: number;\n  };\n}\n\nexport function changePageAction(page: number): IChangePage {\n  return {\n    type: '/VENUES/CHANGE_PAGE',\n    payload: {\n      page\n    }\n  };\n}\n\ninterface IChangeSearchVenue {\n  type: '/VENUES/CHANGE_SEARCH';\n  payload: {\n    searchText: string;\n  };\n}\n\nexport function changeSearchAction(searchText: string): IChangeSearchVenue {\n  return {\n    type: '/VENUES/CHANGE_SEARCH',\n    payload: {\n      searchText\n    }\n  };\n}\n\n\ninterface IChangeTempVenue {\n  type: '/VENUES/CHANGE_TEMP_VENUE';\n  payload: {\n    venue: IBaseVenue;\n  };\n  meta: {\n    debounce: {\n      time: number\n    }\n  };\n}\n\nexport function changeTempVenueAction(venue: IBaseVenue, noDelay?: boolean): IChangeTempVenue {\n  return {\n    type: '/VENUES/CHANGE_TEMP_VENUE',\n    payload: {\n      venue\n    },\n    meta: {\n      debounce: {\n        time: noDelay ? 0 : 300\n      }\n    }\n  };\n}\n\ninterface ILoadVenues {\n  type: '/VENUES/LOAD_VENUES';\n  payload: {\n    venues: any;\n    count: number;\n    pages: number\n  };\n}\n\nexport function loadVenuesAction(venues: any, count: number, pages: number): ILoadVenues {\n  return {\n    type: '/VENUES/LOAD_VENUES',\n    payload: {\n      venues,\n      count,\n      pages\n    }\n  };\n}\n\ninterface ILoadCompaniesVenue {\n  type: '/VENUES/LOAD_COMPANIES';\n  payload: {\n    companies: ICompany[];\n  };\n}\n\nexport function loadCompaniesVenueAction(companies: ICompany[]): ILoadCompaniesVenue {\n  return {\n    type: '/VENUES/LOAD_COMPANIES',\n    payload: {\n      companies\n    }\n  };\n}\n\ninterface ILoadAllVenue {\n  type: '/VENUES/LOAD_ALL_VENUES';\n  payload: {\n    allVenues: IVenue[];\n  };\n}\n\nexport function loadAllVenueAction(allVenues: IVenue[]): ILoadAllVenue {\n  return {\n    type: '/VENUES/LOAD_ALL_VENUES',\n    payload: {\n      allVenues\n    }\n  };\n}\n\ninterface ILoadCarriers {\n  type: '/VENUES/LOAD_CARRIERS';\n  payload: {\n    carriers: ICarrier[];\n  };\n}\n\nexport function loadCarriersAction(carriers: ICarrier[]): ILoadCarriers {\n  return {\n    type: '/VENUES/LOAD_CARRIERS',\n    payload: {\n      carriers\n    }\n  };\n}\n\ninterface ILoadRegions {\n  type: '/VENUES/LOAD_REGIONS';\n  payload: {\n    regions: IRegion[];\n  };\n}\n\nexport function loadRegionsAction(regions: IRegion[]): ILoadRegions {\n  return {\n    type: '/VENUES/LOAD_REGIONS',\n    payload: {\n      regions\n    }\n  };\n}\n\nexport function getVenuesAction(nextPage: number) {\n  return (dispatch: Dispatch<VenueReduxAction>, getState: () => { venues: IVenuesState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    const { searchText } = state.venues;\n    if (nextPage && nextPage !== state.venues.pagination.page) {\n      dispatch(isLoadingAction(true));\n    }\n    dispatch(cancelRequestAction(api.getSource()));\n    const page = nextPage ? nextPage : state.venues.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n    Axios.all([\n      api.getCompanies(1, 200),\n      api.getVenues({ page: 1, pageSize: 200, search: searchText }),\n      api.getCarriers(1, 200),\n      api.getRegions(1, 200)\n    ])\n      .then(Axios.spread((companies: AxiosResponse, venues: AxiosResponse, carriers: AxiosResponse, regions: AxiosResponse) => {\n        dispatch(loadCompaniesVenueAction(companies.data.results));\n        dispatch(loadAllVenueAction(venues.data.results));\n        dispatch(loadCarriersAction(carriers.data.results));\n        dispatch(loadRegionsAction(regions.data.results));\n      }))\n      .catch((err: AxiosError): void => {\n        api.errorHandler(err);\n      });\n    api.getVenues({ page, search: searchText })\n      .then((response: AxiosResponse) => {\n        dispatch(loadVenuesAction(response.data.results, response.data.count, response.data.pages));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\nexport function createVenueAction() {\n  return (dispatch: Dispatch<VenueReduxAction>, getState: () => { venues: IVenuesState }) => {\n    dispatch(isLoadingAction(true));\n    const state = getState();\n    const { tempVenue } = state.venues;\n    const api: ApiService = new ApiService();\n    api.createVenue(tempVenue)\n      .then((response: AxiosResponse) => {\n        dispatch(getVenuesAction(state.venues.pagination.page) as any);\n        statusFooterButttonsModal(false);\n        showModal(false);\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\ninterface IChangeVenue {\n  type: '/VENUES/CHANGE_VENUE';\n  payload: {\n    venue: IBaseVenue;\n  };\n}\n\nexport function changeVenueAction(venue: IBaseVenue): IChangeVenue {\n  return {\n    type: '/VENUES/CHANGE_VENUE',\n    payload: {\n      venue\n    }\n  };\n}\n\nexport function updateVenueAction() {\n  return (dispatch: Dispatch<VenueReduxAction>, getState: () => { venues: IVenuesState }) => {\n    const state = getState();\n    const { tempVenue } = state.venues;\n    const $venue = $(`#venue-${tempVenue._id}`);\n    const api: ApiService = new ApiService();\n    api.updateVenue(tempVenue)\n      .then((response: AxiosResponse) => {\n        dispatch(changeVenueAction(response.data.venue));\n        dispatch(getVenuesAction(state.venues.pagination.page) as any);\n        statusFooterButttonsModal(false);\n        showModal(false);\n        $venue.addClass('editing-item');\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n        setTimeout(() => {\n          $venue.removeClass('editing-item');\n        }, 1000);\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n        $venue.removeClass('editing-item');\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\ninterface IDeleteVenue {\n  type: '/VENUES/DELETE_VENUE';\n  payload: {\n    id: string;\n  };\n}\n\nexport function processDeleteVenueAction(id: string): IDeleteVenue {\n  return {\n    type: '/VENUES/DELETE_VENUE',\n    payload: {\n      id\n    }\n  };\n}\n\ninterface ILoadUsers {\n  type: '/VENUES/LOAD_USERS';\n  payload: {\n    users: IUser[];\n  };\n}\n\nexport function loadUsers(users: IUser[]) : ILoadUsers {\n  return {\n    type: '/VENUES/LOAD_USERS',\n    payload: {\n      users\n    }\n  };\n}\n\nexport function deleteVenueAction(id: string) {\n  return (dispatch: Dispatch<VenueReduxAction>) => {\n    const api: ApiService = new ApiService();\n    api.deleteVenue(id)\n      .then((response: AxiosResponse): void => {\n        // effect when removing user\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n        $(`#venue-${id}`)\n          .addClass('deleted-item');\n        setTimeout(() => {\n          dispatch(processDeleteVenueAction(id));\n        }, 500);\n      })\n      .catch((err: AxiosError): void => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function getVenueUsersAction(page: number, venue: IVenue){\n  return (dispatch: Dispatch<VenueReduxAction>) => {\n    const api : ApiService = new ApiService();\n    api.getSource();\n    api.getUsers(page, \"\", venue, true, 100)\n      .then((response: AxiosResponse) : void => {\n        dispatch(loadUsers(response.data.results));\n      })\n      .catch((err: any) => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      })\n  };\n}\n\nexport type VenueReduxAction =\n  ICancelRequest |\n  IIsLoading |\n  IChangePage |\n  ILoadVenues |\n  IDeleteVenue |\n  IChangeSearchVenue |\n  IChangeTempVenue |\n  IChangeVenue |\n  ILoadCompaniesVenue |\n  ILoadAllVenue |\n  ILoadCarriers |\n  ILoadRegions |\n  ILoadUsers;\n","import {ITransmittal} from '../../../../../src/distribution/interfaces/transmittal.interface';\nimport {CancelTokenSource} from \"axios\";\nimport {IVenueModel} from '../../../../../src/app/models/venue.model';\nimport {ICarrierModel} from '../../../../../src/app/models/carrier.model';\nimport {ITransmittalItemModel} from '../../../../../src/distribution/models/transmittalItem.model';\nimport {IUserModel} from '../../../../../src/app/models/user.model';\nimport {IRequestItem} from '../../../../../src/request/interfaces/requestItem.interface';\nimport { ITransmittalModel } from '../../../../../src/distribution/models/transmittal.model';\nimport { IMilestoneType } from '../../../../../src/distribution/interfaces/milestoneType.interface';\nimport {IMilestone} from \"../../../../../src/distribution/interfaces\";\n\n\nexport const LOADING_TRANSMITTAL = '@transmittal/IS_LOADING';\nexport const LOAD_TRANSMITTAL = '@transmittal/LOAD';\nexport const LOAD_VENUES_TRANSMITTAL = '@transmittal/LOAD_VENUES';\nexport const LOAD_CARRIERS_TRANSMITTAL = '@transmittal/LOAD_CARRIERS';\nexport const LOAD_DRIVERS_TRANSMITTAL = '@transmittal/LOAD_DRIVERS';\nexport const LOAD_MILESTONE_TYPES_TRANSMITTAL = '@transmittal/LOAD_MILESTONE_TYPES';\nexport const TOOGLE_TAB_TRANSMITTAL = '@transmittal/TOOGLE_TAB';\nexport const CHANGE_ORDER_TRANSMITTAL = '@transmittal/CHANGE_ORDER';\nexport const CANCEL_REQUEST_TRANSMITTAL = '@transmittal/CANCEL_REQUEST';\nexport const CREATE_TRANSMITTAL_ITEM_TRANSMITTAL = '@transmittal/CREATE_TRANSMITTAL_ITEM';\nexport const UPDATE_TRANSMITTAL_ITEM_TRANSMITTAL = '@transmittal/UPDATE_TRANSMITTAL_ITEM';\nexport const DELETE_TRANSMITTAL_ITEM_TRANSMITTAL = '@transmittal/DELETE_TRANSMITTAL_ITEM';\nexport const UPDATE_TRANSMITTAL_TRANSMITTAL = '@transmittal/UPDATE_TRANSMITTAL';\nexport const DELETE_TRANSMITTAL_TRANSMITTAL = '@transmittal/DELETE_TRANSMITTAL';\nexport const TRANSPORT_MILESTONE_LOAD_STATUS = '@transmittal/LOAD_MILESTONES';\n\n\nexport interface IPaginationListView {\n  count: number;\n  page: number;\n  pages: number;\n}\n\nexport interface IOrderListView {\n  orderType: string;\n  orderBy: string;\n}\n\nexport interface IListView<T = any> {\n  loading: boolean;\n  data: T[];\n  source: CancelTokenSource | null;\n  pagination: IPaginationListView;\n  options: IOrderListView;\n}\n\nexport interface IRequestItemsFilters {\n  text: string;\n  request: string;\n  entry: string;\n  venues: any[];\n  properties: any[];\n  status: any[];\n  from: any;\n  to: any;\n}\n\nexport interface ITransmittalState<T = ITransmittal> extends IListView<T> {\n  requestItemsLoading: boolean;\n  venues: IVenueModel[];\n  carriers: ICarrierModel[];\n  drivers: IUserModel[];\n  milestoneTypes: IMilestoneType[];\n  milestones: IMilestone[];\n  requestItems: IRequestItem[];\n  requestItemsfilters: IRequestItemsFilters;\n  requestItemsPagination: IPaginationListView;\n  transmittalOpen: string[];\n}\n\nexport interface ITransmittalChangeOrderAction {\n  type: typeof CHANGE_ORDER_TRANSMITTAL;\n  payload: {\n    orderBy: string;\n    orderType: string;\n  };\n}\n\ninterface ITransmittalLoadingAction {\n  type: typeof LOADING_TRANSMITTAL;\n  payload: {\n    loading: boolean;\n  }\n}\n\ninterface ITransmittalCancerlRequestAction {\n  type: typeof CANCEL_REQUEST_TRANSMITTAL;\n  payload: {\n    source: CancelTokenSource;\n  }\n}\n\ninterface ITransmittalLoadMilestones {\n  type: typeof TRANSPORT_MILESTONE_LOAD_STATUS;\n  payload: {\n    milestones: IMilestone[];\n  }\n}\n\ninterface ITransmittalLoadAction {\n  type: typeof LOAD_TRANSMITTAL;\n  payload: {\n    data: ITransmittal[];\n    count: number;\n    pages: number;\n    page: number;\n  }\n}\n\ninterface ITransmittalLoadVenuesAction {\n  type: typeof LOAD_VENUES_TRANSMITTAL;\n  payload: {\n    venues: IVenueModel[];\n  }\n}\n\ninterface ITransmittalLoadCarriersAction {\n  type: typeof LOAD_CARRIERS_TRANSMITTAL;\n  payload: {\n    carriers: ICarrierModel[];\n  }\n}\n\ninterface ITransmittalLoadDriversAction {\n  type: typeof LOAD_DRIVERS_TRANSMITTAL;\n  payload: {\n    drivers: IUserModel[];\n  }\n}\n\ninterface ITransmittalLoadMilestoneTypesAction {\n  type: typeof LOAD_MILESTONE_TYPES_TRANSMITTAL;\n  payload: {\n    milestoneTypes: IMilestoneType[];\n  }\n}\n\ninterface ITransmittalToogleTabAction {\n  type: typeof TOOGLE_TAB_TRANSMITTAL;\n  payload: {\n    transmittalId: string;\n  }\n}\n\ninterface ICreateTransmittalItemAction {\n  type: typeof CREATE_TRANSMITTAL_ITEM_TRANSMITTAL;\n  payload: {\n    transmittalItem: Partial<ITransmittalItemModel>;\n  }\n}\n\ninterface IUpdateTransmittalItemAction {\n  type: typeof UPDATE_TRANSMITTAL_ITEM_TRANSMITTAL;\n  payload: {\n    transmittalItem: Partial<ITransmittalItemModel>;\n  }\n}\n\ninterface IDeleteTransmittalAction {\n  type: typeof DELETE_TRANSMITTAL_TRANSMITTAL;\n  payload: {\n    transmittal: Partial<ITransmittalModel>;\n  }\n}\n\ninterface IDeleteTransmittalItemAction {\n  type: typeof DELETE_TRANSMITTAL_ITEM_TRANSMITTAL;\n  payload: {\n    transmittalItem: Partial<ITransmittalItemModel>;\n  }\n}\n\ninterface IUpdateTransmittalAction {\n  type: typeof UPDATE_TRANSMITTAL_TRANSMITTAL;\n  payload: {\n    transmittal: Partial<ITransmittalModel>;\n  }\n}\n\n// SEARCH CARS IN REQUEST\nexport const LOAD_REQUEST_ITEMS_TRANSMITTAL = '@transmittal/LOAD_REQUEST_ITEMS';\nexport const LOADING_REQUEST_ITEMS_TRANSMITTAL = '@transmittal/LOADING_REQUEST_ITEMS';\nexport const FILTER_REQUEST_ITEMS_TRANSMITTAL = '@transmittal/FILTER_REQUEST_ITEMS';\n\nexport interface IChangeFilterRequestItemsTransmittalItemAction  {\n  type: typeof FILTER_REQUEST_ITEMS_TRANSMITTAL;\n  payload: {\n    key: keyof IRequestItemsFilters;\n    value: any | any[];\n  };\n}\n\nexport interface ILoadRequestItemsTransmittalItemAction  {\n  type: typeof LOAD_REQUEST_ITEMS_TRANSMITTAL;\n  payload: {\n    requestItems: IRequestItem[];\n    count: number;\n    pages: number\n    page: number;\n  };\n}\n\nexport interface ILoadingRequestItemsTransmittalItemAction  {\n  type: typeof LOADING_REQUEST_ITEMS_TRANSMITTAL;\n  payload: {\n    requestItemsLoading: boolean;\n  };\n}\n\nexport type ITransmittalActionTypes =\n  ITransmittalCancerlRequestAction |\n  ITransmittalLoadVenuesAction |\n  ITransmittalLoadCarriersAction |\n  ITransmittalToogleTabAction |\n  ITransmittalChangeOrderAction |\n  ITransmittalLoadAction |\n  IUpdateTransmittalAction |\n  IDeleteTransmittalItemAction |\n  ICreateTransmittalItemAction |\n  IUpdateTransmittalItemAction |\n  IDeleteTransmittalAction |\n  ITransmittalLoadDriversAction |\n  ITransmittalLoadMilestoneTypesAction |\n  IChangeFilterRequestItemsTransmittalItemAction |\n  ILoadRequestItemsTransmittalItemAction |\n  ILoadingRequestItemsTransmittalItemAction |\n  ITransmittalLoadingAction |\n  ITransmittalLoadMilestones;\n\n","import { CancelTokenSource } from 'axios';\nimport { IOperationType } from '../../../../../src/request/interfaces/operationType.interface';\n\nexport const OPERATION_TYPE_CANCEL_STATUS = '/OPERATION_TYPE/CANCEL_STATUS';\nexport const OPERATION_TYPE_IS_LOADING = '/OPERATION_TYPE/IS_LOADING';\nexport const OPERATION_TYPE_LOAD_STATUS = '/OPERATION_TYPE/LOAD_STATUS';\nexport const OPERATION_TYPE_CREATE_STATUS = '/OPERATION_TYPE/CREATE_STATUS';\nexport const OPERATION_TYPE_UDPATE_STATUS = '/OPERATION_TYPE/UDPATE_STATUS';\nexport const OPERATION_TYPE_DELETE_STATUS = '/OPERATION_TYPE/DELETE_STATUS';\nexport const OPERATION_TYPE_CHANGE_ORDER = '/OPERATION_TYPE/CHANGE_ORDER';\n\nexport interface IOperationTypeState {\n  operationTypes: IOperationType[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  options: {\n    orderBy: string;\n    orderType: string;\n  };\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\nexport interface ICancelOperationType {\n  type: typeof OPERATION_TYPE_CANCEL_STATUS;\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport interface IIsLoadingOperationType {\n  type: typeof OPERATION_TYPE_IS_LOADING;\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport interface ILoadOperationType {\n  type: typeof OPERATION_TYPE_LOAD_STATUS;\n  payload: {\n    operationTypes: IOperationType[];\n    count: number;\n    pages: number\n    page: number\n  };\n}\n\nexport interface ICreateOperationType {\n  type: typeof OPERATION_TYPE_CREATE_STATUS;\n  payload: {\n    operationType: IOperationType\n  };\n}\n\nexport interface IUpdateOperationType {\n  type: typeof OPERATION_TYPE_UDPATE_STATUS;\n  payload: {\n    operationType: IOperationType\n  };\n}\n\nexport interface IDeleteOperationType {\n  type: typeof OPERATION_TYPE_DELETE_STATUS;\n  payload: {\n    operationType: IOperationType\n  };\n}\n\nexport interface IChangeOrderOperationType {\n  type: typeof OPERATION_TYPE_CHANGE_ORDER;\n  payload: {\n    orderBy: string;\n    orderType: string;\n  };\n}\n\nexport type OperationTypeReduxActions =\n  ICancelOperationType |\n  IIsLoadingOperationType |\n  ICreateOperationType |\n  IUpdateOperationType |\n  IDeleteOperationType |\n  IChangeOrderOperationType |\n  ILoadOperationType;\n","import { CancelTokenSource } from 'axios';\nimport { IMilestone } from '../../../../../src/distribution/interfaces/milestone.interface';\nimport { IRequestStatus } from '../../../../../src/request/interfaces/requestStatus.interface';\nimport { IForm } from '../../../../../src/form/interfaces/form.interface';\nimport { IMilestoneType } from '../../../../../src/distribution/interfaces/milestoneType.interface';\n\nexport const MILESTONE_CANCEL_STATUS = '/MILESTONE/CANCEL_STATUS';\nexport const MILESTONE_IS_LOADING = '/MILESTONE/IS_LOADING';\nexport const MILESTONE_LOAD_STATUS = '/MILESTONE/LOAD_STATUS';\nexport const MILESTONE_LOAD_FORMS = '/MILESTONE/LOAD_FORMS';\nexport const MILESTONE_LOAD_TYPES = '/MILESTONE/LOAD_TYPES';\nexport const MILESTONE_LOAD_REQUEST_STATUS = '/MILESTONE/LOAD_REQUEST_STATUS';\nexport const MILESTONE_CREATE_STATUS = '/MILESTONE/CREATE_STATUS';\nexport const MILESTONE_UDPATE_STATUS = '/MILESTONE/UDPATE_STATUS';\nexport const MILESTONE_DELETE_STATUS = '/MILESTONE/DELETE_STATUS';\nexport const MILESTONE_CHANGE_ORDER = '/MILESTONE/CHANGE_ORDER';\n\nexport interface IMilestoneState {\n  milestones: IMilestone[];\n  milestoneTypes: IMilestoneType[];\n  requestStatus: IRequestStatus[];\n  forms: IForm[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  options: {\n    orderBy: string;\n    orderType: string;\n  };\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\nexport interface ICancelMilestone {\n  type: typeof MILESTONE_CANCEL_STATUS;\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport interface IIsLoadingMilestone {\n  type: typeof MILESTONE_IS_LOADING;\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport interface ILoadFormsMilestone {\n  type: typeof MILESTONE_LOAD_FORMS;\n  payload: {\n    forms: IForm[];\n  };\n}\n\nexport interface ILoadTypesMilestone {\n  type: typeof MILESTONE_LOAD_TYPES;\n  payload: {\n    milestoneTypes: IMilestoneType[];\n  };\n}\n\nexport interface ILoadRequestStatusMilestone {\n  type: typeof MILESTONE_LOAD_REQUEST_STATUS;\n  payload: {\n    requestStatus: IRequestStatus[];\n  };\n}\n\nexport interface ILoadMilestone {\n  type: typeof MILESTONE_LOAD_STATUS;\n  payload: {\n    milestones: IMilestone[];\n    count: number;\n    pages: number\n    page: number\n  };\n}\n\nexport interface ICreateMilestone {\n  type: typeof MILESTONE_CREATE_STATUS;\n  payload: {\n    milestone: IMilestone\n  };\n}\n\nexport interface IUpdateMilestone {\n  type: typeof MILESTONE_UDPATE_STATUS;\n  payload: {\n    milestone: IMilestone\n  };\n}\n\nexport interface IDeleteMilestone {\n  type: typeof MILESTONE_DELETE_STATUS;\n  payload: {\n    milestone: IMilestone\n  };\n}\n\nexport interface IChangeOrderMilestone {\n  type: typeof MILESTONE_CHANGE_ORDER;\n  payload: {\n    orderBy: string;\n    orderType: string;\n  };\n}\n\nexport type MilestoneReduxActions =\n  ICancelMilestone |\n  IIsLoadingMilestone |\n  ILoadFormsMilestone |\n  ILoadTypesMilestone |\n  ILoadRequestStatusMilestone |\n  ICreateMilestone |\n  IUpdateMilestone |\n  IDeleteMilestone |\n  IChangeOrderMilestone |\n  ILoadMilestone;\n","import { CancelTokenSource } from 'axios';\nimport { IMilestoneType } from '../../../../../src/distribution/interfaces/milestoneType.interface';\n\nexport const MILESTONE_TYPE_CANCEL_STATUS = '/MILESTONE_TYPE/CANCEL_STATUS';\nexport const MILESTONE_TYPE_IS_LOADING = '/MILESTONE_TYPE/IS_LOADING';\nexport const MILESTONE_TYPE_LOAD_STATUS = '/MILESTONE_TYPE/LOAD_STATUS';\nexport const MILESTONE_TYPE_CREATE_STATUS = '/MILESTONE_TYPE/CREATE_STATUS';\nexport const MILESTONE_TYPE_UDPATE_STATUS = '/MILESTONE_TYPE/UDPATE_STATUS';\nexport const MILESTONE_TYPE_DELETE_STATUS = '/MILESTONE_TYPE/DELETE_STATUS';\nexport const MILESTONE_TYPE_CHANGE_ORDER = '/MILESTONE_TYPE/CHANGE_ORDER';\n\nexport interface IMilestoneTypeState {\n  milestoneTypes: IMilestoneType[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  options: {\n    orderBy: string;\n    orderType: string;\n  };\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\nexport interface ICancelMilestoneType {\n  type: typeof MILESTONE_TYPE_CANCEL_STATUS;\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport interface IIsLoadingMilestoneType {\n  type: typeof MILESTONE_TYPE_IS_LOADING;\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport interface ILoadMilestoneType {\n  type: typeof MILESTONE_TYPE_LOAD_STATUS;\n  payload: {\n    milestoneTypes: IMilestoneType[];\n    count: number;\n    pages: number\n    page: number\n  };\n}\n\nexport interface ICreateMilestoneType {\n  type: typeof MILESTONE_TYPE_CREATE_STATUS;\n  payload: {\n    milestoneType: IMilestoneType\n  };\n}\n\nexport interface IUpdateMilestoneType {\n  type: typeof MILESTONE_TYPE_UDPATE_STATUS;\n  payload: {\n    milestoneType: IMilestoneType\n  };\n}\n\nexport interface IDeleteMilestoneType {\n  type: typeof MILESTONE_TYPE_DELETE_STATUS;\n  payload: {\n    milestoneType: IMilestoneType\n  };\n}\n\nexport interface IChangeOrderMilestoneType {\n  type: typeof MILESTONE_TYPE_CHANGE_ORDER;\n  payload: {\n    orderBy: string;\n    orderType: string;\n  };\n}\n\nexport type MilestoneTypeReduxActions =\n  ICancelMilestoneType |\n  IIsLoadingMilestoneType |\n  ICreateMilestoneType |\n  IUpdateMilestoneType |\n  IDeleteMilestoneType |\n  IChangeOrderMilestoneType |\n  ILoadMilestoneType;\n","import { CancelTokenSource } from 'axios';\nimport { IForm } from '../../../../../src/form/interfaces/form.interface';\nimport { IRequestStatus } from '../../../../../src/request/interfaces/requestStatus.interface';\n\nexport const FORM_CANCEL_STATUS = '/FORM/CANCEL_STATUS';\nexport const FORM_IS_LOADING = '/FORM/IS_LOADING';\nexport const FORM_LOAD_STATUS = '/FORM/LOAD_STATUS';\nexport const FORM_LOAD_REQUEST_STATUS = '/FORM/LOAD_REQUEST_STATUS';\nexport const FORM_CREATE_STATUS = '/FORM/CREATE_STATUS';\nexport const FORM_UDPATE_STATUS = '/FORM/UDPATE_STATUS';\nexport const FORM_DELETE_STATUS = '/FORM/DELETE_STATUS';\nexport const FORM_CHANGE_ORDER = '/FORM/CHANGE_ORDER';\n\nexport interface IFormsState {\n  forms: IForm[];\n  requestStatus: IRequestStatus[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  options: {\n    orderBy: string;\n    orderType: string;\n  };\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\nexport interface ICancelForm {\n  type: typeof FORM_CANCEL_STATUS;\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport interface IIsLoadingForm {\n  type: typeof FORM_IS_LOADING;\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport interface ILoadRequestStatusForm {\n  type: typeof FORM_LOAD_REQUEST_STATUS;\n  payload: {\n    requestStatus: IRequestStatus[];\n  };\n}\n\nexport interface ILoadForm {\n  type: typeof FORM_LOAD_STATUS;\n  payload: {\n    forms: IForm[];\n    count: number;\n    pages: number\n    page: number\n  };\n}\n\nexport interface ICreateForm {\n  type: typeof FORM_CREATE_STATUS;\n  payload: {\n    form: IForm\n  };\n}\n\nexport interface IUpdateForm {\n  type: typeof FORM_UDPATE_STATUS;\n  payload: {\n    form: IForm\n  };\n}\n\nexport interface IDeleteForm {\n  type: typeof FORM_DELETE_STATUS;\n  payload: {\n    form: IForm\n  };\n}\n\nexport interface IChangeOrderForm {\n  type: typeof FORM_CHANGE_ORDER;\n  payload: {\n    orderBy: string;\n    orderType: string;\n  };\n}\n\nexport type FormReduxActions =\n  ICancelForm |\n  IIsLoadingForm |\n  ILoadRequestStatusForm |\n  ICreateForm |\n  IUpdateForm |\n  IDeleteForm |\n  IChangeOrderForm |\n  ILoadForm;\n","import { CancelTokenSource } from 'axios';\nimport { IColor } from '../../../../../src/app/interfaces/color.interface';\nimport { IRequestStatus } from '../../../../../src/request/interfaces/requestStatus.interface';\nimport { IForm } from '../../../../../src/form/interfaces/form.interface';\n\nexport const COLOR_CANCEL = '/COLOR/CANCEL';\nexport const COLOR_IS_LOADING = '/COLOR/IS_LOADING';\nexport const COLOR_LOAD = '/COLOR/LOAD';\nexport const COLOR_LOAD_FORMS = '/COLOR/LOAD_FORMS';\nexport const COLOR_LOAD_REQUEST = '/COLOR/LOAD_REQUEST';\nexport const COLOR_CREATE = '/COLOR/CREATE';\nexport const COLOR_UDPATE = '/COLOR/UDPATE';\nexport const COLOR_DELETE = '/COLOR/DELETE';\nexport const COLOR_CHANGE_ORDER = '/COLOR/CHANGE_ORDER';\n\nexport interface IColorState {\n  colors: IColor[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  options: {\n    orderBy: string;\n    orderType: string;\n  };\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\nexport interface ICancelColor {\n  type: typeof COLOR_CANCEL;\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport interface IIsLoadingColor {\n  type: typeof COLOR_IS_LOADING;\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport interface ILoadFormsColor {\n  type: typeof COLOR_LOAD_FORMS;\n  payload: {\n    forms: IForm[];\n  };\n}\n\nexport interface ILoadRequestStatusColor {\n  type: typeof COLOR_LOAD_REQUEST;\n  payload: {\n    requestStatus: IRequestStatus[];\n  };\n}\n\nexport interface ILoadColor {\n  type: typeof COLOR_LOAD;\n  payload: {\n    colors: IColor[];\n    count: number;\n    pages: number\n    page: number\n  };\n}\n\nexport interface ICreateColor {\n  type: typeof COLOR_CREATE;\n  payload: {\n    color: IColor\n  };\n}\n\nexport interface IUpdateColor {\n  type: typeof COLOR_UDPATE;\n  payload: {\n    color: IColor\n  };\n}\n\nexport interface IDeleteColor {\n  type: typeof COLOR_DELETE;\n  payload: {\n    color: IColor\n  };\n}\n\nexport interface IChangeOrderColor {\n  type: typeof COLOR_CHANGE_ORDER;\n  payload: {\n    orderBy: string;\n    orderType: string;\n  };\n}\n\nexport type ColorReduxActions =\n  ICancelColor |\n  IIsLoadingColor |\n  ILoadFormsColor |\n  ILoadRequestStatusColor |\n  ICreateColor |\n  IUpdateColor |\n  IDeleteColor |\n  IChangeOrderColor |\n  ILoadColor;\n","import * as React from 'react';\nimport ShowIf from '../../Utils/ShowIf';\nimport { FieldArrayFieldsProps } from 'redux-form/lib/FieldArray';\nimport { IRequestItem } from '../../../../../../../src/request/interfaces/requestItem.interface';\nimport SearchCarInRequests from './SearchCarInRequest';\nimport SearchCarInCars from './SearchCarInCars';\nimport { ICar } from '../../../../../../../src/app/interfaces/car.interface';\nimport { hasPermission } from '../../../utils/common';\nimport { IWindow } from '../../../interfaces/window';\n\ntype Tabs = 'cars' | 'requests'\n\ninterface IPropsType {\n  fields?: FieldArrayFieldsProps<any>;\n  slimView?: boolean;\n\n  onClickRequest(item: IRequestItem): void;\n\n  onClickCar(car: ICar): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  tab: Tabs;\n}\n\ndeclare let window: IWindow;\n\n\nclass AddItemsToTransmittal extends React.Component<IPropsType, IStateType> {\n\n  readonly state: IStateType = {\n    error: null,\n    tab: 'requests'\n  };\n\n  public render(): React.ReactElement<IPropsType> {\n    const { tab } = this.state;\n    const { fields, onClickRequest, onClickCar, slimView } = this.props;\n    return (\n      <div>\n        <ShowIf condition={hasPermission(window.user, 'addCarOnTransmittal')}>\n          <ul className='nav nav-pills nav-justified' style={{ marginTop: '10px', marginBottom: '10px', border: '1px solid #f4f4f4' }}>\n            <li className={tab === 'requests' ? 'active' : ''}>\n              <a\n                className={tab === 'requests' ? 'background-transition' : ''}\n                href='javascript:void(0);'\n                style={{ borderTop: '0', marginBottom: '0' }}\n                onClick={() => this.changeTab('requests')}\n              >Solicitudes</a>\n            </li>\n            <li className={tab === 'cars' ? 'active' : ''}>\n              <a\n                href='javascript:void(0);'\n                className={tab === 'cars' ? 'background-transition' : ''}\n                style={{ borderTop: '0', marginBottom: '0' }}\n                onClick={() => this.changeTab('cars')}\n              >Unidades</a>\n            </li>\n          </ul>\n        </ShowIf>\n        <ShowIf condition={tab === 'requests'}>\n          <SearchCarInRequests fields={fields!} onClick={onClickRequest} slimView={slimView} />\n        </ShowIf>\n        <ShowIf condition={tab === 'cars'}>\n          <SearchCarInCars fields={fields!} slimView={slimView} onClick={onClickCar} />\n        </ShowIf>\n      </div>\n    );\n  }\n\n  private changeTab(tab: Tabs) {\n    this.setState({\n      tab\n    });\n  }\n}\n\nexport default AddItemsToTransmittal;\n\n\n","import * as React from \"react\";\nimport { TextareaHTMLAttributes} from \"react\";\nimport {Property} from \"csstype\";\ninterface IPropsType {\n  input: TextareaHTMLAttributes<any>\n  label: string;\n  labelOff?:boolean;\n  resize: Property.Resize;\n  type: string\n  help: string\n  placeholder: string;\n  meta: {\n    touched: boolean;\n    error: string;\n    warning: string;\n  }\n}\nconst TextAreaField: React.FunctionComponent<IPropsType> = ({\n  input,\n  label,\n  labelOff,\n  placeholder,\n  help,\n  resize,\n  meta: { touched, error, warning },\n  ...custom\n}: IPropsType) => (\n  <div className={`form-group ${touched && error ? 'has-error' : warning ? 'has-warning' : ''}`}>\n    {!labelOff?<label className=\"control-label\">{label}</label>: null}\n    <textarea\n      {...input}\n      {...custom}\n      style={{\n        resize: resize ? resize : 'inherit'\n      }}\n      className={`form-control`}\n      placeholder={placeholder}\n    />\n    {\n      help ?\n        <small id=\"passwordHelpBlock\" className=\"form-text text-muted\">\n          {help}\n        </small>\n        : null\n    }\n    {\n      touched &&\n      ((error && <span className=\"help-block\">{error}</span>) ||\n        (warning && <span className=\"help-block\">{warning}</span>))\n    }\n  </div>\n);\n\nexport default TextAreaField;\n","import * as React from 'react';\nimport { InputHTMLAttributes } from 'react';\n\ninterface IPropsType {\n  input: InputHTMLAttributes<any>;\n  type: string;\n}\n\nconst InputHiddenField: React.FunctionComponent<IPropsType> = ({ input, type }: IPropsType) => (\n    <input\n      {...input}\n      type={type}\n    />\n);\n\nexport default InputHiddenField;\n","import {AxiosError, AxiosResponse, CancelTokenSource} from 'axios';\nimport {Dispatch} from 'redux';\nimport ApiService from '../utils/axios';\nimport {StatsDashboardTypes} from '../../../../../src/stats/models/studio.model';\nimport {IStudio} from '../../../../../src/stats/interfaces/studio.interface';\nimport {ITeam, IUser} from '../../../../../src/app/interfaces';\nimport * as swal from 'sweetalert';\nimport {showModal, statusFooterButttonsModal} from \"../utils/common\";\nimport {changeUserAction, getUsersAction, IUsersState, UserReduxAction} from \"./users.actions\";\n\nexport interface ITempStudio {\n  _id?: string;\n  name: string;\n  embedURL: string;\n  users: IUser[];\n  type: string;\n  team: ITeam | null\n}\n\n\nexport interface IStatsDashboardState {\n  loading: boolean;\n  studios: IStudio[];\n  tempStudio: ITempStudio;\n  currentStudio: IStudio | null;\n  users: IUser[];\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface IChangePage {\n  type: '/STATS_DASHBOARD/CHANGE_PAGE';\n  payload: {\n    page: number;\n  };\n}\n\nexport function changePageAction(page: number): IChangePage {\n  return {\n    type: '/STATS_DASHBOARD/CHANGE_PAGE',\n    payload: {\n      page\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/STATS_DASHBOARD/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/STATS_DASHBOARD/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\n\ninterface IChangeTempStudio {\n  type: '/STATS_DASHBOARD/CHANGE_TEMP_STUDIO';\n  payload: {\n    tempStudio: ITempStudio;\n  };\n  meta: {\n    debounce: {\n      time: number\n    }\n  };\n}\n\nexport function changeTempStudioAction(tempStudio: ITempStudio): IChangeTempStudio {\n  return {\n    type: '/STATS_DASHBOARD/CHANGE_TEMP_STUDIO',\n    payload: {\n      tempStudio\n    },\n    meta: {\n      debounce: {\n        time: 100\n      }\n    }\n  };\n}\n\n\ninterface ILoadStudios {\n  type: '/STATS_DASHBOARD/LOAD_STUDIOS';\n  payload: {\n    studios: IStudio[];\n  };\n}\n\n\nexport function loadStudiosAction(studios: IStudio[]): ILoadStudios {\n  return {\n    type: '/STATS_DASHBOARD/LOAD_STUDIOS',\n    payload: {\n      studios\n    }\n  };\n}\n\nexport function getMyStudiosAction(type? : StatsDashboardTypes) {\n  return (dispatch: Dispatch<StatsDashboardReducerAction>) => {\n    dispatch(isLoadingAction(true));\n    const api: ApiService = new ApiService();\n    api.getMyStudiosDashboards(type)\n      .then((response: AxiosResponse) => {\n        dispatch(loadStudiosAction(response.data.studios));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function getStudiosAction(type? : StatsDashboardTypes) {\n  return (dispatch: Dispatch<StatsDashboardReducerAction>) => {\n    dispatch(isLoadingAction(true));\n    const api: ApiService = new ApiService();\n    api.getStudiosDashboards(type)\n      .then((response: AxiosResponse) => {\n        dispatch(loadStudiosAction(response.data.studios));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\ninterface IDeleteStudio {\n  type: '/STATS_DASHBOARD/DELETE_USER';\n  payload: {\n    id: string;\n  };\n}\n\nexport function removeStudioAction(id: string): IDeleteStudio {\n  return {\n    type: '/STATS_DASHBOARD/DELETE_USER',\n    payload: {\n      id\n    }\n  };\n}\n\nexport function deleteStudioAction(id: string) {\n  return (dispatch: Dispatch<StatsDashboardReducerAction>) => {\n    const api: ApiService = new ApiService();\n    api.deleteStudio(id)\n      .then((response: AxiosResponse): void => {\n        dispatch(removeStudioAction(id));\n        swal(response.data.message, {\n          icon: 'success'\n        });\n        // effect when removing user\n        $(`#studio-${id}`)\n          .addClass('deleted-item');\n        setTimeout(() => {\n          dispatch(getStudiosAction() as any);\n        }, 1000);\n      })\n      .catch((err: AxiosError): void => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\ninterface ILoadStudioUsers {\n  type: '/STATS_DASHBOARD/LOAD_STUDIOS_USERS';\n  payload: {\n    users: IUser[];\n  };\n}\n\nexport function loadStudioUsers(users: IUser[]): ILoadStudioUsers {\n  return {\n    type: '/STATS_DASHBOARD/LOAD_STUDIOS_USERS',\n    payload: {\n      users\n    }\n  };\n}\n\nexport function loadStudioUsersAction() {\n  return (dispatch: Dispatch<StatsDashboardReducerAction>) => {\n    dispatch(isLoadingAction(true));\n    const api: ApiService = new ApiService();\n    api.getStudioUsers()\n      .then((response: AxiosResponse) => {\n        dispatch(loadStudioUsers(response.data.results));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function createStudioAction() {\n  return (dispatch: Dispatch<StatsDashboardReducerAction>, getState: () => {statsDashboard: IStatsDashboardState}) => {\n    dispatch(isLoadingAction(true));\n    const state = getState();\n    const {tempStudio} = state.statsDashboard;\n    const api: ApiService = new ApiService();\n    api.createStudio(tempStudio)\n      .then((response: AxiosResponse) => {\n        statusFooterButttonsModal(false);\n        showModal(false);\n        dispatch(getStudiosAction() as any);\n        swal(response.data.message, {\n          icon: 'success'\n        });\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function editStudioAction() {\n  return (dispatch: Dispatch<StatsDashboardReducerAction>, getState: () => {statsDashboard: IStatsDashboardState}) => {\n    dispatch(isLoadingAction(true));\n    const state = getState();\n    const {tempStudio} = state.statsDashboard;\n    const api: ApiService = new ApiService();\n    api.updateStudio(tempStudio)\n      .then((response: AxiosResponse) => {\n        statusFooterButttonsModal(false);\n        showModal(false);\n        dispatch(getStudiosAction() as any);\n        $(`#studio-${tempStudio._id}`).addClass('editing-item');\n        swal(response.data.message, {\n          icon: 'success'\n        });\n        setTimeout(() => {\n          $(`#studio-${tempStudio._id}`).removeClass('editing-item');\n          console.log(\"remove editing-item\");\n        }, 1000);\n      })\n      .catch((err: AxiosError) => {\n        console.log(err)\n        statusFooterButttonsModal(false);\n        $(`#studio-${tempStudio._id}`).removeClass('editing-item');\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\n\nexport type StatsDashboardReducerAction =\n  IIsLoading |\n  ILoadStudios |\n  IChangePage |\n  IChangeTempStudio |\n  IDeleteStudio |\n  ILoadStudioUsers;\n\n\n","import * as mongoose from 'mongoose';\nimport * as mongoosePaginate from 'mongoose-paginate';\nimport { PaginateModel } from 'mongoose';\nimport {IInvoiceModel} from \"../../billing/models/invoice.model\";\n\nexport enum StatsDashboardTypes {\n  UNIT_CONTROL = \"UNIT_CONTROL\",\n  INVENTORY = \"INVENTORY\",\n  DISTRIBUTION = \"DISTRIBUTION\",\n  PLANIFICATION = \"PLANIFICATION\"\n}\n\nexport const DashboardTypesDictionary : {[id: string]: string} = {\n  [StatsDashboardTypes.UNIT_CONTROL]: \"Control de unidades\",\n  [StatsDashboardTypes.INVENTORY]: \"Inventarios\",\n  [StatsDashboardTypes.DISTRIBUTION]: \"Distribución\",\n  [StatsDashboardTypes.PLANIFICATION]: \"Planificación\"\n};\n\nexport const choicesStatsDashboardTypes = [\n  StatsDashboardTypes.UNIT_CONTROL,\n  StatsDashboardTypes.INVENTORY,\n  StatsDashboardTypes.DISTRIBUTION,\n  StatsDashboardTypes.PLANIFICATION,\n];\n\nconst studioSchema = new mongoose.Schema({\n  team: {\n    type: mongoose.Schema.Types.ObjectId,\n    ref: 'Team'\n  },\n  users: [{\n    type: mongoose.Schema.Types.ObjectId,\n    ref: 'User'\n  }],\n  type: {\n    type: String,\n    enum: choicesStatsDashboardTypes,\n    default: StatsDashboardTypes.UNIT_CONTROL\n  },\n  name: String,\n  embedURL: String,\n},{\n  timestamps: true\n});\n\nstudioSchema.plugin(mongoosePaginate);\n\nexport type StudioSchema = mongoose.Model<IInvoiceModel> & PaginateModel<IInvoiceModel>;\n\nconst Studio = mongoose.model<IInvoiceModel, StudioSchema>('Studio', studioSchema);\n\nexport default Studio;\n","import { ConnectedRouter } from 'connected-react-router';\nimport * as moment from 'moment';\nimport * as React from 'react';\nimport * as ReactDOM from 'react-dom';\nimport { Provider } from 'react-redux';\nimport { Route, RouteComponentProps, Switch } from 'react-router-dom';\nimport AlertsViews from './components/Alerts/AlertViews';\nimport BillingListView from './components/Billing/BillingListView';\nimport CarriersListView from './components/Carriers/CarriersListView';\nimport CarDetailView from './components/Cars/CarDetailView';\nimport CarsListView from './components/Cars/CarListView';\nimport RequestChannelListView from './components/RequestSettings/RequestChannelListView';\nimport PaymentMethodListView from './components/RequestSettings/PaymentMethodlListView';\nimport RequestStatusListView from './components/RequestSettings/RequestStatusListView';\nimport CompaniesListView from './components/Companies/CompaniesListView';\nimport DashboardDamagesView from './components/DashboardGeneral/DashboardDamagesView';\nimport DashboardDercoView from './components/DashboardGeneral/DashboardDercoView';\nimport DashboardGeneralView from './components/DashboardGeneral/DashboardGeneralView';\nimport DashboardTimingView from './components/DashboardGeneral/DashboardTimingView';\nimport DashboardRevisionsView from './components/DashboardVin/DashboardRevisionsView';\nimport DashboardVinDetail from './components/DashboardVin/DashboardVinDetail';\nimport DashboardVinView from './components/DashboardVin/DashboardVinView';\nimport ImportCarsView from './components/Imports/ImportCarView';\nimport InventoryCreateView from './components/Inventory/InventoryCreateView';\nimport InventoryDashboardView from './components/Inventory/InventoryDashboardView';\nimport InventoryDetailView from './components/Inventory/InventoryDetailView';\nimport InventoryListView from './components/Inventory/InventoryListView';\nimport LabelsListView from './components/Labels/LabelsListView';\nimport PlanningImportView from './components/Planning/PlanningImportView';\nimport PlanningListView from './components/Planning/PlanningListView';\nimport RequestReasonListView from './components/RequestSettings/RequestReasonListView';\nimport RegionsListView from './components/Region/RegionsListFiew';\nimport RequestCreateView from './components/Request/RequestCreateView';\nimport RequestDetailView from './components/Request/RequestDetail/RequestDetailView';\nimport RequestListView from './components/Request/RequestList/RequestListView';\nimport RequestUpdaterView from './components/Request/RequestUpdaterView';\nimport RequestVehicleListView from './components/Request/RequestVehicleList/RequestVehicleListView';\nimport StockImportView from './components/Stock/StockImportView';\nimport StockView from './components/Stock/StockListView';\nimport UsersListView from './components/Users/UserListView';\nimport VenuesListView from './components/Venues/VenuesListView';\nimport VersionListView from './components/Versions/VersionListView';\nimport { IWindow } from './interfaces/window';\nimport configureStore, { history } from './store/configureStore';\nimport { isIntenertExplorer } from './utils/common';\nimport CustomDashboardComponent from './components/CustomDashboard/CustomDashboardComponent';\nimport TransmittalListView from './components/Transmittal/TransmittalList/TransmittalListView';\nimport TransmittalCreateView from './components/Transmittal/TransmittalCreateView';\nimport CustomInventoryAnalysis from './components/CustomDashboard/CustomInventoryAnalysis';\nimport OperationTypeListView from './components/RequestSettings/OperationTypeListView';\nimport RequestImportView from './components/Request/RequestImportView';\nimport MilestoneListView from './components/RequestSettings/MilestoneListView';\nimport MilestoneTypeListView from './components/RequestSettings/MilestoneTypeListView';\nimport FormsSettingsListView from './components/FormsSettings/FormListView';\nimport RequestCreateIntegration from './components/Request/RequestCreateIntegration';\nimport ColorListView from './components/Colors/ColorsListView';\nimport DashboardStatsView, {\n  VDistributionDashboardStatsView, VInventoryDashboardStatsView, VPlanificationDashboardStatsView,\n  VUnitControlDashboardStatsView\n} from \"./components/Stats/DashboardStatsView\";\nimport DashboardStatsListView from \"./components/Stats/DashboardStatsListView\";\n\n\ndeclare let window: IWindow;\n\nconst store = configureStore();\n\nconst NoMatch = ({ location }: RouteComponentProps<{}>) => (\n  <div>\n    <h3>No match for <code>{location.pathname}</code></h3>\n  </div>\n);\nconst App = () => (\n  <Provider store={store}>\n    <ConnectedRouter history={history}>\n      <Switch>\n        <Route exact path='/' component={DashboardGeneralView} />\n        <Route exact path='/revision-report/' component={DashboardRevisionsView} />\n        <Route exact path='/cars/' component={DashboardVinView} />\n        <Route exact path='/planning/import/' component={PlanningImportView} />\n        <Route exact path='/planning/studio/' component={VPlanificationDashboardStatsView} />\n        <Route exact path='/planning/' component={PlanningListView} />\n        <Route exact path='/dashboard/damages/' component={DashboardDamagesView} />\n        <Route exact path='/dashboard/timing/' component={DashboardTimingView} />\n        <Route exact path='/dashboard/derco/' component={DashboardDercoView} />\n        <Route exact path='/dashboard/studio/' component={VUnitControlDashboardStatsView}  />\n        <Route exact path='/dashboard/custom-dashboard/' component={CustomDashboardComponent} />\n        <Route exact path='/forms/settings/forms/' component={FormsSettingsListView} />\n        <Route exact path='/stock/' component={StockView} />\n        <Route exact path='/stock/import/' component={StockImportView} />\n        <Route exact path='/cars/:id/' component={DashboardVinDetail} />\n        <Route exact path='/inventory/' component={InventoryListView} />\n        <Route exact path='/inventory/studio/' component={VInventoryDashboardStatsView} />\n        <Route exact path='/inventory/dashboard/' component={InventoryDashboardView} />\n        <Route exact path='/inventory/create/' component={InventoryCreateView} />\n        <Route exact path='/inventory/:id/' component={InventoryDetailView} />\n        <Route exact path='/inventory/:id/:tab/' component={InventoryDetailView} />\n        <Route exact path='/settings/users/' component={UsersListView} />\n        <Route exact path='/settings/cars/' component={CarsListView} />\n        <Route exact path='/settings/cars/import/' component={ImportCarsView} />\n        <Route exact path='/settings/cars/:id/' component={CarDetailView} />\n        <Route exact path='/settings/labels/' component={LabelsListView} />\n        <Route exact path='/settings/venues/' component={VenuesListView} />\n        <Route exact path='/settings/regions/' component={RegionsListView} />\n        <Route exact path='/settings/colors/' component={ColorListView} />\n        <Route exact path='/settings/carriers/' component={CarriersListView} />\n        <Route exact path='/settings/companies/' component={CompaniesListView} />\n        <Route exact path='/settings/alerts/' component={AlertsViews} />\n        <Route exact path='/settings/billing/' component={BillingListView} />\n        <Route exact path='/settings/versions/' component={VersionListView} />\n        <Route exact path='/settings/stats/' component={DashboardStatsListView} />\n        <Route exact path='/requests/create/' component={RequestCreateView} />\n        <Route exact path='/transmittals/' component={TransmittalListView} />\n        <Route exact path='/transmittals/create/' component={TransmittalCreateView} />\n        <Route exact path='/requests/' component={RequestListView} />\n        <Route exact path='/requests/settings/reasons/' component={RequestReasonListView} />\n        <Route exact path='/requests/settings/channels/' component={RequestChannelListView} />\n        <Route exact path='/requests/settings/payment-methods/' component={PaymentMethodListView} />\n        <Route exact path='/requests/settings/status/' component={RequestStatusListView} />\n        <Route exact path='/requests/settings/operations-type/' component={OperationTypeListView} />\n        <Route exact path='/transmittals/settings/milestone/' component={MilestoneListView} />\n        <Route exact path='/transmittals/settings/milestone-type/' component={MilestoneTypeListView} />\n        <Route exact path='/requests/import/' component={RequestImportView} />\n        <Route exact path='/requests/update/' component={RequestUpdaterView} />\n        <Route exact path='/requests/studio/' component={VDistributionDashboardStatsView} />\n        <Route exact path='/requests/vehicles/external/create/' component={RequestCreateIntegration} />\n        <Route exact path='/requests/vehicles/create' component={RequestCreateView} />\n        <Route exact path='/requests/vehicles/:id/' component={RequestDetailView} />\n        <Route exact path='/requests/vehicles/' component={RequestVehicleListView} />\n        <Route exact path='/requests/:id/' component={RequestDetailView} />\n        <Route component={NoMatch} />\n      </Switch>\n    </ConnectedRouter>\n  </Provider>\n);\nconst $body = $('body');\n// clear state of the modeal on hidden\n$body.on('hidden.bs.modal', '#andesModal', () => {\n  store.dispatch({\n    type: '/MODAL/CLEAR'\n  });\n});\n\n$(() => {\n  // add ekko-lightbox\n  const script = document.createElement('script');\n  const link = document.createElement('link');\n  link.rel = 'stylesheet';\n  link.href = isIntenertExplorer() ? '/static/js/vendor/lightbox/ekko-lightbox.css' : '/static/js/vendor/lightbox/ekko-lightbox.last.css';\n  const js = document.getElementsByClassName('js')[0];\n  script.src = isIntenertExplorer() ? '/static/js/vendor/lightbox/ekko-lightbox.min.js' : '/static/js/vendor/lightbox/ekko-lightbox.last.min.js';\n  js.appendChild(script);\n  js.appendChild(link);\n\n  moment.locale('es');\n  ReactDOM.render(\n    <App />,\n    document.querySelector('#app')\n  );\n  ($('.sidebar-menu') as any).tree();\n  $body.on('click', '.treeview-menu li', () => {\n    $body.removeClass('sidebar-open');\n  });\n  // ekk-lightbox\n  $(document).on('click', '[data-toggle=\"lightbox\"]', function(event) {\n    event.preventDefault();\n    ($(this) as any).ekkoLightbox();\n  });\n  // fix ekk-lightbox\n  $(document).on('hidden.bs.modal', () => {\n    if ($('.modal:visible').length) {\n      $body.addClass('modal-open');\n    }\n  });\n\n  $(document).on('click.bs.dropdown.data-api', '.dropdown.keep-inside-clicks-open', function(event) {\n    event.stopPropagation();\n  });\n  // prevenet show modal addons when is open and user change page\n  window.addEventListener('popstate', function(e) {\n    $('.modal-backdrop').remove();\n    $body.removeClass('modal-open');\n    // ($('#andesModal') as any).modal('hide');\n  });\n\n\n  ($ as any).AdminLTESidebarTweak = {};\n\n  ($ as any).AdminLTESidebarTweak.options = {\n    EnableRemember: true,\n    NoTransitionAfterReload: true\n    //Removes the transition after page reload.\n  };\n\n  $(function() {\n    'use strict';\n    $body.on('collapsed.pushMenu', function() {\n      if (($ as any).AdminLTESidebarTweak.options.EnableRemember) {\n        localStorage.setItem('toggleState', 'closed');\n      }\n    });\n\n    $body.on('expanded.pushMenu', function() {\n      if (($ as any).AdminLTESidebarTweak.options.EnableRemember) {\n        localStorage.setItem('toggleState', 'opened');\n      }\n    });\n    // $('.sidebar-menu a').on('click', function() {\n    //   const toggleState = localStorage.getItem('toggleState');\n    //   console.log(toggleState);\n    //   if(toggleState === 'closed'){\n    //     localStorage.setItem('toggleState', 'closed');\n    //     $body.addClass('sidebar-collapse');\n    //   }\n    // });\n\n    if (($ as any).AdminLTESidebarTweak.options.EnableRemember) {\n      const toggleState = localStorage.getItem('toggleState');\n      if (toggleState === 'closed') {\n        if (($ as any).AdminLTESidebarTweak.options.NoTransitionAfterReload) {\n          $body.addClass('sidebar-collapse hold-transition').delay(100).queue(function() {\n            $(this).removeClass('hold-transition');\n          });\n        } else {\n          $body.addClass('sidebar-collapse');\n        }\n      }\n    }\n  });\n});\n\nif (process.env.NODE_ENV !== 'development') {\n  // disable react debug\n  if (window.hasOwnProperty('__REACT_DEVTOOLS_GLOBAL_HOOK__')) {\n    window.__REACT_DEVTOOLS_GLOBAL_HOOK__._renderers = {};\n  }\n}\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport {IAlert} from '../../../../../../src/app/interfaces/alert.interface';\nimport {AlertReduxAction, createAlertAction, deleteAlertAction, getAlertsAction, IAlertsState} from '../../actions/alerts.actions';\nimport {loadDataAction, ModalReduxAction} from '../../actions/modal.actions';\nimport AppContainer from '../../container/AppContainer';\nimport {statusFooterButttonsModal} from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport AlertFormView from './AlertFormView';\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  alerts: IAlertsState;\n  dispatch: Dispatch<AlertReduxAction>;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n  getAlertsAction(): ModalReduxAction;\n\n  deleteAlertAction(id: string): ModalReduxAction;\n  createAlertAction(alert: ITempAlert): ModalReduxAction;\n}\n\ninterface ITempAlert {\n  name: string;\n  gte: number;\n  lte: number;\n  users: string[];\n  type: string;\n}\n\ninterface IStateType {\n  error: Error | null;\n  tempAlert: ITempAlert;\n}\n\nclass AlertViews extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  // static propTypes = {\n  //   alerts: PropTypes.object.isRequired,\n  //   dispatch: PropTypes.func.isRequired\n  // };\n\n  state = {\n    error: null,\n    tempAlert: {\n      name: '',\n      type: 'gte',\n      gte: 0,\n      lte: 0,\n      users: []\n    }\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = ' Listado de alertas';\n    this.changeTempAlert = this.changeTempAlert.bind(this);\n\n    this.addAlert = this.addAlert.bind(this);\n    this.processAddAlert = this.processAddAlert.bind(this);\n\n    this.deleteAlert = this.deleteAlert.bind(this);\n  }\n  componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public componentWillMount() {\n    this.props.getAlertsAction();\n  }\n\n  public componentWillUnmount() {\n    // cancel request if component is inmounted\n    if (this.props.alerts.source) {\n      this.props.alerts.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {alerts, loading} = this.props.alerts;\n    return (\n      <AppContainer title=\"\" cMenu=\"10\" cSubMenu=\"10.1\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Alertas <small>{alerts.length}</small></h3>\n              <div className=\"pull-right box-tools\">\n                <button className=\"btn btn-sm btn-success\" onClick={this.addAlert}>Agregar</button>\n              </div>\n            </div>\n            <div className=\"box-body no-padding\">\n              <table className=\"table table-andes table-striped\">\n                <thead>\n                  <tr>\n                    <th className=\"middle\">Nombre</th>\n                    <th className=\"middle text-center\">Menor igual que</th>\n                    <th className=\"middle text-center\">Mayor igual que</th>\n                    <th style={{width: '40%'}} className=\"middle hidden-xs\">Usuarios</th>\n                    {/*<th className=\"width-10\" />*/}\n                    <th className=\"middle width-10\" />\n                  </tr>\n                </thead>\n                <tbody>\n                {\n                  alerts.length ?\n                    alerts.map((alert) => {\n                      return (\n                        <tr\n                          key={alert._id}\n                          id={`alert-${alert._id}`}\n                          className={'background-transition'}\n                        >\n                          <td className=\"middle\">{alert.name}</td>\n                          <td className=\"middle text-center\">{alert.lte !== 0 ? alert.lte : '-'}</td>\n                          <td className=\"middle text-center\">{alert.gte !== 0 ? alert.gte : '-'}</td>\n                          <td className=\"hidden-xs\">\n                            {\n                              alert.users.map((user) => {\n                                return (\n                                  <p key={user._id} style={{margin: 0}}>{`${user.firstName} ${user.lastName} <${user.email}>`}</p>\n                                );\n                              })\n                            }\n                          </td>\n                          {/*<td className=\"text-blue pointer\" onClick={undefined}><i className=\"fa fa-pencil\"/></td>*/}\n                          <td className=\"text-red pointer\" onClick={() => this.deleteAlert(alert)}><i className=\"fa fa-minus-circle\"/></td>\n                        </tr>\n                      );\n                    }) : <tr>\n                      <td colSpan={5}>Aún no se han ingresado alertas</td>\n                    </tr>\n                }\n                </tbody>\n              </table>\n            </div>\n            {\n              loading &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private deleteAlert(alert: IAlert) {\n    // ask if you are sure that you are going to delete the alert?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar la alerta ${alert.name}`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteAlertAction(alert._id);\n      }\n    });\n  }\n\n  private addAlert() {\n    const {users} = this.props.alerts;\n    this.props.loadDataAction(\n      'Agregar Alerta',\n        <AlertFormView users={users} changeTempAlert={this.changeTempAlert} />\n      ,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-sm btn-primary\" onClick={this.processAddAlert}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private changeTempAlert(tempAlert: ITempAlert) {\n    this.setState({\n      tempAlert\n    });\n  }\n\n  private processAddAlert() {\n    const {tempAlert} = this.state;\n    const value = (tempAlert as any)[tempAlert.type];\n    if (tempAlert.name.trim().length === 0) {\n      swal('Agregar alerta', 'El campo nombre es requerido.', 'error');\n    } else if (tempAlert.users.length === 0) {\n      swal('Agregar alerta', 'Debe seleccionar al menos un usuario para notificar.', 'error');\n    } else if (!value || value === 0) {\n      swal('Agregar alerta', 'El valor para notificar debe ser entre 1 y 100.', 'error');\n    } else {\n      statusFooterButttonsModal(true);\n      this.props.createAlertAction(tempAlert);\n      // console.log('tempAlert', tempAlert);\n    }\n  }\n}\n\nconst mapStateToProps = (state: { alerts: IAlertsState }) => {\n  return {\n    alerts: state.alerts\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer)),\n    getAlertsAction: () => dispatch(getAlertsAction()),\n    deleteAlertAction: (id: string) => dispatch(deleteAlertAction(id)),\n    createAlertAction: (alert: ITempAlert) => dispatch(createAlertAction(alert))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(AlertViews);\n","import {AxiosError, AxiosResponse, CancelTokenSource} from 'axios';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport {IAlert} from '../../../../../src/app/interfaces/alert.interface';\nimport {IUser} from '../../../../../src/app/interfaces/user.interface';\nimport ApiService from '../utils/axios';\nimport {showModal, statusFooterButttonsModal} from '../utils/common';\n\nexport interface IAlertsState {\n  alerts: Array<IAlert>;\n  users: Array<IUser>;\n  loading: boolean;\n  source: CancelTokenSource | null;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface ICancelRequest {\n  type: '/ALERTS/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/ALERTS/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/ALERTS/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/ALERTS/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IDeleteAlert {\n  type: '/ALERTS/DELETE';\n  payload: {\n    id: string;\n  };\n}\n\nexport function deleteAlert(id: string): IDeleteAlert {\n  return {\n    type: '/ALERTS/DELETE',\n    payload: {\n      id\n    }\n  };\n}\n\nexport function deleteAlertAction(id: string) {\n  return (dispatch: Dispatch<AlertReduxAction>) => {\n    const api: ApiService = new ApiService();\n    api.deleteAlert(id)\n      .then((response: AxiosResponse) => {\n        const data = response.data;\n        swal(response.data.message, {\n          icon: 'success'\n        });\n        $(`#alert-${id}`)\n          .addClass('deleted-item');\n        setTimeout(() => {\n          dispatch(deleteAlert(data.id));\n        }, 500);\n      })\n      .catch((err: AxiosError) => {\n        api.errorHandler(err);\n      });\n  };\n}\n\ninterface ICreateAlert {\n  type: '/ALERTS/CREATE';\n  payload: {\n    alert: IAlert;\n  };\n}\n\nexport function createAlert(alert: IAlert): ICreateAlert {\n  return {\n    type: '/ALERTS/CREATE',\n    payload: {\n      alert\n    }\n  };\n}\n\nexport function createAlertAction(alert: any) {\n  return (dispatch: Dispatch<AlertReduxAction>) => {\n    dispatch(isLoadingAction(true));\n    const api: ApiService = new ApiService();\n    api.createAlert(alert)\n      .then((response: AxiosResponse) => {\n        const data = response.data;\n        statusFooterButttonsModal(false);\n        showModal(false);\n        dispatch(createAlert(data.alert));\n        dispatch(isLoadingAction(false));\n        swal(response.data.message, {\n          icon: 'success'\n        });\n      })\n      .catch((err: AxiosError) => {\n        api.errorHandler(err);\n        dispatch(isLoadingAction(false));\n      });\n  };\n}\n\ninterface ILoadAlerts {\n  type: '/ALERTS/LOAD_DATA';\n  payload: {\n    alerts: IAlert[];\n    users: IUser[];\n  };\n}\n\nexport function loadAlertsAction(alerts: IAlert[], users: IUser[]): ILoadAlerts {\n  return {\n    type: '/ALERTS/LOAD_DATA',\n    payload: {\n      alerts,\n      users\n    }\n  };\n}\n\nexport function getAlertsAction() {\n  return (dispatch: Dispatch<AlertReduxAction>) => {\n    const api: ApiService = new ApiService();\n    // dispatch(isLoadingAction(true));\n    dispatch(cancelRequestAction(api.getSource()));\n    api.getAlerts()\n      .then((response: AxiosResponse) => {\n        const data = response.data;\n        dispatch(loadAlertsAction(data.alerts, data.users));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport type AlertReduxAction =\n  ICancelRequest |\n  IIsLoading |\n  ILoadAlerts |\n  IDeleteAlert |\n  ICreateAlert;\n","import * as PropTypes from 'prop-types';\nimport * as React from 'react';\nimport {Link} from 'react-router-dom';\nimport menus from '../utils/menus';\n\ninterface IPropsType {\n  cMenu: string;\n  cSubMenu: string;\n  cAction?: string;\n}\n\nconst BreadcrumbApp: React.FunctionComponent<IPropsType> = (props) => {\n  const menu = menus.find((menu: any) => menu.id === props.cMenu);\n  if (menu) {\n    const subMenu = menu.items.find((item: any) => item.id === props.cSubMenu);\n    return (\n      <ol className=\"breadcrumb\">\n        <li><Link to={menu.url}><i className={`fa ${menu.icon}`}/>{menu.text}</Link></li>\n        {\n          props.cAction && props.cAction.length ?\n            subMenu ? <li><Link to={subMenu.url}>{subMenu.text}</Link></li> : null :\n            subMenu ? <li className=\"active\">{subMenu.text}</li> : null\n        }\n        {props.cAction && props.cAction.length && <li className=\"active\">{props.cAction}</li>}\n      </ol>\n    );\n  }\n  return null;\n};\n\n// BreadcrumbApp.propTypes = {\n//   cMenu: PropTypes.string.isRequired,\n//   cSubMenu: PropTypes.string.isRequired,\n//   cAction: PropTypes.string\n// };\n\nexport default BreadcrumbApp;\n","import * as React from 'react';\nimport * as moment from 'moment-timezone';\n\nconst FooterApp: React.StatelessComponent<{}> = () => {\n  return (\n    <footer className=\"main-footer\">\n      <div className=\"pull-right hidden-xs\"><b>Version</b> 2.1.3 stable</div>\n      <strong>Copyright (c) {moment().format('YYYY')} <a href=\"https://www.osa-app.cl\" target={'_blank'}>OSA SPA.</a></strong> All rights\n      reserved.\n    </footer>\n  );\n};\n\nFooterApp.propTypes = {\n};\n\nexport default FooterApp;\n","// import * as PropTypes from 'prop-types';\nimport * as React from 'react';\nimport {IWindow} from '../interfaces/window';\n\ndeclare let window: IWindow;\n\nclass HeaderApp extends React.Component<{}, {}> {\n  protected channel: BroadcastChannel;\n  protected existBC: boolean = window.hasOwnProperty('BroadcastChannel');\n\n  constructor(props: {}) {\n    super(props);\n    this.closeSesion = this.closeSesion.bind(this);\n  }\n\n  public componentDidMount() {\n    if (this.existBC) {\n      this.channel = new BroadcastChannel('andes');\n      this.channel.onmessage = (e) => {\n        if (e.data.close) {\n          location.href = '/account/logout/';\n        }\n      };\n    }\n  }\n\n  public componentWillUnmount() {\n    if (this.existBC) {\n      this.channel.close();\n    }\n  }\n\n  public render() {\n    return (\n      <header className=\"main-header\">\n        <a className=\"logo\" href=\"/\" style={{padding: '5px 15px'}}>\n          <span className=\"logo-mini\">&nbsp;</span>\n          <span className=\"logo-lg\"><img src=\"/static/images/OSA_andes_logo_horizontal.svg\" style={{maxHeight: '40px', verticalAlign: 'baseline'}}/></span>\n        </a>\n        <nav className=\"navbar navbar-static-top\">\n          <a className=\"sidebar-toggle hidden-sm hidden-md hidden-lg\" href=\"#\" data-toggle=\"push-menu\" role=\"button\">\n          {/*<a className=\"sidebar-toggle\" href=\"#\" data-toggle=\"push-menu\" role=\"button\">*/}\n            <span className=\"sr-only\">Toggle navigation</span>\n            <span className=\"icon-bar\"/>\n            <span className=\"icon-bar\"/>\n            <span className=\"icon-bar\"/>\n          </a>\n          <div className=\"navbar-custom-menu\">\n            <ul className=\"nav navbar-nav\">\n              {/*<li className=\"dropdown messages-menu\">*/}\n              {/*<a className=\"dropdown-toggle\" href=\"#\" data-toggle=\"dropdown\">*/}\n              {/*<i className=\"fa fa-envelope-o\" />*/}\n              {/*<span className=\"label label-success\">4</span>*/}\n              {/*</a>*/}\n              {/*<ul className=\"dropdown-menu\">*/}\n              {/*<li className=\"header\">You have 4 messages</li>*/}\n              {/*<li>*/}\n              {/*<ul className=\"menu\">*/}\n              {/*<li><a href=\"#\">*/}\n              {/*<div className=\"pull-left\">*/}\n              {/*<img className=\"img-circle\" src=\"/static/theme/dist/img/user2-160x160.jpg\" alt=\"User Image\" />*/}\n              {/*</div>*/}\n              {/*<h4>Support Team*/}\n              {/*<small><i className=\"fa fa-clock-o\" /> 5 mins</small>*/}\n              {/*</h4>*/}\n              {/*<p>Why not buy a new awesome theme?</p></a></li>*/}\n              {/*</ul>*/}\n              {/*</li>*/}\n              {/*<li className=\"footer\"><a href=\"#\">See All Messages</a></li>*/}\n              {/*</ul>*/}\n              {/*</li>*/}\n              {/*<li className=\"dropdown notifications-menu\">*/}\n              {/*<a className=\"dropdown-toggle\" href=\"#\" data-toggle=\"dropdown\">*/}\n              {/*<i className=\"fa fa-bell-o\" />*/}\n              {/*<span className=\"label label-warning\">10</span>*/}\n              {/*</a>*/}\n              {/*<ul className=\"dropdown-menu\">*/}\n              {/*<li className=\"header\">You have 10 notifications</li>*/}\n              {/*<li>*/}\n              {/*<ul className=\"menu\">*/}\n              {/*<li><a href=\"#\"><i className=\"fa fa-users text-aqua\" /> 5 new members joined today</a></li>*/}\n              {/*</ul>*/}\n              {/*</li>*/}\n              {/*<li className=\"footer\"><a href=\"#\">View all</a></li>*/}\n              {/*</ul>*/}\n              {/*</li>*/}\n              <li className=\"dropdown user user-menu\">\n                <a className=\"dropdown-toggle\" href=\"#\" data-toggle=\"dropdown\">\n                  <img className=\"user-image\" src=\"/static/images/icon_circular.png\" alt=\"User Image\"/>\n                  <span\n                    className=\"hidden-xs\">{`${window.user.firstName || ''} ${window.user.lastName || ''}${!window.user.firstName && !window.user.lastName ? 'Unknown User' : ''}`}</span>\n                </a>\n                <ul className=\"dropdown-menu\">\n                  <li className=\"user-header\">\n                    <img className=\"img-circle\" src=\"/static/images/icon_circular.png\" alt=\"User Image\"/>\n                    <p>{`${window.user.firstName || ''} ${window.user.lastName || ''}${!window.user.firstName && !window.user.lastName ? 'Unknown User' : ''}`}\n                      <small>{window.user.email || ''}</small>\n                    </p>\n                  </li>\n                  {/*<li className=\"user-body\">*/}\n                  {/*<div className=\"row\">*/}\n                  {/*<div className=\"col-xs-4 text-center\"><a href=\"#\">Followers</a></div>*/}\n                  {/*<div className=\"col-xs-4 text-center\"><a href=\"#\">Sales</a></div>*/}\n                  {/*<div className=\"col-xs-4 text-center\"><a href=\"#\">Friends</a></div>*/}\n                  {/*</div>*/}\n                  {/*</li>*/}\n                  <li className=\"user-footer\">\n                    {/*<div className=\"pull-left\"><a className=\"btn btn-default btn-flat\" href=\"#\">Profile</a></div>*/}\n                    <div className=\"pull-right\">\n                      <a\n                        className=\"btn btn-sm btn-default btn-flat\"\n                        href=\"/account/logout/\"\n                        onClick={this.closeSesion}\n                      >\n                        Cerrar sesión\n                      </a>\n                    </div>\n                  </li>\n                </ul>\n              </li>\n              {/*<li><a href=\"#\" data-toggle=\"control-sidebar\"><i className=\"fa fa-gears\"></i></a></li>*/}\n            </ul>\n          </div>\n        </nav>\n      </header>\n    );\n  }\n  private closeSesion() {\n    if (this.existBC) {\n      this.channel.postMessage({\n        close: true\n      });\n    }\n  }\n}\n\nexport default HeaderApp;\n","import * as PropTypes from 'prop-types';\nimport * as React from 'react';\nimport {Link} from 'react-router-dom';\nimport menus from '../utils/menus';\n\ninterface IPropsType {\n  cMenu: string;\n  cSubMenu: string;\n}\n\nclass MenuApp extends React.Component<IPropsType, {}> {\n\n  static propTypes = {\n    cMenu: PropTypes.string.isRequired,\n    cSubMenu: PropTypes.string.isRequired\n  };\n\n  public componentDidMount(): void {\n    ($('.sidebar-menu') as any).tree();\n  }\n\n  public render() {\n    const {cMenu, cSubMenu} = this.props;\n\n    return (\n      <aside className=\"main-sidebar\">\n        <section className=\"sidebar\">\n          <ul className=\"sidebar-menu\" data-widget=\"tree\">\n            <li className=\"header\">MENÚ</li>\n            {\n              menus.map((menu: any) => {\n                return (\n                  <li className={`treeview ${menu.id === cMenu ? 'active menu-open' : ''}`} key={menu.id}>\n                    <a href=\"#\">\n                      <i className={`fa ${menu.icon}`}/> <span>{menu.text}</span>\n                      <span className=\"pull-right-container\">\n                      <i className=\"fa fa-angle-left pull-right\"/>\n                    </span>\n                    </a>\n                    <ul className=\"treeview-menu\">\n                      {\n                        menu.items.map((item: any) => {\n                          return (\n                            <li key={item.id} className={item.id === cSubMenu ? 'active' : ''}>\n                              <Link to={item.url}><i className={`fa ${item.icon}`}/> {item.text}</Link>\n                            </li>\n                          );\n                        })\n                      }\n                    </ul>\n                  </li>\n                );\n              })\n            }\n          </ul>\n        </section>\n      </aside>\n    );\n  }\n}\n\nexport default MenuApp;\n","import * as PropTypes from 'prop-types';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {IUser} from '../../../../../../src/app/interfaces/user.interface';\n\ninterface IPropsType {\n  users: IUser[];\n  changeTempAlert: (tempAlert: ITempAlert) => void;\n}\n\ninterface ITempAlert {\n  name: string;\n  gte: number;\n  lte: number;\n  users: string[];\n  type: string;\n}\n\ninterface IStateType {\n  error: Error | null;\n  tempAlert: ITempAlert;\n  currentUser: string;\n}\n\nclass AlertFormView extends React.Component<IPropsType, IStateType> {\n\n  static propTypes = {\n    users: PropTypes.array.isRequired\n  };\n\n  readonly state = {\n    error: null,\n    currentUser: '',\n    tempAlert: {\n      name: '',\n      type: 'lte',\n      gte: 0,\n      lte: 0,\n      users: []\n    }\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.onChangeSelectUser = this.onChangeSelectUser.bind(this);\n    this.addUser = this.addUser.bind(this);\n    this.changeQualification = this.changeQualification.bind(this);\n    this.onChangeType = this.onChangeType.bind(this);\n    this.onChangeName = this.onChangeName.bind(this);\n    this.deleteUser = this.deleteUser.bind(this);\n  }\n\n  public componentDidMount() {\n    ($('#user-select') as any).chosen().change((e: React.ChangeEvent<HTMLSelectElement>) => {\n      this.onChangeSelectUser(e);\n      // console.log(e.target.value)\n    });\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  componentDidUpdate() {\n    $('#user-select').trigger('chosen:updated');\n    this.props.changeTempAlert(this.state.tempAlert);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { users } = this.props;\n    const { tempAlert } = this.state;\n    const usersToNotify = users.filter((user) => (tempAlert.users as string[]).includes(user._id));\n    return (\n      <div className={'row'}>\n        <div className=\"col-md-12\">\n          <div className=\"form-group\">\n            <label>Nombre</label>\n            <input\n              type=\"text\"\n              className=\"form-control\"\n              maxLength={200}\n              onChange={this.onChangeName}\n            />\n          </div>\n        </div>\n        <div className=\"col-md-12\">\n          <div className=\"form-group\">\n            <label>Usuarios a notificar</label>\n            <select\n              id=\"user-select\"\n              className=\"chosen-select form-control\"\n              style={{minWidth: '200px'}}\n              onChange={this.onChangeSelectUser}\n              data-placeholder={'Seleccione usuarios'}\n            >\n              <option value=\"\" />\n              {\n                users.filter((user) => !(tempAlert.users as string[]).includes(user._id)).map((user) => {\n                  return (\n                    <option key={user._id} value={user._id}>{user.firstName} {user.lastName} {`<${user.email}>`}</option>\n                  );\n                })\n              }\n            </select>\n            {/*<span className=\"input-group-btn\">*/}\n              {/*<button className=\"btn btn-success\" onClick={this.addUser}>agregar</button>*/}\n            {/*</span>*/}\n          </div>\n        </div>\n        <div className=\"col-md-12\">\n          <table className=\"table table-striped\">\n            <thead>\n              <tr>\n                <th style={{width: '40%'}}>Nombre</th>\n                <th style={{width: '50%'}}>Email</th>\n                <th style={{width: '10%'}}/>\n              </tr>\n            </thead>\n            <tbody>\n            {\n              usersToNotify.length ? usersToNotify.map((user) => {\n                return (\n                  <tr key={user._id}>\n                    <td>{user.firstName} {user.lastName}</td>\n                    <td>{user.email}</td>\n                    <td className=\"text-center text-red pointer\" onClick={() => this.deleteUser(user._id)}><i className=\"fa fa-minus-circle\"/></td>\n                  </tr>\n                );\n                }) :\n              <tr>\n                <td colSpan={3}>Aún no se han seleccionado usuarios.</td>\n              </tr>\n            }\n            </tbody>\n          </table>\n        </div>\n        <div className=\"col-md-12\">\n          <div className=\"form-group\" style={{marginBottom: '0px'}}>\n            <label>Notificar cuando la calificación sea:</label>\n          </div>\n          <div>\n            <label className=\"radio-inline\">\n              <input type=\"radio\" value=\"lte\" checked={this.state.tempAlert.type === 'lte'} onChange={this.onChangeType}/>\n              Menor igual que\n            </label>\n            <label className=\"radio-inline\">\n              <input type=\"radio\" value=\"gte\" checked={this.state.tempAlert.type === 'gte'} onChange={this.onChangeType}/>\n              Mayor igual que\n            </label>\n            <input\n              type=\"text\"\n              className=\"form-control\"\n              maxLength={4}\n              onChange={this.changeQualification}\n              value={this.state.tempAlert.type === 'gte' ? this.state.tempAlert.gte : this.state.tempAlert.lte}\n              style={{marginTop: '10px'}}\n            />\n          </div>\n        </div>\n      </div>\n    );\n  }\n\n  private onChangeName(e: React.ChangeEvent<HTMLInputElement>) {\n    this.setState({\n      tempAlert: {\n        ...this.state.tempAlert,\n        name: e.target.value.trim()\n      }\n    });\n  }\n\n  private changeQualification(e: React.ChangeEvent<HTMLInputElement>) {\n    const pattern = new RegExp(/[^\\d]/g);\n    const value = e.target.value.replace(pattern, '');\n    if (value && value.length) {\n      const numberValue = parseInt(value, 10);\n      this.setState({\n        tempAlert: {\n          ...this.state.tempAlert,\n          [this.state.tempAlert.type]: numberValue > 100 ? 100 : numberValue\n        }\n      });\n    } else {\n      this.setState({\n        tempAlert: {\n          ...this.state.tempAlert,\n          [this.state.tempAlert.type]: ''\n        }\n      });\n    }\n  }\n\n  private onChangeType(e: React.ChangeEvent<HTMLInputElement>) {\n    this.setState({\n      tempAlert: {\n        ...this.state.tempAlert,\n        type: e.target.value,\n        gte: e.target.value === 'gte' ? this.state.tempAlert.lte : 0,\n        lte: e.target.value === 'gte' ? 0 : this.state.tempAlert.gte\n      }\n    });\n  }\n\n  private onChangeSelectUser(e: React.ChangeEvent<HTMLSelectElement>) {\n    if (e.target.value) {\n      this.setState({\n        currentUser: e.target.value\n      }, () => this.addUser());\n    }\n  }\n\n  private deleteUser(id: string) {\n    this.setState({\n      tempAlert: {\n        ...this.state.tempAlert,\n        users: this.state.tempAlert.users.filter((user) => id !== user)\n      }\n    });\n  }\n\n  private addUser() {\n    if (this.state.currentUser && this.state.currentUser.length) {\n      this.setState({\n        currentUser: '',\n        tempAlert: {\n          ...this.state.tempAlert,\n          users: [this.state.currentUser, ...this.state.tempAlert.users]\n        }\n      });\n    }\n  }\n}\n\nexport default AlertFormView;\n","import * as Mixpanel from 'mixpanel-browser';\nimport {IUser} from \"../../../../../../src/app/interfaces/user.interface\";\nimport {IWindow} from \"../../interfaces/window\";\n\ndeclare let window: IWindow;\n\nclass MixpanelTracker {\n  private static instance : MixpanelTracker;\n\n  static getInstance() : MixpanelTracker {\n    if (!this.instance)\n      this.instance = new MixpanelTracker();\n    return this.instance;\n  }\n\n  private constructor() {\n    Mixpanel.init(window.MIXPANEL);\n  }\n\n  public trackAction(title: string, properties: any = {}) : void {\n    Mixpanel.track(title, properties);\n  }\n\n  public identifyUser(user : IUser) : void {\n    Mixpanel.register({\n      'team': user.team.name,\n      'team_id': user.team._id,\n      'company': user.company.name,\n      'company_id': user.company._id,\n      'venue': user.venue.name,\n      'venue_id': user.venue._id,\n    });\n    Mixpanel.identify(user._id);\n    Mixpanel.people.set( user._id, {\n      '$first_name': user.firstName,\n      '$last_name': user.lastName,\n      '$email': user.email,\n      'team': user.team.name,\n      'team_id': user.team._id,\n      'company': user.company.name,\n      'company_id': user.company._id,\n      'venue': user.venue.name,\n      'venue_id': user.venue._id,\n    });\n  }\n\n}\n\nexport default MixpanelTracker;\n","import * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport {\n  BillingReduxAction,\n  getBillingAction,\n  IBillingState\n} from '../../actions/billing.actions';\nimport AppContainer from '../../container/AppContainer';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\n\ninterface IPropsType extends RouteComponentProps<{ }> {\n  dispatch: Dispatch<BillingReduxAction>;\n  billing: IBillingState;\n\n  getBillingAction(page: number): BillingReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass BillingListView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  readonly state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Billing';\n    this.changePage = this.changePage.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const {pagination} = this.props.billing;\n    this.props.getBillingAction(pagination.page);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if(this.props.billing.pagination !== prevProps.billing.pagination){\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    window.scrollTo(0, 0);\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.billing.source) {\n      this.props.billing.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public render() {\n    const {pagination, loading, invoices} = this.props.billing;\n    return (\n      <AppContainer title=\"\" cMenu=\"10\" cSubMenu=\"10.8\" cAction=\"Detalle\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Billing <small>{pagination.count}</small></h3>\n            </div>\n            <div className={`box-body ${invoices.length ? 'no-padding' : ''}`}>\n              {\n                !loading && !invoices.length?\n                  <div className=\"row\">\n                    <div className=\"col-md-12\">\n                      <p>No se han encontrado resultados.</p>\n                    </div>\n                  </div>\n                  :null\n              }\n              {\n                invoices.length ?\n                  <table className=\"table\">\n                    <thead>\n                      <tr>\n                        <th className=\"middle\">Período</th>\n                        <th className=\"middle\">Empresa</th>\n                        <th className=\"middle\">Unidades en Inventario</th>\n                        <th className=\"middle\">Unidades en Checklist</th>\n                        <th className=\"middle\">Unidades en Solicitudes</th>\n                        {/*<th className=\"middle\">Valor Inventario</th>*/}\n                        {/*<th className=\"middle\">Valor Checklist</th>*/}\n                        <th className=\"middle\">Total</th>\n                        <th style={{width: '80px'}} />\n                      </tr>\n                    </thead>\n                    <tbody>\n                      {\n                        invoices.map((invoice)=>(\n                          <tr key={invoice._id}>\n                            <td>\n                              {\n                                moment(invoice.createdAt).subtract(1, 'month').format('MMMM YYYY')\n                              }\n                            </td>\n                            <td>{invoice.company.name}</td>\n                            <td>{invoice.inventoryCars}</td>\n                            <td>{invoice.checklistCars}</td>\n                            <td>{invoice.requestCars}</td>\n                            {/*<td>{invoice.inventoryPrice} UF</td>*/}\n                            {/*<td>{invoice.checklistPrice} UF</td>*/}\n                            <td>{invoice.totalUF.toFixed(2)} UF</td>\n                            <td>\n                              <button\n                                className=\"btn btn-xs btn-primary hidden-xs\"\n                                onClick={()=>window.open(`/settings/billing/pdf/${invoice._id}`,'_blank')}\n                              >\n                                <i className=\"fa fa-fw fa-download\" /> Billing\n                              </button>\n                            </td>\n                          </tr>\n                        ))\n                      }\n                    </tbody>\n                  </table>\n                  : null\n              }\n            </div>\n            {\n              pagination.pages > 1 &&\n              <div className=\"box-footer text-right\">\n                <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages}/>\n              </div>\n            }\n            {\n              loading &&\n              <div className=\"overlay\">\n                <i className=\"fa fa-spinner fa-spin text-purple\"/>\n              </div>\n            }\n          </div>\n          <ModalView/>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    this.props.getBillingAction(page);\n  }\n}\n\nconst mapStateToProps = (state: { billing: IBillingState }) => {\n  return {\n    billing: state.billing\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getBillingAction: (page: number) => dispatch(getBillingAction(page))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(BillingListView);\n","import {IInvoice} from '../../../../../src/billing/interfaces/invoice.interface';\nimport {AxiosError, AxiosResponse, CancelTokenSource, default as Axios} from \"axios\";\nimport {Dispatch} from \"redux\";\nimport ApiService from \"../utils/axios\";\n\nexport interface IBillingState {\n  invoices: IInvoice[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface ICancelRequest {\n  type: '/BILLING/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/BILLING/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/BILLING/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/BILLING/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IChangePage {\n  type: '/BILLING/CHANGE_PAGE';\n  payload: {\n    page: number;\n  };\n}\n\nexport function changePageAction(page: number): IChangePage {\n  return {\n    type: '/BILLING/CHANGE_PAGE',\n    payload: {\n      page\n    }\n  };\n}\n\ninterface ILoadBilling {\n  type: '/BILLING/LOAD_BILLING';\n  payload: {\n    invoices: any;\n    count: number;\n    pages: number\n  };\n}\n\nexport function loadBillingAction(invoices: any, count: number, pages: number): ILoadBilling {\n  return {\n    type: '/BILLING/LOAD_BILLING',\n    payload: {\n      invoices,\n      count,\n      pages\n    }\n  };\n}\n\nexport function getBillingAction(nextPage: number) {\n  return (dispatch: Dispatch<BillingReduxAction>, getState: () => {labels: IBillingState}) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    if (nextPage && nextPage !== state.labels.pagination.page) {\n      dispatch(isLoadingAction(true));\n    }\n    dispatch(cancelRequestAction(api.getSource()));\n    const page = nextPage ? nextPage : state.labels.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n    api.getBilling(page)\n      .then((response: AxiosResponse) => {\n        dispatch(loadBillingAction(response.data.results, response.data.count, response.data.pages));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\nexport type BillingReduxAction = IIsLoading\n  | ICancelRequest\n  | ILoadBilling\n  | IChangePage;\n","import * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport {ErrorInfo} from 'react';\nimport * as React from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport {\n  IBaseCarrier, ICarrier\n} from '../../../../../../src/app/interfaces/carrier.interface';\nimport {\n  CarrierReduxAction,\n  changeTempCarrierAction,\n  createCarrierAction, deleteCarrierAction,\n  getCarriersAction,\n  ICarriersState,\n  updateCarrierAction\n} from '../../actions/carriers.actions';\nimport {loadDataAction, ModalReduxAction} from '../../actions/modal.actions';\nimport AppContainer from '../../container/AppContainer';\nimport {IWindow} from '../../interfaces/window';\nimport {hasPermission} from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport CarriersFormView from './CarriersFormView';\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\n\ninterface IPropsType extends RouteComponentProps<{ carrier: string }> {\n  dispatch: Dispatch<CarrierReduxAction>;\n  carriers: ICarriersState;\n\n  createCarrierAction(): CarrierReduxAction;\n  updateCarrierAction(): CarrierReduxAction;\n\n  deleteCarrierAction(id: string): CarrierReduxAction;\n  changeTempCarrierAction(carrier: IBaseCarrier, delay?: boolean): CarrierReduxAction;\n  getCarriersAction(page: number): CarrierReduxAction;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass CarriersListView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de transportistas';\n    this.createCarrier = this.createCarrier.bind(this);\n    this.processCreateCarrier = this.processCreateCarrier.bind(this);\n    this.updateCarrier = this.updateCarrier.bind(this);\n    this.processUpdateCarrier = this.processUpdateCarrier.bind(this);\n    this.deleteCarrier = this.deleteCarrier.bind(this);\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public componentWillMount(): void {\n    const {pagination} = this.props.carriers;\n    this.props.getCarriersAction(pagination.page);\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.carriers.source) {\n      this.props.carriers.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {loading, carriers, pagination} = this.props.carriers;\n    return (\n      <AppContainer title=\"\" cMenu=\"10\" cSubMenu=\"10.6\" cAction=\"Listado\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\"><h3 className=\"box-title\">Transportistas <small>{pagination.count}</small></h3>\n              {\n                hasPermission(window.user, 'addCarrier') ?\n                  <div className=\"box-tools pull-right\">\n                    <button className=\"btn btn-sm btn-success\" onClick={this.createCarrier}><i className=\"fa fa-plus\" /> Agregar</button>\n                  </div>\n                  : null\n              }\n            </div>\n            <div className=\"box-body no-padding\">\n              <table className=\"table table-andes table-striped\">\n                <thead>\n                  <tr>\n                    <th style={{width: '60%'}} className=\"middle\">Nombre</th>\n                    <th style={{width: '20%'}} className=\"middle hidden-xs\">Modificado</th>\n                    {\n                      hasPermission(window.user, 'changeCarrier') ?\n                        <th style={{width: '1%'}} className=\"width-10\"/> : null\n                    }\n                    {\n                      hasPermission(window.user, 'deleteCarrier') ?\n                        <th style={{width: '1%'}} className=\"width-10\"/> : null\n                    }\n                  </tr>\n                </thead>\n                <tbody>\n                  {\n                    carriers.map((carrier: ICarrier) => {\n                      return (\n                        <tr\n                          key={carrier._id}\n                          id={`carrier-${carrier._id}`}\n                          className={'background-transition'}\n                        >\n                          <td className=\"middle\">{carrier.name}</td>\n                          <td className=\"middle hidden-xs\">{moment(carrier.updatedAt).format('LLL')}</td>\n                          {\n                            hasPermission(window.user, 'changeCarrier') ?\n                              <td\n                                className=\"middle text-blue pointer\"\n                                onClick={() => this.updateCarrier(carrier)}\n                              >\n                                <i className=\"fa fa-pencil\"/>\n                              </td> : null\n                          }\n                          {\n                            hasPermission(window.user, 'deleteCarrier') ?\n                              <td\n                                className={'middle text-red pointer'}\n                                onClick={() => this.deleteCarrier(carrier)}\n                              ><i className=\"fa fa-minus-circle\"/></td> : null\n                          }\n                        </tr>\n                      );\n                    })\n                  }\n                </tbody>\n              </table>\n            </div>\n            {\n              pagination.pages > 1 &&\n                <div className=\"box-footer text-right\">\n                  <Paginator changePage={this.props.getCarriersAction} page={pagination.page} pages={pagination.pages} />\n                </div>\n            }\n            {\n              loading &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private createCarrier(): void {\n    this.props.changeTempCarrierAction({\n      _id: '',\n      name: ''\n    });\n    this.props.loadDataAction(\n      'Agregar Transportista',\n      <CarriersFormView/>,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processCreateCarrier}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processCreateCarrier(): void {\n    const {tempCarrier} = this.props.carriers;\n    if (!tempCarrier.name || !tempCarrier.name.trim()) {\n      swal('Agregar Transportista', 'El nombres es requerido', 'error');\n    } else {\n      this.props.createCarrierAction();\n    }\n  }\n\n  private updateCarrier(carrier: ICarrier): void {\n    const {_id, name} = carrier;\n    this.props.changeTempCarrierAction({_id, name});\n    this.props.loadDataAction(\n      'Editar Transportista',\n      <CarriersFormView update={true}/>,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processUpdateCarrier}>Editar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processUpdateCarrier(): void {\n    const {tempCarrier} = this.props.carriers;\n    if (!tempCarrier.name || !tempCarrier.name.trim()) {\n      swal('Editar Transportista', 'El nombres es requerido', 'error');\n    } else {\n      this.props.updateCarrierAction();\n    }\n  }\n\n  private deleteCarrier(carrier: ICarrier): void {\n     // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar al transportista ${carrier.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteCarrierAction(carrier._id);\n      }\n    });\n  }\n}\n\nconst mapStateToProps = (state: { carriers: ICarriersState }) => {\n  return {\n    carriers: state.carriers\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getCarriersAction: (page: number) => dispatch(getCarriersAction(page)),\n    createCarrierAction: () => dispatch(createCarrierAction()),\n    updateCarrierAction: () => dispatch(updateCarrierAction()),\n    deleteCarrierAction: (id: string) => dispatch(deleteCarrierAction(id)),\n    changeTempCarrierAction: (carrier: IBaseCarrier, delay?: boolean) => dispatch(changeTempCarrierAction(carrier, delay)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{carriers: ICarriersState}, {dispatch: any}, IPropsType>(mapStateToProps, mapDispatchToProps)(CarriersListView);\n","import * as React from 'react';\nimport {connect} from 'react-redux';\nimport {\n  IBaseCarrier\n} from '../../../../../../src/app/interfaces/carrier.interface';\nimport {\n  CarrierReduxAction,\n  changeTempCarrierAction,\n  ICarriersState\n} from '../../actions/carriers.actions';\n\ninterface IPropsType {\n  carriers?: ICarriersState;\n  update?: boolean;\n  changeTempCarrierAction?: (carrier: IBaseCarrier, delay?: boolean) => CarrierReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass CarriersFormView extends React.Component<IPropsType, IStateType> {\n\n  render(): React.ReactElement<IPropsType> | null {\n    if (this.props.carriers && this.props.changeTempCarrierAction) {\n      const {tempCarrier} = this.props.carriers;\n      const {changeTempCarrierAction} = this.props;\n      return (\n        <div className=\"row\">\n          <div className=\"col-md-12\">\n            <div className=\"form-group\">\n              <label>Nombre</label>\n              <input\n                type=\"text\"\n                name=\"fistName\"\n                className=\"form-control\"\n                maxLength={50}\n                value={tempCarrier ? tempCarrier.name : ''}\n                onChange={\n                  (e: React.ChangeEvent<HTMLInputElement>) => changeTempCarrierAction({\n                    ...tempCarrier,\n                    name: e.target.value.trim()\n                  })\n                }\n              />\n            </div>\n          </div>\n        </div>\n      );\n    }\n    return null;\n  }\n}\n\nconst mapStateToProps = (state: { carriers: ICarriersState }) => {\n  return {\n    carriers: state.carriers\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    changeTempCarrierAction: (carrier: IBaseCarrier, delay?: boolean) => dispatch(changeTempCarrierAction(carrier, delay))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(CarriersFormView);\n","// import * as PropTypes from 'prop-types';\nimport * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport {ErrorInfo} from 'react';\nimport * as React from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport {IParticipant} from '../../../../../../src/form/interfaces/participant.interface';\nimport {CarReduxAction, getCarAction, ICarsState} from '../../actions/cars.actions';\nimport {getParticipant, IDashboardState, loadParticipantInCarAction} from '../../actions/dashboard.actions';\nimport AppContainer from '../../container/AppContainer';\nimport {IWindow} from '../../interfaces/window';\nimport ModalView from '../Modal/ModalView';\nimport Row from '../Utils/Row';\nimport TimeLineForm from './TimeLineForm';\nimport TimeLineInventory from './TimeLineInventory';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\n\ndeclare let window: IWindow;\n\ninterface IPropsType extends RouteComponentProps<{ id: string }> {\n  dispatch: Dispatch<CarReduxAction>;\n  cars: ICarsState;\n  dashboard: IDashboardState;\n  getCarAction(id: string): void;\n  getParticipant(id: string): void;\n\n  loadParticipantInCarAction(participant: IParticipant): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass CarDetailView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  state = {\n    error: null,\n    highlight: []\n  };\n\n  constructor(props : IPropsType) {\n    super(props);\n    this.title = 'Detalle VIN';\n  }\n\n  componentWillMount() {\n    const {id} = this.props.match.params;\n    this.props.getCarAction(id);\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentWillUnmount() {\n    // cancel request if component is inmounted\n    if (this.props.cars.source) {\n      this.props.cars.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {loading, car, carEvents} = this.props.cars;\n    const {loadingParticipant} = this.props.dashboard;\n    const {getParticipant} = this.props;\n    return (\n      <AppContainer title={`Detalle VIN ${car ? car.vin : null}`} cMenu=\"10\" cSubMenu=\"10.2\"  cAction=\"Detalle Vehículo\">\n        <section className=\"content\">\n          <Row>\n            <div className=\"col col-md-3\">\n              <div className=\"box box-primary\">\n                <div className=\"box-body box-profile\">\n                  {/*<ImageLazyLoad url={decodeURI(image.file.url)} height={'100px'} maxHeight={'100px'} maxWidth={'100px'} small={true}/>*/}\n                  {/*<img*/}\n                    {/*className=\"profile-user-img img-responsive img-circle\"*/}\n                    {/*src=\"https://cdn.forbes.com.mx/2018/03/Auto-Carretera-1280x720.jpg\"*/}\n                    {/*alt=\"User profile picture\"*/}\n                    {/*style={{*/}\n                      {/*fontFamily: 'object-fit:cover',*/}\n                      {/*objectFit: 'cover',*/}\n                      {/*width: '100px',*/}\n                      {/*height: '100px'*/}\n                    {/*}}*/}\n                  {/*/>*/}\n                  <h3 className=\"profile-username text-center\">{car && car.brand ? car.brand : '-'}</h3>\n                  <p className=\"text-muted text-center\">{car && car.denomination ? car.denomination : '-'}</p>\n                  <ul className=\"list-group list-group-unbordered\">\n                    <li className=\"list-group-item\">\n                      <strong>VIN</strong>\n                      <a className=\"pull-right\">\n                        {\n                          car && car.vin ? car.vin : '-'\n                        }\n                      </a>\n                    </li>\n                    <li className=\"list-group-item\">\n                      <strong>Nº Interno</strong>\n                      <a className=\"pull-right\">\n                        {\n                          car && car.internalNumber ? car.internalNumber : '-'\n                        }\n                      </a>\n                    </li>\n                    <li className=\"list-group-item\">\n                      <strong>Patente</strong>\n                      <a className=\"pull-right\">\n                        {\n                          car && car.patent ? car.patent : '-'\n                        }\n                      </a>\n                    </li>\n                    <li className=\"list-group-item\">\n                      <strong>Color</strong>\n                      <a className=\"pull-right\">\n                        {\n                          car && car.color ? car.color : '-'\n                        }\n                      </a>\n                    </li>\n                    <li className=\"list-group-item\">\n                      <strong>Revisiones</strong>\n                      <a className=\"pull-right\">\n                        {\n                          car && car.participants ? car.participants.length : 0\n                        }\n                      </a>\n                    </li>\n                    <li className=\"list-group-item\">\n                      <strong>Inventarios</strong>\n                      <a className=\"pull-right\">\n                        {\n                          car && car.inventories ? car.inventories.length : 0\n                        }\n                      </a>\n                    </li>\n                  </ul>\n                    {/*<a href=\"#\" className=\"btn btn-primary btn-block\"><b>Follow</b></a>*/}\n                </div>\n              </div>\n            </div>\n            <div className=\"col col-md-9\">\n              {\n                loading ?\n                  <div className=\"box\">\n                    <div className=\"box-body text-center\">\n                      <p>&nbsp;</p>\n                    </div>\n                      <div className=\"overlay\">\n                        <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                      </div>\n                  </div> :\n                  <div className=\"nav-tabs-custom\">\n                    <ul className=\"nav nav-tabs\">\n                      <li className=\"active\"><a href=\"#timeline\" data-toggle=\"tab\" aria-expanded=\"true\">Timeline</a></li>\n                    </ul>\n                    <div className=\"tab-content\" style={{\n                      backgroundColor: '#f9f9f9'\n                      // maxHeight: '80vh',\n                      // overflowX: 'auto'\n                    }}>\n                      <div className=\"tab-pane active\" id=\"timeline\">\n                        <ul className=\"timeline\">\n                          {\n                            Object.keys(carEvents).map((event) => {\n                              const events = carEvents[event];\n                              return <React.Fragment key={event}>\n                                <li className=\"time-label\">\n                                  <span className=\"bg-blue\">\n                                      {moment(event).format('MMMM YYYY')}\n                                  </span>\n                                </li>\n                                {\n                                  events.map((data: any) => {\n                                    return (\n                                      data.typeEvent === 'created' ?\n                                        <li style={{marginRight: '0'}} key={data._id}>\n                                          <i className={`fa fa-cloud-upload bg-green`}/>\n                                          <div className=\"timeline-item\">\n                                            <span className=\"time\" style={{\n                                              color: '#888',\n                                              fontSize: '13px'\n                                            }}>\n                                              <i className=\"fa fa-fw fa-calendar-o\"/> {data.createdAt.format('LL')}\n                                            </span>\n                                            <h3 className=\"timeline-header\"><a href=\"javascript:void(0)\">VEHÍCULO IMPORTADO</a></h3>\n                                            <div className=\"timeline-body\">\n                                              El vehículo fue importado al sistema\n                                              el {data.createdAt.format('LLLL')}.\n                                            </div>\n                                          </div>\n                                        </li>\n                                        : data.typeEvent === 'revision' ?\n                                        <TimeLineForm form={data} getParticipant={getParticipant} loadingParticipant={loadingParticipant} key={data._id}/>\n                                        : <TimeLineInventory inventory={data} key={data._id}/>\n                                    );\n                                  })\n                                }\n                              </React.Fragment>;\n                            })\n                          }\n                          <li>\n                            <i className=\"fa fa-clock-o bg-gray\"/>\n                          </li>\n                        </ul>\n                      </div>\n                    </div>\n                  </div>\n              }\n            </div>\n          </Row>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n}\n\nconst mapStateToProps = (state: { cars: ICarsState, dashboard: IDashboardState }) => {\n  return {\n    cars: state.cars,\n    dashboard: state.dashboard\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getCarAction: (id: string) => dispatch(getCarAction(id)),\n    getParticipant: (id: string) => dispatch(getParticipant(id)),\n    loadParticipantInCarAction: (participant: IParticipant) => dispatch(loadParticipantInCarAction(participant))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(CarDetailView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport Row from '../Utils/Row';\n\ninterface IPropsType {\n  form: any;\n  loadingParticipant: string | null;\n\n  getParticipant(id: string): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass TimeLineForm extends React.Component<IPropsType, IStateType> {\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.getColorByDamage = this.getColorByDamage.bind(this);\n    this.getIconDamage = this.getIconDamage.bind(this);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  render(): React.ReactElement<IPropsType> {\n    const { form, loadingParticipant } = this.props;\n    return (\n\n      <li style={{ marginRight: '0' }}>\n        <i className={`fa ${this.getIconDamage(form.hasDamages)} $ ${this.getColorByDamage(form.hasDamages)}`} />\n        <div className='timeline-item'>\n          <span className='time' style={{\n            color: '#888',\n            fontSize: '13px'\n          }}>\n            <i className='fa fa-fw fa-calendar-o' /> {form.createdAt.format('LL')}\n          </span>\n\n          <h3 className='timeline-header'><a href='javascript:void(0)'>{form.name}</a></h3>\n\n          <div className='timeline-body'>\n            {\n              form.form.reception ?\n                <React.Fragment>\n                  El vehículo fue recepcionado\n                  {\n                    form.venue ?\n                      <React.Fragment> en <span className='text-blue'>{form.venue.name}</span></React.Fragment>\n                      : ''\n                  }.\n                  {/* Con una calificación de <strong>{form.qualification.toFixed(0)}%</strong>. */}\n                </React.Fragment> : null\n            }\n            {\n              form.form.shipping ?\n                <React.Fragment>\n                  El vehículo fue Despachado.\n                  {/* Con una calificación de <strong>{form.qualification.toFixed(0)}%</strong>. */}\n                </React.Fragment>\n                : ''\n            }\n          </div>\n          <div className='timeline-footer'>\n            <Row>\n              <div\n                className='col col-md-6'\n                style={{\n                  padding: '5px 15px'\n                }}>\n                <button\n                  className='btn btn-primary btn-flat btn-xs'\n                  disabled={loadingParticipant && loadingParticipant === form._id ? true : false}\n                  onClick={() => this.props.getParticipant(form._id)}\n                >\n                  {\n                    loadingParticipant && loadingParticipant === form._id ?\n                      <React.Fragment><i className='fa fa-spin fa-spinner' /> Cargando...</React.Fragment>\n                      : `Ver detalle`\n                  }\n                </button>\n              </div>\n              <div\n                className='col col-md-6 text-right'\n                style={{\n                  color: '#888',\n                  fontSize: '12px',\n                  padding: '5px 15px'\n                }}>\n                {\n                  form.user ?\n                    <React.Fragment>\n                      <i className='fa fa-user' /> {form.user.firstName} {form.user.lastName}\n                    </React.Fragment> : null\n                }\n              </div>\n            </Row>\n          </div>\n        </div>\n      </li>\n    );\n  }\n\n  private getColorByDamage(hasDamages: boolean): string {\n    if (hasDamages) {\n      return 'bg-red';\n    } else {\n      return 'bg-green';\n    }\n  }\n\n  private getIconDamage(hasDamages: boolean): string {\n    if (hasDamages) {\n      return 'fa-warning';\n    } else {\n      return 'fa-check-square-o';\n    }\n  }\n\n  private getColor(form: any): string {\n    const { qualification } = form;\n    if (qualification <= 25) {\n      return 'bg-red';\n    } else if (qualification <= 50) {\n      return 'bg-orange';\n    } else if (qualification <= 75) {\n      return 'bg-yellow';\n    } else {\n      return 'bg-green';\n    }\n  }\n}\n\nexport default TimeLineForm;\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport Row from '../Utils/Row';\n\ninterface IPropsType {\n  inventory: any;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass TimeLineInventory extends React.Component<IPropsType, IStateType> {\n\n  private iconStatus: any = {\n    pending: 'fa-clock-o',\n    found: 'fa-check',\n    leftover: 'fa-arrow-up',\n    missing: 'fa-arrow-down',\n    reported: 'fa-exclamation'\n  };\n\n  private classStatus: any = {\n    pending: 'bg-aqua',\n    found: 'bg-green',\n    missing: 'bg-red',\n    leftover: 'bg-yellow',\n    reported: 'bg-gray'\n  };\n\n  private classLabelStatus: any = {\n    pending: 'label-info',\n    found: 'label-success',\n    missing: 'label-danger',\n    leftover: 'label-warning',\n    reported: 'label-default'\n  };\n\n  private statusText: any = {\n    pending: 'Pendiente',\n    found: 'Encontrado',\n    leftover: 'Sobrante',\n    missing: 'Faltante',\n    reported: 'Reportado'\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  render(): React.ReactElement<IPropsType> {\n    const { inventory } = this.props;\n    return (\n      <li style={{ marginRight: '0' }}>\n        <i className={`fa ${this.iconStatus[inventory.status]} ${this.classStatus[inventory.status]}`} />\n        <div className='timeline-item'>\n          <span className='time' style={{\n            color: '#888',\n            fontSize: '13px'\n          }}>\n            <i className='fa fa-fw fa-calendar-o' /> {inventory.createdAt.format('LL')}\n          </span>\n\n          <h3 className='timeline-header'><a href={`/inventory/${inventory.inventory._id}`} target='_blank'>{inventory.inventory.name}</a></h3>\n\n          <div className='timeline-body'>\n            {\n              ['found'].includes(inventory.status) ?\n                <React.Fragment>\n                  El vehículo fue encontrado en <span\n                  className='text-blue'>{inventory.venueFound ? inventory.venueFound.name : inventory.venue.name}</span>.\n                </React.Fragment>\n                : null\n            }\n            {\n              ['pending'].includes(inventory.status) ?\n                <React.Fragment>\n                  El vehículo no fue encontrado en <span className='text-blue'>{inventory.venue.name}</span>.\n                </React.Fragment> : null\n            }\n            {\n              ['reported'].includes(inventory.status) ?\n                <React.Fragment>\n                  El vehículo fue reportado en <span className='text-blue'>{inventory.venue.name}</span>.\n                </React.Fragment> : null\n            }\n            {\n              ['missing'].includes(inventory.status) ?\n                <React.Fragment>\n                  El vehículo fue marcado como faltante en <span\n                  className='text-blue'>{inventory.venueFound ? inventory.venueFound.name : inventory.venue.name}</span>.\n                </React.Fragment> : null\n            }\n            {\n              ['leftover'].includes(inventory.status) ?\n                <React.Fragment>\n                  El vehículo fue marcado como sobrante en <span\n                  className='text-blue'>{inventory.venueFound ? inventory.venueFound.name : inventory.venue.name}</span>.\n                </React.Fragment> : null\n            }\n          </div>\n          <div className='timeline-footer'>\n            <Row>\n              <div\n                className='col col-md-6'\n                style={{\n                  padding: '5px 15px'\n                }}>\n                {this.status(inventory.status)}{' '}\n                {this.label(inventory.label, inventory.labelText)}\n              </div>\n              <div\n                className='col col-md-6 text-right'\n                style={{\n                  color: '#888',\n                  fontSize: '12px',\n                  padding: '5px 15px'\n                }}>\n                {\n                  ['leftover', 'missing'].includes(inventory.status) && inventory.labelBy ?\n                    <React.Fragment>\n                      <i className='fa fa-user' /> {inventory.labelBy.firstName} {inventory.labelBy.lastName}\n                    </React.Fragment>\n                    : inventory.inventoriedBy ?\n                      <React.Fragment>\n                        <i className='fa fa-user' /> {inventory.inventoriedBy.firstName} {inventory.inventoriedBy.lastName}\n                      </React.Fragment> : null\n                }\n              </div>\n            </Row>\n          </div>\n        </div>\n      </li>\n    );\n  }\n\n  private label(label: any, labelText: string) {\n    if (label) {\n      const { sendTo } = label;\n      return (\n        <span\n          className={\n            `label ${this.classLabelStatus.hasOwnProperty(sendTo) ? this.classLabelStatus[sendTo] : ''}`\n          }\n          style={{\n            padding: '5px 10px'\n          }}\n        >\n          <i className={`fa fa-fw ${this.iconStatus[sendTo]}`} />\n          {label.name} {label.requireCustomText ? <span\n          data-toggle='tooltip'\n          data-placement='top'\n          title={labelText}>Ver más</span> : ''}\n        </span>\n      );\n    } else {\n      return null;\n    }\n  }\n\n  private status(status: string) {\n    return (\n      <span\n        className={`label ${this.classLabelStatus.hasOwnProperty(status) ? this.classLabelStatus[status] : ''}`}\n        style={{\n          padding: '5px 10px'\n        }}\n      >\n          {this.statusText.hasOwnProperty(status) ? this.statusText[status] : status}\n          </span>\n    );\n  }\n}\n\nexport default TimeLineInventory;\n","import * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport {ErrorInfo} from 'react';\nimport * as React from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport {debounce} from 'throttle-debounce';\nimport {ICar} from '../../../../../../src/app/interfaces/car.interface';\nimport {CarReduxAction, getCarsAction, ICarsState} from '../../actions/cars.actions';\nimport AppContainer from '../../container/AppContainer';\nimport {IWindow} from '../../interfaces/window';\nimport {hasPermission} from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\n\ndeclare let window: IWindow;\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<CarReduxAction>;\n  cars: ICarsState;\n\n  getCarsAction(page: number, search?: string): CarReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  searchText: string;\n}\n\nclass CarListView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  // static propTypes = {\n  //   dispatch: PropTypes.func.isRequired\n  // };\n\n  readonly state = {\n    error: null,\n    searchText: ''\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de autos';\n    this.changePage = this.changePage.bind(this);\n    this.onChangeSearch = this.onChangeSearch.bind(this);\n    this.debounceOnChangeSearch = debounce(300, this.debounceOnChangeSearch);\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public componentWillMount() {\n    const {pagination} = this.props.cars;\n    this.props.getCarsAction(pagination.page);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if(this.props.cars.pagination !== prevProps.cars.pagination){\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentWillUnmount() {\n    // cancel request if component is inmounted\n    if (this.props.cars.source) {\n      this.props.cars.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {loading, cars, pagination} = this.props.cars;\n    const {searchText} = this.state;\n    return (\n      <AppContainer title=\"\" cMenu=\"10\" cSubMenu=\"10.2\" cAction=\"Listado\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">\n                Autos <small>{pagination.count}</small>\n              </h3>\n              <div className=\"box-tools\">\n                {\n                  hasPermission(window.user, 'addCar') ?\n                    <button\n                      className=\"btn btn-sm btn-primary hidden-xs\"\n                      onClick={() => this.props.history.push(`/settings/cars/import/`)}\n                      style={{marginRight: '5px'}}\n                    ><i className=\"fa fa-fw fa-cloud-upload\" /> Importar</button> : null\n                }\n              </div>\n            </div>\n            <div className=\"box-body no-padding\">\n              <div className=\"row\">\n                <div className=\"col-md-offset-8 col-md-4\">\n                  <div\n                    className=\"input-group input-group-sm\"\n                    style={{padding: '10px'}}\n                  >\n                    <input\n                      type=\"text\"\n                      className=\"form-control pull-right\"\n                      onChange={this.onChangeSearch}\n                      placeholder=\"Buscar\"/>\n                    <div className=\"input-group-btn\">\n                      <button className=\"btn btn-default\"><i className=\"fa fa-search\"/></button>\n                    </div>\n                  </div>\n                </div>\n              </div>\n              <table className=\"table table-andes table-striped\">\n                <thead>\n                  <tr>\n                    <th style={{width: '20%'}}>VIN</th>\n                    <th style={{width: '10%'}}>Patente</th>\n                    <th style={{width: '10%'}}>Marca</th>\n                    <th style={{width: '20%'}} className=\"hidden-xs\">Denominación</th>\n                    <th style={{width: '15%'}} className=\"hidden-xs\">Color</th>\n                    <th style={{width: '20%'}} className=\"hidden-xs\">Creado</th>\n                    <th style={{width: '5%'}} />\n                    {/*<th className=\"width-10\" />*/}\n                  </tr>\n                </thead>\n                <tbody>\n                  {\n                    !loading && cars.length === 0 && searchText ? <tr>\n                      <td colSpan={5}>No se han encontrado resultados.</td>\n                    </tr> : null\n                  }\n                  {\n                    cars.map((car: ICar) => {\n                      return (\n                        <tr key={car._id} id={`car-${car._id}`}>\n                          <td>{car.vin}</td>\n                          <td>{car.patent}</td>\n                          <td>{car.brand}</td>\n                          <td className=\"hidden-xs text-ellipsis\">{car.denomination}</td>\n                          <td className=\"hidden-xs text-ellipsis\">{car.color}</td>\n                          <td className=\"hidden-xs text-ellipsis\">{moment(car.createdAt).format('LLL')}</td>\n                          <td className=\"text-primary middle-center\">\n                            <button\n                              className=\"btn btn-xs btn-primary\"\n                              onClick={() => this.props.history.push(`/settings/cars/${car._id}`)}\n                            ><i className=\"fa fa-bars\"/>\n                            </button>\n                          </td>\n                        </tr>\n                      );\n                    })\n                  }\n                </tbody>\n              </table>\n            </div>\n            {\n              pagination.pages > 1 &&\n                <div className=\"box-footer\">\n                  <div className=\"row\">\n                    <div className=\"col-md-6\">\n                      {\n                        searchText && searchText.length ? <p><strong>Filtrado por:</strong> {searchText}</p> : null\n                      }\n                    </div>\n                    <div className=\"col-md-6 text-right\">\n                      <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                    </div>\n                  </div>\n                </div>\n            }\n            {\n              loading &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private onChangeSearch(e: React.ChangeEvent<HTMLInputElement>): void {\n    e.preventDefault();\n    const value = e.target.value.trim();\n    this.setState({\n      searchText: value\n    });\n    this.debounceOnChangeSearch();\n  }\n\n  private debounceOnChangeSearch(): void {\n    const {searchText} = this.state;\n    if (searchText && searchText.length) {\n      this.props.getCarsAction(1, searchText);\n    } else {\n      this.props.getCarsAction(1);\n    }\n  }\n\n  private changePage(page: number): void {\n    const { searchText } = this.state;\n    this.props.getCarsAction(page, searchText);\n  }\n}\n\nconst mapStateToProps = (state: { cars: ICarsState }) => {\n  return {\n    cars: state.cars\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getCarsAction: (page: number, search?: string) => dispatch(getCarsAction(page, search))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(CarListView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Link } from 'react-router-dom';\nimport { Dispatch } from 'redux';\nimport { FormAction, submit } from 'redux-form';\nimport * as swal from 'sweetalert';\nimport { ISalesChannel } from '../../../../../../src/request/interfaces/salesChannel.interface';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport { ISalesChannelState, RequestChannelReduxActions } from '../../actions/requestChannel.types';\nimport {\n  createRequestChannelThunkAction,\n  deleteRequestChannelItemThunkAction,\n  getRequestChannelThunkAction,\n  updateRequestChannelThunkAction\n} from '../../actions/requestChannel.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { hasPermission, showModal, statusFooterButttonsModal } from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport ChannelForm from './ChannelForm';\nimport ShowIf from '../Utils/ShowIf';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<RequestChannelReduxActions | FormAction>;\n  requestChannel: ISalesChannelState;\n\n  getRequestChannelThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean): RequestChannelReduxActions;\n  createRequestChannelThunkAction(requestChannel: ISalesChannel): RequestChannelReduxActions;\n  updateRequestChannelThunkAction(requestChannel: ISalesChannel): RequestChannelReduxActions;\n  deleteRequestChannelThunkAction(requestChannel: ISalesChannel): RequestChannelReduxActions;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass RequestChannelListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  private socket: Socket;\n  readonly state = {\n    error: null,\n    exporing: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de Canales';\n    this.changePage = this.changePage.bind(this);\n    this.createRequestChannel = this.createRequestChannel.bind(this);\n    this.processCreateRequestChannel = this.processCreateRequestChannel.bind(this);\n    this.updateReaon = this.updateReaon.bind(this);\n    this.processUpdateRequestChannel = this.processUpdateRequestChannel.bind(this);\n    this.deleteRequestChannel = this.deleteRequestChannel.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const { pagination } = this.props.requestChannel;\n    const { orderBy, orderType } = this.props.requestChannel.options;\n    this.props.getRequestChannelThunkAction(pagination.page, orderBy, orderType);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: { token: (window.user as any).token }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `request-status-list-${window.user.team._id}` });\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update) {\n        const { pagination } = this.props.requestChannel;\n        const { orderBy, orderType } = this.props.requestChannel.options;\n        this.props.getRequestChannelThunkAction(pagination.page, orderBy, orderType, true);\n      }\n    });\n  }\n\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if (this.props.requestChannel.pagination !== prevProps.requestChannel.pagination) {\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.requestChannel.source) {\n      this.props.requestChannel.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, channels, pagination } = this.props.requestChannel;\n    const canEdit = hasPermission(window.user, 'adminRequest');\n    const canDelete = hasPermission(window.user, 'adminRequest');\n    return (\n      <AppContainer title=\"\" cMenu=\"3\" cSubMenu=\"3.3\" cAction=\"Canales\">\n        <section className=\"content\">\n          <div className=\"row\">\n            <div className=\"col-md-3\">\n              <div className=\"list-group\">\n                <Link to=\"/requests/settings/reasons/\" className=\"list-group-item\">\n                  Motivos\n                </Link>\n                <Link to=\"/requests/settings/channels/\" className=\"list-group-item active\">\n                  Canales\n                </Link>\n                <Link to=\"/requests/settings/status/\" className=\"list-group-item \">\n                  Estados\n                </Link>\n                <Link to=\"/requests/settings/operations-type/\" className=\"list-group-item \">\n                  Tipos de operación\n                </Link>\n                <Link to=\"/requests/settings/payment-methods/\" className=\"list-group-item\">\n                  Métodos de pago\n                </Link>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone-type/' className='list-group-item'>\n                    Tipos de hitos\n                  </Link>\n                </ShowIf>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone/' className='list-group-item'>\n                    Hitos\n                  </Link>\n                </ShowIf>\n              </div>\n            </div>\n            <div className=\"col-md-9\">\n              <div className=\"box\">\n                <div className=\"box-header with-border\">\n                  <h3 className=\"box-title\">Canales <small>{pagination.count}</small></h3>\n                  <div className=\"box-tools pull-right\">\n                    {\n                      hasPermission(window.user, 'addVenue') ?\n                        <button className=\"btn btn-sm btn-success\"\n                          onClick={this.createRequestChannel}\n                        ><i className=\"fa fa-plus\" />  Agregar</button>\n                        : null\n                    }\n                  </div>\n                </div>\n                <div className=\"box-body table-responsive no-padding\">\n                  <table className=\"table table-andes table-striped\">\n                    <thead>\n                      <tr>\n                        <th style={{ width: '98%' }} className=\"middle\">Nombre</th>\n                        {\n                          canEdit ?\n                            <th style={{ width: '1%' }} className=\"width-10\" /> : null\n                        }\n                        {\n                          canDelete ?\n                            <th style={{ width: '1%' }} className=\"width-10\" /> : null\n                        }\n                      </tr>\n                    </thead>\n                    <tbody>\n                      {\n                        channels.map((item) => {\n                          return (\n                            <tr key={item._id}>\n                              <td className=\"middle\">{item.name}</td>\n                              {\n                                canEdit ?\n                                  <td\n                                    className=\"middle text-blue pointer\"\n                                    onClick={() => this.updateReaon(item)}\n                                  >\n                                    <i className=\"fa fa-pencil\" />\n                                  </td> : null\n                              }\n                              {\n                                canDelete ?\n                                  <td\n                                    className={canDelete ? 'middle text-red pointer' : 'middle text-muted not-allowed'}\n                                    // className={'middle text-red pointer'}\n                                    onClick={canDelete ? () => this.deleteRequestChannel(item) : undefined}\n                                  >\n                                    <i className=\"fa fa-minus-circle\" />\n                                  </td> : null\n                              }\n                            </tr>\n                          );\n                        })\n                      }\n                    </tbody>\n                  </table>\n                </div>\n                {\n                  pagination.pages > 1 &&\n                  <div className=\"box-footer text-right\">\n                    <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                  </div>\n                }\n                {\n                  loading &&\n                  <div className=\"overlay\">\n                    <i className=\"fa fa-spinner fa-spin text-purple\" />\n                  </div>\n                }\n              </div>\n            </div>\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private createRequestChannel(): void {\n    this.props.loadDataAction(\n      'Agregar Canal',\n      <ChannelForm\n        initialValues={{ update: false }}\n        onSubmit={this.processCreateRequestChannel}\n      />,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={() => this.props.dispatch(submit('channelForm'))}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processCreateRequestChannel(requestChannel: any): void {\n    statusFooterButttonsModal(true);\n    this.props.createRequestChannelThunkAction(requestChannel);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private updateReaon(reason: any): void {\n    this.props.loadDataAction(\n      'Editar Canal',\n      <ChannelForm\n        initialValues={{ update: false, ...reason }}\n        onSubmit={this.processUpdateRequestChannel}\n      />,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={() => this.props.dispatch(submit('channelForm'))}>Editar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processUpdateRequestChannel(requestChannel: any): void {\n    statusFooterButttonsModal(true);\n    this.props.updateRequestChannelThunkAction(requestChannel);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private deleteRequestChannel(requestChannel: ISalesChannel): void {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el canal: ${requestChannel.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteRequestChannelThunkAction(requestChannel);\n      }\n    });\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    const { orderBy, orderType } = this.props.requestChannel.options;\n    this.props.getRequestChannelThunkAction(page, orderBy, orderType);\n  }\n}\n\nconst mapStateToProps = (state: { requestChannel: ISalesChannelState }) => {\n  return {\n    requestChannel: state.requestChannel\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getRequestChannelThunkAction: (nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) => dispatch(getRequestChannelThunkAction(nextPage, orderBy, orderType, hideLoading)),\n    createRequestChannelThunkAction: (requestChannel: ISalesChannel) => dispatch(createRequestChannelThunkAction(requestChannel)),\n    updateRequestChannelThunkAction: (requestChannel: ISalesChannel) => dispatch(updateRequestChannelThunkAction(requestChannel)),\n    deleteRequestChannelThunkAction: (requestChannel: ISalesChannel) => dispatch(deleteRequestChannelItemThunkAction(requestChannel)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{ requestChannel: ISalesChannelState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(RequestChannelListView);\n","import Axios, { AxiosError, AxiosResponse, CancelTokenSource } from 'axios';\nimport { Dispatch } from 'redux';\nimport { ISalesChannel } from '../../../../../src/request/interfaces/salesChannel.interface';\nimport ApiService from '../utils/axios';\nimport { ICancelRequestChannel, IIsLoadingRequestChannel, ILoadRequestChannel, ICreateRequestChannel, IUpdateRequestChannel, IDeleteRequestChannel, IChangeOrderRequestChannel, RequestChannelReduxActions, ISalesChannelState } from './requestChannel.types';\nimport { REQUEST_CANCEL_CHANNEL,\n  REQUEST_IS_LOADING,\n  REQUEST_LOAD_CHANNEL,\n  REQUEST_CREATE_CHANNEL,\n  REQUEST_UDPATE_CHANNEL,\n  REQUEST_DELETE_CHANNEL,\n  REQUEST_CHANGE_ORDER\n} from './requestChannel.types';\n\nexport function cancelRequestChannelAction(source: CancelTokenSource): ICancelRequestChannel {\n  return {\n    type: REQUEST_CANCEL_CHANNEL,\n    payload: {\n      source\n    }\n  };\n}\n\nexport function isLoadingRequestChannelAction(loading: boolean): IIsLoadingRequestChannel {\n  return {\n    type: REQUEST_IS_LOADING,\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function loadRequestChannelAction(channels: ISalesChannel[], count: number, pages: number, page: number): ILoadRequestChannel {\n  return {\n    type: REQUEST_LOAD_CHANNEL,\n    payload: {\n      channels,\n      count,\n      pages,\n      page\n    }\n  };\n}\n\n\nexport function createRequestChannelItemAction(reason: ISalesChannel): ICreateRequestChannel {\n  return {\n    type: REQUEST_CREATE_CHANNEL,\n    payload: {\n      reason\n    }\n  };\n}\n\nexport function updateRequestChannelItemAction(reason: ISalesChannel): IUpdateRequestChannel {\n  return {\n    type: REQUEST_UDPATE_CHANNEL,\n    payload: {\n      reason\n    }\n  };\n}\n\n\nexport function deleteRequestChannelAction(reason: ISalesChannel): IDeleteRequestChannel {\n  return {\n    type: REQUEST_DELETE_CHANNEL,\n    payload: {\n      reason\n    }\n  };\n}\n\nexport function changeOrderRequestChannelAction(orderBy: string, orderType: string): IChangeOrderRequestChannel {\n  return {\n    type: REQUEST_CHANGE_ORDER,\n    payload: {\n      orderBy,\n      orderType\n    }\n  };\n}\n\nexport function getRequestChannelThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) {\n  return (dispatch: Dispatch<RequestChannelReduxActions>, getState: () => { requestStatus: ISalesChannelState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(isLoadingRequestChannelAction(hideLoading ? false : true));\n    const page = nextPage ? nextPage : state.requestStatus.pagination.page;\n    dispatch(changeOrderRequestChannelAction(orderBy, orderType));\n    dispatch(cancelRequestChannelAction(api.getSource()));\n    Axios\n      .all([\n        api.getSalesChannel({ page, orderBy, orderType })\n      ])\n      .then(Axios.spread((channels) => {\n        const { data } = channels;\n        dispatch(loadRequestChannelAction(data.results, data.count, data.pages, page));\n        dispatch(isLoadingRequestChannelAction(false));\n      }))\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingRequestChannelAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function createRequestChannelThunkAction(requestStatus: ISalesChannel) {\n  return (dispatch: Dispatch<RequestChannelReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.createSalesChannel(requestStatus)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateRequestChannelItemAction(idRequestChannel, data));\n      });\n  };\n}\n\nexport function updateRequestChannelThunkAction(requestStatus: ISalesChannel) {\n  return (dispatch: Dispatch<RequestChannelReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.updateSalesChannel(requestStatus)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateRequestChannelItemAction(idRequestChannel, data));\n      });\n  };\n}\n\nexport function deleteRequestChannelItemThunkAction(requestStatus: ISalesChannel) {\n  return (dispatch: Dispatch<RequestChannelReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.deleteSalesChannel(requestStatus)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateRequestChannelItemAction(idRequestChannel, data));\n      });\n  };\n}\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Link } from 'react-router-dom';\nimport { Dispatch } from 'redux';\nimport { FormAction, submit } from 'redux-form';\nimport * as swal from 'sweetalert';\nimport { IPaymentMethod } from '../../../../../../src/request/interfaces/paymentMethod.interface';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport { IPaymentMethodState, PaymentMethodReduxActions } from '../../actions/paymentMethod.types';\nimport {\n  createPaymentMethodThunkAction,\n  deletePaymentMethodItemThunkAction,\n  getPaymentMethodThunkAction,\n  updatePaymentMethodThunkAction\n} from '../../actions/paymentMethod.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { hasPermission, showModal, statusFooterButttonsModal } from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport ChannelForm from './ChannelForm';\nimport ShowIf from '../Utils/ShowIf';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<PaymentMethodReduxActions | FormAction>;\n  paymentMethod: IPaymentMethodState;\n\n  getPaymentMethodThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean): PaymentMethodReduxActions;\n  createPaymentMethodThunkAction(paymentMethod: IPaymentMethod): PaymentMethodReduxActions;\n  updatePaymentMethodThunkAction(paymentMethod: IPaymentMethod): PaymentMethodReduxActions;\n  deletePaymentMethodThunkAction(paymentMethod: IPaymentMethod): PaymentMethodReduxActions;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass PaymentMethodListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  private socket: Socket;\n  readonly state = {\n    error: null,\n    exporing: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de Canales';\n    this.changePage = this.changePage.bind(this);\n    this.createPaymentMethod = this.createPaymentMethod.bind(this);\n    this.processCreatePaymentMethod = this.processCreatePaymentMethod.bind(this);\n    this.updateReaon = this.updateReaon.bind(this);\n    this.processUpdatePaymentMethod = this.processUpdatePaymentMethod.bind(this);\n    this.deletePaymentMethod = this.deletePaymentMethod.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const { pagination } = this.props.paymentMethod;\n    const { orderBy, orderType } = this.props.paymentMethod.options;\n    this.props.getPaymentMethodThunkAction(pagination.page, orderBy, orderType);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: { token: (window.user as any).token }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `payment-method-list-${window.user.team._id}` });\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update) {\n        const { pagination } = this.props.paymentMethod;\n        const { orderBy, orderType } = this.props.paymentMethod.options;\n        this.props.getPaymentMethodThunkAction(pagination.page, orderBy, orderType, true);\n      }\n    });\n  }\n\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if (this.props.paymentMethod.pagination !== prevProps.paymentMethod.pagination) {\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.paymentMethod.source) {\n      this.props.paymentMethod.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, paymentMethods, pagination } = this.props.paymentMethod;\n    const canEdit = hasPermission(window.user, 'adminRequest');\n    const canDelete = hasPermission(window.user, 'adminRequest');\n    let cols = 1;\n    if(canDelete){\n      cols++;\n    }\n    if(canEdit){\n      cols++;\n    }\n    return (\n      <AppContainer title=\"\" cMenu=\"3\" cSubMenu=\"3.3\" cAction=\"Métodos de pago\">\n        <section className=\"content\">\n          <div className=\"row\">\n            <div className=\"col-md-3\">\n              <div className=\"list-group\">\n                <Link to=\"/requests/settings/reasons/\" className=\"list-group-item\">\n                  Motivos\n                </Link>\n                <Link to=\"/requests/settings/channels/\" className=\"list-group-item\">\n                  Canales\n                </Link>\n                <Link to=\"/requests/settings/status/\" className=\"list-group-item \">\n                  Estados\n                </Link>\n                <Link to=\"/requests/settings/operations-type/\" className=\"list-group-item \">\n                  Tipos de operación\n                </Link>\n                <Link to=\"/requests/settings/payment-methods/\" className=\"list-group-item active\">\n                  Métodos de pago\n                </Link>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone-type/' className='list-group-item'>\n                    Tipos de hitos\n                  </Link>\n                </ShowIf>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone/' className='list-group-item'>\n                    Hitos\n                  </Link>\n                </ShowIf>\n              </div>\n            </div>\n            <div className=\"col-md-9\">\n              <div className=\"box\">\n                <div className=\"box-header with-border\">\n                  <h3 className=\"box-title\">Métodos de pago <small>{pagination.count}</small></h3>\n                  <div className=\"box-tools pull-right\">\n                    {\n                      hasPermission(window.user, 'addVenue') ?\n                        <button className=\"btn btn-sm btn-success\"\n                          onClick={this.createPaymentMethod}\n                        ><i className=\"fa fa-plus\" />  Agregar</button>\n                        : null\n                    }\n                  </div>\n                </div>\n                <div className=\"box-body table-responsive no-padding\">\n                  <table className=\"table table-andes table-striped\">\n                    <thead>\n                      <tr>\n                        <th style={{ width: '98%' }} className=\"middle\">Nombre</th>\n                        {\n                          canEdit ?\n                            <th style={{ width: '1%' }} className=\"width-10\" /> : null\n                        }\n                        {\n                          canDelete ?\n                            <th style={{ width: '1%' }} className=\"width-10\" /> : null\n                        }\n                      </tr>\n                    </thead>\n                    <tbody>\n                      <ShowIf condition={!paymentMethods.length}>\n                        <tr>\n                          <td colSpan={cols}>No se han creado métodos de pago.</td>\n                        </tr>\n                      </ShowIf>\n                      {\n                        paymentMethods.map((item) => {\n                          return (\n                            <tr key={item._id}>\n                              <td className=\"middle\">{item.name}</td>\n                              {\n                                canEdit ?\n                                  <td\n                                    className=\"middle text-blue pointer\"\n                                    onClick={() => this.updateReaon(item)}\n                                  >\n                                    <i className=\"fa fa-pencil\" />\n                                  </td> : null\n                              }\n                              {\n                                canDelete ?\n                                  <td\n                                    className={canDelete ? 'middle text-red pointer' : 'middle text-muted not-allowed'}\n                                    // className={'middle text-red pointer'}\n                                    onClick={canDelete ? () => this.deletePaymentMethod(item) : undefined}\n                                  >\n                                    <i className=\"fa fa-minus-circle\" />\n                                  </td> : null\n                              }\n                            </tr>\n                          );\n                        })\n                      }\n                    </tbody>\n                  </table>\n                </div>\n                {\n                  pagination.pages > 1 &&\n                  <div className=\"box-footer text-right\">\n                    <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                  </div>\n                }\n                {\n                  loading &&\n                  <div className=\"overlay\">\n                    <i className=\"fa fa-spinner fa-spin text-purple\" />\n                  </div>\n                }\n              </div>\n            </div>\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private createPaymentMethod(): void {\n    this.props.loadDataAction(\n      'Agregar método de pago',\n      <ChannelForm\n        initialValues={{ update: false }}\n        onSubmit={this.processCreatePaymentMethod}\n      />,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={() => this.props.dispatch(submit('channelForm'))}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processCreatePaymentMethod(paymentMethod: any): void {\n    statusFooterButttonsModal(true);\n    this.props.createPaymentMethodThunkAction(paymentMethod);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private updateReaon(reason: any): void {\n    this.props.loadDataAction(\n      'Editar método de pago',\n      <ChannelForm\n        initialValues={{ update: false, ...reason }}\n        onSubmit={this.processUpdatePaymentMethod}\n      />,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={() => this.props.dispatch(submit('channelForm'))}>Editar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processUpdatePaymentMethod(paymentMethod: any): void {\n    statusFooterButttonsModal(true);\n    this.props.updatePaymentMethodThunkAction(paymentMethod);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private deletePaymentMethod(paymentMethod: IPaymentMethod): void {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el canal: ${paymentMethod.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deletePaymentMethodThunkAction(paymentMethod);\n      }\n    });\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    const { orderBy, orderType } = this.props.paymentMethod.options;\n    this.props.getPaymentMethodThunkAction(page, orderBy, orderType);\n  }\n}\n\nconst mapStateToProps = (state: { paymentMethod: IPaymentMethodState }) => {\n  return {\n    paymentMethod: state.paymentMethod\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getPaymentMethodThunkAction: (nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) => dispatch(getPaymentMethodThunkAction(nextPage, orderBy, orderType, hideLoading)),\n    createPaymentMethodThunkAction: (paymentMethod: IPaymentMethod) => dispatch(createPaymentMethodThunkAction(paymentMethod)),\n    updatePaymentMethodThunkAction: (paymentMethod: IPaymentMethod) => dispatch(updatePaymentMethodThunkAction(paymentMethod)),\n    deletePaymentMethodThunkAction: (paymentMethod: IPaymentMethod) => dispatch(deletePaymentMethodItemThunkAction(paymentMethod)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{ paymentMethod: IPaymentMethodState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(PaymentMethodListView);\n","import Axios, { AxiosError, AxiosResponse, CancelTokenSource } from 'axios';\nimport { Dispatch } from 'redux';\nimport { IPaymentMethod } from '../../../../../src/request/interfaces/paymentMethod.interface';\nimport ApiService from '../utils/axios';\nimport {\n  ICancelPaymentMethod,\n  IChangeOrderPaymentMethod,\n  ICreatePaymentMethod,\n  IDeletePaymentMethod,\n  IIsLoadingPaymentMethod,\n  ILoadPaymentMethod,\n  IPaymentMethodState,\n  IUpdatePaymentMethod,\n  PAYMENT_METHOD_CANCEL,\n  PAYMENT_METHOD_CHANGE_ORDER,\n  PAYMENT_METHOD_CREATE,\n  PAYMENT_METHOD_DELETE,\n  PAYMENT_METHOD_IS_LOADING,\n  PAYMENT_METHOD_LOAD,\n  PAYMENT_METHOD_UDPATE,\n  PaymentMethodReduxActions\n} from './paymentMethod.types';\n\nexport function cancelPaymentMethodAction(source: CancelTokenSource): ICancelPaymentMethod {\n  return {\n    type: PAYMENT_METHOD_CANCEL,\n    payload: {\n      source\n    }\n  };\n}\n\nexport function isLoadingPaymentMethodAction(loading: boolean): IIsLoadingPaymentMethod {\n  return {\n    type: PAYMENT_METHOD_IS_LOADING,\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function loadPaymentMethodAction(paymentMethods: IPaymentMethod[], count: number, pages: number, page: number): ILoadPaymentMethod {\n  return {\n    type: PAYMENT_METHOD_LOAD,\n    payload: {\n      paymentMethods,\n      count,\n      pages,\n      page\n    }\n  };\n}\n\n\nexport function createPaymentMethodItemAction(reason: IPaymentMethod): ICreatePaymentMethod {\n  return {\n    type: PAYMENT_METHOD_CREATE,\n    payload: {\n      reason\n    }\n  };\n}\n\nexport function updatePaymentMethodItemAction(reason: IPaymentMethod): IUpdatePaymentMethod {\n  return {\n    type: PAYMENT_METHOD_UDPATE,\n    payload: {\n      reason\n    }\n  };\n}\n\n\nexport function deletePaymentMethodAction(reason: IPaymentMethod): IDeletePaymentMethod {\n  return {\n    type: PAYMENT_METHOD_DELETE,\n    payload: {\n      reason\n    }\n  };\n}\n\nexport function changeOrderPaymentMethodAction(orderBy: string, orderType: string): IChangeOrderPaymentMethod {\n  return {\n    type: PAYMENT_METHOD_CHANGE_ORDER,\n    payload: {\n      orderBy,\n      orderType\n    }\n  };\n}\n\nexport function getPaymentMethodThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) {\n  return (dispatch: Dispatch<PaymentMethodReduxActions>, getState: () => { paymentMethod: IPaymentMethodState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(isLoadingPaymentMethodAction(!hideLoading));\n    const page = nextPage ? nextPage : state.paymentMethod.pagination.page;\n    dispatch(changeOrderPaymentMethodAction(orderBy, orderType));\n    dispatch(cancelPaymentMethodAction(api.getSource()));\n    Axios\n      .all([\n        api.getPaymentMethods({ page, orderBy, orderType })\n      ])\n      .then(Axios.spread((channels) => {\n        const { data } = channels;\n        dispatch(loadPaymentMethodAction(data.results, data.count, data.pages, page));\n        dispatch(isLoadingPaymentMethodAction(false));\n      }))\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingPaymentMethodAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function createPaymentMethodThunkAction(paymentMethod: IPaymentMethod) {\n  return (dispatch: Dispatch<PaymentMethodReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.createPaymentMethod(paymentMethod)\n      .then((response: AxiosResponse) => {\n        // dispatch(updatePaymentMethodItemAction(idPaymentMethod, data));\n      });\n  };\n}\n\nexport function updatePaymentMethodThunkAction(paymentMethod: IPaymentMethod) {\n  return (dispatch: Dispatch<PaymentMethodReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.updatePaymentMethod(paymentMethod)\n      .then((response: AxiosResponse) => {\n        // dispatch(updatePaymentMethodItemAction(idPaymentMethod, data));\n      });\n  };\n}\n\nexport function deletePaymentMethodItemThunkAction(paymentMethod: IPaymentMethod) {\n  return (dispatch: Dispatch<PaymentMethodReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.deletePaymentMethod(paymentMethod)\n      .then((response: AxiosResponse) => {\n        // dispatch(updatePaymentMethodItemAction(idPaymentMethod, data));\n      });\n  };\n}\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Link } from 'react-router-dom';\nimport { Dispatch } from 'redux';\nimport { FormAction, submit } from 'redux-form';\nimport * as swal from 'sweetalert';\nimport { IRequestStatus } from '../../../../../../src/request/interfaces/requestStatus.interface';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport {\n  createRequestStatusThunkAction,\n  deleteRequestStatusItemThunkAction,\n  getRequestStatusThunkAction,\n  updateRequestStatusThunkAction\n} from '../../actions/requestStatus.actions';\nimport { IRequestStatusState, RequestStatusReduxActions } from '../../actions/requestStatus.types';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { hasPermission, showModal, statusFooterButttonsModal } from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport StatusForm from './StatusForm';\nimport ShowIf from '../Utils/ShowIf';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<RequestStatusReduxActions | FormAction>;\n  requestStatus: IRequestStatusState;\n\n  getRequestStatusThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean): RequestStatusReduxActions;\n  createRequestStatusThunkAction(requestStatus: IRequestStatus): RequestStatusReduxActions;\n  updateRequestStatusThunkAction(requestStatus: IRequestStatus): RequestStatusReduxActions;\n  deleteRequestStatusThunkAction(requestStatus: IRequestStatus): RequestStatusReduxActions;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass RequestStatusListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  private socket: Socket;\n  readonly state = {\n    error: null,\n    exporing: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de Status';\n    this.changePage = this.changePage.bind(this);\n    this.createRequestStatus = this.createRequestStatus.bind(this);\n    this.processCreateRequestStatus = this.processCreateRequestStatus.bind(this);\n    this.updateReaon = this.updateReaon.bind(this);\n    this.processUpdateRequestStatus = this.processUpdateRequestStatus.bind(this);\n    this.deleteRequestStatus = this.deleteRequestStatus.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const { pagination } = this.props.requestStatus;\n    const { orderBy, orderType } = this.props.requestStatus.options;\n    this.props.getRequestStatusThunkAction(pagination.page, orderBy, orderType);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: { token: (window.user as any).token }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `request-status-list-${window.user.team._id}` });\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update) {\n        const { pagination } = this.props.requestStatus;\n        const { orderBy, orderType } = this.props.requestStatus.options;\n        this.props.getRequestStatusThunkAction(pagination.page, orderBy, orderType, true);\n      }\n    });\n  }\n\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if (this.props.requestStatus.pagination !== prevProps.requestStatus.pagination) {\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.requestStatus.source) {\n      this.props.requestStatus.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, status, pagination } = this.props.requestStatus;\n    const canEdit = hasPermission(window.user, 'adminRequest');\n    const canDelete = hasPermission(window.user, 'adminRequest');\n    return (\n      <AppContainer title=\"\" cMenu=\"3\" cSubMenu=\"3.3\" cAction=\"Estados\">\n        <section className=\"content\">\n          <div className=\"row\">\n            <div className=\"col-md-3\">\n              <div className=\"list-group\">\n                <Link to=\"/requests/settings/reasons/\" className=\"list-group-item\">\n                  Motivos\n                </Link>\n                <Link to=\"/requests/settings/channels/\" className=\"list-group-item\">\n                  Canales\n                </Link>\n                <Link to=\"/requests/settings/status/\" className=\"list-group-item active\">\n                  Estados\n                </Link>\n                <Link to=\"/requests/settings/operations-type/\" className=\"list-group-item \">\n                  Tipos de operación\n                </Link>\n                <Link to=\"/requests/settings/payment-methods/\" className=\"list-group-item\">\n                  Métodos de pago\n                </Link>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone-type/' className='list-group-item'>\n                    Tipos de hitos\n                  </Link>\n                </ShowIf>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone/' className='list-group-item'>\n                    Hitos\n                  </Link>\n                </ShowIf>\n              </div>\n            </div>\n            <div className=\"col-md-9\">\n              <div className=\"box\">\n                <div className=\"box-header with-border\">\n                  <h3 className=\"box-title\">Estados <small>{pagination.count}</small></h3>\n                  <div className=\"box-tools pull-right\">\n                    {\n                      hasPermission(window.user, 'addVenue') ?\n                        <button className=\"btn btn-sm btn-success\"\n                        onClick={this.createRequestStatus}\n                        ><i className=\"fa fa-plus\" />  Agregar</button>\n                        : null\n                    }\n                  </div>\n                </div>\n                <div className=\"box-body table-responsive no-padding\">\n                  <table className=\"table table-andes table-striped\">\n                    <thead>\n                      <tr>\n                        <th style={{ width: '70%' }} className=\"middle\">Nombre</th>\n                        <th style={{ width: '10%' }} className=\"middle\">Peso</th>\n                        <th style={{ width: '18%' }} className=\"middle text-center\">Default</th>\n                        {\n                          canEdit ?\n                            <th style={{ width: '1%' }} className=\"width-10\" /> : null\n                        }\n                        {\n                          canDelete ?\n                            <th style={{ width: '1%' }} className=\"width-10\" /> : null\n                        }\n                      </tr>\n                    </thead>\n                    <tbody>\n                      {\n                        status.map((item) => {\n                          return (\n                            <tr key={item._id}>\n                              <td className=\"middle\">{item.name}</td>\n                              <td className=\"middle\">{item.weigth}</td>\n                              <td className=\"middle text-center\">\n                                <i\n                                  className={\n                                    item.default ?\n                                      'fa fa-check-circle text-green':\n                                      'fa fa-times-circle text-red'\n                                  }\n                                />\n                              </td>\n                              {\n                                canEdit ?\n                                  <td\n                                    className=\"middle text-blue pointer\"\n                                    onClick={() => this.updateReaon(item)}\n                                  >\n                                    <i className=\"fa fa-pencil\" />\n                                  </td> : null\n                              }\n                              {\n                                !item.default && canDelete ?\n                                  <td\n                                    className={canDelete ? 'middle text-red pointer' : 'middle text-muted not-allowed'}\n                                    // className={'middle text-red pointer'}\n                                    onClick={canDelete ? () => this.deleteRequestStatus(item) : undefined}\n                                  >\n                                    <i className=\"fa fa-minus-circle\"/>\n                                  </td> : canDelete ?\n                                    <td/> : null\n                              }\n                            </tr>\n                          );\n                        })\n                      }\n                    </tbody>\n                  </table>\n                </div>\n                {\n                  pagination.pages > 1 &&\n                  <div className=\"box-footer text-right\">\n                    <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                  </div>\n                }\n                {\n                  loading &&\n                  <div className=\"overlay\">\n                    <i className=\"fa fa-spinner fa-spin text-purple\" />\n                  </div>\n                }\n              </div>\n            </div>\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private createRequestStatus(): void {\n    this.props.loadDataAction(\n      'Agregar Estado',\n      <StatusForm\n        initialValues={{ update: false }}\n        onSubmit={this.processCreateRequestStatus}\n      />,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={() => this.props.dispatch(submit('statusForm'))}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processCreateRequestStatus(requestStatus: any): void {\n    statusFooterButttonsModal(true);\n    this.props.createRequestStatusThunkAction(requestStatus);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private updateReaon(reason: any): void {\n    this.props.loadDataAction(\n      'Editar Estado',\n      <StatusForm\n        initialValues={{ update: false, ...reason }}\n        onSubmit={this.processUpdateRequestStatus}\n      />,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={() => this.props.dispatch(submit('statusForm'))}>Editar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processUpdateRequestStatus(requestStatus: any): void {\n    statusFooterButttonsModal(true);\n    this.props.updateRequestStatusThunkAction(requestStatus);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private deleteRequestStatus(requestStatus: IRequestStatus): void {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el estado: ${requestStatus.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteRequestStatusThunkAction(requestStatus);\n      }\n    });\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    const { orderBy, orderType } = this.props.requestStatus.options;\n    this.props.getRequestStatusThunkAction(page, orderBy, orderType);\n  }\n}\n\nconst mapStateToProps = (state: { requestStatus: IRequestStatusState }) => {\n  return {\n    requestStatus: state.requestStatus\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getRequestStatusThunkAction: (nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) => dispatch(getRequestStatusThunkAction(nextPage, orderBy, orderType, hideLoading)),\n    createRequestStatusThunkAction: (requestStatus: IRequestStatus) => dispatch(createRequestStatusThunkAction(requestStatus)),\n    updateRequestStatusThunkAction: (requestStatus: IRequestStatus) => dispatch(updateRequestStatusThunkAction(requestStatus)),\n    deleteRequestStatusThunkAction: (requestStatus: IRequestStatus) => dispatch(deleteRequestStatusItemThunkAction(requestStatus)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{ requestStatus: IRequestStatusState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(RequestStatusListView);\n","import Axios, { AxiosError, AxiosResponse, CancelTokenSource } from 'axios';\nimport { Dispatch } from 'redux';\nimport { IRequestStatus } from '../../../../../src/request/interfaces/requestStatus.interface';\nimport ApiService from '../utils/axios';\nimport {\n  REQUEST_IS_LOADING,\n  REQUEST_CHANGE_ORDER,\n  REQUEST_CANCEL_STATUS,\n  REQUEST_LOAD_STATUS,\n  REQUEST_CREATE_STATUS,\n  REQUEST_UDPATE_STATUS,\n  REQUEST_DELETE_STATUS,\n  ICreateRequestStatus,\n  ICancelRequestStatus,\n  IIsLoadingRequestStatus,\n  ILoadRequestStatus,\n  IUpdateRequestStatus,\n  IDeleteRequestStatus,\n  IChangeOrderRequestStatus,\n  IRequestStatusState,\n  RequestStatusReduxActions\n} from './requestStatus.types';\n\nexport function cancelRequestStatusAction(source: CancelTokenSource): ICancelRequestStatus {\n  return {\n    type: REQUEST_CANCEL_STATUS,\n    payload: {\n      source\n    }\n  };\n}\n\nexport function isLoadingRequestStatusAction(loading: boolean): IIsLoadingRequestStatus {\n  return {\n    type: REQUEST_IS_LOADING,\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function loadRequestStatusAction(status: IRequestStatus[], count: number, pages: number, page: number): ILoadRequestStatus {\n  return {\n    type: REQUEST_LOAD_STATUS,\n    payload: {\n      status,\n      count,\n      pages,\n      page\n    }\n  };\n}\n\n\nexport function createRequestStatusItemAction(reason: IRequestStatus): ICreateRequestStatus {\n  return {\n    type: REQUEST_CREATE_STATUS,\n    payload: {\n      reason\n    }\n  };\n}\n\nexport function updateRequestStatusItemAction(reason: IRequestStatus): IUpdateRequestStatus {\n  return {\n    type: REQUEST_UDPATE_STATUS,\n    payload: {\n      reason\n    }\n  };\n}\n\n\nexport function deleteRequestStatusAction(reason: IRequestStatus): IDeleteRequestStatus {\n  return {\n    type: REQUEST_DELETE_STATUS,\n    payload: {\n      reason\n    }\n  };\n}\n\nexport function changeOrderRequestStatusAction(orderBy: string, orderType: string): IChangeOrderRequestStatus {\n  return {\n    type: REQUEST_CHANGE_ORDER,\n    payload: {\n      orderBy,\n      orderType\n    }\n  };\n}\n\nexport function getRequestStatusThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) {\n  return (dispatch: Dispatch<RequestStatusReduxActions>, getState: () => { requestStatus: IRequestStatusState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(isLoadingRequestStatusAction(hideLoading ? false : true));\n    const page = nextPage ? nextPage : state.requestStatus.pagination.page;\n    dispatch(changeOrderRequestStatusAction(orderBy, orderType));\n    dispatch(cancelRequestStatusAction(api.getSource()));\n    Axios\n      .all([\n        api.getRequestItemsStatus({ page, orderBy, orderType })\n      ])\n      .then(Axios.spread((status) => {\n        const { data } = status;\n        dispatch(loadRequestStatusAction(data.results, data.count, data.pages, page));\n        dispatch(isLoadingRequestStatusAction(false));\n      }))\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingRequestStatusAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function createRequestStatusThunkAction(requestStatus: IRequestStatus) {\n  return (dispatch: Dispatch<RequestStatusReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.createRequestItemsStatus(requestStatus)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateRequestStatusItemAction(idRequestStatus, data));\n      });\n  };\n}\n\nexport function updateRequestStatusThunkAction(requestStatus: IRequestStatus) {\n  return (dispatch: Dispatch<RequestStatusReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.updateRequestItemsStatus(requestStatus)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateRequestStatusItemAction(idRequestStatus, data));\n      });\n  };\n}\n\nexport function deleteRequestStatusItemThunkAction(requestStatus: IRequestStatus) {\n  return (dispatch: Dispatch<RequestStatusReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.deleteRequestItemsStatus(requestStatus)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateRequestStatusItemAction(idRequestStatus, data));\n      });\n  };\n}\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { Field, InjectedFormProps, reduxForm } from 'redux-form';\nimport { IRequestStatusState } from '../../actions/requestStatus.types';\nimport BootstrapSwitchField from '../Utils/forms/BootsrapSwitchField';\nimport InputField from '../Utils/forms/InputField';\nimport { inputStringRequired } from '../Utils/forms/validations';\n\ninterface IPropsType extends InjectedFormProps {\n  update: boolean;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass Form extends React.Component<IPropsType, IStateType> {\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n  public render(): React.ReactElement<IPropsType> {\n    const { handleSubmit, valid, submitFailed } = this.props;\n    return (\n      <form onSubmit={handleSubmit}>\n        <div className=\"row\">\n          <div className=\"col-md-12\">\n            <Field\n              name=\"name\"\n              label=\"Nombre *\"\n              placeholder=\"Nombre\"\n              type=\"text\"\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>\n          <div className=\"col-md-12\">\n            <Field\n              name=\"weigth\"\n              label=\"Peso *\"\n              placeholder=\"Peso\"\n              type=\"text\"\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>\n          <div className=\"col-md-12\">\n            <Field\n              name={`default`}\n              label=\"Por defecto\"\n              type=\"checkbox\"\n              component={BootstrapSwitchField}\n              validate={[]}\n            />\n          </div>\n          {\n            submitFailed && valid === false &&\n            <div className=\"col-md-12\">\n              <div\n                className=\"alert alert-danger\"\n                style={{ marginTop: '20px' }}\n              >\n                Todos los campos con * son obligatorios\n              </div>\n            </div>\n          }\n        </div>\n      </form>\n    );\n  }\n}\n\nconst StatusForm = reduxForm({\n  form: 'statusForm'\n})(Form);\n\nconst mapStateToProps = (state: { requestStatus: IRequestStatusState }) => {\n  return {\n    requestStatus: state.requestStatus\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{ requestStatus: IRequestStatusState }, { dispatch: any }, IPropsType | {}>(mapStateToProps, mapDispatchToProps)(StatusForm);","import * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport {IBaseCompany, ICompany} from '../../../../../../src/app/interfaces/company.interface';\nimport {\n  changeTempCompanyAction,\n  CompaniesReduxAction,\n  createCompanyAction, deleteCompanyAction,\n  getCompaniesAction,\n  ICompaniesState,\n  updateCompanyAction\n} from '../../actions/companies.actions';\nimport {loadDataAction, ModalReduxAction} from '../../actions/modal.actions';\nimport AppContainer from '../../container/AppContainer';\nimport {IWindow} from '../../interfaces/window';\nimport {hasPermission} from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport CompaniesFormView from './CompaniesFormView';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\n\ninterface IPropsType extends RouteComponentProps<{ company: string }> {\n  dispatch: Dispatch<CompaniesReduxAction>;\n  companies: ICompaniesState;\n\n  getCompaniesAction(page: number): CompaniesReduxAction;\n  createCompanyAction(): CompaniesReduxAction;\n  updateCompanyAction(): CompaniesReduxAction;\n  deleteCompanyAction(id?: string): CompaniesReduxAction;\n  changeTempCompanyAction(company: IBaseCompany): CompaniesReduxAction;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass CompaniesListView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de empresas';\n    this.addCompany = this.addCompany.bind(this);\n    this.processAddCompany = this.processAddCompany.bind(this);\n    this.udpateCompany = this.udpateCompany.bind(this);\n    this.processUpdateCompany = this.processUpdateCompany.bind(this);\n    this.deleteCompany = this.deleteCompany.bind(this);\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public componentWillMount(): void {\n    const {pagination} = this.props.companies;\n    this.props.getCompaniesAction(pagination.page);\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.companies.source) {\n      this.props.companies.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {loading, companies, pagination} = this.props.companies;\n    return (\n      <AppContainer title=\"\" cMenu=\"10\" cSubMenu=\"10.3\" cAction=\"Listado\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\"><h3 className=\"box-title\">Empresas <small>{pagination.count}</small></h3>\n              {\n                hasPermission(window.user, 'addCompany') ?\n                  <div className=\"box-tools pull-right\">\n                    <button className=\"btn btn-sm btn-success\" onClick={this.addCompany}><i className=\"fa fa-plus\" /> Agregar</button>\n                  </div>\n                  : null\n              }\n            </div>\n            <div className=\"box-body no-padding\">\n              <table className=\"table table-andes table-striped\">\n                <thead>\n                  <tr>\n                    <th style={{width: '60%'}} className=\"middle\">Nombre</th>\n                    <th style={{width: '20%'}} className=\"middle hidden-xs\">Modificado</th>\n                    {\n                      window.user.isAdmin ?\n                        <th style={{width: '1%'}} className=\"width-10\">Billing</th> : null\n                    }\n                    {\n                      hasPermission(window.user, 'changeCompany') ?\n                        <th style={{width: '1%'}} className=\"width-10\"/> : null\n                    }\n                    {\n                      hasPermission(window.user, 'deleteCompany') ?\n                        <th style={{width: '1%'}} className=\"width-10\"/> : null\n                    }\n                  </tr>\n                </thead>\n                <tbody>\n                  {\n                    companies.map((company: ICompany) => {\n                      return (\n                        <tr\n                          key={company._id}\n                          id={`company-${company._id}`}\n                          className={'background-transition'}\n                        >\n                          <td className=\"middle\">{company.name}</td>\n                          <td className=\"middle hidden-xs\">{moment(company.updatedAt).format('LLL')}</td>\n                          {\n                            window.user.isAdmin ?\n                              <td className=\"middle text-center\">\n                                <i\n                                  className={\n                                    company.billing.active ?\n                                      'fa fa-check-circle text-green':\n                                      'fa fa-times-circle text-red'\n                                  }\n                                />\n                              </td> : null\n                          }\n                          {\n                            hasPermission(window.user, 'changeCompany') ?\n                              <td\n                                className=\"middle text-blue pointer\"\n                                onClick={() => this.udpateCompany(company)}>\n                                <i className=\"fa fa-pencil\"/>\n                              </td> : null\n                          }\n                          {\n                            hasPermission(window.user, 'deleteCompany') ?\n                              <td\n                                className={'middle text-red pointer'}\n                                onClick={() => this.deleteCompany(company)}\n                              ><i className=\"fa fa-minus-circle\"/></td> : null\n                          }\n                        </tr>\n                      );\n                    })\n                  }\n                </tbody>\n              </table>\n            </div>\n            {\n              pagination.pages > 1 &&\n                <div className=\"box-footer text-right\">\n                  <Paginator changePage={this.props.getCompaniesAction} page={pagination.page} pages={pagination.pages} />\n                </div>\n            }\n            {\n              loading &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private addCompany(): void {\n    this.props.changeTempCompanyAction({\n      _id: '',\n      name: '',\n      businessName: '',\n      rut: '',\n      image: null,\n      marker: null,\n      markerURI: '/static/images/files/pin_osa.svg',\n      billing: {\n        active: false,\n        checklistPrice: 0.0,\n        inventoryPrice: 0.0,\n        requestPrice: 0.0\n      },\n      notifications: []\n    });\n    setTimeout(() => {\n      this.props.loadDataAction(\n        'Agregar Empresa',\n        <CompaniesFormView />,\n        <React.Fragment>\n          <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n          <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processAddCompany}>Grabar</button>\n        </React.Fragment>\n      );\n    }, 400);\n  }\n\n  private processAddCompany(): void {\n    const {tempCompany} = this.props.companies;\n    if (!tempCompany.name || !tempCompany.name.trim()) {\n      swal('Agregar empresa', 'El nombres es requerido', 'error');\n    } else {\n      this.props.createCompanyAction();\n    }\n  }\n\n  private udpateCompany(company: ICompany): void {\n    const {_id, name, businessName, rut, billing, marker, image, notifications} = company;\n    this.props.changeTempCompanyAction({\n      _id,\n      name,\n      businessName,\n      rut,\n      image: null,\n      marker: null,\n      imageURI: image && image.hasOwnProperty('url') ? decodeURI(image.url) : null,\n      markerURI: marker && marker.hasOwnProperty('url') ? decodeURI(marker.url) : '/static/images/files/pin_osa.svg',\n      billing,\n      notifications\n    });\n    setTimeout(() => {\n      this.props.loadDataAction(\n        'Editar Empresa',\n        <CompaniesFormView />,\n        <React.Fragment>\n          <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n          <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processUpdateCompany}>Editar</button>\n        </React.Fragment>\n      );\n    }, 400);\n  }\n\n  private processUpdateCompany(): void {\n    const {name} = this.props.companies.tempCompany;\n    if (!name || !name.trim()) {\n      swal('Editar Empresa', 'El nombres es requerido', 'error');\n    } else {\n      this.props.updateCompanyAction();\n    }\n  }\n\n  private deleteCompany(company: ICompany): void {\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar la empresa ${company.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete: any) => {\n      if (willDelete) {\n        this.props.deleteCompanyAction(company._id);\n      }\n    });\n  }\n}\n\nconst mapStateToProps = (state: { companies: ICompaniesState }) => {\n  return {\n    companies: state.companies\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getCompaniesAction: (page: number) => dispatch(getCompaniesAction(page)),\n    createCompanyAction: () => dispatch(createCompanyAction()),\n    updateCompanyAction: () => dispatch(updateCompanyAction()),\n    deleteCompanyAction: (id: string) => dispatch(deleteCompanyAction(id)),\n    changeTempCompanyAction: (company: IBaseCompany) => dispatch(changeTempCompanyAction(company)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{companies: ICompaniesState}, {dispatch: any}, IPropsType>(mapStateToProps, mapDispatchToProps)(CompaniesListView);\n","import * as React from 'react';\nimport {connect} from 'react-redux';\nimport {IBaseCompany} from '../../../../../../src/app/interfaces/company.interface';\nimport {\n  changeTempCompanyAction,\n  CompaniesReduxAction,\n  ICompaniesState\n} from '../../actions/companies.actions';\nimport ImageLazyLoad from '../Utils/ImageLazyLoad';\nimport BootstrapSwitch from '../Utils/BootstrapSwitch';\nimport * as uuid from 'uuid';\n\ninterface IPropsType {\n  companies?: ICompaniesState;\n  changeTempCompanyAction?: (company: IBaseCompany) => CompaniesReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  canDrop: boolean;\n  tmpReceiver: any;\n}\n\nclass CompaniesFormView extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null,\n    canDrop: false,\n    tmpReceiver:{\n      name: '',\n      email: ''\n    }\n  };\n  readonly inputImage: React.RefObject<HTMLInputElement>;\n  readonly inputMarker: React.RefObject<HTMLInputElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.clickUploadFile = this.clickUploadFile.bind(this);\n    this.handleChangeInputFile = this.handleChangeInputFile.bind(this);\n    this.handleDrop = this.handleDrop.bind(this);\n    this.handleAddReceiver = this.handleAddReceiver.bind(this);\n    this.handleRemoveReceiver = this.handleRemoveReceiver.bind(this);\n    this.dragOverHandler = this.dragOverHandler.bind(this);\n    this.dragEndHandler = this.dragEndHandler.bind(this);\n    this.dragLeaveHandler = this.dragLeaveHandler.bind(this);\n    this.inputImage = React.createRef();\n    this.inputMarker = React.createRef();\n  }\n\n  render(): React.ReactElement<IPropsType> | null {\n    if (this.props.companies && this.props.changeTempCompanyAction) {\n      const {tempCompany} = this.props.companies;\n      const {changeTempCompanyAction} = this.props;\n      const {tmpReceiver} = this.state;\n      return (\n        <React.Fragment>\n          <ul className=\"nav nav-tabs\" style={{marginBottom: '15px'}}>\n            <li className=\"active\"><a data-toggle=\"tab\" href=\"#general\">General</a></li>\n            <li><a data-toggle=\"tab\" href=\"#billing\">Billing</a></li>\n            <li><a data-toggle=\"tab\" href=\"#customizations\">Personalizaciones</a></li>\n          </ul>\n          <div className=\"tab-content\">\n            <div id=\"general\" className=\"tab-pane fade in active\">\n              <div className=\"row\">\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label>Nombre</label>\n                    <input\n                      type=\"text\"\n                      name=\"fistName\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      defaultValue={tempCompany ? tempCompany.name : ''}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempCompanyAction({\n                          ...tempCompany,\n                          name: e.target.value.trim()\n                        })\n                      }\n                    />\n                  </div>\n                  <div className=\"form-group\">\n                    <label>Razón social</label>\n                    <input\n                      type=\"text\"\n                      name=\"fistName\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      defaultValue={tempCompany ? tempCompany.businessName : ''}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempCompanyAction({\n                          ...tempCompany,\n                          businessName: e.target.value.trim()\n                        })\n                      }\n                    />\n                  </div>\n                  <div className=\"form-group\">\n                    <label>RUT</label>\n                    <input\n                      type=\"text\"\n                      name=\"fistName\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      defaultValue={tempCompany ? tempCompany.rut : ''}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempCompanyAction({\n                          ...tempCompany,\n                          rut: e.target.value.trim()\n                        })\n                      }\n                    />\n                  </div>\n                  <div className=\"form-group-switch\">\n                    <BootstrapSwitch\n                      checked={tempCompany.billing.active}\n                      color=\"blue\"\n                      onChange={() => {\n                        changeTempCompanyAction({\n                          ...tempCompany,\n                          billing: {\n                            ...tempCompany.billing,\n                            active: !tempCompany.billing.active\n                          }\n                        });\n                      }}/>\n                    <label className=\"switch-label\">Activar billing</label>\n                  </div>\n                </div>\n              </div>\n            </div>\n            <div id=\"billing\" className=\"tab-pane fade\">\n              <div className=\"row\">\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label>Precio Inventario</label>\n                    <input\n                      type=\"number\"\n                      name=\"fistName\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      defaultValue={tempCompany ? tempCompany.billing.inventoryPrice : '0.0'}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempCompanyAction({\n                          ...tempCompany,\n                          billing: {\n                            ...tempCompany.billing,\n                            inventoryPrice: parseFloat(e.target.value.trim())\n                          }\n                        })\n                      }\n                    />\n                  </div>\n                  <div className=\"form-group\">\n                    <label>Precio Checklist</label>\n                    <input\n                      type=\"number\"\n                      name=\"fistName\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      defaultValue={tempCompany ? tempCompany.billing.checklistPrice : '0.0'}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempCompanyAction({\n                          ...tempCompany,\n                          billing: {\n                            ...tempCompany.billing,\n                            checklistPrice: parseFloat(e.target.value.trim())\n                          }\n                        })\n                      }\n                    />\n                  </div>\n                  <div className=\"form-group\">\n                    <label>Precio Solicitudes</label>\n                    <input\n                      type=\"number\"\n                      name=\"fistName\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      defaultValue={tempCompany ? tempCompany.billing.requestPrice : '0.0'}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempCompanyAction({\n                          ...tempCompany,\n                          billing: {\n                            ...tempCompany.billing,\n                            requestPrice: parseFloat(e.target.value.trim())\n                          }\n                        })\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <strong style={{color: '#2372bb'}}>Notificaciones</strong>\n                  <table className=\"table table-striped\">\n                    <thead>\n                    <tr>\n                      <th>Nombre</th>\n                      <th>Email</th>\n                      <th/>\n                    </tr>\n                    </thead>\n                    <tbody>\n                    {\n                      !tempCompany.notifications.length ?\n                        <tr>\n                          <td colSpan={3} className={'text-center'}>\n                            <strong>No se han agregado destinatarios</strong>\n                          </td>\n                        </tr> :\n                        null\n                    }\n                    {\n                      tempCompany.notifications.map((notification) => (\n                        <tr key={notification._id ? notification._id : notification.tempID}>\n                          <td width={'45%'}>{notification.name}</td>\n                          <td width={'45%'}>{notification.email}</td>\n                          <td\n                            className={'text-center'}\n                          >\n                            <i\n                              className=\"fa fa-minus-circle text-red\"\n                              onClick={() => this.handleRemoveReceiver(notification._id || notification.tempID)}\n                            />\n                          </td>\n                        </tr>\n                      ))\n                    }\n                    </tbody>\n                  </table>\n                  {/*<div className=\"alert alert-info alert-dismissible\">*/}\n                  {/*  <p>Estos son los destinatarios que recibiran un correo mensual con el informe de billing.</p>*/}\n                  {/*</div>*/}\n                </div>\n                <div className=\"col-md-5\">\n                  <div className=\"form-group\">\n                    <label>Nombre</label>\n                    <input\n                      type=\"text\"\n                      name=\"receiverName\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      value={tmpReceiver.name}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => this.setState({\n                          tmpReceiver: {\n                            ...this.state.tmpReceiver,\n                            name: e.target.value\n                          }\n                        })\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-7\">\n                  <div className=\"form-group\">\n                    <label>Email</label>\n                    <input\n                      type=\"text\"\n                      name=\"receiverEmail\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      value={tmpReceiver.email}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => this.setState({\n                          tmpReceiver: {\n                            ...this.state.tmpReceiver,\n                            email: e.target.value.trim()\n                          }\n                        })\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12 text-right\">\n                  <button\n                    className=\"btn btn-sm btn-success\"\n                    onClick={this.handleAddReceiver}\n                  >\n                    Agregar Destinatario\n                  </button>\n                </div>\n              </div>\n            </div>\n            <div id=\"customizations\" className=\"tab-pane fade\">\n              <div className=\"row\">\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label>Imagen</label>\n                    {\n                      tempCompany.imageURI ?\n                        <div\n                          className=\"change-image-wrapper text-center\"\n                          style={{display: 'table', width: '100%', color: '#2776b8'}}\n                          onClick={() => this.clickUploadFile('inputImage')}\n                        >\n                          <ImageLazyLoad\n                            url={tempCompany.imageURI}\n                            height={'200px'}\n                            style={{\n                              maxWidth: '100%',\n                              maxHeight: '200px'\n                            }}\n                          />\n                          <div className=\"text-layer pointer\">\n                            <p className=\"text\">\n                              <i className=\"fa fa-2x fa-cloud-upload\"/> <br/>Haz click aquí para cambiar la imágen.\n                            </p>\n                          </div>\n                        </div> :\n                        <div\n                          className=\"upload-file text-center pointer\"\n                          onClick={() => this.clickUploadFile('inputImage')}\n                          onDrop={(e) => this.handleDrop(e, 'image')}\n                          onDragOver={this.dragOverHandler}\n                          onDragEnd={this.dragEndHandler}\n                          onDragLeave={this.dragLeaveHandler}\n                          style={{\n                            backgroundColor: '#EEEEEE',\n                            border: this.state.canDrop ? '1px solid #979797' : '1px dashed #979797',\n                            padding: '100px 20px',\n                            color: this.state.canDrop ? '#aebccb' : '#6e7a89',\n                            borderRadius: '5px',\n                            marginBottom: '10px'\n                          }}>\n                          <i className=\"fa fa-2x fa-cloud-upload\"/><br/>\n                          Prueba a soltanto la imágen aquí, o haz click para seleccionar la imágen a cargar.\n                        </div>\n                    }\n                    <input\n                      type=\"file\"\n                      accept=\"image/*\"\n                      ref={this.inputImage}\n                      style={{display: 'none'}}\n                      onChange={(e) => this.handleChangeInputFile(e, 'image')}\n                    />\n                  </div>\n                  <div className=\"form-group\">\n                    <label>Marcador de Mapa</label>\n                    {\n                      tempCompany.markerURI ?\n                        <div\n                          className=\"change-image-wrapper text-center\"\n                          style={{display: 'table', width: '100%', color: '#2776b8'}}\n                          onClick={() => this.clickUploadFile('inputMarker')}\n                        >\n                          <ImageLazyLoad\n                            url={tempCompany.markerURI}\n                            height={'100px'}\n                            style={{\n                              maxWidth: '100px'\n                            }}\n                          />\n                          <div className=\"text-layer pointer\">\n                            <p className=\"text\">\n                              <i className=\"fa fa-2x fa-cloud-upload\"/> <br/>Haz click aquí para cambiar la imágen.\n                            </p>\n                          </div>\n                        </div> :\n                        <div\n                          className=\"upload-file text-center pointer\"\n                          onClick={() => this.clickUploadFile('inputMarker')}\n                          onDrop={(e) => this.handleDrop(e, 'marker')}\n                          onDragOver={this.dragOverHandler}\n                          onDragEnd={this.dragEndHandler}\n                          onDragLeave={this.dragLeaveHandler}\n                          style={{\n                            backgroundColor: '#EEEEEE',\n                            border: this.state.canDrop ? '1px solid #979797' : '1px dashed #979797',\n                            padding: '24px 20px',\n                            color: this.state.canDrop ? '#aebccb' : '#6e7a89',\n                            borderRadius: '5px',\n                            marginBottom: '10px',\n                            height: '100px'\n                          }}>\n                          <i className=\"fa fa-2x fa-cloud-upload\"/><br/>\n                          Prueba a soltanto la imágen aquí, o haz click para seleccionar la imágen a cargar.\n                        </div>\n                    }\n                    <input\n                      type=\"file\"\n                      accept=\"image/*\"\n                      ref={this.inputMarker}\n                      style={{display: 'none'}}\n                      onChange={(e) => this.handleChangeInputFile(e, 'marker')}\n                    />\n                  </div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </React.Fragment>\n      );\n    }\n    return null;\n  }\n\n  private handleAddReceiver(){\n    const {tmpReceiver} = this.state;\n    this.props.changeTempCompanyAction!({\n      ...this.props.companies!.tempCompany,\n      notifications: [...this.props.companies!.tempCompany.notifications!, {\n        ...tmpReceiver,\n        tempID: uuid.v1()\n      }]\n    });\n    this.setState({\n      tmpReceiver: {\n        name: '',\n        email: ''\n      }\n    });\n  }\n\n  private handleRemoveReceiver(id: any) {\n    this.props.changeTempCompanyAction!({\n      ...this.props.companies!.tempCompany,\n      notifications: this.props.companies!.tempCompany.notifications!.filter((notification) => {\n        return notification._id !== id && notification.tempID !== id;\n      })\n    });\n  }\n\n  private clickUploadFile(input: 'inputImage' | 'inputMarker') {\n    if (this[input].current) {\n      this[input].current!.click();\n    }\n  }\n\n  private handleDrop(e: React.DragEvent<HTMLDivElement>, input: 'marker' | 'image'): void {\n    e.preventDefault();\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      if (dt.items.length) {\n        const file: File | null = dt.items[0].getAsFile();\n        if (file) {\n          this.processFile(file, input);\n        }\n      }\n    } else {\n      if (dt.files.length) {\n        const file = dt.files[0];\n        this.processFile(file, input);\n      }\n    }\n  }\n\n  private handleChangeInputFile(e: React.ChangeEvent<HTMLInputElement>, input: 'marker' | 'image' ) {\n    const {files} = e.target;\n    if (files && files.length) {\n      const file = files[0];\n      this.processFile(file, input);\n    }\n  }\n\n  private dragOverHandler(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    this.setState({\n      canDrop: true\n    });\n  }\n\n  private dragLeaveHandler(): void {\n    this.setState({\n      canDrop: false\n    });\n  }\n\n  private dragEndHandler(e: React.DragEvent<HTMLDivElement>): void {\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      // Use DataTransferItemList interface to remove the drag data\n      for (let i = 0; i < dt.items.length; i++) {\n        dt.items.remove(i);\n      }\n    } else {\n      // Use DataTransfer interface to remove the drag data\n      e.dataTransfer.clearData();\n    }\n  }\n\n  private processFile(file: File, input: 'marker' | 'image'): void {\n    if (file && this.props.companies && this.props.changeTempCompanyAction) {\n      const {tempCompany} = this.props.companies;\n      const {changeTempCompanyAction} = this.props;\n      const reader: FileReader = new FileReader();\n      reader.onload = (e: ProgressEvent) => {\n        if (e.target) {\n          changeTempCompanyAction({\n            ...tempCompany,\n            [`${input}URI`]: (e.target as any).result,\n            [input]: file\n          });\n        }\n      };\n      reader.readAsDataURL(file);\n    }\n  }\n}\n\nconst mapStateToProps = (state: { companies: ICompaniesState }) => {\n  return {\n    companies: state.companies\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    changeTempCompanyAction: (company: IBaseCompany) => dispatch(changeTempCompanyAction(company))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(CompaniesFormView);\n","// import * as PropTypes from 'prop-types';\nimport * as Raven from 'raven-js';\nimport * as moment from 'moment';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport { DashboardReduxAction } from '../../actions/dashboard.actions';\nimport { getDashboardDamagesPerVenue, IDashboardDamagesState } from '../../actions/dashboardDamages.actions';\nimport AppContainer from '../../container/AppContainer';\nimport Row from '../Utils/Row';\nimport { IWindow } from '../../interfaces/window';\nimport * as swal from 'sweetalert';\nimport { default as Axios } from 'axios';\nimport ApiService from '../../utils/axios';\nimport { hasPermission } from '../../utils/common';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ndeclare let window: IWindow;\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<DashboardReduxAction>;\n  dashboard: IDashboardDamagesState;\n\n  getDashboardDamagesPerVenue(update?: boolean): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  detail: boolean;\n  detailName: string;\n  exporting: boolean\n}\n\nclass DashboardDamagesView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  readonly state: IStateType = {\n    error: null,\n    detail: false,\n    detailName: '',\n    exporting: false,\n  };\n  protected damagesPerVenueChart: echarts.ECharts;\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Reportería de daños';\n    this.resizeCharts = this.resizeCharts.bind(this);\n    this.showdetail = this.showdetail.bind(this);\n    this.back = this.back.bind(this);\n    this.updateDamagesPerVenueChart = this.updateDamagesPerVenueChart.bind(this);\n    this.exportDamages = this.exportDamages.bind(this);\n  }\n\n  public componentWillMount(): void {\n    // get data\n    this.props.getDashboardDamagesPerVenue(true);\n    // add listeners\n    window.addEventListener('resize', this.resizeCharts, false);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: (window.user as any).token\n      }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {room: `dashboard-vin-view-${window.user.team._id}`});\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update) {\n        this.props.getDashboardDamagesPerVenue();\n      }\n    });\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    const $damagesPerVenue = document.getElementById('damages-per-venue') as HTMLDivElement;\n    this.damagesPerVenueChart = echarts.init($damagesPerVenue);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: IPropsType, prevState: IStateType): void {\n    this.updateDamagesPerVenueChart();\n  }\n\n  public componentWillUnmount() {\n    // remove listeners\n    window.removeEventListener('resize', this.resizeCharts, false);\n    this.socket.disconnect();\n  }\n\n  public exportDamages() {\n    this.setState({\n      exporting: true\n    });\n    this.trackClick(\"Exportar\");\n    const api: ApiService = new ApiService();\n    const instance = api.getInstance();\n    instance.defaults.responseType = 'blob';\n    instance\n      .get(`/api/damages/export/`)\n      .then((response) => {\n        const blob = new Blob([response.data], {\n          type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'\n        });\n        const fileName = `${moment().format('YYYYMMDD')}-danos.xlsx`;\n        if (typeof window.navigator.msSaveBlob !== 'undefined') {\n          // IE workaround for \"HTML7007: One or more blob URLs were\n          // revoked by closing the blob for which they were created.\n          // These URLs will no longer resolve as the data backing\n          // the URL has been freed.\"\n          window.navigator.msSaveBlob(blob, fileName);\n        } else {\n          const blobURL = URL.createObjectURL(blob);\n          const tempLink = document.createElement('a');\n          tempLink.style.display = 'none';\n          tempLink.href = blobURL;\n          tempLink.setAttribute('download', fileName);\n          // Safari thinks _blank anchor are pop ups. We only want to set _blank\n          // target if the browser does not support the HTML5 download attribute.\n          // This allows you to download files in desktop safari if pop up blocking\n          // is enabled.\n          if (typeof tempLink.download === 'undefined') {\n            tempLink.setAttribute('target', '_blank');\n          }\n          this.setState({\n            exporting: false\n          });\n          document.body.appendChild(tempLink);\n          tempLink.click();\n          document.body.removeChild(tempLink);\n          URL.revokeObjectURL(blobURL);\n        }\n      })\n      .catch((err) => {\n        this.setState({\n          exporting: false\n        });\n        if (!Axios.isCancel(err)) {\n          swal('Exportar daños', 'Ha ocurrido un error al general el excel.', 'error');\n        }\n      });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {loading} = this.props.dashboard;\n    const {detail, detailName, exporting} = this.state;\n    return (\n      <AppContainer title=\"\" cMenu=\"1\" cSubMenu=\"1.4\">\n        <section className=\"content\">\n          <Row>\n            <div className=\"col-md-12\">\n              <div className=\"box\">\n                <div className='box-header with-border'>\n                  <h3 className='box-title'>Dashboard de daños</h3>\n                  {\n                    false && hasPermission(window.user, 'exportDamages') ?\n                    <div className='box-tools pull-right'>\n                      <button\n                        className='btn btn-sm btn-primary hidden-xs hidden-sm'\n                        onClick={this.exportDamages}\n                        disabled={exporting}\n                      >\n                        {\n                          exporting ?\n                            <React.Fragment>\n                              <i className='fa fa-fw fa-spinner fa-spin'></i> Exportando reporte\n                            </React.Fragment>\n                            :\n                            <React.Fragment>\n                              <i className='fa fa-fw fa-download'></i> Exportar reporte\n                            </React.Fragment>\n                        }\n                      </button>\n                    </div>\n                    :\n                    null\n                  }\n                </div>\n                <div className=\"box-body\">\n                  {\n                    detail ?\n                      <div className=\"text-center\">\n                        <h4 className=\"text-muted\" style={{margin: '0 5px'}}>Detalle del {detailName}</h4>\n                        <p className=\"text-muted\">Para volver al detalle por día haz <a\n                          href=\"javascript:void(0)\"\n                          onClick={this.back}\n                        >click aquí</a></p>\n                      </div> :\n                      <div className=\"text-center\">\n                        <h4 className=\"text-muted\" style={{margin: '0 5px'}}>Detalle de daños por día</h4>\n                        <p className=\"text-muted\">Haz click sobre una barra para ver el detalle por sucursales</p>\n                      </div>\n                  }\n                  <div id=\"damages-per-venue\" style={{height: '70vh', maxWidth: '100%'}}/>\n\n                </div>\n                {\n                  loading &&\n                  <div className=\"overlay\">\n                    <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                  </div>\n                }\n              </div>\n            </div>\n          </Row>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private updateDamagesPerVenueChart() {\n    const {loading} = this.props.dashboard;\n    if (!loading) {\n      const {data} = this.props.dashboard;\n      const {detail, detailName} = this.state;\n      let damages = [],\n          undamages = [];\n      let category = Object.keys(data).reverse();\n      if (detail) {\n        let detailData = [];\n        for(const key in data[detailName]){\n          if ( data[detailName].hasOwnProperty(key) && !['damaged', 'undamaged'].includes(key)) {\n            const venue = data[detailName][key];\n            detailData.push(venue)\n          }\n        }\n        detailData = detailData.sort((a, b) => (a.name > b.name) ? 1 : ((b.name > a.name) ? -1 : 0));\n        const detailCategories = [];\n        for (const venue of detailData) {\n            detailCategories.push(venue.name);\n            damages.push(venue.damaged);\n            undamages.push(venue.undamaged);\n        }\n        category = detailCategories;\n      } else {\n        for (const key in data) {\n          if (data.hasOwnProperty(key)) {\n            const day = data[key];\n            damages.push(day.damaged);\n            undamages.push(day.undamaged);\n          }\n        }\n        damages = damages.reverse()\n        undamages = undamages.reverse()\n      }\n\n      const option: echarts.EChartOption = {\n        color: ['#00aa51', '#f1392c'],\n        tooltip: {\n          trigger: 'axis',\n          axisPointer: {\n            type: 'shadow'\n          }\n        },\n        legend: {\n          data: ['Sin daños', 'Con daños'],\n          // x: 'center',\n          bottom: 50,\n        },\n        xAxis: {\n          type: 'category',\n          axisTick: {show: false},\n          data: category,\n          axisLine: {\n            lineStyle: {\n              color: 'rgba(0, 0, 0, 0.5)'\n            }\n          },\n          splitLine: {\n            show: false,\n            lineStyle: {\n              type: 'dashed',\n              color: 'rgba(150, 150, 150, 0.5)'\n            }\n          },\n          axisLabel: {\n            rotate: 60,\n            fontSize: 10,\n            formatter: function (value: string) {\n              let text = '';\n              const array = value.split(\" \");\n              for (let i = 0; i < array.length; i++) {\n                text += `${array[i]}`;\n                if (i > 0 && i % 2 !== 0) {\n                  text += ' \\n';\n                } else {\n                  text += ' ';\n                }\n              }\n              return text;\n            }\n          }\n        },\n        grid: {\n          top: 10,\n          bottom: 100,\n          // left\n          left: 5,\n          // right\n          right: 10,\n          containLabel: true\n        },\n        yAxis: [\n          {\n            minInterval: 1,\n            type: 'value',\n            axisLine: {\n              lineStyle: {\n                color: 'rgba(0, 0, 0, 0.5)'\n              }\n            },\n            splitLine: {\n              show: true,\n              lineStyle: {\n                type: 'dashed',\n                color: 'rgba(150, 150, 150, 0.5)'\n              }\n            }\n          }\n        ],\n        series: [\n          {\n            name: 'Sin daños',\n            type: 'bar',\n            barGap: \"0.1\",\n            barMaxWidth: 50,\n            data: undamages\n          },\n          {\n            name: 'Con daños',\n            type: 'bar',\n            barGap: \"0.1\",\n            barMaxWidth: 50,\n            data: damages\n          }\n        ],\n        dataZoom: [{\n          show: true,\n          realtime: true,\n          start: 0,\n          end: 100\n        }]\n      };\n      this.damagesPerVenueChart.setOption(option);\n      this.damagesPerVenueChart.off('click');\n      this.damagesPerVenueChart.on('click', (params: any) => {\n        this.showdetail(params.name);\n      });\n    }\n  }\n\n  private back(){\n    this.setState({detail: false, detailName: ''})\n  }\n\n  private showdetail(name: string){\n    const {detail} =this.state;\n    const {data} = this.props.dashboard;\n    if(!detail && data.hasOwnProperty(name)){\n      const day = data[name];\n      if(day.damaged || day.undamaged){\n        this.setState({\n          detailName: name,\n          detail: true\n        })\n      }\n    }\n  }\n\n  private resizeCharts() {\n    if (this.damagesPerVenueChart) {\n      this.damagesPerVenueChart.resize();\n      setTimeout(() => {\n        this.damagesPerVenueChart.resize();\n      }, 400);\n    }\n  }\n}\n\nconst mapStateToProps = (state: { dashboardDamages: IDashboardDamagesState }) => {\n  return {\n    dashboard: state.dashboardDamages\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getDashboardDamagesPerVenue: (update?: boolean) => dispatch(getDashboardDamagesPerVenue(update))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DashboardDamagesView);\n","import {AxiosError, default as Axios} from 'axios';\nimport {Dispatch} from 'redux';\nimport ApiService from '../utils/axios';\n\nexport interface IDashboardDamagesState {\n  data: any;\n  venues: any[],\n  loading: boolean;\n}\n\ninterface ILoadDashboardDamages {\n  type: '/DASHBOARD/DAMAGES/LOAD_DATA';\n  payload: {\n    data: any\n  };\n}\n\nexport function loadDashboardDamagesAction(data: any): ILoadDashboardDamages {\n  return {\n    type: '/DASHBOARD/DAMAGES/LOAD_DATA',\n    payload: {\n      data\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/DASHBOARD/DAMAGES/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/DASHBOARD/DAMAGES/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function getDashboardDamagesPerVenue(update?: boolean) {\n  return (dispatch: Dispatch<DashboardDamagesReduxAction>) => {\n    const api: ApiService = new ApiService();\n    if (update) {\n      dispatch(isLoadingAction(true));\n    }\n    Axios.all([\n      api.getDashboardDamagesPerVenue()\n    ]).then(Axios.spread((dashboard) => {\n      dispatch(isLoadingAction(false));\n      dispatch(loadDashboardDamagesAction(dashboard.data));\n    })).catch((err: AxiosError): void => {\n      dispatch(isLoadingAction(false));\n      api.errorHandler(err);\n    });\n  };\n}\n\nexport type DashboardDamagesReduxAction = ILoadDashboardDamages | IIsLoading;\n","// import * as PropTypes from 'prop-types';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport {DashboardReduxAction} from '../../actions/dashboard.actions';\nimport AppContainer from '../../container/AppContainer';\nimport Row from '../Utils/Row';\nimport {getDashboardCleaning, IDashboardDercoState} from \"../../actions/dashboardDerco.actions\";\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<DashboardReduxAction>;\n  dashboard: IDashboardDercoState;\n\n  getDashboardCleaning(): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass DashboardDercoView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  cleaningPerDayChart: echarts.ECharts;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Reportería de daños';\n    this.resizeCharts = this.resizeCharts.bind(this);\n    this.updateCleaningPerDayChart = this.updateCleaningPerDayChart.bind(this);\n  }\n\n  public componentWillMount(): void {\n    // get data\n    this.props.getDashboardCleaning();\n    // add listeners\n    window.addEventListener('resize', this.resizeCharts, false);\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    const $cleaningPerDayChart = document.getElementById('cleaning-per-day') as HTMLDivElement;\n    this.cleaningPerDayChart = echarts.init($cleaningPerDayChart);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: IPropsType, prevState: IStateType): void {\n\n    const { cleaning } = this.props.dashboard;\n    if (!cleaning.loading) {\n      this.updateCleaningPerDayChart();\n    }\n  }\n\n  public componentWillUnmount() {\n    // remove listeners\n    window.removeEventListener('resize', this.resizeCharts, false);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { cleaning } = this.props.dashboard;\n    return (\n      <AppContainer title=\"\" cMenu=\"1\" cSubMenu=\"1.4\">\n        <section className=\"content\">\n          <Row>\n            <div className=\"col-md-12\">\n              <div className=\"box\">\n                <div className=\"box-header with-border\"><h3 className=\"box-title\"># Unidades con daños por sucursal</h3>\n                  <div className=\"box-tools pull-right\">\n                  </div>\n                </div>\n                <div className=\"box-body\">\n                  <div id=\"cleaning-per-day\" style={{height: '50vh', maxWidth: '100%'}} />\n                </div>\n                {\n                  cleaning.loading &&\n                  <div className=\"overlay\">\n                    <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                  </div>\n                }\n              </div>\n            </div>\n          </Row>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private updateCleaningPerDayChart() {\n\n    const { cleaning } = this.props.dashboard;\n\n    const option: any = {\n      color: ['#00aa51', '#f1392c'],\n      tooltip: {\n        trigger: 'axis',\n        axisPointer: {\n          type: 'shadow'\n        }\n      },\n      legend: {\n        data: ['Sin daños', 'Con daños'],\n        x: 'center',\n        bottom: 50\n      },\n      xAxis: {\n        data: cleaning.days,\n        axisLabel: {\n          rotate: 60\n        }\n\n      },\n      yAxis: {\n        // type: 'category',\n      },\n      grid: {\n        top: 30,\n        bottom: 100,\n        // left\n        x: 20,\n        // right\n        x2: 10,\n        containLabel: true\n      },\n      series: [\n        {\n          name: 'Limpios',\n          type: 'bar',\n          data: cleaning.clean,\n          stack: '1'\n        },\n        {\n          name: 'Con daños',\n          type: 'bar',\n          data: cleaning.notClean,\n          stack: '1'\n        }\n      ]\n    };\n    this.cleaningPerDayChart.setOption(option);\n\n  }\n\n  private resizeCharts() {\n    if (this.cleaningPerDayChart) {\n      this.cleaningPerDayChart.resize();\n      setTimeout(() => {\n        this.cleaningPerDayChart.resize();\n      }, 400);\n    }\n  }\n}\n\nconst mapStateToProps = (state: { dashboardDerco: IDashboardDercoState }) => {\n  return {\n    dashboard: state.dashboardDerco\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getDashboardCleaning: () => dispatch(getDashboardCleaning())\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DashboardDercoView);\n","import {AxiosError, default as Axios} from 'axios';\nimport {Dispatch} from 'redux';\nimport ApiService from '../utils/axios';\n\ninterface ICleaningData {\n  loading: boolean,\n  days: [],\n  clean: [],\n  notClean: []\n}\n\nexport interface IDashboardDercoState {\n  cleaning: ICleaningData\n}\n\ninterface ILoadDashboardCleaning {\n  type: '/DASHBOARD/CLEANING/LOAD_DATA_DAILY';\n  payload: {\n    cleaning: ICleaningData,\n  };\n}\n\nexport function loadDashboardCleaningAction(cleaning: ICleaningData): ILoadDashboardCleaning {\n  return {\n    type: '/DASHBOARD/CLEANING/LOAD_DATA_DAILY',\n    payload: {\n      cleaning\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/DASHBOARD/CLEANING/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/DASHBOARD/CLEANING/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function getDashboardCleaning() {\n  return (dispatch: Dispatch<DashboardDercoReduxAction>) => {\n    const api: ApiService = new ApiService();\n    dispatch(isLoadingAction(true));\n    Axios.all([\n      api.getVenues({ page: 1, pageSize: 200 }),\n      api.getDashboardCleaning()\n    ]).then(Axios.spread((venues, dashboard) => {\n      dispatch(loadDashboardCleaningAction(dashboard.data));\n    })).catch((err: AxiosError): void => {\n      api.errorHandler(err);\n    });\n  };\n}\n\nexport type DashboardDercoReduxAction = ILoadDashboardCleaning | IIsLoading\n","// import * as PropTypes from 'prop-types';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport {DashboardReduxAction, getParticipantsPerDateAction, IDashboardState} from '../../actions/dashboard.actions';\nimport AppContainer from '../../container/AppContainer';\nimport Row from '../Utils/Row';\nimport BootstrapSelect from '../Utils/BootstrapSelect';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport { hasPermission } from '../../utils/common';\nimport { IWindow } from '../../interfaces/window';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<DashboardReduxAction>;\n  dashboard: IDashboardState;\n\n  getParticipantsPerDateAction(companies?:string): void;\n}\n\ninterface IStateType {\n  selectedCompanies: any[];\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass DashboardGeneralView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  // static propTypes = {\n  //   dashboard: PropTypes.object.isRequired,\n  //   dispatch: PropTypes.func.isRequired,\n  //   getParticipantsPerDateAction: PropTypes.func.isRequired\n  // };\n  readonly state = {\n    error: null,\n    selectedCompanies: ['']\n  };\n\n  participantsPerDayChart: echarts.ECharts;\n  participantsRangeChart: echarts.ECharts;\n  carsByVenueChart: echarts.ECharts;\n\n  // chartsColors: string[] = ['#3085c1', '#5c4b55', '#55b188', '#4d5c99', '#c53e5a', '#f8d991'];\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Reportes generales';\n    this.resizeCharts = this.resizeCharts.bind(this);\n    this.updateParticipantsChart = this.updateParticipantsChart.bind(this);\n    this.updateCarsChart = this.updateCarsChart.bind(this);\n    this.updateChartParticipantRange = this.updateChartParticipantRange.bind(this);\n    this.filterCompanies = this.filterCompanies.bind(this);\n  }\n\n  public componentWillMount(): void {\n    // get data\n    this.props.getParticipantsPerDateAction();\n    // add listeners\n    window.addEventListener('resize', this.resizeCharts, false);\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    const $participantPerDate = document.getElementById('participant-per-date') as HTMLDivElement;\n    const $participantRange = document.getElementById('participant-range') as HTMLDivElement;\n    const $carsByVenue = document.getElementById('cars-by-venue') as HTMLDivElement;\n    this.participantsPerDayChart = echarts.init($participantPerDate);\n    this.carsByVenueChart = echarts.init($carsByVenue);\n    this.participantsRangeChart = echarts.init($participantRange);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: IPropsType, prevState: IStateType): void {\n    const {loading} = this.props.dashboard;\n    if (!loading) {\n      this.updateParticipantsChart();\n      // this.updateCarsChart();\n      this.updateChartParticipantRange();\n    }\n  }\n\n  public componentWillUnmount() {\n    // remove listeners\n    window.removeEventListener('resize', this.resizeCharts, false);\n    // cancel request if component is inmounted\n    if (this.props.dashboard.source) {\n      this.props.dashboard.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      loading, participantsReceivedPerDate, participantsSentPerDate, carsPerDate, totalCars, companies\n    } = this.props.dashboard;\n    const {selectedCompanies} = this.state;\n\n    return (\n      <AppContainer title=\"\" cMenu=\"1\" cSubMenu=\"1.1\">\n        <section className=\"content\">\n          <Row>\n            <div className=\"col-md-3 col-sm-6 col-xs-12\">\n              <div className=\"info-box\">\n                <span className=\"info-box-icon bg-aqua\"><i className=\"fa fa-clipboard\"/></span>\n                <div className=\"info-box-content\">\n                  <span className=\"info-box-text\">Revisiones Hoy</span>\n                  <span className=\"info-box-number\">\n                    {(participantsReceivedPerDate.length ? participantsReceivedPerDate[participantsReceivedPerDate.length - 1 ].total : 0) +participantsSentPerDate.length ? participantsSentPerDate[participantsSentPerDate.length - 1 ].total : 0 }\n                  </span>\n                </div>\n              </div>\n            </div>\n            <div className=\"col-md-3 col-sm-6 col-xs-12\">\n              <div className=\"info-box\">\n                <span className=\"info-box-icon bg-yellow\"><i className=\"fa fa-check-square\"/></span>\n                <div className=\"info-box-content\">\n                  <span className=\"info-box-text\">Cargados Hoy</span>\n                  <span className=\"info-box-number\">{carsPerDate.length ? carsPerDate[carsPerDate.length - 1 ].total : 0}</span>\n                </div>\n              </div>\n            </div>\n            <div className=\"col-md-3 col-sm-6 col-xs-12\">\n              <div className=\"info-box\">\n                <span className=\"info-box-icon bg-green\"><i className=\"fa fa-car\"/></span>\n                <div className=\"info-box-content\">\n                  <span className=\"info-box-text\">Total Cargas</span>\n                  <span className=\"info-box-number\">{new Intl.NumberFormat('es-CL').format(totalCars)}</span>\n                </div>\n              </div>\n            </div>\n          </Row>\n          <Row>\n            <div className=\"col-md-12\">\n              <div className=\"box\">\n                <div className=\"box-header with-border\"><h3 className=\"box-title\">Revisiones y cargas realizadas por día</h3>\n                  <div className=\"box-tools pull-right\">\n                  </div>\n                </div>\n                <div className=\"box-body\">\n                  <div className=\"row\">\n                    <div className=\"col-md-8\" />\n                    <div className=\"col-md-4\">\n                      <BootstrapSelect\n                        noneSelectedText=\"Todas las empresas\"\n                        displayItems={2}\n                        selectedText=\"empresas seleccionadas.\"\n                        selected={selectedCompanies}\n                        autoClouse={true}\n                        allOption={false}\n                        selectAll={() => ({})}\n                        options={[{value: '', text: 'Todas las empresas'},\n                          ...companies.map((company: any) => ({\n                          value: company._id,\n                          text: company.name\n                        }))]}\n                        onClick={this.filterCompanies}\n                      />\n                    </div>\n                    <div className=\"col-md-12\">\n                      <div id=\"participant-per-date\" style={{height: '450px', maxWidth: '100%'}}/>\n                    </div>\n                  </div>\n                </div>\n                {\n                  loading &&\n                    <div className=\"overlay\">\n                      <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                    </div>\n                }\n              </div>\n            </div>\n            <div className=\"col-md-12\" style={{display: 'none'}}>\n              <div className=\"box\">\n                <div className=\"box-header with-border\"><h3 className=\"box-title\">Histograma cumplimiento de revisiones</h3>\n                  <div className=\"box-tools pull-right\">\n                  </div>\n                </div>\n                <div className=\"box-body\">\n                  <div id=\"participant-range\" style={{height: '400px', maxWidth: '100%'}}/>\n                </div>\n                {\n                  loading &&\n                    <div className=\"overlay\">\n                      <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                    </div>\n                }\n              </div>\n            </div>\n            <div className=\"col-md-8\" style={{display: 'none'}}>\n              <div className=\"box\">\n                <div className=\"box-header with-border\"><h3 className=\"box-title\">Vehiculos por sucursal</h3>\n                  <div className=\"box-tools pull-right\">\n                  </div>\n                </div>\n                <div className=\"box-body\">\n                  <div id=\"cars-by-venue\" style={{height: '500px', maxWidth: '100%'}}/>\n                </div>\n                {\n                  loading &&\n                    <div className=\"overlay\">\n                      <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                    </div>\n                }\n              </div>\n            </div>\n          </Row>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private filterCompanies(value: any) {\n    this.props.getParticipantsPerDateAction(value);\n    this.setState({\n      selectedCompanies: [value]\n    });\n  }\n\n  private updateParticipantsChart() {\n    const {\n      participantsReceivedPerDate,participantsSentPerDate, carsPerDate,\n      planningPerDate, planningProcessPerDate\n    } = this.props.dashboard;\n    const categories: any[] = [];\n    const totalsReceived: any[] = [];\n    const totalsSent: any[] = [];\n    const totalsCars: any[] = [];\n    const totalsPlanning: any[] = [];\n    const totalsplanningProcess: any[] = [];\n\n    if (participantsReceivedPerDate.length) {\n      participantsReceivedPerDate.forEach((day) => {\n        categories.push(day._id);\n        totalsReceived.push(day.total);\n      });\n    }\n    if (participantsSentPerDate.length) {\n      participantsSentPerDate.forEach((day) => {\n        totalsSent.push(day.total);\n      });\n    }\n    if (carsPerDate.length) {\n      carsPerDate.forEach((day) => {\n        totalsCars.push(day.total);\n      });\n    }\n    if (planningPerDate.length) {\n      planningPerDate.forEach((day) => {\n        totalsPlanning.push(day.total);\n      });\n    }\n    if (planningProcessPerDate.length) {\n      planningProcessPerDate.forEach((day) => {\n        totalsplanningProcess.push(day.total);\n      });\n    }\n    const dataLabels = ['Recepciones', 'Envíos'];\n    const series = [{\n      data: totalsReceived,\n      name: 'Recepciones',\n      type: 'line',\n      color: '#337AB7',\n      smooth: true\n    }, {\n      data: totalsSent,\n      name: 'Envíos',\n      type: 'line',\n      color: '#2DB06B',\n      smooth: true\n    }, {\n      data: totalsCars,\n      name: 'Cargados',\n      type: 'line',\n        color: '#678099',\n        smooth: true\n      }];\n\n    if (hasPermission(window.user, 'viewPlanning')) {\n      dataLabels.push('Planificados', 'Linea de control');\n      series.push({\n        data: totalsPlanning,\n        name: 'Planificados',\n        type: 'line',\n        color: '#00b5fd',\n        smooth: true\n      });\n      series.push({\n        data: totalsplanningProcess,\n        name: 'Linea de control',\n        type: 'line',\n        color: '#7c344c',\n        smooth: true\n      });\n    }\n    dataLabels.push('Cargados');\n    // const option: echarts.EChartOption = {\n    const option: any = {\n      // title: {\n      //   text: 'Revisiones y cargas realizadas por día',\n      //   x: 'center',\n      //   textStyle: {\n      //     align: 'center'\n      //   }\n      // },\n      tooltip: {\n        trigger: 'axis'\n      },\n      legend: {\n        x: 'center',\n        bottom: 50,\n        // y: 'bottom',\n        data: dataLabels\n      },\n      xAxis: {\n        type: 'category',\n        boundaryGap: false,\n        data: categories,\n        axisLine: {\n          lineStyle: {\n            color: 'rgba(0, 0, 0, 0.5)'\n          }\n        },\n        splitLine: {\n          show: false,\n          lineStyle: {\n            type: 'dashed',\n            color: 'rgba(150, 150, 150, 0.5)'\n          }\n        },\n        axisLabel: {\n          rotate: 60\n          // fontSize: 10\n        }\n      },\n      yAxis: {\n        minInterval: 1,\n        type: 'value',\n        axisLine: {\n          lineStyle: {\n            color: 'rgba(0, 0, 0, 0.5)'\n          }\n        },\n        splitLine: {\n          show: true,\n          lineStyle: {\n            type: 'dashed',\n            color: 'rgba(150, 150, 150, 0.5)'\n          }\n        }\n      },\n      grid: {\n        top: 30,\n        bottom: 80,\n        // left\n        x: 20,\n        // right\n        x2: 20,\n        containLabel: true\n        // borderColor: '#FF0000'\n      },\n      dataZoom: {\n        show: true,\n        realtime: true,\n        start: 0,\n        end: 100\n      },\n      series\n    };\n    this.participantsPerDayChart.setOption(option);\n  }\n\n  private updateChartParticipantRange() {\n    const {participantPerRange} = this.props.dashboard;\n    const legends: any[] = [];\n    const proyectionInterval = 5;\n    const totals: any[] = [];\n    for (let i = 0; i < 100; i += proyectionInterval) {\n      const max = i + proyectionInterval;\n      const key = `${i}-${max}`;\n      legends.push(key);\n      const value = participantPerRange.find((range) => (range._id === key));\n      if (value) {\n        totals.push(value.count);\n      } else {\n        totals.push(0);\n      }\n      // proyection.push({$cond: [{$and: [{$gte: ['$qualification', i]}, {$lte: ['$qualification', max]}]}, `${i}-${max}`, '']});\n    }\n    // const option: echarts.EChartOption | any = {\n    const option: any = {\n      tooltip: {\n        trigger: 'axis'\n      },\n      xAxis: {\n        type: 'category',\n        // boundaryGap: false,\n        data: legends,\n        axisLine: {\n          lineStyle: {\n            color: 'rgba(0, 0, 0, 0.5)'\n          }\n        },\n        splitLine: {\n          show: false,\n          lineStyle: {\n            type: 'dashed',\n            color: 'rgba(150, 150, 150, 0.5)'\n          }\n        }\n      },\n      legend: {\n        x: 'center',\n        y: 'bottom',\n        data: ['Revisiones']\n      },\n      grid: {\n        top: 30,\n        // left\n        x: 20,\n        // right\n        x2: 20,\n        containLabel: true\n        // borderColor: '#FF0000'\n      },\n      yAxis: {\n        minInterval: 1,\n        type: 'value',\n        axisLine: {\n          lineStyle: {\n            color: 'rgba(0, 0, 0, 0.5)'\n          }\n        },\n        splitLine: {\n          show: true,\n          lineStyle: {\n            type: 'dashed',\n            color: 'rgba(150, 150, 150, 0.5)'\n          }\n        }\n      },\n      series: [{\n        data: totals,\n        type: 'line',\n        name: 'Revisiones',\n        color: '#e54e76',\n        areaStyle: {},\n        smooth: true\n      }]\n    };\n    this.participantsRangeChart.setOption(option);\n  }\n\n  private updateCarsChart() {\n    const {carsByVenue} = this.props.dashboard;\n    const legends = [];\n    const series = [];\n    for (const car in carsByVenue) {\n      const currentCar = carsByVenue[car];\n      if (car !== 'inTransit') {\n        legends.push(car);\n        series.push({\n          name: car,\n          value: currentCar.cars.length\n          // itemStyle: {\n          //   col  or: this.chartsColors[0]\n          // }\n        });\n      } else {\n        legends.push('En tránsito');\n        series.push({\n          name: 'En tránsito',\n          value: currentCar.cars.length\n          // itemStyle: {\n          //   color: this.chartsColors[0]\n          // }\n        });\n      }\n    }\n    const option: echarts.EChartOption = {\n      tooltip: {\n        trigger: 'item',\n        formatter: '{a} <br/>{b} : {c} ({d}%)'\n      },\n      legend: {\n        // x: 'center',\n        // type: 'scroll',\n        // orient: 'vertical',\n        // right: 10,\n        // top: 20,\n        // bottom: 20,\n        data: legends,\n        bottom: 40,\n        selected: {\n          ['En tránsito']: Object.keys(carsByVenue).length === 1\n        }\n      },\n      series: [\n        {\n          name: 'Sucursales',\n          type: 'pie',\n          radius: '70%',\n          center: ['50%', '43%'],\n          // label: {\n          //   normal: {\n          //     position: 'inner'\n          //   }\n          // },\n          data: series,\n          itemStyle: {\n            emphasis: {\n              shadowBlur: 10,\n              shadowOffsetX: 0,\n              shadowColor: 'rgba(0, 0, 0, 0.5)'\n            }\n          }\n        }\n      ]\n    };\n    this.carsByVenueChart.setOption(option);\n\n  }\n\n  private resizeCharts() {\n    if (this.participantsPerDayChart) {\n      this.participantsPerDayChart.resize();\n      setTimeout(() => {\n        this.participantsPerDayChart.resize();\n      }, 400);\n    }\n    if (this.carsByVenueChart) {\n      this.carsByVenueChart.resize();\n      setTimeout(() => {\n        this.carsByVenueChart.resize();\n      }, 400);\n    }\n    if (this.participantsRangeChart) {\n      this.participantsRangeChart.resize();\n      setTimeout(() => {\n        this.participantsRangeChart.resize();\n      }, 400);\n    }\n  }\n}\n\nconst mapStateToProps = (state: { dashboard: IDashboardState }) => {\n  return {\n    dashboard: state.dashboard\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getParticipantsPerDateAction: (companies?:string) => dispatch(getParticipantsPerDateAction(companies))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DashboardGeneralView);\n","// import * as PropTypes from 'prop-types';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport * as moment from 'moment';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport { DashboardReduxAction } from '../../actions/dashboard.actions';\nimport { getDashboardTiming, IDashboardTimingState } from '../../actions/dashboardTiming.actions';\nimport AppContainer from '../../container/AppContainer';\nimport Row from '../Utils/Row';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport DateRangeInput from '../Utils/DateRangeInput';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<DashboardReduxAction>;\n  dashboard: IDashboardTimingState;\n\n  getDashboardTiming(from: string, to: string): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  showDrilldown: boolean,\n  selectedDate: string | null,\n  from: Date,\n  to: Date,\n}\n\nclass DashboardTimingView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n  timingPerMonthChart: echarts.ECharts;\n  timingPerVenueChart: echarts.ECharts;\n\n  state = {\n    showDrilldown: false,\n    error: null,\n    selectedDate: null,\n    from: moment().subtract(2, 'months').startOf('month').toDate(),\n    to: moment().endOf('month').toDate()\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Reportería de tiempos de traslado';\n    this.resizeCharts = this.resizeCharts.bind(this);\n    this.updateTimingPerMonthChart = this.updateTimingPerMonthChart.bind(this);\n    this.showVenueChart = this.showVenueChart.bind(this);\n    this.showDateChart = this.showDateChart.bind(this);\n    this.onDateRangeChange = this.onDateRangeChange.bind(this);\n  }\n\n  public componentWillMount(): void {\n    // get data\n    let from = moment().subtract(2, 'months').startOf('month');\n    let to = moment().endOf('month');\n    this.props.getDashboardTiming(from.format('YYYY-MM-DD'), to.format('YYYY-MM-DD'));\n    // add listeners\n    window.addEventListener('resize', this.resizeCharts, false);\n  }\n\n  getDateRangeOptions(): daterangepicker.Options {\n    return {\n      maxDate: moment(),\n      locale: {\n        format: 'MM/YYYY',\n        customRangeLabel: 'Período personalizado',\n        applyLabel: 'Aplicar',\n        cancelLabel: 'Cancelar'\n      },\n      ranges: {\n        'Este mes': [moment().startOf('month'), moment().endOf('month')],\n        'Últimos 3 meses': [moment().subtract(2, 'months').startOf('month'), moment().endOf('month')],\n        'Últimos 6 meses': [moment().subtract(5, 'months').startOf('month'), moment().endOf('month')],\n        'Último año': [moment().subtract(11, 'months').startOf('month'), moment().endOf('month')]\n      }\n    };\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    const $timingPerMonth = document.getElementById('damages-per-month') as HTMLDivElement;\n    this.timingPerMonthChart = echarts.init($timingPerMonth);\n    this.timingPerMonthChart.on('click', this.showVenueChart);\n  }\n\n  onDateRangeChange(from: Date, to: Date) {\n    this.props.getDashboardTiming(moment(from).format('YYYY-MM-DD'), moment(to).format('YYYY-MM-DD'));\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: IPropsType, prevState: IStateType): void {\n    const { loading, loadingPerVenue, perVenue } = this.props.dashboard;\n    const { showDrilldown } = this.state;\n    if (!loading) {\n      showDrilldown ? this.updateTimingPerVenueChart() :\n        this.updateTimingPerMonthChart();\n    }\n  }\n\n  public componentWillUnmount() {\n    // remove listeners\n    window.removeEventListener('resize', this.resizeCharts, false);\n\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading } = this.props.dashboard;\n    const { selectedDate, from, to } = this.state;\n    let selectedMonth = selectedDate ?\n      this.capitalizeFirstLetter(moment(selectedDate, 'MM-YYYY').format('MMMM YYYY')) : '';\n\n    return (\n      <AppContainer title='' cMenu='1' cSubMenu='1.5'>\n        <section className='content'>\n          <Row>\n            <div className='col-md-12'>\n              <div className='box'>\n                <div className='box-header with-border'><h3\n                  className='box-title'>{selectedDate ? `Traslados nacionales: ${selectedMonth}` : 'Traslados nacionales por mes'}</h3>\n                  <div className='box-tools pull-right'>\n                  </div>\n                </div>\n\n                <div className='row' style={{ display: selectedDate ? 'none' : 'inherit' }}>\n                  <div className='col-md-offset-8 col-md-4'>\n                    <DateRangeInput\n                      options={this.getDateRangeOptions()}\n                      onChange={this.onDateRangeChange}\n                      startDate={from}\n                      endDate={to}\n                    />\n                  </div>\n                </div>\n                <div className='box-body'>\n                  <p\n                    className='text-muted text-center'\n                    style={{ padding: '10px 0 0 0', margin: '0' }}\n                  >{selectedDate ? '' : 'Haz click en el gráfico para ver detalles de no cumplimiento'}.</p>\n                  <div id='damages-per-month' style={{ minHeight: '350px', maxWidth: '100%' }} />\n                </div>\n                {\n                  loading &&\n                  <div className='overlay'>\n                    <i className='fa fa-spinner fa-spin text-purple' />\n                  </div>\n                }\n              </div>\n            </div>\n          </Row>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private capitalizeFirstLetter(str: string) {\n    return str.charAt(0).toUpperCase() + str.slice(1);\n  }\n\n  private updateTimingPerMonthChart() {\n    const { data } = this.props.dashboard;\n    let months: string[] = [];\n    let overdue: any[] = [];\n    let ontime: any[] = [];\n    const createDataElement = (n: number) => n > 0 ? {\n      value: n,\n      label: n > 0 ? { show: true, position: 'insideRight' } : { show: false }\n    } : null;\n\n    Object.keys(data).map(k => {\n      months.push(this.capitalizeFirstLetter(moment(k, 'MM-YYYY').format('MMMM YYYY')));\n      ontime.push(data[k].filter((d: { atTime: boolean; }) => d.atTime).length);\n      overdue.push(data[k].filter((d: { atTime: boolean; }) => !d.atTime).length);\n    });\n\n    ontime = ontime.map(createDataElement);\n    overdue = overdue.map(createDataElement);\n\n    const option: echarts.EChartOption = {\n      color: ['#f1392c', '#00aa51'],\n      tooltip: {\n        trigger: 'axis',\n        axisPointer: {\n          type: 'shadow'\n        }\n      },\n      legend: {\n        data: ['No cumple', 'Cumple'],\n        // x: 'center',\n        bottom: 5\n      },\n      xAxis: {\n        type: 'value',\n        position: 'top'\n      },\n      yAxis: {\n        type: 'category',\n        data: months\n      },\n      grid: {\n        top: 30,\n        bottom: 100,\n        left: 10,\n        right: 10,\n        containLabel: true,\n        height: 290\n      },\n      series: [\n        {\n          name: 'No cumple',\n          type: 'bar',\n          stack: '1',\n          data: overdue,\n          barMinHeight: 15\n        },\n        {\n          name: 'Cumple',\n          type: 'bar',\n          stack: '1',\n          data: ontime,\n          barMinHeight: 15\n        }\n      ],\n      toolbox: []\n    };\n\n    this.timingPerMonthChart.setOption(option, true);\n  }\n\n  private updateTimingPerVenueChart() {\n    const { selectedDate } = this.state;\n    const { data } = this.props.dashboard;\n    let values = data[selectedDate!];\n    let routes: any = {};\n    let names: string[] = [];\n\n    const createDataElement = (n: number) => n > 0 ? {\n      value: n,\n      label: n > 0 ? { show: true, position: 'insideRight' } : { show: false }\n    } : null;\n\n    values.map((d: any) => {\n      let routeName = d.from + ' - ' + d.to;\n      if (routes[routeName] === undefined) {\n        routes[routeName] = { overdue: 0, ontime: 0, limitTime: d.daysLimit };\n        names.push(routeName);\n      }\n      d.atTime ? routes[routeName].ontime++ : routes[routeName].overdue++;\n    });\n\n    names.sort();\n    let ontime: any[] = [];\n    let overdue: any[] = [];\n\n    names.map((n: string) => {\n      let data = routes[n];\n      ontime.push({ ...createDataElement(data.ontime as number), limitTime: data.limitTime });\n      overdue.push({ ...createDataElement(data.overdue as number), limitTime: data.limitTime });\n    });\n\n    const option: echarts.EChartOption = {\n      color: ['#f1392c', '#00aa51'],\n      tooltip: {\n        trigger: 'axis',\n        formatter: function(params: any) {\n          let timeLimit = 0;\n          let output = '<b>' + params[0].name + '</b><br/>';\n\n          params.map((p: any) => {\n            output += p.marker + p.seriesName + ': ' + (p.value ? p.value : '-') + '<br/>'; // : every 2nth\n            if (timeLimit === 0)\n              timeLimit = p.data.limitTime;\n          });\n\n          output += `Tiempo límite de entrega: ${timeLimit} días`;\n          return output;\n        },\n        axisPointer: {\n          type: 'shadow'\n        }\n      },\n      legend: {\n        data: ['No cumple', 'Cumple'],\n        // x: 'center',\n        bottom: 5\n      },\n      xAxis: {\n        type: 'value',\n        position: 'top'\n      },\n      yAxis: {\n        type: 'category',\n        data: names\n      },\n      grid: {\n        top: 30,\n        bottom: 100,\n        left: 10,\n        right: 10,\n        containLabel: true,\n        height: 290\n      },\n      series: [\n        {\n          name: 'No cumple',\n          type: 'bar',\n          stack: '1',\n          data: overdue,\n          barMinHeight: 15,\n          barMinWidth: 25\n        },\n        {\n          name: 'Cumple',\n          type: 'bar',\n          stack: '1',\n          data: ontime,\n          barMinHeight: 15,\n          barMinWidth: 25\n        }\n      ],\n      toolbox: {\n        left: 20,\n        top: 0,\n        feature: {\n          myBackBtn: {\n            show: true,\n            icon: 'path://M16.6666667 9.16666667 6.525 9.16666667 11.1833333 4.50833333 10 3.33333333 3.33333333 10 10 16.6666667 11.175 15.4916667 6.525 10.8333333 16.6666667 10.8333333z',\n            title: ' ',\n            onclick: this.showDateChart\n          }\n        },\n        iconStyle: {\n          color: 'rgba(0, 0, 0, 0.8)',\n          fontWeight: 'bolder',\n          borderColor: 'rgba(0, 0, 0, 0)',\n          shadowColor: 'rgba(0, 0, 0, 0)',\n          emphasis: {\n            color: '#a94442',\n            borderColor: 'rgba(0, 0, 0, 0)',\n            shadowColor: 'rgba(0, 0, 0, 0)'\n          }\n        }\n      }\n    };\n\n    this.timingPerMonthChart.setOption(option, true);\n\n  }\n\n  private showVenueChart(param: any) {\n    const { data } = this.props.dashboard;\n    const month = moment(param.name.toLowerCase(), 'MMMM YYYY').format('MM-YYYY');\n    this.setState({\n      showDrilldown: true,\n      selectedDate: month\n    }, () => {\n      setTimeout(() => {\n        this.timingPerMonthChart.off('click');\n      }, 200);\n    });\n  }\n\n  private showDateChart() {\n    this.setState({\n      showDrilldown: false,\n      selectedDate: null\n    }, () => {\n      setTimeout(() => {\n        this.timingPerMonthChart.on('click', this.showVenueChart);\n      }, 500);\n      const $timingPerMonth = document.getElementById('damages-per-month') as HTMLDivElement;\n      this.timingPerMonthChart = echarts.init($timingPerMonth);\n    });\n  }\n\n  private resizeCharts() {\n    if (this.timingPerMonthChart) {\n      this.timingPerMonthChart.resize();\n      setTimeout(() => {\n        this.timingPerMonthChart.resize();\n      }, 400);\n    }\n\n    if (this.timingPerVenueChart) {\n      this.timingPerVenueChart.resize();\n      setTimeout(() => {\n        this.timingPerVenueChart.resize();\n      }, 400);\n    }\n  }\n}\n\nconst mapStateToProps = (state: { dashboardTiming: IDashboardTimingState }) => {\n  return {\n    dashboard: state.dashboardTiming\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getDashboardTiming: (from: string, to: string) => dispatch(getDashboardTiming(from, to))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DashboardTimingView);\n","import {AxiosError, default as Axios} from 'axios';\nimport {Dispatch} from 'redux';\nimport ApiService from '../utils/axios';\n\ninterface ITimingData {\n  months: string[];\n  overdue: number[];\n  ontime: number[];\n}\n\nexport interface IDashboardTimingState {\n  data: any;\n  venues: any[];\n  venuesDict: any;\n  loading: boolean;\n  loadingPerVenue: boolean;\n  perVenue: any;\n}\n\ninterface ILoadDashboardTiming {\n  type: '/DASHBOARD/TIMING/LOAD_DATA';\n  payload: {\n    venues: any[],\n    data: any\n  };\n}\n\nexport function loadDashboardTimingAction(venues: any[], data: any): ILoadDashboardTiming {\n  return {\n    type: '/DASHBOARD/TIMING/LOAD_DATA',\n    payload: {\n      venues,\n      data\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/DASHBOARD/TIMING/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/DASHBOARD/TIMING/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IIsLoadingPerVenue {\n  type: '/DASHBOARD/TIMING/IS_LOADING_PER_VENUE';\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport function isLoadingPerVenueAction(loading: boolean): IIsLoadingPerVenue {\n  return {\n    type: '/DASHBOARD/TIMING/IS_LOADING_PER_VENUE',\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function getDashboardTiming(from: string, to: string) {\n  return (dispatch: Dispatch<DashboardTimingReduxAction>) => {\n    const api: ApiService = new ApiService();\n    dispatch(isLoadingAction(true));\n    Axios.all([\n      api.getVenues({ page: 1, pageSize: 200 }),\n      api.getDashboardTiming(from, to)\n    ]).then(Axios.spread((venues, dashboard) => {\n      dispatch(loadDashboardTimingAction(venues.data.results, dashboard.data));\n    })).catch((err: AxiosError): void => {\n      api.errorHandler(err);\n    });\n  };\n}\n\n\nexport type DashboardTimingReduxAction = ILoadDashboardTiming | IIsLoading | IIsLoadingPerVenue;\n","import * as React from 'react';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport { DashboardReduxAction, getRevisionStats, IDashboardState } from '../../actions/dashboard.actions';\nimport AppContainer from '../../container/AppContainer';\nimport InfoCard, { CardColors } from './InfoCard';\nimport CircleChartCard from './CircleChartCard';\nimport FilterableVenueTable from './FilterableVenueTable';\nimport { connect } from 'react-redux';\nimport * as moment from 'moment';\nimport NumberFormat from 'react-number-format';\nimport { IWindow } from '../../interfaces/window';\nimport { IUser } from '../../../../../../src/app/interfaces/user.interface';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\n\ndeclare let window: IWindow;\n\ninterface IPropsType extends RouteComponentProps<{}> {\n  dispatch: Dispatch<DashboardReduxAction>;\n  dashboard: IDashboardState;\n  getRevisionStats(): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\n\nclass DashboardRevisionsView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n  readonly state: IStateType = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Dashboard Revisiones';\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n    this.props.getRevisionStats();\n  }\n\n  private isSALFARAC() {\n    const user: IUser = window.user;\n    return user.company._id === '5ef1271dd569c10013d17e8b';\n  }\n\n  public render() {\n    const { revisionStats, loading } = this.props.dashboard;\n    // tslint:disable-next-line: one-variable-per-declaration\n    let today: number = 0,\n      yesterday: number = 0,\n      dayVariation: number = 0,\n      currentMonthMean: number = 0,\n      lastMonthMean: number = 0,\n      monthMeanVariation: number = 0,\n      totalRevisions: number = 0,\n      participantAcceptance: number = 0,\n      shipAcceptance: number = 0,\n      receiveAcceptance: number = 0,\n      venueActivity: number = 0;\n\n    if (revisionStats) {\n      today = revisionStats.revisions.today;\n      yesterday = revisionStats.revisions.yesterday;\n      dayVariation = yesterday ? 100 * (today - yesterday) / yesterday : Infinity;\n\n      currentMonthMean = revisionStats.revisions.currentMonthTotal / moment().date();\n      lastMonthMean = revisionStats.revisions.lastMonthTotal / moment().subtract(1, 'month').daysInMonth();\n      monthMeanVariation = lastMonthMean ? 100 * (currentMonthMean - lastMonthMean) / (lastMonthMean) : Infinity;\n\n      totalRevisions = revisionStats.revisions.totalRevisions;\n\n      if (revisionStats.revisions.sentStats && revisionStats.revisions.receivedStats) {\n        const acceptedRevisions = revisionStats.revisions.sentStats.accepted + revisionStats.revisions.receivedStats.accepted;\n        const rejectedRevisions = revisionStats.revisions.sentStats.rejected + revisionStats.revisions.receivedStats.rejected;\n\n        participantAcceptance = 100 * acceptedRevisions / (acceptedRevisions + rejectedRevisions);\n\n        const totalSent = (revisionStats.revisions.sentStats.accepted + revisionStats.revisions.sentStats.rejected);\n        const totalReceive = (revisionStats.revisions.receivedStats.accepted + revisionStats.revisions.receivedStats.rejected);\n        shipAcceptance = totalSent ? 100 * revisionStats.revisions.sentStats.accepted / totalSent : Infinity;\n        receiveAcceptance = totalReceive ? 100 * revisionStats.revisions.receivedStats.accepted / totalReceive : Infinity;\n      }\n\n      const totalVenues = (revisionStats.venues.activeVenues + revisionStats.venues.inactiveVenues);\n      venueActivity = 100 * revisionStats.venues.activeVenues / totalVenues;\n\n    }\n\n    return (\n      <AppContainer title=\"\" cMenu=\"1\" cSubMenu=\"1.3\">\n        <section className=\"content\">\n          <div className=\"row\" style={{ marginTop: '10px' }}>\n            <InfoCard\n              icon=\"fa-search\"\n              title=\"REVISIONES HOY\" value={today}\n              className=\"col-md-6 col-lg-3\"\n              showLoading={loading}\n            />\n            <InfoCard\n              className=\"col-md-6 col-lg-3\"\n              icon={!dayVariation || dayVariation === Infinity || dayVariation === 0 ? 'fa-search' :\n                dayVariation > 0 ? 'fa-caret-up' : 'fa-caret-down'\n              }\n              iconBackgroundColor={!dayVariation || dayVariation === Infinity || dayVariation === 0 ? null :\n                dayVariation > 0 ? CardColors.GREEN : CardColors.RED\n              }\n              title=\"REVISIONES ÚLTIMO DÍA\"\n              value={yesterday}\n              showLoading={loading}>\n              {!dayVariation || dayVariation === Infinity || dayVariation === 0 ? null :\n                <span className={`${!dayVariation || dayVariation === Infinity || dayVariation === 0 ? 'fa-search' :\n                  dayVariation > 0 ? 'green' : 'red'\n                  } font-normal font-14`} style={{ marginLeft: '5px' }}>\n                  ({dayVariation.toFixed(0)}% vs día anterior)\n                    </span>\n              }\n            </InfoCard>\n            <InfoCard\n              className=\"col-md-6 col-lg-3\"\n              icon={!monthMeanVariation || monthMeanVariation === Infinity || monthMeanVariation === 0 ? 'fa-search' :\n                monthMeanVariation > 0 ? 'fa-caret-up' : 'fa-caret-down'\n              }\n              iconBackgroundColor={!monthMeanVariation || monthMeanVariation === Infinity || monthMeanVariation === 0 ? null :\n                monthMeanVariation > 0 ? CardColors.GREEN : CardColors.RED\n              }\n              title=\"PROMEDIO DIARIO MES\"\n              value={currentMonthMean}\n              showLoading={loading}>\n              {!monthMeanVariation || monthMeanVariation === Infinity || monthMeanVariation === 0 ? null :\n                <span className={`${!monthMeanVariation || monthMeanVariation === Infinity || monthMeanVariation === 0 ? 'fa-search' :\n                  monthMeanVariation > 0 ? 'green' : 'red'\n                  } font-normal font-14`} style={{ marginLeft: '5px' }}>\n                  ({monthMeanVariation.toFixed(0)}% vs mes anterior)\n                    </span>\n              }\n            </InfoCard>\n            <InfoCard\n              className=\"col-md-6 col-lg-3\"\n              bordered\n              icon=\"fa-search\"\n              title=\"TOTAL REVISIONES\"\n              showLoading={loading}\n              value={totalRevisions}\n            />\n          </div>\n          <div className=\"box\">\n            <div className=\"box-header with-border bg-\">\n              <h3 className=\"box-title\">Reporte Revisiones</h3>\n            </div>\n            <div className=\"box-body\">\n              <div className=\"row\">\n                <CircleChartCard className=\"col-md-6 col-lg-6 lg-tm-10\"\n                  title={this.isSALFARAC() ?\n                    '% DE ENTREGAS/RECEPCIONES POR USUARIO HABITUAL' :\n                    '% ACEPTA REVISIÓN (pórtico)'}\n                  value={participantAcceptance}\n                  bordered\n                  showLoading={loading}>\n                  <div>\n                    {!receiveAcceptance || receiveAcceptance === Infinity || receiveAcceptance === 0 ? null :\n                      <span className=\"info-box-text xs-center-text text-wrap\">\n                        {this.isSALFARAC() ?\n                          'ENTREGA USUARIO HABITUAL ' :\n                          'ACEPTA RECEPCIÓN '}\n                        <NumberFormat\n                          value={receiveAcceptance}\n                          displayType={'text'}\n                          thousandSeparator={'.'}\n                          decimalScale={0}\n                          decimalSeparator={','}\n                          suffix=\"%\" />\n                      </span>\n                    }\n                    {!shipAcceptance || shipAcceptance === Infinity || shipAcceptance === 0 ? null :\n                      <span className=\"info-box-text xs-center-text text-wrap\">\n                        {\n                          this.isSALFARAC() ?\n                          'RECIBE USUARIO HABITUAL ' :\n                          'ACEPTA DESPACHO '\n                        }\n                        <NumberFormat\n                          value={shipAcceptance}\n                          displayType={'text'}\n                          thousandSeparator={'.'}\n                          decimalScale={0}\n                          decimalSeparator={','}\n                          suffix=\"%\" />\n                      </span>\n                    }\n                  </div>\n                </CircleChartCard>\n                <CircleChartCard className=\"col-md-6 lg-tm-10\" title=\"SUCURSALES ACTIVAS MES\" value={venueActivity} bordered showLoading={loading} />\n              </div>\n              <div className=\"row\">\n                <FilterableVenueTable className=\"col-md-12 col-lg-12 lg-tm-12\" bordered />\n              </div>\n            </div>\n            {\n              loading &&\n              <div className=\"overlay\">\n                <i className=\"fa fa-spinner fa-spin text-purple\" />\n              </div>\n            }\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n}\n\nconst mapStateToProps = (state: { dashboard: IDashboardState }) => {\n  return {\n    dashboard: state.dashboard\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getRevisionStats: () => dispatch(getRevisionStats())\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DashboardRevisionsView);\n","import * as React from 'react';\nimport { HTMLProps } from 'react';\nimport NumberFormat from 'react-number-format';\n\nexport enum CardColors {\n  AQUA = 'bg-aqua',\n  GREEN = 'bg-green',\n  YELLOW = 'bg-yellow',\n  RED = 'bg-red',\n  GRAY = 'bg-gray-dark'\n}\n\ninterface IPropsType extends HTMLProps<HTMLDivElement> {\n  title: string;\n  value: number;\n  percentageValue?: number;\n  cardColor?: CardColors | null;\n  iconBackgroundColor?: CardColors | null;\n  icon: string;\n  onClickMethod?: () => void;\n  showLoading?: boolean;\n  showProgressBar?: boolean;\n  bordered?: boolean;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass InfoCard extends React.Component<IPropsType, IStateType> {\n\n  readonly state: IStateType = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { title, value, cardColor, icon, onClickMethod, percentageValue, showLoading, showProgressBar, iconBackgroundColor, bordered } = this.props;\n    return (\n      <div className={`${this.props.className}  ${onClickMethod ? 'pointer' : ''}`} onClick={() => { if (onClickMethod) onClickMethod(); }}>\n        <div className={`info-box ${cardColor ? cardColor.toString() : ''} ${bordered ? 'bordered' : ''}`}>\n          <span className={`info-box-icon ${iconBackgroundColor}`} >\n            <i className={`fa ${icon}`} />\n          </span>\n          <div className=\"info-box-content\">\n            <span className=\"info-box-text\">{title}</span>\n            <span className=\"info-box-number count\">\n              {!showLoading ?\n                <NumberFormat\n                  value={value} displayType={'text'}\n                  thousandSeparator={'.'}\n                  decimalScale={0}\n                  decimalSeparator={','}\n                /> :\n                <i className=\"fa fa-spinner fa-spin\" />}\n              {this.props.children}\n            </span>\n\n            {!showLoading && showProgressBar ?\n              <>\n                <div className=\"progress\">\n                  <div className=\"progress-bar\" style={{\n                    width: `${percentageValue}%`,\n                    transition: 'width .6s ease'\n                  }} />\n                </div>\n                <span className=\"progress-description\">\n                  {`${percentageValue?.toFixed(1)}% ${title.toLowerCase()}.`}\n                </span>\n              </>\n              : null}\n          </div>\n        </div>\n      </div>\n    );\n  }\n}\n\nexport default InfoCard;\n\n\n\n","import * as React from 'react';\nimport {HTMLProps} from 'react';\nimport NumberFormat from \"react-number-format\";\n\ninterface IPropsType extends HTMLProps<HTMLDivElement>{\n  value: number;\n  title: string;\n  onClickMethod?: () => void;\n  showLoading?: boolean;\n  bordered? :boolean;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass CircleChartCard extends React.Component<IPropsType, IStateType>{\n  readonly state : IStateType = {\n    error: null\n  };\n\n  circleChart: echarts.ECharts;\n  private chartRef: React.RefObject<HTMLDivElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.chartRef = React.createRef();\n    this.drawChart = this.drawChart.bind(this);\n    this.resizeCharts = this.resizeCharts.bind(this);\n  }\n\n\n  componentDidUpdate(prevProps: IPropsType, prevState: IStateType): void {\n    if (!this.props.showLoading) {\n      this.circleChart = echarts.init(this.chartRef.current!);\n      this.drawChart();\n    }\n  }\n\n\n  public componentWillMount() {\n    window.addEventListener('resize', this.resizeCharts, false);\n  }\n\n  public componentWillUnmount() {\n    window.removeEventListener('resize', this.resizeCharts, false);\n  }\n\n  private drawChart(){\n    const {value, showLoading} = this.props;\n    if (showLoading){\n      return\n    }\n    const option: echarts.EChartOption = {\n      color: ['#00aa51', '#f1392c'],\n      grid: {\n        width: \"100%\",\n        height: \"100%\",\n        // top: 30,\n        // bottom: 100,\n        // left\n        left: 0,\n        right: 0,\n        containLabel: true\n      },\n      series: [\n        {\n          type: 'pie',\n          radius: ['40%', '70%'],\n          avoidLabelOverlap: true,\n          label: {\n            show: false\n          },\n          data: [\n            value,\n            100-value\n          ]\n        }\n      ]\n    };\n\n    this.circleChart.setOption(option, true);\n  }\n\n  private resizeCharts() {\n    if (this.circleChart) {\n      this.circleChart.resize();\n      setTimeout(() => {\n        this.circleChart.resize();\n      }, 400);\n    }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {title, value, onClickMethod, bordered} = this.props;\n    return (\n      <div className={`${this.props.className}  ${onClickMethod ? 'pointer' : ''}`} onClick={() => {if (onClickMethod) onClickMethod();}}>\n        <div className={`${bordered ? 'bordered' : ''}`}>\n          <div className=\"row justify-content-center\">\n            <div className=\"col-sm-4 col-xs-12\">\n              <div ref={this.chartRef} style={{minHeight: '160px', maxWidth: '100%'}}/>\n            </div>\n            <div className=\"col-sm-8 col-xs-12\" style={{padding: '15px'}}>\n              <span className=\"info-box-text xs-center-text text-wrap\">{title}</span>\n              <span className=\"info-box-number count font-32 xs-center-text\">\n                <NumberFormat\n                  value={value}\n                  displayType={'text'}\n                  thousandSeparator={'.'}\n                  decimalScale={0}\n                  decimalSeparator={','}\n                  suffix=\"%\"/>\n              </span>\n              {this.props.children}\n            </div>\n          </div>\n        </div>\n      </div>);\n  }\n}\n\nexport default CircleChartCard;\n\n\n\n","import * as React from 'react';\nimport {RouteComponentProps} from \"react-router\";\nimport {Dispatch} from \"redux\";\nimport {connect} from 'react-redux';\nimport {\n  DashboardReduxAction, getVenuesStats, IDashboardState,\n} from \"../../actions/dashboard.actions\";\nimport * as moment from \"moment\";\n\ninterface IPropsType {\n  className?: string;\n  dispatch?: Dispatch<DashboardReduxAction>;\n  dashboard?: IDashboardState;\n  getVenuesStats(from: number, to: number): void;\n  bordered? : boolean;\n}\n\nexport enum TimePeriods {\n  MONTH = \"MES\",\n  WEEK = \"SEMANA\",\n  YEAR = \"AÑO\",\n  DAY = \"DÍA\",\n}\n\ninterface IStateType {\n  error: Error | null;\n  from: number;\n  to: number;\n  timeControl: string;\n  minValue: number | null;\n}\n\nclass FilterableVenueTable extends React.Component<IPropsType, IStateType> {\n  readonly state: IStateType = {\n    error: null,\n    from: moment().startOf(\"month\").unix(),\n    to: moment().endOf(\"month\").unix(),\n    timeControl: TimePeriods.WEEK,\n    minValue: null\n  };\n\n  componentDidMount() {\n    const {from, to} = this.state;\n    this.props.getVenuesStats(from, to);\n  }\n\n  onValueChange = (e: any) => {\n    this.setState({\n      minValue: e.currentTarget.value\n    });\n  }\n\n  onTimePeriodChange = (e: React.ChangeEvent<HTMLSelectElement>) => {\n    let from : number, to : number;\n    let value : string = e.target.value;\n\n    switch (value) {\n      case TimePeriods.MONTH:\n        from = moment().startOf(\"month\").unix();\n        to = moment().endOf(\"month\").unix();\n        break;\n      case TimePeriods.WEEK:\n        from = moment().startOf(\"week\").unix();\n        to = moment().endOf(\"week\").unix();\n        break;\n      case TimePeriods.DAY:\n        from = moment().startOf(\"day\").unix();\n        to = moment().endOf(\"day\").unix();\n        break;\n      default:\n        from = moment().startOf(\"year\").unix();\n        to = moment().endOf(\"year\").unix();\n        break;\n    }\n\n    this.setState({from, to, timeControl: value}, () => {\n      this.props.getVenuesStats(from, to)\n    });\n  }\n\n  public render() {\n    const minValue = this.state.minValue ?? null;\n    let venuesInfo = this.props.dashboard ? this.props.dashboard.venueStats ?? [] : [];\n    if (minValue){\n      venuesInfo = venuesInfo.filter(v => (v.total ?? 0) < minValue);\n    }\n    return (\n      <div className={`${this.props.className}`} >\n        <div className={`col ${this.props.bordered ? 'bordered' : ''}`} style={{padding: \"5px\"}} >\n          <div className='row' >\n            <div className=\"col-xs-6\">\n              <span className=\"font-14\">\n                SUCURSALES BAJO:\n              </span>\n              <input\n                className=\"font-12\"\n                style={{width: \"60px\", marginLeft: \"5px\"}}\n                name=\"minValue\"\n                min={1}\n                value={this.state.minValue ?? \"\"}\n                onChange={this.onValueChange}\n                type=\"number\"\n              />\n            </div>\n            <div className=\"col-xs-6\">\n              <div>\n                <span className=\"font-14\" >REVISIONES ESTE:</span>\n                <select\n                  className=\"font-12\"\n                  style={{width:\"90px\", marginLeft: \"5px\"}}\n                  name=\"timeControl\"\n                  value={this.state.timeControl}\n                  onChange={this.onTimePeriodChange}>\n                  {Object.keys(TimePeriods).map( (p : string) =>\n                    <option key={p} value={(TimePeriods as any)[p].toString()}>{(TimePeriods as any)[p].toString()}</option>\n                  )}\n                </select>\n              </div>\n            </div>\n          </div>\n          <div className=\"row\" style={{overflowY: \"scroll\", minHeight: \"122px\", height: \"50vh\",  margin: \"0px\"}}>\n            <table className=\"table table-striped\">\n              <thead>\n              <tr>\n                <th className=\"\">Sucursal</th>\n                <th style={{width: \"100px\"}}># Revisiones</th>\n              </tr>\n              </thead>\n              <tbody>\n              {venuesInfo\n                .sort((a,b) => b.total-a.total)\n                .map(venueStats =>\n                <tr key={venueStats._id}>\n                  <td>{venueStats.name}</td>\n                  <td>{venueStats.total ?? 0}</td>\n                </tr>\n              )}\n              </tbody>\n            </table>\n          </div>\n       </div>\n      </div>\n    )\n  }\n}\n\nconst mapStateToProps = (state: { dashboard: IDashboardState }) => {\n  return {\n    dashboard: state.dashboard\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getVenuesStats: (from: number, to: number) => dispatch(getVenuesStats(from, to))\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType | any>(mapStateToProps, mapDispatchToProps)(FilterableVenueTable);\n","// import * as PropTypes from 'prop-types';\nimport * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport {ErrorInfo} from 'react';\nimport * as React from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport { io } from \"socket.io-client\";\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\nimport {IParticipant} from '../../../../../../src/form/interfaces/participant.interface';\nimport {\n  DashboardReduxAction,\n  getCarAction,\n  getParticipant,\n  IDashboardState,\n  loadParticipantInCarAction\n} from '../../actions/dashboard.actions';\nimport AppContainer from '../../container/AppContainer';\nimport {IWindow} from '../../interfaces/window';\nimport ModalView from '../Modal/ModalView';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport ShowIf from '../Utils/ShowIf';\nimport { parseReplicableURL } from '../../utils/common';\n\ndeclare let window: IWindow;\n\ninterface IPropsType extends RouteComponentProps<{ id: string }> {\n  dispatch: Dispatch<DashboardReduxAction>;\n  dashboard: IDashboardState;\n  getCarAction(id: string): void;\n  getParticipant(id: string): void;\n\n  loadParticipantInCarAction(participant: IParticipant): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  highlight: string[];\n  carLoading: string;\n}\n\nclass DashboardVinDetail extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  // static propTypes = {\n  //   dashboard: PropTypes.object.isRequired,\n  //   dispatch: PropTypes.func.isRequired,\n  //   getCarAction: PropTypes.func.isRequired,\n  //   getParticipant: PropTypes.func.isRequired\n  // };\n\n  constructor(props : IPropsType) {\n    super(props);\n    this.title = 'Detalle VIN';\n    this.openBlank = this.openBlank.bind(this);\n  }\n\n  readonly state = {\n    error: null,\n    highlight: [],\n    carLoading: ''\n  };\n  protected printIframe: any;\n\n  private socket: Socket;\n\n  componentWillMount() {\n    // set the title of the page\n    const { id } = this.props.match.params;\n    this.props.getCarAction(id);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: (window.user as any).token\n      }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `dashboard-vin-detail-${window.user.team._id}-${id}` });\n    });\n    this.socket.on('ADD_PARTICIPANT', (data: any): void => {\n      this.setState({\n        highlight: [data._id, ...this.state.highlight]\n      });\n      this.props.loadParticipantInCarAction(data);\n    });\n\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public printPdf(url: string, carLoading: string) {\n    this.setState({carLoading});\n    let iframe: any = this.printIframe;\n    const timezone = moment.tz.guess();\n    if (!this.printIframe) {\n      iframe = this.printIframe = document.createElement('iframe');\n      document.body.appendChild(iframe);\n      iframe.style.display = 'none';\n      iframe.onload = () => {\n        setTimeout(() => {\n          iframe.focus();\n          iframe.contentWindow.print();\n          this.setState({carLoading: ''});\n          // document.body.removeChild(iframe)\n        }, 1);\n      };\n    }\n    iframe.src = `${url}?timezone=${timezone}`;\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentWillUnmount() {\n    // cancel request if component is inmounted\n    if (this.props.dashboard.source) {\n      this.props.dashboard.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {loading, car, loadingParticipant, requests} = this.props.dashboard;\n    const {highlight, carLoading} = this.state;\n    const {getParticipant} = this.props;\n    return (\n      <AppContainer title=\"\" cMenu=\"1\" cSubMenu=\"1.2\" cAction={`Detalle`}>\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\"><h3 className=\"box-title\">Detalle VIN {car ? car.vin : null}</h3>\n              <div className=\"box-tools pull-right\">\n              </div>\n            </div>\n            <div className=\"box-body\">\n              <table style={{width: '100%'}}>\n                <tbody>\n                  <tr>\n                    <td style={{padding: '5px'}}><strong>Último Checkeo</strong></td>\n                    <td style={{padding: '5px'}}>\n                      {\n                        car && car.participants && `${moment(car.participants[0].createdAt).format('LLL')}`\n                      }\n                    </td>\n                  </tr>\n                  <tr>\n                    <td style={{padding: '5px'}}><strong>Por</strong></td>\n                    <td style={{padding: '5px'}}>\n                      {\n                        car && car.participants && car.participants[0].user ? `${car.participants[0].user.firstName} ${car.participants[0].user.lastName}` : '-'\n                      }\n                    </td>\n                  </tr>\n                <tr>\n                    <td style={{padding: '5px'}}><strong>Marca</strong></td>\n                    <td style={{padding: '5px'}}>\n                      {\n                        car && car.brand ? car.brand : '-'\n                      }\n                    </td>\n                  </tr>\n                <tr>\n                    <td style={{padding: '5px'}}><strong>Denominación</strong></td>\n                    <td style={{padding: '5px'}}>\n                      {\n                        car && car.denomination ? car.denomination : '-'\n                      }\n                    </td>\n                  </tr>\n                </tbody>\n              </table>\n              <h4>Detalle</h4>\n              <table className=\"table table-striped\">\n                <thead>\n                  <tr>\n                    <th className=\"middle\">Nº</th>\n                    <th className=\"middle\">Fecha</th>\n                    <th className=\"middle\">Formulario</th>\n                    <th className=\"middle hidden-xs\">Supervisor</th>\n                    <th className=\"middle hidden-xs\">Sucursal</th>\n                    <th className=\"middle-center hidden-xs\">Calificación</th>\n                    <th className=\"width-10\"/>\n                    <th className=\"width-10\"/>\n                  </tr>\n                </thead>\n                <tbody>\n                {\n                  car &&  car.participants && car.participants.map((participant) => (\n                    <tr key={participant._id} className={highlight.length && highlight.includes(participant._id as never) ? 'highlight-info' : ''}>\n                      <td className=\"middle\">{participant.number}</td>\n                      <td className=\"middle\">{moment(participant.createdAt).format('LLL')}</td>\n                      <td className=\"middle\">{participant.name}</td>\n                      <td className=\"middle hidden-xs\">{participant.user ? participant.user.firstName : ''} {participant.user ? participant.user.lastName : ''}</td>\n                      <td className=\"middle hidden-xs\">{participant.venue ? participant.venue.name : '-'}</td>\n                      <td className=\"middle-center hidden-xs\">\n                        <ShowIf\n                          condition={!!(participant.hasOwnProperty('qualification') && participant.qualification)}\n                          alternative={'-'}\n                        >\n                          {`${Math.round(participant.qualification)}%`}\n                        </ShowIf>\n                        <ShowIf\n                          condition={participant.hasDamages}\n                        >\n                          <React.Fragment>\n                            {' '}<i\n                            className='fa fa-warning text-red'\n                            data-toggle='tooltip'\n                            data-placement='top'\n                            title='Daños encontrados en esta revisión.'\n                          />\n                          </React.Fragment>\n                        </ShowIf>\n                      </td>\n                      <td className=\"text-primary middle-center\">\n                        <button\n                          className=\"btn btn-xs btn-default\"\n                          disabled={carLoading === participant._id}\n                          onClick={() => this.printPdf(`/report/forms/pdf/${participant._id}.pdf`, participant._id)}\n                        ><i className={carLoading === participant._id ? 'fa fa-spinner fa-spin' : 'fa fa-print'}/></button>\n                      </td>\n                      <td className=\"middle pointer\">\n                        <button\n                          className=\"btn btn-xs btn-primary\"\n                          disabled={!!(loadingParticipant && loadingParticipant === participant._id)}\n                          onClick={loadingParticipant ? undefined : () => getParticipant(participant._id)}\n                        >\n                          <ShowIf\n                            condition={!!(loadingParticipant && loadingParticipant === participant._id)}\n                            alternative={<i className=\"fa fa-bar-chart\"/>}\n                          >\n                            <i className=\"fa fa-spin fa-spinner\"/>\n                          </ShowIf>\n                        </button>\n                      </td>\n                    </tr>\n                  ))\n                }\n                </tbody>\n              </table>\n              <h4>Solicitudes</h4>\n              <table className=\"table table-striped\">\n                <thead>\n                  <tr>\n                    <th className=\"middle\">Nº</th>\n                    <th className=\"middle\">Estado</th>\n                    <th className=\"middle\">Solicitante</th>\n                    <th className=\"middle\">Vendedor</th>\n                    <th className=\"middle\">Cliente</th>\n                    <th className=\"middle\">RUT Cliente</th>\n                    <th className=\"middle\">Correo</th>\n                    <th className=\"middle-center\">Ticket</th>\n                    <th className=\"middle\">Nº Ticket</th>\n                    <th className=\"middle\">Sucursal</th>\n                  </tr>\n                </thead>\n                <tbody>\n                {\n                  requests.map((request) => {\n                    return (\n                      <tr key={request._id}>\n                        <td>\n                          <a\n                            href={parseReplicableURL(`/requests/vehicles/${request.request._id}/`)}\n                            target='_blank'\n                            style={{\n                              textDecoration: 'underline'\n                            }}\n                          >#{request.request.number} <i className='fa fa-fw fa-share-alt-square' /></a>\n                        </td>\n                        <td>{request.status?.name}</td>\n                        <td>{request.request.createdBy ? `${request.request.createdBy.firstName} ${request.request.createdBy.lastName}` : ''}</td>\n                        <td>{request.request.sellerText}</td>\n                        <td>{request.request?.customerInformation?.name}</td>\n                        <td>{request.request?.customerInformation?.rut}</td>\n                        <td>{request.request?.customerInformation?.email}</td>\n                        <td className='middle-center'>\n                          {\n                            request.request?.advancePaymentInformation?.files?.length ?\n                              <i\n                                className='fa fa-check-circle text-green pointer'\n                                onClick={() => this.openBlank(request.request.advancePaymentInformation.files[0].file.url)}\n                              /> : ''\n                          }\n                        </td>\n                        <td className='middle'>{request.request?.advancePaymentInformation?.number}</td>\n                        <td>{request.destination?.name}</td>\n                      </tr>\n                    )\n                  })\n                }\n                </tbody>\n              </table>\n            </div>\n            {\n              loading &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private openBlank(url: string) {\n    window.open(url, '_blank');\n  }\n}\n\nconst mapStateToProps = (state: { dashboard: IDashboardState }) => {\n  return {\n    dashboard: state.dashboard\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getCarAction: (id: string) => dispatch(getCarAction(id)),\n    getParticipant: (id: string) => dispatch(getParticipant(id)),\n    loadParticipantInCarAction: (participant: IParticipant) => dispatch(loadParticipantInCarAction(participant))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DashboardVinDetail);\n","import * as moment from 'moment-timezone';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport { io } from \"socket.io-client\";\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport { debounce } from 'throttle-debounce';\nimport * as swal from 'sweetalert';\nimport { IParticipant } from '../../../../../../src/form/interfaces/participant.interface';\nimport {\n  changeFormsSearchDashboardAction,\n  changeRangeDashboardAction,\n  changeSearchDashboardAction,\n  DashboardReduxAction,\n  getRevisionsAction,\n  getRevisionsThunkAction,\n  IDashboardState\n} from '../../actions/dashboard.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport Paginator from '../Utils/Paginator';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport DateRangeInput from '../Utils/DateRangeInput';\nimport BootstrapSelect from \"../Utils/BootstrapSelect\";\nimport {IForm} from \"../../../../../../src/form/interfaces/form.interface\";\nimport ShowIf from '../Utils/ShowIf';\n\ndeclare let window: IWindow;\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<DashboardReduxAction>;\n  dashboard: IDashboardState;\n  getRevisionsThunkAction(page: number, loading: boolean, search?: string) : void;\n  getRevisionsAction(page: number, loading: boolean, search?: string): void;\n  changeSearchFormsDashboardAction(forms: string[]): DashboardReduxAction;\n  changeSearchDashboardAction(searchText: string): DashboardReduxAction;\n  changeRangeDashboardAction(from: string, to: string): DashboardReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  highlight: string[];\n  searchText: string;\n  selectedForms: string[];\n  carLoading: string;\n  from: Date;\n  to: Date;\n  downloading: boolean;\n}\n\nclass DashboardVinView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  readonly state: IStateType = {\n    error: null,\n    highlight: [],\n    searchText: '',\n    carLoading: '',\n    selectedForms: [],\n    from: moment().subtract(30, 'days').toDate(),\n    to: moment().toDate(),\n    downloading: false\n  };\n  protected printIframe: any;\n\n  protected isMount: boolean = false;\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Revisiones';\n    this.changePage = this.changePage.bind(this);\n    this.onChangeSearch = this.onChangeSearch.bind(this);\n    this.printPdf = this.printPdf.bind(this);\n    this.debounceOnChangeSearch = debounce(300, this.debounceOnChangeSearch);\n    this.downloadReport = this.downloadReport.bind(this);\n    this.onDateRangeChange = this.onDateRangeChange.bind(this);\n    this.filterForms = this.filterForms.bind(this);\n    this.filterAllForms = this.filterAllForms.bind(this);\n    this.showSelect = this.showSelect.bind(this);\n  }\n\n  public printPdf(url: string, carLoading: string) {\n    this.setState({carLoading});\n    let iframe: any = this.printIframe;\n    const timezone = moment.tz.guess();\n    if (!this.printIframe) {\n      iframe = this.printIframe = document.createElement('iframe');\n      document.body.appendChild(iframe);\n      iframe.style.display = 'none';\n      iframe.onload = () => {\n        setTimeout(() => {\n          iframe.focus();\n          iframe.contentWindow.print();\n          this.setState({carLoading: ''});\n          // document.body.removeChild(iframe)\n        }, 1);\n      };\n    }\n    iframe.src = `${url}?timezone=${timezone}`;\n  }\n\n  public componentWillMount(): void {\n    // set the title of the page\n    const {page} = this.props.dashboard.pagination;\n    this.props.getRevisionsThunkAction(page, true);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: (window.user as any).token\n      }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {room: `dashboard-vin-view-${window.user.team._id}`});\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      const {page} = this.props.dashboard.pagination;\n      if (data.update) {\n        ($ as any).toast({\n          heading: data.notification.title,\n          text: data.notification.text,\n          position: 'top-right',\n          loaderBg: '#e2e2e2',\n          icon: 'success',\n          hideAfter: 5000,\n          stack: 6\n        });\n        this.props.getRevisionsAction(page, false);\n        if (!this.state.highlight.includes(data.car)) {\n          this.setState({\n            highlight: [data.car, ...this.state.highlight]\n          });\n        } else {\n          this.setState({\n            highlight: this.state.highlight.filter((e) => e !== data.car)\n          }, () => {\n            this.setState({\n              highlight: [data.car, ...this.state.highlight]\n            });\n          });\n        }\n        setTimeout(() => {\n          if (this.isMount) {\n            this.setState({\n              highlight: this.state.highlight.filter((e) => e !== data.car)\n            });\n          }\n        }, 3000);\n      }\n    });\n    this.isMount = true;\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n  }\n\n  getDateRangeOptions(): daterangepicker.Options {\n    return {\n      maxDate: moment(),\n      opens: 'left'\n    };\n}\n\n  onDateRangeChange(from: Date, to: Date){\n    this.setState({\n      from,\n      to\n    });\n    this.props.changeRangeDashboardAction(moment(from).format('YYYY-MM-DD'), moment(to).format('YYYY-MM-DD'));\n    this.debounceOnChangeSearch();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentWillUnmount() {\n    this.isMount = false;\n    // cancel request if component is inmounted\n    if (this.props.dashboard.source) {\n      this.props.dashboard.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if(this.props.dashboard.pagination !== prevProps.dashboard.pagination){\n      window.scrollTo(0, 0);\n    }\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public downloadReport(){\n    const {from, to} = this.state;\n    const monthsDiff = moment(to).diff(moment(from), 'months');\n    this.trackClick('Descargar reporte', {\n      from,\n      to\n    });\n    if(monthsDiff > 3){\n      swal('Revisiones', 'Selecciona un rango de 3 meses para dercargar la información', 'error');\n    } else {\n      window.open(`/api/participant/export/?from=${moment(from).unix()}&to=${moment(to).unix()}`, '_blank');\n    }\n\n    // const api: ApiService = new ApiService();\n    // const instance = api.getInstance();\n    // const source = api.getSource();\n    // instance.defaults.timeout = 7200000;\n    // instance.get(`/api/participant/export/?from=${from}&to=${to}`, {\n    //     responseType: 'arraybuffer',\n    //   })\n    //   .then((response) => {\n    //     const blob = new Blob([response.data], {\n    //       type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'\n    //     });\n    //     const fileName = `${moment().format('YYYYMMDD')}-revisiones.xlsx`;\n    //     if (typeof window.navigator.msSaveBlob !== 'undefined') {\n    //       // IE workaround for \"HTML7007: One or more blob URLs were\n    //       // revoked by closing the blob for which they were created.\n    //       // These URLs will no longer resolve as the data backing\n    //       // the URL has been freed.\"\n    //       window.navigator.msSaveBlob(blob, fileName);\n    //     } else {\n    //       const blobURL = URL.createObjectURL(blob);\n    //       const tempLink = document.createElement('a');\n    //       tempLink.style.display = 'none';\n    //       tempLink.href = blobURL;\n    //       tempLink.setAttribute('download', fileName);\n    //       // Safari thinks _blank anchor are pop ups. We only want to set _blank\n    //       // target if the browser does not support the HTML5 download attribute.\n    //       // This allows you to download files in desktop safari if pop up blocking\n    //       // is enabled.\n    //       if (typeof tempLink.download === 'undefined') {\n    //         tempLink.setAttribute('target', '_blank');\n    //       }\n    //       document.body.appendChild(tempLink);\n    //       tempLink.click();\n    //       document.body.removeChild(tempLink);\n    //       URL.revokeObjectURL(blobURL);\n\n    //       this.setState({\n    //         downloading: false\n    //       });\n    //     }\n    //   })\n    //   .catch((err) => {\n    //     this.setState({\n    //       downloading: false\n    //     });\n    //     if (!Axios.isCancel(err)) {\n    //       swal('Exportar revisiones', 'Ha ocurrido un error al general el excel.', 'error');\n    //     }\n    //   });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {loading, participants, pagination, searchText, forms} = this.props.dashboard;\n    const {highlight, carLoading, downloading, from, to, selectedForms} = this.state;\n    return (\n      <AppContainer title=\"\" cMenu=\"1\" cSubMenu=\"1.2\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\"><h3 className=\"box-title\">Revisiones <small>{pagination.count}</small></h3>\n              <div className=\"box-tools pull-right\">\n                <button\n                  className=\"btn btn-sm btn-primary hidden-xs hidden-sm\"\n                  onClick={this.downloadReport}\n                  disabled={downloading}\n                >\n                  <i className=\"fa fa-fw fa-download\" /> Exportar Excel\n                </button>\n              </div>\n            </div>\n            <div className={`box-body no-padding`}>\n              <div className=\"row\">\n                <div className=\"col-md-offset-2 col-md-4\">\n                  <DateRangeInput\n                    options={this.getDateRangeOptions()}\n                    onChange={this.onDateRangeChange}\n                    startDate={from}\n                    endDate={to} />\n                </div>\n                <div className=\"col-md-3\">\n                  <div\n                    className='input-group input-group-sm'\n                    style={{ padding: '10px' }}\n                  >\n                    <input\n                      type=\"text\"\n                      className=\"form-control pull-right\"\n                      onChange={this.onChangeSearch}\n                      value={searchText}\n                      placeholder=\"Buscar VIN, marca, supervisor o sucursal\"/>\n                    <div className=\"input-group-btn\">\n                      <button className=\"btn btn-default\"><i className=\"fa fa-search\"/></button>\n                    </div>\n                  </div>\n                </div>\n                {/*<div className='col-md-3' style={{ paddingTop: '10px', paddingRight: '28px' }}>*/}\n                <div className='col-md-3'>\n                  <div style={{padding: \"10px\"}}>\n                    <BootstrapSelect\n                      noneSelectedText=\"Filtrar por checklist\"\n                      displayItems={2}\n                      sm={true}\n                      selectedText=\"Formularios seleccionadas.\"\n                      selected={selectedForms}\n                      allOption={true}\n                      selectAll={this.filterAllForms}\n                      options={forms.map((form: IForm) => ({\n                        value: form._id,\n                        text: form.name\n                      }))}\n                      onClick={this.filterForms}\n                      displayHandler={this.showSelect}\n                      notHideOnClickOutside={false}\n                    />\n                  </div>\n                </div>\n              </div>\n              {\n                participants.length ?\n                  <div className='table-responsive'>\n                    <table className=\"table table-andes table-striped\">\n                    <thead>\n                      <tr>\n                        <th style={{width: '5%'}} className=\"middle hidden-xs\">Nº</th>\n                        <th style={{width: '12%'}} className=\"middle\">VIN</th>\n                        <th style={{width: '8%'}} className=\"middle hidden-xs\">Patente</th>\n                        <th style={{width: '9%'}} className=\"middle hidden-xs\">Marca</th>\n                        <th style={{width: '13%'}} className=\"middle hidden-xs\">Supervisor</th>\n                        <th style={{width: '13%'}} className=\"middle\">Sucursal</th>\n                        <th style={{width: '10%'}} className=\"middle-center hidden-xs\">Calificación</th>\n                        <th style={{width: '15%'}} className=\"hidden-xs\">Fecha</th>\n                        <th style={{width: '15%'}} className=\"hidden-xs\">Último checkeo</th>\n                        <th className=\"width-10 hidden-xs\"/>\n                        <th className=\"width-10\"/>\n                      </tr>\n                    </thead>\n                    <tbody>\n                      {\n                        participants.map((participant: IParticipant) => {\n                          return (\n                            <tr\n                              key={participant._id} id={`car-${participant._id}`}\n                              className={highlight.length && highlight.includes(participant._id as never) ? 'highlight-info' : ''}\n                            >\n                              <td className=\"middle hidden-xs\">{participant.number}</td>\n                              <td className=\"middle\">\n                                {participant.car.vin}\n                                <div className='visible-xs'>\n                                  <ShowIf condition={!!participant.car.patent?.length}>\n                                    <br />{participant.car.patent}\n                                  </ShowIf>\n                                </div>\n                              </td>\n                              <td className=\"middle hidden-xs\">{participant.car.patent && participant.car.patent.length ? participant.car.patent : '-'}</td>\n                              <td className=\"middle hidden-xs\">{participant.car.brand}</td>\n                              <td className=\"middle hidden-xs\">\n                                {`${participant.user ? `${participant.user.firstName} ${participant.user.lastName}` : ''}`}\n                              </td>\n                              <td className=\"middle\">\n                                {`${participant.venue ? `${participant.venue.name}` : '-'}`}\n                              </td>\n                              <td className=\"middle-center\">\n                                {\n                                  `${participant.hasOwnProperty('qualification') ?\n                                    participant.qualification ? `${Math.round(participant.qualification)}%` : !participant.hasDamages ? '-' : '' : ''}`\n                                }\n                                {\n                                  participant.hasDamages ?\n                                    <React.Fragment>\n                                      {' '}<i\n                                        className=\"fa fa-warning text-red\"\n                                        data-toggle=\"tooltip\"\n                                        data-placement=\"top\"\n                                        title=\"Daños encontrados en esta revisión.\"\n                                      />\n                                    </React.Fragment>\n                                    : null\n                                }\n                              </td>\n                              <td className=\"middle hidden-xs\">\n                                {moment(participant.createdAt).format('L HH:mm:ss')}\n                              </td>\n                              <td className=\"middle hidden-xs\">\n                                {participant.name}\n                                {/* {participant.car.lastForm && participant.car.lastForm.createdAt ?\n                                  moment(participant.car.lastForm.createdAt).format('L HH:mm:ss')\n                                  :\n                                  '-'\n                                } */}\n                              </td>\n                              <td className=\"text-primary middle-center hidden-xs\">\n                                <button\n                                  className=\"btn btn-xs btn-default\"\n                                  disabled={carLoading === participant._id}\n                                  onClick={() => this.printPdf(`/report/forms/pdf/${participant._id}.pdf`, participant._id)}\n                                ><i className={carLoading === participant._id ? 'fa fa-spinner fa-spin' : 'fa fa-print'}/></button>\n                              </td>\n                              <td className=\"text-primary middle-center\">\n                                <button\n                                  className=\"btn btn-xs btn-primary\"\n                                  onClick={() => this.props.history.push(`/cars/${participant.car._id}`)}\n                                ><i className=\"fa fa-bars\"/></button>\n                              </td>\n                            </tr>\n                          );\n                        })\n                      }\n                    </tbody>\n                  </table>\n                  </div>\n                  : !loading ? <p style={{padding: '10px'}}><strong>No se han encontrado revisiones.</strong></p> : null\n              }\n            </div>\n            {\n              pagination.pages > 1 &&\n              <div className=\"box-footer\">\n                <div className=\"row\">\n                  <div className=\"col-md-6\" style={{ padding: '20px 15px' }}>\n                    <span className=\"react-bootstrap-table-pagination-total text-ellipsis\">\n                      &nbsp;&nbsp;Mostrando registros del {(pagination.page - 1) * 20 + 1} al {(pagination.page) * 20} de {pagination.count} registros.\n                      </span>\n                  </div>\n                  <div className=\"col-md-6\">\n                    <div className=\"text-right\" style={{ marginRight: '15px' }}>\n                      <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                    </div>\n                  </div>\n                </div>\n              </div>\n            }\n            {\n              loading &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private filterForms(value: any) {\n    let {selectedForms} = this.state;\n    let sForms = selectedForms;\n\n    sForms = sForms.includes(value)\n        ? sForms.filter((form) => form !== value)\n        : [value, ...selectedForms]\n\n    this.setState({\n      selectedForms: sForms\n    });\n  }\n\n  private filterAllForms(value: boolean) {\n    let {forms} = this.props.dashboard;\n    let sForms = value ? forms.map( (f: IForm) => f._id) : [];\n\n    this.setState({\n      selectedForms: sForms\n    });\n  }\n\n  showSelect(value: boolean) : void {\n    let {selectedForms} = this.state;\n    if (!value) {\n      this.props.changeSearchFormsDashboardAction(selectedForms);\n      this.props.getRevisionsAction(1, true);\n    }\n  }\n\n  private onChangeSearch(e: React.ChangeEvent<HTMLInputElement>): void {\n    e.preventDefault();\n    const value = e.target.value;\n    this.props.changeSearchDashboardAction(value);\n    this.debounceOnChangeSearch();\n  }\n\n  private debounceOnChangeSearch(): void {\n    const {searchText} = this.state;\n    if (searchText && searchText.length) {\n      this.props.getRevisionsAction(1, true, searchText);\n    } else {\n      this.props.getRevisionsAction(1, true);\n    }\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    this.props.getRevisionsAction(page, true);\n  }\n}\n\nconst mapStateToProps = (state: { dashboard: IDashboardState }) => {\n  return {\n    dashboard: state.dashboard\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getRevisionsThunkAction: (page: number, loading: boolean, search?: string) => dispatch(getRevisionsThunkAction(page, loading, search)),\n    changeSearchFormsDashboardAction : (forms : string[]) => dispatch(changeFormsSearchDashboardAction(forms)),\n    changeSearchDashboardAction: (searchText: string) => dispatch(changeSearchDashboardAction(searchText)),\n    changeRangeDashboardAction: (from: string, to: string) => dispatch(changeRangeDashboardAction(from, to)),\n    getRevisionsAction: (page: number, loading: boolean, search?: string) => dispatch(getRevisionsAction(page, loading, search))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DashboardVinView);\n","import {AxiosError} from 'axios';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo, RefObject} from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport * as uuid from 'uuid';\nimport * as XLSX from 'xlsx';\nimport {IUsersState, UserReduxAction} from '../../actions/users.actions';\nimport AppContainer from '../../container/AppContainer';\nimport ApiService from '../../utils/axios';\nimport ModalView from '../Modal/ModalView';\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\n\nenum carStatus {\n  Error,\n  Pending,\n  Finish\n}\n\ninterface IImportCar {\n  id?: string;\n  NInterno: string;\n  vin: string;\n  marca: string;\n  denominacion: string;\n  patente: string;\n  color: string;\n  destino: string;\n  status: number;\n}\n\ninterface ICarObject {\n  [key: string]: IImportCar;\n}\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<UserReduxAction>;\n}\n\ninterface IStateType {\n  error: Error | null;\n  loadFile: boolean;\n  cars: IImportCar[];\n  carsObj: ICarObject;\n  canDrop: boolean;\n}\n\nclass ImportCarsView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  // static propTypes = {\n  //   users: PropTypes.object.isRequired,\n  //   dispatch: PropTypes.func.isRequired\n  // };\n\n  state = {\n    error: null,\n    loadFile: false,\n    cars: [],\n    canDrop: false,\n    carsObj: {}\n  };\n\n  readonly inputFile: RefObject<HTMLInputElement>;\n  // private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Importar autos';\n    this.clickUploadFile = this.clickUploadFile.bind(this);\n    this.handleChangeInputFile = this.handleChangeInputFile.bind(this);\n    this.startLoad = this.startLoad.bind(this);\n    this.processSettings = this.processSettings.bind(this);\n    this.handleDrop = this.handleDrop.bind(this);\n    this.dragOverHandler = this.dragOverHandler.bind(this);\n    this.dragEndHandler = this.dragEndHandler.bind(this);\n    this.dragLeaveHandler = this.dragLeaveHandler.bind(this);\n    this.inputFile = React.createRef();\n  }\n\n componentDidMount() {\n   super.componentDidMount();\n }\n\n  public componentWillUnmount() {\n    // this.socket.disconnect();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {cars, loadFile} = this.state;\n    return (\n      <AppContainer title=\"\" cMenu=\"10\" cSubMenu=\"10.2\"  cAction=\"Importar\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Importar autos</h3>\n              <div className=\"pull-right box-tools\">\n                <button\n                  className=\"btn btn-sm btn-primary\"\n                  onClick={this.downloadTemplate}\n                  style={{marginRight: '5px'}}>\n                  <i className=\"fa fa-fw fa-download\" /> Descargar Formato\n                </button>\n                {\n                  cars.length >= 1 ? <button\n                    className=\"btn btn-sm btn-default\"\n                    onClick={this.clickUploadFile}>\n                    <i className=\"fa fa-fw fa-cloud-upload\"/> {cars.length >= 1 ? 'Cargar otro excel' : 'Subir excel'}\n                  </button> : null\n                }\n              </div>\n            </div>\n            <div className=\"box-body margin\">\n              <div className=\"row\">\n                <div className=\"col-md-12\">\n                  <input\n                    type=\"file\"\n                    ref={this.inputFile}\n                    style={{display: 'none'}}\n                    onChange={this.handleChangeInputFile}\n                    accept=\".xlsx, .xls\"\n                  />\n                </div>\n              </div>\n              {\n                cars.length ?\n                  <div className=\"row\">\n                    <div className=\"col-md-12\">\n                      {\n                        loadFile ? <div>\n                          Cargando...\n                        </div> :\n                          <div className=\"pull-right\">\n                            <button className=\"btn btn-sm btn-flat btn-success\" onClick={this.startLoad}>\n                              <i className=\"fa fa-fw fa-play\" /> Iniciar carga\n                            </button>\n                          </div>\n                      }\n                      <table className=\"table\">\n                        <thead>\n                        <tr>\n                          <th>Nº Interno</th>\n                          <th>VIN</th>\n                          <th>Patente</th>\n                          <th>Marca</th>\n                          <th>Denominación</th>\n                          <th>Color</th>\n                          <th>Destino</th>\n                        </tr>\n                        </thead>\n                        <tbody>\n                        {\n                          cars.map((car: IImportCar) => {\n                            let classTR = '';\n                            if (car.status === carStatus.Finish) {\n                              classTR = 'success';\n                            } else if (car.status === carStatus.Error) {\n                              classTR = 'danger';\n                            }\n                            return (\n                              <tr key={car.id} className={classTR}>\n                                <td>{car.NInterno}</td>\n                                <td>{car.vin}</td>\n                                <td>{car.patente}</td>\n                                <td>{car.marca}</td>\n                                <td>{car.denominacion}</td>\n                                <td>{car.color}</td>\n                                <td>{car.destino}</td>\n                              </tr>\n                            );\n                          })\n                        }\n                        </tbody>\n                      </table>\n                    </div>\n                  </div> : <div\n                  className=\"upload-file text-center pointer\"\n                  onClick={this.clickUploadFile}\n                  onDrop={this.handleDrop}\n                  onDragOver={this.dragOverHandler}\n                  onDragEnd={this.dragEndHandler}\n                  onDragLeave={this.dragLeaveHandler}\n                  style={{\n                    backgroundColor: '#EEEEEE',\n                    border: this.state.canDrop ? '1px solid #979797' : '1px dashed #979797',\n                    padding: '100px 20px',\n                    color: this.state.canDrop ? '#aebccb' : '#6e7a89',\n                    borderRadius: '5px',\n                    marginBottom: '10px'\n                  }}>\n                  <i className=\"fa fa-2x fa-cloud-upload\"/><br/>\n                  Prueba a soltanto el excel aquí, o haz click para seleccionar el excel a cargar.\n                </div>\n              }\n            </div>\n            {\n              loadFile &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private handleDrop(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      if (dt.items.length) {\n        const file: File | null = dt.items[0].getAsFile();\n        if (file) {\n          this.processSettings(file);\n        }\n      }\n    } else {\n      if (dt.files.length) {\n        const file = dt.files[0];\n        this.processSettings(file);\n      }\n    }\n  }\n\n  private dragOverHandler(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    this.setState({\n      canDrop: true\n    });\n  }\n\n  private dragLeaveHandler(): void {\n    this.setState({\n      canDrop: false\n    });\n  }\n\n  private dragEndHandler(e: React.DragEvent<HTMLDivElement>): void {\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      // Use DataTransferItemList interface to remove the drag data\n      for (let i = 0; i < dt.items.length; i++) {\n        dt.items.remove(i);\n      }\n    } else {\n      // Use DataTransfer interface to remove the drag data\n      e.dataTransfer.clearData();\n    }\n  }\n\n  private startLoad() {\n    const {cars} = this.state;\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a cargar ${cars.length} autos, recuerda que puedes revisar que los datos estén correctos en la pre visualización del Excel.`,\n      icon: 'warning',\n      buttons: true,\n      dangerMode: true\n    } as any)\n      .then((willDelete) => {\n        if (willDelete) {\n          const api: ApiService = new ApiService();\n          this.setState({\n            loadFile: true\n          });\n          api\n            .getSource();\n          api\n            .sendImportCars({cars})\n            .then(() => {\n              swal('Importador de autos', 'La carga a finalizado exitosamente.', 'success');\n              this.setState({\n                loadFile: false,\n                cars: this.state.cars.map((car: IImportCar) => {\n                  car.status = carStatus.Finish;\n                  return car;\n                })\n              });\n            })\n            .catch((err: AxiosError) => {\n              api.errorHandler(err);\n            });\n        }\n      });\n\n  }\n\n  private clickUploadFile() {\n    if (this.inputFile.current) {\n      this.inputFile.current.click();\n    }\n  }\n\n  private downloadTemplate() {\n    /* headers worksheet */\n    const data = [{\n     NInterno: '',\n      vin: '',\n      marca: '',\n      patente: '',\n      denominacion: '',\n      color: '',\n      propiedad: '',\n      tipo: ''\n      // motor: '',\n      // destino: ''\n    }];\n    /* make the worksheet */\n    const ws = XLSX.utils.json_to_sheet(data);\n    /* add to workbook */\n    const wb = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(wb, ws, 'Autos');\n    /* generate an XLSX file */\n    XLSX.writeFile(wb, 'template_import_cars_v1.1.xlsx');\n  }\n\n  private handleChangeInputFile(e: React.ChangeEvent<HTMLInputElement>) {\n    const {files} = e.target;\n    if (files && files.length) {\n      const file = files[0];\n      this.processSettings(file);\n    }\n  }\n\n  private processSettings(file: File): void {\n    if (['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'].includes(file.type)) {\n      const reader = new FileReader();\n      const rABS = !!reader.readAsBinaryString;\n      reader.onload = (e: any) => {\n        if (e.target) {\n          let data = e.target.result;\n          if (!rABS) {\n            data = new Uint8Array(data);\n          }\n          const workbook = XLSX.read(data, {\n            type: rABS ? 'binary' : 'array'\n          });\n          const cars: IImportCar[] = workbook.Sheets.hasOwnProperty('Autos') ? XLSX.utils.sheet_to_json(workbook.Sheets.Autos) : [];\n          if (cars.length >= 1) {\n            this.setState({\n              cars: cars.map((car) => {\n                car.id = uuid.v1();\n                car.status = carStatus.Pending;\n                return car;\n              })\n            });\n          } else {\n            swal('Importador de autos', 'Este excel no cumple con los requisitos mínimos o no tiene autos.', 'error');\n          }\n        }\n      };\n      if (rABS) {\n        reader.readAsBinaryString(file);\n      } else {\n        reader.readAsArrayBuffer(file);\n      }\n      if (this.inputFile.current) {\n        this.inputFile.current.value = '';\n      }\n    }\n  }\n}\n\nconst mapStateToProps = (state: { users: IUsersState }) => {\n  return {\n    users: state.users\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(ImportCarsView);\n","import { AxiosError, AxiosResponse } from 'axios';\nimport * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo, RefObject } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport * as swal from 'sweetalert';\nimport * as XLSX from 'xlsx';\nimport { AlertReduxAction, IAlertsState } from '../../actions/alerts.actions';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport AppContainer from '../../container/AppContainer';\nimport ApiService from '../../utils/axios';\nimport { getExtension, getIconFromExtension } from '../../utils/common';\nimport Checkbox from '../Utils/CheckBox';\nimport VenueDetail from './VenueDetail';\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  alerts: IAlertsState;\n  dispatch: Dispatch<AlertReduxAction>;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  canDrop: boolean;\n  notification: boolean;\n  loadingSettings: boolean;\n  carsByVenue: any;\n  venues: any[];\n  loading: boolean;\n  name: string;\n  sending: boolean;\n  file: File | null;\n  backupFile: File | null;\n  backupUri: string;\n  manualPhoto: number;\n  reportPhoto: number;\n}\n\nclass InventoryCreateView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  // static propTypes = {\n  //   dispatch: PropTypes.func.isRequired\n  // };\n\n  readonly inputFile: RefObject<HTMLInputElement>;\n  readonly inputBackup: RefObject<HTMLInputElement>;\n\n  readonly state = {\n    error: null,\n    canDrop: false,\n    loadingSettings: false,\n    carsByVenue: [],\n    venues: [],\n    loading: true,\n    notification: true,\n    name: `Inventario del ${moment().format('DD-MM-YYYY')}`,\n    sending: false,\n    file: null,\n    backupFile: null,\n    backupUri: '',\n    manualPhoto: 1,\n    reportPhoto: 1\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Creando Inventario';\n    this.clickUploadFile = this.clickUploadFile.bind(this);\n    this.clickUploadBackup = this.clickUploadBackup.bind(this);\n    this.getVenues = this.getVenues.bind(this);\n    this.processSettings = this.processSettings.bind(this);\n    this.deleteVenue = this.deleteVenue.bind(this);\n    this.handleChangeInputFile = this.handleChangeInputFile.bind(this);\n    this.handleChangeInputBackup = this.handleChangeInputBackup.bind(this);\n    this.handleChangeManualPhoto = this.handleChangeManualPhoto.bind(this);\n    this.handleDrop = this.handleDrop.bind(this);\n    this.dragOverHandler = this.dragOverHandler.bind(this);\n    this.dragEndHandler = this.dragEndHandler.bind(this);\n    this.clearBackup = this.clearBackup.bind(this);\n    this.dragLeaveHandler = this.dragLeaveHandler.bind(this);\n    this.sendCreate = this.sendCreate.bind(this);\n    this.handleChangeName = this.handleChangeName.bind(this);\n    this.handleChangeNotification = this.handleChangeNotification.bind(this);\n    this.inputFile = React.createRef();\n    this.inputBackup = React.createRef();\n  }\n\n  public componentWillMount(): void {\n    this.getVenues();\n  }\n\n  public componentWillUnmount() {\n    // cancel request if component is inmounted\n    // if (this.props.alerts.source) {\n    //   this.props.alerts.source.cancel('Operation canceled by the user.');\n    // }\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    const $reportPhoto: any = $('#report-photo');\n    $reportPhoto.TouchSpin({\n      initval: 1,\n      min: 0,\n      max: 3\n    }).on('change', () => {\n      this.setState({\n        reportPhoto: parseInt($reportPhoto.val(), 10)\n      });\n    });\n    const $manualPhoto: any = $('#manual-photo');\n    $manualPhoto.TouchSpin({\n      initval: 1,\n      min: 0,\n      max: 3\n    }).on('change', () => {\n      this.setState({\n        manualPhoto: parseInt($manualPhoto.val(), 10)\n      });\n    });\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      loadingSettings, carsByVenue, name,\n      sending, notification, backupFile,\n      backupUri, loading\n    } = this.state;\n    let carsInSettings = 0;\n    return (\n      <AppContainer title=\"\" cMenu=\"2\" cSubMenu=\"2.1\" cAction=\"Creación\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Creando Inventario</h3>\n            </div>\n            <div className=\"box-body margin\">\n              <div className=\"row\">\n                <div className=\"col col-md-6\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"name\">Nombre</label>\n                    <input type=\"text\" className=\"form-control\" id=\"name\" value={name} onChange={this.handleChangeName} />\n                  </div>\n                </div>\n              </div>\n              {\n                carsByVenue.length ?\n                  <div className=\"row\">\n                    <div className=\"col-md-12\">\n                      <div className=\"form-group\">\n                        <label>Configuración cargada</label>\n                        <div className=\"box-group\" id=\"accordion\" style={{margin: '2px 0 10px 0'}}>\n                          {\n                            carsByVenue.map((venue: any, index) => {\n                              carsInSettings += venue.cars.length;\n                              return (\n                                <VenueDetail index={index} venue={venue} key={venue.name} deleteVenue={this.deleteVenue} />\n                              );\n                            })\n                          }\n                        </div>\n                      </div>\n                    </div>\n                    <div className=\"col-md-6\">\n                      <p><strong>Total de sucursales:</strong> {carsByVenue.length}</p>\n                      <p><strong>Total de unidades:</strong> {carsInSettings}</p>\n                    </div>\n                    <div className=\"col-md-6 text-right\">\n                      <button className=\"btn btn-sm btn-primary\" onClick={this.downloadTemplate}>\n                        <i className=\"fa fa-fw fa-download\" /> Descargar Formato\n                      </button>\n                      <button className=\"btn btn-sm btn-default\" onClick={this.clickUploadFile} style={{marginLeft: '5px'}}>\n                        <i className=\"fa fa-fw fa-cogs\" /> Cambiar configuración\n                      </button>\n                    </div>\n                    <div className=\"col-md-12\">\n                      <div className=\"form-group\" style={{marginBottom: '0px'}}>\n                        <label>Archivo de respaldo</label>\n                      </div>\n                      <div className=\"preview-files\">\n                        {\n                          backupFile && backupUri ?\n                            <div className=\"file\">\n                              <i className=\"fa fa-minus-circle text-red pointer\" onClick={this.clearBackup}/>\n                              <a\n                                href={backupUri}\n                                className=\"zoom-in\"\n                                data-toggle=\"lightbox\"\n                                data-title={`Vista previa de la imagen`}\n                                data-footer={(backupFile as unknown as File).name}\n                              >\n                                <img\n                                  src={backupUri}\n                                  data-toggle=\"tooltip\"\n                                  data-placement=\"bottom\"\n                                  title={(backupFile as unknown as File).name}\n                                />\n                              </a>\n                            </div>\n                            : backupFile ?\n                            <div className=\"file\">\n                              <i className=\"fa fa-minus-circle text-red pointer\" onClick={this.clearBackup}/>\n                              <div className={`icon type-${getIconFromExtension(getExtension((backupFile as unknown as File).name))}`}/>\n                              <div\n                                className=\"name-file\"\n                                data-toggle=\"tooltip\"\n                                data-placement=\"bottom\"\n                                title={(backupFile as unknown as File).name}\n                              >\n                                {(backupFile as unknown as File).name}\n                              </div>\n                            </div>\n                            : <div\n                              className=\"add-file\"\n                              onClick={this.clickUploadBackup}\n                            >\n                              <i className=\"fa fa-plus\"/>\n                              AGREGAR ARCHIVO\n                            </div>\n                        }\n                      </div>\n                      <input\n                        type=\"file\"\n                        onChange={this.handleChangeInputBackup}\n                        style={{display: 'None'}}\n                        ref={this.inputBackup}\n                      />\n                    </div>\n                  </div> :\n                  <div className=\"row\">\n                    <div className=\"col col-md-12\">\n                      <div className=\"form-group\">\n                        <label>Importar configuración</label>\n                        <div\n                          className=\"upload-file text-center pointer\"\n                          onClick={this.clickUploadFile}\n                          onDrop={this.handleDrop}\n                          onDragOver={this.dragOverHandler}\n                          onDragEnd={this.dragEndHandler}\n                          onDragLeave={this.dragLeaveHandler}\n                          style={{\n                            backgroundColor: '#EEEEEE',\n                            border: this.state.canDrop ? '1px solid #979797' : '1px dashed #979797',\n                            padding: '40px 20px',\n                            color: this.state.canDrop ? '#aebccb' : '#6e7a89',\n                            borderRadius: '5px'\n                          }}>\n                          <i className=\"fa fa-2x fa-cloud-upload\"/><br/>\n                          Prueba soltando el excel aquí, o haz click para seleccionar el excel a cargar.\n                        </div>\n                      </div>\n                    </div>\n                    <div className=\"col-md-12 text-right\">\n                      <button\n                        className=\"btn btn-sm btn-primary\"\n                        onClick={this.downloadTemplate}\n                      >\n                        <i className=\"fa fa-fw fa-download\"/> Descargar Formato\n                      </button>\n                    </div>\n                  </div>\n              }\n\n              <input\n                type=\"file\"\n                onChange={this.handleChangeInputFile}\n                style={{display: 'None'}}\n                ref={this.inputFile} accept=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel\"\n              />\n              <div className=\"row\">\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\" style={{marginBottom: '0px', marginTop: '10px'}}>\n                    <label>Configuraciones</label>\n                  </div>\n                </div>\n                <div className=\"col-md-12 no-padding\">\n                  <div className=\"col-sm-12 col-md-8 col-lg-6\">\n                    <div className=\"form-horizontal\">\n                      <div className=\"form-group\" style={{marginRight: '0', marginLeft: '0'}}>\n                        <div className=\"col-sm-6 col-md-8 col-lg-8 no-padding\">\n                          <span\n                            className=\"control-label\"\n                            style={{\n                              paddingLeft: '0',\n                              textAlign: 'left',\n                              fontWeight: 600\n                            }}\n                          >\n                          Nº imágenes al inventariar\n                        </span><br/>\n                          <span className={'text-sm text-muted'}>Cantidad de fotografías solicitadas al ingresar unidad digitando el VIN.</span>\n                        </div>\n                        <input id=\"manual-photo\" type=\"text\" className=\"col-sm-6 col-md-4 col-lg-4 form-control\" />\n                      </div>\n                    </div>\n                    {/*<div className=\"checkbox\">*/}\n                    {/*  <label style={{paddingLeft: '0'}} onClick={this.handleChangeManualPhoto}>*/}\n                    {/*    <Checkbox*/}\n                    {/*      active={manualPhoto === 1}*/}\n                    {/*      action={this.handleChangeManualPhoto}*/}\n                    {/*      classes=\"icheck-in-checkbox\"*/}\n                    {/*      style={{marginTop: '-4px', marginRight: '5px'}}*/}\n                    {/*    />*/}\n                    {/*    Solicitar foto en modo manual*/}\n                    {/*  </label>*/}\n                    {/*</div>*/}\n                  </div>\n                </div>\n                <div className=\"col-sm-12 col-md-8 col-lg-6\">\n                  <div className=\"form-horizontal\">\n                    <div className=\"form-group\" style={{marginRight: '0', marginLeft: '0'}}>\n                      <div className=\"col-sm-6 col-md-8 col-lg-8 no-padding\">\n                        <span\n                          className=\"control-label\"\n                          style={{\n                            paddingLeft: '0',\n                            textAlign: 'left',\n                            fontWeight: 600\n                          }}\n                        >\n                        Nº imágenes al reportar\n                      </span><br/>\n                        <span className={'text-sm text-muted'}>Cantidad de fotografías solicitadas al reportar una unidad.</span>\n                      </div>\n                      <input id=\"report-photo\" type=\"text\" className=\"col-sm-6 col-md-4 col-lg-4 form-control\" />\n                    </div>\n                  </div>\n                    {/*<input*/}\n                    {/*  type=\"text\"*/}\n                    {/*  id=\"report-photo\"*/}\n                    {/*  className=\"input-sm form-control\"*/}\n                    {/*  style={{*/}\n                    {/*    width: '35px'*/}\n                    {/*  }}*/}\n                    {/*/>*/}\n                    {/*<span>Cantidad de imágenes al reportar</span>*/}\n                </div>\n                <div className=\"col-md-8 col-sm-12\">\n                  <div className=\"checkbox\">\n                    <label style={{paddingLeft: '0', fontWeight: 600}} onClick={this.handleChangeNotification}>\n                      <Checkbox\n                        active={notification}\n                        action={this.handleChangeNotification}\n                        classes=\"icheck-in-checkbox\"\n                        style={{marginTop: '-4px', marginRight: '5px'}}\n                      />\n                      Enviar notificaciones push\n                    </label>\n                  </div>\n                </div>\n              </div>\n            </div>\n            <div className=\"box-footer text-right\">\n              <button className=\"btn btn-sm btn-default\" onClick={() => this.props.history.push('/inventory/')}>Cancelar</button>\n              <button className=\"btn btn-sm btn-primary\" style={{marginLeft: '5px'}} onClick={this.sendCreate} disabled={sending}>\n                {\n                  sending || loading ?\n                    <React.Fragment>\n                      <i className=\"fa fa-fw fa-spin fa-spinner\"/> Creando...\n                    </React.Fragment>\n                    : 'Crear'\n                }\n              </button>\n            </div>\n            {\n              sending || loading || loadingSettings ?\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div> : null\n            }\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private deleteVenue(venueName: string): void {\n    const {carsByVenue} = this.state;\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar la sucursal \"${venueName}\"`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.setState({\n          carsByVenue: carsByVenue.filter((venue: any) => venue.name !== venueName)\n        });\n      }\n    });\n  }\n\n  private handleChangeNotification() {\n    this.setState({\n      notification: !this.state.notification\n    });\n  }\n\n  private clickUploadFile(): void {\n    if (this.inputFile.current) {\n      this.inputFile.current.click();\n    }\n  }\n\n  private clickUploadBackup(): void {\n    if (this.inputBackup.current) {\n      this.inputBackup.current.click();\n    }\n  }\n\n  private handleChangeManualPhoto(): void {\n    const {manualPhoto} = this.state;\n    this.setState({\n      manualPhoto: manualPhoto === 1 ? 0 : 1\n    });\n  }\n\n  private handleChangeName(e: React.ChangeEvent<HTMLInputElement>): void {\n    const {value} = e.target;\n    this.setState({\n      name: value\n    });\n  }\n\n  private downloadTemplate(): void {\n    /* headers worksheet */\n    const data = [{\n      sucursal: '',\n      NInterno: '',\n      vin: '',\n      marca: '',\n      patente: '',\n      denominacion: '',\n      color: '',\n      propiedad: '',\n      tipo: ''\n    }];\n    /* make the worksheet */\n    const ws = XLSX.utils.json_to_sheet(data);\n    /* add to workbook */\n    const wb = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(wb, ws, 'Autos');\n    /* generate an XLSX file */\n    XLSX.writeFile(wb, 'template_inventory_settings.xlsx');\n  }\n\n  private processSettings(file: File): void {\n    const {venues} = this.state;\n    this.setState({\n      loadingSettings: true\n    });\n    if (['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'].includes(file.type)) {\n      const reader = new FileReader();\n      const rABS = !!reader.readAsBinaryString;\n      reader.onload = (e: any) => {\n        if (e.target) {\n          let data = e.target.result;\n          if (!rABS) {\n            data = new Uint8Array(data);\n          }\n          const workbook: XLSX.WorkBook = XLSX.read(data, {\n            type: rABS ? 'binary' : 'array'\n          });\n          const excelData = workbook.Sheets.hasOwnProperty('Autos') ? XLSX.utils.sheet_to_json(workbook.Sheets.Autos) : [];\n          const carsByVenue: any = {};\n          if (excelData.length >= 1) {\n            excelData.forEach((item: any) => {\n              if (item.hasOwnProperty('vin') && item.vin && item.hasOwnProperty('sucursal') && item.sucursal) {\n                const vinWarning = item.vin.length < 17;\n                const patentWarning = item.patente && item.patente.length < 6;\n                const car = {\n                  vin: item.vin.trim(),\n                  internalNumber: item.NInterno ? item.NInterno.trim() : '',\n                  color: item.color ? item.color.trim() : '',\n                  denomination: item.denominacion ? item.denominacion.trim() : '',\n                  brand: item.marca ? item.marca.trim() : '',\n                  patent: item.patente ? item.patente.trim() : '',\n                  property: item.propiedad ? item.propiedad.trim().toUpperCase() : '',\n                  type: item.tipo ? item.tipo.trim() : '',\n                  hasWarnings: vinWarning || patentWarning,\n                  warning: {\n                    vin: vinWarning,\n                    patent: patentWarning\n                  }\n                };\n                if (!carsByVenue.hasOwnProperty(item.sucursal)) {\n                  // venues.push(item.sucursal);\n                  carsByVenue[item.sucursal] = {\n                    cars: []\n                  };\n                }\n                carsByVenue[item.sucursal].cars.push(car);\n                // cars.push(car);\n              } else {\n                /* tslint:disable:no-console */\n                console.log('Error en linea:');\n                console.log(item.__rowNum__);\n              }\n            });\n            const carsByVenueArray: any[] = [];\n            for (const cv in carsByVenue) {\n              if (carsByVenue.hasOwnProperty(cv)) {\n                const existVenue = venues.some((venue: any) => {\n                  return venue.name.trim().toLowerCase() === cv.trim().toLowerCase();\n                });\n                carsByVenueArray.push({\n                  name: cv.trim(),\n                  warningNoExist: !existVenue,\n                  cars: carsByVenue[cv].cars.sort((x: any, y: any) => {\n                    return (x.hasWarnings === y.hasWarnings) ? 0 : x.hasWarnings ? -1 : 1;\n                  })\n                });\n              }\n            }\n            this.setState({\n              file,\n              carsByVenue: carsByVenueArray,\n              loadingSettings: false\n            });\n          } else {\n            swal!(\n              'Importador de configuración',\n              `\"${file.name}\" no cumple con los requisitos mínimos o no tiene autos.`,\n              'error'\n            );\n            this.setState({\n              loadingSettings: false\n            });\n          }\n        }\n      };\n      if (rABS) {\n        reader.readAsBinaryString(file);\n      } else {\n        reader.readAsArrayBuffer(file);\n      }\n      if (this.inputFile.current) {\n        this.inputFile.current.value = '';\n      }\n    } else {\n      swal!('Importador de configuración', 'Este archivo no cumple con los requisitos mínimos o no tiene autos.', 'error');\n      this.setState({\n        loadingSettings: false\n      });\n    }\n  }\n\n  private handleChangeInputFile(e: React.ChangeEvent<HTMLInputElement>): void {\n    const {files} = e.target;\n    if (files && files.length) {\n      this.processSettings(files[0]);\n    }\n  }\n\n  private validateSize(size: number): boolean {\n    const maxSize = Math.pow(1024, 2) * 10; // 10MB\n    return size <= maxSize;\n  }\n\n  private clearBackup(): void {\n    this.setState({\n      backupFile: null,\n      backupUri: ''\n    });\n  }\n\n  private handleChangeInputBackup(e: React.ChangeEvent<HTMLInputElement>): void {\n    const {files} = e.target;\n    if (files && files.length) {\n      const file = files[0];\n      if (!this.validateSize(file.size)) {\n        swal!('Envió inventario', 'El archivo supera los 10Mb permitidos.', 'error');\n      } else {\n        if (new RegExp('\\\\bimage\\\\b').test(file.type)) {\n          const reader = new FileReader();\n          reader.onload = (e) => {\n            if (e.target) {\n              this.setState({\n                backupFile: file,\n                backupUri: (e.target as any).result\n              });\n            }\n          };\n          reader.readAsDataURL(file);\n        } else {\n          this.setState({\n            backupFile: file,\n            backupUri: ''\n          });\n        }\n      }\n    }\n  }\n\n  private handleDrop(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      if (dt.items.length) {\n        const file: File | null = dt.items[0].getAsFile();\n        if (file) {\n          this.processSettings(file);\n        }\n      }\n    } else {\n      if (dt.files.length) {\n        const file = dt.files[0];\n        this.processSettings(file);\n      }\n    }\n  }\n\n  private dragOverHandler(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    this.setState({\n      canDrop: true\n    });\n  }\n\n  private dragLeaveHandler(): void {\n    this.setState({\n      canDrop: false\n    });\n  }\n\n  private dragEndHandler(e: React.DragEvent<HTMLDivElement>): void {\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      // Use DataTransferItemList interface to remove the drag data\n      for (let i = 0; i < dt.items.length; i++) {\n        dt.items.remove(i);\n      }\n    } else {\n      // Use DataTransfer interface to remove the drag data\n      e.dataTransfer.clearData();\n    }\n  }\n\n  private getVenues(){\n    this.setState({loading: true});\n    const api: ApiService = new ApiService();\n    api.getVenues({ page: 1, pageSize: 200, noPopulate: true })\n      .then((response: AxiosResponse):void =>{\n        this.setState({\n          venues: response.data.results,\n          loading: false\n        });\n      })\n    .catch((err: AxiosError): void => {\n      api.errorHandler(err);\n    });\n  }\n\n  private sendCreate(): void {\n    const {carsByVenue, name, notification, file, backupFile, manualPhoto, reportPhoto} = this.state;\n    const { history } = this.props;\n    this.setState({\n      sending: true\n    });\n    if (!name.trim().length) {\n      swal!('Envió inventario', 'El nombre del inventario es obligatorio.', 'error');\n      this.setState({\n        sending: false\n      });\n    } else if (!carsByVenue.length) {\n      swal!('Envió inventario', 'No se ha importado la configuración o no contiene sucursales.', 'error');\n      this.setState({\n        sending: false\n      });\n    } else if (file) {\n      const api = new ApiService({\n        'Content-Type': 'multipart/form-data'\n      });\n      api.getSource();\n      api\n        .createInventory({\n          carsByVenue, name, notification, file, backupFile, manualPhoto, reportPhoto\n        })\n        .then((response: any) => {\n          const { message } = response.data;\n          setTimeout(() => {\n            swal!('Envió inventario', message, 'success');\n          }, 200);\n          history.push('/inventory/');\n          this.setState({\n            sending: false\n          });\n        })\n        .catch((e) => {\n          console.log('e', e);\n          swal!('Envió inventario', 'Se produjo un error al crear el inventario.', 'error');\n          this.setState({\n            sending: false\n          });\n        });\n    }\n  }\n}\n\nconst mapStateToProps = (state: { alerts: IAlertsState }) => {\n  return {\n    alerts: state.alerts\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(InventoryCreateView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport slugify from 'slugify';\nimport CarDetail from './CarDetail';\n\ninterface IPropsType {\n  venue: any;\n  index: number;\n\n  deleteVenue(venueName: string): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass VenueDetail extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {venue, index} = this.props;\n    const warnings = venue.cars.filter((car: any) => car.hasWarnings).length;\n    return (\n      <div className=\"panel box box-default\" style={{borderTopWidth: '2px'}}>\n        <div className=\"box-header with-border\" style={{padding: '6px'}}>\n          <h4 className=\"box-title\" style={{\n            fontSize: '15px',\n            display: 'block'\n          }}>\n            <a data-toggle=\"collapse\"\n               data-parent=\"#accordion\"\n               href={`#${slugify(venue.name.toLowerCase(), {remove: /[*+~.()'\"!:@]/g})}`}\n               aria-expanded=\"false\"\n               className=\"collapsed\">\n              {index + 1} {venue.name} ({venue.cars.length} Unidades)\n            </a>\n            <i className=\"fa fa-minus-circle text-red pull-right pointer\" onClick={() => this.props.deleteVenue(venue.name)} />\n            {\n              venue.warningNoExist ?\n                <span className=\"text-muted pull-right\" style={{marginLeft: '5px'}}>\n                  <i className=\"fa fa-warning\" style={{color: '#f2aa2e'}}/> Esta sucursal se creará.\n                </span> : null\n            }\n            {\n              warnings ?\n                <span className=\"text-muted pull-right\" style={{marginLeft: '5px'}}>\n                  <i className=\"fa fa-warning\" style={{color: '#f2aa2e'}}/> {warnings} posibles problemas.\n                </span> : null\n            }\n          </h4>\n        </div>\n        <div id={`${slugify(venue.name.toLowerCase(), {remove: /[*+~.()'\"!:@]/g})}`} className=\"panel-collapse collapse\" aria-expanded=\"false\">\n          <div className=\"box-body no-padding\">\n            <table className=\"table table-striped\">\n              <thead>\n              <tr>\n                <th style={{width: '15%'}}>VIN</th>\n                <th style={{width: '10%'}}>PATENTE</th>\n                <th style={{width: '15%'}}>MARCA</th>\n                <th>DENOMINACION</th>\n                <th style={{width: '15%'}}>TIPO</th>\n              </tr>\n              </thead>\n              <tbody>\n              {\n                venue.cars.map((car: any, index: any) => {\n                  return (\n                    <CarDetail car={car} key={index}/>\n                  );\n                })\n              }\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </div>\n    );\n  }\n}\n\nexport default VenueDetail;\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\n\ninterface IPropsType {\n  car: any;\n  // increaseWarning(): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass CarDetail extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {car} = this.props;\n    return (\n      <tr>\n        <td>\n          {\n            car.hasWarnings && car.warning.vin ?\n              <i\n                className=\"fa fa-warning pointer\"\n                style={{\n                  color: '#f2aa2e'\n                }}\n                data-toggle=\"tooltip\"\n                data-placement=\"top\"\n                title=\"El vin debe tener al menos 17 dígitos.\"\n              /> : null} {car.vin}\n        </td>\n        <td>\n          {\n            car.hasWarnings && car.warning.patent ?\n              <i\n                className=\"fa fa-warning pointer\"\n                style={{\n                  color: '#f2aa2e'\n                }}\n                data-toggle=\"tooltip\"\n                data-placement=\"top\"\n                title=\"La patente debe tener al menos 6 dígitos.\"\n              /> : null} {car.patent}\n        </td>\n        <td>{car.brand}</td>\n        <td>{car.denomination}</td>\n        <td>{car.type}</td>\n      </tr>\n    );\n  }\n}\n\nexport default CarDetail;\n","import * as Raven from 'raven-js';\nimport {ErrorInfo} from 'react';\nimport * as React from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport {\n  getInventoryDashboard,\n  getInventoryDashboardFiltered,\n  IInventoryDashboardState,\n  InventoryDashboardReduxAction\n} from '../../actions/inventoryDashboard.actions';\nimport AppContainer from '../../container/AppContainer';\nimport {IWindow} from '../../interfaces/window';\nimport {IFilterCar} from '../../reducers/inventory.reducer';\nimport BootstrapSelect from '../Utils/BootstrapSelect';\nimport Row from '../Utils/Row';\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\n\ndeclare let window: IWindow;\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  inventoryDashboard: IInventoryDashboardState;\n  dispatch: Dispatch<InventoryDashboardReduxAction>;\n  getInventoryDashboard(filter: IFilterCar): void;\n  getInventoryDashboardFiltered(filter: IFilterCar): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass InventoryDashboardView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  monthlyReport: echarts.ECharts;\n\n  state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Dashboard de inventarios';\n    this.resizeCharts = this.resizeCharts.bind(this);\n\n    this.filterVenues = this.filterVenues.bind(this);\n    this.filterAllVenues = this.filterAllVenues.bind(this);\n  }\n\n  public componentWillMount(): void {\n\n    window.scrollTo(0, 0);\n\n    // add listeners\n    window.addEventListener('resize', this.resizeCharts, false);\n\n    // get data\n    const { filter } = this.props.inventoryDashboard;\n    this.props.getInventoryDashboard(filter);\n\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    const $monthlyReport = document.getElementById('inventory-monthly-report') as HTMLDivElement;\n    this.monthlyReport = echarts.init($monthlyReport);\n\n  }\n\n  public componentDidUpdate(prevProps: IPropsType, prevState: IStateType): void {\n    const {loading} = this.props.inventoryDashboard;\n    if (!loading) {\n      this.updateDashboardChart();\n    }\n  }\n\n  public componentWillUnmount(): void {\n    // remove listeners\n    window.removeEventListener('resize', this.resizeCharts, false);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { filter, loading, venues } = this.props.inventoryDashboard;\n    return (\n      <AppContainer title=\"\" cMenu=\"2\" cSubMenu=\"2.3\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Dashboard de inventarios</h3>\n            </div>\n            <div className=\"box-body\">\n              <Row>\n                <div className=\"col-md-12\">\n                  <BootstrapSelect\n                    noneSelectedText=\"Todas\"\n                    displayItems={2}\n                    selectedText=\"sucursales seleccionadas.\"\n                    selected={filter.venues}\n                    allOption={true}\n                    selectAll={this.filterAllVenues}\n                    options={venues.map((venue: any) => ({\n                      value: venue._id,\n                      text: venue.name\n                    }))}\n                    onClick={this.filterVenues}\n                  />\n                  <div id=\"inventory-monthly-report\" style={{height: '50vh', maxWidth: '100%'}} />\n                </div>\n              </Row>\n            </div>\n            {\n              loading &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private resizeCharts(): void {\n    if (this.monthlyReport) {\n      this.monthlyReport.resize();\n      setTimeout(() => {\n        this.monthlyReport.resize();\n      }, 400);\n    }\n  }\n\n  private filterVenues(value: any) {\n\n    const {filter} = this.props.inventoryDashboard;\n\n    const venues = filter.venues.includes(value) ? filter.venues.filter((venue) => venue !== value) : [value, ...filter.venues];\n    this.props.getInventoryDashboardFiltered({\n      ...filter,\n      venues\n    });\n  }\n\n  private filterAllVenues(value: boolean) {\n    const { filter, venues} = this.props.inventoryDashboard;\n    this.props.getInventoryDashboardFiltered({\n      ...filter,\n      venues: value ? venues.map((v) => v._id) : []\n    });\n  }\n\n  private updateDashboardChart() {\n    const { monthlyReport, inventorySettings } = this.props.inventoryDashboard;\n\n    const labelOption = {\n      normal: {\n        show: true,\n        position: 'inside',\n        align: 'center',\n        verticalAlign: 'middle',\n        rotate: 90,\n        formatter: '{c}',\n        fontSize: 12,\n        rich: {\n          name: {\n            textBorderColor: '#fff'\n          }\n        }\n      }\n    };\n\n    const xSerie = Object.keys(monthlyReport);\n    const found = Object.values(monthlyReport).map((v) => v.found);\n    const pending = Object.values(monthlyReport).map((v) => v.pending);\n    const leftover = Object.values(monthlyReport).map((v) => v.leftover);\n    const missing = Object.values(monthlyReport).map((v) => v.missing);\n    const reported = Object.values(monthlyReport).map((v) => v.reported);\n\n    const option: any = {\n      color: [inventorySettings.foundColor, inventorySettings.leftoverColor, inventorySettings.missingColor, inventorySettings.pendingColor, inventorySettings.reportedColor],\n      tooltip: {\n        trigger: 'axis',\n        axisPointer: {\n          type: 'shadow'\n        }\n      },\n      legend: {\n        x: 'center',\n        bottom: 50,\n        data: [inventorySettings.found, inventorySettings.leftover, inventorySettings.missing, inventorySettings.pending, inventorySettings.reported]\n      },\n      calculable: true,\n      xAxis: [\n        {\n          type: 'category',\n          axisTick: {show: false},\n          data: xSerie\n        }\n      ],\n      yAxis: [\n        {\n          type: 'value'\n        }\n      ],\n      grid: {\n        top: 30,\n        bottom: 100,\n        // left\n        x: 0,\n        // right\n        x2: 10,\n        containLabel: true\n      },\n      series: [\n        {\n          name: inventorySettings.found,\n          type: 'bar',\n          barMaxWidth: 100,\n          label: labelOption,\n          data: found\n        },\n        {\n          name: inventorySettings.leftover,\n          type: 'bar',\n          barMaxWidth: 100,\n          label: labelOption,\n          data: leftover\n        },\n        {\n          name: inventorySettings.missing,\n          type: 'bar',\n          barMaxWidth: 100,\n          label: labelOption,\n          data: missing\n        },\n        {\n          name: inventorySettings.pending,\n          type: 'bar',\n          barMaxWidth: 100,\n          label: labelOption,\n          data: pending\n        },\n        {\n          name: inventorySettings.reported,\n          type: 'bar',\n          barMaxWidth: 100,\n          label: labelOption,\n          data: reported\n        }\n      ]\n    };\n\n    this.monthlyReport.setOption(option);\n\n  }\n}\n\nconst mapStateToProps = (state: { inventoryDashboard: IInventoryDashboardState }) => {\n  return {\n    inventoryDashboard: state.inventoryDashboard\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getInventoryDashboard: () => dispatch(getInventoryDashboard()),\n    getInventoryDashboardFiltered: (filter: IFilterCar) => dispatch(getInventoryDashboardFiltered(filter))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(InventoryDashboardView);\n","import { AxiosError, default as Axios } from 'axios';\nimport {Dispatch} from 'redux';\nimport {IFilterCar} from '../reducers/inventory.reducer';\nimport ApiService from '../utils/axios';\nimport {IInventorySetting} from '../../../../../src/app/interfaces/teamSetting.interface';\n\nexport interface IInventoryDashboardState {\n  venues: any[];\n  monthlyReport: any[];\n  inventorySettings: IInventorySetting;\n  filter: IFilterCar;\n  loading: boolean;\n}\n\ninterface ILoadInventoryDashboard {\n  type: '/INVENTORY_DASHBOARD/LOAD_DATA';\n  payload: {\n    venues: any[];\n    monthlyReport: any[];\n    inventorySettings: any;\n  };\n}\n\nexport function loadInventoriesDashboardAction(venues: any[], monthlyReport: any[], inventorySettings: any): ILoadInventoryDashboard {\n  return {\n    type: '/INVENTORY_DASHBOARD/LOAD_DATA',\n    payload: {\n      venues,\n      monthlyReport,\n      inventorySettings\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/INVENTORY_DASHBOARD/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/INVENTORY_DASHBOARD/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface ILoadInventoryDashboardFiltered {\n  type: '/INVENTORY_DASHBOARD/LOAD_DATA_FILTERED';\n  payload: {\n    filter: IFilterCar;\n    monthlyReport: any[];\n    inventorySettings: any;\n  };\n}\n\nexport function loadInventoriesDashboardFilteredAction(filter: IFilterCar, monthlyReport: any[], inventorySettings: any): ILoadInventoryDashboardFiltered {\n  return {\n    type: '/INVENTORY_DASHBOARD/LOAD_DATA_FILTERED',\n    payload: {\n      filter,\n      monthlyReport,\n      inventorySettings\n    }\n  };\n}\n\nexport function getInventoryDashboard() {\n  return (dispatch: Dispatch<InventoryDashboardReduxAction>) => {\n    const api: ApiService = new ApiService();\n    dispatch(isLoadingAction(true));\n    Axios.all([\n      api.getVenues({ page: 1, pageSize: 200 }),\n      api.getInventoryDashboard()\n    ]).then(Axios.spread((venues, dashboard) => {\n      dispatch(loadInventoriesDashboardAction(venues.data.results, dashboard.data.data, dashboard.data.inventorySettings));\n    })).catch((err: AxiosError): void => {\n      api.errorHandler(err);\n    });\n  };\n}\n\nexport function getInventoryDashboardFiltered(filter: IFilterCar) {\n  return (dispatch: Dispatch<InventoryDashboardReduxAction>) => {\n    const api: ApiService = new ApiService();\n    api.getInventoryDashboard(filter)\n      .then((dashboard) => {\n        dispatch(loadInventoriesDashboardFilteredAction(filter, dashboard.data.data, dashboard.data.inventorySettings));\n      }).catch((err: AxiosError): void => {\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport type InventoryDashboardReduxAction = ILoadInventoryDashboard | ILoadInventoryDashboardFiltered | IIsLoading;\n","///<reference path=\"../../../src/types/react-bootstrap-table-next.d.ts\"/>\n///<reference path=\"../../../src/types/react-bootstrap-table2-filter.d.ts\"/>\n///<reference path=\"../../../src/types/react-bootstrap-table2-paginator.d.ts\"/>\nimport {CancelTokenSource, default as Axios} from 'axios';\nimport * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport BootstrapTable from 'react-bootstrap-table-next';\nimport filterFactory from 'react-bootstrap-table2-filter';\nimport paginationFactory from 'react-bootstrap-table2-paginator';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {RouterState} from 'react-router-redux';\nimport {Dispatch} from 'redux';\nimport { io } from \"socket.io-client\";\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport * as swal from 'sweetalert';\nimport * as XLSX from 'xlsx';\nimport {IInventoryCar} from '../../../../../../src/inventory/interfaces/inventory.interface';\nimport {IInventoryLabel} from '../../../../../../src/inventory/interfaces/inventoryLabel.interface';\nimport {IInventorySetting} from '../../../../../../src/app/interfaces/teamSetting.interface';\nimport {\n  actionSetLabel,\n  addCommentAction,\n  getInventoryDetailAction,\n  IDetailByBrand,\n  IDetailByVenue,\n  IInventoryState,\n  IInventorySummaryResult,\n  inventoryDetailChangeFilter,\n  inventoryDetailChangeFilterText,\n  inventoryDetailChangeSelected,\n  InventoryReduxAction,\n  sendCommentAction,\n  updateInventoryCarAction\n} from '../../actions/inventory.actions';\nimport {\n  loadDataAction,\n  ModalReduxAction\n} from '../../actions/modal.actions';\nimport AppContainer from '../../container/AppContainer';\nimport {IWindow} from '../../interfaces/window';\nimport {IFilterCar} from '../../reducers/inventory.reducer';\nimport ApiService from '../../utils/axios';\nimport {goToSection, hasPermission, isDercoDercocenter, maxText} from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport BootstrapSelect from '../Utils/BootstrapSelect';\nimport Checkbox from '../Utils/CheckBox';\nimport CopyText from '../Utils/CopyText';\nimport ImageLazyLoad from '../Utils/ImageLazyLoad';\nimport Row from '../Utils/Row';\nimport InventoryCarComments from './InventoryCarComments';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport InventoryFileManager from './InventoryFileManager';\n\ndeclare let window: IWindow;\n\nexport type CarStatusType = Extract<keyof IInventorySetting, string>;\n\ninterface IPropsType extends RouteComponentProps<{ id: string, tab?: string }> {\n  inventories: IInventoryState;\n  router: RouterState;\n  dispatch: Dispatch<InventoryReduxAction>;\n\n  inventoryDetailChangeSelected(item: string): InventoryReduxAction;\n  updateInventoryCarAction(inventoryCar: IInventoryCar): InventoryReduxAction;\n  inventoryDetailChangeFilter(filter: IFilterCar): InventoryReduxAction;\n  inventoryDetailChangeFilterText(filter: IFilterCar): InventoryReduxAction;\n  getInventoryDetailAction(id: string, update: boolean): InventoryReduxAction;\n  loadDataAction(title: string, body: JSX.Element, footer?: JSX.Element): ModalReduxAction;\n  actionSetLabel(inventory: string, car: string, carID: string, label: IInventoryLabel): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  setCharts: boolean;\n  tab: string;\n  source: CancelTokenSource | null;\n  downloadImages: {\n    downloading: boolean;\n    progress: number;\n    sizeFile: number;\n    loaded: number;\n  };\n}\n\nclass InventoryDetailView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  readonly state = {\n    error: null,\n    downloadImages: {\n      downloading: false,\n      progress: 0,\n      sizeFile: 0,\n      loaded: 0\n    },\n    setCharts: false,\n    tab: 'summary',\n    source: null\n  };\n\n  private venuesDetailChart: echarts.ECharts;\n  private brandDetailChart: echarts.ECharts;\n\n  private labelOption: any = {\n    normal: {\n      show: true,\n      position: 'inside',\n      align: 'center',\n      verticalAlign: 'middle',\n      rotate: 90,\n      formatter: '{c}',\n      fontSize: 12,\n      rich: {\n        name: {\n          textBorderColor: '#fff'\n        }\n      }\n    }\n  };\n\n  private statusText: any = {\n    pending: 'Pendiente',\n    found: 'Encontrado',\n    leftover: 'Sobrante',\n    missing: 'Faltante',\n    reported: 'Reportado'\n  };\n\n  private iconStatus: any = {\n    pending: 'fa-clock-o',\n    found: 'fa-check',\n    leftover: 'fa-arrow-up',\n    missing: 'fa-arrow-down',\n    reported: 'fa-exclamation',\n    deleted: 'fa-close'\n  };\n\n  private paginationOption: any = {\n    // paginationSize: 4,\n    showTotal: true,\n    paginationTotalRenderer: this.customTotal,\n    sizePerPageList: [{\n      text: '10', value: 10\n    }, {\n      text: '50', value: 50\n    }, {\n      text: '200', value: 200\n    }],\n    onPageChange: () => {\n      setTimeout(() => {\n        $('[data-toggle=\"tooltip\"]').tooltip();\n      }, 200);\n    }\n  };\n\n  private defaultSorted = [{\n    dataField: 'status',\n    order: 'asc'\n  }];\n\n  private readonly columns: any[] = [];\n\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Detalle Inventario';\n    this.resizeCharts = this.resizeCharts.bind(this);\n    this.xlsExport = this.xlsExport.bind(this);\n    this.carComments = this.carComments.bind(this);\n    this.selectedFormatter = this.selectedFormatter.bind(this);\n    this.filterVenues = this.filterVenues.bind(this);\n    this.filterAllVenues = this.filterAllVenues.bind(this);\n    this.filterStatus = this.filterStatus.bind(this);\n    this.filterType = this.filterType.bind(this);\n    this.filterProperty = this.filterProperty.bind(this);\n    this.selectedHeaderFormatter = this.selectedHeaderFormatter.bind(this);\n    this.statusFormatter = this.statusFormatter.bind(this);\n    this.brandFormatter = this.brandFormatter.bind(this);\n    this.commentFormatter = this.commentFormatter.bind(this);\n    this.labelFormatter = this.labelFormatter.bind(this);\n    this.optionsFormatter = this.optionsFormatter.bind(this);\n    this.calculateDetails = this.calculateDetails.bind(this);\n    this.imagesFormatter = this.imagesFormatter.bind(this);\n    this.filesFormatter = this.filesFormatter.bind(this);\n    this.openFileManager = this.openFileManager.bind(this);\n    this.handleChangeSearchText = this.handleChangeSearchText.bind(this);\n    this.clearFilter = this.clearFilter.bind(this);\n    this.sendToDetailFilteredByState = this.sendToDetailFilteredByState.bind(this);\n    this.sendToDetailFilteredByVenue = this.sendToDetailFilteredByVenue.bind(this);\n    this.downloadImages = this.downloadImages.bind(this);\n    this.changeTab = this.changeTab.bind(this);\n    const {tab} = this.props.match.params;\n    if (tab && tab === 'detail') {\n      this.state.tab = 'detail';\n    }\n    this.columns = [{\n      dataField: 'selected',\n      text: '',\n      // headerFormatter: this.selectedHeaderFormatter,\n      formatter: this.selectedFormatter,\n      sort: true,\n      headerClasses: 'pointer middle-center hidden-xs hidden-sm',\n      classes: 'middle-center hidden-xs hidden-sm',\n      headerStyle: {\n        maxWidth: '60px',\n        minWidth: '60px',\n        width: '60px'\n      },\n      style: {\n        maxWidth: '60px',\n        minWidth: '60px',\n        width: '60px'\n      }\n    }, {\n      dataField: 'brand',\n      text: 'Vehículo',\n      formatter: this.brandFormatter,\n      filterValue: (cell: any, row: any) => `${cell}${row.denomination}${row.vin}${row.patent}`,\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true\n    }, {\n      dataField: 'venue',\n      text: 'Sucursal',\n      classes: 'middle hidden-xs hidden-sm',\n      headerClasses: 'middle hidden-xs hidden-sm pointer',\n      style: {\n        width: '15%'\n      },\n      sort: true\n    }, {\n      dataField: 'venueFound',\n      text: 'Encontrado en',\n      classes: 'middle hidden-xs hidden-sm hidden-md',\n      headerClasses: 'middle hidden-xs hidden-sm hidden-md pointer',\n      style: {\n        width: '15%'\n      },\n      sort: true\n    }, /* {\n      dataField: 'countComments',\n      text: 'Comentarios',\n      classes: 'middle hidden-xs text-ellipsis',\n      formatter: this.commentFormatter,\n      headerClasses: 'middle hidden-xs',\n      style: {\n        width: '15%'\n      },\n      headerStyle: {\n        verticalAlign: 'top'\n      }\n    } */ {\n      dataField: 'labelName',\n      text: 'Etiqueta',\n      sort: true,\n      classes: 'middle hidden-xs',\n      filterValue: (cell: any) => `${cell ? cell.name : ''}`,\n      formatter: this.labelFormatter,\n      headerClasses: 'middle hidden-xs',\n      style: {\n        width: '18%',\n        maxWidth: '18%'\n      },\n      headerStyle: {\n        verticalAlign: 'top'\n      }\n    }, {\n      dataField: 'images',\n      text: 'Imágenes',\n      classes: 'middle hidden-xs hidden-sm hidden-md',\n      headerClasses: 'middle hidden-xs hidden-sm hidden-md',\n      formatter: this.imagesFormatter,\n      headerStyle: {\n        maxWidth: '80px',\n        minWidth: '80px',\n        width: '80px'\n      },\n      style: {\n        maxWidth: '80px',\n        minWidth: '80px',\n        width: '80px'\n      }\n    }, {\n      dataField: 'files',\n      text: 'Archivos',\n      classes: 'middle hidden-xs hidden-sm hidden-md',\n      headerClasses: 'middle hidden-xs hidden-sm hidden-md',\n      formatter: this.filesFormatter,\n      headerStyle: {\n        maxWidth: '80px',\n        minWidth: '80px',\n        width: '80px'\n      },\n      style: {\n        maxWidth: '80px',\n        minWidth: '80px',\n        width: '80px'\n      }\n    }, {\n      dataField: 'status',\n      text: 'Estado',\n      sort: true,\n      formatter: this.statusFormatter,\n      // formatter: (cell: string) => (this.statusText[cell]),\n      headerClasses: 'middle pointer',\n      headerStyle: {\n        maxWidth: '100px',\n        minWidth: '100px',\n        width: '100px'\n      },\n      style: {\n        maxWidth: '100px',\n        minWidth: '100px',\n        width: '100px'\n      },\n      classes: 'middle-center'\n      // classes: (cell: any) => {\n      //   return `middle-center ${this.classStatus.hasOwnProperty(cell) ? this.classStatus[cell] : ''}`;\n      // }\n    }, {\n      dataField: 'option',\n      text: '',\n      formatter: this.optionsFormatter,\n      headerClasses: 'middle hidden-xs hidden-sm',\n      classes: () => {\n        return `middle-center hidden-xs hidden-sm`;\n      },\n      headerStyle: {\n        maxWidth: '150px',\n        minWidth: '150px',\n        width: '150px'\n      },\n      style: {\n        maxWidth: '150px',\n        minWidth: '150px',\n        width: '150px'\n      }\n    }];\n  }\n\n  public componentWillMount(): void {\n    // get data\n    const {id} = this.props.match.params;\n    this.props.getInventoryDetailAction(id, false);\n    // add listeners\n    window.addEventListener('resize', this.resizeCharts, false);\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {token: (window.user as any).token}\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {room: `inventory-detail-${id}`});\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update && (window.user.venuesAccess as string[]).includes(data.venue)) {\n        this.props.getInventoryDetailAction(id, true);\n        if (data.title) {\n          const status: any = {\n            found: 'success',\n            leftover: 'warning',\n            reported: 'grey'\n          };\n          (($ as any).toast as any)({\n            heading: data.title,\n            text: data.text,\n            position: 'top-right',\n            loaderBg: '#e2e2e2',\n            icon: status[data.status],\n            hideAfter: 5000,\n            stack: 6\n          });\n        }\n      }\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // remove listeners\n    window.removeEventListener('resize', this.resizeCharts, false);\n    // cancel request if component is inmounted\n    if (this.props.inventories.source) {\n      this.props.inventories.source.cancel('Operation canceled by the user.');\n    }\n    if (this.state.source) {\n      (this.state.source as any).cancel('Operation canceled by the user.');\n    }\n    const {id} = this.props.match.params;\n    this.socket.emit('leave', {room: `inventory-detail-${id}`});\n    this.socket.disconnect();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    const $venuesDetail = document.getElementById('chart-venues-detail') as HTMLDivElement;\n    const $brandDetail = document.getElementById('chart-brand-detail') as HTMLDivElement;\n    this.venuesDetailChart = echarts.init($venuesDetail);\n    this.brandDetailChart = echarts.init($brandDetail);\n    window.scrollTo(0, 0);\n  }\n\n  public componentDidUpdate(prevProps: IPropsType): void {\n    const {loadingDetail, detailByVenue, detailByBrand} = this.props.inventories;\n    // style react boostrap table\n    $('.react-bootstrap-table-pagination').css({padding: '3px 15px'});\n    $('.react-bootstrap-table-pagination div').removeClass('col-xs-6').addClass('col-xs-12').css({padding: '3px 15px'});\n    $('.react-bootstrap-table-pagination div:last-child').removeClass('text-right').addClass('text-right');\n    $('#pageDropDown').removeClass('btn-sm').addClass('btn-sm');\n    $('.bs-searchbox input').removeClass('input-sm').addClass('input-sm');\n    $('.pagination').removeClass('pagination-sm').addClass('pagination-sm').css({margin: 0});\n    const {setCharts} = this.state;\n    if (!loadingDetail && !setCharts) {\n      this.updateVenueChart(detailByVenue, false);\n      this.updateBrandChart(detailByBrand, false);\n      this.setState({\n        setCharts: true\n      });\n    } else {\n      this.updateVenueChart(detailByVenue, true);\n      this.updateBrandChart(detailByBrand, true);\n    }\n    $('[data-toggle=\"tooltip\"]').tooltip();\n    if (\n      !this.props.router.location || !prevProps.router.location ||\n      this.props.router.location.key !== prevProps.router.location.key\n    ) {\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public imagesFormatter(cell: string, row: any) {\n    if (row.images && row.images.length) {\n      return (\n        <div className='row'>{\n          row.images.map((image: any, index: number) => (\n            <div key={image._id} className={'col-md-12 images-25 text-center'} style={{ display: index === 0 ? '' : 'none' }}>\n              <a href={decodeURI(image.file.url)}\n                 data-toggle='lightbox'\n                 data-gallery={row._id}\n                 data-title={`${row.vin} / ${row.brand} ${row.denomination} `}\n                 data-footer={`${row.venueFound ? `En ${row.venueFound}` : `En ${row.venue}`} ${row.inventoriedBy ? ` por ${row.inventoriedBy}.` : ''}`}\n              >\n                <button className='btn btn-xs btn-default'>\n                  <i className='fa fa-fw fa-image' /> {row.images.length}\n                </button>\n                {/*<ImageLazyLoad url={decodeURI(image.file.url)} height={'10px'} maxHeight={'35px'} maxWidth={'35px'} small={true}/>*/}\n              </a>\n            </div>\n          ))\n        }</div>\n      );\n    }\n    return null;\n  }\n\n  private openFileManager(car: any): void {\n    const {inventories} = this.props;\n    setTimeout(() => {\n      this.props.loadDataAction(\n        `Archivos de ${car.vin}`,\n        <InventoryFileManager\n          inventories={inventories}\n          inventoryCardId={car._id}\n          socket={this.socket}\n        />\n      );\n    }, 200);\n  }\n\n  public filesFormatter(cell: string, row: any) {\n    return (\n      <div className='row'>\n        <div className={'col-md-12 images-25 text-center'}>\n          <button className='btn btn-xs btn-default' onClick={() => this.openFileManager(row)}>\n            <i className='fa fa-fw fa-cloud-upload' /> {row.files?.length }\n          </button>\n        </div>\n      </div>\n    );\n  }\n\n  public brandFormatter(cell: any, row: any) {\n    return (\n      <React.Fragment>\n        {\n          row.venue && row.venueFound && row.venueFound !== '-' && row.venue !== row.venueFound ?\n            <React.Fragment>\n              <i\n                data-toggle=\"tooltip\"\n                data-placement=\"top\"\n                title=\"Este vehículo no fue encontrado en la sucursal esperada.\"\n                className=\"fa fa-warning text-yellow pointer\"\n              /> {` `}\n            </React.Fragment>\n            : null\n        }\n            <React.Fragment>\n              {row.patent && row.patent.length ?\n              <CopyText value={row.patent}><strong>{row.patent}</strong></CopyText> : null }&nbsp;\n              {row.vin && row.vin.length ?\n                <CopyText value={row.vin} className={row.patent && row.patent.length ? 'text-muted text-sm' : ''}>{row.vin}</CopyText> : null }\n            </React.Fragment>\n        <br/>\n        <span className=\"text-muted text-sm\">{cell} / {row.denomination}</span>\n        {\n          row.internalNumber ? <React.Fragment><br/><span className=\"text-muted text-sm\">{row.internalNumber}</span></React.Fragment> : null\n        }\n        {\n          row.color ?\n            <React.Fragment><br/>\n              <span className=\"text-muted text-sm\">{row.color}</span>\n            </React.Fragment> : null\n        }\n        <div className=\"visible-xs\">\n          {this.labelFormatter(cell, row)}\n        </div>\n      </React.Fragment>\n    );\n  }\n\n  public selectedFormatter(cell: any, row: any) {\n    return (\n      <Checkbox\n        active={cell}\n        action={() => this.props.inventoryDetailChangeSelected(row._id)}\n        classes=\"icheck-in-checkbox\"\n        style={{margin: '5px', marginTop: '5px'}}\n      />\n    );\n  }\n\n  public statusFormatter(cell: CarStatusType) {\n    const {inventorySettings} = this.props.inventories;\n    const className = `${cell}Class` as CarStatusType;\n    return (\n      <span\n        className={`label label-${inventorySettings.hasOwnProperty(className) ? inventorySettings[className] : ''}`}\n        style={{\n          padding: '5px 10px'\n        }}\n      >\n        {inventorySettings.hasOwnProperty(cell) ? inventorySettings[cell] : cell}\n        </span>\n    );\n  }\n\n  public optionsFormatter(cell: any, row: any) {\n    const {labels} = this.props.inventories;\n    const {id} = this.props.match.params;\n    const newLabels = [...labels];\n    if (hasPermission(window.user, 'deleteReported')) {\n      newLabels.push({\n        _id: 'deleted',\n        name: 'Eliminar vehículo',\n        description: '',\n        sendTo: 'deleted',\n        requireCustomText: false,\n        isExhibition: false,\n        affected: ['reported'],\n        color: '',\n        active: true\n      });\n    }\n    const options = newLabels.filter((label) => {\n      return label.affected.includes(row.status);\n    });\n    if (options.length) {\n      return (\n        <div className=\"btn-group btn-group-sm\" style={{\n          marginLeft: '5px'\n        }}>\n          <button type=\"button\" className=\"btn btn-default\">\n            <i className=\"fa fa-fw fa-cogs\"/> Etiqueta\n          </button>\n          <button type=\"button\" className=\"btn btn-default dropdown-toggle\" data-toggle=\"dropdown\">\n            <span className=\"caret\"/>\n            <span className=\"sr-only\">Toggle Dropdown</span>\n          </button>\n          <ul className=\"dropdown-menu dropdown-menu-right dropdown-menu-scrollable\" role=\"menu\">\n            {\n              options.map((option) => {\n                return (\n                  <li key={option._id} onClick={() => {\n                    this.props.actionSetLabel(id, row._id, row.carID, option);\n                  }}>\n                    <a href=\"javascript:void(0)\">\n                      <i className={`fa ${this.iconStatus[option.sendTo]}`} />{option.name}\n                    </a>\n                  </li>\n                );\n              })\n            }\n          </ul>\n        </div>\n      );\n    }\n    return null;\n  }\n\n  public commentFormatter(cell: any, row: any) {\n    if (row.comments && row.comments.length) {\n      return (\n        <React.Fragment>\n          {maxText(row.comments[row.comments.length - 1].comment, 20)}<br />\n          <button className={'btn btn-default btn-xs'} onClick={() => this.carComments(row)}>\n            {row.comments.length} <i className={'fa fa-comments'}/>\n          </button>\n        </React.Fragment>\n      );\n    } else {\n      return (\n        <button className={'btn btn-default btn-xs'} onClick={() => this.carComments(row)}>\n          Agregar <i className={'fa fa-comments'}/>\n        </button>\n      );\n    }\n  }\n\n  public labelFormatter(cell: any, row: any) {\n    if (row.label) {\n      const sendTo = row.label.sendTo;\n      const {inventorySettings} = this.props.inventories;\n      const className = `${sendTo}Class` as CarStatusType;\n      return (\n        <React.Fragment>\n          <span\n            className={\n              `label label-${inventorySettings.hasOwnProperty(className) ? inventorySettings[className] : ''}`\n            }\n          >\n            <i className={`fa fa-fw ${this.iconStatus[sendTo]}`}/>\n            {row.label.name}\n          </span>\n          {/*<span*/}\n          {/*   data-toggle=\"tooltip\"*/}\n          {/*   data-placement=\"top\"*/}\n          {/*   title={row.labelText}*/}\n          {/* >*/}\n          {/*   Ver más*/}\n          {/* </span>*/}\n          {\n            row.label.requireCustomText ?\n              <React.Fragment>\n                <p\n                  style={{\n                    paddingTop: '5px',\n                    marginBottom: 0\n                  }}\n                  className={'text-sm'}\n                >\n                  <strong>Datos adicionales:</strong>\n                </p>\n                <p\n                  className={'text-sm text-muted'}\n                >\n                  {row.labelText}\n                </p>\n              </React.Fragment>:\n              ''\n          }\n        </React.Fragment>\n      );\n    } else {\n      return null;\n    }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      loadingDetail,\n      summary,\n      detail,\n      carsTable,\n      filter,\n      selectedItems,\n      cardTypes,\n      cardProperties,\n      inventorySettings\n    } = this.props.inventories;\n    const { tab, source } = this.state;\n    const selected = Object.keys(selectedItems);\n    const {\n      percentagePending,\n      percentageFound,\n      percentageLeftover,\n      percentageReported,\n      percentageMissing\n    } = this.calculateDetails(summary.results);\n\n    const showDownloadFile = isDercoDercocenter(this.props.inventories.detail) || moment().subtract(1, 'months').isSameOrBefore(summary.createdAt);\n\n    return (\n      <AppContainer title={summary.name} cMenu=\"2\" cSubMenu=\"2.1\" cAction={tab === 'summary' ? 'Consolidado' : 'Detalle'}>\n        <section className=\"content\">\n          <Row>\n            <div className=\"col-md-12 col-lg-12\">\n              <div className=\"box box-solid\">\n                <ul className=\"nav nav-pills nav-justified\">\n                  <li className={tab === 'summary' ? 'active' : ''}>\n                    <a\n                      href=\"javascript:void(0);\"\n                      className={tab === 'summary' ? 'background-transition' : ''}\n                      style={{borderTop: '0', marginBottom: '0'}}\n                      onClick={() => this.changeTab('summary')}\n                    >Consolidado</a>\n                  </li>\n                  <li className={tab === 'detail' ? 'active' : ''}>\n                    <a\n                      className={tab === 'detail' ? 'background-transition' : ''}\n                      href=\"javascript:void(0);\"\n                      style={{borderTop: '0', marginBottom: '0'}}\n                      onClick={() => this.changeTab('detail')}\n                    >Detalle</a>\n                  </li>\n                </ul>\n              </div>\n            </div>\n          </Row>\n          <Row style={{display: tab === 'summary' ? 'block' : 'none'}}>\n            <div className=\"col-md-12 col-lg-12\">\n              <div className=\"box box-default\">\n                <div className=\"box-header with-border\">\n                  <Row className=\"vertical-line-mobile\">\n                    <div className=\"col-md-4 col-lg-3\">\n                      <i className=\"fa fa-fw fa-user text-primary\"/>\n                      <strong>\n                        {\n                          !loadingDetail && summary && summary.createdBy ?\n                            summary.createdBy.fullName\n                            : '-'\n                        }\n                      </strong>\n\n                    </div>\n                    <div className=\"col-md-4 col-lg-3\">\n                      <i className=\"fa fa-fw fa-clock-o text-green\"/>\n                      <strong>{!loadingDetail && summary && summary.createdAt ? moment(summary.createdAt).format('LLL') : '-'}</strong>\n                    </div>\n                    <div className=\"col-md-4 col-lg-3\">\n                      <i className=\"fa fa-fw fa-clock-o text-red\"/>\n                      <strong>{!loadingDetail && summary && summary.finalizedAt ? moment(summary.finalizedAt).format('LLL') : '-'}</strong>\n                    </div>\n                    <div className=\"col-md-12 col-lg-3 text-right\">\n                      {!loadingDetail ? this.labelStatus(detail.status) : null}\n                    </div>\n                  </Row>\n                </div>\n                {\n                  loadingDetail &&\n                  <div className=\"overlay\">\n                    <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                  </div>\n                }\n              </div>\n            </div>\n          </Row>\n          <Row style={{display: tab === 'summary' ? 'block' : 'none'}}>\n            <div className=\"col-md-4 col-lg-4 pointer\" onClick={() => this.sendToDetailFilteredByState('found')}>\n              <div className={`info-box bg-${inventorySettings.foundClass}`}>\n                <span className=\"info-box-icon\"><i className=\"fa fa-check\" /></span>\n                <div className=\"info-box-content\">\n                  <span className=\"info-box-text\">{inventorySettings.found}</span>\n                  <span className=\"info-box-number count\">\n                    {!loadingDetail && summary.results ? summary.results.found : <i className=\"fa fa-spinner fa-spin\"/>}\n                  </span>\n                  <div className=\"progress\">\n                    <div className=\"progress-bar\" style={{\n                      width: `${!loadingDetail ? percentageFound : 0}%`,\n                      transition: loadingDetail ? 'none' : 'width .6s ease'\n                    }} />\n                  </div>\n                  <span className=\"progress-description\">\n                    {!loadingDetail ? `${percentageFound.toFixed(1)}% ${inventorySettings.found.toLowerCase()}.` : null}\n                  </span>\n                </div>\n              </div>\n            </div>\n            <div className=\"col-md-4 col-lg-4 pointer\" onClick={() => this.sendToDetailFilteredByState('leftover')}>\n              <div className={`info-box bg-${inventorySettings.leftoverClass}`}>\n                <span className=\"info-box-icon\"><i className=\"fa fa-arrow-up\" /></span>\n                <div className=\"info-box-content\">\n                  <span className=\"info-box-text\">{inventorySettings.leftover}</span>\n                  <span className=\"info-box-number count\">\n                    {!loadingDetail && summary.results ? summary.results.leftover : <i className=\"fa fa-spinner fa-spin\"/>}\n                  </span>\n                  <div className=\"progress\">\n                    <div className=\"progress-bar\" style={{\n                      width: `${!loadingDetail ? percentageLeftover : 0}%`,\n                      transition: loadingDetail ? 'none' : 'width .6s ease'\n                    }}/>\n                  </div>\n                  <span className=\"progress-description\">\n                    {!loadingDetail ? `${percentageLeftover.toFixed(1)}% ${inventorySettings.leftover.toLowerCase()}.` : null}\n                  </span>\n                </div>\n              </div>\n            </div>\n            <div className=\"col-md-4 col-lg-4 pointer\" onClick={() => this.sendToDetailFilteredByState('missing')}>\n              <div className={`info-box bg-${inventorySettings.missingClass}`}>\n                <span className=\"info-box-icon\">\n                  <i className=\"fa fa-arrow-down\"/>\n                </span>\n                <div className=\"info-box-content\">\n                  <span className=\"info-box-text\">{inventorySettings.missing}</span>\n                  <span className=\"info-box-number count\">\n                    {!loadingDetail && summary.results ? summary.results.missing : <i className=\"fa fa-spinner fa-spin\"/>}\n                  </span>\n                  <div className=\"progress\">\n                    <div className=\"progress-bar\" style={{\n                      width: `${!loadingDetail ? percentageMissing : 0}%`,\n                      transition: loadingDetail ? 'none' : 'width .6s ease'\n                    }} />\n                  </div>\n                  <span className=\"progress-description\">\n                    {!loadingDetail ? `${percentageMissing.toFixed(1)}% ${inventorySettings.missing.toLowerCase()}.` : null}\n                  </span>\n                </div>\n              </div>\n            </div>\n          </Row>\n          <Row style={{display: tab === 'summary' ? 'block' : 'none'}}>\n            <div className=\"col-md-12 col-lg-12\">\n              <div className=\"box box-primary\">\n                <div className=\"box-header with-border\">\n                  <h3 className=\"box-title\">Detalle de inventario por sucursal</h3>\n                  {\n                    showDownloadFile ?\n                      <div className=\"box-tools pull-right\">\n                        <button\n                          className=\"btn btn-sm btn-primary hidden-xs hidden-sm\"\n                          onClick={() => this.xlsExport(['pending', 'found', 'leftover', 'missing', 'reported'])}\n                        >\n                          <i className=\"fa fa-fw fa-download\" /> Exportar Excel\n                    </button>\n                      </div> : null\n                  }\n                </div>\n                <div className=\"box-body\">\n                  <div id=\"chart-venues-detail\" style={{height: '550px', maxWidth: '100%'}}/>\n                </div>\n                {\n                  loadingDetail &&\n                  <div className=\"overlay\">\n                    <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                  </div>\n                }\n              </div>\n            </div>\n          </Row>\n          <Row style={{display: tab === 'summary' ? 'block' : 'none'}}>\n            <div className=\"col-md-12\">\n              <div className=\"box box-success\">\n                <div className=\"box-header with-border\">\n                  <h3 className=\"box-title\">Detalle de inventario por Marca</h3>\n                  {/*<div className=\"box-tools pull-right\">*/}\n                  {/*</div>*/}\n                </div>\n                <div className=\"box-body\">\n                  <div id=\"chart-brand-detail\" style={{height: '550px', maxWidth: '100%'}}/>\n                </div>\n                {\n                  loadingDetail &&\n                  <div className=\"overlay\">\n                    <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                  </div>\n                }\n              </div>\n            </div>\n          </Row>\n          <Row style={{display: tab === 'detail' ? 'block' : 'none'}}>\n            <div className=\"col-md-6 col-lg-6 pointer\" onClick={() => this.sendToDetailFilteredByState('pending')}>\n              <div className={`info-box bg-${inventorySettings.pendingClass}`}>\n                <span className=\"info-box-icon\"><i className=\"fa fa-clock-o\" /></span>\n                <div className=\"info-box-content\">\n                  <span className=\"info-box-text\">{inventorySettings.pending}</span>\n                  <span className=\"info-box-number count\">\n                    {!loadingDetail && summary.results ? summary.results.pending : <i className=\"fa fa-spinner fa-spin\"/>}\n                  </span>\n                  <div className=\"progress\">\n                    <div className=\"progress-bar\" style={{\n                      width: `${!loadingDetail ? percentagePending : 0}%`,\n                      transition: loadingDetail ? 'none' : 'width .6s ease'\n                    }} />\n                  </div>\n                  <span className=\"progress-description\">\n                    {!loadingDetail ? `${percentagePending.toFixed(1)}% ${inventorySettings.pending.toLowerCase()}.` : null}\n                  </span>\n                </div>\n              </div>\n            </div>\n            <div className=\"col-md-6 col-lg-6 pointer\" onClick={() => this.sendToDetailFilteredByState('reported')}>\n              <div className={`info-box bg-${inventorySettings.reportedClass}`}>\n                <span className=\"info-box-icon\"><i className=\"fa fa-exclamation\" /></span>\n                <div className=\"info-box-content\">\n                  <span className=\"info-box-text\">{inventorySettings.reported}</span>\n                  <span className=\"info-box-number count\">\n                    {!loadingDetail && summary.results ? summary.results.reported : <i className=\"fa fa-spinner fa-spin\"/>}\n                  </span>\n                  <div className=\"progress\">\n                    <div className=\"progress-bar\" style={{\n                      width: `${!loadingDetail ? percentageReported : 0}%`,\n                      transition: loadingDetail ? 'none' : 'width .6s ease'\n                    }} />\n                  </div>\n                  <span className=\"progress-description\">\n                    {!loadingDetail ? `${percentageReported.toFixed(1)}% ${inventorySettings.reported.toLowerCase()}.` : null}\n                  </span>\n                </div>\n              </div>\n            </div>\n          </Row>\n          <Row style={{display: tab === 'detail' ? 'block' : 'none'}}>\n            <div className=\"col-md-12\">\n              <div className=\"box box-info\">\n                <div className=\"box-header with-border\">\n                  <h3 className=\"box-title\">\n                    Detalle de inventario {selected.length ? <small className=\"hidden-sm hidden-xs text-primary\">{selected.length} {selected.length > 1 ? 'seleccionados' : 'seleccionado'}.</small> : <small>{carsTable.length}</small>}\n                  </h3>\n                  <div className=\"box-tools pull-right\">\n                    {\n                      showDownloadFile ?\n                        <button\n                          className=\"btn btn-sm btn-primary hidden-xs hidden-sm\"\n                          onClick={() => this.xlsExport(['pending', 'found', 'leftover', 'missing', 'reported'])}\n                        >\n                          <i className=\"fa fa-fw fa-download\" /> Exportar Excel\n                    </button>\n                        : null\n                    }\n                    <div className=\"btn-group btn-group-sm hidden-xs hidden-sm\" style={{marginLeft: '5px'}}>\n                      <button type=\"button\" className=\"btn btn-success\"><i className=\"fa fa-fw fa-cogs\"/> Acciones</button>\n                      <button type=\"button\" className=\"btn btn-success dropdown-toggle\" data-toggle=\"dropdown\">\n                        <span className=\"caret\"/>\n                        <span className=\"sr-only\">Toggle Dropdown</span>\n                      </button>\n                      <ul className=\"dropdown-menu\" role=\"menu\">\n                        <li onClick={() => this.downloadImages({all: true})}>\n                          <a href=\"javascript:void(0)\"><i className=\"fa fa-fw fa-download\"/> Descargar todas las imágenes</a>\n                        </li>\n                        <li onClick={() => this.downloadImages({})}>\n                          <a href=\"javascript:void(0)\"><i className=\"fa fa-fw fa-download\"/> Descargar imágenes seleccionadas</a>\n                        </li>\n                      </ul>\n                    </div>\n                  </div>\n                </div>\n                <div className=\"box-body no-padding\" id=\"table-detail-inventory\" style={{\n                  display: loadingDetail ? 'none' : ''\n                }}>\n                  <Row style={{margin: '5px 0'}}>\n                    <div className=\"col-md-12\">\n                      <div className=\"form-group\">\n                        <label htmlFor=\"cars\" className=\"control-label\">Unidades</label>\n                        <input\n                          type=\"text\"\n                          className=\"form-control\"\n                          id=\"cars\"\n                          placeholder=\"Busca por VIN, patente, marca o modelo.\"\n                          onChange={this.handleChangeSearchText}\n                        />\n                      </div>\n                    </div>\n                    <div className=\"col-md-3\">\n                      <div className=\"form-group\">\n                        <label htmlFor=\"venues\" className=\"control-label\">Sucursales</label>\n                        <BootstrapSelect\n                          noneSelectedText=\"Todas\"\n                          displayItems={2}\n                          selectedText=\"sucursales seleccionadas.\"\n                          selected={filter.venues}\n                          allOption={true}\n                          selectAll={this.filterAllVenues}\n                          options={detail.venues.map((venue: any) => ({\n                            value: venue._id,\n                            text: venue.name\n                          }))}\n                          onClick={this.filterVenues}\n                        />\n                      </div>\n                    </div>\n                    <div className=\"col-md-3\">\n                      <div className=\"form-group\">\n                        <label htmlFor=\"states\" className=\"control-label\">Estados</label>\n                        <BootstrapSelect\n                          noneSelectedText=\"Todos\"\n                          displayItems={4}\n                          selectedText=\"estados seleccionados.\"\n                          separator=\" - \"\n                          options={Object\n                            .keys(this.statusText)\n                            .map((status: CarStatusType ) => ({\n                              value: status,\n                              text: inventorySettings[status],\n                              className: `label label-${inventorySettings[`${status}Class` as CarStatusType]}`\n                            }))}\n                          selected={filter.states}\n                          onClick={this.filterStatus}\n                        />\n                      </div>\n                    </div>\n                    {\n                      cardTypes.length ?\n                        <div className=\"col-md-3\">\n                          <div className=\"form-group\">\n                            <label htmlFor=\"states\" className=\"control-label\">Tipo</label>\n                            <BootstrapSelect\n                              noneSelectedText=\"Todos\"\n                              displayItems={4}\n                              selectedText=\"estados seleccionados.\"\n                              separator=\" - \"\n                              options={cardTypes\n                                .map((name) => ({\n                                  value: name,\n                                  text: name\n                                }))}\n                              selected={[filter.type]}\n                              autoClouse={true}\n                              onClick={this.filterType}\n                            />\n                          </div>\n                        </div>\n                        : null\n                    }\n                    {\n                      cardProperties.length ?\n                        <div className=\"col-md-3\">\n                          <div className=\"form-group\">\n                            <label htmlFor=\"states\" className=\"control-label\">Propiedad</label>\n                            <BootstrapSelect\n                              noneSelectedText=\"Todos\"\n                              displayItems={4}\n                              selectedText=\"estados seleccionados.\"\n                              separator=\" - \"\n                              options={cardProperties\n                                .map((name) => ({\n                                  value: name,\n                                  text: name\n                                }))}\n                              selected={[filter.property]}\n                              autoClouse={true}\n                              onClick={this.filterProperty}\n                            />\n                          </div>\n                        </div>\n                        : null\n                    }\n                  </Row>\n                  <Row style={{margin: '5px 0'}}>\n                    <div className=\"col-md-3 col-md-push-9 text-right\" style={{marginBottom: '10px'}}>\n                      <button\n                        className=\"btn btn-default btn-sm\"\n                        onClick={this.clearFilter}\n                        style={{paddingLeft: '5px'}}\n                        disabled={\n                          !(filter.states.length || filter.text.length || filter.venues.length || filter.type.length || filter.property.length)}\n                      >\n                        <i className=\"fa fa-fw fa-eraser\"/> Limpiar\n                      </button>\n                    </div>\n                  </Row>\n                  {\n                    this.state.downloadImages.downloading ?\n                      <Row>\n                        <div className=\"col-md-12\" style={{padding: '24px 25vh'}}>\n                          <div className=\"progress progress-xs progress-striped active\">\n                            <div\n                              className=\"progress-bar progress-bar-success\"\n                              style={{width: `${this.state.downloadImages.progress}%`}}/>\n                          </div>\n                          {\n                            this.state.downloadImages.downloading && this.state.downloadImages.sizeFile === 0 ?\n                              <div className=\"text-center\">\n                                Estamos preparando las imágenes.\n                                <button\n                                  className=\"btn btn-sm btn-danger\"\n                                  style={{marginLeft: '10px'}}\n                                  onClick={() => (source as any).cancel('Operation canceled by the user.')}\n                                >\n                                  Cancelar\n                                </button>\n                              </div>\n                            : <div className=\"text-center\">\n                                Descargando imágenes {this.state.downloadImages.progress}%\n                                <button\n                                  className=\"btn btn-sm btn-danger\"\n                                  style={{marginLeft: '10px'}}\n                                  onClick={() => (source as any).cancel('Operation canceled by the user.')}\n                                >\n                                  Cancelar\n                                </button>\n                            </div>\n                          }\n                        </div>\n                      </Row> : null\n                  }\n                  <Row>\n                    <div className=\"col-md-12\">\n                      {\n                        !loadingDetail && carsTable.length ?\n                          <BootstrapTable\n                            keyField=\"_id\"\n                            data={carsTable}\n                            columns={this.columns}\n                            filter={filterFactory()}\n                            pagination={paginationFactory(this.paginationOption)}\n                            defaultSorted={this.defaultSorted}\n                          /> : !loadingDetail ? <p className=\"text-center text-muted\">\n                            <ImageLazyLoad\n                              url=\"/images/not_found.png\"\n                              height={'200px'}\n                              style={{\n                                opacity: 0.5,\n                                maxHeight: '200px',\n                                marginBottom: '10px'\n                              }}\n                              replaceLoading={<i\n                                className={'fa fa-2x fa-circle-o-notch text-primary fa-spin'}\n                                style={{padding: '30px'}}\n                              /> }\n                            /><br/>\n                            <strong>No hay información para mostrar</strong>\n                          </p> : null\n                      }\n                    </div>\n                  </Row>\n                </div>\n                {\n                  loadingDetail &&\n                  <div className=\"overlay\">\n                    <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                  </div>\n                }\n              </div>\n            </div>\n          </Row>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private downloadImages({all}: { all?: boolean }) {\n    const {id} = this.props.match.params;\n    const {selectedItems, summary, carsTable} = this.props.inventories;\n    let ids: string[];\n    if (all) {\n      ids = carsTable\n        .filter((car) => car.images.length)\n        .map((car) => car._id);\n    } else {\n      ids = Object.keys(selectedItems);\n    }\n\n    const countImages: number = carsTable\n      .filter((car) => ids.includes(car._id))\n      .reduce((a: any, b: any) => {\n        return a + b.images.length;\n      }, 0);\n\n    if (countImages > 0) {\n      this.setState({\n        downloadImages: {\n          downloading: true,\n          progress: 0,\n          sizeFile: 0,\n          loaded: 0\n        }\n      });\n      const api: ApiService = new ApiService();\n      const instance = api.getInstance();\n      instance.defaults.responseType = 'blob';\n      instance.defaults.timeout = 7200000;\n      const source = api.getSource();\n      this.setState({\n        source\n      });\n      instance\n        .post(\n          `/api/inventory/${id}/download-images/`, {\n            cars: ids\n          }, {\n            cancelToken: source.token,\n            onDownloadProgress: (progressEvent) => {\n              const sizeFile = parseInt(progressEvent.target.getResponseHeader('size'), 10);\n              const {loaded} = progressEvent;\n              if (sizeFile) {\n                const progress = Math.round((progressEvent.loaded * 100) / sizeFile);\n                this.setState({\n                  downloadImages: {\n                    downloading: true,\n                    progress,\n                    sizeFile,\n                    loaded\n                  }\n                });\n              }\n            }\n          }\n        )\n        .then((response) => {\n          const blob = new Blob([response.data], {\n            type: 'application/zip'\n          });\n          const fileName = `${summary.name}.zip`;\n          if (typeof window.navigator.msSaveBlob !== 'undefined') {\n            // IE workaround for \"HTML7007: One or more blob URLs were\n            // revoked by closing the blob for which they were created.\n            // These URLs will no longer resolve as the data backing\n            // the URL has been freed.\"\n            window.navigator.msSaveBlob(blob, fileName);\n          } else {\n            const blobURL = URL.createObjectURL(blob);\n            const tempLink = document.createElement('a');\n            tempLink.style.display = 'none';\n            tempLink.href = blobURL;\n            tempLink.setAttribute('download', fileName);\n            // Safari thinks _blank anchor are pop ups. We only want to set _blank\n            // target if the browser does not support the HTML5 download attribute.\n            // This allows you to download files in desktop safari if pop up blocking\n            // is enabled.\n            if (typeof tempLink.download === 'undefined') {\n              tempLink.setAttribute('target', '_blank');\n            }\n            document.body.appendChild(tempLink);\n            tempLink.click();\n            document.body.removeChild(tempLink);\n            URL.revokeObjectURL(blobURL);\n          }\n          this.setState({\n            downloadImages: {\n              ...this.state.downloadImages,\n              downloading: false,\n              progress: 100,\n              sizeFile: 0,\n              loaded: 0\n            }\n          });\n        })\n        .catch((err) => {\n          if (!Axios.isCancel(err)) {\n            Raven.captureException(JSON.stringify({\n              error: JSON.stringify(err),\n              ...this.state.downloadImages\n            }));\n            swal!('Descargar imágenes', 'ha ocurrido un error descargando las imágenes.', 'error');\n          }\n          this.setState({\n            downloadImages: {\n              downloading: false,\n              progress: 0,\n              sizeFile: 0,\n              loaded: 0\n            }\n          });\n        });\n    } else {\n      if (all) {\n        swal!('Descargar imágenes', 'No hay imágenes para dercargar.', 'error');\n      } else {\n        swal!('Descargar imágenes', 'No has seleccionado unidades que contengan imágenes.', 'error');\n      }\n    }\n  }\n\n  private filterVenues(value: any) {\n    const {filter} = this.props.inventories;\n    this.props.inventoryDetailChangeFilter({\n      ...filter,\n      venues: filter.venues.includes(value)\n        ? filter.venues.filter((venue) => venue !== value)\n        : [value, ...filter.venues]\n    });\n  }\n\n  private filterAllVenues(value: boolean) {\n    const {filter, detail} = this.props.inventories;\n    this.props.inventoryDetailChangeFilter({\n      ...filter,\n      venues: value ? detail.venues.map((venue: any) => venue._id) : []\n    });\n  }\n\n  private filterStatus(value: any) {\n    const {filter} = this.props.inventories;\n    this.props.inventoryDetailChangeFilter({\n      ...filter,\n      states: filter.states.includes(value)\n        ? filter.states.filter((state) => state !== value)\n        : [value, ...filter.states]\n    });\n  }\n\n  private filterType(value: string) {\n    const {filter} = this.props.inventories;\n    this.props.inventoryDetailChangeFilter({\n      ...filter,\n      type: filter.type !== value ? value : ''\n    });\n  }\n\n  private filterProperty(value: string) {\n    const {filter} = this.props.inventories;\n    this.props.inventoryDetailChangeFilter({\n      ...filter,\n      property: filter.property !== value ? value : ''\n    });\n  }\n\n  private sendToDetailFilteredByState(state: string) {\n    this.props.inventoryDetailChangeFilter({\n      text: '',\n      type: '',\n      property: '',\n      venues: [],\n      states: [state]\n    });\n    $('#cars').val('');\n    this.changeTab('detail');\n    setTimeout(() => {\n      goToSection('#table-detail-inventory');\n    }, 100);\n  }\n\n  private sendToDetailFilteredByVenue(venue: string) {\n    this.props.inventoryDetailChangeFilter({\n      text: '',\n      type: '',\n      property: '',\n      venues: [venue],\n      states: []\n    });\n    $('#cars').val('');\n    this.changeTab('detail');\n    setTimeout(() => {\n      goToSection('#table-detail-inventory');\n    }, 100);\n  }\n\n  private clearFilter(): void {\n    this.props.inventoryDetailChangeFilter({\n      venues: [],\n      states: [],\n      property: '',\n      type: '',\n      text: ''\n    });\n    $('#cars').val('');\n  }\n\n  private handleChangeSearchText(e: React.ChangeEvent<HTMLInputElement>): void {\n    e.preventDefault();\n    const value = e.target.value.trim();\n    const {filter} = this.props.inventories;\n    this.props.inventoryDetailChangeFilterText({\n      ...filter,\n      text: value ? e.target.value : ''\n    });\n  }\n\n  private changeTab(name: string): void {\n    const {id} = this.props.match.params;\n    if (name === 'detail') {\n      this.props.history.replace(`/inventory/${id}/detail/`);\n    } else {\n      this.props.history.replace(`/inventory/${id}/`);\n    }\n    this.setState({\n      tab: name\n    }, () => {\n      this.resizeCharts();\n    });\n  }\n\n  private selectedHeaderFormatter(): React.ReactElement<IPropsType> | null  {\n    return (\n      <React.Fragment>\n        <Checkbox\n          active={false}\n          action={undefined}\n          classes=\"icheck-in-checkbox\"\n          style={{margin: '5px', marginTop: '5px'}}\n        />\n        <i className=\"fa fa-order\" />\n      </React.Fragment>\n    );\n  }\n\n  private calculateDetails(results: IInventorySummaryResult | undefined) {\n    const {loadingDetail} = this.props.inventories;\n    if (!loadingDetail) {\n      const totalCars = results ? results.missing + results.found + results.pending + results.leftover + results.reported : 0;\n      return {\n        totalCars,\n        percentagePending: results && results.pending ? (100 / totalCars) * results.pending : 0,\n        percentageFound: results && results.found ? (100 / totalCars) * results.found : 0,\n        percentageLeftover: results && results.leftover ? (100 / totalCars) * results.leftover : 0,\n        percentageMissing: results && results.missing ? (100 / totalCars) * results.missing : 0,\n        percentageReported: results && results.reported ? (100 / totalCars) * results.reported : 0\n      };\n    }\n    return {\n      totalCars: 0,\n      percentagePending: 0,\n      percentageFound: 0,\n      percentageLeftover: 0,\n      percentageMissing: 0,\n      percentageReported: 0\n    };\n  }\n\n  private carComments(inventoryCar: IInventoryCar): void {\n    const { inventories} = this.props;\n    this.props.updateInventoryCarAction(inventoryCar);\n    setTimeout(() => {\n      this.props.loadDataAction(\n        `Comentarios`,\n        <InventoryCarComments\n          inventories={inventories}\n          socket={this.socket}\n          addCommentAction={addCommentAction}\n          sendCommentAction={sendCommentAction}\n        />\n      );\n    }, 200);\n  }\n\n  private xlsExport(status: string[]) {\n    this.trackClick('Exportar');\n    const {detail} = this.props.inventories;\n    const data: any = [];\n    const {inventorySettings} = this.props.inventories;\n    // Order data\n    if (detail && detail.cars && detail.cars.length) {\n      for (const car of detail.cars) {\n        if (status.includes(car.status) && car.car?.vin) {\n          data.push({\n            VIN: car.car.vin,\n            Patente: car.car.patent && car.car.patent.length ? car.car.patent : '-',\n            ['Nº interno']: car.car.internalNumber && car.car.internalNumber.length ? car.car.internalNumber : '-',\n            Marca: car.car.brand && car.car.brand.length ? car.car.brand : '-',\n            ['Denominación']: car.car.denomination && car.car.denomination.length ? car.car.denomination : '-',\n            Color: car.car.color && car.car.color.length ? car.car.color : '-',\n            Sucursal: car.venue && car.venue.hasOwnProperty('name') ? car.venue.name : '-',\n            Tipo: car.car.type && car.car.type ? car.car.type : '-',\n            Propiedad: car.car.property && car.car.property ? car.car.property : '-',\n            ['Sucursal encontrado']: car.venueFound && car.venueFound.hasOwnProperty('name') ? car.venueFound.name : '-',\n            ['Encontrado por']: car.inventoriedBy ? `${car.inventoriedBy.firstName} ${car.inventoriedBy.lastName}` : '-',\n            ['Comentario']: car.comments && car.comments.length ? `${car.comments[car.comments.length - 1].comment}` : '-',\n            ['Etiqueta']: car.label ? car.label.name : '-',\n            ['Comentario etiqueta']: car.label && car.label.requireCustomText && car.labelText ? car.labelText : '-',\n            ['Imágenes']: car.images.length ? car.images.length : '-',\n            // ['Imágenes']: car.images.length ? car.images.map((image: any) => `${image.file.url}`).join('\\n') : '-',\n            Status: inventorySettings.hasOwnProperty(car.status) ? inventorySettings[car.status as CarStatusType] : '-'\n          });\n        }\n      }\n    }\n    /* make the worksheet */\n    const ws = XLSX.utils.json_to_sheet(data);\n    /* add to workbook */\n    const wb = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(wb, ws, 'Detalle');\n    /* generate an XLSX file */\n    XLSX.writeFile(wb, `Detalle ${detail.name}.xlsx`);\n  }\n\n  private updateVenueChart(detailByVenue: IDetailByVenue[], update?: boolean) {\n    const {loadingDetail, detail, inventorySettings} = this.props.inventories;\n    const venuesNames: string[] = [];\n    const venuesFound: any[] = [];\n    const venuesPending: any[] = [];\n    const venuesLeftover: any[] = [];\n    const venuesReported: any[] = [];\n    const venuesMissing: any[] = [];\n    // detailByVenue.sort((a, b) => {\n    //   return a.name.localeCompare(b.name);\n    // });\n    if (detail.status === 'inProcess') {\n      detailByVenue.sort((a: any, b: any) => {\n        return b.results.pending - a.results.pending;\n      });\n    } else {\n      detailByVenue.sort((a: any, b: any) => {\n        return b.results.pending - a.results.pending;\n      });\n      detailByVenue.sort((a: any, b: any) => {\n        const suma = a.results.leftover + a.results.missing + a.results.reported;\n        const sumb = b.results.leftover + b.results.missing + b.results.reported;\n        return sumb - suma;\n      });\n    }\n\n    for (const venue of detailByVenue) {\n      venuesNames.push(venue.name);\n      venuesFound.push(venue.results && venue.results.found > 0 ? venue.results.found : null);\n      venuesPending.push(venue.results && venue.results.pending > 0 ? venue.results.pending : null);\n      venuesLeftover.push(venue.results && venue.results.leftover > 0 ? venue.results.leftover : null);\n      venuesReported.push(venue.results && venue.results.reported > 0 ? venue.results.reported : null);\n      venuesMissing.push(venue.results && venue.results.missing > 0 ? venue.results.missing : null);\n    }\n    const optionVenues: echarts.EChartOption = {\n      tooltip: {\n        trigger: 'axis',\n        axisPointer: {\n          type: 'shadow'\n        },\n        formatter: (params: any) => {\n          const colorSpan = (color: any) => `<span style=\"display:inline-block;margin-right:5px;border-radius:10px;width:10px;height:10px;background-color:${color};\"></span>`;\n          let rez = `<span> ${params[0].axisValue}</span>`;\n          // console.log(params); //quite useful for debug\n          let total = 0;\n          params.forEach((item: any) => {\n            // console.log(item); //quite useful for debug\n            const value = item.data ? item.data : 0;\n            const xx = `<br />${item.marker} ${item.seriesName}: ${value}`;\n            total += value;\n            rez = rez + xx;\n          });\n          rez += `<br />${colorSpan('#ffffff')} <strong>Total: ${total}</strong>`;\n          return rez;\n        }\n      },\n      legend: {\n        // x: 'center',\n        bottom: 50,\n        data: [inventorySettings.found, inventorySettings.leftover, inventorySettings.missing, inventorySettings.pending, inventorySettings.reported]\n      },\n      xAxis: {\n        type: 'category',\n        data: venuesNames,\n        axisLine: {\n          lineStyle: {\n            color: 'rgba(0, 0, 0, 0.5)'\n          }\n        },\n        axisLabel: {\n          rotate: 60,\n          fontSize: 10,\n          formatter: (value: string) => {\n            let text = '';\n            const array = value.split(' ');\n            for (let i = 0; i < array.length; i++) {\n              text += `${array[i]}`;\n              if (i > 0 && i % 2 !== 0) {\n                text += ' \\n';\n              } else {\n                text += ' ';\n              }\n            }\n            return text;\n          }\n        }\n      },\n      yAxis: {\n        minInterval: 1,\n        type: 'value',\n        axisLine: {\n          lineStyle: {\n            color: 'rgba(0, 0, 0, 0.5)'\n          }\n        },\n        splitLine: {\n          show: true,\n          lineStyle: {\n            type: 'dashed',\n            color: 'rgba(150, 150, 150, 0.5)'\n          }\n        }\n      },\n      grid: {\n        top: 30,\n        bottom: 100,\n        // left\n        left: 5,\n        // right\n        right: 10,\n        containLabel: true\n      },\n      color: [inventorySettings.foundColor, inventorySettings.leftoverColor, inventorySettings.missingColor, inventorySettings.pendingColor, inventorySettings.reportedColor],\n      series: [{\n        data: venuesFound,\n        name: inventorySettings.found,\n        type: 'bar',\n        stack: 'cars',\n        barMaxWidth: 100,\n        label: {\n          normal: {\n            ...this.labelOption.normal\n          }\n        },\n        barGap: '0'\n      }, {\n        data: venuesLeftover,\n        name: inventorySettings.leftover,\n        type: 'bar',\n        stack: 'cars',\n        barMaxWidth: 100,\n        label: {\n          normal: {\n            ...this.labelOption.normal\n\n          }\n        },\n        barGap: '0'\n      }, {\n        data: venuesMissing,\n        name: inventorySettings.missing,\n        type: 'bar',\n        stack: 'cars',\n        barMaxWidth: 100,\n        label: {\n          normal: {\n            ...this.labelOption.normal\n          }\n        },\n        barGap: '0'\n      }, {\n        data: venuesPending,\n        name: inventorySettings.pending,\n        type: 'bar',\n        stack: 'cars',\n        barMaxWidth: 100,\n        // barMinHeight: 20,\n        label: {\n          normal: {\n            ...this.labelOption.normal\n          }\n        },\n        barGap: '0'\n      }, {\n        data: venuesReported,\n        name: inventorySettings.reported,\n        type: 'bar',\n        stack: 'cars',\n        barMaxWidth: 100,\n        label: {\n          normal: {\n            ...this.labelOption.normal\n          }\n        },\n        barGap: '0'\n      }]\n    };\n    if (!update) {\n      optionVenues.legend = {\n        ...optionVenues.legend,\n        selected: {\n          Reportados: false\n        }\n      };\n      if (detail.status === 'finalized') {\n        (optionVenues.legend as any).selected = {\n          ...(optionVenues.legend as any).selected,\n          Pendientes: false\n        };\n      }\n      optionVenues.dataZoom = [\n        {\n          show: venuesNames.length > 12,\n          realtime: true,\n          start: 0,\n          end: venuesNames.length > 12 ? 80 : 100\n        }\n      ];\n    }\n    if (!loadingDetail) {\n      this.venuesDetailChart.setOption(optionVenues);\n      (this.venuesDetailChart as any).off();\n      this.venuesDetailChart.on('click', (params: any) => {\n        const venue = detailByVenue[params.dataIndex];\n        this.sendToDetailFilteredByVenue(venue._id);\n      });\n    }\n  }\n\n  private updateBrandChart(detailByBrand: IDetailByBrand[], update?: boolean) {\n    const {loadingDetail, detail, inventorySettings} = this.props.inventories;\n    const brandNames: string[] = [];\n    const brandFound: any[] = [];\n    const brandPending: any[] = [];\n    const brandLeftover: any[] = [];\n    const brandReported: any[] = [];\n    const brandMissing: any[] = [];\n    // detailByBrand.sort((a, b) => {\n    //   return a.name.localeCompare(b.name);\n    // });\n    if (detail.status === 'inProcess') {\n      detailByBrand.sort((a: any, b: any) => {\n        return b.results.pending - a.results.pending;\n      });\n    } else {\n      detailByBrand.sort((a: any, b: any) => {\n        return b.results.pending - a.results.pending;\n      });\n      detailByBrand.sort((a: any, b: any) => {\n        const suma = a.results.leftover + a.results.missing + a.results.reported;\n        const sumb = b.results.leftover + b.results.missing + b.results.reported;\n        return sumb - suma;\n      });\n    }\n\n    for (const brand of detailByBrand) {\n      brandNames.push(brand.name);\n      brandFound.push(brand.results && brand.results.found > 0 ? brand.results.found : null);\n      brandPending.push(brand.results && brand.results.pending > 0 ? brand.results.pending : null);\n      brandLeftover.push(brand.results && brand.results.leftover > 0 ? brand.results.leftover : null);\n      brandReported.push(brand.results && brand.results.reported > 0 ? brand.results.reported : null);\n      brandMissing.push(brand.results && brand.results.missing > 0 ? brand.results.missing : null);\n    }\n    const optionBrands: echarts.EChartOption = {\n      tooltip: {\n        trigger: 'axis',\n        axisPointer: {\n          type: 'shadow'\n        }\n      },\n      legend: {\n        // x: 'center',\n        bottom: 50,\n        data: [inventorySettings.found, inventorySettings.leftover, inventorySettings.missing, inventorySettings.pending, inventorySettings.reported]\n      },\n      xAxis: {\n        type: 'category',\n        data: brandNames,\n        axisLine: {\n          lineStyle: {\n            color: 'rgba(0, 0, 0, 0.5)'\n          }\n        },\n        axisLabel: {\n          rotate: 90\n        }\n      },\n      yAxis: {\n        minInterval: 1,\n        type: 'value',\n        axisLine: {\n          lineStyle: {\n            color: 'rgba(0, 0, 0, 0.5)'\n          }\n        },\n        splitLine: {\n          show: true,\n          lineStyle: {\n            color: 'rgba(150, 150, 150, 0.5)'\n          }\n        }\n      },\n      grid: {\n        top: 30,\n        bottom: 100,\n        // left\n        left: 5,\n        // right\n        right: 10,\n        containLabel: true\n      },\n      color: [inventorySettings.foundColor, inventorySettings.leftoverColor, inventorySettings.missingColor, inventorySettings.pendingColor, inventorySettings.reportedColor],\n      series: [{\n        data: brandFound,\n        name: inventorySettings.found,\n        type: 'bar',\n        stack: 'cars',\n        barMaxWidth: 100,\n        barGap: '0'\n      }, {\n        data: brandLeftover,\n        name: inventorySettings.leftover,\n        type: 'bar',\n        stack: 'cars',\n        barMaxWidth: 100,\n        barGap: '0'\n      }, {\n        data: brandMissing,\n        name: inventorySettings.missing,\n        type: 'bar',\n        stack: 'cars',\n        barMaxWidth: 100,\n        barGap: '0'\n      }, {\n        data: brandPending,\n        name: inventorySettings.pending,\n        type: 'bar',\n        stack: 'cars',\n        barMaxWidth: 100,\n        barGap: '0'\n      }, {\n        data: brandReported,\n        name: inventorySettings.reported,\n        type: 'bar',\n        stack: 'cars',\n        barMaxWidth: 100,\n        barGap: '0'\n      }]\n    };\n    if (!update) {\n      optionBrands.legend = {\n        ...optionBrands.legend,\n        selected: {\n          Reportados: false\n        }\n      };\n      if (detail.status === 'finalized') {\n        (optionBrands.legend as any).selected = {\n          ...(optionBrands.legend as any).selected,\n          Pendientes: false\n        };\n      }\n      optionBrands.dataZoom = [\n        {\n          show: brandNames.length > 12,\n          realtime: true,\n          start: 0,\n          end: brandNames.length > 12 ? 80 : 100\n        }\n      ];\n    }\n    if (!loadingDetail) {\n      this.brandDetailChart.setOption(optionBrands);\n    }\n  }\n\n  private resizeCharts(): void {\n    if (this.venuesDetailChart) {\n      this.venuesDetailChart.resize();\n      setTimeout(() => {\n        this.venuesDetailChart.resize();\n      }, 400);\n    }\n    if (this.brandDetailChart) {\n      this.brandDetailChart.resize();\n      setTimeout(() => {\n        this.brandDetailChart.resize();\n      }, 400);\n    }\n  }\n\n  private customTotal(from: any, to: any, size: any) {\n    return(\n      <span className=\"react-bootstrap-table-pagination-total text-ellipsis\" style={{fontSize: '75%'}}>\n        &nbsp;&nbsp;Mostrando registros del {from} al {to} de {size} registros.\n      </span>\n    );\n  }\n\n  private labelStatus(option: string): React.ReactElement<IPropsType> | null {\n    if (option === 'finalized') {\n      return <span className=\"label label-success\" style={{\n        padding: '5px 10px', fontSize: '11px'\n      }}><i className=\"fa fa-fw fa-check\"/> Finalizado</span>;\n    } else if (option === 'inProcess') {\n      return <span className=\"label label-primary\" style={{\n        padding: '5px 10px', fontSize: '11px'\n      }}><i className=\"fa fa-fw fa-spin fa-spinner\"/> En progreso</span>;\n    } else {\n      return null;\n    }\n  }\n\n}\n\nconst mapStateToProps = (state: { inventories: IInventoryState, router: RouterState }) => {\n  return {\n    inventories: state.inventories,\n    router: state.router\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer)),\n    updateInventoryCarAction: (inventoryCar: IInventoryCar) => dispatch(updateInventoryCarAction(inventoryCar)),\n    inventoryDetailChangeSelected: (item: string) => dispatch(inventoryDetailChangeSelected(item)),\n    getInventoryDetailAction: (id: string, update: boolean) => dispatch(getInventoryDetailAction(id, update)),\n    inventoryDetailChangeFilter: (filter: IFilterCar) => dispatch(inventoryDetailChangeFilter(filter)),\n    inventoryDetailChangeFilterText: (filter: IFilterCar) => dispatch(inventoryDetailChangeFilterText(filter)),\n    actionSetLabel: (inventory: string, car: string, carID: string, label: IInventoryLabel) => dispatch(actionSetLabel(inventory, car, carID, label))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(InventoryDetailView);\n","import * as React from 'react';\n\ninterface IPropsType {\n  value: string;\n  className?: string;\n}\n\nclass CopyText extends React.Component<IPropsType, {}> {\n\n  private element: React.RefObject<HTMLDivElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.element = React.createRef();\n    this.copyToClipboard = this.copyToClipboard.bind(this);\n  }\n\n  showNotification(value: string) {\n    if ($('#center-message').length) {\n      $('#center-message').remove();\n    }\n    const div = document.createElement('div');\n    div.id = 'center-message';\n    div.textContent = `${value} copiado a clipboard.`;\n    document.body.appendChild(div);\n    $('#center-message').fadeIn();\n    setTimeout(() => {\n      const $centerMessage = $('#center-message');\n      $centerMessage.fadeOut('slow', () => {\n        if ($centerMessage.length) {\n          $centerMessage.remove();\n        }\n      });\n    }, 1500);\n  }\n\n  copyToClipboard() {\n    const {value} = this.props;\n    if (value && value.length && this.element.current) {\n      const element = document.createElement('input');\n      element.value = value;\n      // element.type = 'hidden';\n      this.element.current.appendChild(element);\n      element.select();\n      document.execCommand('copy');\n      this.element.current.removeChild(element);\n      this.showNotification(value);\n    }\n  }\n\n  render(): React.ReactElement<IPropsType> {\n    const {className} = this.props;\n    return (\n      <span className={className ? className : ''} ref={this.element}>\n        {this.props.children}{' '}\n        <i\n          className=\"fa fa-copy pointer hidden-xs hidden-sm\"\n          onClick={this.copyToClipboard}\n          data-toggle=\"tooltip\"\n          data-placement=\"top\"\n          title=\"Copiar a clipboard\"\n          style={{\n            fontSize: '80%'\n          }}\n        />\n      </span>\n    );\n  }\n}\n\nexport default CopyText;\n","import * as moment from 'moment';\nimport * as React from 'react';\nimport {connect} from 'react-redux';\nimport {IInventoryComment} from '../../../../../../src/inventory/interfaces/inventoryComment.interface';\nimport {addCommentAction, IInventoryState, sendCommentAction} from '../../actions/inventory.actions';\nimport {IWindow} from '../../interfaces/window';\nimport Row from '../Utils/Row';\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\n\ninterface IPropsType {\n  inventories: IInventoryState;\n  socket: Socket;\n  addCommentAction(inventoryComment: IInventoryComment): void;\n  sendCommentAction(carId: string, comment: string): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  comment: string;\n  resetRender: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass InventoryCarComments extends React.Component<IPropsType, IStateType> {\n\n  state = {\n    error: null,\n    comment: '',\n    resetRender: true\n  };\n\n  interval: any;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.handlerComment = this.handlerComment.bind(this);\n    this.sendComment = this.sendComment.bind(this);\n    this.keyPressComment = this.keyPressComment.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const {inventoryCar} = this.props.inventories;\n    if (inventoryCar) {\n      const id = (inventoryCar as any)._id;\n      this.props.socket.emit('join', {room: `inventory-comment-${id}`});\n      this.props.socket.on('connect', () => {\n        this.props.socket.emit('join', {room: `inventory-comment-${id}`});\n      });\n      this.props.socket.on('NEW_COMMENT', (data: any): void => {\n        this.props.addCommentAction(data);\n        const $comments = document.getElementById('comments');\n        if ($comments) {\n          $comments.scrollTop = $comments.scrollHeight;\n        }\n      });\n    }\n  }\n\n  public componentDidMount(): void {\n    setTimeout(() => {\n      const $comments = document.getElementById('comments');\n      if ($comments) {\n        $comments.scrollTop = $comments.scrollHeight;\n      }\n    }, 300);\n    this.interval = setInterval(() => {\n      this.setState({\n        resetRender: !this.state.resetRender\n      });\n    }, 2000);\n  }\n\n  public componentWillUnmount(): void {\n    clearInterval(this.interval);\n    this.props.socket.off('NEW_COMMENT');\n    const {inventoryCar} = this.props.inventories;\n    if (inventoryCar) {\n      const id = (inventoryCar as any)._id;\n      this.props.socket.emit('leave', {room: `inventory-comment-${id}`});\n    }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {inventoryCar} = this.props.inventories;\n    return (\n      <Row>\n        <div className={'col-md-12'}>\n          <strong>Detalle del vehiculo</strong>\n        </div>\n        <div className={'col-md-3'}>\n          <strong>VIN</strong>\n        </div>\n        <div className={'col-md-9'}>\n          {(inventoryCar as any).vin ? (inventoryCar as any).vin : '-'}\n        </div>\n        <div className={'col-md-3'}>\n          <strong>Marca</strong>\n        </div>\n        <div className={'col-md-9'}>\n          {(inventoryCar as any).brand ? (inventoryCar as any).brand : '-'}\n        </div>\n        <div className={'col-md-3'}>\n          <strong>Denominación</strong>\n        </div>\n        <div className={'col-md-9'}>\n          {(inventoryCar as any).denomination ? (inventoryCar as any).denomination : '-'}\n        </div>\n        <div className={'col-md-3'}>\n          <strong>Reportado en</strong>\n        </div>\n        <div className={'col-md-9'}>\n          {(inventoryCar as any).venueFound ? (inventoryCar as any).venueFound : '-'}\n        </div>\n        <div className={'col-md-3'}>\n          <strong>Reportado por</strong>\n        </div>\n        <div className={'col-md-9'}>\n          {(inventoryCar as any).inventoriedBy ? (inventoryCar as any).inventoriedBy : '-'}\n        </div>\n        <div className={'col-md-12'}>\n          &nbsp;\n        </div>\n        <div className={'col-md-12'}>\n          <div className=\"direct-chat-info\" style={{border: '1px solid #efefef'}}>\n            <div className=\"direct-chat-messages\" id={'comments'} style={{height: '30vh'}}>\n              {\n                inventoryCar ? inventoryCar.comments.map((comment) => {\n                  return (\n                    <div\n                      className={`direct-chat-msg ${comment.user && comment.user._id === window.user._id ? 'right' : ''}`}\n                      key={comment._id}\n                    >\n                      <div className=\"direct-chat-info clearfix\">\n                        <span\n                          className=\"direct-chat-name pull-left\"\n                        >\n                          {comment.user ? `${comment.user.firstName} ${comment.user.lastName}` : '-'}\n                        </span>\n                        <span className=\"direct-chat-timestamp pull-right\">{moment(comment.createdAt).fromNow()}</span>\n                      </div>\n                      <img className=\"direct-chat-img\" src=\"/static/images/icon_circular.png\" alt=\"message user image\"/>\n                      <div className=\"direct-chat-text\">\n                        {\n                          comment.comment.split('\\n').map((item, key) => {\n                            return (\n                              <span key={key}>{item}<br/></span>\n                            );\n                          })}\n                      </div>\n                    </div>\n                  );\n                }) : null\n              }\n            </div>\n          </div>\n          <div className=\"form-group\">\n            <label htmlFor=\"comment\">Comentario:</label>\n            <textarea\n              className=\"form-control\"\n              rows={4}\n              id=\"comment\"\n              onChange={this.handlerComment}\n              onKeyPress={this.keyPressComment}\n              value={this.state.comment}\n            />\n          </div>\n          <div className=\"form-group text-right\">\n            <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.sendComment}>Comentar</button>\n          </div>\n        </div>\n      </Row>\n    );\n  }\n\n  private handlerComment(e: React.ChangeEvent<HTMLTextAreaElement>): void {\n    this.setState({\n      comment: e.target.value\n    });\n  }\n\n  private keyPressComment(e: React.KeyboardEvent<HTMLTextAreaElement>): void {\n    if (e.key === 'Enter' && !e.shiftKey) {\n      this.sendComment();\n      setTimeout(() => {\n        this.setState({\n          comment: ''\n        });\n      }, 100);\n    }\n  }\n\n  private sendComment() {\n    const {inventoryCar} = this.props.inventories;\n    if (inventoryCar && this.state.comment.trim().length) {\n      this.props.sendCommentAction((inventoryCar as any)._id, this.state.comment);\n      this.setState({\n        comment: ''\n      });\n    }\n  }\n}\n\nconst mapStateToProps = (state: { inventories: IInventoryState }) => {\n  return {\n    inventories: state.inventories\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    addCommentAction: (inventoryComment: IInventoryComment) => dispatch(addCommentAction(inventoryComment)),\n    sendCommentAction: (carId: string, comment: string) => dispatch(sendCommentAction(carId, comment))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(InventoryCarComments);\n","import * as React from 'react';\nimport { connect } from 'react-redux';\nimport { IInventoryState } from '../../actions/inventory.actions';\nimport { IWindow } from '../../interfaces/window';\nimport Row from '../Utils/Row';\nimport ShowIf from '../Utils/ShowIf';\nimport MultiUploadFiles, { imageStatus } from '../Utils/MultiUploadFiles';\nimport ApiService from '../../utils/axios';\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ninterface IPropsType {\n  inventoryCardId: string;\n  inventories: IInventoryState;\n  socket: Socket;\n}\n\ninterface IStateType {\n  error: Error | null;\n  loading: boolean;\n  files: any[];\n}\n\ndeclare let window: IWindow;\n\nclass InventoryFileManager extends React.Component<IPropsType, IStateType> {\n\n  readonly state: IStateType = {\n    error: null,\n    loading: true,\n    files: []\n  };\n\n  readonly api: ApiService;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.api = new ApiService();\n    this.deleteFile = this.deleteFile.bind(this);\n  }\n\n  public componentWillMount(): void {\n    // if (inventoryCar) {\n    //   const id = (inventoryCar as any)._id;\n    //   this.props.socket.emit('join', { room: `inventory-comment-${id}` });\n    //   this.props.socket.on('connect', () => {\n    //     this.props.socket.emit('join', { room: `inventory-comment-${id}` });\n    //   });\n    //   this.props.socket.on('NEW_COMMENT', (data: any): void => {\n    //   });\n    // }\n  }\n\n  public componentDidMount(): void {\n    const {inventoryCardId} = this.props;\n    this.api.getInventoryCarFiles(inventoryCardId)\n      .then((response) => {\n        const { files } = response.data;\n        this.setState({\n          loading: false,\n          files: files.map((file: any) => {\n            return {\n              ...file.file,\n              _id: file._id,\n              url: decodeURIComponent(file.file.url),\n              isImage: this.isImage(file.file.type),\n              status: imageStatus.complete\n            };\n          })\n        });\n      })\n  }\n\n  private deleteFile(id: string){\n    this.api.deleteInventoryCarFile(id);\n  }\n\n  private isImage(type: string): boolean {\n    const accepted = ['image/jpg', 'image/jpeg', 'image/png'];\n    return accepted.includes(type);\n  }\n\n  public componentWillUnmount(): void {\n    const { inventoryCar } = this.props.inventories;\n    if (inventoryCar) {\n      const id = (inventoryCar as any)._id;\n      this.props.socket.emit('leave', { room: `inventory-comment-${id}` });\n    }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {inventories, inventoryCardId} = this.props;\n    const {loading, files} = this.state;\n    return (\n      <>\n        <Row>\n          <div className={'col-md-12'}>\n            <MultiUploadFiles\n              url={`/api/v1/inventory/${inventories.detail._id}/upload-file/`}\n              listMode={true}\n              deleteCalback={this.deleteFile}\n              body={{\n                inventoryCardId\n              }}\n              onChange={(files) => {\n                this.setState({ files });\n              }}\n              files={files}\n            />\n          </div>\n          <ShowIf condition={loading}>\n            <div className={'col-md-12 text-center'}>\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            </div>\n          </ShowIf>\n        </Row>\n      </>\n    );\n  }\n\n}\n\nconst mapStateToProps = (state: { inventories: IInventoryState }) => {\n  return {\n    inventories: state.inventories\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(InventoryFileManager);\n","import * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport { io } from \"socket.io-client\";\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport * as swal from 'sweetalert';\nimport {\n  deleteInventoryAction,\n  finishInventoryAction,\n  getInventoriesAction,\n  IInventoryState,\n  InventoryReduxAction\n} from '../../actions/inventory.actions';\nimport AppContainer from '../../container/AppContainer';\nimport {IWindow} from '../../interfaces/window';\nimport {hasPermission} from '../../utils/common';\nimport Row from '../Utils/Row';\nimport Paginator from '../Utils/Paginator';\nimport { Link } from 'react-router-dom';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\n\ndeclare let window: IWindow;\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  inventories: IInventoryState;\n  dispatch: Dispatch<InventoryReduxAction>;\n\n  getInventoriesAction(loading: boolean, page: number): void;\n  finishInventoryAction(id: string): void;\n  deleteInventoryAction(id: string): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass InventoryListView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  // static propTypes = {\n  //   dispatch: PropTypes.func.isRequired\n  // };\n\n  readonly state = {\n    error: null\n  };\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Inventarios';\n    this.create = this.create.bind(this);\n    this.changePage = this.changePage.bind(this);\n    this.labelStatus = this.labelStatus.bind(this);\n    this.finishInventoryAction = this.finishInventoryAction.bind(this);\n    this.deleteInventoryAction = this.deleteInventoryAction.bind(this);\n    this.goToDetail = this.goToDetail.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const {page} = this.props.inventories.pagination;\n    // set the title of the page\n    window.scrollTo(0, 0);\n\n    // get data\n    this.props.getInventoriesAction(true, page);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: window.user.token\n      }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {room: `inventory-list-${window.user.team._id}`});\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update) {\n        const {pagination} = this.props.inventories;\n        this.props.getInventoriesAction(false, pagination.page);\n      }\n    });\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    window.scrollTo(0, 0);\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.inventories.source) {\n      this.props.inventories.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.emit('leave', {room: `inventory-list-${window.user.team._id}`});\n    this.socket.disconnect();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {inventories, inventorySettings, loading, pagination} = this.props.inventories;\n    return (\n      <AppContainer title=\"\" cMenu=\"2\" cSubMenu=\"2.1\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Gestión de inventarios <small>{pagination.count}</small></h3>\n              <div className=\"pull-right box-tools\">\n                {\n                  hasPermission(window.user, 'createInventory') ?\n                    <button className=\"btn btn-sm btn-success\" onClick={this.create}>Nuevo</button>\n                    : null\n                }\n              </div>\n            </div>\n            <div className=\"box-body\">\n              <Row>\n                <div className=\"col-md-12\">\n                  {\n                    !inventories.length && !loading ? 'Aún no se han creado inventarios.' : null\n                  }\n                  {\n                    inventories.map((inventory: any) => {\n                      return (\n                        <div className=\"inventory\" key={inventory._id} id={`inventory-${inventory._id}`}>\n                          <Row>\n                            <div className=\"col-md-8 col-xs-8\">\n                              <h4 className=\"text-primary pointer\" onClick={() => this.goToDetail(inventory._id)}>{inventory.name}</h4>\n                            </div>\n                            <div className=\"col-md-4 col-xs-4 text-right\">\n                              {this.labelStatus(inventory.status)}\n                            </div>\n                          </Row>\n                          <Row>\n                            <div className=\"col-lg-3 col-md-4 col-xs-12 text-muted text-detail-user\">\n                              <p>\n                                <i className=\"fa fa-fw fa-clock-o text-success\"/>Creado el {moment(inventory.createdAt).format('LLL')}<br/>\n                                {\n                                  inventory.createdBy ?\n                                    <React.Fragment><i className=\"fa fa-fw fa-user\"/>Por {inventory.createdBy.fullName}<br/></React.Fragment>\n                                    : null\n                                }\n                                {\n                                  inventory.finalizedAt ?\n                                    <React.Fragment>\n                                      <i className=\"fa fa-fw fa-clock-o text-danger\"/>Finalizado el {moment(inventory.finalizedAt).format('LLL')}<br/>\n                                      {\n                                        inventory.finalizedBy ? <React.Fragment><i className=\"fa fa-fw fa-user\"/>Por {inventory.finalizedBy.fullName}</React.Fragment> : null\n                                      }\n                                    </React.Fragment>\n                                    : null\n                                }\n                              </p>\n                            </div>\n                            <div className=\"col-lg-7 col-md-8\">\n                              <div className=\"row right-border\">\n                                <div className={`col-md-5th-1 col-xs-3 text-center text-${inventorySettings.foundClass}`}>\n                                  <strong style={{fontSize: '80%'}}>{inventorySettings.found}</strong>\n                                  <h2 style={{marginTop: '10px'}}>{inventory.results.found}</h2>\n                                </div>\n                                <div className={`col-md-5th-1 col-xs-3 text-center text-${inventorySettings.leftoverClass}`}>\n                                  <strong style={{fontSize: '80%'}}>{inventorySettings.leftover}</strong>\n                                  <h2 style={{marginTop: '10px'}}>{inventory.results.leftover}</h2>\n                                </div>\n                                <div className={`col-md-5th-1 col-xs-3 text-center text-${inventorySettings.missingClass}`}>\n                                  <strong style={{fontSize: '80%'}}>{inventorySettings.missing}</strong>\n                                  <h2 style={{marginTop: '10px'}}>{inventory.results.missing}</h2>\n                                </div>\n                                <div className={`col-md-5th-1 col-xs-3 text-center text-${inventorySettings.pendingClass} no-right-border-mobile`}>\n                                  <strong style={{fontSize: '80%'}}>{inventorySettings.pending}</strong>\n                                  <h2 style={{marginTop: '10px'}}>{inventory.results.pending}</h2>\n                                </div>\n                                <div className={`col-md-5th-1 text-center text-${inventorySettings.reportedClass} hidden-xs hidden-sm`}>\n                                  <strong style={{fontSize: '80%'}}>{inventorySettings.reported}</strong>\n                                  <h2 style={{marginTop: '10px'}}>{inventory.results.reported}</h2>\n                                </div>\n                              </div>\n                            </div>\n                            <div className=\"col-lg-2 col-md-12 text-right\">\n                              <div className=\"btn-group btn-group-sm\">\n                                {\n                                  inventory.status === 'inProcess' ?\n                                    <button type=\"button\" className=\"btn btn-default\" onClick={() => this.goToDetail(inventory._id)}>\n                                      <i className=\"fa fa-fw fa-area-chart\"/> Ver Progreso\n                                    </button>\n                                    :\n                                    <button type=\"button\" className=\"btn btn-default\" onClick={() => this.goToDetail(inventory._id)}>\n                                      <i className=\"fa fa-fw fa-area-chart\"/> Ver Reporte\n                                    </button>\n                                }\n                                <button type=\"button\" className=\"btn btn-default dropdown-toggle\" data-toggle=\"dropdown\">\n                                  <span className=\"caret\" />\n                                  <span className=\"sr-only\">Toggle Dropdown</span>\n                                </button>\n                                <ul className=\"dropdown-menu pull-right\" role=\"menu\">\n                                  <li>\n                                    <Link to={`/inventory/${inventory._id}/detail/`}>\n                                    {/* <a href=\"javascript:void(0);\" onClick={() => this.goToDetail(inventory._id, true)}> */}\n                                      <i className=\"fa fa-fw fa-table\" />Ver Detalle\n                                    {/* </a> */}\n                                    </Link>\n                                  </li>\n                                  {\n                                    hasPermission(window.user, 'viewFilesInventory') && inventory.file && inventory.file.hasOwnProperty('url') ?\n                                      <li>\n                                        <a href={decodeURI(inventory.file.url)} download={inventory.file.name}>\n                                          <i className=\"fa fa-fw fa-download\"/>Descargar archivo cargado\n                                        </a>\n                                      </li>\n                                      : null\n                                  }\n                                  {\n                                    hasPermission(window.user, 'viewFilesInventory') && inventory.backup && inventory.backup.hasOwnProperty('url') ?\n                                      <li>\n                                        <a href={decodeURI(inventory.backup.url)} target=\"_blank\" download={inventory.backup.name}>\n                                          <i className=\"fa fa-fw fa-download\"/>Descargar archivo de respaldo\n                                        </a>\n                                      </li>\n                                      : null\n                                  }\n                                  {\n                                    inventory.status === 'inProcess' && hasPermission(window.user, 'finishInventory') ?\n                                        <li>\n                                          <a href=\"javascript:void(0);\" onClick={() => this.finishInventoryAction(inventory)}>\n                                            <i className=\"fa fa-fw fa-stop\" />Finalizar\n                                          </a>\n                                        </li>\n                                      : null\n                                  }\n                                  {\n                                    inventory.status === 'inProcess' && hasPermission(window.user, 'deleteInventory') ?\n                                      <li>\n                                        <a href=\"javascript:void(0);\" onClick={() => this.deleteInventoryAction(inventory)}>\n                                          <i className=\"fa fa-fw fa-close\" />Eliminar\n                                        </a>\n                                      </li>\n                                      : null\n                                  }\n                                </ul>\n                              </div>\n                            </div>\n                          </Row>\n                        </div>\n                      );\n                    })\n                  }\n                </div>\n              </Row>\n            </div>\n            {\n              pagination.pages > 1 &&\n                <div className=\"box-footer\">\n                  <div className=\"row\">\n                    <div className=\"col-md-6\" style={{ padding: '20px 15px' }}>\n                      <span className=\"react-bootstrap-table-pagination-total text-ellipsis\">\n                        &nbsp;&nbsp;Mostrando registros del {(pagination.page - 1) * 10 + 1} al {(pagination.page) * 10} de {pagination.count} registros.\n                            </span>\n                    </div>\n                    <div className=\"col-md-6\">\n                      <div className=\"text-right\" style={{ marginRight: '15px' }}>\n                        <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                      </div>\n                    </div>\n                  </div>\n                </div>\n            }\n            {\n              loading &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private changePage(page: number): void {\n    this.props.getInventoriesAction(true, page);\n  }\n\n  private goToDetail(id: string, detail?: boolean): void {\n    const {history} = this.props;\n    history.push(`/inventory/${id}/${detail ? 'detail/' : ''}`);\n  }\n\n  private finishInventoryAction(inventory: any): void {\n    const {finishInventoryAction} = this.props;\n    // ask if you are sure that you are going to finish the inventory?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a finalizar \"${inventory.name}\".`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        finishInventoryAction(inventory._id);\n      }\n    });\n  }\n\n  private deleteInventoryAction(inventory: any): void {\n    const {deleteInventoryAction} = this.props;\n    // ask if you are sure that you are going to delete the inventory?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar \"${inventory.name}\".`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        deleteInventoryAction(inventory._id);\n      }\n    });\n  }\n\n  private labelStatus(option: string): React.ReactElement<IPropsType> {\n    if (option === 'finalized') {\n      return <span className=\"label label-success\"><i className=\"fa fa-fw fa-check\"/> Finalizado</span>;\n    } else if (option === 'inProcess') {\n      return <span className=\"label label-primary\"><i className=\"fa fa-fw fa-spin fa-spinner\"/> En progreso</span>;\n    } else {\n      return <span className=\"label label-warning\">Pendiente</span>;\n    }\n  }\n\n  private create(): void {\n    this.props.history.push('/inventory/create/');\n  }\n}\n\nconst mapStateToProps = (state: { inventories: IInventoryState }) => {\n  return {\n    inventories: state.inventories\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getInventoriesAction: (loading: boolean, page: number) => dispatch(getInventoriesAction(loading, page)),\n    finishInventoryAction: (id: string) => dispatch(finishInventoryAction(id)),\n    deleteInventoryAction: (id: string) => dispatch(deleteInventoryAction(id))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(InventoryListView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport * as swal from 'sweetalert';\nimport { IInventoryLabel } from '../../../../../../src/inventory/interfaces/inventoryLabel.interface';\nimport {\n  changeLabelAction,\n  changeTempLabelAction,\n  createLabelAction,\n  deleteLabelAction,\n  getLabelsAction,\n  ILabelsState,\n  LabelsReduxAction\n} from '../../actions/labels.actions';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { statusFooterButttonsModal } from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport BootstrapSwitch from '../Utils/BootstrapSwitch';\nimport Paginator from '../Utils/Paginator';\nimport LabelFormView from './LabelFormView';\nimport { CarStatusType } from '../Inventory/InventoryDetailView';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<LabelsReduxAction>;\n  labels: ILabelsState;\n\n  changeTempLabelAction(tempLabel: IInventoryLabel): LabelsReduxAction;\n  getLabelsAction(page: number): LabelsReduxAction;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n  createLabelAction(label: IInventoryLabel): LabelsReduxAction;\n  changeLabelAction(label: IInventoryLabel, message?: boolean): LabelsReduxAction;\n  deleteLabelAction(id: string): LabelsReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass LabelsListView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de etiquetas';\n    this.addLabel = this.addLabel.bind(this);\n    this.processAddLabel = this.processAddLabel.bind(this);\n    this.editLabel = this.editLabel.bind(this);\n    this.processEditLabel = this.processEditLabel.bind(this);\n    this.deleteLabel = this.deleteLabel.bind(this);\n    this.changePage = this.changePage.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const {pagination} = this.props.labels;\n    this.props.getLabelsAction(pagination.page);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {token: (window.user as any).token}\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {room: `label-list-${window.user.team._id}`});\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update && data.updatedBy !== window.user._id) {\n        const {pagination} = this.props.labels;\n        this.props.getLabelsAction(pagination.page);\n      }\n    });\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if(this.props.labels.pagination !== prevProps.labels.pagination){\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    window.scrollTo(0, 0);\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.labels.source) {\n      this.props.labels.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {loading, labels, pagination, inventorySettings} = this.props.labels;\n    return (\n      <AppContainer title=\"\" cMenu=\"2\" cSubMenu=\"2.2\" cAction=\"Listado\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Etiquetas <small>{pagination.count}</small></h3>\n              <div className=\"box-tools pull-right\">\n                <button className=\"btn btn-sm btn-success\" onClick={this.addLabel}>Agregar</button>\n              </div>\n            </div>\n            <div className=\"box-body no-padding\">\n              <table className=\"table  table-andes table-striped\">\n                <thead>\n                  <tr>\n                    <th className=\"middle\">Nombre</th>\n                    <th className=\"middle\" style={{width: '100px'}}>Agregar opción en</th>\n                    <th className=\"middle\" style={{width: '80px'}}>Envia a</th>\n                    <th className=\"middle-center\" style={{width: '80px'}}>Activo</th>\n                    <th style={{width: '1%'}} className=\"width-10\"/>\n                    <th style={{width: '1%'}} className=\"width-10\"/>\n                  </tr>\n                </thead>\n                <tbody>\n                  {\n                    labels.map((label) => {\n                      return (\n                        <tr\n                          key={label._id} id={`label-${label._id}`}\n                          className={`background-transition ${!label.active ? 'text-muted' : ''}`}\n                        >\n                          <td className=\"middle text-ellipsis\">\n                            {label.name}\n                            <p className={\"text-muted text-sm\"}>{label.description}</p>\n                          </td>\n                          <td className=\"middle\" style={{lineHeight: 1.6}}>\n                            {\n                              label.affected.map((aff, key)=>(\n                                <React.Fragment key={key}>\n                                  <label\n                                    className={`label label-${inventorySettings[`${aff}Class` as CarStatusType]}`}\n                                  >\n                                    {inventorySettings[aff as CarStatusType]}\n                                  </label><br />\n                                  </React.Fragment>\n                              ))\n                            }\n                          </td>\n                          <td className=\"middle\">\n                            <label className={`label label-${inventorySettings[`${label.sendTo}Class` as CarStatusType]}`}>\n                              {inventorySettings[label.sendTo as CarStatusType]}\n                            </label>\n                          </td>\n                          <td className=\"middle-center\" style={{paddingTop: '15px'}}>\n                            <BootstrapSwitch\n                              checked={label.active}\n                              onChange={() => {\n                                this.props.changeLabelAction({\n                                  ...label,\n                                  active: !label.active\n                                });\n                              }}\n                            />\n                          </td>\n                          <td\n                            onClick={() => this.editLabel(label)}\n                            className=\"middle text-blue pointer\"\n                          >\n                            <i className=\"fa fa-pencil\"/>\n                          </td>\n                          <td\n                            onClick={() => this.deleteLabel(label)}\n                            className={'middle text-red pointer'}\n                          >\n                            <i className=\"fa fa-minus-circle\"/>\n                          </td>\n                        </tr>\n                      );\n                    })\n                  }\n                </tbody>\n              </table>\n            </div>\n            {\n              pagination.pages > 1 &&\n                <div className=\"box-footer text-right\">\n                  <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                </div>\n            }\n            {\n              loading &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private addLabel(): void {\n    this.props.changeTempLabelAction({\n      _id: '',\n      name: '',\n      description: '',\n      color: '',\n      affected: [],\n      sendTo: '',\n      requireCustomText: false,\n      isExhibition: false,\n      active: true\n    });\n    setTimeout(() => {\n      this.props.loadDataAction(\n        'Agregar Etiqueta',\n        <LabelFormView changeTempLabelAction={changeTempLabelAction}/>,\n        <React.Fragment>\n          <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n          <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processAddLabel}>Grabar</button>\n        </React.Fragment>\n      );\n    }, 200);\n  }\n\n  private processAddLabel(): void {\n    const { tempLabel} = this.props.labels;\n    if (this.validateLabel(tempLabel, 'Agregar Etiqueta')) {\n      statusFooterButttonsModal(true);\n      this.props.createLabelAction(tempLabel);\n    }\n  }\n\n  private editLabel(tempLabel: IInventoryLabel): void {\n    this.props.changeTempLabelAction(tempLabel);\n    setTimeout(() => {\n      this.props.loadDataAction(\n        'Editar Etiqueta',\n        <LabelFormView changeTempLabelAction={changeTempLabelAction}/>,\n        <React.Fragment>\n          <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n          <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processEditLabel}>Editar</button>\n        </React.Fragment>\n      );\n    }, 200);\n\n  }\n\n  private processEditLabel(): void {\n    const { tempLabel} = this.props.labels;\n    if (this.validateLabel(tempLabel, 'Editar Etiqueta')) {\n      statusFooterButttonsModal(true);\n      this.props.changeLabelAction(tempLabel, true);\n    }\n  }\n\n  private deleteLabel(label: IInventoryLabel): void {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar la etiqueta \"${label.name}\". Los inventarios marcados con esta etiqueta serán afectados y no se mostrara. `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete: any) => {\n      if (willDelete) {\n        this.props.deleteLabelAction(label._id);\n      }\n    });\n  }\n\n  private validateLabel(label: IInventoryLabel, action: string): boolean {\n    if (!label.name || !label.name.trim().length) {\n      swal!(action, 'El nombres es requerido', 'error');\n      return false;\n    } else if (!label.affected || !label.affected.length) {\n      swal!(action, '\"Agregar opción en\" debe tener al menos 1 seleccionado.', 'error');\n      return false;\n    } else if (!label.sendTo || !label.sendTo.trim().length) {\n      swal!(action, 'Debe seleccionar donde se enviara', 'error');\n      return false;\n    }\n    return true;\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    this.props.getLabelsAction(page);\n  }\n}\n\nconst mapStateToProps = (state: { labels: ILabelsState }) => {\n  return {\n    labels: state.labels\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    changeTempLabelAction: (tempLabel: IInventoryLabel) => dispatch(changeTempLabelAction(tempLabel)),\n    createLabelAction: (label: IInventoryLabel) => dispatch(createLabelAction(label)),\n    changeLabelAction: (label: IInventoryLabel, message?: boolean) => dispatch(changeLabelAction(label, message)),\n    deleteLabelAction: (id: string) => dispatch(deleteLabelAction(id)),\n    getLabelsAction: (page: number) => dispatch(getLabelsAction(page)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{labels: ILabelsState}, {dispatch: any}, IPropsType>(mapStateToProps, mapDispatchToProps)(LabelsListView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {IInventoryLabel} from '../../../../../../src/inventory/interfaces/inventoryLabel.interface';\nimport {changeTempLabelAction, ILabelsState, LabelsReduxAction} from '../../actions/labels.actions';\nimport {updateTooltip} from '../../utils/common';\nimport BootstrapSelect from '../Utils/BootstrapSelect';\nimport BootstrapSwitch from '../Utils/BootstrapSwitch';\nimport {CarStatusType} from \"../Inventory/InventoryDetailView\";\n\ninterface IPropsType {\n  labels?: ILabelsState;\n  update?: boolean;\n  changeTempLabelAction: (label: IInventoryLabel, debounce?: number) => LabelsReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass LabelFormView extends React.Component<IPropsType, IStateType> {\n\n  private statusText: any = {\n    pending: 'Pendiente',\n    found: 'Encontrado',\n    leftover: 'Sobrante',\n    missing: 'Faltante',\n    reported: 'Reportado'\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.filterAffected = this.filterAffected.bind(this);\n    this.filterSendTo = this.filterSendTo.bind(this);\n    this.getOptions = this.getOptions.bind(this);\n  }\n\n  public componentDidMount(): void {\n    updateTooltip();\n  }\n\n  public componentDidUpdate(): void {\n    updateTooltip();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n\n\n  render(): React.ReactElement<IPropsType> | null {\n    const {changeTempLabelAction} = this.props;\n    if (this.props.labels) {\n      const {tempLabel} = this.props.labels;\n      return (\n        <div className=\"row\">\n          <div className=\"col-md-12\">\n            <div className=\"form-group\">\n              <label>Nombre</label>\n              <input\n                type=\"text\"\n                name=\"name\"\n                className=\"form-control\"\n                maxLength={50}\n                defaultValue={tempLabel ? tempLabel.name : ''}\n                onChange={\n                  (e: React.ChangeEvent<HTMLInputElement>) => changeTempLabelAction({\n                    ...tempLabel,\n                    name: e.target.value.trim()\n                  }, 300)\n                }\n              />\n            </div>\n          </div>\n          <div className=\"col-md-12\">\n            <div className=\"form-group\">\n              <label htmlFor=\"states\" className=\"control-label\">Agregar opción en</label>\n              <BootstrapSelect\n                noneSelectedText=\"Seleccione\"\n                displayItems={5}\n                selectedText=\"estados seleccionados.\"\n                separator=\" - \"\n                options={this.getOptions()}\n                selected={tempLabel.affected}\n                onClick={this.filterAffected}\n              />\n            </div>\n          </div>\n          <div className=\"col-md-12\">\n            <div className=\"form-group\">\n              <label htmlFor=\"states\" className=\"control-label\">Enviar a</label>\n              <BootstrapSelect\n                noneSelectedText=\"Seleccione a donde\"\n                displayItems={5}\n                autoClouse={true}\n                selectedText=\"estados seleccionados.\"\n                separator=\" - \"\n                options={this.getOptions()}\n                selected={tempLabel.sendTo ? [tempLabel.sendTo] : []}\n                onClick={this.filterSendTo}\n              />\n            </div>\n          </div>\n          <div className=\"col-md-12\">\n            <div className=\"form-group-switch\">\n              <BootstrapSwitch\n                checked={tempLabel.isExhibition}\n                color=\"blue\"\n                onChange={() => {\n                  this.props.changeTempLabelAction({\n                    ...tempLabel,\n                    isExhibition: !tempLabel.isExhibition\n                  });\n                }}/>\n              <label className=\"switch-label\">Unidad de la marca</label>\n            </div>\n          </div>\n          <div className=\"col-md-12\">\n            <div className=\"form-group-switch\">\n              <BootstrapSwitch\n                checked={tempLabel.requireCustomText}\n                color=\"blue\"\n                onChange={() => {\n                  this.props.changeTempLabelAction({\n                    ...tempLabel,\n                    requireCustomText: !tempLabel.requireCustomText\n                  });\n                }}/>\n              <label className=\"switch-label\">Requerir datos adicionales</label>\n            </div>\n          </div>\n          <div className=\"col-md-12\">\n            <div className=\"form-group\">\n              <label>Descripción</label>\n              <textarea\n                name=\"description\"\n                className=\"form-control\"\n                defaultValue={tempLabel ? tempLabel.description : ''}\n                onChange={\n                  (e: React.ChangeEvent<HTMLTextAreaElement>) => changeTempLabelAction({\n                    ...tempLabel,\n                    description: e.target.value.trim()\n                  }, 300)\n                }\n              />\n            </div>\n          </div>\n        </div>\n      );\n    } else {\n      return null;\n    }\n  }\n\n  private getOptions() {\n    const {inventorySettings} = this.props.labels!;\n    return Object\n      .keys(this.statusText)\n      .map((status: CarStatusType) => ({\n        value: status,\n        text: inventorySettings[status],\n        className: `label label-${inventorySettings[`${status}Class` as CarStatusType]}`\n      }));\n  }\n\n  private filterAffected(value: any): void  {\n    if (this.props.labels && this.props.changeTempLabelAction) {\n      const {tempLabel} = this.props.labels;\n      this.props.changeTempLabelAction({\n        ...tempLabel,\n        affected: tempLabel.affected.includes(value)\n          ? tempLabel.affected.filter((state) => state !== value)\n          : [value, ...tempLabel.affected]\n      });\n    }\n  }\n\n  private filterSendTo(value: any): void  {\n    if (this.props.labels && this.props.changeTempLabelAction) {\n      const {tempLabel} = this.props.labels;\n      this.props.changeTempLabelAction({\n        ...tempLabel,\n        sendTo: value\n      });\n    }\n  }\n}\n\nconst mapStateToProps = (state: { labels: ILabelsState }) => {\n  return {\n    labels: state.labels\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    changeTempLabelAction: (label: IInventoryLabel, debounce?: number) => dispatch(changeTempLabelAction(label, debounce))\n  };\n};\n\nexport default connect<{labels: ILabelsState}, {dispatch: LabelsReduxAction}, IPropsType>(mapStateToProps, mapDispatchToProps)(LabelFormView);\n","import * as React from 'react';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport {connect} from 'react-redux';\nimport AppContainer from '../../container/AppContainer';\nimport ModalView from '../Modal/ModalView';\nimport {IPlanningState, PlanningReduxAction} from '../../actions/planning.action';\nimport {IWindow} from '../../interfaces/window';\nimport {ErrorInfo, RefObject} from 'react';\nimport * as Raven from 'raven-js';\nimport * as XLSX from 'xlsx';\nimport * as moment from 'moment';\nimport * as swal from 'sweetalert';\nimport slugify from 'slugify';\nimport ApiService from '../../utils/axios';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<PlanningReduxAction>;\n  planning: IPlanningState;\n}\n\ninterface IStateType {\n  error: Error | null;\n  carsByDate: any[];\n  canDrop: boolean;\n  sending: boolean;\n  loadingSettings: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass PlanningImportView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  readonly inputFile: RefObject<HTMLInputElement>;\n\n  readonly state = {\n    error: null,\n    canDrop: false,\n    sending: false,\n    carsByDate: [],\n    loadingSettings: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Importar planicacion';\n    this.inputFile = React.createRef();\n    this.clickUploadFile = this.clickUploadFile.bind(this);\n    this.handleDrop = this.handleDrop.bind(this);\n    this.dragOverHandler = this.dragOverHandler.bind(this);\n    this.dragEndHandler = this.dragEndHandler.bind(this);\n    this.dragLeaveHandler = this.dragLeaveHandler.bind(this);\n    this.handleChangeInputFile = this.handleChangeInputFile.bind(this);\n    this.downloadTemplate = this.downloadTemplate.bind(this);\n    this.processSettings = this.processSettings.bind(this);\n    this.sendCreate = this.sendCreate.bind(this);\n  }\n\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    window.scrollTo(0, 0);\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.planning.source) {\n      this.props.planning.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      loadingSettings, carsByDate, sending\n    } = this.state;\n    return (\n      <AppContainer title=\"\" cMenu=\"4\" cSubMenu=\"4.2\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Importar planificación</h3>\n              <div className=\"pull-right box-tools\">\n                {\n                  !carsByDate.length?\n                    <button\n                      className=\"btn btn-sm btn-primary\"\n                      onClick={this.downloadTemplate}\n                      style={{marginRight: '5px'}}>\n                      <i className=\"fa fa-fw fa-download\" /> Descargar Formato\n                    </button>\n                    :null\n                }\n              </div>\n            </div>\n            <div className=\"box-body margin\">\n              {\n                carsByDate.length?\n                  <div className=\"row\">\n                    <div className=\"col col-md-12\">\n                      <div className=\"form-group\">\n                        <label>Días que serán importardos</label>\n                        {\n                          carsByDate.map((carByDate: any) => (\n                            <div className=\"panel box box-default\" style={{borderTopWidth: '2px', marginBottom: '5px'}} key={carByDate.key}>\n                              <div className=\"box-header with-border\" style={{padding: '6px'}}>\n                                <h4 className=\"box-title\" style={{\n                                  fontSize: '15px',\n                                  display: 'block'\n                                }}>\n                                  <a data-toggle=\"collapse\"\n                                   data-parent=\"#accordion\"\n                                   href={`#${slugify(carByDate.key, {remove: /[*+~.()'\"!:@]/g})}`}\n                                   aria-expanded=\"false\"\n                                   className=\"collapsed\">\n                                  {`${moment(carByDate.key, 'YYYYMMDD').format('dddd, DD MMMM YYYY')} (${carByDate.cars.length} unidades)`}\n                                  </a>\n                                </h4>\n                              </div>\n                              <div id={`${slugify(carByDate.key, {remove: /[*+~.()'\"!:@]/g})}`} className=\"panel-collapse collapse\"\n                                   aria-expanded=\"false\">\n                                <div className=\"box-body no-padding\">\n                                  <table className=\"table table-striped\">\n                                    <thead>\n                                    <tr>\n                                      <th style={{width: '10%'}}>Nº Interno</th>\n                                      <th style={{width: '15%'}}>VIN</th>\n                                      <th style={{width: '5%'}}>PATENTE</th>\n                                      <th style={{width: '10%'}}>MARCA</th>\n                                      <th style={{width: '30%'}}>DENOMINACIÓN</th>\n                                      <th style={{width: '30%'}}>COLOR</th>\n                                    </tr>\n                                    </thead>\n                                    <tbody>\n                                    {\n                                      carByDate.cars.map((car: any) => (\n                                        <tr key={car.vin}>\n                                          <td>{car.NInterno}</td>\n                                          <td>{car.vin}</td>\n                                          <td>{car.patente}</td>\n                                          <td>{car.marca}</td>\n                                          <td>{car.denominacion}</td>\n                                          <td>{car.color}</td>\n                                        </tr>\n                                      ))\n                                    }\n                                    </tbody>\n                                  </table>\n                                </div>\n                              </div>\n                            </div>\n                          ))\n                        }\n                      </div>\n                    </div>\n                    <div className=\"col col-md-6\">\n                      <strong>Total de unidades:</strong> {carsByDate.reduce((total, x: any) => (total + x.cars.length), 0)}\n                    </div>\n                    <div className=\"col-md-6 text-right\">\n                      <button className=\"btn btn-sm btn-primary\" onClick={this.downloadTemplate}>\n                        <i className=\"fa fa-fw fa-download\" /> Descargar Formato\n                      </button>\n                      <button className=\"btn btn-sm btn-default\" onClick={this.clickUploadFile} style={{marginLeft: '5px'}}>\n                        <i className=\"fa fa-fw fa-cogs\" /> Cambiar configuración\n                      </button>\n                    </div>\n                  </div>\n                  :\n                  <div className=\"row\">\n                    <div className=\"col col-md-12\">\n                      <div className=\"form-group\">\n                        {/*<label>Días que serán importardos</label>*/}\n                        <div\n                          className=\"upload-file text-center pointer\"\n                          onClick={this.clickUploadFile}\n                          onDrop={this.handleDrop}\n                          onDragOver={this.dragOverHandler}\n                          onDragEnd={this.dragEndHandler}\n                          onDragLeave={this.dragLeaveHandler}\n                          style={{\n                            backgroundColor: '#EEEEEE',\n                            border: this.state.canDrop ? '1px solid #979797' : '1px dashed #979797',\n                            padding: '100px 20px',\n                            color: this.state.canDrop ? '#aebccb' : '#6e7a89',\n                            borderRadius: '5px',\n                            marginBottom: '10px'\n                          }}>\n                          <i className=\"fa fa-2x fa-cloud-upload\"/><br/>\n                          Prueba a soltanto el excel aquí, o haz click para seleccionar el excel a cargar.\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n              }\n              <input\n                type=\"file\"\n                onChange={this.handleChangeInputFile}\n                style={{display: 'None'}}\n                ref={this.inputFile} accept=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel\"\n              />\n            </div>\n            <div className=\"box-footer text-right\">\n              <button\n                className=\"btn btn-sm btn-default\"\n                onClick={() => this.props.history.push('/planning/')}\n              >\n                Cancelar\n              </button>\n              {carsByDate.length ? <button className=\"btn btn-sm btn-primary\" style={{marginLeft: '5px'}} onClick={this.sendCreate} disabled={sending}>\n                {\n                  sending ?\n                    <React.Fragment>\n                      <i className=\"fa fa-fw fa-spin fa-spinner\"/> Importando...\n                    </React.Fragment>\n                    : 'Importar'\n                }\n              </button> : null}\n            </div>\n            {\n              loadingSettings || sending &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView/>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private clickUploadFile(): void {\n    if (this.inputFile.current) {\n      this.inputFile.current.click();\n    }\n  }\n\n  private handleDrop(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      if (dt.items.length) {\n        const file: File | null = dt.items[0].getAsFile();\n        if (file) {\n          this.processSettings(file);\n        }\n      }\n    } else {\n      if (dt.files.length) {\n        const file = dt.files[0];\n        this.processSettings(file);\n      }\n    }\n  }\n\n  private handleChangeInputFile(e: React.ChangeEvent<HTMLInputElement>): void {\n    const {files} = e.target;\n    if (files && files.length) {\n      this.processSettings(files[0]);\n    }\n  }\n\n  private dragOverHandler(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    this.setState({\n      canDrop: true\n    });\n  }\n\n  private dragEndHandler(e: React.DragEvent<HTMLDivElement>): void {\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      // Use DataTransferItemList interface to remove the drag data\n      for (let i = 0; i < dt.items.length; i++) {\n        dt.items.remove(i);\n      }\n    } else {\n      // Use DataTransfer interface to remove the drag data\n      e.dataTransfer.clearData();\n    }\n  }\n\n  private dragLeaveHandler(): void {\n    this.setState({\n      canDrop: false\n    });\n  }\n\n  private downloadTemplate(): void {\n    /* make the worksheet */\n    const ws = XLSX.utils.json_to_sheet([{\n      NInterno: '',\n      vin: '',\n      marca: '',\n      patente: '',\n      denominacion: '',\n      color: '',\n      propiedad: '',\n      tipo: '',\n      fecha: ''\n    }]);\n    /* add to workbook */\n    const wb = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(wb, ws, 'Autos');\n    /* generate an XLSX file */\n    XLSX.writeFile(wb, 'template_planning_settings.xlsx');\n  }\n\n  private processSettings(file: File): void {\n    this.setState({\n      loadingSettings: true\n    });\n    if (['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'].includes(file.type)) {\n      const reader = new FileReader();\n      const rABS = !!reader.readAsBinaryString;\n      reader.onload = (e: any) => {\n        let data = e.target.result;\n        if (!rABS) {\n          data = new Uint8Array(data);\n        }\n        const workbook: XLSX.WorkBook = XLSX.read(data, {\n          type: rABS ? 'binary' : 'array',\n          cellDates: true\n        });\n        const excelData = workbook.Sheets.hasOwnProperty('Autos') ? XLSX.utils.sheet_to_json(workbook.Sheets.Autos) : [];\n        const carsByDate: any = {};\n        if (excelData.length >= 1) {\n          excelData.forEach((item: any, index: number) => {\n            const date = moment(workbook.Sheets.Autos[`I${index + 2}`].v);\n            if(date.isValid()){\n              const key: string = date.format('YYYYMMDD');\n              if (!carsByDate.hasOwnProperty(key)) {\n                carsByDate[key] = {\n                  key,\n                  cars: []\n                };\n              }\n              carsByDate[key].cars.push({\n                NInterno: item.NInterno,\n                vin: item.vin,\n                marca: item.marca,\n                patente: item.patente,\n                denominacion: item.denominacion,\n                color: item.color,\n                propiedad: item.propiedad,\n                tipo: item.tipo,\n                date\n              });\n            }\n          });\n          this.setState({\n            loadingSettings: false,\n            carsByDate: Object.keys(carsByDate)\n              .map((key) => ({key, ...carsByDate[key]}))\n              .sort((a, b) => {\n                if (a.key < b.key) return 1;\n                if (a.key > b.key) return -1;\n                return 0;\n              })\n              .reverse()\n          });\n        } else {\n          swal(\n            'Importador de configuración',\n            `\"${file.name}\" no cumple con los requisitos mínimos o no tiene autos.`,\n            'error'\n          );\n          this.setState({\n            loadingSettings: false\n          });\n        }\n      };\n      if (rABS) {\n        reader.readAsBinaryString(file);\n      } else {\n        reader.readAsArrayBuffer(file);\n      }\n      if (this.inputFile.current) {\n        this.inputFile.current.value = '';\n      }\n    }\n  }\n\n  private sendCreate(): void {\n    const {carsByDate} = this.state;\n    const { history } = this.props;\n    this.setState({\n      sending: true\n    });\n    const api = new ApiService();\n    api.getSource();\n    api\n      .importPlanning({\n        carsByDate\n      })\n      .then((response: any) => {\n        const {message} = response.data;\n        setTimeout(() => {\n          swal('Envió planificación', message, 'success');\n        }, 200);\n        history.push('/planning/');\n        this.setState({\n          sending: false\n        });\n      })\n      .catch((e) => {\n        console.log('e', e);\n        swal('Envió planificación', 'Se produjo un error al importar la planificación.', 'error');\n        this.setState({\n          sending: false\n        });\n      });\n\n  }\n\n}\n\nconst mapStateToProps = (state: { planning: IPlanningState }) => {\n  return {\n    planning: state.planning\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{ planning: IPlanningState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(PlanningImportView);\n","import * as React from \"react\";\nimport {RouteComponentProps} from \"react-router\";\nimport {Dispatch} from \"redux\";\nimport {connect} from \"react-redux\";\nimport AppContainer from \"../../container/AppContainer\";\nimport ModalView from \"../Modal/ModalView\";\nimport {getPlanningAction, IPlanningState, PlanningReduxAction} from \"../../actions/planning.action\";\nimport {IWindow} from \"../../interfaces/window\";\nimport {ErrorInfo} from \"react\";\nimport * as Raven from \"raven-js\";\nimport * as moment from \"moment\";\nimport Paginator from \"../Utils/Paginator\";\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\nimport { io } from \"socket.io-client\";\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<PlanningReduxAction>;\n  planning: IPlanningState;\n\n  getPlanningAction(page: number): PlanningReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass PlanningListView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de planificación';\n    this.changePage = this.changePage.bind(this);\n    this.import = this.import.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const {pagination} = this.props.planning;\n    // set the title of the page\n    this.props.getPlanningAction(pagination.page);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {token: (window.user as any).token}\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {room: `planning-list-${window.user.team._id}`});\n    });\n    this.socket.on('REFRESH', (): void => {\n        this.props.getPlanningAction(pagination.page);\n    });\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if(this.props.planning.pagination !== prevProps.planning.pagination){\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    window.scrollTo(0, 0);\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.planning.source) {\n      this.props.planning.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {loading, plannings, pagination} = this.props.planning;\n    return (\n      <AppContainer title=\"\" cMenu=\"4\" cSubMenu=\"4.1\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Planificación <small>{pagination.count}</small></h3>\n              <div className=\"box-tools pull-right\">\n                <button className=\"btn btn-sm btn-success\" onClick={this.import}>Importar</button>\n              </div>\n            </div>\n            <div className=\"box-body\">\n              {\n                !loading && !plannings.length?\n                  <div className=\"row\">\n                    <div className=\"col-md-12\">\n                      <p>No se han encontrado resultados.</p>\n                    </div>\n                  </div>\n                  :null\n              }\n              {\n                plannings.length ?\n                  <table className=\"table\">\n                    <thead>\n                      <tr>\n                        <th>VIN</th>\n                        <th>Marca</th>\n                        <th>Denominación</th>\n                        <th>Color</th>\n                        <th>Fecha</th>\n                      </tr>\n                    </thead>\n                    <tbody>\n                      {\n                        plannings.map((item)=>(\n                          <tr key={item.car.vin}>\n                            <td>{item.car.vin}</td>\n                            <td>{item.car.brand}</td>\n                            <td>{item.car.denomination}</td>\n                            <td>{item.car.color}</td>\n                            <td>{moment(item.date).format(\"DD-MM-YYYY\")}</td>\n                          </tr>\n                        ))\n                      }\n                    </tbody>\n                  </table>\n                  : null\n              }\n            </div>\n            {\n              pagination.pages > 1 &&\n                <div className=\"box-footer text-right\">\n                  <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                </div>\n            }\n            {\n              loading &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n  private changePage(page: number): void {\n    // change the page\n    this.props.getPlanningAction(page);\n  }\n\n  private import(): void {\n    this.props.history.push('/planning/import/');\n  }\n}\n\nconst mapStateToProps = (state: { planning: IPlanningState }) => {\n  return {\n    planning: state.planning\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getPlanningAction: (page: number) => dispatch(getPlanningAction(page)),\n  };\n};\n\nexport default connect<{planning: IPlanningState}, {dispatch: any}, IPropsType>(mapStateToProps, mapDispatchToProps)(PlanningListView);\n","import {AxiosError, AxiosResponse, CancelTokenSource, default as Axios} from \"axios\";\nimport {\n  IPlanning\n} from '../../../../../src/planning/interfaces/planning.interface';\nimport {Dispatch} from \"redux\";\nimport ApiService from \"../utils/axios\";\n\nexport interface IPlanningState {\n  plannings: IPlanning[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface ICancelRequest {\n  type: '/PLANNING/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/PLANNING/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/PLANNING/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/PLANNING/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IChangePage {\n  type: '/PLANNING/CHANGE_PAGE';\n  payload: {\n    page: number;\n  };\n}\n\nexport function changePageAction(page: number): IChangePage {\n  return {\n    type: '/PLANNING/CHANGE_PAGE',\n    payload: {\n      page\n    }\n  };\n}\n\ninterface ILoadPlanning {\n  type: '/PLANNING/LOAD_PLANNING';\n  payload: {\n    plannings: any;\n    count: number;\n    pages: number\n  };\n}\n\nexport function loadPlanningAction(plannings: any, count: number, pages: number): ILoadPlanning {\n  return {\n    type: '/PLANNING/LOAD_PLANNING',\n    payload: {\n      plannings,\n      count,\n      pages\n    }\n  };\n}\n\nexport function getPlanningAction(nextPage: number) {\n  return (dispatch: Dispatch<PlanningReduxAction>, getState: () => {labels: IPlanningState}) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    if (nextPage && nextPage !== state.labels.pagination.page) {\n      dispatch(isLoadingAction(true));\n    }\n    dispatch(cancelRequestAction(api.getSource()));\n    const page = nextPage ? nextPage : state.labels.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n    api.getPlanning(page)\n      .then((response: AxiosResponse) => {\n        dispatch(loadPlanningAction(response.data.results, response.data.count, response.data.pages));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\nexport type PlanningReduxAction =\n  ILoadPlanning |\n  IChangePage |\n  IIsLoading |\n  ICancelRequest;\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Link } from 'react-router-dom';\nimport { Dispatch } from 'redux';\nimport { FormAction, submit } from 'redux-form';\nimport * as swal from 'sweetalert';\nimport { IReason } from '../../../../../../src/request/interfaces/reason.interface';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport {\n  createReasonThunkAction,\n  deleteReasonThunkAction,\n  getReasonsThunkAction, updateReasonThunkAction\n} from '../../actions/reasons.actions';\nimport { IReasonsState, ReasonsReduxActions } from '../../actions/reasons.types';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { hasPermission, showModal, statusFooterButttonsModal } from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport ReasonForm from './ReasonForm';\nimport ShowIf from '../Utils/ShowIf';\nimport { io } from \"socket.io-client\";\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<ReasonsReduxActions | FormAction>;\n  reasons: IReasonsState;\n\n  getReasonsThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean): ReasonsReduxActions;\n  createReasonThunkAction(reason: IReason): ReasonsReduxActions;\n  updateReasonThunkAction(reason: IReason): ReasonsReduxActions;\n  deleteReasonThunkAction(reason: IReason): ReasonsReduxActions;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass RequestReasonListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  private socket: Socket;\n  readonly state = {\n    error: null,\n    exporing: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de Motivos';\n    this.changePage = this.changePage.bind(this);\n    this.createReason = this.createReason.bind(this);\n    this.processCreateReason = this.processCreateReason.bind(this);\n    this.updateReaon = this.updateReaon.bind(this);\n    this.processUpdateReason = this.processUpdateReason.bind(this);\n    this.deleteReason = this.deleteReason.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const { pagination } = this.props.reasons;\n    const { orderBy, orderType } = this.props.reasons.options;\n    this.props.getReasonsThunkAction(pagination.page, orderBy, orderType);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: { token: (window.user as any).token }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `reasons-list-${window.user.team._id}` });\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update) {\n        const { pagination } = this.props.reasons;\n        const { orderBy, orderType } = this.props.reasons.options;\n        this.props.getReasonsThunkAction(pagination.page, orderBy, orderType, true);\n      }\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if (this.props.reasons.pagination !== prevProps.reasons.pagination) {\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.reasons.source) {\n      this.props.reasons.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    // const { exporing } = this.state;\n    const { loading, reasons, pagination } = this.props.reasons;\n    const canEdit = hasPermission(window.user, 'adminRequest');\n    const canDelete = hasPermission(window.user, 'adminRequest');\n    return (\n      <AppContainer title=\"\" cMenu=\"3\" cSubMenu=\"3.3\" cAction=\"Motivos\">\n        <section className=\"content\">\n          <div className=\"row\">\n            <div className=\"col-md-3\">\n              <div className=\"list-group\">\n                <Link to=\"/requests/settings/reasons/\" className=\"list-group-item active\">\n                  Motivos\n                </Link>\n                <Link to=\"/requests/settings/channels/\" className=\"list-group-item \">\n                  Canales\n                </Link>\n                <Link to=\"/requests/settings/status/\" className=\"list-group-item \">\n                  Estados\n                </Link>\n                <Link to=\"/requests/settings/operations-type/\" className=\"list-group-item \">\n                  Tipos de operación\n                </Link>\n                <Link to=\"/requests/settings/payment-methods/\" className=\"list-group-item\">\n                  Métodos de pago\n                </Link>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone-type/' className='list-group-item'>\n                    Tipos de hitos\n                  </Link>\n                </ShowIf>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone/' className='list-group-item'>\n                    Hitos\n                  </Link>\n                </ShowIf>\n              </div>\n            </div>\n            <div className=\"col-md-9\">\n              <div className=\"box\">\n                <div className=\"box-header with-border\">\n                  <h3 className=\"box-title\">Motivos <small>{pagination.count}</small></h3>\n                  <div className=\"box-tools pull-right\">\n                    {\n                      hasPermission(window.user, 'addVenue') ?\n                        <button className=\"btn btn-sm btn-success\"\n                        onClick={this.createReason}\n                        ><i className=\"fa fa-plus\" /> Agregar</button>\n                        : null\n                    }\n                  </div>\n                </div>\n                <div className=\"box-body table-responsive no-padding\">\n                  <table className=\"table table-andes table-striped\">\n                    <thead>\n                      <tr>\n                        <th style={{ width: '50%' }} className=\"middle\">Nombre</th>\n                        <th style={{ width: '15%' }} className=\"middle-center\">Archivos</th>\n                        <th style={{ width: '15%' }} className=\"middle-center\">Preguntas</th>\n                        {/* <th style={{ width: '20%' }} className=\"middle hidden-xs\">Modificado</th> */}\n                        {\n                          canEdit ?\n                            <th style={{ width: '1%' }} className=\"width-10\" /> : null\n                        }\n                        {\n                          canDelete ?\n                            <th style={{ width: '1%' }} className=\"width-10\" /> : null\n                        }\n                      </tr>\n                    </thead>\n                    <tbody>\n                      {\n                        reasons.map((reason) => {\n                          return (\n                            <tr key={reason._id}>\n                              <td>{reason.name}</td>\n                              <td className=\"middle-center\">\n                                <i\n                                  className={\n                                    reason.file.active ?\n                                      'fa fa-check-circle text-green' :\n                                      'fa fa-times-circle text-red'\n                                  }\n                                />\n                              </td>\n                              <td className=\"middle-center\">{reason.questions.length}</td>\n                              {\n                                canEdit ?\n                                  <td\n                                    className=\"middle text-blue pointer\"\n                                    onClick={() => this.updateReaon(reason)}\n                                  >\n                                    <i className=\"fa fa-pencil\" />\n                                  </td> : null\n                              }\n                              {\n                                canDelete ?\n                                  <td\n                                    className={canDelete ? 'middle text-red pointer' : 'middle text-muted not-allowed'}\n                                    // className={'middle text-red pointer'}\n                                    onClick={canDelete ? () => this.deleteReason(reason) : undefined}\n                                  >\n                                    <i className=\"fa fa-minus-circle\" />\n                                  </td> : null\n                              }\n                            </tr>\n                          );\n                        })\n                      }\n                    </tbody>\n                  </table>\n                </div>\n                {\n                  pagination.pages > 1 &&\n                  <div className=\"box-footer text-right\">\n                    <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                  </div>\n                }\n                {\n                  loading &&\n                  <div className=\"overlay\">\n                    <i className=\"fa fa-spinner fa-spin text-purple\" />\n                  </div>\n                }\n              </div>\n            </div>\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private createReason(): void {\n    this.props.loadDataAction(\n      'Agregar Motivo',\n      <ReasonForm\n        initialValues={{ update: false }}\n        onSubmit={this.processCreateReason}\n      />,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={() => this.props.dispatch(submit('reasonForm'))}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processCreateReason(reason: IReason): void {\n    statusFooterButttonsModal(true);\n    this.props.createReasonThunkAction(reason);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private updateReaon(reason: IReason): void {\n    this.props.loadDataAction(\n      'Editar Motivo',\n      <ReasonForm\n        initialValues={{ update: false, ...reason }}\n        onSubmit={this.processUpdateReason}\n      />,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={() => this.props.dispatch(submit('reasonForm'))}>Editar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processUpdateReason(reason: any): void {\n    statusFooterButttonsModal(true);\n    this.props.updateReasonThunkAction(reason);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private deleteReason(reason: IReason): void {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el motivo: ${reason.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteReasonThunkAction(reason);\n      }\n    });\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    const { orderBy, orderType } = this.props.reasons.options;\n    this.props.getReasonsThunkAction(page, orderBy, orderType);\n  }\n}\n\nconst mapStateToProps = (state: { reasons: IReasonsState }) => {\n  return {\n    reasons: state.reasons\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getReasonsThunkAction: (nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) => dispatch(getReasonsThunkAction(nextPage, orderBy, orderType, hideLoading)),\n    createReasonThunkAction: (reason: IReason) => dispatch(createReasonThunkAction(reason)),\n    updateReasonThunkAction: (reason: IReason) => dispatch(updateReasonThunkAction(reason)),\n    deleteReasonThunkAction: (reason: IReason) => dispatch(deleteReasonThunkAction(reason)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{ reasons: IReasonsState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(RequestReasonListView);\n","import Axios, { AxiosError, AxiosResponse, CancelTokenSource } from 'axios';\nimport { Dispatch } from 'redux';\nimport { IReason } from '../../../../../src/request/interfaces/reason.interface';\nimport ApiService from '../utils/axios';\nimport {\n  ICancelReason,\n  IChangeOrderReason,\n  ICreateReason,\n  IDeleteReason,\n  IIsLoadingReason,\n  ILoadReasons,\n  IReasonsState,\n  IUpdateReason,\n  ReasonsReduxActions, REASON_CANCEL_REASON,\n  REASON_CHANGE_ORDER,\n  REASON_CREATE_REASON,\n  REASON_DELETE_REASON,\n  REASON_IS_LOADING,\n  REASON_LOAD_REASONS,\n  REASON_UDPATE_REASON\n} from './reasons.types';\n\nexport function cancelReasonAction(source: CancelTokenSource): ICancelReason {\n  return {\n    type: REASON_CANCEL_REASON,\n    payload: {\n      source\n    }\n  };\n}\n\nexport function isLoadingReasonAction(loading: boolean): IIsLoadingReason {\n  return {\n    type: REASON_IS_LOADING,\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function loadReasonsAction(reasons: any[], count: number, pages: number, page: number): ILoadReasons {\n  return {\n    type: REASON_LOAD_REASONS,\n    payload: {\n      reasons,\n      count,\n      pages,\n      page\n    }\n  };\n}\n\n\nexport function createReasonItemAction(reason: IReason): ICreateReason {\n  return {\n    type: REASON_CREATE_REASON,\n    payload: {\n      reason\n    }\n  };\n}\n\nexport function updateReasonItemAction(reason: IReason): IUpdateReason {\n  return {\n    type: REASON_UDPATE_REASON,\n    payload: {\n      reason\n    }\n  };\n}\n\nexport function deleteReasonItemAction(reason: IReason): IDeleteReason {\n  return {\n    type: REASON_DELETE_REASON,\n    payload: {\n      reason\n    }\n  };\n}\n\nexport function deleteReasonAction(reason: IReason): IDeleteReason {\n  return {\n    type: REASON_DELETE_REASON,\n    payload: {\n      reason\n    }\n  };\n}\n\nexport function changeOrderReasonAction(orderBy: string, orderType: string): IChangeOrderReason {\n  return {\n    type: REASON_CHANGE_ORDER,\n    payload: {\n      orderBy,\n      orderType\n    }\n  };\n}\n\nexport function getReasonsThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) {\n  return (dispatch: Dispatch<ReasonsReduxActions>, getState: () => { requests: IReasonsState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(isLoadingReasonAction(!hideLoading));\n    const page = nextPage ? nextPage : state.requests.pagination.page;\n    dispatch(changeOrderReasonAction(orderBy, orderType));\n    dispatch(cancelReasonAction(api.getSource()));\n    Axios\n      .all([\n        api.getReasons({ page, orderBy, orderType })\n      ])\n      .then(Axios.spread((reasons) => {\n        const { data } = reasons;\n        dispatch(loadReasonsAction(data.results, data.count, data.pages, page));\n        // dispatch(loadCarriersReasonAction(carriers.data.results));\n        dispatch(isLoadingReasonAction(false));\n      }))\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingReasonAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function createReasonThunkAction(reason: IReason) {\n  return (dispatch: Dispatch<ReasonsReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.createReason(reason)\n      .then((response: AxiosResponse) => {\n        console.log('response', response);\n        // dispatch(updateReasonItemAction(idReason, data));\n      });\n  };\n}\n\nexport function updateReasonThunkAction(reason: IReason) {\n  return (dispatch: Dispatch<ReasonsReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.updateReason(reason)\n      .then((response: AxiosResponse) => {\n        console.log('response', response);\n        // dispatch(updateReasonItemAction(idReason, data));\n      });\n  };\n}\n\nexport function deleteReasonThunkAction(reason: IReason) {\n  return (dispatch: Dispatch<ReasonsReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.deleteReason(reason)\n      .then((response: AxiosResponse) => {\n        console.log('response', response);\n        // dispatch(updateReasonItemAction(idReason, data));\n      });\n  };\n}\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { Field, FieldArray, InjectedFormProps, reduxForm, WrappedFieldArrayProps } from 'redux-form';\nimport { IReasonsState } from '../../actions/reasons.types';\nimport BootstrapSwitchField from '../Utils/forms/BootsrapSwitchField';\nimport CheckBoxField from '../Utils/forms/CheckBoxField';\nimport InputField from '../Utils/forms/InputField';\nimport { inputStringRequired } from '../Utils/forms/validations';\n\nconst renderQuestion: React.FunctionComponent<WrappedFieldArrayProps<{}>> = ({\n  fields,\n  meta: { error, submitFailed }\n}) => {\n  return (\n    <React.Fragment>\n      {\n        fields.length === 0 ?\n          <div className=\"col-md-12\">\n            <p\n              className=\"text-center text-muted\"\n              style={{padding: '20px 0'}}\n            >\n              No hay preguntas personalizadas para agregar una <a href=\"javascript:void(0)\" onClick={() => fields.push({})}>haz click aquí.</a>\n            </p>\n          </div> :\n          fields.map((question, index) => {\n            return (\n              <div style={{\n                borderBottom: index + 1 !== fields.length ? '1px solid #ededed' : '',\n                margin: '0',\n                marginBottom:  index + 1 !== fields.length ? '5px': '0'\n              }}\n                key={index} className=\"row\"\n              >\n                <div className=\"col-md-11 col-sm-11 col-xs-10\">\n                  <Field\n                    name={`${question}.name`}\n                    label={`Pregunta ${index + 1} *`}\n                    component={InputField}\n                    validate={[inputStringRequired]}\n                  />\n                  <Field\n                    name={`${question}.required`}\n                    label=\"Hacer obligatoria\"\n                    type=\"checkbox\"\n                    component={CheckBoxField}\n                    validate={[]}\n                  />\n                </div>\n                <div className=\"col-md-1 col-sm-1 col-xs-2 text-left\" style={{ paddingLeft: '0' }}>\n                  <button\n                    type=\"button\"\n                    style={{ marginTop: '25px' }}\n                    className=\"btn btn-sm btn-danger\"\n                    onClick={() => fields.remove(index)}\n                  >\n                    <i className=\"fa fa-trash\" />\n                  </button>\n                </div>\n                {/* <div className=\"col-md-2 col-sm-2 col-xs-2\" /> */}\n              </div>\n            );\n          })\n      }\n      {\n        fields.length >= 1 ?\n          <div className=\"col-md-12 col-sm-12 col-xs-12 text-right\">\n            <button\n              type=\"button\"\n              className=\"btn btn-sm btn-success\"\n              onClick={() => fields.push({})}\n            >\n              <i className=\"fa fa-fw fa-plus\" /> Agregar pregunta\n        </button>\n            {submitFailed && error && <span>{error}</span>}\n          </div>\n          : null\n      }\n    </React.Fragment>\n  );\n};\n\ninterface IPropsType extends InjectedFormProps {\n  update: boolean;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass Form extends React.Component<IPropsType, IStateType> {\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n  public render(): React.ReactElement<IPropsType> {\n    const { handleSubmit, valid , submitFailed} = this.props;\n    return (\n      <form onSubmit={handleSubmit}>\n        <div className=\"row\">\n          <div className=\"col-md-10\">\n            <Field\n              name=\"name\"\n              label=\"Nombre *\"\n              placeholder=\"Nombre\"\n              type=\"text\"\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>\n          <div className=\"col-md-4\">\n            <Field\n              name=\"file.active\"\n              label=\"Requerir archivos\"\n              type=\"checkbox\"\n              component={BootstrapSwitchField}\n              validate={[]}\n            />\n          </div>\n          <div className=\"col-md-8\">\n            <Field\n              name=\"file.required\"\n              label=\"Archivos obligatorios\"\n              type=\"checkbox\"\n              component={BootstrapSwitchField}\n              validate={[]}\n            />\n          </div>\n          <div className=\"col-md-12\" style={{marginTop: '10px'}}>\n            <h4>Preguntas personalizadas</h4>\n          </div>\n          <FieldArray\n            name=\"questions\"\n            component={renderQuestion}\n          />\n          {\n            submitFailed && valid === false &&\n            <div className=\"col-md-12\">\n              <div\n                className=\"alert alert-danger\"\n                style={{marginTop: '20px'}}\n              >\n                Todos los campos con * son obligatorios\n              </div>\n            </div>\n          }\n        </div>\n      </form>\n    );\n  }\n}\n\nconst ReasonForm = reduxForm({\n  form: 'reasonForm'\n})(Form);\n\nconst mapStateToProps = (state: { reasons: IReasonsState }) => {\n  return {\n    reasons: state.reasons\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{ reasons: IReasonsState }, { dispatch: any }, IPropsType | {}>(mapStateToProps, mapDispatchToProps)(ReasonForm);","import * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport {IBaseRegion, IRegion} from '../../../../../../src/app/interfaces/region.interface';\n\nimport {loadDataAction, ModalReduxAction} from '../../actions/modal.actions';\nimport AppContainer from '../../container/AppContainer';\nimport {IWindow} from '../../interfaces/window';\nimport {hasPermission} from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport RegionsFormView from './RegionsFormView';\nimport {\n  changeTempRegionAction,\n  createRegionAction,\n  deleteRegionAction,\n  getRegionsAction,\n  IRegionsState,\n  RegionReduxAction,\n  updateRegionAction\n} from \"../../actions/regions.actions\";\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\n\ninterface IPropsType extends RouteComponentProps<{ region: string }> {\n  dispatch: Dispatch<RegionReduxAction>;\n  regions: IRegionsState;\n\n  createRegionAction(): RegionReduxAction;\n  updateRegionAction(): RegionReduxAction;\n\n  deleteRegionAction(id: string): RegionReduxAction;\n  changeTempRegionAction(region: IBaseRegion, delay?: boolean): RegionReduxAction;\n  getRegionsAction(page: number): RegionReduxAction;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass RegionsListView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de regiones';\n    this.createRegion = this.createRegion.bind(this);\n    this.processCreateRegion = this.processCreateRegion.bind(this);\n    this.updateRegion = this.updateRegion.bind(this);\n    this.processUpdateRegion = this.processUpdateRegion.bind(this);\n    this.deleteRegion = this.deleteRegion.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const {pagination} = this.props.regions;\n    this.props.getRegionsAction(pagination.page);\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.regions.source) {\n      this.props.regions.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {loading, regions, pagination} = this.props.regions;\n    return (\n      <AppContainer title=\"\" cMenu=\"10\" cSubMenu=\"10.9\" cAction=\"Listado\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\"><h3 className=\"box-title\">Regiones <small>{pagination.count}</small></h3>\n              {\n                hasPermission(window.user, 'addRegion') ?\n                  <div className=\"box-tools pull-right\">\n                    <button className=\"btn btn-sm btn-success\" onClick={this.createRegion}>Agregar</button>\n                  </div>\n                  : null\n              }\n            </div>\n            <div className=\"box-body no-padding\">\n              <table className=\"table table-andes table-striped\">\n                <thead>\n                  <tr>\n                    <th style={{width: '60%'}} className=\"middle\">Nombre</th>\n                    <th style={{width: '20%'}} className=\"middle hidden-xs\">Modificado</th>\n                    {\n                      hasPermission(window.user, 'changeRegion') ?\n                        <th style={{width: '1%'}} className=\"width-10\"/> : null\n                    }\n                    {\n                      hasPermission(window.user, 'deleteRegion') ?\n                        <th style={{width: '1%'}} className=\"width-10\"/> : null\n                    }\n                  </tr>\n                </thead>\n                <tbody>\n                  {\n                    !loading && !regions.length?\n                      <tr>\n                        <td\n                          colSpan={2 + (hasPermission(window.user, 'deleteRegion') ? 1 : 0) +( hasPermission(window.user, 'deleteRegion') ? 1 : 0)}\n                        >\n                          No se han creado regiones\n                        </td>\n                      </tr>\n                    :null\n                  }\n                  {\n                    regions.map((region: IRegion) => {\n                      return (\n                        <tr\n                          key={region._id}\n                          id={`region-${region._id}`}\n                          className={'background-transition'}\n                        >\n                          <td className=\"middle\">{region.name}</td>\n                          <td className=\"middle hidden-xs\">{moment(region.updatedAt).format('LLL')}</td>\n                          {\n                            hasPermission(window.user, 'changeRegion') ?\n                              <td\n                                className=\"middle text-blue pointer\"\n                                onClick={() => this.updateRegion(region)}\n                              >\n                                <i className=\"fa fa-pencil\"/>\n                              </td> : null\n                          }\n                          {\n                            hasPermission(window.user, 'deleteRegion') ?\n                              <td\n                                className={'middle text-red pointer'}\n                                onClick={() => this.deleteRegion(region)}\n                              ><i className=\"fa fa-minus-circle\"/></td> : null\n                          }\n                        </tr>\n                      );\n                    })\n                  }\n                </tbody>\n              </table>\n            </div>\n            {\n              pagination.pages > 1 &&\n                <div className=\"box-footer text-right\">\n                  <Paginator changePage={this.props.getRegionsAction} page={pagination.page} pages={pagination.pages} />\n                </div>\n            }\n            {\n              loading &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private createRegion(): void {\n    this.props.changeTempRegionAction({\n      _id: '',\n      name: '',\n      code: ''\n    });\n    this.props.loadDataAction(\n      'Agregar Region',\n      <RegionsFormView/>,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processCreateRegion}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processCreateRegion(): void {\n    const {tempRegion} = this.props.regions;\n    if (!tempRegion.name || !tempRegion.name.trim()) {\n      swal('Agregar Region', 'El nombres es requerido', 'error');\n    } else {\n      this.props.createRegionAction();\n    }\n  }\n\n  private updateRegion(region: IRegion): void {\n    const {_id, name, code} = region;\n    this.props.changeTempRegionAction({_id, name, code});\n    this.props.loadDataAction(\n      'Editar Region',\n      <RegionsFormView update={true}/>,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processUpdateRegion}>Editar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processUpdateRegion(): void {\n    const {tempRegion} = this.props.regions;\n    if (!tempRegion.name || !tempRegion.name.trim()) {\n      swal('Editar Region', 'El nombres es requerido', 'error');\n    } else {\n      this.props.updateRegionAction();\n    }\n  }\n\n  private deleteRegion(region: IRegion): void {\n     // ask if you are sure that you are going to delete the region?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar la región ${region.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteRegionAction(region._id);\n      }\n    });\n  }\n}\n\nconst mapStateToProps = (state: { regions: IRegionsState }) => {\n  return {\n    regions: state.regions\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getRegionsAction: (page: number) => dispatch(getRegionsAction(page)),\n    createRegionAction: () => dispatch(createRegionAction()),\n    updateRegionAction: () => dispatch(updateRegionAction()),\n    deleteRegionAction: (id: string) => dispatch(deleteRegionAction(id)),\n    changeTempRegionAction: (region: IBaseRegion, delay?: boolean) => dispatch(changeTempRegionAction(region, delay)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{regions: IRegionsState}, {dispatch: any}, IPropsType>(mapStateToProps, mapDispatchToProps)(RegionsListView);\n","import * as React from 'react';\nimport {connect} from 'react-redux';\nimport {\n  IBaseRegion\n} from '../../../../../../src/app/interfaces/region.interface';\nimport {\n  RegionReduxAction,\n  changeTempRegionAction,\n  IRegionsState\n} from '../../actions/regions.actions';\n\n\ninterface IPropsType {\n  regions?: IRegionsState;\n  update?: boolean;\n  changeTempRegionAction?: (carrier: IBaseRegion, delay?: boolean) => RegionReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass RegionsFormView extends React.Component<IPropsType, IStateType> {\n\n  render(): React.ReactElement<IPropsType> | null {\n    if (this.props.regions && this.props.changeTempRegionAction) {\n      const {tempRegion} = this.props.regions;\n      return (\n        <div className=\"row\">\n          <div className=\"col-md-12\">\n            <div className=\"form-group\">\n              <label>Nombre</label>\n              <input\n                type=\"text\"\n                name=\"name\"\n                className=\"form-control\"\n                maxLength={50}\n                value={tempRegion ? tempRegion.name : ''}\n                onChange={\n                  (e: React.ChangeEvent<HTMLInputElement>) => this.props.changeTempRegionAction!({\n                    ...tempRegion,\n                    name: e.target.value.trim()\n                  })\n                }\n              />\n            </div>\n            <div className=\"form-group\">\n              <label>Código</label>\n              <input\n                type=\"text\"\n                name=\"code\"\n                className=\"form-control\"\n                maxLength={50}\n                value={tempRegion ? tempRegion.code : ''}\n                onChange={\n                  (e: React.ChangeEvent<HTMLInputElement>) => this.props.changeTempRegionAction!({\n                    ...tempRegion,\n                    code: e.target.value.trim()\n                  })\n                }\n              />\n            </div>\n          </div>\n        </div>\n      );\n    }\n    return null;\n  }\n}\n\nconst mapStateToProps = (state: { regions: IRegionsState }) => {\n  return {\n    regions: state.regions\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    changeTempRegionAction: (carrier: IBaseRegion, delay?: boolean) => dispatch(changeTempRegionAction(carrier, delay))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(RegionsFormView);\n","import { AxiosError, AxiosResponse, default as Axios } from 'axios';\nimport * as React from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport * as swal from 'sweetalert';\nimport { debounce } from 'throttle-debounce';\nimport * as uuid from 'uuid';\nimport { IReason } from '../../../../../../src/request/interfaces/reason.interface';\nimport { ISalesChannel } from '../../../../../../src/request/interfaces/salesChannel.interface';\nimport { IInventoryState } from '../../actions/inventory.actions';\nimport AppContainer from '../../container/AppContainer';\nimport ApiService from '../../utils/axios';\nimport AutoCompleteInput from '../Utils/AutoCompleteInput';\nimport BootstrapSelect from '../Utils/BootstrapSelect';\nimport MultiUploadFiles, { imageStatus } from '../Utils/MultiUploadFiles';\nimport ShowIf from '../Utils/ShowIf';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport { IRequestSetting } from '../../../../../../src/app/interfaces/teamSetting.interface';\nimport { IOperationType } from '../../../../../../src/request/interfaces/operationType.interface';\nimport { parseReplicableURL } from '../../utils/common';\nimport { requestSettings } from './defaults';\n\n\ninterface IPropsType extends RouteComponentProps<{}> {\n}\n\ninterface INewCar {\n  brand: string;\n  brands: any[];\n  denomination: string;\n  denominations: any[];\n  material: string;\n  materials: any[];\n  color: string;\n  amount: number;\n  observation: string;\n  priority: boolean;\n  files: any[];\n  answers: any[];\n  equipment: boolean;\n  washed: boolean;\n  reason: string;\n}\n\ninterface IStateType {\n  newCar: INewCar;\n  cars: any[];\n  sellerText: string;\n  venue: string;\n  venues: any[];\n  reasons: IReason[];\n  channels: ISalesChannel[];\n  operationTypes: IOperationType[];\n  requestSettings: IRequestSetting;\n  channel: string;\n  operationType: string;\n  fleet: boolean;\n  loading: boolean;\n  error: Error | null;\n}\n\nconst initialNewCar = {\n  brand: '',\n  brands: [],\n  denomination: '',\n  denominations: [],\n  material: '',\n  materials: [],\n  files: [],\n  answers: [],\n  color: '',\n  amount: 1,\n  observation: '',\n  reason: '',\n  priority: false,\n  equipment: false,\n  washed: false\n};\n\nclass RequestCreateView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  readonly api: ApiService;\n\n  readonly state: IStateType = {\n    newCar: initialNewCar,\n    cars: [],\n    venue: '',\n    sellerText: '',\n    venues: [],\n    reasons: [],\n    channels: [],\n    requestSettings,\n    operationTypes: [],\n    operationType: '',\n    loading: false,\n    fleet: false,\n    channel: '',\n    error: null,\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Crear solicitud';\n    this.cancel = this.cancel.bind(this);\n    this.addCar = this.addCar.bind(this);\n    this.deleteCar = this.deleteCar.bind(this);\n    this.searchReason = this.searchReason.bind(this);\n    this.createRequest = this.createRequest.bind(this);\n    this.loadBaseData = this.loadBaseData.bind(this);\n    this.changeNewCar = this.changeNewCar.bind(this);\n    this.changeVenue = this.changeVenue.bind(this);\n    this.changeNumberNewCar = this.changeNumberNewCar.bind(this);\n    this.changeBooleanNewCar = this.changeBooleanNewCar.bind(this);\n    this.changeFleet = this.changeFleet.bind(this);\n    this.search = debounce(500, this.search.bind(this));\n    this.api = new ApiService();\n  }\n\n  public componentWillMount(): void {\n    window.scrollTo(0, 0);\n    this.loadBaseData();\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    const $amount: any = $('#amount');\n    $amount.TouchSpin({\n      initval: 1,\n      min: 1,\n      max: 50\n    }).on('change', () => {\n      this.changeNumberNewCar('amount', parseInt($amount.val(), 10));\n    });\n    $('.bootstrap-touchspin')\n      .addClass('input-group-sm');\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { newCar, cars, requestSettings, loading, venues, reasons, channel, channels, operationTypes, operationType } = this.state;\n    const vehiclesView = this.props.location.pathname === '/requests/vehicles/create/';\n    const filesCompleted = newCar.files.filter((file: any) => file.status === imageStatus.complete);\n    const isUploadingFiles = newCar.files.length > 0 && filesCompleted.length < newCar.files.length;\n    const reasonSelected: IReason | undefined = (reasons as IReason[]).find((reason: IReason) => reason._id === newCar.reason);\n    return (\n      <AppContainer title='' cMenu='3' cSubMenu={vehiclesView ? '3.2' : '3.1'} cAction='Crear solicitud'>\n        <section className='content'>\n          <div className='box'>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>Crear solicitud</h3>\n            </div>\n            <div className='box-body create-request'>\n              <div className='row'>\n                <div className='col-md-6 col-lg-6'>\n                  <h3>Agregar Unidades</h3>\n                  <div className='form-horizontal'>\n                    <div className='form-group'>\n                      <label htmlFor='marca' className='col-sm-3 control-label label-left'>Marca *</label>\n                      <div className='col-sm-9'>\n                        <AutoCompleteInput\n                          value={newCar.brand}\n                          inputClass={'input-sm'}\n                          items={newCar.brands}\n                          renderItem={(item, index) => (\n                            <div key={index} className='item'>\n                              {item.material ? `${item.material} - ` : ''} {item.denomination} <br />\n                              <strong>{item.brand}</strong>\n                            </div>\n                          )}\n                          onChange={(e) => {\n                            const { value } = e.target;\n                            this.changeNewCar('brand', value);\n                            this.search(value, 'brands');\n                          }}\n                          onSelect={(item) => {\n                            this.setState({\n                              newCar: {\n                                ...this.state.newCar,\n                                brand: item.brand,\n                                brands: [],\n                                denomination: item.denomination,\n                                denominations: [],\n                                material: '',\n                                materials: []\n                              }\n                            });\n                          }}\n                        />\n                      </div>\n                    </div>\n                    <div className='form-group'>\n                      <label htmlFor='modelo' className='col-sm-3 control-label label-left'>Modelo {\n                        requestSettings.materialRequired ? '*' : ''\n                      }</label>\n                      <div className='col-sm-9'>\n                        <AutoCompleteInput\n                          value={newCar.denomination}\n                          inputClass={'input-sm'}\n                          items={newCar.denominations}\n                          renderItem={(item, index) => (\n                            <div key={index} className='item'>\n                              {item.material ? `${item.material} - ` : ''} {item.denomination} <br />\n                              <strong>{item.brand}</strong>\n                            </div>\n                          )}\n                          onChange={(e) => {\n                            const { value } = e.target;\n                            this.changeNewCar('denomination', value);\n                            this.search(value, 'denominations');\n                          }}\n                          onSelect={(item) => {\n                            this.setState({\n                              newCar: {\n                                ...this.state.newCar,\n                                brand: item.brand,\n                                brands: [],\n                                denomination: item.denomination,\n                                denominations: [],\n                                material: '',\n                                materials: []\n                              }\n                            });\n                          }}\n                        />\n                      </div>\n                    </div>\n                    <ShowIf condition={requestSettings.material}>\n                      <div className='form-group'>\n                        <label htmlFor='material' className='col-sm-3 control-label label-left'>Material {\n                          requestSettings.materialRequired ? '*' : ''\n                        }</label>\n                        <div className='col-sm-9'>\n                          <AutoCompleteInput\n                            value={newCar.material}\n                            inputClass={'input-sm'}\n                            items={newCar.materials}\n                            renderItem={(item, index) => (\n                              <div key={index} className='item'>\n                                {item.material ? `${item.material} - ` : ''} {item.denomination} <br />\n                                <strong>{item.brand}</strong>\n                              </div>\n\n                            )}\n                            onChange={(e) => {\n                              const { value } = e.target;\n                              this.changeNewCar('material', value);\n                              this.search(value, 'materials');\n                            }}\n                            onSelect={(item) => {\n                              this.setState({\n                                newCar: {\n                                  ...this.state.newCar,\n                                  brand: item.brand,\n                                  brands: [],\n                                  denomination: item.denomination,\n                                  denominations: [],\n                                  material: '',\n                                  materials: []\n                                }\n                              });\n                            }}\n                          />\n                        </div>\n                      </div>\n                    </ShowIf>\n                    <div className='form-group'>\n                      <label htmlFor='color' className='col-sm-3 control-label label-left'>Color {\n                        requestSettings.colorRequired ? '*' : ''\n                      }</label>\n                      <div className='col-sm-9'>\n                        <input\n                          type='text'\n                          className='input-sm form-control'\n                          value={newCar.color}\n                          onChange={(e) => {\n                            this.changeNewCar('color', e.target.value);\n                          }}\n                        />\n                      </div>\n                    </div>\n                    <div className='form-group'>\n                      <label className='col-sm-3 control-label label-left'>Motivo *</label>\n                      <div className='col-sm-9'>\n                        <BootstrapSelect\n                          noneSelectedText='Seleccione'\n                          displayItems={1}\n                          sm={true}\n                          search={true}\n                          autoClouse={true}\n                          selectedText='motivos seleccionados.'\n                          selected={newCar.reason.length ? [newCar.reason] : []}\n                          allOption={false}\n                          options={reasons.map((reason: any) => ({\n                            value: reason._id,\n                            text: reason.name\n                          }))}\n                          onClick={(value: string) => {\n                            this.changeNewCar('reason', value);\n                          }}\n                        />\n                      </div>\n                    </div>\n                    <ShowIf condition={!!(reasonSelected && reasonSelected.questions.length)}>\n                      {\n                        reasonSelected?.questions.map((question: any) => {\n                          const currentAnswer: any = newCar.answers.find((answer: any) => (answer.questionId === question._id));\n                          return (\n                            <div className='form-group' key={(question)._id}>\n                              <label\n                                htmlFor='color'\n                                className='col-sm-3 control-label label-left'\n                              >\n                                {question.name} {question.required ? '*' : ''}\n                              </label>\n                              <div className='col-sm-9'>\n                                {\n                                  question._id === '5bf2de35caf8ef7096105c23' ?\n                                    <select\n                                      className='form-control select-sm font-12'\n                                      value={currentAnswer ? currentAnswer.answer : ''}\n                                      onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                                        this.changeNewCar('answers', (() => {\n                                          if (e.target.value) {\n                                            if (currentAnswer) {\n                                              return [...newCar.answers].map((answer: any) => {\n                                                if (question._id === answer.questionId) {\n                                                  answer.answer = e.target.value;\n                                                }\n                                                return answer;\n                                              });\n                                            }\n                                            return [...newCar.answers, {\n                                              questionId: question._id,\n                                              question: question.name,\n                                              answer: e.target.value\n                                            }];\n                                          }\n                                          return [...newCar.answers].filter((answer: any) => (question._id !== answer.questionId));\n                                        })());\n                                      }}\n                                    >\n                                      <option value=\"\" disabled={true}>Seleccione</option>\n                                      <option value=\"VPP+CREDITO\">VPP+CREDITO</option>\n                                      <option value=\"VPP\">VPP</option>\n                                      <option value=\"CREDITO\">CREDITO</option>\n                                      <option value=\"CONTADO\">CONTADO</option>\n                                      <option value=\"LEASING\">LEASING</option>\n                                    </select> :\n                                    <input\n                                      type='text'\n                                      className='input-sm form-control'\n                                      value={currentAnswer ? currentAnswer.answer : ''}\n                                      onChange={(e) => {\n                                        this.changeNewCar('answers', (() => {\n                                          if (e.target.value) {\n                                            if (currentAnswer) {\n                                              return [...newCar.answers].map((answer: any) => {\n                                                if (question._id === answer.questionId) {\n                                                  answer.answer = e.target.value;\n                                                }\n                                                return answer;\n                                              });\n                                            }\n                                            return [...newCar.answers, {\n                                              questionId: question._id,\n                                              question: question.name,\n                                              answer: e.target.value\n                                            }];\n                                          }\n                                          return [...newCar.answers].filter((answer: any) => (question._id !== answer.questionId));\n                                        })());\n                                      }}\n                                    />\n                                }\n                              </div>\n                            </div>\n                          );\n                        })\n                      }\n                    </ShowIf>\n                    <ShowIf condition={!!(reasonSelected && reasonSelected.file.active)}>\n                      <div className='form-group'>\n                        <label className='col-sm-3 control-label label-left'>Archivos *</label>\n                        <div className='col-sm-9'>\n                          <MultiUploadFiles\n                            url={'/api/v1/requests/upload-file/'}\n                            onChange={(files) => {\n                              this.changeNewCar('files', files);\n                            }}\n                            files={newCar.files}\n                          />\n                          <ShowIf condition={isUploadingFiles}>\n                            <p>\n                              Se están cargando sus archivos, llevamos {filesCompleted.length} de {newCar.files.length} <i\n                              className='fa fa-spinner fa-spin' />.\n                            </p>\n                          </ShowIf>\n                        </div>\n                      </div>\n                    </ShowIf>\n                    {\n                      /* <div className=\"form-group\">\n                        <label className=\"col-sm-3 control-label label-left\">Pre-entrega</label>\n                        <div className=\"col-sm-9\">\n                          <div className=\"checkbox\">\n                            <label>\n                              <input\n                                type=\"checkbox\"\n                                checked={newCar.washed}\n                                onChange={() => {\n                                  this.changeBooleanNewCar('washed', !newCar.washed);\n                                }}\n                              /> <i className=\"material-icons\">local_car_wash</i> Lavado\n                            </label>\n                          </div>\n                          <div className=\"checkbox\">\n                            <label>\n                              <input\n                                type=\"checkbox\"\n                                checked={newCar.equipment}\n                                onChange={() => {\n                                  this.changeBooleanNewCar('equipment', !newCar.equipment);\n                                }}\n                              /> <i className=\"material-icons\">build</i> Pre-entrega mecánica\n                            </label>\n                          </div>\n                        </div>\n                      </div> */\n                    }\n                    <div className='form-group'>\n                      <label className='col-sm-3 control-label label-left'>Cantidad</label>\n                      <div className='col-sm-4'>\n                        <input id='amount' type='text' className='form-control' />\n                      </div>\n                    </div>\n                    <div className='form-group'>\n                      <label className='col-sm-3 control-label label-left'>Prioridad</label>\n                      <div className='col-sm-6'>\n                        {\n                          newCar.priority ?\n                            <i\n                              className='fa fa-2x fa-star text-yellow pointer'\n                              style={{ marginTop: '5px', fontSize: '1.7em' }}\n                              onClick={() => this.changeBooleanNewCar('priority', false)}\n                            />\n                            :\n                            <i\n                              className='fa fa-2x fa-star-o text-yellow pointer'\n                              style={{ marginTop: '5px', fontSize: '1.7em' }}\n                              onClick={() => this.changeBooleanNewCar('priority', true)}\n                            />\n                        }\n                      </div>\n                    </div>\n                    <div className='form-group'>\n                      <label className='col-sm-3 control-label label-left'>Observación despacho</label>\n                      <div className='col-sm-9'>\n                        <textarea\n                          className='form-control input-sm'\n                          onChange={(e) => {\n                            const { value } = e.target;\n                            this.changeNewCar('observation', value);\n                          }}\n                          value={newCar.observation}\n                          style={{ resize: 'none' }}\n                          rows={4}\n                        />\n                      </div>\n                    </div>\n                    <div className='text-right'>\n                      <button\n                        className='btn btn-sm btn-primary'\n                        onClick={this.addCar}\n                        disabled={\n                          !(reasonSelected && reasonSelected.questions.length === newCar.answers.length) ||\n                          !newCar.brand.length ||\n                          (requestSettings.denomination && requestSettings.denominationRequired && !newCar.denomination.length) ||\n                          (requestSettings.material && requestSettings.materialRequired && !newCar.material.length) ||\n                          (requestSettings.color && requestSettings.colorRequired && !newCar.color.length) ||\n                          !newCar.reason ||\n                          isUploadingFiles\n                        }\n                      >\n                        Agregar\n                      </button>\n                    </div>\n                  </div>\n                </div>\n                <div className='col-md-6 col-lg-6' style={{ paddingLeft: '10px' }}>\n                  <div className='add-cars'>\n                    <div className='arrow'>\n                      <i className='fa fa-3x fa-caret-right' />\n                    </div>\n                    <div className='detail'>\n                      <h3>Solicitud</h3>\n                      <div className='form-horizontal'>\n                        <div className='form-group'>\n                          <label className='col-sm-3 control-label label-left'>Destino</label>\n                          <div className='col-sm-9'>\n                            <BootstrapSelect\n                              noneSelectedText='Seleccione'\n                              displayItems={1}\n                              sm={true}\n                              search={true}\n                              autoClouse={true}\n                              selectedText='sucursales seleccionadas.'\n                              selected={this.state.venue.length ? [this.state.venue] : []}\n                              allOption={false}\n                              options={venues.map((venue: any) => ({\n                                value: venue._id,\n                                text: venue.name\n                              }))}\n                              onClick={(value: string) => {\n                                this.changeVenue(value);\n                              }}\n                            />\n                          </div>\n                        </div>\n                        <div className='form-group'>\n                          <label className='col-sm-3 control-label label-left'>Vendedor</label>\n                          <div className='col-sm-9'>\n                            <input type='text' className='form-control input-sm' onChange={(e) => {\n                              this.setState({\n                                sellerText: e.target.value\n                              });\n                            }} />\n                          </div>\n                        </div>\n                        <div className='form-group'>\n                          <label className='col-sm-3 control-label label-left'>Canal *</label>\n                          <div className='col-sm-9'>\n                            <BootstrapSelect\n                              noneSelectedText='Seleccione'\n                              displayItems={1}\n                              sm={true}\n                              search={true}\n                              autoClouse={true}\n                              selected={channel.length ? [channel] : []}\n                              allOption={false}\n                              options={channels.map((channel: any) => ({\n                                value: channel._id,\n                                text: channel.name\n                              }))}\n                              onClick={(value: string) => {\n                                this.setState({\n                                  channel: value\n                                });\n                              }}\n                            />\n                          </div>\n                        </div>\n                        <ShowIf condition={!!operationTypes.length}>\n                          <div className='form-group'>\n                            <label className='col-sm-3 control-label label-left'>Tipo operación</label>\n                            <div className='col-sm-9'>\n                              <BootstrapSelect\n                                noneSelectedText='Seleccione'\n                                displayItems={1}\n                                sm={true}\n                                search={true}\n                                autoClouse={true}\n                                selected={operationType.length ? [operationType] : []}\n                                allOption={false}\n                                options={operationTypes.map((operationType: any) => ({\n                                  value: operationType._id,\n                                  text: operationType.name\n                                }))}\n                                onClick={(value: string) => {\n                                  this.setState({\n                                    operationType: value\n                                  });\n                                }}\n                              />\n                            </div>\n                          </div>\n                        </ShowIf>\n                      </div>\n                      {/* <div className=\"form-group-switch\">\n                        <label className=\"switch-label switch-label-left\">Estás solicitando flota</label>\n                        <BootstrapSwitch\n                          checked={fleet}\n                          color=\"blue\"\n                          onChange={this.changeFleet}\n                        />\n                      </div> */}\n                      <div className='create-detail'>\n                        <table className='table'>\n                          <tbody>\n                          {\n                            cars.map((car: any) => (\n                              <tr key={car.tid}>\n                                <td className='middle'>{`${car.denomination} ${car.material} ${car.brand}`}</td>\n                                <td className='middle'>{car.color}</td>\n                                <td className='middle'>{this.searchReason(car.reason)}</td>\n                                <td className='middle'>\n                                  <i className={`material-icons ${!car.washed ? 'text-gray' : ''}`}>local_car_wash</i>\n                                </td>\n                                <td className='middle'>\n                                  <i className={`material-icons ${!car.equipment ? 'text-gray' : ''}`}>build</i>\n                                </td>\n                                <td className='middle'>\n                                  {car.files.length ? <i className={`fa fa-paperclip`} /> : null}\n                                </td>\n                                <td className='middle text-muted' style={{ width: '140px' }}>\n                                  {\n                                    car.observation && car.observation.length ?\n                                      car.observation\n                                      : 'Sin observaciones'\n                                  }\n                                </td>\n                                <td\n                                  className='middle'\n                                  onClick={() => this.deleteCar(car)}\n                                >\n                                  <i className='fa fa-trash text-red pointer' />\n                                </td>\n                              </tr>\n                            ))\n                          }\n                          </tbody>\n                        </table>\n                      </div>\n                      <div className='text-right text-muted' style={{ padding: '2px' }}>\n                        {cars.length} unidades\n                      </div>\n                    </div>\n                  </div>\n                </div>\n              </div>\n            </div>\n            <div className='box-footer text-right'>\n              <button className='btn btn-sm btn-default' onClick={this.cancel}>Cancelar</button>\n              <button\n                className='btn btn-sm btn-primary'\n                style={{ marginLeft: '5px' }}\n                onClick={this.createRequest}\n              >\n                Crear\n              </button>\n            </div>\n            {\n              loading ?\n                <div className='overlay'>\n                  <i className='fa fa-spinner fa-spin text-purple' />\n                </div> : null\n            }\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private addCar(): void {\n    const { newCar, reasons } = this.state;\n    const reasonSelected: IReason | undefined = (reasons as IReason[]).find((reason: IReason) => reason._id === newCar.reason);\n    if (reasonSelected?.file.required && !newCar.files.length) {\n      swal!('Solicitud', `Se requiere que subas un archivo para este vehículo.`, 'error');\n    } else {\n      const $amount: any = $('#amount');\n      const cars = Array(newCar.amount).fill({\n        brand: newCar.brand,\n        denomination: newCar.denomination,\n        files: newCar.files,\n        answers: newCar.answers,\n        material: newCar.material,\n        color: newCar.color,\n        observation: newCar.observation,\n        priority: newCar.priority,\n        equipment: newCar.equipment,\n        reason: newCar.reason,\n        washed: newCar.washed\n      });\n      this.setState({\n        cars: [...this.state.cars, ...cars.map((car) => {\n          const tid = uuid.v4();\n          return {\n            ...car,\n            tid\n          };\n        })],\n        newCar: initialNewCar\n      }, () => {\n        $amount.val(1);\n      });\n    }\n  }\n\n  private searchReason(id: string) {\n    const { reasons } = this.state;\n    const reason: any = reasons.find((r: any) => r._id === id);\n    if (reason) {\n      return reason.name;\n    }\n    return '';\n  }\n\n  private deleteCar(dcar: any): void {\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar ${dcar.denomination} ${dcar.material} ${dcar.brand} (${dcar.color})`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete: any) => {\n      if (willDelete) {\n        this.setState({\n          cars: this.state.cars.filter((car: any) => car.tid !== dcar.tid)\n        });\n      }\n    });\n  }\n\n  private changeNewCar(field: keyof INewCar, value: any) {\n    const extra: any = {};\n    if (field === 'reason') {\n      extra.answers = [];\n    }\n    this.setState({\n      newCar: {\n        ...this.state.newCar,\n        ...extra,\n        [field]: value\n      }\n    });\n  }\n\n  private changeNumberNewCar(field: 'amount', value: number) {\n    this.setState({\n      newCar: {\n        ...this.state.newCar,\n        [field]: value\n      }\n    });\n  }\n\n  private changeBooleanNewCar(field: 'priority' | 'equipment' | 'washed', value: boolean) {\n    this.setState({\n      newCar: {\n        ...this.state.newCar,\n        [field]: value\n      }\n    });\n  }\n\n  private changeVenue(venue: string) {\n    this.setState({\n      venue\n    });\n  }\n\n  private changeFleet() {\n    const { fleet } = this.state;\n    this.setState({\n      fleet: !fleet\n    });\n  }\n\n  private loadBaseData() {\n    this.setState({ loading: true });\n    Axios\n      .all([\n        this.api.getVenues({ page: 1, pageSize: 200, noPopulate: true, filted: true }),\n        this.api.getReasons({ page: 1, pageSize: 200 }),\n        this.api.getSalesChannel({ page: 1, pageSize: 200 }),\n        this.api.getTeamSettings(),\n        this.api.getOperationTypes({ page: 1, pageSize: 200 })\n      ])\n      .then(Axios.spread((venues, reasons, channels, teamSettings, operationTypes) => {\n        this.setState({\n          venues: venues.data.results,\n          reasons: reasons.data.results,\n          channels: channels.data.results,\n          requestSettings: teamSettings.data.request,\n          operationTypes: operationTypes.data.results,\n          loading: false\n        });\n      }))\n      .catch((err: AxiosError): void => {\n        this.api.errorHandler(err);\n      });\n  }\n\n  private search(text: string, base: 'denominations' | 'brands' | 'materials'): void {\n    this.api\n      .searchCar(text)\n      .then((response: AxiosResponse): void => {\n        this.setState({\n          newCar: {\n            ...this.state.newCar,\n            [base]: response.data.cars\n          }\n        });\n      })\n      .catch((err: AxiosError): void => {\n        this.api.errorHandler(err);\n      });\n  }\n\n  private createRequest() {\n    const vehiclesView = this.props.location.pathname === parseReplicableURL('/requests/vehicles/create/');\n    const { cars, channel, venue, sellerText, operationType } = this.state;\n    if (!cars.length) {\n      swal!('Solicitud', 'No se han agregado unidades para crear la solicitud.', 'error');\n    } else if (!venue.length) {\n      swal!('Solicitud', 'No se ha seleccionado destino para crear la solicitud.', 'error');\n    } else if (!channel.length) {\n      swal!('Solicitud', 'No se ha seleccionado canal para crear la solicitud.', 'error');\n    } else {\n      this.api\n        .createRequest({\n          cars,\n          channel,\n          operationType,\n          venue,\n          sellerText\n        })\n        .then(() => {\n          swal!('Solicitud', 'Se ha creado satisfactoriamente.', 'success').then(() => {\n            this.props.history.push(parseReplicableURL(vehiclesView ? '/requests/vehicles/' : '/requests/'));\n          });\n        })\n        .catch((err: AxiosError): void => {\n          this.api.errorHandler(err);\n        });\n    }\n  }\n\n  private cancel(): void {\n    const vehiclesView = this.props.location.pathname === '/requests/vehicles/create/';\n    this.props.history.push(parseReplicableURL(vehiclesView ? '/requests/vehicles/' : '/requests/'));\n  }\n}\n\nconst mapStateToProps = (state: { inventories: IInventoryState }) => {\n  return {\n    inventories: state.inventories\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(RequestCreateView);\n","import { AxiosError, AxiosResponse } from 'axios';\nimport * as moment from 'moment-timezone';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router-dom';\nimport { io } from \"socket.io-client\";\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport * as swal from 'sweetalert';\nimport { debounce } from 'throttle-debounce';\nimport { ICar } from '../../../../../../../src/app/interfaces/car.interface';\nimport { IRequestItem } from '../../../../../../../src/request/interfaces/requestItem.interface';\nimport {\n  createRequestItemActionInDetail,\n  deleteRequestItemActionInDetail,\n  deleteRequestThunkAction,\n  getRequestThunkAction,\n  updateRequestItemActionInDetail\n} from '../../../actions/requests.actions';\nimport { IRequestsState } from '../../../actions/requests.types';\nimport AppContainer from '../../../container/AppContainer';\nimport { IWindow } from '../../../interfaces/window';\nimport ApiService from '../../../utils/axios';\nimport { hasPermission, parseReplicableURL } from '../../../utils/common';\nimport AutoCompleteInput from '../../Utils/AutoCompleteInput';\nimport RequestItem from './RequestItem';\nimport TrackingBasePage from '../../Utils/TrackingBasePage';\nimport ShowIf from '../../Utils/ShowIf';\n\ninterface IPropsType extends RouteComponentProps<{ id: string }> {\n  requests: IRequestsState;\n  getRequestAction: (id: string) => void;\n  createRequestItemActionInDetail: (item: IRequestItem) => void;\n  updateRequestItemActionInDetail: (item: IRequestItem) => void;\n  deleteRequestItemActionInDetail: (item: IRequestItem) => void;\n  deleteRequestThunkAction: (id: string) => void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  recommends: ICar[];\n  car: Partial<ICar & {reason: string}>;\n}\n\ndeclare let window: IWindow;\n\nclass RequestDetailView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  readonly api: ApiService;\n  readonly state = {\n    error: null,\n    recommends: [],\n    car: {\n      brand: '',\n      denomination: '',\n      material: '',\n      color: '',\n      reason: ''\n    }\n  };\n\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Detalle Solicitud';\n    this.search = debounce(500, this.search.bind(this));\n    this.api = new ApiService();\n    this.deleteRequest = this.deleteRequest.bind(this);\n    this.createItem = this.createItem.bind(this);\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public componentWillMount(): void {\n    const { id } = this.props.match.params;\n    window.scrollTo(0, 0);\n\n    this.props.getRequestAction(id);\n\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: window.user.token\n      }\n    });\n\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `request-detail-${window.user.team._id}` });\n    });\n\n    this.socket.on('UPDATE_REQUEST_ITEM', (data: any): void => {\n      if (data.idRequest === id) {\n        this.props.updateRequestItemActionInDetail(data.item);\n        const $item = $(`#request-item-${data.item._id}`);\n        if ($item) {\n          $item.addClass('bg-aqua-active');\n        }\n        setTimeout(() => {\n          $item.removeClass('bg-aqua-active');\n        }, 300);\n      }\n    });\n\n    this.socket.on('DELETE_REQUEST_ITEM', (data: any): void => {\n      if (data.idRequest === id) {\n        const $item = $(`#request-item-${data.item._id}`);\n        if ($item) {\n          $item.addClass('bg-red-active');\n        }\n        setTimeout(() => {\n          this.props.deleteRequestItemActionInDetail(data.item);\n        }, 300);\n      }\n    });\n\n    this.socket.on('DELETE_REQUEST', (data: any): void => {\n      if (data.idRequest === id) {\n        const vehiclesView = this.props.location.pathname.includes('requests/vehicles');\n        this.props.history.push(parseReplicableURL(vehiclesView ? '/requests/vehicles/' : '/requests/'));\n      }\n    });\n\n    this.socket.on('CREATE_REQUEST_ITEM', (data: any): void => {\n      if (data.idRequest === id) {\n        this.props.createRequestItemActionInDetail(data.item);\n        const $item = $(`#request-item-${data.item._id}`);\n        if ($item) {\n          $item.addClass('bg-green-active');\n        }\n        setTimeout(() => {\n          $item.removeClass('bg-green-active');\n        }, 300);\n      }\n    });\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: IPropsType): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.requests.source) {\n      this.props.requests.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { request, loading, reasons, requestSettings} = this.props.requests;\n    const { recommends, car } = this.state;\n    const canChangeRequest = hasPermission(window.user, 'changeRequest');\n    const vehiclesView = this.props.location.pathname.includes('requests/vehicles');\n    return (\n      <AppContainer title='' cMenu='3' cSubMenu={vehiclesView ? '3.2' : '3.1'} cAction={'Detalle solicitud'}>\n        <section className='content'>\n          <div className='box'>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>Detalle solicitud #{request?.number}</h3>\n              {\n                hasPermission(window.user, 'deleteRequest') ?\n                  <div className='pull-right box-tools'>\n                    <button\n                      className='btn btn-sm btn-danger'\n                      onClick={this.deleteRequest}\n                    >\n                      <i className='fa fa-fw fa-trash' /> Eliminar solicitud\n                    </button>\n                  </div>\n                  : null\n              }\n            </div>\n            <div className='box-body request-detail no-padding table-responsive'>\n              {\n                Object.keys(request).length ?\n                  <React.Fragment>\n                    <div className={'bg-blue'} style={{ padding: '5px', minWidth: '900px' }}>\n                      <table className='table table-xs bg-blue' style={{ minWidth: '900px' }}>\n                        <tbody>\n                        <tr>\n                          <td style={{ borderTop: '0' }}>\n                            <span style={{ paddingLeft: '17px' }}>Vendedor</span><br />\n                            <strong><i className='fa fa-fw fa-user' /> {request.createdBy?.firstName} {request.createdBy?.lastName}</strong>\n                          </td>\n                          {/*<td style={{ borderTop: '0' }}>*/}\n                          {/*  <span style={{ paddingLeft: '17px' }}> Vendedor</span><br />*/}\n                          {/*  <strong><i className='fa fa-fw fa-handshake' /> {request.sellerText?.length ? request.sellerText : '-'}</strong>*/}\n                          {/*</td>*/}\n                          <td style={{ borderTop: '0' }}>\n                            Canal<br />\n                            <strong>{request.channel?.name}</strong>\n                          </td>\n                          <td style={{ borderTop: '0' }}>\n                            ID Cotización<br />\n                            <strong>{request.conectaID}</strong>\n                          </td>\n                          <td style={{ borderTop: '0' }}>\n                            <span style={{ paddingLeft: '17px' }}> Sucursal</span><br />\n                            <strong><i className='fa fa-fw fa-building' /> {request.origin?.name}</strong>\n                          </td>\n                          <td style={{ width: '30%', borderTop: '0' }}>\n                            Dirección<br />\n                            <strong>{request?.deliveryAddress}</strong>\n                          </td>\n                          <td style={{ borderTop: '0' }}>\n                            <span style={{ paddingLeft: '17px' }}> Creada</span><br />\n                            <strong><i className='fa fa-fw fa-calendar' /> {moment(request.createdAt).format('DD-MM-YYYY')}</strong>\n                          </td>\n                          <td style={{ borderTop: '0' }}>\n                            <span style={{ paddingLeft: '17px' }}> Entrega esperada</span><br />\n                            <strong><i\n                              className='fa fa-fw fa-calendar-check-o' /> {request.deliveryDate ? moment(request.deliveryDate).format('DD-MM-YYYY') : '-'}\n                            </strong>\n                          </td>\n                        </tr>\n                        </tbody>\n                      </table>\n                    </div>\n                    <div style={{ padding: '5px', backgroundColor: '#f9f9f9', minWidth: '900px' }}>\n                      <table className='table table-xs text-black' style={{ minWidth: '900px', backgroundColor: '#f9f9f9' }}>\n                        <tbody>\n                        <tr>\n                          <td style={{ borderTop: '0' }}>\n                            <span style={{ paddingLeft: '17px' }}>Cliente</span><br />\n                            <strong><i className='fa fa-fw fa-address-book' /> {request.customerInformation?.name} </strong>\n                          </td>\n                          <td style={{ borderTop: '0' }}>\n                            Rut Cliente<br />\n                            <strong>{request.customerInformation?.rut} </strong>\n                          </td>\n                          <td style={{ borderTop: '0' }}>\n                            <span style={{ paddingLeft: '17px' }}>Correo Cliente</span><br />\n                            <strong><i className='fa fa-fw fa-envelope' /> {\n                              request.customerInformation?.email ?\n                                <a href={request.customerInformation.email}>{request.customerInformation.email}</a> : '-'\n                            } </strong>\n                          </td>\n                          <td style={{ width: '40%', borderTop: '0' }} />\n                        </tr>\n                        </tbody>\n                      </table>\n                    </div>\n                    <table className='table table-xs table-hover' style={{ minWidth: '900px' }}>\n                      <thead>\n                      <tr>\n                        <th className='middle-center' style={{ width: '25px' }}>#</th>\n                        <ShowIf condition={requestSettings.priority}>\n                          <th className='middle' style={{ width: '28px' }} />\n                        </ShowIf>\n                        <th className='middle' style={{ width: '10px' }}>Propiedad</th>\n                        <ShowIf condition={requestSettings.brand}>\n                          <th className='middle' style={{ minWidth: '100px' }}>Marca</th>\n                        </ShowIf>\n                        <ShowIf condition={requestSettings.denomination}>\n                          <th className='middle' style={{ minWidth: '160px' }}>Modelo</th>\n                        </ShowIf>\n                        <ShowIf condition={requestSettings.material}>\n                          <th className='middle' style={{ width: '100px' }}>Material</th>\n                        </ShowIf>\n                        <ShowIf condition={requestSettings.color}>\n                          <th className='middle' style={{ width: '100px' }}>Color</th>\n                        </ShowIf>\n                        <th className='middle' style={{ width: '200px' }}>VIN</th>\n                        <th className='middle' style={{ minWidth: '100px' }}>Estado</th>\n                        <ShowIf condition={requestSettings.conectaID}>\n                          <th className='middle-center'>Ticket</th>\n                          <th className='middle' style={{ width: '100px' }}>Nº Ticket</th>\n                        </ShowIf>\n                        <ShowIf condition={requestSettings.internalNumber}>\n                          <th className='middle' style={{ width: '80px' }}>CDO</th>\n                        </ShowIf>\n                        <ShowIf condition={requestSettings.reason}>\n                          <th className='middle' style={{ minWidth: '100px' }}>Motivo</th>\n                        </ShowIf>\n                        <th className='middle-center' style={{ width: '40px' }}>Adj</th>\n                        <th className='middle' style={{ width: '20px' }}>Obs</th>\n                        {\n                          hasPermission(window.user, 'deleteRequest') ?\n                            <th className='middle' style={{ width: '30px' }} />\n                            : null\n                        }\n                      </tr>\n                      </thead>\n                      <tbody>\n                      {\n                        request!.items!.map((item, index) => (\n                          <RequestItem\n                            key={item._id}\n                            index={index}\n                            request={request}\n                            item={item}\n                          />\n                        ))\n                      }\n                      </tbody>\n                    </table>\n                    {\n                      canChangeRequest ?\n                        <div className='row' style={{ minWidth: '900px' }}>\n                          <div className='col-md-10 col-md-offset-2' style={{ paddingRight: '5px' }}>\n                            <div className='container-table-add-car' style={{ padding: '5px', marginTop: '20px', marginBottom: '20px' }}>\n                              <table className='table table-xs'>\n                                <thead>\n                                <tr>\n                                  <ShowIf condition={requestSettings.brand}>\n                                    <th>Marca</th>\n                                  </ShowIf>\n                                  <ShowIf condition={requestSettings.denomination}>\n                                    <th>Modelo</th>\n                                  </ShowIf>\n                                  <ShowIf condition={requestSettings.material}>\n                                    <th>Material</th>\n                                  </ShowIf>\n                                  <ShowIf condition={requestSettings.color}>\n                                    <th>Color</th>\n                                  </ShowIf>\n                                  <ShowIf condition={requestSettings.reason}>\n                                    <th style={{ width: '100px' }}>Motivo</th>\n                                  </ShowIf>\n                                  <th style={{ width: '100px' }} />\n                                </tr>\n                                </thead>\n                                <tbody>\n                                <tr>\n                                  <ShowIf condition={requestSettings.brand}>\n                                    <td>\n                                      <AutoCompleteInput\n                                        value={car.brand}\n                                        inputClass={'input-sm'}\n                                        items={recommends}\n                                        renderItem={(car, index) => (\n                                          <div key={index} className='item'>\n                                            {car.denomination} <br />\n                                            <strong>{car.brand}</strong>\n                                          </div>\n                                        )}\n                                        onChange={(e) => {\n                                          const { value } = e.target;\n                                          this.setState({\n                                            car: {\n                                              ...this.state.car,\n                                              brand: value\n                                            }\n                                          });\n                                          this.search(value);\n                                        }}\n                                        onSelect={(car: any) => {\n                                          this.setState({\n                                            car: {\n                                              ...this.state.car,\n                                              brand: car.brand,\n                                              denomination: car.denomination,\n                                              material: car.material ?? ''\n                                            }\n                                          });\n                                        }}\n                                      />\n                                    </td>\n                                  </ShowIf>\n                                  <ShowIf condition={requestSettings.denomination}>\n                                    <td>\n                                      <AutoCompleteInput\n                                        value={car.denomination}\n                                        inputClass={'input-sm'}\n                                        items={recommends}\n                                        renderItem={(car, index) => (\n                                          <div key={index} className='item'>\n                                            {car.denomination} <br />\n                                            <strong>{car.denomination}</strong>\n                                          </div>\n                                        )}\n                                        onChange={(e) => {\n                                          const { value } = e.target;\n                                          this.setState({\n                                            car: {\n                                              ...this.state.car,\n                                              denomination: value\n                                            }\n                                          });\n                                          this.search(value);\n                                        }}\n                                        onSelect={(car: any) => {\n                                          this.setState({\n                                            car: {\n                                              ...this.state.car,\n                                              brand: car.brand,\n                                              denomination: car.denomination,\n                                              material: car.material ?? ''\n                                            }\n                                          });\n                                        }}\n                                      />\n                                    </td>\n                                  </ShowIf>\n                                  <ShowIf condition={requestSettings.material}>\n                                    <td>\n                                      <AutoCompleteInput\n                                        value={car.material}\n                                        inputClass={'input-sm'}\n                                        items={recommends}\n                                        renderItem={(car, index) => (\n                                          <div key={index} className='item'>\n                                            {car.denomination} <br />\n                                            <strong>{car.brand}</strong>\n                                          </div>\n                                        )}\n                                        onChange={(e) => {\n                                          const { value } = e.target;\n                                          this.setState({\n                                            car: {\n                                              ...this.state.car,\n                                              material: value\n                                            }\n                                          });\n                                          this.search(value);\n                                        }}\n                                        onSelect={(car: any) => {\n                                          this.setState({\n                                            car: {\n                                              ...this.state.car,\n                                              brand: car.brand,\n                                              denomination: car.denomination,\n                                              material: car.material ?? ''\n                                            }\n                                          });\n                                        }}\n                                      />\n                                    </td>\n                                  </ShowIf>\n                                  <ShowIf condition={requestSettings.color}>\n                                    <td>\n                                      <input\n                                        type='text'\n                                        className='form-control input-sm'\n                                        value={this.state.car.color}\n                                        onChange={(e: React.ChangeEvent<HTMLInputElement>) => {\n                                          const { value } = e.target;\n                                          this.setState({\n                                            car: {\n                                              ...this.state.car,\n                                              color: value\n                                            }\n                                          });\n                                        }}\n                                      />\n                                    </td>\n                                  </ShowIf>\n                                  <ShowIf condition={requestSettings.reason}>\n                                    <td>\n                                      <select\n                                        className='form-control select-sm font-12' value={this.state.car.reason}\n                                        onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                                          const { value } = e.target;\n                                          this.setState({\n                                            car: {\n                                              ...this.state.car,\n                                              reason: value\n                                            }\n                                          });\n                                        }}\n                                      >\n                                        <option value='' disabled={true}>-</option>\n                                        {\n                                          reasons.map((reason) => (\n                                            <option key={reason._id} value={reason._id}>{reason.name}</option>\n                                          ))\n                                        }\n                                      </select>\n                                    </td>\n                                  </ShowIf>\n                                  <td className='text-right'>\n                                    <button\n                                      className='btn btn-sm btn-block btn-success'\n                                      onClick={this.createItem}\n                                      disabled={!this.state.car.brand || !this.state.car.color || !this.state.car.denomination || !this.state.car.reason}\n                                    >\n                                      <i className='fa fa-fw fa-plus' />Agregar vehículo\n                                    </button>\n                                  </td>\n                                </tr>\n                                </tbody>\n                              </table>\n                            </div>\n                          </div>\n                        </div>\n                        : null\n                    }\n                  </React.Fragment>\n                  : null\n              }\n            </div>\n            <div className='box-footer text-right'>\n              <button className='btn btn-sm btn-default' onClick={() => {\n                this.props.history.push(parseReplicableURL(vehiclesView ? '/requests/vehicles/' : '/requests/'));\n              }}><i className='fa fa-fw fa-rotate-left' /> Volver a unidades\n              </button>\n            </div>\n            {\n              loading &&\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            }\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private search(text: string): void {\n    this.api\n      .searchCar(text)\n      .then((response: AxiosResponse): void => {\n        this.setState({\n          recommends: response.data.cars\n        });\n      })\n      .catch((err: AxiosError): void => {\n        this.api.errorHandler(err);\n      });\n  }\n\n  private createItem() {\n    const { id } = this.props.match.params;\n    const { car } = this.state;\n    this.api\n      .createRequestItem(id, car)\n      .then((response: AxiosResponse): void => {\n        this.setState({\n          car: {\n            brand: '',\n            denomination: '',\n            material: '',\n            color: '',\n            reason: ''\n          }\n        });\n      })\n      .catch((err: AxiosError): void => {\n        this.api.errorHandler(err);\n      });\n  }\n\n  private deleteRequest() {\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar esta solicitud.`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        const { id } = this.props.match.params;\n        this.props.deleteRequestThunkAction(id);\n      }\n    });\n  }\n\n}\n\n\nconst mapStateToProps = (state: { requests: IRequestsState }) => {\n  return {\n    requests: state.requests\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    createRequestItemActionInDetail: (item: IRequestItem) => dispatch(createRequestItemActionInDetail(item)),\n    updateRequestItemActionInDetail: (item: IRequestItem) => dispatch(updateRequestItemActionInDetail(item)),\n    deleteRequestItemActionInDetail: (item: IRequestItem) => dispatch(deleteRequestItemActionInDetail(item)),\n    deleteRequestThunkAction: (id: string) => dispatch(deleteRequestThunkAction(id)),\n    getRequestAction: (id: string) => dispatch(getRequestThunkAction(id))\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(RequestDetailView);\n","import { AxiosError, AxiosResponse } from 'axios';\nimport * as moment from 'moment-timezone';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router-dom';\nimport * as swal from 'sweetalert';\nimport { debounce } from 'throttle-debounce';\nimport { ICar } from '../../../../../../../src/app/interfaces/car.interface';\nimport { IRequest } from '../../../../../../../src/request/interfaces/request.interface';\nimport { IRequestItem } from '../../../../../../../src/request/interfaces/requestItem.interface';\nimport {\n  deleteRequestItemThunkAction,\n  deleteRequestThunkAction,\n  updateRequestItemInDetailThunkAction\n} from '../../../actions/requests.actions';\nimport { IRequestsState } from '../../../actions/requests.types';\nimport { IWindow } from '../../../interfaces/window';\nimport ApiService from '../../../utils/axios';\nimport { hasPermission, parseReplicableURL } from '../../../utils/common';\nimport AutoCompleteInput from '../../Utils/AutoCompleteInput';\nimport AutoCompleteVinInput from '../../Utils/AutoCompleteVinInput';\nimport DateRangePicker from '../../Utils/DateRangePicker';\nimport ShowIf from '../../Utils/ShowIf';\nimport { debounceTime, switchMap } from 'rxjs/operators';\nimport { ajax } from 'rxjs/ajax';\nimport * as Rx from 'rxjs';\n\ninterface IPropsType extends RouteComponentProps<{ id: string }> {\n  requests: IRequestsState;\n  request: IRequest;\n  item: IRequestItem;\n  index: any;\n  updateRequestItemInDetailThunkAction: ({ item, debounce }: { item: IRequestItem, debounce?: boolean }) => void;\n  deleteRequestItemThunkAction: (item: IRequestItem) => void;\n  deleteRequestThunkAction: (idRequest: string) => void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  recommends: ICar[];\n  VINRecommends: any[];\n}\n\ndeclare let window: IWindow;\n\nclass RequestItem extends React.Component<IPropsType, IStateType> {\n  readonly api: ApiService;\n  readonly $subjectRecommends = new Rx.Subject<any>();\n  readonly $subjectVINRecommends = new Rx.Subject<any>();\n\n  readonly state = {\n    error: null,\n    recommends: [],\n    VINRecommends: []\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.search = debounce(500, this.search.bind(this));\n    this.downloadFiles = this.downloadFiles.bind(this);\n    this.api = new ApiService();\n    this.$subjectRecommends.pipe(\n      debounceTime(300),\n      switchMap((text: string) => {\n        return ajax({\n          url: `/api/v1/requests/search-car/?search=${text}`,\n          headers: {\n            'Content-Type': 'application/json;charset=UTF-8'\n          },\n          method: 'GET'\n        });\n      })\n    ).subscribe((response) => {\n      this.setState({\n        recommends: response.response.cars\n      });\n    });\n    this.$subjectVINRecommends.pipe(\n      debounceTime(300),\n      switchMap((vin: string) => {\n        return ajax({\n          url: `/api/v1/requests/search-vin/?vin=${vin}`,\n          headers: {\n            'Content-Type': 'application/json;charset=UTF-8'\n          },\n          method: 'GET'\n        });\n      })\n    ).subscribe((response) => {\n      this.setState({\n        VINRecommends: response.response.data\n      });\n    });\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { item, index, request } = this.props;\n    const { requestItemStatus, reasons, requestSettings } = this.props.requests;\n    const { recommends, VINRecommends } = this.state;\n    const canChangeRequest = hasPermission(window.user, 'changeRequest');\n    return (\n      <tr id={`request-item-${item._id}`} className={'background-transition'}>\n        <td className=\"middle-center\">{index + 1}</td>\n        <ShowIf condition={requestSettings.priority}>\n          <td\n            className={`middle-center ${canChangeRequest ? 'pointer' : ''}`}\n            onClick={canChangeRequest ? () => {\n              this.props.updateRequestItemInDetailThunkAction({\n                item: {\n                  ...item,\n                  priority: !item.priority\n                },\n                debounce: false\n              });\n            } : undefined}\n          >\n            {item.priority ? <i className='fa fa-star text-yellow' /> : <i className='fa fa-star text-muted' />}\n          </td>\n        </ShowIf>\n        <td className=\"middle\">{item.car.property ? item.car.property : '-'}</td>\n        <ShowIf condition={requestSettings.brand}>\n          {\n            canChangeRequest && !requestSettings.brandReadOnly ?\n              <td className=\"middle\">\n                <AutoCompleteInput\n                  value={item.car.brand}\n                  inputClass={'input-sm'}\n                  items={recommends}\n                  renderItem={(car, index) => (\n                    <div key={index} className=\"item\">\n                      {car.material ? `${car.material} - ` : ''} {car.denomination} <br />\n                      <strong>{car.brand}</strong>\n                    </div>\n                  )}\n                  onChange={(e) => {\n                    const { value } = e.target;\n                    this.props.updateRequestItemInDetailThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          brand: value\n                        }\n                      },\n                      debounce: true\n                    });\n                    this.search(value);\n                  }}\n                  onSelect={(car: any) => {\n                    this.props.updateRequestItemInDetailThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          brand: car.brand,\n                          denomination: car.denomination,\n                          material: car.material ?? ''\n                        }\n                      },\n                      debounce: false\n                    });\n                  }}\n                />\n              </td>\n              : <td className=\"middle\">{item.car.brand}</td>\n          }\n        </ShowIf>\n        <ShowIf condition={requestSettings.denomination}>\n          {\n            canChangeRequest && !requestSettings.denominationReadOnly ?\n              <td className=\"middle\">\n                <AutoCompleteInput\n                  value={item.car.denomination}\n                  inputClass={'input-sm'}\n                  items={recommends}\n                  renderItem={(car, index) => (\n                    <div key={index} className=\"item\">\n                      {car.material ? `${car.material} - ` : ''} {car.denomination} <br />\n                      <strong>{car.brand}</strong>\n                    </div>\n                  )}\n                  onChange={(e) => {\n                    const { value } = e.target;\n                    this.props.updateRequestItemInDetailThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          denomination: value\n                        }\n                      },\n                      debounce: true\n                    });\n                    this.search(value);\n                  }}\n                  onSelect={(car: any) => {\n                    this.props.updateRequestItemInDetailThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          brand: car.brand,\n                          denomination: car.denomination,\n                          material: car.material ?? ''\n                        }\n                      },\n                      debounce: false\n                    });\n                  }}\n                />\n              </td> : <td className=\"middle\">{item.car.denomination}</td>\n          }\n        </ShowIf>\n        <ShowIf condition={requestSettings.material}>\n          {\n            canChangeRequest && !requestSettings.materialReadOnly ?\n              <td className=\"middle\">\n                <AutoCompleteInput\n                  value={item.car.material}\n                  inputClass={'input-sm'}\n                  items={recommends}\n                  renderItem={(car, index) => (\n                    <div key={index} className=\"item\">\n                      {car.material ? `${car.material} - ` : ''} {car.denomination} <br />\n                      <strong>{car.brand}</strong>\n                    </div>\n                  )}\n                  onChange={(e) => {\n                    const { value } = e.target;\n                    this.props.updateRequestItemInDetailThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          material: value\n                        }\n                      },\n                      debounce: true\n                    });\n                    this.search(value);\n                  }}\n                  onSelect={(car: any) => {\n                    this.props.updateRequestItemInDetailThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          brand: car.brand,\n                          denomination: car.denomination,\n                          material: car.material ?? ''\n                        }\n                      },\n                      debounce: false\n                    });\n                  }}\n                />\n              </td> :\n              <td className=\"middle\">{item.car.material}</td>\n          }\n        </ShowIf>\n        <ShowIf condition={requestSettings.color}>\n          {\n            canChangeRequest && !requestSettings.colorReadOnly ?\n              <td className=\"middle\">\n                <input type=\"text\"\n                  className=\"form-control input-sm\"\n                  defaultValue={item.car.color}\n                  onChange={(e: React.ChangeEvent<HTMLInputElement>) => {\n                    this.props.updateRequestItemInDetailThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          color: e.target.value\n                        }\n                      },\n                      debounce: false\n                    });\n                  }}\n                />\n              </td> :\n              <td className=\"middle\">{item.car.color}</td>\n          }\n        </ShowIf>\n        {\n          canChangeRequest ?\n           <td\n              className='middle'\n              style={{ paddingRight: !item.car.vin?.length ? '29px' : undefined }}>\n             <div className='flex'>\n              <AutoCompleteVinInput\n                  defaultValue={item.car.vin}\n                  item={item}\n                  inputClass={'input-sm'}\n                  renderItem={(car, index) => (\n                    <div key={index} className='item'>\n                      {car.vin ? `${car.vin} - ` : ''} {car.denomination} <br />\n                      <strong>{car.brand}</strong>\n                    </div>\n                  )}\n                />\n               </div>\n            </td> :\n            <td className=\"middle\">{item.car.vin}</td>\n        }\n        {\n          canChangeRequest ?\n            <td className=\"middle\">\n              <select className=\"form-control select-sm font-12\" value={item.status?._id ?? ''}\n                onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                  this.props.updateRequestItemInDetailThunkAction({\n                    item: {\n                      ...item,\n                      status: {\n                        ...item.status,\n                        _id: e.target.value\n                      }\n                    },\n                    debounce: false\n                  });\n                }}\n              >\n                <option value=\"\" disabled={true}>-</option>\n                {\n                  requestItemStatus.map((req) => (\n                    <option key={req._id} value={req._id}>{req.name}</option>\n                  ))\n                }\n\n              </select>\n            </td> :\n            <td className=\"middle\">{item.status?.name}</td>\n        }\n        <ShowIf condition={requestSettings.ticket}>\n          <td className='middle-center'>\n            {\n              //request.advancePaymentInformation.files[0].file.url\n              request.advancePaymentInformation?.files?.length ?\n                <i\n                  className='fa fa-check-circle text-green pointer'\n                  onClick={() => this.openBlank(request.advancePaymentInformation.files[0].file.url)}\n                /> : ''\n            }\n          </td>\n          <td className='middle'>{request.advancePaymentInformation?.number}</td>\n        </ShowIf>\n        <ShowIf condition={requestSettings.internalNumber}>\n          {\n            canChangeRequest ?\n              <td className=\"middle\">\n                <input type=\"text\"\n                  className=\"form-control input-sm\"\n                  defaultValue={item.car.internalNumber}\n                  onChange={(e: React.ChangeEvent<HTMLInputElement>) => {\n                    this.props.updateRequestItemInDetailThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          internalNumber: e.target.value\n                        }\n                      },\n                      debounce: false\n                    });\n                  }}\n                />\n              </td> :\n              <td className=\"middle\">{item.car.internalNumber}</td>\n          }\n        </ShowIf>\n        <ShowIf condition={requestSettings.reason}>\n          {\n            canChangeRequest ?\n              <td className=\"middle\">\n                <select\n                  className=\"form-control select-sm font-12\" value={item.reason?._id ?? ''}\n                  onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                    this.props.updateRequestItemInDetailThunkAction({\n                      item: {\n                        ...item,\n                        reason: {\n                          ...item.reason,\n                          _id: e.target.value\n                        }\n                      },\n                      debounce: false\n                    });\n                  }}\n                >\n                  <option value=\"\" disabled={true}>-</option>\n                  {\n                    reasons.map((reason) => (\n                      <option key={reason._id} value={reason._id}>{reason.name}</option>\n                    ))\n                  }\n                </select>\n              </td> :\n              <td className=\"middle\">{item.reason?.name}</td>\n          }\n        </ShowIf>\n        <td\n          className={`middle-center ${item.files && item.files.length ? 'pointer' : ''}`}\n          onClick={() => this.downloadFiles(item)}\n        >\n          {\n            item.files && item.files.length ?\n              <span\n                data-toggle={'tooltip'}\n                data-placement={'top'}\n                title={`${item.files.length} archivos adjuntos.`}\n              >\n                <i className=\"fa fa-paperclip\" /> ({item.files.length})\n              </span> : null\n          }\n        </td>\n        <td className=\"middle-center\">\n          {\n            item.observation && item.observation.length ?\n              <i\n                className=\"fa fa-comment\"\n                data-toggle=\"tooltip\"\n                data-placement=\"top\"\n                title={item.observation}\n              /> : null\n          }\n        </td>\n        {/* <td className=\"middle\">\n          <div className=\"flex-wrap\">\n            <div\n              className={`flex-wrap-item-center ${canChangeRequest ? 'pointer' : ''} ${item.equipment ? '' : 'text-gray'}`}\n              data-toggle=\"tooltip\"\n              data-placement=\"top\"\n              title=\"Accesorización\"\n              onClick={canChangeRequest ? () => {\n                this.props.updateRequestItemInDetailThunkAction({\n                  item: {\n                    ...item,\n                    equipment: !item.equipment\n                  },\n                  debounce: false\n                });\n              } : undefined}\n            >\n              <i className=\"material-icons font-14\">library_add</i>\n            </div>\n            <div\n              className={`flex-wrap-item-center ${canChangeRequest ? 'pointer' : ''} ${item.body ? '' : 'text-gray'}`}\n              data-toggle=\"tooltip\"\n              data-placement=\"top\"\n              title=\"Carrocero\"\n              onClick={canChangeRequest ? () => {\n                this.props.updateRequestItemInDetailThunkAction({\n                  item: {\n                    ...item,\n                    body: !item.body\n                  },\n                  debounce: false\n                });\n              } : undefined}\n            >\n              <i className=\"material-icons font-14\">rv_hookup</i>\n            </div>\n          </div>\n        </td>\n        <td className=\"middle\">\n          <div className=\"flex-wrap\">\n            <div\n              className={`flex-wrap-item-center ${canChangeRequest ? 'pointer' : ''} ${item.washed ? '' : 'text-gray'}`}\n              data-toggle=\"tooltip\"\n              data-placement=\"top\"\n              title=\"Pre-Lavado\"\n              onClick={canChangeRequest ? () => {\n                this.props.updateRequestItemInDetailThunkAction({\n                  item: {\n                    ...item,\n                    washed: !item.washed\n                  },\n                  debounce: false\n                });\n              } : undefined}\n            >\n              <i className=\"material-icons font-14\">local_car_wash</i>\n            </div>\n            <div\n              className={`flex-wrap-item-center ${canChangeRequest ? 'pointer' : ''} ${item.review ? '' : 'text-gray'}`}\n              data-toggle=\"tooltip\"\n              data-placement=\"top\"\n              title=\"Inspección Pre-entrega\"\n              onClick={canChangeRequest ? () => {\n                this.props.updateRequestItemInDetailThunkAction({\n                  item: {\n                    ...item,\n                    review: !item.review\n                  },\n                  debounce: false\n                });\n              } : undefined}\n            >\n              <i className=\"material-icons font-14\">build</i>\n            </div>\n          </div>\n        </td> */}\n        {/*\n          canChangeRequest ?\n            <td className=\"middle\">\n              <select className=\"form-control select-sm font-12\" value={item.carrier?._id ?? ''}\n                onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                  this.props.updateRequestItemInDetailThunkAction({\n                    item: {\n                      ...item,\n                      carrier: !e.target.value.length ? null : {\n                        ...item.carrier,\n                        _id: (e.target.value as any)\n                      }\n                    },\n                    debounce: false\n                  });\n                }}\n              >\n                <option value=\"\">-</option>\n                {\n                  carriers.map((carrier) => (\n                    <option key={carrier._id} value={carrier._id}>{carrier.name}</option>\n                  ))\n                }\n              </select>\n            </td> :\n            <td className=\"middle\">{item.carrier?.name}</td>\n            */\n        }\n        {/*\n          canChangeRequest ?\n            <td className=\"middle\">\n              <DateRangePicker\n                className={'input-sm'}\n                value={item.uploadDate}\n                onChange={(e) => {\n                  this.props.updateRequestItemInDetailThunkAction({\n                    item: {\n                      ...item,\n                      uploadDate: e as any\n                    },\n                    debounce: false\n                  });\n                }}\n              />\n            </td> :\n            <td className=\"middle\">{item.uploadDate ? moment(item.uploadDate).format('DD-MM-YY') : '-'}</td>\n            */\n        }\n        { /*\n          canChangeRequest ?\n            <td className=\"middle\">\n              <DateRangePicker\n                className={'input-sm'}\n                value={item.estimatedArrival}\n                onChange={(e) => {\n                  this.props.updateRequestItemInDetailThunkAction({\n                    item: {\n                      ...item,\n                      estimatedArrival: e as any\n                    },\n                    debounce: false\n                  });\n                }}\n              />\n            </td>\n            :<td className=\"middle\">{item.estimatedArrival ? moment(item.estimatedArrival).format('DD-MM-YY') : '-'}</td>\n            */\n        }\n        <ShowIf condition={hasPermission(window.user, 'deleteRequest')}>\n          <td className=\"middle-center text-red pointer\" onClick={() => this.deleteRequestItem(item)}>\n            <i className=\"fa fa-minus-circle\" />\n          </td>\n        </ShowIf>\n      </tr>\n    );\n  }\n\n  private downloadFiles(item: IRequestItem) {\n    if (item.files && item.files.length) {\n      this.openBlank(`/requests-item/${item._id}/download-files/`);\n    }\n  }\n\n  private openBlank(url: string) {\n    window.open(decodeURI(url), '_blank');\n  }\n\n  private search(text: string): void {\n    this.$subjectRecommends.next(text)\n  }\n\n  private searchVin(vin: string): void {\n    this.$subjectVINRecommends.next(vin)\n  }\n\n  private deleteRequestItem(item: IRequestItem) {\n    const {request} = this.props;\n    if (request.items.length > 1) {\n      swal({\n        title: '¿Estás seguro?',\n        text: `Vas a eliminar este vehículo ${item.car.brand} ${item.car.denomination} ${item.car.material}.`,\n        icon: 'warning',\n        dangerMode: true,\n        buttons: {\n          cancel: 'Cancelar' as any,\n          confirm: {\n            text: 'Sí'\n          }\n        }\n      }).then((willDelete) => {\n        if (willDelete) {\n          this.props.deleteRequestItemThunkAction(item);\n        }\n      });\n    } else {\n      swal({\n        title: '¿Estás seguro?',\n        text: `Si eliminas este último vehículo, vas a eliminar esta solicitud.`,\n        icon: 'warning',\n        dangerMode: true,\n        buttons: {\n          cancel: 'Cancelar' as any,\n          confirm: {\n            text: 'Sí'\n          }\n        }\n      }).then((willDelete) => {\n        if (willDelete) {\n          this.props.deleteRequestThunkAction(request._id);\n        }\n      });\n    }\n  }\n}\n\nconst mapStateToProps = (state: { requests: IRequestsState }) => {\n  return {\n    requests: state.requests\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    updateRequestItemInDetailThunkAction: ({ item, debounce }: { item: IRequestItem, debounce?: boolean }) => dispatch(updateRequestItemInDetailThunkAction({ item, debounce })),\n    deleteRequestItemThunkAction: (item: IRequestItem) => dispatch(deleteRequestItemThunkAction(item)),\n    deleteRequestThunkAction: (idRequest: string) => dispatch(deleteRequestThunkAction(idRequest))\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType | any>(mapStateToProps, mapDispatchToProps)(RequestItem);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { Dispatch, ErrorInfo, Fragment } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport { IRequestItem } from '../../../../../../../src/request/interfaces/requestItem.interface';\nimport {\n  createRequestItemActionInList,\n  deleteRequestActionInList,\n  deleteRequestItemActionInList,\n  getRequestsThunkAction,\n  updateRequestItemActionInList\n} from '../../../actions/requests.actions';\nimport { IRequestsState } from '../../../actions/requests.types';\nimport AppContainer from '../../../container/AppContainer';\nimport { IWindow } from '../../../interfaces/window';\nimport { hasPermission, parseReplicableURL } from '../../../utils/common';\nimport ImageLazyLoad from '../../Utils/ImageLazyLoad';\nimport Paginator from '../../Utils/Paginator';\nimport ShowIf from '../../Utils/ShowIf';\nimport RequestListDetail from './RequestDetail';\nimport TrackingBasePage from '../../Utils/TrackingBasePage';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  requests: IRequestsState;\n  dispatch: Dispatch<IRequestsState>;\n  updateRequestItemActionInList: (idRequest: string, item: IRequestItem) => void;\n  getRequestsThunkAction: (page: number, orderBy: string, orderType: string, hideLoading?: boolean) => void;\n  deleteRequestItemActionInList: (idRequest: string, item: IRequestItem) => void;\n  deleteRequestActionInList: (id: string) => void;\n  createRequestItemActionInList: (idRequest: string, item: IRequestItem) => void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass RequestListView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  readonly state = {\n    error: null,\n    exporing: false\n  };\n\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Solicitudes';\n    this.create = this.create.bind(this);\n    this.changeOrder = this.changeOrder.bind(this);\n    this.changePage = this.changePage.bind(this);\n    this.exportExcel = this.exportExcel.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const {orderBy, orderType} = this.props.requests.options;\n    const {page} = this.props.requests.pagination;\n    window.scrollTo(0, 0);\n\n    this.props.getRequestsThunkAction(page, orderBy, orderType);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: window.user.token\n      }\n    });\n\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {room: `request-list-${window.user.team._id}`});\n    });\n\n    this.socket.on('UPDATE_REQUEST_ITEM', (data: any): void => {\n      this.props.updateRequestItemActionInList(data.idRequest, data.item);\n      const $item = $(`#request-item-${data.item._id}`);\n      if ($item) {\n        $item.addClass('bg-aqua-active');\n        setTimeout(() => {\n          $item.removeClass('bg-aqua-active');\n        }, 300);\n      }\n    });\n\n    this.socket.on('DELETE_REQUEST_ITEM', (data: any): void => {\n      const $item = $(`#request-item-${data.item._id}`);\n      if ($item) {\n        $item.addClass('bg-red-active');\n      }\n      setTimeout(() => {\n        this.props.deleteRequestItemActionInList(data.idRequest, data.item);\n      }, 300);\n    });\n\n    this.socket.on('DELETE_REQUEST', (data: any): void => {\n      const $item = $(`#request-${data.idRequest}`);\n      if ($item) {\n        $item.addClass('bg-red-active');\n      }\n      setTimeout(() => {\n        this.props.deleteRequestActionInList(data.idRequest);\n      }, 300);\n    });\n\n    this.socket.on('CREATE_REQUEST', (): void => {\n      const { page } = this.props.requests.pagination;\n      const { orderBy, orderType } = this.props.requests.options;\n      this.props.getRequestsThunkAction(page, orderBy, orderType, true);\n    });\n\n    this.socket.on('CREATE_REQUEST_ITEM', (data: any): void => {\n      this.props.createRequestItemActionInList(data.idRequest, data.item);\n        const $item = $(`#request-item-${data.item._id}`);\n        if ($item) {\n          $item.addClass('bg-green-active');\n        }\n        setTimeout(() => {\n          $item.removeClass('bg-green-active');\n        }, 300);\n    });\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    window.scrollTo(0, 0);\n  }\n\n  public componentDidUpdate(prevProps: IPropsType): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.requests.source) {\n      this.props.requests.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.emit('leave', {room: `request-list-${window.user.team._id}`});\n    this.socket.disconnect();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      pagination, loading, requests, reasons, requestItemStatus, carriers\n    } = this.props.requests;\n    const {orderBy, orderType} = this.props.requests.options;\n    const {exporing} = this.state;\n    return (\n      <AppContainer title=\"\" cMenu=\"3\" cSubMenu=\"3.1\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Solicitudes <small>{pagination.count}</small></h3>\n              <div className=\"pull-right box-tools\">\n                {\n                  hasPermission(window.user, 'createRequest') ?\n                    <button className=\"btn btn-sm btn-success\" onClick={this.create}>\n                      <i className=\"fa fa-fw fa-plus\" /> Crear solicitud\n                    </button>\n                    : null\n                }\n                <ShowIf condition={requests.length > 0}>\n                  <button\n                    className=\"btn btn-sm btn-primary hidden-xs\"\n                    onClick={this.exportExcel}\n                    disabled={exporing}\n                    style={{ marginLeft: '5px' }}\n                  >\n                    {\n                      exporing ? <Fragment><i className=\"fa fa-spin fa-spinner\" /> Exportando</Fragment>\n                        : <Fragment><i className=\"fa fa-fw fa-download\" /> Exportar</Fragment>\n                    }\n                  </button>\n                </ShowIf>\n              </div>\n            </div>\n            <div className=\"box-body table-responsive request-list\">\n              <ShowIf condition={requests.length > 0}>\n                <div className=\"row request bg-primary\">\n                  <div className=\"col-sm-1 col-xs-1 col-md-1 col-lg-1 center pointer head-sorted\" onClick={() => this.changeOrder('_id')}>\n                    <strong>ID</strong> <i className={`fa ${orderBy === '_id' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} />\n                  </div>\n                  <div className=\"col-sm-1 col-xs-1 col-md-1 col-lg-1\">\n                    <strong>Canal</strong>\n                  </div>\n                  <div className=\"col-sm-2 col-xs-2 col-md-2 col-lg-2\">\n                    <strong>Vendedor</strong>\n                  </div>\n                  <div className=\"col-sm-2 col-xs-2 col-md-2 col-lg-2\">\n                    <strong>Destino</strong>\n                  </div>\n                  <div className=\"col-sm-1 col-xs-1 col-md-1 col-lg-1\">\n                    <strong>Nº Unidades</strong>\n                  </div>\n                  <div className=\"col-sm-2 col-xs-2 col-md-2 col-lg-2  pointer head-sorted\" onClick={() => this.changeOrder('createdAt')}>\n                    <strong>Fecha Creación</strong> <i className={`fa ${orderBy === 'createdAt' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} />\n                  </div>\n                  <div className=\"col-sm-2 col-xs-2 col-md-2 col-lg-2  pointer head-sorted\" onClick={() => this.changeOrder('updatedAt')}>\n                    <strong>Última Actualización</strong> <i className={`fa ${orderBy === 'updatedAt' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} />\n                  </div>\n                  {/* <div className=\"col-sm-1 col-xs-1 col-md-1 col-lg-1 center\"> */}\n                    {/* <strong><i className=\"fa fa-comment\" /></strong> */}\n                  {/* </div> */}\n                  <div className=\"col-sm-1 col-xs-1 col-md-1 col-lg-1\" />\n                </div>\n                {\n                  requests.map((request: any) => (\n                    <RequestListDetail\n                      request={request}\n                      requestItemStatus={requestItemStatus}\n                      reasons={reasons}\n                      carriers={carriers}\n                      key={request._id}\n                      {...this.props}\n                    />\n                  ))\n                }\n              </ShowIf>\n              <ShowIf condition={!loading && requests.length === 0}>\n                <div className=\"row\">\n                  <div className=\"col-md-12 text-center\" style={{paddingTop: '10px', paddingBottom: '10px'}}>\n                      <ImageLazyLoad\n                        url=\"/images/not_found.png\"\n                        height={'200px'}\n                        style={{\n                          opacity: 0.5,\n                          maxHeight: '200px',\n                          marginBottom: '10px'\n                        }}\n                        replaceLoading={<i\n                          className={'fa fa-2x fa-circle-o-notch text-primary fa-spin'}\n                          style={{ padding: '30px' }}\n                        />}\n                      /><br />\n                      <strong>No hay información para mostrar</strong>\n                  </div>\n                </div>\n              </ShowIf>\n            </div>\n            <div className='box-footer'>\n              <div className='row'>\n                <div className='col-md-12'>\n                  <ShowIf condition={pagination.pages > 1}>\n                    <div className='row'>\n                      <div className='col-md-6' style={{ padding: '20px 15px' }}>\n                          <span className='react-bootstrap-table-pagination-total text-ellipsis'>\n                            &nbsp;&nbsp;Mostrando registros del {(pagination.page - 1) * 20 + 1} al {(pagination.page) * 20} de {pagination.count} registros.\n                          </span>\n                      </div>\n                      <div className='col-md-6'>\n                        <div className='text-right' style={{ marginRight: '15px' }}>\n                          <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                        </div>\n                      </div>\n                    </div>\n                  </ShowIf>\n                </div>\n              </div>\n            </div>\n            <ShowIf condition={loading}>\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            </ShowIf>\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private changeOrder(key: string) {\n    const { page } = this.props.requests.pagination;\n    const { orderBy, orderType } = this.props.requests.options;\n    let newOrderType = orderType;\n    let newOrderBy = orderBy;\n    if (key === orderBy) {\n      newOrderType = orderType === 'descending' ? 'ascending' : 'descending';\n    } else {\n      newOrderBy = key;\n    }\n    this.props.getRequestsThunkAction(page, newOrderBy, newOrderType);\n  }\n\n  private create(): void {\n    this.props.history.push(parseReplicableURL('/requests/create/'));\n  }\n\n  private changePage(page: number): void {\n    const {orderBy, orderType} = this.props.requests.options;\n    this.props.getRequestsThunkAction(page, orderBy, orderType);\n  }\n\n  public exportExcel() {\n    this.trackClick(\"Exportar\");\n    window.open(`/requests/export/`, '_blank');\n    // this.setState({\n    //   exporing: true\n    // });\n    // const api: ApiService = new ApiService();\n    // const instance = api.getInstance();\n    // instance.defaults.responseType = 'blob';\n    // instance\n    //   .get(`/requests/export/`)\n    //   .then((response) => {\n    //     const blob = new Blob([response.data], {\n    //       type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'\n    //     });\n    //     const fileName = `${moment().format('YYYYMMDD')}-solicitudes.xlsx`;\n    //     if (typeof window.navigator.msSaveBlob !== 'undefined') {\n    //       // IE workaround for \"HTML7007: One or more blob URLs were\n    //       // revoked by closing the blob for which they were created.\n    //       // These URLs will no longer resolve as the data backing\n    //       // the URL has been freed.\"\n    //       window.navigator.msSaveBlob(blob, fileName);\n    //     } else {\n    //       const blobURL = URL.createObjectURL(blob);\n    //       const tempLink = document.createElement('a');\n    //       tempLink.style.display = 'none';\n    //       tempLink.href = blobURL;\n    //       tempLink.setAttribute('download', fileName);\n    //       // Safari thinks _blank anchor are pop ups. We only want to set _blank\n    //       // target if the browser does not support the HTML5 download attribute.\n    //       // This allows you to download files in desktop safari if pop up blocking\n    //       // is enabled.\n    //       if (typeof tempLink.download === 'undefined') {\n    //         tempLink.setAttribute('target', '_blank');\n    //       }\n    //       this.setState({\n    //         exporing: false\n    //       });\n    //       document.body.appendChild(tempLink);\n    //       tempLink.click();\n    //       document.body.removeChild(tempLink);\n    //       URL.revokeObjectURL(blobURL);\n    //     }\n    //   })\n    //   .catch((err) => {\n    //     this.setState({\n    //       exporing: false\n    //     });\n    //     if (!Axios.isCancel(err)) {\n    //       swal('Exportar usuarios', 'Ha ocurrido un error al general el excel.', 'error');\n    //     }\n    //   });\n  }\n\n}\n\nconst mapStateToProps = (state: { requests: IRequestsState }) => {\n  return {\n    requests: state.requests\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getRequestsThunkAction: (page: number, orderBy: string, orderType: string, hideLoading?: boolean) => dispatch(getRequestsThunkAction(page, orderBy, orderType, hideLoading)),\n    createRequestItemActionInList: (idRequest: string, item: IRequestItem) => dispatch(createRequestItemActionInList(idRequest, item)),\n    updateRequestItemActionInList: (idRequest: string, item: IRequestItem) => dispatch(updateRequestItemActionInList(idRequest, item)),\n    deleteRequestItemActionInList: (idRequest: string, item: IRequestItem) => dispatch(deleteRequestItemActionInList(idRequest, item)),\n    deleteRequestActionInList: (id: string) => dispatch(deleteRequestActionInList(id))\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(RequestListView);\n","import * as moment from 'moment-timezone';\nimport * as React from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { ICarrier } from '../../../../../../../src/app/interfaces/carrier.interface';\nimport { IReason } from '../../../../../../../src/request/interfaces/reason.interface';\nimport { IRequest } from '../../../../../../../src/request/interfaces/request.interface';\nimport { IRequestItem } from '../../../../../../../src/request/interfaces/requestItem.interface';\nimport { IRequestItemStatus } from '../../../../../../../src/request/interfaces/requestItemStatus.interface';\nimport { tabStatusAction, updateRequestItemInListThunkAction } from '../../../actions/requests.actions';\nimport { IRequestsState } from '../../../actions/requests.types';\nimport { IWindow } from '../../../interfaces/window';\nimport { hasPermission, parseReplicableURL } from '../../../utils/common';\nimport ShowIf from '../../Utils/ShowIf';\n\ndeclare let window: IWindow;\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  requests: IRequestsState;\n  key: any;\n  request: IRequest;\n  reasons: IReason[];\n  carriers: ICarrier[];\n  requestItemStatus: IRequestItemStatus[];\n  updateRequestItemInListReduxAction: (idRequest: string, item: IRequestItem) => void;\n  tabStatusAction: (request: string) => void;\n}\n\ninterface IStateType {\n  open: boolean;\n  error: Error | null;\n}\n\nconst getColorForPercentage = (value: number): string => {\n  if (value < 40) {\n    return '#00c0ef';\n  } else if (value < 60) {\n    return '#f39c12';\n  } else {\n    return '#00a65a';\n  }\n};\n\nclass RequestListDetail extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null,\n    open: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.goToDetail = this.goToDetail.bind(this);\n    this.downloadFiles = this.downloadFiles.bind(this);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { requests, request, reasons, requestItemStatus } = this.props;\n    const { requestSettings } = requests;\n    const open = this.props.requests.requestOpen.includes(request._id);\n    const canChangeRequest = hasPermission(window.user, 'changeRequest');\n    return (\n      <React.Fragment>\n        <div id={`request-${request._id}`} className='row request bg-request-title background-transition'>\n          <div\n            className='col-sm-1 col-xs-1 col-md-1 col-lg-1 pointer center'\n            onClick={() => this.goToDetail(request._id)}\n          >\n            {/* <i className=\"fa fa-circle status-circle-red\" /> */}\n            <strong className='text-underline'>\n              #{request.number}\n            </strong>&nbsp;\n            <i className='fa fa-share-square-o' style={{ fontSize: '10px' }} />\n          </div>\n          <div className='col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n            {request.channel ? request.channel.name : ''}\n            {/* {\n              request.fleet ?\n                <i className=\"fa fa-check-circle-o text-green\" />\n                : null\n            } */}\n          </div>\n          <div className='col-sm-2 col-xs-2 col-md-2 col-lg-2'>{request.sellerText?.length ? request.sellerText : '-'}</div>\n          <div className='col-sm-2 col-xs-2 col-md-2 col-lg-2'>{request.destination.name}</div>\n          <div className='col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n            {\n              request.items.length\n            }\n          </div>\n          <div className='col-sm-2 col-xs-2 col-md-2 col-lg-2'>\n            {moment(request.createdAt).format('DD-MM-YY')}\n          </div>\n          <div className='col-sm-2 col-xs-2 col-md-2 col-lg-2'>\n            {moment(request.updatedAt).format('DD-MM-YY')}\n          </div>\n          {/* <div className=\"col-sm-1 col-xs-1 col-md-1 col-lg-1 center\"> */}\n          {/* 10 */}\n          {/* </div> */}\n          <div className='col-sm-1 col-xs-1 col-md-1 col-lg-1 chevron pointer' onClick={() => this.props.tabStatusAction(request._id)}>\n            {\n              open ? (<i className='fa fa-chevron-up' />) : (<i className='fa fa-chevron-down' />)\n            }\n          </div>\n        </div>\n        <div className='table-request' style={{ display: open ? 'block' : 'none' }}>\n          <ShowIf condition={!this.props.requests.requestItemsById.hasOwnProperty(request._id)}>\n            <div className='text-center' style={{\n              padding: '10px',\n              borderBottom: '1px solid #e1e1e1',\n              borderLeft: '1px solid #e1e1e1',\n              borderRight: '1px solid #e1e1e1',\n            }}>\n              <i className=\"fa fa-spinner fa-spin text-purple\"/>\n            </div>\n          </ShowIf>\n          <ShowIf condition={this.props.requests.requestItemsById.hasOwnProperty(request._id)}>\n            <table className='table table-hover'>\n              <thead>\n              <tr style={{ backgroundColor: '#f9f9f9' }}>\n                <th className='middle' style={{ width: '28px' }} />\n                <th className='middle' style={{ width: '100px' }}>Progreso</th>\n                <th className='middle' style={{ width: '120px' }}>Estado</th>\n                <th className='middle' style={{ width: '220px' }}>Modelo</th>\n                <th className='middle' style={{ width: '120px' }}>Color</th>\n                <th className='middle' style={{ width: '160px' }}>VIN</th>\n                <ShowIf condition={requestSettings.ticket}>\n                  <th className='middle-center pointer' style={{ width: '60px' }}>\n                    Ticket\n                  </th>\n                  <th className='middle pointer' style={{ width: '80px' }}>\n                    Nº Ticket\n                  </th>\n                </ShowIf>\n                <ShowIf condition={requestSettings.entry}>\n                  <th>Partida</th>\n                </ShowIf>\n                <th>OT</th>\n                <th>F. emisión</th>\n                <th>F. carga</th>\n                <th>F. arribo</th>\n                <th className='middle-center' style={{ width: '20px' }}>Adj</th>\n                <th className='middle'>Obs</th>\n                {/* <th className=\"middle-center\">Equip. / Carroc. / Preentrega</th> */}\n                <ShowIf condition={requestSettings.reason}>\n                  <th className='middle' style={{ width: '150px' }}>Motivo</th>\n                </ShowIf>\n                {/* <th className=\"middle\" >Transporte</th>\n                <th  className=\"middle\" style={{ width: '70px' }}>Fecha carga</th>\n                <th className=\"middle\"  style={{ width: '70px' }}>Fecha llegada</th> */}\n                <th />\n              </tr>\n              </thead>\n              <tbody>\n              {\n                (this.props.requests.requestItemsById[request._id] || []).map((item: any) => (\n                  <tr key={item._id} id={`request-item-${item._id}`} className={'background-transition'}>\n                    <td className='middle-center'>\n                      {item.priority ?\n                        <i className='fa fa-star text-yellow' />\n                        : null}\n                    </td>\n                    <td className='middle'>\n                      <div className='progress progress-xs'>\n                        <div\n                          className={`progress-bar progress-bar-aqua`}\n                          style={{\n                            width: `${(item.status?.weigth ?? 0)}%`,\n                            backgroundColor: getColorForPercentage(100 / requests.requestItemStatusMax * (item.status?.weigth ?? 0))\n                          }}\n                        />\n                      </div>\n                    </td>\n                    {\n                      canChangeRequest ?\n                        <td className='middle'>\n                          <select className='form-control select-sm font-12' value={item.status?._id ?? ''}\n                                  onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                                    this.props.updateRequestItemInListReduxAction!(request._id, {\n                                      ...item,\n                                      status: e.target.value\n                                    });\n                                  }}\n                          >\n                            <option value='' disabled={true}>-</option>\n                            {\n                              requestItemStatus.map((req) => (\n                                <option key={req._id} value={req._id}>{req.name}</option>\n                              ))\n                            }\n\n                          </select>\n                        </td> :\n                        <td className='middle'>{item.status?.name}</td>\n                    }\n                    <td className='middle'>\n                      {`${item.car.brand} ${item.car.denomination} ${item.car.material ?? ''}`}\n                    </td>\n                    <td className='middle'>\n                      {item.car.color}\n                    </td>\n                    <td className={`middle`}>\n                      <ShowIf condition={item.car.vin?.length}>\n                        <a\n                          href={parseReplicableURL(`/settings/cars/${item.car._id}/`)}\n                          target='_blank'\n                          style={{\n                            textDecoration: 'underline'\n                          }}\n                        >\n                          {item.car.vin} <i className='fa fa-fw fa-share-alt-square' />\n                        </a>\n                      </ShowIf>\n                    </td>\n                    <ShowIf condition={requestSettings.ticket}>\n                      <td className='middle-center'>\n                        {\n                          //request.advancePaymentInformation.files[0].file.url\n                          request.advancePaymentInformation?.files?.length ?\n                            <i\n                              className='fa fa-check-circle text-green pointer'\n                              onClick={() => this.openBlank(request.advancePaymentInformation.files[0].file.url)}\n                            /> : ''\n                        }\n                      </td>\n                      <td className='middle'>{request.advancePaymentInformation?.number}</td>\n                    </ShowIf>\n                    <ShowIf condition={requestSettings.entry}>\n                      <td className='middle'>\n                        {\n                          item.car.entry && item.car.entry.length ? item.car.entry : null\n                        }\n                      </td>\n                    </ShowIf>\n                    <td\n                      className={`middle ${item.transmittal?.number ? 'pointer' : ''}`}\n                      onClick={item.transmittal?.number ? () => this.openOT(item.transmittal.number.toString()) : undefined}\n                    ><strong>{item?.transmittal?.number ? `#${item?.transmittal?.number}`: '-'}</strong></td>\n                    <td className='middle'>{item.transmittalItem?.loadingDate ? moment(item.transmittalItem.loadingDate).format('DD-MM-YYYY') : '-'}</td>\n                    <td className='middle'>{item?.transmittalItem?.revisions?.length ? moment(item.transmittalItem.revisions[item.transmittalItem.revisions.length -1].createdAt).format('DD-MM-YY'): '-'}</td>\n                    <td className='middle'>{item?.transmittal?.revision ? moment(item.transmittal.revision.createdAt).format('DD-MM-YY'): '-'}</td>\n                    {/*<td>{item.transmittalItem?.arrivalDate ? moment(item.transmittalItem.arrivalDate).format('DD-MM-YYYY') : '-'}</td>*/}\n                    <td\n                      className={`middle-center ${item.files && item.files.length ? 'pointer' : ''}`}\n                      onClick={item.files?.length ? () => this.downloadFiles(item) : undefined}\n                    >\n                      {\n                        item.files?.length ?\n                          <i\n                            className='fa fa-paperclip'\n                            data-toggle='tooltip'\n                            data-placement='top'\n                            title={`${item.files.length} archivos adjuntos.`}\n                          /> : null\n                      }\n                    </td>\n                    <td className='middle-center'>\n                      {\n                        item.observation && item.observation.length ?\n                          <i\n                            className='fa fa-comment'\n                            data-toggle='tooltip'\n                            data-placement='top'\n                            title={item.observation}\n                          /> : null\n                      }\n                    </td>\n                    {/* <td className=\"middle\">\n                      <div className=\"flex-wrap\">\n                        <div\n                          className={`flex-wrap-item-center ${item.equipment ? '' : 'text-gray'}`}\n                          data-toggle=\"tooltip\"\n                          data-placement=\"top\"\n                          title=\"Accesorización\"\n                        >\n                          <i className=\"material-icons\">library_add</i>\n                        </div>\n                        <div\n                          className={`flex-wrap-item-center ${item.body ? '' : 'text-gray'}`}\n                          data-toggle=\"tooltip\"\n                          data-placement=\"top\"\n                          title=\"Carrocero\"\n                        >\n                          <i className=\"material-icons\">rv_hookup</i>\n                        </div>\n                        <div\n                          className={`flex-wrap-item-center ${item.washed ? '' : 'text-gray'}`}\n                          data-toggle=\"tooltip\"\n                          data-placement=\"top\"\n                          title=\"Pre-Lavado\"\n                        >\n                          <i className=\"material-icons\">local_car_wash</i>\n                        </div>\n                        <div\n                          className={`flex-wrap-item-center ${item.review ? '' : 'text-gray'}`}\n                          data-toggle=\"tooltip\"\n                          data-placement=\"top\"\n                          title=\"Inspección Pre-entrega\"\n                        >\n                          <i className=\"material-icons\">build</i>\n                        </div>\n                      </div>\n                    </td> */}\n                    <ShowIf condition={requestSettings.reason}>\n                      {\n                        canChangeRequest ?\n                          <td className='middle'>\n                            <select\n                              className='form-control select-sm font-12' value={item.reason?._id ?? ''}\n                              onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                                this.props.updateRequestItemInListReduxAction!(request._id, {\n                                  ...item,\n                                  reason: e.target.value\n                                });\n                              }}\n                            >\n                              <option value='' disabled={true}>-</option>\n                              {\n                                reasons.map((reason) => (\n                                  <option key={reason._id} value={reason._id}>{reason.name}</option>\n                                ))\n                              }\n                            </select>\n                          </td> :\n                          <td className='middle'>{item.reason?.name}</td>\n                      }\n                    </ShowIf>\n                    { /*\n                      canChangeRequest ?\n                        <td className=\"middle\">\n                          <select className=\"form-control select-sm font-12\" value={item.carrier?._id ?? ''}\n                            onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                              this.props.updateRequestItemInListReduxAction!(request._id, {\n                                ...item,\n                                carrier: !e.target.value.length ? null : e.target.value\n                              });\n                            }}\n                          >\n                            <option value=\"\">-</option>\n                            {\n                              carriers.map((carrier) => (\n                                <option key={carrier._id} value={carrier._id}>{carrier.name}</option>\n                              ))\n                            }\n                          </select>\n                        </td> :\n                        <td className=\"middle\">{item.carrier?.name}</td>\n                        */\n                    }\n                    { /*\n                      canChangeRequest ?\n                        <td className=\"middle\">\n                          <DateRangePicker\n                            className={'input-sm'}\n                            value={item.uploadDate}\n                            onChange={(e) => {\n                              this.props.updateRequestItemInListReduxAction!(request._id, {\n                                ...item,\n                                uploadDate: e\n                              });\n                            }}\n                          />\n                        </td> :\n                        <td className=\"middle\">{item.uploadDate ? moment(item.uploadDate).format('DD-MM-YY') : '-'}</td>\n                        */\n                    }\n                    { /*\n                      canChangeRequest ?\n                        <td className=\"middle\">\n                          <DateRangePicker\n                            className={'input-sm'}\n                            value={item.estimatedArrival}\n                            onChange={(e) => {\n                              this.props.updateRequestItemInListReduxAction!(request._id, {\n                                ...item,\n                                estimatedArrival: e\n                              });\n                            }}\n                          />\n                        </td> :\n                        <td className=\"middle\">{item.estimatedArrival ? moment(item.estimatedArrival).format('DD-MM-YY') : '-'}</td>\n                        */\n                    }\n                    <td></td>\n                  </tr>\n                ))\n              }\n              </tbody>\n            </table>\n          </ShowIf>\n        </div>\n      </React.Fragment>\n    );\n  }\n\n  private openOT(number: string) {\n    window.open(parseReplicableURL(`/transmittals/?number=${number}`), '_blank');\n  }\n\n  private downloadFiles(item: IRequestItem) {\n    window.open(`/requests-item/${item._id}/download-files/`, '_blank');\n  }\n\n  private openBlank(url: string) {\n    window.open(url, '_blank');\n  }\n\n  private goToDetail(id: string): void {\n    this.props.history.push(parseReplicableURL(`/requests/${id}/`));\n  }\n}\n\nconst mapStateToProps = (state: { requests: IRequestsState }) => {\n  return {\n    requests: state.requests\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    updateRequestItemInListReduxAction: (idRequest: string, item: IRequestItem) => dispatch(updateRequestItemInListThunkAction(idRequest, item)),\n    tabStatusAction: (request: string) => dispatch(tabStatusAction(request))\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType | any>(mapStateToProps, mapDispatchToProps)(RequestListDetail);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo, RefObject } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport * as swal from 'sweetalert';\nimport * as XLSX from 'xlsx';\nimport { IRequestItemsState, RequestItemsReduxActions } from '../../actions/requestItems.types';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport ApiService from '../../utils/axios';\nimport ModalView from '../Modal/ModalView';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport { parseReplicableURL } from '../../utils/common';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  requestItems: IRequestItemsState;\n  dispatch: Dispatch<RequestItemsReduxActions>;\n}\n\ninterface IStateType {\n  error: Error | null;\n  properties: any[];\n  canDrop: boolean;\n  sending: boolean;\n  loadingSettings: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass RequestUpdaterView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  readonly inputFile: RefObject<HTMLInputElement>;\n\n  readonly state = {\n    error: null,\n    canDrop: false,\n    sending: false,\n    properties: [],\n    loadingSettings: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Actualización masiva';\n    this.inputFile = React.createRef();\n    this.clickUploadFile = this.clickUploadFile.bind(this);\n    this.handleDrop = this.handleDrop.bind(this);\n    this.dragOverHandler = this.dragOverHandler.bind(this);\n    this.dragEndHandler = this.dragEndHandler.bind(this);\n    this.dragLeaveHandler = this.dragLeaveHandler.bind(this);\n    this.handleChangeInputFile = this.handleChangeInputFile.bind(this);\n    this.downloadTemplate = this.downloadTemplate.bind(this);\n    this.processSettings = this.processSettings.bind(this);\n    this.sendCreate = this.sendCreate.bind(this);\n  }\n\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    window.scrollTo(0, 0);\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.requestItems.source) {\n      this.props.requestItems.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      loadingSettings, properties, sending\n    } = this.state;\n    return (\n      <AppContainer title=\"\" cMenu=\"3\" cSubMenu=\"3.2\" cAction=\"Actualización masiva\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Actualización masiva</h3>\n              <div className=\"pull-right box-tools\">\n                {\n                  !properties.length?\n                    <button\n                      className=\"btn btn-sm btn-primary\"\n                      onClick={this.downloadTemplate}\n                      style={{marginRight: '5px'}}>\n                      <i className=\"fa fa-fw fa-download\" /> Descargar Formato\n                    </button>\n                    :null\n                }\n              </div>\n            </div>\n            <div className=\"box-body margin\">\n              {\n                properties.length?\n                  <div className=\"row\">\n                    <div className=\"col col-md-12\">\n                      <table className=\"table table-striped\">\n                        <thead>\n                          <tr>\n                            <th>Propiedad</th>\n                            <th>Marca</th>\n                          </tr>\n                        </thead>\n                        <tbody>\n                          {\n                            properties.map((property: any) => {\n                              return (\n                                <tr key={property.key}>\n                                  <td>{property.key}</td>\n                                  <td>\n                                    {\n                                      property.brands.map((brand: string) => (\n                                        <React.Fragment key={brand}>- {brand}<br /></React.Fragment>)\n                                      )\n                                    }\n                                  </td>\n                                </tr>\n                              );\n                            })\n                          }\n                        </tbody>\n                      </table>\n                    </div>\n                    <div className=\"col col-md-6\">\n                      {/* <strong>Total de :</strong> {properties.reduce((total, x: any) => (total + x.cars.length), 0)} */}\n                    </div>\n                    <div className=\"col-md-6 text-right\">\n                      <button className=\"btn btn-sm btn-primary\" onClick={this.downloadTemplate}>\n                        <i className=\"fa fa-fw fa-download\" /> Descargar Formato\n                      </button>\n                      <button className=\"btn btn-sm btn-default\" onClick={this.clickUploadFile} style={{marginLeft: '5px'}}>\n                        <i className=\"fa fa-fw fa-cogs\" /> Cambiar configuración\n                      </button>\n                    </div>\n                  </div>\n                  :\n                  <div className=\"row\">\n                    <div className=\"col col-md-12\">\n                      <div className=\"form-group\">\n                        {/*<label>Días que serán importardos</label>*/}\n                        <div\n                          className=\"upload-file text-center pointer\"\n                          onClick={this.clickUploadFile}\n                          onDrop={this.handleDrop}\n                          onDragOver={this.dragOverHandler}\n                          onDragEnd={this.dragEndHandler}\n                          onDragLeave={this.dragLeaveHandler}\n                          style={{\n                            backgroundColor: '#EEEEEE',\n                            border: this.state.canDrop ? '1px solid #979797' : '1px dashed #979797',\n                            padding: '100px 20px',\n                            color: this.state.canDrop ? '#aebccb' : '#6e7a89',\n                            borderRadius: '5px',\n                            marginBottom: '10px'\n                          }}>\n                          <i className=\"fa fa-2x fa-cloud-upload\"/><br/>\n                          Prueba a soltanto el excel aquí, o haz click para seleccionar el excel a cargar.\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n              }\n              <input\n                type=\"file\"\n                onChange={this.handleChangeInputFile}\n                style={{display: 'None'}}\n                ref={this.inputFile} accept=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel\"\n              />\n            </div>\n            <div className=\"box-footer text-right\">\n              <button\n                className=\"btn btn-sm btn-default\"\n                onClick={() => this.props.history.push(parseReplicableURL('/requests/vehicles/'))}\n              >\n                Cancelar\n              </button>\n              {properties.length ? <button className=\"btn btn-sm btn-primary\" style={{marginLeft: '5px'}} onClick={this.sendCreate} disabled={sending}>\n                {\n                  sending ?\n                    <React.Fragment>\n                      <i className=\"fa fa-fw fa-spin fa-spinner\"/> Actualizando...\n                    </React.Fragment>\n                    : 'Actualizar'\n                }\n              </button> : null}\n            </div>\n            {\n              loadingSettings || sending &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView/>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private clickUploadFile(): void {\n    if (this.inputFile.current) {\n      this.inputFile.current.click();\n    }\n  }\n\n  private handleDrop(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      if (dt.items.length) {\n        const file: File | null = dt.items[0].getAsFile();\n        if (file) {\n          this.processSettings(file);\n        }\n      }\n    } else {\n      if (dt.files.length) {\n        const file = dt.files[0];\n        this.processSettings(file);\n      }\n    }\n  }\n\n  private handleChangeInputFile(e: React.ChangeEvent<HTMLInputElement>): void {\n    const {files} = e.target;\n    if (files && files.length) {\n      this.processSettings(files[0]);\n    }\n  }\n\n  private dragOverHandler(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    this.setState({\n      canDrop: true\n    });\n  }\n\n  private dragEndHandler(e: React.DragEvent<HTMLDivElement>): void {\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      // Use DataTransferItemList interface to remove the drag data\n      for (let i = 0; i < dt.items.length; i++) {\n        dt.items.remove(i);\n      }\n    } else {\n      // Use DataTransfer interface to remove the drag data\n      e.dataTransfer.clearData();\n    }\n  }\n\n  private dragLeaveHandler(): void {\n    this.setState({\n      canDrop: false\n    });\n  }\n\n  private downloadTemplate(): void {\n    /* make the worksheet */\n    const ws = XLSX.utils.json_to_sheet([{\n      propiedad: '',\n      marca: ''\n    }]);\n    /* add to workbook */\n    const wb = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(wb, ws, 'Propiedades');\n    /* generate an XLSX file */\n    XLSX.writeFile(wb, 'template_request_settings.xlsx');\n  }\n\n  private processSettings(file: File): void {\n    this.setState({\n      loadingSettings: true\n    });\n    if (['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'].includes(file.type)) {\n      const reader = new FileReader();\n      const rABS = !!reader.readAsBinaryString;\n      reader.onload = (e: any) => {\n        let data = e.target.result;\n        if (!rABS) {\n          data = new Uint8Array(data);\n        }\n        const workbook: XLSX.WorkBook = XLSX.read(data, {\n          type: rABS ? 'binary' : 'array',\n          cellDates: true\n        });\n        const excelData = workbook.Sheets.hasOwnProperty('Propiedades') ? XLSX.utils.sheet_to_json(workbook.Sheets.Propiedades) : [];\n        const brandByProperty: any = {};\n        if (excelData.length >= 1) {\n          excelData.forEach((item: any, index: number) => {\n            const key =  item.propiedad;\n            if (!brandByProperty.hasOwnProperty(key)) {\n              brandByProperty[key] = {\n                brands: []\n              };\n            }\n            brandByProperty[key].brands.push(item.marca);\n          });\n          this.setState({\n            loadingSettings: false,\n            properties: Object.keys(brandByProperty)\n              .map((key) => ({key, ...brandByProperty[key]}))\n              .sort((a, b) => {\n                if (a.key < b.key) return 1;\n                if (a.key > b.key) return -1;\n                return 0;\n              })\n              .reverse()\n          });\n        } else {\n          swal(\n            'Importador de configuración',\n            `\"${file.name}\" no cumple con los requisitos mínimos o no tiene autos.`,\n            'error'\n          );\n          this.setState({\n            loadingSettings: false\n          });\n        }\n      };\n      if (rABS) {\n        reader.readAsBinaryString(file);\n      } else {\n        reader.readAsArrayBuffer(file);\n      }\n      if (this.inputFile.current) {\n        this.inputFile.current.value = '';\n      }\n    }\n  }\n\n  private sendCreate(): void {\n    const { properties } = this.state;\n    const { history } = this.props;\n    this.setState({\n      sending: true\n    });\n    const api = new ApiService();\n    api.getSource();\n    api\n      .updateMassiveRequest({\n        properties\n      })\n      .then((response: any) => {\n        const { message } = response.data;\n        history.push(parseReplicableURL('/requests/vehicles/'));\n        setTimeout(() => {\n          swal('Actualización masiva', message, 'success');\n        }, 200);\n        this.setState({\n          sending: false\n        });\n      })\n      .catch((e) => {\n        swal('Actualización masiva', 'Se produjo un error al actualizar.', 'error');\n        this.setState({\n          sending: false\n        });\n      });\n  }\n\n}\n\nconst mapStateToProps = (state: { requestItems: IRequestItemsState }) => {\n  return {\n    requestItems: state.requestItems\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(RequestUpdaterView);\n","import * as React from 'react';\nimport { Dispatch, Fragment } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { debounce } from 'throttle-debounce';\nimport { IRequestItem } from '../../../../../../../src/request/interfaces/requestItem.interface';\nimport {\n  changeFilterRequestAction,\n  createRequestItemAction,\n  deleteRequestItemAction,\n  getRequestItemsThunkAction,\n  updateRequestItemAction\n} from '../../../actions/requestItems.actions';\nimport { IRequestItemsFilters, IRequestItemsState, RequestItemsReduxActions } from '../../../actions/requestItems.types';\nimport AppContainer from '../../../container/AppContainer';\nimport { IWindow } from '../../../interfaces/window';\nimport { hasPermission, parseReplicableURL } from '../../../utils/common';\nimport BootstrapSelect from '../../Utils/BootstrapSelect';\nimport DateRangePicker from '../../Utils/DateRangePicker';\nimport ImageLazyLoad from '../../Utils/ImageLazyLoad';\nimport Paginator from '../../Utils/Paginator';\nimport ShowIf from '../../Utils/ShowIf';\nimport TrackingBasePage from '../../Utils/TrackingBasePage';\nimport RequestVehicleItem from './RequestVehicleItem';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  requestItems: IRequestItemsState;\n  dispatch: Dispatch<RequestItemsReduxActions>;\n  updateRequestItemAction: (item: IRequestItem) => void;\n  getRequestItemsThunkAction: (page: number, orderBy: string, orderType: string, hideLoading?: boolean) => void;\n  deleteRequestItemAction: (item: IRequestItem) => void;\n  createRequestItemAction: (item: IRequestItem) => void;\n  changeFilterRequestAction: (key: keyof IRequestItemsFilters, value: any | any[]) => void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass RequestVehicleListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  private socket: Socket;\n\n  readonly state = {\n    error: null,\n    exporing: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Solicitudes';\n    this.changePage = this.changePage.bind(this);\n    this.changeOrder = this.changeOrder.bind(this);\n    this.changeFilterDebounced = debounce(200, this.changeFilterDebounced.bind(this));\n    this.changeFilter = this.changeFilter.bind(this);\n    this.exportExcel = this.exportExcel.bind(this);\n    this.create = this.create.bind(this);\n    this.update = this.update.bind(this);\n    this.import = this.import.bind(this);\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public componentWillMount(): void {\n    const { orderBy, orderType } = this.props.requestItems.options;\n    const { page } = this.props.requestItems.pagination;\n    window.scrollTo(0, 0);\n\n    this.props.getRequestItemsThunkAction(page, orderBy, orderType);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: window.user.token\n      }\n    });\n\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `request-list-${window.user.team._id}` });\n    });\n\n    this.socket.on('UPDATE_REQUEST_ITEM', (data: any): void => {\n      this.props.updateRequestItemAction(data.item);\n      const $item = $(`#request-item-${data.item._id}`);\n      if ($item) {\n        $item.addClass('bg-aqua-active');\n        setTimeout(() => {\n          $item.removeClass('bg-aqua-active');\n        }, 300);\n      }\n    });\n\n    this.socket.on('DELETE_REQUEST_ITEM', (data: any): void => {\n      const $item = $(`#request-item-${data.item._id}`);\n      if ($item) {\n        $item.addClass('bg-red-active');\n      }\n      setTimeout(() => {\n        this.props.deleteRequestItemAction(data.item);\n      }, 300);\n    });\n\n    // this.socket.on('DELETE_REQUEST', (data: any): void => {\n      // const $item = $(`#request-${data.idRequest}`);\n      // if ($item) {\n      //   $item.addClass('bg-red-active');\n      // }\n      // setTimeout(() => {\n      //   this.props.deleteRequestActionInList(data.idRequest);\n      // }, 300);\n    // });\n\n    this.socket.on('CREATE_REQUEST', (data: any): void => {\n      const { page } = this.props.requestItems.pagination;\n      const { orderBy, orderType } = this.props.requestItems.options;\n      if (page === 1) {\n        for (const item of data.request.items) {\n          if (window.user.venuesAccess.includes(item.destination._id)) {\n            this.props.createRequestItemAction(item);\n            const $item = $(`#request-item-${item._id}`);\n            if ($item) {\n              $item.addClass('bg-green-active');\n            }\n            setTimeout(() => {\n              $item.removeClass('bg-green-active');\n            }, 300);\n          }\n        }\n      } else {\n        this.props.getRequestItemsThunkAction(page, orderBy, orderType, true);\n      }\n    });\n\n    this.socket.on('CREATE_REQUEST_ITEM', (data: any): void => {\n      this.props.createRequestItemAction(data.item);\n      const $item = $(`#request-item-${data.item._id}`);\n      if ($item) {\n        $item.addClass('bg-green-active');\n      }\n      setTimeout(() => {\n        $item.removeClass('bg-green-active');\n      }, 300);\n    });\n  }\n\n  public componentDidUpdate(prevProps: IPropsType): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.requestItems.source) {\n      this.props.requestItems.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.emit('leave', { room: `request-list-${window.user.team._id}` });\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      pagination, loading, requestItems, requestItemStatus, venues, filters, properties, requestSettings, users\n    } = this.props.requestItems;\n    const { orderBy, orderType } = this.props.requestItems.options;\n    const { exporing } = this.state;\n    return (\n      <AppContainer title='' cMenu='3' cSubMenu='3.2'>\n        <section className='content'>\n          <div className='box'>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>Unidades <small>{pagination.count}</small></h3>\n              <div className='pull-right box-tools'>\n                <ShowIf condition={hasPermission(window.user, 'updateMassiveRequest')}>\n                  <button\n                    className='btn btn-sm btn-success'\n                    onClick={this.update}\n                  >\n                    <i className='fa fa-fw fa-plus' /> Actualizador\n                  </button>\n                </ShowIf>\n                <ShowIf condition={hasPermission(window.user, 'importRequest')}>\n                  <button\n                    style={{ marginLeft: '5px' }}\n                    className='btn btn-sm btn-success'\n                    onClick={this.import}\n                  >\n                    <i className='fa fa-fw fa-plus' /> Importar\n                  </button>\n                </ShowIf>\n                <ShowIf condition={hasPermission(window.user, 'createRequest')}>\n                  <button\n                    className='btn btn-sm btn-success'\n                    onClick={this.create}\n                    style={{ marginLeft: '5px' }}\n                  >\n                    <i className='fa fa-fw fa-plus' /> Crear solicitud\n                  </button>\n                </ShowIf>\n                <ShowIf condition={requestItems.length > 0}>\n                  <button\n                    className='btn btn-sm btn-primary hidden-xs'\n                    onClick={this.exportExcel}\n                    disabled={exporing}\n                    style={{ marginLeft: '5px' }}\n                  >\n                    {\n                      exporing ?\n                        <Fragment><i className='fa fa-spin fa-spinner' /> Exportando</Fragment> :\n                        <Fragment><i className='fa fa-fw fa-download' /> Exportar</Fragment>\n                    }\n                  </button>\n                </ShowIf>\n              </div>\n            </div>\n            <div className='box-body no-padding'>\n              <div style={{ padding: '10px 5px' }}>\n                <div className='row' style={{ margin: 0 }}>\n                  <div className='col-md-3' style={{padding: '0 5px'}}>\n                    <div className='form-group'>\n                      <label className='control-label'>\n                        Vehículo\n                      </label>\n                      <input\n                        type='text'\n                        className='form-control input-sm'\n                        placeholder='Busca por VIN, marca, modelo o material.'\n                        defaultValue={filters.text}\n                        onChange={(e) => {\n                          this.changeFilterDebounced('text', e.target.value);\n                        }}\n                      />\n                    </div>\n                  </div>\n                  <ShowIf condition={requestSettings.entry}>\n                    <div className='col-md-3' style={{padding: '0 5px'}}>\n                      <div className='form-group'>\n                        <label className='control-label'>\n                          Partida\n                        </label>\n                        <input\n                          type='text'\n                          className='form-control input-sm'\n                          placeholder='Nº de partida: S14795'\n                          defaultValue={filters.entry}\n                          onChange={(e) => {\n                            this.changeFilterDebounced('entry', e.target.value);\n                          }}\n                        />\n                      </div>\n                    </div>\n                  </ShowIf>\n                  <ShowIf condition={requestSettings.ticket}>\n                    <div className='col-md-3' style={{padding: '0 5px'}}>\n                      <div className='form-group'>\n                        <label className='control-label'>\n                          Nº Ticket Anticipo\n                        </label>\n                        <input\n                          type='text'\n                          className='form-control input-sm'\n                          placeholder='Nº de ticket: 14795'\n                          defaultValue={filters.ticket}\n                          onChange={(e) => {\n                            this.changeFilterDebounced('ticket', e.target.value);\n                          }}\n                        />\n                      </div>\n                    </div>\n                  </ShowIf>\n                  <div className='col-md-3' style={{padding: '0 5px'}}>\n                    <div className='form-group'>\n                      <label className='control-label'>\n                        Nº Solicitudes\n                      </label>\n                      <input\n                        type='text'\n                        className='form-control input-sm'\n                        placeholder='Nº de solicitudes ejemplo: 2, 8, 10'\n                        defaultValue={filters.request}\n                        onChange={(e) => {\n                          this.changeFilterDebounced('request', e.target.value);\n                        }}\n                      />\n                    </div>\n                  </div>\n                  <div className='col-md-3' style={{padding: '0 5px'}}>\n                    <div className='form-group'>\n                      <label className='control-label'>\n                        Vendedor\n                      </label>\n                      <BootstrapSelect\n                        noneSelectedText='Todas'\n                        search={true}\n                        displayItems={2}\n                        selectedText='sucursales seleccionadas.'\n                        selected={filters.users}\n                        sm={true}\n                        allOption={true}\n                        selectAll={\n                          (all: boolean) => {\n                            if (all) {\n                              this.changeFilter('users', users.map((user) => user._id));\n                            } else {\n                              this.changeFilter('users', []);\n                            }\n                          }\n                        }\n                        options={users.map((user) => ({\n                          value: user._id,\n                          text: `${user.firstName} ${user.lastName}`\n                        }))}\n                        onClick={(selected: any) => {\n                          if (filters.users.includes(selected)) {\n                            this.changeFilter('users', [...filters.users.filter((venue) => venue !== selected)]);\n                          } else {\n                            this.changeFilter('users', [...filters.users, selected]);\n                          }\n                        }}\n                      />\n                    </div>\n                  </div>\n                  {/*<ShowIf condition={requestSettings.sellerText}>*/}\n                  {/*<div className='col-md-3' style={{padding: '0 5px'}}>*/}\n                  {/*  <div className='form-group'>*/}\n                  {/*    <label className='control-label'>*/}\n                  {/*      Vendedor*/}\n                  {/*    </label>*/}\n                  {/*    <input*/}\n                  {/*      type='text'*/}\n                  {/*      className='form-control input-sm'*/}\n                  {/*      placeholder='Jhon Doe'*/}\n                  {/*      defaultValue={filters.sellerText}*/}\n                  {/*      onChange={(e) => {*/}\n                  {/*        this.changeFilterDebounced('sellerText', e.target.value);*/}\n                  {/*      }}*/}\n                  {/*    />*/}\n                  {/*  </div>*/}\n                  {/*</div>*/}\n                  {/*</ShowIf>*/}\n                  <div className='col-md-3' style={{padding: '0 5px'}}>\n                    <div className='form-group'>\n                      <label htmlFor='venues' className='control-label'>Propiedad</label>\n                      <BootstrapSelect\n                        noneSelectedText='Todas'\n                        search={true}\n                        displayItems={2}\n                        selectedText='propiedades seleccionadas.'\n                        selected={filters.properties}\n                        sm={true}\n                        allOption={true}\n                        selectAll={\n                          (all: boolean) => {\n                            if (all) {\n                              this.changeFilter('properties', properties.map((property) => property._id));\n                            } else {\n                              this.changeFilter('properties', []);\n                            }\n                          }\n                        }\n                        options={properties.map((property) => ({\n                          value: property._id,\n                          text: property.name\n                        }))}\n                        onClick={(selected: any) => {\n                          if (filters.properties.includes(selected)) {\n                            this.changeFilter('properties', [...filters.properties.filter((property) => property !== selected)]);\n                          } else {\n                            this.changeFilter('properties', [...filters.properties, selected]);\n                          }\n                        }}\n                      />\n                    </div>\n                  </div>\n                  <div className='col-md-3' style={{padding: '0 5px'}}>\n                    <div className='form-group'>\n                      <label htmlFor='venues' className='control-label'>Sucursales</label>\n                      <BootstrapSelect\n                        noneSelectedText='Todas'\n                        search={true}\n                        displayItems={2}\n                        selectedText='sucursales seleccionadas.'\n                        selected={filters.venues}\n                        sm={true}\n                        allOption={true}\n                        selectAll={\n                          (all: boolean) => {\n                            if (all) {\n                              this.changeFilter('venues', venues.map((venue) => venue._id));\n                            } else {\n                              this.changeFilter('venues', []);\n                            }\n                          }\n                        }\n                        options={venues.map((venue) => ({\n                          value: venue._id,\n                          text: venue.name\n                        }))}\n                        onClick={(selected: any) => {\n                          if (filters.venues.includes(selected)) {\n                            this.changeFilter('venues', [...filters.venues.filter((venue) => venue !== selected)]);\n                          } else {\n                            this.changeFilter('venues', [...filters.venues, selected]);\n                          }\n                        }}\n                      />\n                    </div>\n                  </div>\n                  <div className='col-md-3' style={{padding: '0 5px'}}>\n                    <div className='form-group'>\n                      <label htmlFor='venues' className='control-label'>Estados</label>\n                      <BootstrapSelect\n                        noneSelectedText='Todos'\n                        displayItems={2}\n                        selectedText='estados seleccionados.'\n                        selected={filters.status}\n                        sm={true}\n                        allOption={true}\n                        selectAll={\n                          (all: boolean) => {\n                            if (all) {\n                              this.changeFilter('status', requestItemStatus.map((status) => status._id));\n                            } else {\n                              this.changeFilter('status', []);\n                            }\n                          }\n                        }\n                        options={requestItemStatus.map((status) => ({\n                          value: status._id,\n                          text: status.name\n                        }))}\n                        onClick={(selected: any) => {\n                          if (filters.status.includes(selected)) {\n                            this.changeFilter('status', [...filters.status.filter((status) => status !== selected)]);\n                          } else {\n                            this.changeFilter('status', [...filters.status, selected]);\n                          }\n                        }}\n                      />\n                    </div>\n                  </div>\n                  {\n                    /* <div className=\"col-md-3\">\n                    <div className=\"form-group\">\n                      <label htmlFor=\"venues\" className=\"control-label\">Marcas</label>\n                      <BootstrapSelect\n                        noneSelectedText=\"Todas\"\n                        search={true}\n                        displayItems={2}\n                        selectedText=\"marcas seleccionadas.\"\n                        selected={[]}\n                        allOption={true}\n                        selectAll={[]}\n                        options={[]}\n                        onClick={() => { }}\n                      />\n                    </div>\n                  </div> */\n                  }\n                  <div className='col-md-3'>\n                    <div className='row'>\n                      <div className='col-md-6' style={{padding: '0 5px'}}>\n                        <div className='form-group'>\n                          <label htmlFor='venues' className='control-label'>Desde</label>\n                          <DateRangePicker\n                            value={filters.from}\n                            className={'input-sm'}\n                            onChange={(e) => {\n                              this.changeFilter('from', e);\n                            }}\n                          />\n                        </div>\n                      </div>\n                      <div className='col-md-6' style={{padding: '0 5px'}}>\n                        <div className='form-group'>\n                          <label htmlFor='venues' className='control-label'>Hasta</label>\n                          <DateRangePicker\n                            value={filters.to}\n                            className={'input-sm'}\n                            onChange={(e) => {\n                              this.changeFilter('to', e);\n                            }}\n                          />\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n                </div>\n              </div>\n              <ShowIf condition={requestItems.length > 0}>\n                <div className='table-responsive'>\n                  <table className='table table-xs table-hover' style={{ minWidth: '1000px' }}>\n                    <thead>\n                    <tr className='bg-primary' style={{ height: '45px' }}>\n                      <ShowIf condition={requestSettings.priority}>\n                        <th className='middle' style={{ width: '28px' }} />\n                      </ShowIf>\n                      <th\n                        className='middle-center pointer'\n                        style={{ minWidth: '60px' }}\n                        onClick={() => this.changeOrder('meta.request.number')}\n                      >\n                        Solic.\n                        <span style={{ float: 'right' }}><i\n                          className={`fa fa-fw ${orderBy === 'meta.request.number' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} /></span>\n                      </th>\n                       <th\n                        className='middle pointer'\n                        style={{ minWidth: '40px' }}\n                        // onClick={() => this.changeOrder('request.number')}\n                      >\n                        OT\n                        {/*<span style={{ float: 'right' }}><i className={`fa fa-fw ${orderBy === 'request.number' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} /></span>*/}\n                      </th>\n                      <th\n                        className='middle pointer'\n                        style={{ width: '80px' }}\n                        onClick={() => this.changeOrder('meta.origin.name')}\n                      >\n                        Creada\n                        <span style={{ float: 'right' }}><i\n                          className={`fa fa-fw ${orderBy === 'meta.origin.name' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} /></span>\n                      </th>\n                      <th\n                        className='middle pointer'\n                        style={{ width: '80px' }}\n                        onClick={() => this.changeOrder('meta.destination.name')}\n                      >\n                        Destino\n                        <span style={{ float: 'right' }}><i\n                          className={`fa fa-fw ${orderBy === 'meta.destination.name' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} /></span>\n                      </th>\n                      {/*<th*/}\n                      {/*  className='middle pointer'*/}\n                      {/*  // style={{ width: '100px' }}*/}\n                      {/*  onClick={() => this.changeOrder('car.property')}*/}\n                      {/*>*/}\n                      {/*  Prop.*/}\n                      {/*  <span style={{ float: 'right' }}><i*/}\n                      {/*    className={`fa fa-fw ${orderBy === 'car.property' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} /></span>*/}\n                      {/*</th>*/}\n                      <th\n                        className='middle pointer'\n                        style={{ minWidth: '100px' }}\n                        onClick={() => this.changeOrder('meta.car.brand')}\n                      >\n                        Marca\n                        <span style={{ float: 'right' }}><i\n                          className={`fa fa-fw ${orderBy === 'meta.car.brand' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} /></span>\n                      </th>\n                      <th className='middle' style={{ minWidth: '200px', width: '200px' }}>VIN</th>\n                      <ShowIf condition={requestSettings.entry}>\n                        <th className='middle' style={{ width: '80px' }}>Partida</th>\n                      </ShowIf>\n                      <ShowIf condition={requestSettings.denomination}>\n                        <th\n                          className='middle pointer'\n                          style={{ minWidth: '120px' }}\n                          onClick={() => this.changeOrder('meta.car.denomination')}\n                        >\n                          Modelo\n                          <span style={{ float: 'right' }}><i\n                            className={`fa fa-fw ${orderBy === 'meta.car.denomination' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} /></span>\n                        </th>\n                      </ShowIf>\n                      <ShowIf condition={requestSettings.material}>\n                        <th\n                          className='middle pointer'\n                          style={{ width: '80px' }}\n                          onClick={() => this.changeOrder('meta.car.material')}\n                        >\n                          Material\n                          <span style={{ float: 'right' }}><i\n                            className={`fa fa-fw ${orderBy === 'meta.car.material' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} /></span>\n                        </th>\n                      </ShowIf>\n                      <ShowIf condition={requestSettings.color}>\n                        <th className='middle' style={{ minWidth: '80px' }}>Color</th>\n                      </ShowIf>\n                      <th\n                        className='middle pointer'\n                        style={{ minWidth: '120px', maxWidth: '160px' }}\n                        onClick={() => this.changeOrder('meta.status.weigth')}\n                      >\n                        Estado\n                        <span style={{ float: 'right' }}><i\n                          className={`fa fa-fw ${orderBy === 'meta.status.weigth' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} /></span>\n                      </th>\n                      <ShowIf condition={requestSettings.internalNumber}>\n                        <th className='middle' style={{ width: '60px' }}>CDO</th>\n                      </ShowIf>\n                      <ShowIf condition={requestSettings.reason}>\n                        <th\n                          className='middle pointer'\n                          style={{ minWidth: '100px' }}\n                          onClick={() => this.changeOrder('reason.name')}\n                        >\n                          Motivo\n                          <span\n                            style={{ float: 'right' }}\n                          >\n                            <i\n                              className={`fa fa-fw ${orderBy === 'reason.name' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} />\n                          </span>\n                        </th>\n                      </ShowIf>\n                      <ShowIf condition={requestSettings.ticket}>\n                        <th className='middle pointer'>\n                          Ticket\n                        </th>\n                        <th className='middle pointer'>\n                          Nº Ticket\n                        </th>\n                      </ShowIf>\n                      {/* <th className=\"middle\">Carrocería</th>\n                        <th className=\"middle\">Pre-Entrega</th> */}\n                      <th className='middle-center' style={{ width: '40px' }}>Adj</th>\n                      <th className='middle-center' style={{ width: '20px' }}>Obs</th>\n                      {/* <th\n                          className=\"middle pointer\"\n                          style={{ width: '100px' }}\n                          onClick={() => this.changeOrder('carrier.name')}\n                        >\n                          Transporte\n                      <span style={{ float: 'right' }}><i className={`fa fa-fw ${orderBy === 'carrier.name' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} /></span>\n                        </th>\n                        <th\n                          className=\"middle pointer\"\n                          style={{ width: '80px' }}\n                          onClick={() => this.changeOrder('uploadDate')}\n                        >\n                          F. carga\n                      <span style={{ float: 'right' }}><i className={`fa fa-fw ${orderBy === 'uploadDate' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} /></span>\n                        </th>\n                        <th\n                          className=\"middle pointer\"\n                          style={{ width: '80px' }}\n                          onClick={() => this.changeOrder('estimatedArrival')}\n                        >\n                          F. llegada\n                      <span style={{ float: 'right' }}><i className={`fa fa-fw ${orderBy === 'estimatedArrival' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} /></span>\n                        </th> */}\n                      <ShowIf condition={hasPermission(window.user, 'deleteRequest')}>\n                        <th className='middle' style={{ width: '30px' }} />\n                      </ShowIf>\n                    </tr>\n                    </thead>\n                    <tbody>\n                    {\n                      requestItems.map((item) => (\n                        <RequestVehicleItem\n                          key={item._id}\n                          item={item}\n                          {...this.props}\n                        />\n                      ))\n                    }\n                    </tbody>\n                  </table>\n                </div>\n              </ShowIf>\n              <ShowIf condition={!loading && requestItems.length === 0}>\n                <div className='row'>\n                  <div className='col-md-12 text-center' style={{ paddingTop: '10px', paddingBottom: '10px' }}>\n                    <ImageLazyLoad\n                      url='/images/not_found.png'\n                      height={'200px'}\n                      style={{\n                        opacity: 0.5,\n                        maxHeight: '200px',\n                        marginBottom: '10px'\n                      }}\n                      replaceLoading={<i\n                        className={'fa fa-2x fa-circle-o-notch text-primary fa-spin'}\n                        style={{ padding: '30px' }}\n                      />}\n                    /><br />\n                    <strong>No hay información para mostrar</strong>\n                  </div>\n                </div>\n              </ShowIf>\n            </div>\n            <div className='box-footer'>\n              <div className='row'>\n                <div className='col-md-12'>\n                  <ShowIf condition={pagination.pages > 1}>\n                    <div className='row'>\n                      <div className='col-md-6' style={{ padding: '20px 15px' }}>\n                          <span className='react-bootstrap-table-pagination-total text-ellipsis'>\n                            &nbsp;&nbsp;Mostrando registros del {(pagination.page - 1) * 20 + 1} al {(pagination.page) * 20} de {pagination.count} registros.\n                          </span>\n                      </div>\n                      <div className='col-md-6'>\n                        <div className='text-right' style={{ marginRight: '15px' }}>\n                          <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                        </div>\n                      </div>\n                    </div>\n                  </ShowIf>\n                </div>\n              </div>\n            </div>\n            <ShowIf condition={loading}>\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            </ShowIf>\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private create(): void {\n    this.props.history.push(parseReplicableURL('/requests/vehicles/create/'));\n  }\n\n  private update() {\n    this.props.history.push(parseReplicableURL('/requests/update/'));\n  }\n\n  private import() {\n    this.props.history.push(parseReplicableURL('/requests/import/'));\n  }\n\n  private changeFilterDebounced(key: keyof IRequestItemsFilters, value: any | any[]): void {\n    this.changeFilter(key, value);\n  }\n\n  private changeFilter(key: keyof IRequestItemsFilters, value: any | any[]): void {\n    const { orderBy, orderType } = this.props.requestItems.options;\n    this.props.changeFilterRequestAction(key, value);\n    this.props.getRequestItemsThunkAction(1, orderBy, orderType, true);\n  }\n\n  private changeOrder(key: string) {\n    const { page } = this.props.requestItems.pagination;\n    const { orderBy, orderType } = this.props.requestItems.options;\n    let newOrderType = orderType;\n    let newOrderBy = orderBy;\n    if (key === orderBy) {\n      newOrderType = orderType === 'descending' ? 'ascending' : 'descending';\n    } else {\n      newOrderBy = key;\n    }\n    this.props.getRequestItemsThunkAction(page, newOrderBy, newOrderType, true);\n  }\n\n  private changePage(page: number): void {\n    window.scrollTo(0, 0);\n    const { orderBy, orderType } = this.props.requestItems.options;\n    this.props.getRequestItemsThunkAction(page, orderBy, orderType);\n  }\n\n  public exportExcel(): void {\n    this.trackClick('Exportar');\n    window.open(`/requests/export/`, '_blank');\n    // this.setState({\n    //   exporing: true\n    // });\n    // const api: ApiService = new ApiService();\n    // const instance = api.getInstance();\n    // instance.defaults.responseType = 'blob';\n    // instance\n    //   .get(`/requests/export/`)\n    //   .then((response) => {\n    //     const blob = new Blob([response.data], {\n    //       type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'\n    //     });\n    //     const fileName = `${moment().format('YYYYMMDD')}-solicitudes.xlsx`;\n    //     if (typeof window.navigator.msSaveBlob !== 'undefined') {\n    //       // IE workaround for \"HTML7007: One or more blob URLs were\n    //       // revoked by closing the blob for which they were created.\n    //       // These URLs will no longer resolve as the data backing\n    //       // the URL has been freed.\"\n    //       window.navigator.msSaveBlob(blob, fileName);\n    //     } else {\n    //       const blobURL = URL.createObjectURL(blob);\n    //       const tempLink = document.createElement('a');\n    //       tempLink.style.display = 'none';\n    //       tempLink.href = blobURL;\n    //       tempLink.setAttribute('download', fileName);\n    //       // Safari thinks _blank anchor are pop ups. We only want to set _blank\n    //       // target if the browser does not support the HTML5 download attribute.\n    //       // This allows you to download files in desktop safari if pop up blocking\n    //       // is enabled.\n    //       if (typeof tempLink.download === 'undefined') {\n    //         tempLink.setAttribute('target', '_blank');\n    //       }\n    //       this.setState({\n    //         exporing: false\n    //       });\n    //       document.body.appendChild(tempLink);\n    //       tempLink.click();\n    //       document.body.removeChild(tempLink);\n    //       URL.revokeObjectURL(blobURL);\n    //     }\n    //   })\n    //   .catch((err) => {\n    //     this.setState({\n    //       exporing: false\n    //     });\n    //     if (!Axios.isCancel(err)) {\n    //       swal('Exportar usuarios', 'Ha ocurrido un error al general el excel.', 'error');\n    //     }\n    //   });\n  }\n}\n\nconst mapStateToProps = (state: { requestItems: IRequestItemsState }) => {\n  return {\n    requestItems: state.requestItems\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getRequestItemsThunkAction: (page: number, orderBy: string, orderType: string, hideLoading?: boolean) => dispatch(getRequestItemsThunkAction(page, orderBy, orderType, hideLoading)),\n    createRequestItemAction: (item: IRequestItem) => dispatch(createRequestItemAction(item)),\n    updateRequestItemAction: (item: IRequestItem) => dispatch(updateRequestItemAction(item)),\n    deleteRequestItemAction: (item: IRequestItem) => dispatch(deleteRequestItemAction(item)),\n    changeFilterRequestAction: (key: keyof IRequestItemsFilters, value: any | any[]) => dispatch(changeFilterRequestAction(key, value))\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(RequestVehicleListView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router-dom';\nimport { ICar } from '../../../../../../../src/app/interfaces/car.interface';\nimport { IRequestItem } from '../../../../../../../src/request/interfaces';\nimport { deleteRequestItemsThunkAction, updateRequestItemsThunkAction } from '../../../actions/requestItems.actions';\nimport { IRequestItemsState } from '../../../actions/requestItems.types';\nimport { IWindow } from '../../../interfaces/window';\nimport ApiService from '../../../utils/axios';\nimport { hasPermission, parseReplicableURL } from '../../../utils/common';\nimport AutoCompleteInput from '../../Utils/AutoCompleteInput';\nimport * as swal from 'sweetalert';\nimport ShowIf from '../../Utils/ShowIf';\nimport * as Rx from 'rxjs';\nimport { debounceTime, switchMap } from 'rxjs/operators';\nimport { ajax } from 'rxjs/ajax';\nimport AutoCompleteVinInput from '../../Utils/AutoCompleteVinInput';\n\ninterface IPropsType extends RouteComponentProps<{ id: string }> {\n  requestItems: IRequestItemsState;\n  item: IRequestItem;\n  updateRequestItemsThunkAction: ({ item, debounce }: { item: IRequestItem, debounce?: boolean }) => void;\n  deleteRequestItemsThunkAction: (id: string) => void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  recommends: ICar[];\n}\n\ndeclare let window: IWindow;\n\nclass RequestVehicleItem extends React.Component<IPropsType, IStateType> {\n  readonly api: ApiService;\n  readonly $subjectRecommends = new Rx.Subject<any>();\n\n  readonly state = {\n    error: null,\n    recommends: []\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.goToDetail = this.goToDetail.bind(this);\n    this.downloadFiles = this.downloadFiles.bind(this);\n    this.api = new ApiService();\n    this.$subjectRecommends.pipe(\n      debounceTime(300),\n      switchMap((text: string) => {\n        return ajax({\n          url: `/api/v1/requests/search-car/?search=${text}`,\n          headers: {\n            'Content-Type': 'application/json;charset=UTF-8'\n          },\n          method: 'GET'\n        });\n      })\n    ).subscribe((response) => {\n      this.setState({\n        recommends: response.response.cars\n      });\n    });\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  componentWillUnmount() {\n    this.$subjectRecommends.unsubscribe();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { item } = this.props;\n    const { requestItemStatus, reasons, requestSettings } = this.props.requestItems;\n    const { recommends } = this.state;\n    const canChangeRequest = hasPermission(window.user, 'changeRequest');\n    return (\n      <tr id={`request-item-${item._id}`} className={'background-transition'}>\n        <ShowIf condition={requestSettings.priority}>\n          <td\n            className={`middle-center ${canChangeRequest ? 'pointer' : ''}`}\n            onClick={canChangeRequest ? () => {\n              this.props.updateRequestItemsThunkAction({\n                item: {\n                  ...item,\n                  priority: !item.priority\n                },\n                debounce: false\n              });\n            } : undefined}\n          >\n            {item.priority ? <i className='fa fa-star text-yellow' /> : <i className='fa fa-star text-gray' />}\n          </td>\n        </ShowIf>\n        <td\n          className=\"middle-center pointer\"\n          onClick={() => this.goToDetail(item.request._id)}\n        >\n            <strong className=\"text-underline\">#{item.request?.number}</strong>\n        </td>\n        <td\n          className={`middle ${item.transmittal?.number ? 'pointer' : ''}`}\n          onClick={item.transmittal?.number?() => this.openOT(item.transmittal.number.toString()):undefined}\n        >\n          <ShowIf condition={!!item.transmittal?.number} alternative={'-'}>\n            <strong className='text-underline'>#{item.transmittal?.number}</strong>\n          </ShowIf>\n        </td>\n        <td className=\"middle\" style={{fontSize: '80%'}}>{item.origin?.name ?? '-'}</td>\n        <td className=\"middle\" style={{fontSize: '80%'}}>{item.destination?.name ?? '-'}</td>\n        {/*<td className=\"middle\">{item.car.property ? item.car.property : '-'}</td>*/}\n        {\n          canChangeRequest && !requestSettings.brandReadOnly ?\n            <td className=\"middle\">\n              <AutoCompleteInput\n                value={item.car.brand}\n                inputClass={'input-sm'}\n                items={recommends}\n                renderItem={(car, index) => {\n                  return (\n                    <div key={index} className='item'>\n                      {car.material ? `${car.material} - ` : ''} {car.denomination} <br />\n                      <strong>{car.brand}</strong>\n                    </div>\n                  );\n                }}\n                onChange={(e) => {\n                  const { value } = e.target;\n                  this.props.updateRequestItemsThunkAction({\n                    item: {\n                      ...item,\n                      car: {\n                        ...item.car,\n                        brand: value\n                      }\n                    },\n                    debounce: true\n                  });\n                  this.search(value);\n                }}\n                onSelect={(car: any) => {\n                  this.props.updateRequestItemsThunkAction({\n                    item: {\n                      ...item,\n                      car: {\n                        ...item.car,\n                        brand: car.brand,\n                        denomination: car.denomination,\n                        material: car.material ?? ''\n                      }\n                    },\n                    debounce: false\n                  });\n                }}\n              />\n            </td>\n            : <td className=\"middle\">{item.car.brand}</td>\n        }\n        {\n          canChangeRequest ?\n            <td\n              className='middle'\n            >\n              <div className='flex'>\n                <AutoCompleteVinInput\n                  defaultValue={item.car.vin}\n                  item={item}\n                  inputClass={'input-sm'}\n                  renderItem={(car, index) => (\n                    <div key={index} className='item'>\n                      {car.vin ? `${car.vin} - ` : ''} {car.denomination} <br />\n                      <strong>{car.brand}</strong>\n                    </div>\n                  )}\n                />\n              </div>\n            </td>\n            : <td className=\"middle\">{item.car.vin}</td>\n        }\n        <ShowIf condition={requestSettings.entry}>\n          {\n            canChangeRequest ?\n              <td className=\"middle\">\n                <input\n                  type=\"text\"\n                  className=\"form-control input-sm\"\n                  defaultValue={item.car.entry}\n                  onChange={(e: React.ChangeEvent<HTMLInputElement>) => {\n                    this.props.updateRequestItemsThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          entry: e.target.value\n                        }\n                      },\n                      debounce: true\n                    });\n                  }}\n                />\n              </td>\n              : <td className=\"middle\">{item.car.entry}</td>\n          }\n        </ShowIf>\n        <ShowIf condition={requestSettings.denomination}>\n          {\n            canChangeRequest && !requestSettings.denominationReadOnly ?\n              <td className=\"middle\">\n                <AutoCompleteInput\n                  value={item.car.denomination}\n                  inputClass={'input-sm'}\n                  items={recommends}\n                  renderItem={(car, index) => (\n                    <div key={index} className=\"item\">\n                      {car.material ? `${car.material} - ` : ''} {car.denomination} <br />\n                      <strong>{car.brand}</strong>\n                    </div>\n                  )}\n                  onChange={(e) => {\n                    const { value } = e.target;\n                    this.props.updateRequestItemsThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          denomination: value\n                        }\n                      },\n                      debounce: true\n                    });\n                    this.search(value);\n                  }}\n                  onSelect={(car: any) => {\n                    this.props.updateRequestItemsThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          brand: car.brand,\n                          denomination: car.denomination,\n                          material: car.material ?? ''\n                        }\n                      },\n                      debounce: false\n                    });\n                  }}\n                />\n              </td>\n              : <td className=\"middle\">{item.car.denomination}</td>\n          }\n        </ShowIf>\n        <ShowIf condition={requestSettings.material}>\n          {\n            canChangeRequest && !requestSettings.materialReadOnly ?\n              <td className=\"middle\">\n                <AutoCompleteInput\n                  value={item.car.material}\n                  inputClass={'input-sm'}\n                  items={recommends}\n                  renderItem={(car, index) => (\n                    <div key={index} className=\"item\">\n                      {car.material ? `${car.material} - ` : ''} {car.denomination} <br />\n                      <strong>{car.brand}</strong>\n                    </div>\n                  )}\n                  onChange={(e) => {\n                    const { value } = e.target;\n                    this.props.updateRequestItemsThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          material: value\n                        }\n                      },\n                      debounce: true\n                    });\n                    this.search(value);\n                  }}\n                  onSelect={(car: any) => {\n                    this.props.updateRequestItemsThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          brand: car.brand,\n                          denomination: car.denomination,\n                          material: car.material ?? ''\n                        }\n                      },\n                      debounce: false\n                    });\n                  }}\n                />\n              </td>\n              : <td className=\"middle\">{item.car.material}</td>\n          }\n        </ShowIf>\n        <ShowIf condition={requestSettings.color}>\n          {\n            canChangeRequest && !requestSettings.colorReadOnly  ?\n              <td className=\"middle\">\n                <input type=\"text\"\n                  className=\"form-control input-sm\"\n                  defaultValue={item.car.color}\n                  onChange={(e: React.ChangeEvent<HTMLInputElement>) => {\n                    this.props.updateRequestItemsThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          color: e.target.value\n                        }\n                      },\n                      debounce: false\n                    });\n                  }}\n                />\n              </td>\n              : <td className=\"middle\">{item.car.color}</td>\n          }\n        </ShowIf>\n        {\n          canChangeRequest ?\n            <td className=\"middle\">\n              <select className=\"form-control select-sm font-12\" value={item.status?._id ?? ''}\n                onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                  this.props.updateRequestItemsThunkAction({\n                    item: {\n                      ...item,\n                      status: {\n                        ...item.status,\n                        _id: e.target.value\n                      }\n                    },\n                    debounce: false\n                  });\n                }}\n              >\n                <option value=\"\" disabled={true}>-</option>\n                {\n                  requestItemStatus.map((req) => (\n                    <option key={req._id} value={req._id}>{req.name}</option>\n                  ))\n                }\n              </select>\n            </td>\n            : <td className=\"middle\">{item.status?.name}</td>\n        }\n        <ShowIf condition={requestSettings.internalNumber}>\n          {\n            canChangeRequest ?\n              <td className=\"middle\">\n                <input type=\"text\"\n                  className=\"form-control input-sm\"\n                  defaultValue={item.car.internalNumber}\n                  onChange={(e: React.ChangeEvent<HTMLInputElement>) => {\n                    this.props.updateRequestItemsThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          internalNumber: e.target.value\n                        }\n                      },\n                      debounce: false\n                    });\n                  }}\n                />\n              </td>\n              : <td className=\"middle\">{item.car.internalNumber}</td>\n          }\n        </ShowIf>\n        <ShowIf condition={requestSettings.reason}>\n          {\n            canChangeRequest ?\n              <td className=\"middle\">\n                <select\n                  className=\"form-control select-sm font-12\"\n                  value={item.reason?._id ?? ''}\n                  onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                    this.props.updateRequestItemsThunkAction({\n                      item: {\n                        ...item,\n                        reason: {\n                          ...item.reason,\n                          _id: e.target.value\n                        }\n                      },\n                      debounce: false\n                    });\n                  }}\n                >\n                  <option value=\"\" disabled={true}>-</option>\n                  {\n                    reasons.map((reason) => (\n                      <option key={reason._id} value={reason._id}>{reason.name}</option>\n                    ))\n                  }\n                </select>\n              </td>\n              : <td className=\"middle\">{item.reason?.name}</td>\n          }\n        </ShowIf>\n        <ShowIf condition={requestSettings.ticket}>\n          <td className='middle-center'>\n            {\n              //request.advancePaymentInformation.files[0].file.url\n              item.request?.advancePaymentInformation?.files?.length ?\n                <i\n                  className='fa fa-check-circle text-green pointer'\n                  onClick={() => this.openBlank(item.request.advancePaymentInformation.files[0].file.url)}\n                /> : ''\n            }\n          </td>\n          <td className='middle'>{item.request?.advancePaymentInformation?.number}</td>\n        </ShowIf>\n        <td\n          className={`middle-center ${item.files && item.files.length ? 'pointer' : ''}`}\n          style={{ fontSize: '80%' }}\n          onClick={item.files?.length ? () => this.downloadFiles(item) : undefined}\n        >\n          {\n            item.files?.length ?\n              <span\n                data-toggle={'tooltip'}\n                data-placement={'top'}\n                title={`${item.files.length} archivos adjuntos.`}\n              >\n                <i className=\"fa fa-paperclip\" /> ({item.files.length})\n              </span> : null\n          }\n        </td>\n        <td className=\"middle-center text-gray\">\n          {\n            item.observation && item.observation.length ?\n              <i\n                className=\"fa fa-comment\"\n                data-toggle=\"tooltip\"\n                data-placement=\"top\"\n                title={item.observation}\n              /> : null\n          }\n        </td>\n        <ShowIf condition={hasPermission(window.user, 'deleteRequest')}>\n          <td className=\"middle-center text-red pointer\" onClick={() => this.deleteRequestItem(item)}>\n            <i className=\"fa fa-minus-circle\" />\n          </td>\n        </ShowIf>\n      </tr>\n    );\n  }\n\n  private openOT(number: string) {\n    window.open(parseReplicableURL(`/transmittals/?number=${number}`), '_blank');\n  }\n\n  private goToDetail(id: string): void {\n    this.props.history.push(parseReplicableURL(`/requests/vehicles/${id}/`));\n  }\n\n  private downloadFiles(item: IRequestItem) {\n    window.open(`/requests-item/${item._id}/download-files/`, '_blank');\n  }\n\n  private search(text: string): void {\n    this.$subjectRecommends.next(text)\n  }\n\n\n  private deleteRequestItem(item: IRequestItem) {\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar este vehículo ${item.car.brand} ${item.car.denomination} ${item.car.material}.`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteRequestItemsThunkAction(item._id);\n      }\n    });\n  }\n\n  private openBlank(url: string) {\n    window.open(decodeURI(url), '_blank');\n  }\n}\n\n\nconst mapStateToProps = (state: { requestItems: IRequestItemsState }) => {\n  return {\n    requestItems: state.requestItems\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    updateRequestItemsThunkAction: ({ item, debounce }: { item: IRequestItem, debounce?: boolean }) => dispatch(updateRequestItemsThunkAction({ item, debounce })),\n    deleteRequestItemsThunkAction: (id: string) => dispatch(deleteRequestItemsThunkAction(id))\n    // deleteRequestThunkAction: (idRequest: string) => dispatch(deleteRequestThunkAction(idRequest))\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType | any>(mapStateToProps, mapDispatchToProps)(RequestVehicleItem);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo, RefObject} from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport * as XLSX from 'xlsx';\nimport {loadDataAction, ModalReduxAction} from '../../actions/modal.actions';\nimport AppContainer from '../../container/AppContainer';\nimport ApiService from '../../utils/axios';\nimport {AxiosError, AxiosResponse} from \"axios\";\nimport {\n  getStockAction,\n  IStockState,\n  StockReducerAction\n} from \"../../actions/stock.actions\";\nimport ShowIf from \"../Utils/ShowIf\";\nimport StockVenueDetail from \"./StockVenueDetail\";\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<StockReducerAction>;\n  stock: IStockState;\n  getStockAction(): StockReducerAction;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  canDrop: boolean;\n  loadingSettings: boolean;\n  carsByVenue: any[];\n  totalCars: number;\n  createdCard: number;\n  deletedCard: number;\n  venues: any[];\n  loading: boolean;\n  sending: boolean;\n  file: File | null;\n}\n\nclass StockImportView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  readonly inputFile: RefObject<HTMLInputElement>;\n\n  readonly state = {\n    error: null,\n    canDrop: false,\n    loadingSettings: false,\n    carsByVenue:[],\n    venues: [],\n    totalCars: 0,\n    createdCard: 0,\n    deletedCard: 0,\n    loading: false,\n    sending: false,\n    file: null,\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Importar Stock';\n    this.clickUploadFile = this.clickUploadFile.bind(this);\n    this.getVenues = this.getVenues.bind(this);\n    this.processSettings = this.processSettings.bind(this);\n    this.deleteVenue = this.deleteVenue.bind(this);\n    this.handleChangeInputFile = this.handleChangeInputFile.bind(this);\n    this.handleDrop = this.handleDrop.bind(this);\n    this.dragOverHandler = this.dragOverHandler.bind(this);\n    this.dragEndHandler = this.dragEndHandler.bind(this);\n    this.dragLeaveHandler = this.dragLeaveHandler.bind(this);\n    this.sendCreate = this.sendCreate.bind(this);\n    this.inputFile = React.createRef();\n  }\n\n  public componentWillMount() {\n    // set the title of the page\n    document.title = 'OSA Andes | Importar Stock';\n    this.getVenues();\n    this.props.getStockAction();\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      loadingSettings, sending, loading, carsByVenue, totalCars, createdCard, deletedCard\n    } = this.state;\n    return (\n      <AppContainer title=\"\" cMenu=\"2\" cSubMenu=\"2.4\" cAction=\"Importar\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Importar stock</h3>\n              <div className=\"pull-right box-tools\">\n                <button\n                  className=\"btn btn-sm btn-primary\"\n                  onClick={this.downloadTemplate}\n                >\n                  <i className=\"fa fa-fw fa-download\"/> Descargar Formato\n                </button>\n              </div>\n            </div>\n            <div className=\"box-body margin\">\n              {\n                carsByVenue.length ?\n                  <div className=\"row\">\n                    <div className=\"col-md-12\">\n                      <div\n                      style={{\n                        backgroundColor: \"#f0f0f0\",\n                        padding: \"10px 10px 2px  10px\",\n                        marginBottom: \"10px\"\n                      }}>\n                        <p className=\"text-green\">\n                          <i className=\"fa fa-fw fa-plus-circle\"/> Se {createdCard > 1 ? \"agregarán\" : \"agregará\"} {createdCard} {createdCard > 1 ? \"unidades\" : \"unidad\"} al stock.\n                        </p>\n                        <p className=\"text-red\">\n                          <i className=\"fa fa-fw fa-minus-circle\" /> Se {deletedCard > 1 ? \"eliminarán\" : \"eliminará\"} {deletedCard} {deletedCard > 1 ? \"unidades\" : \"unidad\"} del stock.\n                        </p>\n                      </div>\n                    </div>\n                    <div className=\"col-md-12\">\n                      <div className=\"form-group\">\n                        <label>Configuración cargada</label>\n                        <div className=\"box-group\" id=\"accordion\" style={{margin: '2px 0 10px 0'}}>\n                          {\n                            carsByVenue.map((venue: any, index) => {\n                              return (\n                                <StockVenueDetail\n                                  index={index}\n                                  venue={venue}\n                                  key={venue.name}\n                                  deleteVenue={this.deleteVenue}\n                                />\n                              );\n                            })\n                          }\n                        </div>\n                      </div>\n                    </div>\n                    <div className=\"col-md-6\">\n                      <p><strong>Total de sucursales:</strong> {carsByVenue.length}</p>\n                      <p><strong>Total de unidades:</strong> {totalCars}</p>\n                    </div>\n                    <div className=\"col-md-6 text-right\">\n                      {/*<button className=\"btn btn-sm btn-default\" onClick={this.clickUploadFile}>*/}\n                      {/*  <i className=\"fa fa-fw fa-cogs\" /> Cambiar configuración*/}\n                      {/*</button>*/}\n                    </div>\n                  </div> :\n                  <div className=\"row\">\n                    <div className=\"col col-md-12\">\n                      <div className=\"form-group\">\n                        <div\n                          className=\"upload-file text-center pointer\"\n                          onClick={this.clickUploadFile}\n                          onDrop={this.handleDrop}\n                          onDragOver={this.dragOverHandler}\n                          onDragEnd={this.dragEndHandler}\n                          onDragLeave={this.dragLeaveHandler}\n                          style={{\n                            backgroundColor: '#EEEEEE',\n                            border: this.state.canDrop ? '1px solid #979797' : '1px dashed #979797',\n                            padding: '100px 20px',\n                            color: this.state.canDrop ? '#aebccb' : '#6e7a89',\n                            borderRadius: '10px'\n                          }}>\n                          <i className=\"fa fa-2x fa-cloud-upload\"/><br/>\n                          Prueba soltando el excel aquí, o haz click para seleccionar el excel a cargar.\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n              }\n              <input\n                type=\"file\"\n                onChange={this.handleChangeInputFile}\n                style={{display: 'None'}}\n                ref={this.inputFile}\n                accept=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel\"\n              />\n            </div>\n            <ShowIf condition={carsByVenue.length > 0}>\n              <div className=\"box-footer text-right\">\n                <button\n                  className=\"btn btn-sm btn-default\"\n                  onClick={() => this.props.history.push('/stock/')}\n                >\n                  Cancelar\n                </button>\n                <button\n                  className=\"btn btn-sm btn-primary\"\n                  style={{marginLeft: '5px'}}\n                  onClick={this.sendCreate}\n                  disabled={sending}\n                >\n                  {\n                    sending || loading ?\n                      <React.Fragment>\n                        <i className=\"fa fa-fw fa-spin fa-spinner\"/> Creando...\n                      </React.Fragment>\n                      : 'Crear'\n                  }\n                </button>\n              </div>\n            </ShowIf>\n            {\n              sending || loading || loadingSettings ?\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div> : null\n            }\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private deleteVenue(venueName: string): void {\n    const {carsByVenue} = this.state;\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar la sucursal \"${venueName}\"`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.setState({\n          carsByVenue: carsByVenue.filter((venue: any) => venue.name !== venueName)\n        });\n      }\n    });\n  }\n\n  private clickUploadFile(): void {\n    if (this.inputFile.current) {\n      this.inputFile.current.click();\n    }\n  }\n\n  private downloadTemplate(): void {\n    /* headers worksheet */\n    const data = [{\n      sucursal: '',\n      NInterno: '',\n      vin: '',\n      marca: '',\n      patente: '',\n      denominacion: '',\n      color: '',\n      propiedad: '',\n      tipo: ''\n    }];\n    /* make the worksheet */\n    const ws = XLSX.utils.json_to_sheet(data);\n    /* add to workbook */\n    const wb = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(wb, ws, 'Autos');\n    /* generate an XLSX file */\n    XLSX.writeFile(wb, 'template_stock_settings.xlsx');\n  }\n\n  private processSettings(file: File): void {\n    const {vinInStock} = this.props.stock;\n    const {venues} = this.state;\n    let createdCard = 0;\n    let totalCars = 0;\n    this.setState({\n      loadingSettings: true\n    });\n    if (['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'].includes(file.type)) {\n      const reader = new FileReader();\n      const rABS = !!reader.readAsBinaryString;\n      reader.onload = (e: any) => {\n        if (e.target) {\n          let data = e.target.result;\n          if (!rABS) {\n            data = new Uint8Array(data);\n          }\n          const workbook: XLSX.WorkBook = XLSX.read(data, {\n            type: rABS ? 'binary' : 'array'\n          });\n          const excelData = workbook.Sheets.hasOwnProperty('Autos') ? XLSX.utils.sheet_to_json(workbook.Sheets.Autos) : [];\n          const carsByVenue: any = {};\n          if (excelData.length >= 1) {\n            excelData.forEach((item: any) => {\n              if (item.hasOwnProperty('vin') && item.vin && item.hasOwnProperty('sucursal') && item.sucursal) {\n                totalCars++;\n                const vinWarning = item.vin.length < 17;\n                const patentWarning = item.patente && item.patente.length < 6;\n                const inStock = vinInStock.hasOwnProperty(item.vin.trim());\n                if(!inStock){\n                  createdCard++;\n                }\n                const car = {\n                  vin: item.vin.trim(),\n                  internalNumber: item.NInterno ? item.NInterno.trim() : '',\n                  color: item.color ? item.color.trim() : '',\n                  denomination: item.denominacion ? item.denominacion.trim() : '',\n                  brand: item.marca ? item.marca.trim() : '',\n                  patent: item.patente ? item.patente.trim() : '',\n                  property: item.propiedad ? item.propiedad.trim().toUpperCase() : '',\n                  type: item.tipo ? item.tipo.trim() : '',\n                  hasWarnings: vinWarning || patentWarning,\n                  created: !inStock,\n                  warning: {\n                    vin: vinWarning,\n                    patent: patentWarning\n                  }\n                };\n                if (!carsByVenue.hasOwnProperty(item.sucursal)) {\n                  carsByVenue[item.sucursal] = {\n                    cars: []\n                  };\n                }\n                carsByVenue[item.sucursal].cars.push(car);\n              } else {\n                /* tslint:disable:no-console */\n                console.log('Error en linea:');\n                console.log(item.__rowNum__);\n              }\n            });\n            const carsByVenueArray: any[] = [];\n            for (const cv in carsByVenue) {\n              if (carsByVenue.hasOwnProperty(cv)) {\n                const existVenue = venues.length ? venues.some((venue: any) => {\n                  return venue.name.trim().toLowerCase() === cv.trim().toLowerCase()\n                }) : false;\n                carsByVenueArray.push({\n                  name: cv.trim(),\n                  warningNoExist: !existVenue,\n                  cars: carsByVenue[cv].cars.sort((x: any, y: any) => {\n                    return (x.hasWarnings === y.hasWarnings) ? 0 : x.hasWarnings ? -1 : 1;\n                  })\n                });\n              }\n            }\n            this.setState({\n              file,\n              createdCard,\n              deletedCard: (Object.keys(vinInStock).length  - (totalCars- createdCard)),\n              totalCars,\n              carsByVenue: carsByVenueArray,\n              loadingSettings: false\n            });\n          } else {\n            swal(\n              'Importador de configuración',\n              `\"${file.name}\" no cumple con los requisitos mínimos o no tiene autos.`,\n              'error'\n            );\n            this.setState({\n              loadingSettings: false\n            });\n          }\n        }\n      };\n      if (rABS) {\n        reader.readAsBinaryString(file);\n      } else {\n        reader.readAsArrayBuffer(file);\n      }\n      if (this.inputFile.current) {\n        this.inputFile.current.value = '';\n      }\n    } else {\n      swal('Importador de configuración', 'Este archivo no cumple con los requisitos mínimos o no tiene autos.', 'error');\n      this.setState({\n        loadingSettings: false\n      });\n    }\n  }\n\n  private handleChangeInputFile(e: React.ChangeEvent<HTMLInputElement>): void {\n    const {files} = e.target;\n    if (files && files.length) {\n      this.processSettings(files[0]);\n    }\n  }\n\n  private handleDrop(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      if (dt.items.length) {\n        const file: File | null = dt.items[0].getAsFile();\n        if (file) {\n          this.processSettings(file);\n        }\n      }\n    } else {\n      if (dt.files.length) {\n        const file = dt.files[0];\n        this.processSettings(file);\n      }\n    }\n  }\n\n  private dragOverHandler(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    this.setState({\n      canDrop: true\n    });\n  }\n\n  private dragLeaveHandler(): void {\n    this.setState({\n      canDrop: false\n    });\n  }\n\n  private dragEndHandler(e: React.DragEvent<HTMLDivElement>): void {\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      // Use DataTransferItemList interface to remove the drag data\n      for (let i = 0; i < dt.items.length; i++) {\n        dt.items.remove(i);\n      }\n    } else {\n      // Use DataTransfer interface to remove the drag data\n      e.dataTransfer.clearData();\n    }\n  }\n\n  private getVenues(){\n    this.setState({loading: true});\n    const api: ApiService = new ApiService();\n    api.getVenues({ page: 1, pageSize: 200 })\n      .then((response: AxiosResponse):void =>{\n        this.setState({\n          venues: response.data.results,\n          loading: false\n        });\n      })\n    .catch((err: AxiosError): void => {\n      api.errorHandler(err);\n    });\n  }\n\n  private sendCreate(): void {\n    const {carsByVenue, totalCars, file} = this.state;\n    const { history } = this.props;\n    this.setState({\n      sending: true\n    });\n    if (!totalCars) {\n      swal('Importación de stock', 'No se ha importado la configuración o no contiene sucursales.', 'error');\n      this.setState({\n        sending: false\n      });\n    } else if (file) {\n      const api = new ApiService();\n      api.getSource();\n      api\n        .loadStock({\n          carsByVenue\n        })\n        .then((response: any) => {\n          const { message } = response.data;\n          setTimeout(() => {\n            swal('Importación de stock', message, 'success');\n          }, 200);\n          history.push('/stock/');\n          this.setState({\n            sending: false\n          });\n        })\n        .catch((e) => {\n          console.log('e', e);\n          swal('Importación de stock', 'Se produjo un error al cargar el stock.', 'error');\n          this.setState({\n            sending: false\n          });\n        });\n    }\n  }\n}\n\nconst mapStateToProps = (state: { stock: IStockState }) => {\n  return {\n    stock: state.stock\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getStockAction: () => dispatch(getStockAction()),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(StockImportView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport slugify from 'slugify';\nimport StockCarDetail from './StockCarDetail';\n\ninterface IPropsType {\n  venue: any;\n  index: number;\n\n  deleteVenue(venueName: string): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass StockVenueDetail extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {venue, index} = this.props;\n    const warnings = venue.cars.filter((car: any) => car.hasWarnings).length;\n    const created = venue.cars.filter((car: any) => car.created).length;\n    return (\n      <div className=\"panel box box-default\" style={{borderTopWidth: '2px'}}>\n        <div className=\"box-header with-border\" style={{padding: '10px 6px'}}>\n          <h4 className=\"box-title\" style={{\n            fontSize: '15px',\n            display: 'block'\n          }}>\n            <a data-toggle=\"collapse\"\n               data-parent=\"#accordion\"\n               href={`#${slugify(venue.name.toLowerCase(), {remove: /[*+~.()'\"!:@]/g})}`}\n               aria-expanded=\"false\"\n               className=\"collapsed\">\n              {index + 1} {venue.name} ({venue.cars.length} Unidades)\n\n            {/*<i*/}\n            {/*  className=\"fa fa-minus-circle text-red pull-right pointer\"*/}\n            {/*  onClick={() => this.props.deleteVenue(venue.name)}*/}\n            {/*/>*/}\n            {\n              venue.warningNoExist ?\n                <span className=\"text-muted pull-right\" style={{marginLeft: '5px'}}>\n                  <i className=\"fa fa-warning\" style={{color: '#f2aa2e'}}/> Esta sucursal se creará.\n                </span> : null\n            }\n            {\n              warnings ?\n                <span className=\"text-muted pull-right\" style={{marginLeft: '5px'}}>\n                  <i className=\"fa fa-warning\" style={{color: '#f2aa2e'}}/> {warnings} alertas.\n                </span> : null\n            }\n            {\n              created ?\n                <span className=\"text-muted  text-green pull-right\" style={{marginLeft: '5px'}}>\n                  <i className=\"fa fa-plus-circle text-green\"/> {created} {created > 1 ? \"unidades\" : \"unidad\"}.\n                </span> : null\n            }\n            </a>\n          </h4>\n        </div>\n        <div\n          id={`${slugify(venue.name.toLowerCase(), {remove: /[*+~.()'\"!:@]/g})}`}\n          className=\"panel-collapse collapse\"\n          aria-expanded=\"false\"\n        >\n          <div className=\"box-body no-padding\">\n            <table className=\"table table-striped\">\n              <thead>\n              <tr>\n                <th style={{width: '18%'}}>VIN</th>\n                <th style={{width: '10%'}}>PATENTE</th>\n                <th style={{width: '15%'}}>MARCA</th>\n                <th>DENOMINACION</th>\n                <th style={{width: '15%'}}>TIPO</th>\n              </tr>\n              </thead>\n              <tbody>\n              {\n                venue.cars.map((car: any, index: any) => {\n                  return (\n                    <StockCarDetail car={car} key={index}/>\n                  );\n                })\n              }\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </div>\n    );\n  }\n}\n\nexport default StockVenueDetail;\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\n\ninterface IPropsType {\n  car: any;\n  // increaseWarning(): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass StockCarDetail extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {car} = this.props;\n    return (\n      <tr className={car.created ? \"text-green\" : \"\"}>\n        <td style={{fontSize: \"12px\"}}>\n          {\n            car.hasWarnings && car.warning.vin ?\n              <i\n                className=\"fa fa-warning pointer\"\n                style={{\n                  color: '#f2aa2e'\n                }}\n                data-toggle=\"tooltip\"\n                data-placement=\"top\"\n                title=\"El vin debe tener al menos 17 dígitos.\"\n              /> : null\n          }{\n            car.created ?\n              <i\n                className=\"fa fa-plus-circle text-green pointer\"\n                data-toggle=\"tooltip\"\n                data-placement=\"top\"\n                title=\"Este vehículo se agregará al stock.\"\n              /> : null\n          } {car.vin}\n        </td>\n        <td style={{fontSize: \"12px\"}}>\n          {\n            car.hasWarnings && car.warning.patent ?\n              <i\n                className=\"fa fa-warning pointer\"\n                style={{\n                  color: '#f2aa2e'\n                }}\n                data-toggle=\"tooltip\"\n                data-placement=\"top\"\n                title=\"La patente debe tener al menos 6 dígitos.\"\n              /> : null\n          } {car.patent}\n        </td>\n        <td style={{fontSize: \"12px\"}}>{car.brand}</td>\n        <td style={{fontSize: \"12px\"}}>{car.denomination}</td>\n        <td style={{fontSize: \"12px\"}}>{car.type}</td>\n      </tr>\n    );\n  }\n}\n\nexport default StockCarDetail;\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport * as moment from 'moment-timezone';\nimport { io } from \"socket.io-client\";\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport AppContainer from '../../container/AppContainer';\nimport ModalView from '../Modal/ModalView';\nimport {\n  changeFilter,\n  changeFilterText,\n  getStockAction,\n  IStockState,\n  StockReducerAction\n} from \"../../actions/stock.actions\";\nimport filterFactory from \"react-bootstrap-table2-filter\";\nimport paginationFactory from \"react-bootstrap-table2-paginator\";\nimport BootstrapTable from \"react-bootstrap-table-next\";\nimport * as XLSX from \"xlsx\";\nimport BootstrapSelect from \"../Utils/BootstrapSelect\";\nimport Row from \"../Utils/Row\";\nimport {IFilterStock} from \"../../reducers/stock.reducer\";\nimport ShowIf from \"../Utils/ShowIf\";\nimport ImageLazyLoad from \"../Utils/ImageLazyLoad\";\nimport {IWindow} from \"../../interfaces/window\";\nimport {hasPermission} from \"../../utils/common\";\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\n\ndeclare let window: IWindow;\n\ninterface IPropsType extends RouteComponentProps<{}> {\n  dispatch: Dispatch<StockReducerAction>;\n  stock: IStockState;\n\n  getStockAction(): StockReducerAction;\n\n  changeFilter(filter: IFilterStock): StockReducerAction;\n\n  changeFilterText(filter: IFilterStock): StockReducerAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\n\nclass StockView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  private paginationOption: any = {\n    paginationSize: 4,\n    showTotal: true,\n    paginationTotalRenderer: this.customTotal,\n    sizePerPageList: [{\n      text: '20', value: 20\n    },{\n      text: '50', value: 50\n    }, {\n      text: '100', value: 100\n    }, {\n      text: '200', value: 200\n    }],\n    onPageChange: () => {\n      window.scrollTo(0, 0);\n      setTimeout(() => {\n        $('[data-toggle=\"tooltip\"]').tooltip();\n      }, 200);\n    }\n  };\n\n  private socket: Socket;\n\n  readonly columns: any[] = [];\n\n  readonly defaultSorted = [{\n    dataField: 'status',\n    order: 'asc'\n  }];\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Stock Actual';\n    this.xlsExport = this.xlsExport.bind(this);\n    this.daysInVenue = this.daysInVenue.bind(this);\n    this.repcetionVenue = this.repcetionVenue.bind(this);\n    this.filterAllVenues = this.filterAllVenues.bind(this);\n    this.filterVenues = this.filterVenues.bind(this);\n    this.filterAllBrands = this.filterAllBrands.bind(this);\n    this.filterBrands = this.filterBrands.bind(this);\n    this.filterAllDenominations = this.filterAllDenominations.bind(this);\n    this.filterDenominations = this.filterDenominations.bind(this);\n    this.filterAllColors = this.filterAllColors.bind(this);\n    this.filterColors = this.filterColors.bind(this);\n    this.filterType = this.filterType.bind(this);\n    this.venueFormatter = this.venueFormatter.bind(this);\n    this.filterProperty = this.filterProperty.bind(this);\n    this.handleChangeSearchText = this.handleChangeSearchText.bind(this);\n    this.clearFilter = this.clearFilter.bind(this);\n    this.columns = [{\n      dataField: 'vin',\n      text: 'VIN',\n      // formatter: this.brandFormatter,\n      // filterValue: (cell: any, row: any) => `${cell}${row.denomination}${row.vin}${row.patent}`,\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true\n    }, {\n      dataField: 'internalNumber',\n      text: 'Nº Interno',\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true\n    }, {\n      dataField: 'brand',\n      text: 'Marca',\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true\n    }, {\n      dataField: 'denomination',\n      text: 'Modelo',\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true\n    }, {\n      dataField: 'color',\n      text: 'Color',\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true\n    }, {\n      dataField: 'venueFound',\n      text: 'Sucursal',\n      formatter: this.venueFormatter,\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true\n    }, {\n      dataField: 'receptionVenue',\n      text: 'Fecha Recepción',\n      formatter: this.repcetionVenue,\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true\n    }, {\n      dataField: 'daysInVenue',\n      text: 'Días en Sucursal',\n      formatter: this.daysInVenue,\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true\n    }];\n  }\n\n  public componentWillMount(): void {\n    this.props.getStockAction();\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {token: (window.user as any).token}\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {room: `stock-${window.user.team._id}`});\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update) {\n        this.props.getStockAction();\n      }\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.stock.source) {\n      this.props.stock.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any) {\n    $('.react-bootstrap-table-pagination')\n      .css({padding: '3px 15px'});\n    $('.react-bootstrap-table-pagination div')\n      .removeClass('col-xs-6')\n      .addClass('col-xs-12')\n      .css({padding: '3px 15px'});\n    $('.react-bootstrap-table-pagination div:last-child')\n      .removeClass('text-right')\n      .addClass('text-right');\n    $('#pageDropDown')\n      .removeClass('btn-sm')\n      .addClass('btn-sm');\n    $('.bs-searchbox input')\n      .removeClass('input-sm')\n      .addClass('input-sm');\n    $('.pagination')\n      .removeClass('pagination-sm')\n      .addClass('pagination-sm')\n      .css({margin: 0});\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {loading, carsTable, dataFilters, filter, searching, message} = this.props.stock;\n    return (\n      <AppContainer title=\"\" cMenu=\"2\" cSubMenu=\"2.4\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Stock Actual</h3>\n              <ShowIf condition={!loading && message.length < 1}>\n                {\n                  hasPermission(window.user, 'importStock') ?\n                    <div className=\"box-tools pull-right\">\n                      <button\n                        className=\"btn btn-sm btn-primary  hidden-xs\"\n                        onClick={() => this.props.history.push(`/stock/import/`)}\n                      >\n                        <i className=\"fa fa-fw fa-cloud-upload\"/> Importar\n                      </button>\n                    </div> : null\n                }\n              </ShowIf>\n            </div>\n            <div className=\"box-body no-padding\">\n              <ShowIf condition={message.length > 1}>\n                <p className=\"text-center text-muted\" style={{paddingBottom: \"10px\"}}>\n                  <ImageLazyLoad\n                    url=\"/images/not_found.png\"\n                    height={'200px'}\n                    style={{\n                      opacity: 0.5,\n                      maxHeight: '200px',\n                      marginBottom: '20px',\n                      marginTop: '35x'\n                    }}\n                    replaceLoading={\n                      <i\n                      className={'fa fa-2x fa-circle-o-notch text-primary fa-spin'}\n                      style={{padding: '30px'}}\n                      />\n                    }\n                  /><br/>\n                  <strong>{message}</strong>\n                </p>\n              </ShowIf>\n              <ShowIf condition={!loading && message.length < 1}>\n                <React.Fragment>\n                  <div className=\"row\" style={{margin: '5px 0'}}>\n                    <div className=\"col-md-12\">\n                      <div className=\"form-group\">\n                        <label htmlFor=\"cars\" className=\"control-label\">Buscador</label>\n                        <input\n                          type=\"text\"\n                          className=\"form-control\"\n                          id=\"cars\"\n                          placeholder=\"Busca por VIN, Nº interno, patente, marca o modelo.\"\n                          onChange={this.handleChangeSearchText}\n                        />\n                      </div>\n                    </div>\n                    <div className=\"col-md-4\">\n                      <div className=\"form-group\">\n                        <label htmlFor=\"venues\" className=\"control-label\">Sucursales</label>\n                        <BootstrapSelect\n                          noneSelectedText=\"Todas\"\n                          displayItems={2}\n                          search={true}\n                          selectedText=\"sucursales seleccionadas.\"\n                          selected={filter.venues}\n                          allOption={true}\n                          selectAll={this.filterAllVenues}\n                          options={dataFilters.venues.map(venue => ({\n                            value: venue._id,\n                            text: venue.name\n                          }))}\n                          onClick={this.filterVenues}\n                        />\n                      </div>\n                    </div>\n                    <div className=\"col-md-4\">\n                      <div className=\"form-group\">\n                        <label htmlFor=\"types\" className=\"control-label\">Tipo</label>\n                          <BootstrapSelect\n                            noneSelectedText=\"Todos\"\n                            displayItems={4}\n                            selectedText=\"estados seleccionados.\"\n                            separator=\" - \"\n                            options={dataFilters.types\n                              .map((type) => ({\n                                value: type,\n                                text: type\n                              }))}\n                            selected={[filter.type]}\n                            autoClouse={true}\n                            onClick={this.filterType}\n                          />\n                      </div>\n                    </div>\n                    <div className=\"col-md-4\">\n                      <div className=\"form-group\">\n                        <label htmlFor=\"properties\" className=\"control-label\">Propiedad</label>\n                          <BootstrapSelect\n                            noneSelectedText=\"Todos\"\n                            displayItems={4}\n                            selectedText=\"estados seleccionados.\"\n                            separator=\" - \"\n                            options={dataFilters.properties\n                              .map((property) => ({\n                                value: property,\n                                text: property\n                              }))}\n                            selected={[filter.property]}\n                            autoClouse={true}\n                            onClick={this.filterProperty}\n                          />\n                      </div>\n                    </div>\n                    <div className=\"col-md-4\">\n                      <div className=\"form-group\">\n                        <label htmlFor=\"brands\" className=\"control-label\">Marca</label>\n                        <BootstrapSelect\n                          noneSelectedText=\"Todas\"\n                          displayItems={2}\n                          search={true}\n                          selectedText=\"marcas seleccionadas.\"\n                          selected={filter.brands}\n                          allOption={true}\n                          selectAll={this.filterAllBrands}\n                          options={dataFilters.brands.map(brand => ({\n                            value: brand,\n                            text: brand\n                          }))}\n                          onClick={this.filterBrands}\n                        />\n                      </div>\n                    </div>\n                    <div className=\"col-md-4\">\n                      <div className=\"form-group\">\n                        <label htmlFor=\"denominations\" className=\"control-label\">Modelo</label>\n                        <BootstrapSelect\n                          noneSelectedText=\"Todas\"\n                          displayItems={2}\n                          search={true}\n                          selectedText=\"modelos seleccionadas.\"\n                          selected={filter.denominations}\n                          allOption={true}\n                          selectAll={this.filterAllDenominations}\n                          options={dataFilters.denominations.map(denomination => ({\n                            value: denomination,\n                            text: denomination\n                          }))}\n                          onClick={this.filterDenominations}\n                        />\n                      </div>\n                    </div>\n                     <div className=\"col-md-4\">\n                      <div className=\"form-group\">\n                        <label htmlFor=\"denominations\" className=\"control-label\">Color</label>\n                        <BootstrapSelect\n                          noneSelectedText=\"Todas\"\n                          displayItems={2}\n                          search={true}\n                          selectedText=\"colores seleccionadas.\"\n                          selected={filter.colors}\n                          allOption={true}\n                          selectAll={this.filterAllColors}\n                          options={dataFilters.colors.map(color => ({\n                            value: color,\n                            text: color\n                          }))}\n                          onClick={this.filterColors}\n                        />\n                      </div>\n                    </div>\n                  </div>\n                  <Row style={{margin: '5px 0'}}>\n                    <div\n                      className=\"col-md-6 col-md-push-6 text-right\"\n                      style={{marginBottom: '10px'}}\n                    >\n                      <button\n                        className=\"btn btn-default btn-sm\"\n                        onClick={this.clearFilter}\n                        disabled={!searching}\n                      >\n                        <i className=\"fa fa-fw fa-eraser\"/> Limpiar Filtros\n                      </button>\n                      <button\n                        className=\"btn btn-sm btn-primary hidden-xs hidden-sm\"\n                        onClick={this.xlsExport}\n                        style={{marginLeft: '5px'}}\n                      >\n                        <i className=\"fa fa-fw fa-download\"/> Exportar Excel\n                      </button>\n                    </div>\n                  </Row>\n                </React.Fragment>\n              </ShowIf>\n              <ShowIf condition={carsTable.length > 0 && !loading}>\n                <div className=\"stock-table\">\n                  <BootstrapTable\n                    keyField=\"_id\"\n                    data={carsTable}\n                    columns={this.columns}\n                    filter={filterFactory()}\n                    pagination={paginationFactory(this.paginationOption)}\n                    defaultSorted={this.defaultSorted}\n                  />\n                </div>\n              </ShowIf>\n              <ShowIf condition={searching && carsTable.length < 1 && !loading}>\n                <p className=\"text-center text-muted\">\n                  <ImageLazyLoad\n                    url=\"/images/not_found.png\"\n                    height={'200px'}\n                    style={{\n                      opacity: 0.5,\n                      maxHeight: '200px',\n                      marginBottom: '10px'\n                    }}\n                    replaceLoading={\n                      <i\n                      className={'fa fa-2x fa-circle-o-notch text-primary fa-spin'}\n                      style={{padding: '30px'}}\n                      />\n                    }\n                  /><br/>\n                  <strong>No hay información para mostrar</strong>\n                </p>\n              </ShowIf>\n            </div>\n            {\n              loading &&\n              <div className=\"overlay\">\n                <i className=\"fa fa-spinner fa-spin text-purple\"/>\n              </div>\n            }\n          </div>\n          <ModalView/>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private handleChangeSearchText(e: React.ChangeEvent<HTMLInputElement>): void {\n    e.preventDefault();\n    const value = e.target.value.trim();\n    const {filter} = this.props.stock;\n    this.props.changeFilterText({\n      ...filter,\n      text: value ? e.target.value : ''\n    });\n  }\n\n  private filterAllVenues(value: boolean): void {\n    const {filter, dataFilters} = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      venues: value ? dataFilters.venues.map((venue: any) => venue._id) : []\n    });\n  }\n\n  private filterVenues(value: any): void {\n    const {filter} = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      venues: filter.venues.includes(value)\n        ? filter.venues.filter((venue) => venue !== value)\n        : [value, ...filter.venues]\n    });\n  }\n\n  private filterAllBrands(value: boolean): void {\n    const {filter, dataFilters} = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      brands: value ? dataFilters.brands.map((brand: any) => brand) : []\n    });\n  }\n\n  private filterBrands(value: any): void {\n    const {filter} = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      brands: filter.brands.includes(value)\n        ? filter.brands.filter((brand) => brand !== value)\n        : [value, ...filter.brands]\n    });\n  }\n\n  private filterAllDenominations(value: boolean): void {\n    const {filter, dataFilters} = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      denominations: value ? dataFilters.denominations.map((denomination: any) => denomination) : []\n    });\n  }\n\n  private filterDenominations(value: any): void {\n    const {filter} = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      denominations: filter.denominations.includes(value)\n        ? filter.denominations.filter((denomination) => denomination !== value)\n        : [value, ...filter.denominations]\n    });\n  }\n\n  private filterAllColors(value: boolean): void {\n    const {filter, dataFilters} = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      colors: value ? dataFilters.colors.map((color: any) => color) : []\n    });\n  }\n\n  private filterColors(value: any): void {\n    const {filter} = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      colors: filter.colors.includes(value)\n        ? filter.colors.filter((color) => color !== value)\n        : [value, ...filter.colors]\n    });\n  }\n\n  private filterType(value: string): void {\n    const {filter} = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      type: filter.type !== value ? value : ''\n    });\n  }\n\n  private filterProperty(value: string): void {\n    const {filter} = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      property: filter.property !== value ? value : ''\n    });\n  }\n\n  private clearFilter(): void {\n    this.props.changeFilter({\n      venues: [],\n      colors: [],\n      brands: [],\n      denominations: [],\n      property: '',\n      type: '',\n      text: ''\n    });\n    $('#cars').val('');\n  }\n\n  private xlsExport(): void {\n    this.trackClick(\"Exportar\");\n    const {cars} = this.props.stock;\n    const data: any = [];\n    // order data\n    if (cars.length) {\n      for (const car of cars) {\n        data.push({\n          VIN: car.car.vin,\n          Patente: car.car.patent && car.car.patent.length ? car.car.patent : '-',\n          ['Nº interno']: car.car.internalNumber && car.car.internalNumber.length ? car.car.internalNumber : '-',\n          Marca: car.car.brand && car.car.brand.length ? car.car.brand : '-',\n          ['Denominación']: car.car.denomination && car.car.denomination.length ? car.car.denomination : '-',\n          Color: car.car.color && car.car.color.length ? car.car.color : '-',\n          Tipo: car.car.type && car.car.type ? car.car.type : '-',\n          Propiedad: car.car.property && car.car.property ? car.car.property : '-',\n          Sucursal: car.venueFound && car.venueFound.hasOwnProperty('name') ? car.venueFound.name : '-',\n        });\n      }\n    }\n    /* make the worksheet */\n    const ws = XLSX.utils.json_to_sheet(data);\n    /* add to workbook */\n    const wb = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(wb, ws, 'Detalle');\n    /* generate an XLSX file */\n    XLSX.writeFile(wb, `Stock ${moment().format('YYYYMMDD')}.xlsx`);\n  }\n\n  private customTotal(from: any, to: any, size: any) {\n    return(\n      <span className=\"react-bootstrap-table-pagination-total text-ellipsis\" style={{fontSize: '75%'}}>\n        &nbsp;&nbsp;Mostrando registros del {from} al {to} de {size} registros.\n      </span>\n    );\n  }\n\n  private daysInVenue(cell: string, row: any) {\n    return row.daysInVenue ?? '-'\n  }\n\n  private repcetionVenue(cell: string, row: any) {\n    return row.receptionVenue ? moment(row.receptionVenue).format('L')  : '-'\n  }\n\n  private venueFormatter(cell: string, row: any) {\n    return row.venueFound !== \"-\" ? row.venueFound : row.venue;\n  }\n}\n\nconst mapStateToProps = (state: { stock: IStockState }) => {\n  return {\n    stock: state.stock\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getStockAction: () => dispatch(getStockAction()),\n    changeFilter: (filter: IFilterStock) => dispatch(changeFilter(filter)),\n    changeFilterText: (filter: IFilterStock) => dispatch(changeFilterText(filter)),\n  };\n};\n\nexport default connect<{ stock: IStockState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(StockView);\n","import { AxiosError, default as Axios } from 'axios';\nimport * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport * as swal from 'sweetalert';\nimport { debounce } from 'throttle-debounce';\nimport { IUser } from '../../../../../../src/app/interfaces/user.interface';\nimport {\n  loadDataAction,\n  ModalReduxAction\n} from '../../actions/modal.actions';\nimport {\n  changeSearchUserAction,\n  changeTempUserAction,\n  createUserAction,\n  deleteUserAction,\n  getUsersAction,\n  ITempUser,\n  IUsersState,\n  updateUserAction,\n  UserReduxAction\n} from '../../actions/users.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport ApiService from '../../utils/axios';\nimport {\n  hasPermission,\n  showModal,\n  statusFooterButttonsModal\n} from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport UserFormChangePasswordView from './UserFormChangePasswordView';\nimport UserFormView from './UserFormView';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport { io } from \"socket.io-client\";\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<UserReduxAction>;\n  users: IUsersState;\n\n  getUsersAction(page: number, search?: string): UserReduxAction;\n  createUserAction(): UserReduxAction;\n  updateUserAction(): UserReduxAction;\n  deleteUserAction(id?: string): UserReduxAction;\n  changeTempUserAction(user: ITempUser): UserReduxAction;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n  changeSearchUserAction(searchText: string): UserReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  searchText: string;\n  exporing: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass UserListView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  readonly state = {\n    error: null,\n    searchText: '',\n    exporing: false\n  };\n\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de usuarios';\n    this.createUser = this.createUser.bind(this);\n    this.processCreateUser = this.processCreateUser.bind(this);\n    this.updateUser = this.updateUser.bind(this);\n    this.processUpdateUser = this.processUpdateUser.bind(this);\n    this.changePage = this.changePage.bind(this);\n    this.changeTempUser = this.changeTempUser.bind(this);\n    this.changePassword = this.changePassword.bind(this);\n    this.processChangePassword = this.processChangePassword.bind(this);\n    this.exportExcel = this.exportExcel.bind(this);\n    this.cloneUser = this.cloneUser.bind(this);\n    this.onChangeSearch = this.onChangeSearch.bind(this);\n    this.debounceOnChangeSearch = debounce(300, this.debounceOnChangeSearch);\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public componentWillMount(): void {\n    const { pagination } = this.props.users;\n    this.props.getUsersAction(pagination.page);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {token: (window.user as any).token}\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {room: `user-list-${window.user.team._id}`});\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update && data.updatedBy !== window.user._id) {\n        const {pagination} = this.props.users;\n        this.props.getUsersAction(pagination.page);\n      }\n    });\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if (this.props.users.pagination !== prevProps.users.pagination) {\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.users.source) {\n      this.props.users.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public exportExcel() {\n    this.trackClick('Exportar');\n    this.setState({\n      exporing: true\n    });\n    const api: ApiService = new ApiService();\n    const instance = api.getInstance();\n    instance.defaults.responseType = 'blob';\n    instance\n      .get(`/settings/users/export/`)\n      .then((response) => {\n        const blob = new Blob([response.data], {\n          type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'\n        });\n        const fileName = `${moment().format('YYYYMMDD')}-usuarios.xlsx`;\n        if (typeof window.navigator.msSaveBlob !== 'undefined') {\n          // IE workaround for \"HTML7007: One or more blob URLs were\n          // revoked by closing the blob for which they were created.\n          // These URLs will no longer resolve as the data backing\n          // the URL has been freed.\"\n          window.navigator.msSaveBlob(blob, fileName);\n        } else {\n          const blobURL = URL.createObjectURL(blob);\n          const tempLink = document.createElement('a');\n          tempLink.style.display = 'none';\n          tempLink.href = blobURL;\n          tempLink.setAttribute('download', fileName);\n          // Safari thinks _blank anchor are pop ups. We only want to set _blank\n          // target if the browser does not support the HTML5 download attribute.\n          // This allows you to download files in desktop safari if pop up blocking\n          // is enabled.\n          if (typeof tempLink.download === 'undefined') {\n            tempLink.setAttribute('target', '_blank');\n          }\n          this.setState({\n            exporing: false\n          });\n          document.body.appendChild(tempLink);\n          tempLink.click();\n          document.body.removeChild(tempLink);\n          URL.revokeObjectURL(blobURL);\n        }\n      })\n      .catch((err) => {\n        this.setState({\n          exporing: false\n        });\n        if (!Axios.isCancel(err)) {\n          swal!('Exportar usuarios', 'Ha ocurrido un error al general el excel.', 'error');\n        }\n      });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {exporing} = this.state;\n    const {\n      loading, users, pagination, searchText\n    } = this.props.users;\n    return (\n      <AppContainer title=\"\" cMenu=\"10\" cSubMenu=\"10.5\" cAction=\"Listado\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Usuarios <small>{pagination.count}</small></h3>\n              <div className=\"box-tools pull-right\">\n                {\n                  hasPermission(window.user, 'addUser') ?\n                    <button className=\"btn btn-sm btn-success\" onClick={this.createUser}><i className=\"fa fa-plus\" /> Agregar</button>\n                    : null\n                }\n                <button\n                  className=\"btn btn-sm btn-primary hidden-xs\"\n                  onClick={this.exportExcel}\n                  disabled={exporing}\n                  style={{marginLeft: '5px'}}\n                >\n                  {\n                    exporing ?\n                      <React.Fragment>\n                        <i className=\"fa fa-spin fa-spinner\"/> Exportando\n                      </React.Fragment>\n                      : <React.Fragment>\n                        <i className=\"fa fa-fw fa-download\"/> Exportar\n                      </React.Fragment>\n                  }\n                </button>\n              </div>\n            </div>\n            <div className=\"box-body no-padding\">\n              <div className=\"row\">\n                <div className=\"col-md-offset-8 col-md-4\">\n                  <div className=\"input-group input-group-sm\"\n                       style={{padding: '10px'}}\n                  >\n                    <input\n                      type=\"text\"\n                      value={searchText}\n                      className=\"form-control pull-right\"\n                      onChange={this.onChangeSearch}\n                      placeholder=\"Buscar\"/>\n                    <div className=\"input-group-btn\">\n                      <button className=\"btn btn-default\"><i className=\"fa fa-search\"/></button>\n                    </div>\n                  </div>\n                </div>\n              </div>\n              <table className=\"table table-andes table-striped\">\n                <thead>\n                <tr>\n                  <th style={{width: '24%'}}>Usuario</th>\n                  <th style={{width: '24%'}} className=\"hidden-xs\">Sucursal</th>\n                  <th style={{width: '24%'}} className=\"hidden-xs\">Formularios</th>\n                  <th style={{width: '24%'}} className=\"hidden-xs\">Modificado</th>\n                  {\n                    hasPermission(window.user, 'changeUser') ?\n                      <th style={{width: '1%'}} className=\"width-10\"/> : null\n                  }\n                  {\n                    hasPermission(window.user, 'addUser') ?\n                      <th style={{width: '1%'}} className=\"width-10\"/> : null\n                  }\n                  {\n                    window.user.isAdmin || (hasPermission(window.user, 'changeUser')) ?\n                      <th style={{width: '1%'}} className=\"width-10\"/> : null\n                  }\n                  {\n                    hasPermission(window.user, 'deleteUser') ?\n                      <th style={{width: '1%'}} className=\"width-10\"/> : null\n                  }\n                </tr>\n                </thead>\n                <tbody>\n                {\n                  !loading && users.length === 0 && users ? <tr>\n                    <td colSpan={6}>No se han encontrado resultados.</td>\n                  </tr> : null\n                }\n                {\n                  users.map((user: IUser) => {\n                    const forms = user.userForms;\n                    return (\n                      <tr\n                        key={user._id}\n                        id={`user-${user._id}`}\n                        className={'background-transition'}\n                      >\n                        <td className=\"middle\">{user.firstName} {user.lastName}<br/>\n                          <span className=\"text-sm text-muted\">{user.email}</span>\n                          <div className=\"hidden-lg hidden-md hidden-sm text-sm\">\n                            <span\n                              className=\"text-sm text-muted\">{user.venue ? user.venue.name : ''} - {user.company ? user.company.name : ''}</span>\n                          </div>\n                        </td>\n                        <td className=\"middle hidden-xs\">{user.venue ? user.venue.name : ''}<br/>\n                          <span className=\"text-sm text-muted\">{user.company ? user.company.name : ''}</span>\n                        </td>\n                        <td className=\"middle hidden-xs\">\n                          {forms.map((form, index) => {\n                            return <React.Fragment key={`${form._id}-${index}`}>\n                              {index > 0 ?\n                                <br/> : null}\n                              <span>{form.name}</span>\n                            </React.Fragment>;\n                          })}\n                        </td>\n                        <td className=\"middle hidden-xs text-muted\">{moment(user.updatedAt).format('LLL')}</td>\n                        {\n                          hasPermission(window.user, 'changeUser') ?\n                            <td className=\"middle-center text-yellow pointer\" onClick={() => this.changePassword(user)}>\n                              <i className=\"fa fa-lock\"/></td> : null\n                        }\n                        {\n                          hasPermission(window.user, 'addUser') ?\n                            <td className=\"middle-center text-blue pointer\" onClick={() => this.cloneUser(user)}>\n                              <i className=\"fa fa-clone\"/></td> : null\n                        }\n                        {\n                          window.user.isAdmin || (hasPermission(window.user, 'changeUser') && !user.isAdmin) ?\n                            <td className=\"middle-center text-blue pointer\" onClick={() => this.updateUser(user)}><i\n                              className=\"fa fa-pencil\"/></td> : <td></td>\n                        }\n                        {\n                          hasPermission(window.user, 'deleteUser') ?\n                            <td className=\"middle-center text-red pointer\" onClick={() => this.deleteUser(user)}><i\n                              className=\"fa fa-minus-circle\"/></td> : null\n                        }\n                      </tr>\n                    );\n                  })\n                }\n                </tbody>\n              </table>\n            </div>\n            {\n              pagination.pages > 1 &&\n              <div className=\"box-footer text-right\">\n                <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages}/>\n              </div>\n            }\n            {\n              loading &&\n              <div className=\"overlay\">\n                <i className=\"fa fa-spinner fa-spin text-purple\"/>\n              </div>\n            }\n          </div>\n          <ModalView/>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private cloneUser(user: IUser): void {\n    const { changeTempUser } = this;\n    const { venues, permissions, forms, companies } = this.props.users;\n    const tmpUser = {\n      ...user,\n      _id: '',\n      firstName: '',\n      lastName: '',\n      email: ''\n    };\n    tmpUser.venue = tmpUser.venue ? tmpUser.venue._id : '';\n    this.props.changeTempUserAction(tmpUser);\n    setTimeout(() => {\n      this.props.loadDataAction(\n        `Clonando usuario`,\n        <UserFormView\n          create={true}\n          changeTempUser={changeTempUser}\n          companies={companies}\n          venues={venues}\n          users={this.props.users}\n          forms={forms}\n          permissions={permissions}\n          user={tmpUser}\n        />,\n        <React.Fragment>\n          <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n          <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processCreateUser}>Crear</button>\n        </React.Fragment>\n      );\n    }, 400);\n  }\n\n  private onChangeSearch(e: React.ChangeEvent<HTMLInputElement>): void {\n    e.preventDefault();\n    const value = e.target.value.trim();\n    this.props.changeSearchUserAction(value);\n    this.debounceOnChangeSearch();\n  }\n\n  private debounceOnChangeSearch(): void {\n    this.props.getUsersAction(1);\n  }\n\n  private createUser(): void {\n    const { changeTempUser } = this;\n    const { venues, permissions, forms, companies } = this.props.users;\n    this.props.changeTempUserAction({\n      _id: '',\n      firstName: '',\n      lastName: '',\n      company: null,\n      email: '',\n      isAdmin: false,\n      isDriver: false,\n      venue: '',\n      userPermissions: [],\n      venuesAccess: [],\n      userForms: [],\n      settings: {}\n    });\n    setTimeout(() => {\n      this.props.loadDataAction(\n        'Agregar Usuario',\n        <UserFormView\n          create={true}\n          changeTempUser={changeTempUser}\n          venues={venues}\n          companies={companies}\n          users={this.props.users}\n          forms={forms}\n          permissions={permissions}\n        />,\n        <React.Fragment>\n          <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n          <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processCreateUser}>Crear</button>\n        </React.Fragment>\n      );\n    }, 400);\n  }\n\n  private processCreateUser(): void {\n    const {firstName, lastName, email, venue} = this.props.users.tempUser;\n    if (!firstName || !firstName.trim().length) {\n      swal!('Agregar usuario', 'El nombres es requerido', 'error');\n    } else if (!lastName || !lastName.trim().length) {\n      swal!('Agregar usuario', 'El apellidos es requerido', 'error');\n    } else if (!email || !email.trim().length) {\n      swal!('Agregar usuario', 'El email es requerido', 'error');\n    } else if (!venue || !venue.trim().length) {\n      swal!('Agregar usuario', 'El sucursal es requerido', 'error');\n    } else {\n      statusFooterButttonsModal(true);\n      this.props.createUserAction();\n    }\n  }\n\n  private changePassword(user: IUser): void {\n    const {changeTempUser} = this;\n    const tmpUser = {\n      ...user,\n      password: ''\n    };\n    changeTempUser(tmpUser);\n    setTimeout(() => {\n      this.props.loadDataAction(\n        `Cambiando contraseña a ${user.firstName} ${user.lastName}`,\n        <UserFormChangePasswordView changeTempUser={changeTempUser} users={this.props.users} user={user}/>,\n        <React.Fragment>\n          <button\n            type=\"button\"\n            className=\"btn btn-sm btn-default\"\n            data-dismiss=\"modal\"\n          >\n            Cancelar\n          </button>\n          <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processChangePassword}>Cambiar</button>\n        </React.Fragment>\n      );\n    }, 400);\n  }\n\n  private processChangePassword() {\n    const {password, _id} = this.props.users.tempUser;\n    statusFooterButttonsModal(true);\n    if (password && password.trim().length >= 6 && _id) {\n      const api: ApiService = new ApiService();\n      api.changePasswordUser(_id, password)\n        .then((response) => {\n          statusFooterButttonsModal(false);\n          showModal(false);\n          swal!(response.data.message, {\n            icon: 'success'\n          });\n        })\n        .catch((err: AxiosError) => {\n          statusFooterButttonsModal(false);\n          api.errorHandler(err);\n        });\n    } else {\n      swal!('Cambiar contraseña', 'La contraseña debe tener al menos 6 caracteres.', 'error');\n      statusFooterButttonsModal(false);\n    }\n  }\n\n  private updateUser(user: IUser): void {\n    const {changeTempUser} = this;\n    const {venues, permissions, forms, companies} = this.props.users;\n    const tmpUser = {...user};\n    tmpUser.venue = tmpUser.venue ? tmpUser.venue._id : '';\n    changeTempUser(tmpUser);\n    setTimeout(() => {\n      this.props.loadDataAction(\n        `Editando a ${user.firstName} ${user.lastName}`,\n        <UserFormView\n          create={false}\n          changeTempUser={changeTempUser}\n          companies={companies}\n          venues={venues}\n          users={this.props.users}\n          forms={forms}\n          permissions={permissions}\n          user={user}\n        />,\n        <React.Fragment>\n          <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n          <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processUpdateUser}>Editar</button>\n        </React.Fragment>\n      );\n    }, 400);\n  }\n\n  private processUpdateUser() {\n    const {firstName, lastName, email, venue} = this.props.users.tempUser;\n    if (!firstName || !firstName.trim().length) {\n      swal!('Agregar usuario', 'El nombres es requerido', 'error');\n    } else if (!lastName || !lastName.trim().length) {\n      swal!('Agregar usuario', 'El apellidos es requerido', 'error');\n    } else if (!email || !email.trim().length) {\n      swal!('Agregar usuario', 'El email es requerido', 'error');\n    } else if (!venue || !venue.trim().length) {\n      swal!('Agregar usuario', 'El sucursal es requerido', 'error');\n    } else {\n      statusFooterButttonsModal(true);\n      this.props.updateUserAction();\n    }\n  }\n\n  private changeTempUser({_id, firstName, lastName, email, venue, userPermissions, preferred, userForms, company, venuesAccess, password, isAdmin, isDriver, settings}: ITempUser) {\n    const tempUser: ITempUser = {\n      _id: _id ? _id : this.props.users.tempUser._id,\n      firstName: firstName ? firstName : this.props.users.tempUser.firstName,\n      lastName: lastName ? lastName : this.props.users.tempUser.lastName,\n      isAdmin: typeof isAdmin === 'boolean' ? isAdmin : this.props.users.tempUser.isAdmin,\n      isDriver: typeof isDriver === 'boolean' ? isDriver : this.props.users.tempUser.isDriver,\n      password: password ? password : '',\n      settings: settings ?? this.props.users.tempUser.settings,\n      email: email ? email : this.props.users.tempUser.email,\n      userPermissions: userPermissions ? userPermissions : this.props.users.tempUser.userPermissions,\n      userForms: userForms ? userForms : this.props.users.tempUser.userForms,\n      preferred: preferred ? preferred : preferred === undefined ? this.props.users.tempUser.preferred : null,\n      venue: venue ? venue : venue === undefined ? this.props.users.tempUser.venue : null,\n      venuesAccess: venuesAccess ? venuesAccess : venuesAccess === undefined ? this.props.users.tempUser.venuesAccess : [],\n      company: company ? company : company === undefined ? this.props.users.tempUser.company : null\n    };\n    this.props.changeTempUserAction(tempUser);\n  }\n\n  private deleteUser(user: IUser) {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el usuario ${user.firstName || ''} ${user.lastName || ''}`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete: any) => {\n      if (willDelete) {\n        this.props.deleteUserAction(user._id);\n      }\n    });\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    this.props.getUsersAction(page);\n  }\n}\n\nconst mapStateToProps = (state: { users: IUsersState }) => {\n  return {\n    users: state.users\n  };\n};\n\n// const mapDispatchToProps = (dispatch: Dispatch<UserReduxAction> ) => {\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getUsersAction: (page: number, search?: string) => dispatch(getUsersAction(page, search)),\n    deleteUserAction: (id: string) => dispatch(deleteUserAction(id)),\n    changeTempUserAction: (user: ITempUser) => dispatch(changeTempUserAction(user)),\n    createUserAction: () => dispatch(createUserAction()),\n    updateUserAction: () => dispatch(updateUserAction()),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer)),\n    changeSearchUserAction: (searchText: string) => dispatch(changeSearchUserAction(searchText))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(UserListView);\n","import {AxiosError, AxiosResponse, CancelTokenSource, default as Axios} from 'axios';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport {ICompany} from '../../../../../src/app/interfaces/company.interface';\nimport {IForm} from '../../../../../src/form/interfaces/form.interface';\nimport {IPermission} from '../../../../../src/app/interfaces/permission.interface';\nimport {IUser} from '../../../../../src/app/interfaces/user.interface';\nimport {IVenue} from '../../../../../src/app/interfaces/venue.interface';\nimport ApiService from '../utils/axios';\nimport {showModal, statusFooterButttonsModal} from '../utils/common';\nimport { ISalesChannel } from '../../../../../src/request/interfaces';\n\nexport interface IUsersState {\n  users: IUser[];\n  venues: IVenue[];\n  forms: IForm[];\n  channels: ISalesChannel[];\n  companies: ICompany[];\n  permissions: IPermission[];\n  loading: boolean;\n  tempUser: ITempUser;\n  source: CancelTokenSource | null;\n  searchText: string;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface ICancelRequest {\n  type: '/USERS/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/USERS/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/USERS/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/USERS/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IChangePage {\n  type: '/USERS/CHANGE_PAGE';\n  payload: {\n    page: number;\n  };\n}\n\nexport function changePageAction(page: number): IChangePage {\n  return {\n    type: '/USERS/CHANGE_PAGE',\n    payload: {\n      page\n    }\n  };\n}\n\nexport interface ITempUser {\n  _id?: string;\n  firstName?: string;\n  password?: string;\n  lastName?: string;\n  email?: string;\n  venue?: string | null;\n  venuesAccess: IVenue[];\n  userForms: IForm[];\n  settings: Dictionary<any>;\n  isAdmin: boolean;\n  isDriver: boolean;\n  preferred?: string | null;\n  userPermissions: IPermission[];\n  company: ICompany | null;\n}\n\ninterface IChangeTempUser {\n  type: '/USERS/CHANGE_TEMP_USER';\n  payload: {\n    user: ITempUser;\n  };\n  meta: {\n    debounce: {\n      time: number\n    }\n  };\n}\n\nexport function changeTempUserAction(user: ITempUser): IChangeTempUser {\n  return {\n    type: '/USERS/CHANGE_TEMP_USER',\n    payload: {\n      user\n    },\n    meta: {\n      debounce: {\n\n        time: 100\n      }\n    }\n  };\n}\n\ninterface ILoadUsers {\n  type: '/USERS/LOAD_USERS';\n  payload: {\n    users: any;\n    count: number;\n    pages: number\n  };\n}\n\nexport function loadUserAction(users: any, count: number, pages: number): ILoadUsers {\n  return {\n    type: '/USERS/LOAD_USERS',\n    payload: {\n      users,\n      count,\n      pages\n    }\n  };\n}\n\ninterface IChangeUser {\n  type: '/USERS/CHANGE_USER';\n  payload: {\n    user: IUser;\n  };\n}\n\nexport function changeUserAction(user: IUser): IChangeUser {\n  return {\n    type: '/USERS/CHANGE_USER',\n    payload: {\n      user\n    }\n  };\n}\n\nexport function updateUserAction() {\n  return (dispatch: Dispatch<UserReduxAction>, getState: () => {users: IUsersState}) => {\n    // dispatch(isLoadingAction(true));\n    const state = getState();\n    const {tempUser} = state.users;\n    const api: ApiService = new ApiService();\n    api.updteUser(tempUser)\n      .then((response: AxiosResponse) => {\n        statusFooterButttonsModal(false);\n        showModal(false);\n        dispatch(changeUserAction(response.data.user));\n        $(`#user-${tempUser._id}`).addClass('editing-item');\n        swal(response.data.message, {\n          icon: 'success'\n        });\n        setTimeout(() => {\n          $(`#user-${tempUser._id}`).removeClass('editing-item');\n        }, 1000);\n        dispatch(getUsersAction(state.users.pagination.page) as any);\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n        $(`#user-${tempUser._id}`).removeClass('editing-item');\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function createUserAction() {\n  return (dispatch: Dispatch<UserReduxAction>, getState: () => {users: IUsersState}) => {\n    dispatch(isLoadingAction(true));\n    const state = getState();\n    const {tempUser} = state.users;\n    const api: ApiService = new ApiService();\n    api.createUser(tempUser)\n      .then((response: AxiosResponse) => {\n        statusFooterButttonsModal(false);\n        showModal(false);\n        dispatch(getUsersAction(1) as any);\n        swal(response.data.message, {\n          icon: 'success'\n        });\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\ninterface IChangeSearchUser {\n  type: '/USERS/CHANGE_SEARCH';\n  payload: {\n    searchText: string;\n  };\n}\n\nexport function changeSearchUserAction(searchText: string): IChangeSearchUser {\n  return {\n    type: '/USERS/CHANGE_SEARCH',\n    payload: {\n      searchText\n    }\n  };\n}\n\ninterface ILoadVenuesUser {\n  type: '/USERS/LOAD_VENUES';\n  payload: {\n    venues: IVenue[];\n  };\n}\n\nexport function loadVenuesUserAction(venues: IVenue[]): ILoadVenuesUser {\n  return {\n    type: '/USERS/LOAD_VENUES',\n    payload: {\n      venues\n    }\n  };\n}\n\ninterface ILoadPermissionsUser {\n  type: '/USERS/LOAD_PERMISSIONS';\n  payload: {\n    permissions: IPermission[];\n  };\n}\n\nexport function loadPermissionsUserAction(permissions: IPermission[]): ILoadPermissionsUser {\n  return {\n    type: '/USERS/LOAD_PERMISSIONS',\n    payload: {\n      permissions\n    }\n  };\n}\n\ninterface ILoadFormsUser {\n  type: '/USERS/LOAD_FORMS';\n  payload: {\n    forms: IForm[];\n  };\n}\n\nexport function loadFormsUserAction(forms: IForm[]): ILoadFormsUser {\n  return {\n    type: '/USERS/LOAD_FORMS',\n    payload: {\n      forms\n    }\n  };\n}\n\ninterface ILoadCompaniesUser {\n  type: '/USERS/LOAD_COMPANIES';\n  payload: {\n    companies: ICompany[];\n  };\n}\n\nexport function loadCompaniesUserAction(companies: ICompany[]): ILoadCompaniesUser {\n  return {\n    type: '/USERS/LOAD_COMPANIES',\n    payload: {\n      companies\n    }\n  };\n}\n\ninterface ILoadChannelsUser {\n  type: '/USERS/LOAD_CHANNELS';\n  payload: {\n    channels: ISalesChannel[];\n  };\n}\n\nexport function loadChannelsUserAction(channels: ISalesChannel[]): ILoadChannelsUser {\n  return {\n    type: '/USERS/LOAD_CHANNELS',\n    payload: {\n      channels\n    }\n  };\n}\n\nexport function getUsersAction(nextPage: number, search?: string) {\n  return (dispatch: Dispatch<UserReduxAction>, getState: () => {users: IUsersState}) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n\n    if (nextPage && nextPage !== state.users.pagination.page) {\n      dispatch(isLoadingAction(true));\n    }\n    // get venues and permissions\n\n    dispatch(cancelRequestAction(api.getSource()));\n    const page = nextPage ? nextPage : state.users.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n\n    Axios.all([\n      api.getUsers(page, state.users.searchText),\n      api.getCompanies(1, 200),\n      api.getVenues({ page: 1, pageSize: 200, noPopulate: false }),\n      api.getSalesChannel({ page: 1, pageSize: 200 }),\n      api.getPermissions(1, 200),\n      api.getForms(1, 200)\n    ])\n      .then(Axios.spread((users, companies, venues, channeles, permissions, forms) => {\n        dispatch(loadUserAction(users.data.results, users.data.count, users.data.pages));\n        dispatch(loadCompaniesUserAction(companies.data.results));\n        dispatch(loadChannelsUserAction(channeles.data.results));\n        dispatch(loadVenuesUserAction(venues.data.results));\n        dispatch(loadPermissionsUserAction(permissions.data.results));\n        dispatch(loadFormsUserAction(forms.data.results));\n        dispatch(isLoadingAction(false));\n      }))\n      .catch((err: AxiosError): void => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n\n\n\n      // .then((response: AxiosResponse): void => {\n      //   dispatch(loadUserAction(response.data.results, response.data.count, response.data.pages));\n      //   dispatch(isLoadingAction(false));\n      // })\n      // .catch((err: AxiosError): void => {\n      //   // if the request is canceled\n      //   if (Axios.isCancel(err)) {\n      //     dispatch(isLoadingAction(true));\n      //   } else {\n      //     dispatch(isLoadingAction(false));\n      //     api.errorHandler(err);\n      //   }\n      // });\n  };\n}\n\ninterface IDeleteUser {\n  type: '/USERS/DELETE_USER';\n  payload: {\n    id: string;\n  };\n}\n\nexport function removeUserAction(id: string): IDeleteUser {\n  return {\n    type: '/USERS/DELETE_USER',\n    payload: {\n      id\n    }\n  };\n}\n\nexport function deleteUserAction(id: string) {\n  return (dispatch: Dispatch<UserReduxAction>) => {\n    const api: ApiService = new ApiService();\n    api.deleteUser(id)\n      .then((response: AxiosResponse): void => {\n        swal(response.data.message, {\n          icon: 'success'\n        });\n        // effect when removing user\n        $(`#user-${id}`)\n          .addClass('deleted-item');\n        setTimeout(() => {\n          dispatch(removeUserAction(id));\n        }, 1000);\n      })\n      .catch((err: AxiosError): void => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport type UserReduxAction =\n  IIsLoading |\n  ILoadUsers |\n  IChangePage |\n  IDeleteUser |\n  IChangeSearchUser |\n  ICancelRequest |\n  IChangeTempUser |\n  ILoadChannelsUser |\n  IChangeUser |\n  ILoadVenuesUser |\n  ILoadPermissionsUser |\n  ILoadFormsUser |\n  ILoadCompaniesUser;\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {IUser} from '../../../../../../src/app/interfaces/user.interface';\nimport {IUsersState} from '../../actions/users.actions';\n\ninterface IPropsType {\n  users: IUsersState;\n  user?: IUser;\n  changeTempUser(user: any): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  type: string;\n}\n\nclass UserFormChangePasswordView extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null,\n    type: 'password'\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.changeType = this.changeType.bind(this);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {changeTempUser} = this.props;\n    const {tempUser} = this.props.users;\n\n    return (\n      <div className=\"row\">\n        <div className=\"col-md-12\">\n          <div className=\"form-group\">\n            <label>Nueva Contraseña</label>\n            <div className=\"input-group\">\n              <input\n                type={this.state.type}\n                className=\"form-control\"\n                defaultValue={tempUser ? tempUser.password : undefined}\n                onChange={(e: React.ChangeEvent<HTMLInputElement>) => changeTempUser({password: e.target.value})}\n              />\n              <span className=\"input-group-addon pointer\" onClick={this.changeType}>\n                <i className={`fa ${this.state.type === 'text' ? 'fa-eye-slash' : 'fa-eye'}`} />\n              </span>\n            </div>\n          </div>\n        </div>\n      </div>\n    );\n  }\n\n  private changeType() {\n    this.setState({\n      type: this.state.type === 'text' ? 'password' : 'text'\n    });\n  }\n}\n\nconst mapStateToProps = (state: { users: IUsersState }) => {\n  return {\n    users: state.users\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(UserFormChangePasswordView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {ICompany} from '../../../../../../src/app/interfaces/company.interface';\nimport {IForm} from '../../../../../../src/form/interfaces/form.interface';\nimport {IPermission} from '../../../../../../src/app/interfaces/permission.interface';\nimport {IUser} from '../../../../../../src/app/interfaces/user.interface';\nimport {IVenue} from '../../../../../../src/app/interfaces/venue.interface';\nimport {IUsersState} from '../../actions/users.actions';\nimport {IWindow} from '../../interfaces/window';\nimport Checkbox from '../Utils/CheckBox';\nimport {hasPermission} from '../../utils/common';\n\ninterface IPropsType {\n  users: IUsersState;\n  venues: IVenue[];\n  forms: IForm[];\n  permissions: IPermission[];\n  companies: ICompany[];\n  user?: IUser;\n  create: boolean;\n  changeTempUser(user: any): void;\n}\ndeclare let window: IWindow;\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass UserFormView extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.addPermission = this.addPermission.bind(this);\n    this.deletePermission = this.deletePermission.bind(this);\n    this.addVenueAccess = this.addVenueAccess.bind(this);\n    this.deleteVenueAccess = this.deleteVenueAccess.bind(this);\n    this.changeIsAdmin = this.changeIsAdmin.bind(this);\n    this.changeIsDriver = this.changeIsDriver.bind(this);\n    this.addForm = this.addForm.bind(this);\n    this.deleteForm = this.deleteForm.bind(this);\n  }\n\n  public componentDidMount() {\n    const {changeTempUser, companies} = this.props;\n    const {tempUser} = this.props.users;\n    const chosenOptions = {\n      no_results_text: 'Sin resultados para:'\n    };\n    ($('#id-forms') as any).chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n        this.addForm(e.target.value);\n      });\n    ($('#id-form-default') as any).chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n        changeTempUser({preferred: e.target.value});\n      });\n    ($('#id-venue') as any).chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n        changeTempUser({venue: e.target.value});\n      });\n    ($('#id-company') as any).chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n        changeTempUser({\n          company: companies.find((company) => (\n            company._id === e.target.value\n          ))\n        });\n      });\n    ($('#id-channel') as any).chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n        changeTempUser({\n          settings: {\n            ...tempUser.settings,\n            defaultChannel: e.target.value\n          }\n        });\n      });\n    ($('#id-permissions') as any).chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n          this.addPermission(e.target.value);\n        });\n    ($('#id-venues-access') as any).chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n        this.addVenueAccess(e.target.value);\n      });\n\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  componentDidUpdate() {\n    $('#id-forms').trigger('chosen:updated');\n    $('#id-form-default').trigger('chosen:updated');\n    $('#id-venue').trigger('chosen:updated');\n    $('#id-permissions').trigger('chosen:updated');\n    $('#id-company').trigger('chosen:updated');\n    $('#id-channel').trigger('chosen:updated');\n    $('#id-venues-access').trigger('chosen:updated');\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {changeTempUser, venues, permissions, forms, create, companies} = this.props;\n    const {tempUser, channels} = this.props.users;\n    const userPermissions: IPermission[] = [];\n    const selectPermissions: IPermission[] = [];\n    const userForms: IForm[] = [];\n    const selectForms: IForm[] = [];\n    const idsUserPermissions = tempUser && tempUser.userPermissions.length ? tempUser.userPermissions.map((userPermission) => userPermission._id) : [];\n    const idsUserVenueAccess = tempUser && tempUser.venuesAccess.length ? tempUser.venuesAccess.map((venue) => venue._id) : [];\n    const idsUserForms = tempUser && tempUser.userForms.length ? tempUser.userForms.map((userForm) => userForm._id) : [];\n    permissions.forEach((permission) => {\n      if (idsUserPermissions.includes(permission._id)) {\n        userPermissions.push(permission);\n      } else {\n        selectPermissions.push(permission);\n      }\n    });\n    forms.forEach((form) => {\n      if (idsUserForms.includes(form._id)) {\n        userForms.push(form);\n      } else {\n        selectForms.push(form);\n      }\n    });\n    return (\n      <React.Fragment>\n        <ul className=\"nav nav-tabs\" style={{marginBottom: '15px'}}>\n          <li className=\"active\"><a data-toggle=\"tab\" href=\"#general\">General</a></li>\n          {\n            window.user.isAdmin || (hasPermission(window.user, 'changeTeamPermissions') && !this.props.user?.isAdmin)  ?\n              <li><a data-toggle=\"tab\" href=\"#permissions\">Permisos</a></li>\n              : null\n          }\n          <li><a data-toggle=\"tab\" href=\"#access\">Accesos</a></li>\n          <li ><a data-toggle=\"tab\" href=\"#request\">Solicitudes</a></li>\n        </ul>\n        <div className=\"tab-content\">\n          <div id=\"general\" className=\"tab-pane fade in active\">\n            <div className=\"row\">\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>Nombres</label>\n                  <input\n                    type=\"text\"\n                    name=\"firstName\"\n                    className=\"form-control\"\n                    maxLength={50}\n                    defaultValue={tempUser ? tempUser.firstName : undefined}\n                    onChange={(e: React.ChangeEvent<HTMLInputElement>) => changeTempUser({firstName: e.target.value})}\n                  />\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>Apellidos</label>\n                  <input\n                    type=\"text\"\n                    name=\"lastName\"\n                    className=\"form-control\"\n                    maxLength={50}\n                    defaultValue={tempUser ? tempUser.lastName : undefined}\n                    onChange={(e: React.ChangeEvent<HTMLInputElement>) => changeTempUser({lastName: e.target.value})}\n                  />\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>Email</label>\n                  <input\n                    type=\"email\"\n                    name=\"email\"\n                    disabled={!create}\n                    className=\"form-control\"\n                    maxLength={80}\n                    defaultValue={tempUser ? tempUser.email : undefined}\n                    onChange={(e: React.ChangeEvent<HTMLInputElement>) => changeTempUser({email: e.target.value})}\n                  />\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label htmlFor=\"id-company\">Empresa</label>\n                  <select\n                    className=\"chosen-select form-control\"\n                    id=\"id-company\"\n                    name=\"venue\"\n                    defaultValue={tempUser && tempUser.company ? tempUser.company._id : undefined}\n                    onChange={undefined}\n                    data-placeholder={'Seleccione...'}\n                  >\n                    <option value=\"\" />\n                    {\n                      companies.map((company) => (\n                        <option key={company._id} value={company._id}>{company.name}</option>\n                      ))\n                    }\n                  </select>\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label htmlFor=\"id-venue\">Sucursal</label>\n                  <select\n                    className=\"chosen-select form-control\"\n                    id=\"id-venue\"\n                    name=\"venue\"\n                    defaultValue={tempUser && tempUser.venue ? tempUser.venue : undefined}\n                    onChange={undefined}\n                    data-placeholder={'Seleccione...'}\n                  >\n                    <option value=\"\" />\n                    {\n                      venues\n                        .filter((venue) => (\n                          venue.company && tempUser.company && tempUser.company._id === venue.company._id\n                        ))\n                        .map((venue) => (\n                          <option key={venue._id} value={venue._id}>{venue.name}</option>\n                        ))\n                    }\n                  </select>\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>Formularios</label>\n                  <select\n                    id=\"id-forms\"\n                    className=\"chosen-select form-control\"\n                    style={{minWidth: '200px'}}\n                    onChange={undefined}\n                    data-placeholder={'Seleccione...'}\n                  >\n                    <option value=\"\" />\n                    {\n                      selectForms.map((form) => {\n                        return (\n                          <option key={form._id} value={form._id}>{form.name}</option>\n                        );\n                      })\n                    }\n                  </select>\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <table className=\"table table-striped\">\n                  <thead>\n                  <tr>\n                    <th style={{width: '90%'}}>Name</th>\n                    <th style={{width: '10%'}}/>\n                  </tr>\n                  </thead>\n                  <tbody>\n                  {\n                    userForms.length ? userForms.map((form: any) => {\n                      return (\n                        <tr key={form._id}>\n                          <td>{form.name}</td>\n                          <td\n                            className=\"text-center text-red pointer\"\n                            onClick={() => this.deleteForm(form._id)}\n                          >\n                            <i className=\"fa fa-minus-circle\"/>\n                          </td>\n                        </tr>\n                      );\n                      }) :\n                      <tr>\n                        <td colSpan={2}>Aún no se han seleccionado permisos.</td>\n                      </tr>\n                  }\n                  </tbody>\n                </table>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>Formulario por defecto</label>\n                  <select\n                    id=\"id-form-default\"\n                    className=\"chosen-select form-control\"\n                    style={{minWidth: '200px'}}\n                    defaultValue={tempUser && tempUser.preferred ? tempUser.preferred : undefined}\n                    onChange={undefined}\n                    data-placeholder={'Seleccione...'}\n                  >\n                    <option value=\"\" />\n                    {\n                      userForms.map((form) => {\n                        return (\n                          <option key={form._id} value={form._id}>{form.name}</option>\n                        );\n                      })\n                    }\n                  </select>\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"checkbox\">\n                  <Checkbox\n                    active={tempUser && tempUser.isDriver}\n                    action={this.changeIsDriver}\n                    classes=\"icheck-in-checkbox\"\n                    style={{marginTop: '-4px', marginRight: '5px'}}\n                  />\n                  Es Conductor\n                </div>\n              </div>\n              {\n                window.user.isAdmin ?\n                  <div className=\"col-md-12\">\n                    <div className=\"checkbox\">\n                      <Checkbox\n                        active={tempUser && tempUser.isAdmin}\n                        action={this.changeIsAdmin}\n                        classes=\"icheck-in-checkbox\"\n                        style={{marginTop: '-4px', marginRight: '5px'}}\n                      />\n                      Es ADMIN\n                    </div>\n                  </div>\n                  : null\n              }\n            </div>\n          </div>\n          {\n            window.user.isAdmin || (hasPermission(window.user, 'changeTeamPermissions') && !this.props.user?.isAdmin) ?\n              <div id=\"permissions\" className=\"tab-pane fade\">\n                <div className=\"row\">\n                  <div className=\"col-md-12\">\n                    <div className=\"form-group\">\n                      <label>Permisos</label>\n                      <select\n                        id=\"id-permissions\"\n                        className=\"chosen-select form-control\"\n                        style={{minWidth: '200px'}}\n                        data-placeholder={'Seleccione...'}\n                      >\n                        <option value=\"\"/>\n                        {\n                          selectPermissions.map((permission) => {\n                            return (\n                              <option key={permission._id} value={permission._id}>{permission.name}</option>\n                            );\n                          })\n                        }\n                      </select>\n                    </div>\n                  </div>\n                  <div className=\"col-md-12\">\n                    <table className=\"table table-striped\">\n                      <thead>\n                      <tr>\n                        <th style={{width: '20%'}}>Code</th>\n                        <th style={{width: '70%'}}>Name</th>\n                        <th style={{width: '10%'}}/>\n                      </tr>\n                      </thead>\n                      <tbody>\n                      {\n                        userPermissions.length ?\n                          userPermissions.map((permission: any) => {\n                            return (\n                              <tr key={permission._id}>\n                                <td>{permission.codeName}</td>\n                                <td>{permission.name}</td>\n                                <td className=\"text-center text-red pointer\" onClick={() => this.deletePermission(permission._id)}>\n                                  <i className=\"fa fa-minus-circle\"/>\n                                </td>\n                              </tr>\n                            );\n                          })\n                          : <tr>\n                            <td colSpan={3}>Aún no se han seleccionado permisos.</td>\n                          </tr>\n                      }\n                      </tbody>\n                    </table>\n                  </div>\n                </div>\n              </div>\n              : null\n          }\n          <div id=\"access\" className=\"tab-pane fade\">\n            <div className=\"row\">\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>Sucursales adicionales</label>\n                  <select\n                    id=\"id-venues-access\"\n                    className=\"chosen-select form-control\"\n                    style={{minWidth: '200px'}}\n                    onChange={undefined}\n                    data-placeholder={'Seleccione...'}\n                  >\n                    <option value=\"\" />\n                    {\n                      venues\n                        .filter((venue) => (\n                          !idsUserVenueAccess.includes(venue._id) && venue._id !== tempUser.venue)\n                        )\n                        .map((venue) => {\n                          return (\n                            <option key={venue._id} value={venue._id}>\n                              {venue.name}{venue.company ? ` - ${venue.company.name}` : ''}\n                            </option>\n                          );\n                        })\n                    }\n                  </select>\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <table className=\"table table-striped\">\n                  <thead>\n                  <tr>\n                    <th style={{width: '90%'}}>Sucursal</th>\n                    <th style={{width: '10%'}}/>\n                  </tr>\n                  </thead>\n                  <tbody>\n                    {\n                      tempUser.venue ?\n                        venues\n                          .filter((venue: any) => (venue._id === tempUser.venue))\n                          .map((venue: any) => (\n                            <tr key={venue._id} className=\"bg-aqua-active\">\n                              <td colSpan={2}>{venue.name}{venue.company ? ` - ${venue.company.name}` : ''}</td>\n                            </tr>\n                          ))\n                        : null\n                    }\n                    {\n                      tempUser.venuesAccess.length ?\n                        tempUser.venuesAccess\n                          .filter((venue: any) => (venue._id !== tempUser.venue))\n                          .map((venue: any) => {\n                          return (\n                            <tr key={venue._id}>\n                              <td>{venue.name}{venue.company ? ` - ${venue.company.name}` : ''}</td>\n                              <td className=\"text-center text-red pointer\" onClick={() => this.deleteVenueAccess(venue._id)}><i\n                                className=\"fa fa-minus-circle\"/></td>\n                            </tr>\n                          );\n                        }) :\n                        <tr>\n                          <td colSpan={2}>Aún no se han seleccionado sucursales adicionales.</td>\n                        </tr>\n                    }\n                  </tbody>\n                </table>\n              </div>\n            </div>\n          </div>\n          <div id=\"request\" className=\"tab-pane fade\">\n            <div className=\"row\">\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label htmlFor=\"id-channel\">Canal</label>\n                  <select\n                    className=\"chosen-select form-control\"\n                    id=\"id-channel\"\n                    name=\"channel\"\n                    defaultValue={tempUser?.settings?.defaultChannel}\n                    onChange={undefined}\n                    data-placeholder={'Seleccione...'}\n                  >\n                    <option value=\"\" />\n                    {\n                      channels.map((channel) => (\n                        <option key={channel._id} value={channel._id}>{channel.name}</option>\n                      ))\n                    }\n                  </select>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </React.Fragment>\n    );\n  }\n\n  private changeIsAdmin() {\n    const {isAdmin} = this.props.users.tempUser;\n    this.props.changeTempUser({isAdmin: !isAdmin});\n  }\n\n  private changeIsDriver() {\n    const {isDriver} = this.props.users.tempUser;\n    this.props.changeTempUser({isDriver: !isDriver});\n  }\n\n  private addVenueAccess(id: string) {\n    const {changeTempUser} = this.props;\n    const {tempUser} = this.props.users;\n    const {venues} = this.props;\n    const findVenue = venues.find((venue) => venue._id === id);\n    if (findVenue) {\n      changeTempUser({\n        venuesAccess: [findVenue, ...tempUser.venuesAccess]\n      });\n    }\n  }\n\n  private deleteVenueAccess(id: string) {\n    const {changeTempUser} = this.props;\n    const {tempUser} = this.props.users;\n    changeTempUser({\n      venuesAccess: tempUser ? tempUser.venuesAccess.filter((venue) => venue._id !== id) : []\n    });\n  }\n\n  private addPermission(id: string) {\n    const {changeTempUser} = this.props;\n    const {tempUser} = this.props.users;\n    const {permissions} = this.props;\n    const findPermision = permissions.find((permission) => permission._id === id);\n    if (findPermision) {\n      changeTempUser({\n        userPermissions: [findPermision, ...tempUser.userPermissions]\n      });\n    }\n  }\n\n  private deletePermission(id: string) {\n    const {changeTempUser} = this.props;\n    const {tempUser} = this.props.users;\n    changeTempUser({\n      userPermissions: tempUser ? tempUser.userPermissions.filter((permission) => permission._id !== id) : []\n    });\n  }\n\n  private addForm(id: string) {\n    const {changeTempUser} = this.props;\n    const {tempUser} = this.props.users;\n    const {forms} = this.props;\n    const findForm = forms.find((form) => form._id === id);\n    if (findForm) {\n      changeTempUser({\n        userForms: [findForm, ...tempUser.userForms]\n      });\n    }\n  }\n\n  private deleteForm(id: string) {\n    const {changeTempUser} = this.props;\n    const {tempUser} = this.props.users;\n    changeTempUser({\n      userForms: tempUser ? tempUser.userForms.filter((form) => form._id !== id) : []\n    });\n  }\n}\n\nconst mapStateToProps = (state: { users: IUsersState }) => {\n  return {\n    users: state.users\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(UserFormView);\n","import { default as Axios } from 'axios';\nimport * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport * as swal from 'sweetalert';\nimport * as mapboxgl from 'mapbox-gl';\nimport ApiService from '../../utils/axios';\nimport { IBaseVenue, IVenue } from '../../../../../../src/app/interfaces/venue.interface';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport {\n  changeSearchAction,\n  changeTempVenueAction,\n  createVenueAction,\n  deleteVenueAction,\n  getVenuesAction,\n  IVenuesState,\n  updateVenueAction,\n  VenueReduxAction\n} from '../../actions/venues.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { hasPermission } from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport VenueFormView from './VenueFormView';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport { debounce } from 'throttle-debounce';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\n// var mapboxgl = require('mapbox-gl/dist/mapbox-gl.js');\n\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<VenueReduxAction>;\n  venues: IVenuesState;\n\n  getVenuesAction(page: number): VenueReduxAction;\n  createVenueAction(): VenueReduxAction;\n  updateVenueAction(): VenueReduxAction;\n  deleteVenueAction(id?: string): VenueReduxAction;\n  changeTempVenueAction(venue: IBaseVenue): VenueReduxAction;\n  changeSearchAction(searchText: string): VenueReduxAction;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass VenuesListView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  private socket: Socket;\n  private map: any;\n  readonly state = {\n    error: null,\n    exporing: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de sucursales';\n    this.changePage = this.changePage.bind(this);\n    this.createVenue = this.createVenue.bind(this);\n    this.processCreateVenue = this.processCreateVenue.bind(this);\n    this.updateVenue = this.updateVenue.bind(this);\n    this.processUpdateVenue = this.processUpdateVenue.bind(this);\n    this.deleteVenue = this.deleteVenue.bind(this);\n    this.onChangeTab = this.onChangeTab.bind(this);\n    this.exportExcel = this.exportExcel.bind(this);\n    this.onChangeSearch = this.onChangeSearch.bind(this);\n    this.debounceOnChangeSearch = debounce(300, this.debounceOnChangeSearch);\n  }\n\n  public componentWillMount(): void {\n    const {pagination} = this.props.venues;\n    this.props.getVenuesAction(pagination.page);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {token: (window.user as any).token}\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {room: `venue-list-${window.user.team._id}`});\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update && data.updatedBy !== window.user._id) {\n        const {pagination} = this.props.venues;\n        this.props.getVenuesAction(pagination.page);\n      }\n    });\n  }\n\n  public exportExcel() {\n    this.setState({\n      exporing: true\n    });\n    this.trackClick(\"Exportar\");\n    const api: ApiService = new ApiService();\n    const instance = api.getInstance();\n    instance.defaults.responseType = 'blob';\n    instance\n      .get(`/settings/venues/export-access/`)\n      .then((response) => {\n        const blob = new Blob([response.data], {\n          type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'\n        });\n        const fileName = `${moment().format('YYYYMMDD')}-acceso-sucursales.xlsx`;\n        if (typeof window.navigator.msSaveBlob !== 'undefined') {\n          // IE workaround for \"HTML7007: One or more blob URLs were\n          // revoked by closing the blob for which they were created.\n          // These URLs will no longer resolve as the data backing\n          // the URL has been freed.\"\n          window.navigator.msSaveBlob(blob, fileName);\n        } else {\n          const blobURL = URL.createObjectURL(blob);\n          const tempLink = document.createElement('a');\n          tempLink.style.display = 'none';\n          tempLink.href = blobURL;\n          tempLink.setAttribute('download', fileName);\n          // Safari thinks _blank anchor are pop ups. We only want to set _blank\n          // target if the browser does not support the HTML5 download attribute.\n          // This allows you to download files in desktop safari if pop up blocking\n          // is enabled.\n          if (typeof tempLink.download === 'undefined') {\n            tempLink.setAttribute('target', '_blank');\n          }\n          this.setState({\n            exporing: false\n          });\n          document.body.appendChild(tempLink);\n          tempLink.click();\n          document.body.removeChild(tempLink);\n          URL.revokeObjectURL(blobURL);\n        }\n      })\n      .catch((err) => {\n        this.setState({\n          exporing: false\n        });\n        if (!Axios.isCancel(err)) {\n          swal('Exportar usuarios', 'Ha ocurrido un error al general el excel.', 'error');\n        }\n      });\n  }\n\n  private onChangeTab() {\n\n    const {venues} = this.props.venues;\n\n    const geojson = {\n      type: 'FeatureCollection',\n      features: venues.map((venue: any) => {\n        return {\n          type: 'Feature',\n          geometry: {\n            type: 'Point',\n            coordinates: [venue.lng, venue.lat]\n          },\n          properties: {\n            title: 'Sucursal',\n            name: venue.name,\n            logo: venue.company.marker && venue.company.marker.hasOwnProperty('url') ? `url(\"${venue.company.marker.url}\")` : 'url(\"/static/images/files/pin_osa.svg\")'\n          }\n        }\n      })\n    };\n\n    const $map = this.map;\n    $('#map').css('width', $('#tab_2').width() as any);\n    const bounds = new mapboxgl.LngLatBounds();\n    geojson.features.forEach((marker) => {\n\n      // create a HTML element for each feature\n      const el: HTMLDivElement = document.createElement('div');\n      // here set class use in the marker\n      // el.className = 'marker';\n      el.style.backgroundImage = marker.properties.logo;\n      el.style.backgroundSize = 'cover';\n      el.style.width = '50px';\n      el.style.height = '50px';\n      el.style.borderRadius = '50p%';\n      el.style.cursor = 'pointer%';\n\n      // make a marker for each feature and add to the map\n      if(Math.abs(marker.geometry.coordinates[0]) > 0.1) // skip sucursales sin lat, lng\n      {\n        new mapboxgl.Marker(el)\n          .setLngLat((marker.geometry.coordinates as [number, number]))\n          .setPopup(new mapboxgl.Popup({offset: 25}).setHTML(`<p>${marker.properties.name}</p>`))\n          .addTo($map);\n\n        bounds.extend((marker.geometry.coordinates as [number, number]));\n      }\n    });\n    $map.resize();\n    $map.fitBounds(bounds);\n\n  }\n\n  public componentDidMount() {\n    // mapboxgl.accessToken = 'pk.eyJ1IjoicmliYXJyYWNsIiwiYSI6ImNqems3dW85bTAwZmUzbnF0a2xubnl5ejUifQ.tfPmGSbHYdh2nMA6Fmxcxw';\n    this.map = new mapboxgl.Map({\n      accessToken: 'pk.eyJ1IjoicmliYXJyYWNsIiwiYSI6ImNqems3dW85bTAwZmUzbnF0a2xubnl5ejUifQ.tfPmGSbHYdh2nMA6Fmxcxw',\n      container: 'map',\n      style: 'mapbox://styles/mapbox/streets-v11',\n      center: [-70.593536, -33.509243],\n      zoom: 10,\n      trackResize: true\n    });\n    this.map.addControl(new mapboxgl.NavigationControl(), 'bottom-right');\n\n    $('a[href=\\'#tab_2\\']').on('shown.bs.tab', () => {\n      this.onChangeTab();\n    });\n  }\n\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if(this.props.venues.pagination !== prevProps.venues.pagination){\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.venues.source) {\n      this.props.venues.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {exporing} = this.state;\n    const {loading, venues, pagination, searchText} = this.props.venues;\n    return (\n      <AppContainer title=\"\" cMenu=\"10\" cSubMenu=\"10.4\" cAction=\"Listado\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Sucursales <small>{pagination.count}</small></h3>\n              <div className=\"box-tools pull-right\">\n                {\n                  hasPermission(window.user, 'addVenue') ?\n                    <button className=\"btn btn-sm btn-success\" onClick={this.createVenue}><i className=\"fa fa-plus\" />  Agregar</button>\n                    : null\n                }\n                <button\n                  className=\"btn btn-sm btn-primary  hidden-xs\"\n                  onClick={this.exportExcel}\n                  disabled={exporing}\n                  style={{marginLeft: '5px'}}\n                >\n                  {\n                    exporing ?\n                      <React.Fragment>\n                        <i className=\"fa fa-spin fa-spinner\"/> Exportando\n                      </React.Fragment>\n                      : <React.Fragment>\n                        <i className=\"fa fa-fw fa-download\"/> Exportar\n                      </React.Fragment>\n                  }\n                </button>\n              </div>\n            </div>\n            <div className=\"box-body no-padding\">\n              <div className=\"nav-tabs-custom\">\n                <ul className=\"nav nav-tabs\">\n                  <li className=\"active\">\n                    <a href=\"#tab_1\" data-toggle=\"tab\" aria-expanded=\"true\">Listado</a>\n                  </li>\n                  <li>\n                    <a href=\"#tab_2\" data-toggle=\"tab\" aria-expanded=\"true\">Mapa</a>\n                  </li>\n                </ul>\n                <div className=\"tab-content\">\n                  <div className='tab-pane active' id='tab_1'>\n                    <div className='box-body table-responsive no-padding'>\n                      <div className='row'>\n                        <div className='col-md-offset-8 col-md-4'>\n                          <div className='input-group input-group-sm'\n                               style={{ padding: '10px' }}\n                          >\n                            <input\n                              type='text'\n                              value={searchText}\n                              className='form-control pull-right'\n                              onChange={this.onChangeSearch}\n                              placeholder='Buscar' />\n                            <div className='input-group-btn'>\n                              <button className='btn btn-default'><i className='fa fa-search' /></button>\n                            </div>\n                          </div>\n                        </div>\n                      </div>\n                      <table className='table table-andes table-striped'>\n                        <thead>\n                        <tr>\n                          <th style={{width: '40%'}} className=\"middle\">Nombre</th>\n                          <th style={{width: '10%'}} className=\"middle\">Código</th>\n                          <th style={{width: '10%'}} className=\"middle-center hidden-xs\">Ubicación</th>\n                          <th style={{width: '10%'}} className=\"middle-center hidden-xs\">Distribuidor</th>\n                          <th style={{width: '10%'}} className=\"middle\">Asignaciones</th>\n                          <th style={{width: '20%'}} className=\"middle hidden-xs\">Modificado</th>\n                          {\n                            hasPermission(window.user, 'changeVenue') ?\n                              <th style={{width: '1%'}} className=\"width-10\"/> : null\n                          }\n                          {\n                            hasPermission(window.user, 'deleteVenue') ?\n                              <th style={{width: '1%'}} className=\"width-10\"/> : null\n                          }\n                        </tr>\n                        </thead>\n                        <tbody>\n                        {\n                          venues.map((venue: IVenue) => {\n                            const canDelete = venue.users && venue.users.length === 0 && venue.participants && venue.participants.length === 0;\n                            return (\n                              <tr\n                                key={venue._id}\n                                id={`venue-${venue._id}`}\n                                className={'background-transition'}\n                              >\n                                <td className=\"middle\">{venue.name}<br/>\n                                  {\n                                    venue.company ? <span className={'text-sm text-muted'}>{venue.company.name}</span> : null\n                                  }\n                                </td>\n                                <td className=\"middle-center\">{venue.code}</td>\n                                <td className=\"middle-center\">{venue.lat}, {venue.lng}</td>\n                                <td className=\"middle-center  hidden-xs\">\n                                  {\n                                    venue.type === 'distributor' ?\n                                      <i className=\"fa fa-check-circle text-green\"/>\n                                      : <i className=\"fa fa-times-circle text-blue\"/>\n                                  }\n                                </td>\n                                <td className=\"text-sm\">\n                                  Usuarios: {venue.users ? venue.users.length : 0}<br/>\n                                  Revisiones: {venue.participants ? venue.participants.length : 0}<br/>\n                                </td>\n                                <td className=\"middle hidden-xs\">\n                                  {\n                                    moment(venue.updatedAt).format('LLL')\n                                  }\n                                </td>\n                                {\n                                  hasPermission(window.user, 'changeVenue') ?\n                                    <td\n                                      className=\"middle text-blue pointer\"\n                                      onClick={() => this.updateVenue(venue)}>\n                                      <i className=\"fa fa-pencil\"/>\n                                    </td> : null\n                                }\n                                {\n                                  hasPermission(window.user, 'deleteVenue') ?\n                                    <td\n                                      className={canDelete ? 'middle text-red pointer' : 'middle text-muted not-allowed'}\n                                      onClick={canDelete ? () => this.deleteVenue(venue) : undefined}\n                                    >\n                                      <i className=\"fa fa-minus-circle\"/>\n                                    </td> : null\n                                }\n                              </tr>\n                            );\n                          })\n                        }\n                        </tbody>\n                      </table>\n                    </div>\n                  </div>\n                  <div className=\"tab-pane\" id=\"tab_2\">\n                    <div\n                      id=\"map\"\n                      style={{\n                        position: 'relative',\n                        width: '100%',\n                        height: '60vh'\n                      }}\n                    />\n                  </div>\n                </div>\n              </div>\n            </div>\n            {\n              pagination.pages > 1 &&\n              <div className=\"box-footer text-right\">\n                <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n              </div>\n            }\n            {\n              loading &&\n              <div className=\"overlay\">\n                <i className=\"fa fa-spinner fa-spin text-purple\"/>\n              </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n\n  private onChangeSearch(e: React.ChangeEvent<HTMLInputElement>): void {\n    e.preventDefault();\n    const value = e.target.value.trim();\n    this.props.changeSearchAction(value);\n    this.debounceOnChangeSearch();\n  }\n\n  private debounceOnChangeSearch(): void {\n    this.props.getVenuesAction(1);\n  }\n\n  private createVenue(): void {\n    this.props.changeTempVenueAction({\n      _id: '',\n      lat: 0,\n      lng: 0,\n      name: '',\n      code: '',\n      abbreviation: '',\n      type: 'receiver',\n      sendTo: [],\n      sendToDays: [],\n      receiveFrom: [],\n      shippingCarriers: [],\n      responsible: [],\n      shippingMaxDays: 5,\n      receptionCarriers: []\n    });\n    this.props.loadDataAction(\n      'Agregar Sucursal',\n      <VenueFormView/>,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processCreateVenue}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processCreateVenue(): void {\n    const {tempVenue} = this.props.venues;\n    if (!tempVenue.name || !tempVenue.name.trim()) {\n      swal!('Agregar sucursal', 'El nombres es requerido', 'error');\n    } else if (!tempVenue.company || !tempVenue.company._id) {\n      swal!('Agregar sucursal', 'La empresa es requerida', 'error');\n    } else {\n      this.props.createVenueAction();\n    }\n  }\n\n  private updateVenue(venue: IVenue): void {\n    this.props.changeTempVenueAction({\n      _id: venue._id,\n      name: venue.name,\n      code: venue.code ?? '',\n      abbreviation: venue.abbreviation ?? '',\n      lat: venue.lat,\n      lng: venue.lng,\n      company: venue.company,\n      region: venue.region,\n      type: venue.type ? venue.type : 'receiver',\n      sendTo: venue.sendTo ? venue.sendTo : [],\n      sendToDays: venue.sendToDays ? venue.sendToDays : [],\n      shippingMaxDays : venue.shippingMaxDays,\n      receiveFrom: venue.receiveFrom ? venue.receiveFrom : [],\n      responsible: venue.responsible ? venue.responsible : [],\n      shippingCarriers: venue.shippingCarriers ? venue.shippingCarriers : [],\n      receptionCarriers: venue.receptionCarriers ? venue.receptionCarriers : []\n    });\n    this.props.loadDataAction(\n      'Editar Sucursal',\n      <VenueFormView update={true} />,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processUpdateVenue}>Editar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processUpdateVenue(): void {\n    const {tempVenue} = this.props.venues;\n    if (!tempVenue.name || !tempVenue.name.trim()) {\n      swal!('Editar sucursal', 'El nombres es requerido', 'error');\n    } else if (!tempVenue.company || !tempVenue.company._id) {\n      swal!('Editar sucursal', 'La empresa es requerida', 'error');\n    } else {\n      this.props.updateVenueAction();\n    }\n  }\n\n  private deleteVenue(venue: IVenue): void {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar la sucursal ${venue.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteVenueAction(venue._id);\n      }\n    });\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    this.props.getVenuesAction(page);\n  }\n}\n\nconst mapStateToProps = (state: { venues: IVenuesState }) => {\n  return {\n    venues: state.venues\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getVenuesAction: (page: number) => dispatch(getVenuesAction(page)),\n    createVenueAction: () => dispatch(createVenueAction()),\n    updateVenueAction: () => dispatch(updateVenueAction()),\n    deleteVenueAction: (id: string) => dispatch(deleteVenueAction(id)),\n    changeSearchAction: (searchText: string) => dispatch(changeSearchAction(searchText)),\n    changeTempVenueAction: (venue: IBaseVenue) => dispatch(changeTempVenueAction(venue)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{venues: IVenuesState}, {dispatch: any}, IPropsType>(mapStateToProps, mapDispatchToProps)(VenuesListView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {IBaseVenue, IVenue} from '../../../../../../src/app/interfaces/venue.interface';\nimport {changeTempVenueAction, getVenueUsersAction, IVenuesState, VenueReduxAction} from '../../actions/venues.actions';\nimport {updateTooltip} from '../../utils/common';\nimport BootstrapSelect from '../Utils/BootstrapSelect';\nimport Checkbox from '../Utils/CheckBox';\nimport {IVenueDay} from '../../../../../../src/app/interfaces/venueDay.interface';\n\ninterface IPropsType {\n  venues?: IVenuesState;\n  update?: boolean;\n  changeTempVenueAction?: (venue: IBaseVenue, noDelay?: boolean) => VenueReduxAction;\n  getVenueUsersAction? : (page:number, venue: IVenue) => VenueReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass VenueFormView extends React.Component<IPropsType, IStateType> {\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.changeTypeAction = this.changeTypeAction.bind(this);\n    this.handleSelectVenues = this.handleSelectVenues.bind(this);\n    this.handleSelectResponsible = this.handleSelectResponsible.bind(this);\n  }\n\n  public componentDidMount(): void {\n    const chosenOptions = {\n      no_results_text: 'Sin resultados para:'\n    };\n    updateTooltip();\n  }\n\n  public componentDidUpdate(prevProps:Readonly<IPropsType>, prevState:Readonly<IStateType>, snapshot?:any): void {\n    updateTooltip();\n    if (prevProps.venues?.tempVenue._id != this.props.venues?.tempVenue._id)\n        this.props.getVenueUsersAction?.(1, this.props.venues?.tempVenue as IVenue)\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  render(): React.ReactElement<IPropsType> | null {\n    if (this.props.venues && this.props.changeTempVenueAction) {\n      const {changeTempVenueAction, update} = this.props;\n      const {tempVenue, companies, carriers, regions, users} = this.props.venues;\n      let {allVenues} = this.props.venues;\n      if (update) {\n        allVenues = allVenues.filter((venue) => venue._id !== tempVenue._id);\n      }\n      return (\n        <React.Fragment>\n          <ul className=\"nav nav-tabs\" style={{marginBottom: '15px'}}>\n            <li className=\"active\"><a data-toggle=\"tab\" href=\"#general\">General</a></li>\n            {tempVenue.sendToDays.length > 0 ? <li><a data-toggle=\"tab\" href=\"#diasSucursales\">Tiempos de despacho</a></li> : null}\n          </ul>\n          <div className=\"tab-content\">\n            <div id=\"general\" className=\"tab-pane fade in active\">\n              <div className=\"row\">\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label>Nombre</label>\n                    <input\n                      type=\"text\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      value={tempVenue.name}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempVenueAction({\n                          ...tempVenue,\n                          name: e.target.value\n                        }, true)\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label>Código</label>\n                    <input\n                      type=\"text\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      value={tempVenue.code}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempVenueAction({\n                          ...tempVenue,\n                          code: e.target.value\n                        }, true)\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label>Abreviación</label>\n                    <input\n                      type=\"text\"\n                      name=\"abbreviation\"\n                      step=\"any\"\n                      className=\"form-control\"\n                      maxLength={10}\n                      value={tempVenue.abbreviation || ''}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempVenueAction({\n                          ...tempVenue,\n                          abbreviation: e.target.value.toUpperCase()\n                        }, true)\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-6\">\n                  <div className=\"form-group\">\n                    <label>Latitud</label>\n                    <input\n                      type=\"number\"\n                      name=\"lng\"\n                      step=\"any\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      value={tempVenue.lat}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempVenueAction({\n                          ...tempVenue,\n                          lat: parseFloat(e.target.value)\n                        }, true)\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-6\">\n                  <div className=\"form-group\">\n                    <label>Longitud</label>\n                    <input\n                      type=\"number\"\n                      name=\"lng\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      value={tempVenue.lng}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempVenueAction({\n                          ...tempVenue,\n                          lng: parseFloat(e.target.value)\n                        }, true)\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"id-company\">Empresa</label>\n                    <BootstrapSelect\n                      noneSelectedText=\"Seleccione\"\n                      search={true}\n                      options={\n                        companies\n                          .map((company) => ({\n                            value: company._id,\n                            text: company.name\n                          }))\n                      }\n                      selected={tempVenue.company ? [tempVenue.company._id] : []}\n                      autoClouse={true}\n                      onClick={(value: string) => changeTempVenueAction({\n                        ...tempVenue,\n                        company: companies.find((company) => (company._id === value))\n                      }, true)}\n                    />\n                  </div>\n                  {\n                    update ?\n                      <div className=\"alert alert-warning alert-dismissible\">\n                        Si se modifica la empresa, los usuarios asignados a esta sucursal también se verán afectados.\n                      </div> : null\n                  }\n                </div>\n                {update? <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"venues\" className=\"control-label\">\n                      Encargados de local\n                    </label>\n                    <BootstrapSelect\n                      noneSelectedText=\"Seleccione\"\n                      displayItems={2}\n                      search={true}\n                      selectedText=\"Usuarios seleccionados.\"\n                      selected={tempVenue.responsible.map((user) => user._id)}\n                      allOption={true}\n                      selectAll={(value: boolean) => this.handleSelectResponsible(true, value)}\n                      options={users.map((user: any) => ({\n                        value: user._id,\n                        text: `${user.firstName} ${user.lastName}`\n                      }))}\n                      onClick={(value: string) => this.handleSelectResponsible(false, value)}\n                    />\n                  </div>\n                </div> : null }\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"id-company\">Región</label>\n                    <BootstrapSelect\n                      noneSelectedText=\"Seleccione\"\n                      options={\n                        regions\n                          .map((region) => ({\n                            value: region._id,\n                            text: region.name\n                          }))\n                      }\n                      selected={tempVenue.region ? [tempVenue.region._id] : []}\n                      autoClouse={true}\n                      onClick={(value: string) => changeTempVenueAction({\n                        ...tempVenue,\n                        region: regions.find((region) => (region._id === value))\n                      }, true)}\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"venues\" className=\"control-label\">\n                      Envia <i\n                      className=\"fa fa-info-circle text-black\"\n                      data-toggle=\"tooltip\" data-placement=\"top\"\n                      title=\"Usuarios asignados a esta sucursal, pueden enviar a estas sucursales.\"\n                    />\n                    </label>\n                    <BootstrapSelect\n                      noneSelectedText=\"Seleccione\"\n                      displayItems={2}\n                      search={true}\n                      selectedText=\"sucursales seleccionadas.\"\n                      selected={tempVenue.sendToDays.map((venueDay) => venueDay.venue._id)}\n                      allOption={true}\n                      selectAll={(value: boolean) => this.handleSelectVenuesSendToDays( true, value)}\n                      options={allVenues.map((venue: any) => ({\n                        value: venue._id,\n                        text: venue.name\n                      }))}\n                      onClick={(value: string) => this.handleSelectVenuesSendToDays(false, value)}\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"venues\" className=\"control-label\">\n                      Transportistas de envio <i\n                      className=\"fa fa-info-circle text-black\"\n                      data-toggle=\"tooltip\" data-placement=\"top\"\n                      title=\"Usuarios asignados a esta sucursal, pueden enviar de estos transportista.\"\n                    />\n                    </label>\n                    <BootstrapSelect\n                      noneSelectedText=\"Seleccione\"\n                      displayItems={2}\n                      search={true}\n                      selectedText=\"sucursales seleccionadas.\"\n                      selected={tempVenue.shippingCarriers.map((carrier) => carrier._id)}\n                      allOption={true}\n                      selectAll={(value: boolean) => this.handleSelectCarriers('shippingCarriers', true, value)}\n                      options={carriers.map((carrier: any) => ({\n                        value: carrier._id,\n                        text: carrier.name\n                      }))}\n                      onClick={(value: string) => this.handleSelectCarriers('shippingCarriers', false, value)}\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"venues\" className=\"control-label\">\n                      Recibe <i\n                      className=\"fa fa-info-circle text-black\"\n                      data-toggle=\"tooltip\"\n                      data-placement=\"top\"\n                      title=\"Usuarios asignados a esta sucursal, pueden recepcionar de estas sucursales.\"\n                    />\n                    </label>\n                    <BootstrapSelect\n                      noneSelectedText=\"Seleccione\"\n                      displayItems={2}\n                      search={true}\n                      selectedText=\"sucursales seleccionadas.\"\n                      selected={tempVenue.receiveFrom.map((venue) => venue._id)}\n                      allOption={true}\n                      selectAll={(value: boolean) => this.handleSelectVenues('receiveFrom', true, value)}\n                      options={allVenues.map((venue: any) => ({\n                        value: venue._id,\n                        text: venue.name\n                      }))}\n                      onClick={(value: string) => this.handleSelectVenues('receiveFrom', false, value)}\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"venues\" className=\"control-label\">\n                      Transportistas de recepción <i\n                      className=\"fa fa-info-circle text-black\"\n                      data-toggle=\"tooltip\" data-placement=\"top\"\n                      title=\"Usuarios asignados a esta sucursal, pueden receocionar de estos transportista.\"\n                    />\n                    </label>\n                    <BootstrapSelect\n                      noneSelectedText=\"Seleccione\"\n                      displayItems={2}\n                      search={true}\n                      selectedText=\"sucursales seleccionadas.\"\n                      selected={tempVenue.receptionCarriers.map((carrier) => carrier._id)}\n                      allOption={true}\n                      selectAll={(value: boolean) => this.handleSelectCarriers('receptionCarriers', true, value)}\n                      options={carriers.map((carrier: any) => ({\n                        value: carrier._id,\n                        text: carrier.name\n                      }))}\n                      onClick={(value: string) => this.handleSelectCarriers('receptionCarriers', false, value)}\n                    />\n                  </div>\n                </div>\n                <div className=\"col col-md-12\">\n                  <div className=\"checkbox\">\n                    <label style={{paddingLeft: '0'}} onClick={this.changeTypeAction}>\n                      <Checkbox active={tempVenue.type === 'distributor'} action={this.changeTypeAction}\n                                classes=\"icheck-in-checkbox\"/>\n                      <span\n                        style={{\n                          paddingLeft: '5px',\n                          top: '2px',\n                          position: 'relative'\n                        }}\n                      >\n                        Distribuidor <i\n                        className=\"fa fa-info-circle\"\n                        data-toggle=\"tooltip\"\n                        data-placement=\"top\"\n                        title=\"Activa funcionalidades a la sucursal.\"\n                      />\n                </span>\n                    </label>\n                  </div>\n                </div>\n              </div>\n            </div>\n            { tempVenue.sendToDays.length > 0 ? <div id=\"diasSucursales\" className=\"tab-pane fade\">\n              { tempVenue.sendToDays.map( (venueDay: IVenueDay) => {\n                const venueIndex = tempVenue.sendToDays.findIndex(v => v.venue._id === venueDay.venue._id);\n                  return <div className=\"row\" key={venueDay.venue._id}>\n                    <div className=\"col-md-12\">\n                      <div className=\"form-group\">\n                        <label>{tempVenue.name} - {venueDay.venue.name}</label>\n                        <input\n                          type=\"number\"\n                          name={venueDay.venue._id}\n                          step=\"any\"\n                          className=\"form-control\"\n                          min={1}\n                          value={venueDay.shippingMaxDays || ''}\n                          onChange={\n                            (e: React.ChangeEvent<HTMLInputElement>) => {\n                              tempVenue.sendToDays[venueIndex].shippingMaxDays = parseInt(e.target.value);\n                              changeTempVenueAction(tempVenue, true);\n                            }\n                          }\n                        />\n                      </div>\n                    </div>\n                  </div>;\n                }\n              )}\n            </div> : null}\n          </div>\n        </React.Fragment>\n      );\n    } else {\n      return null;\n    }\n  }\n\n  private handleSelectVenuesSendToDays(all: boolean, value: string | boolean){\n    if (this.props.changeTempVenueAction && this.props.venues) {\n      const {tempVenue, allVenues} = this.props.venues;\n      let values : IVenueDay[]= [];\n      if (all) {\n        values = value ? allVenues.map((venue: IVenue) => {\n          return {_id: null, shippingMaxDays : undefined, venue};}) :\n          [];\n      } else {\n        const add = tempVenue.sendToDays.find((venueDay : IVenueDay) => venueDay.venue._id === value) === undefined;\n        const venueDay : IVenueDay = {\n          _id: null,\n          venue:allVenues.find((venue) => venue._id === value)!,\n          shippingMaxDays: undefined\n        };\n        if (add) {\n          values = [...tempVenue.sendToDays, venueDay];\n        } else {\n          values = tempVenue.sendToDays.filter((venueDay) => venueDay.venue._id !== value);\n        }\n      }\n      this.props.changeTempVenueAction({\n        ...tempVenue,\n        sendToDays: values\n      }, true);\n    }\n\n  }\n  private handleSelectResponsible(all: boolean, value: string | boolean) {\n    if (this.props.changeTempVenueAction && this.props.venues) {\n      const {tempVenue, users} = this.props.venues;\n      if (all) {\n        this.props.changeTempVenueAction({\n          ...tempVenue,\n          responsible: value ? users : []\n        }, true);\n      } else {\n        let new_user = users.find(u => u._id === value)\n        if (new_user)\n          this.props.changeTempVenueAction({\n            ...tempVenue,\n            responsible: tempVenue.responsible.concat([new_user])\n          }, true);\n      }\n    }\n  }\n\n  private handleSelectVenues(where: 'receiveFrom' | 'sendTo', all: boolean, value: string | boolean) {\n    if (this.props.changeTempVenueAction && this.props.venues) {\n      const {tempVenue, allVenues} = this.props.venues;\n      let values = [];\n      if (all) {\n        values = value ? allVenues : [];\n      } else {\n        const add = tempVenue[where].find((venue) => venue._id === value) === undefined;\n        const venue = allVenues.find((venue) => venue._id === value);\n        if (add) {\n          values = [...tempVenue[where], venue];\n        } else {\n          values = tempVenue[where].filter((venue) => venue._id !== value);\n        }\n      }\n      this.props.changeTempVenueAction({\n        ...tempVenue,\n        [where]: values\n      }, true);\n    }\n  }\n  private handleSelectCarriers(where: 'shippingCarriers' | 'receptionCarriers', all: boolean, value: string | boolean) {\n    if (this.props.changeTempVenueAction && this.props.venues) {\n      const {tempVenue, carriers} = this.props.venues;\n      let values = [];\n      if (all) {\n        values = value ? carriers : [];\n      } else {\n        const add = tempVenue[where].find((carrier) => carrier._id === value) === undefined;\n        const carrier = carriers.find((carrier) => carrier._id === value);\n        if (add) {\n          values = [...tempVenue[where], carrier];\n        } else {\n          values = tempVenue[where].filter((carrier) => carrier._id !== value);\n        }\n      }\n      this.props.changeTempVenueAction({\n        ...tempVenue,\n        [where]: values\n      }, true);\n    }\n  }\n\n  private changeTypeAction() {\n    if (this.props.venues && this.props.changeTempVenueAction) {\n      const {changeTempVenueAction} = this.props;\n      const {tempVenue} = this.props.venues;\n      changeTempVenueAction({\n        ...tempVenue,\n        type: tempVenue.type === 'receiver' ? 'distributor' : 'receiver'\n      }, true);\n    }\n  }\n}\n\nconst mapStateToProps = (state: { venues: IVenuesState }) => {\n  return {\n    venues: state.venues\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    changeTempVenueAction: (venue: IBaseVenue, noDelay?: boolean) => dispatch(changeTempVenueAction(venue, noDelay)),\n    getVenueUsersAction: (page: number, venue: IVenue) => dispatch(getVenueUsersAction(page, venue))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(VenueFormView);\n","import * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport {createVersionAction, IVersionsState, getVersionsAction} from '../../actions/versions.actions';\nimport {loadDataAction, ModalReduxAction} from '../../actions/modal.actions';\nimport AppContainer from '../../container/AppContainer';\nimport {statusFooterButttonsModal} from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport VersionFormView from './VersionFormView';\nimport Row from '../Utils/Row';\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  versions: IVersionsState;\n  dispatch: Dispatch<ModalReduxAction>;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n  getVersionsAction(): ModalReduxAction;\n\n  createVersionAction(version: ITempVersion): ModalReduxAction;\n}\n\ninterface ITempVersion {\n  ios: string;\n  android: string;\n}\n\ninterface IStateType {\n  error: Error | null;\n  dragging: string;\n  draggingLocation: number;\n  completed: string[];\n  users: string[];\n  tempVersion: ITempVersion;\n}\n\nclass VersionListView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  // static propTypes = {\n  //   alerts: PropTypes.object.isRequired,\n  //   dispatch: PropTypes.func.isRequired\n  // };\n\n  state = {\n    error: null,\n    dragging: '',\n    draggingLocation: -1,\n    completed: [],\n    users: ['One', 'Two', 'Three', 'Four', 'Five'],\n    tempVersion: {\n      ios: '',\n      android: ''\n    }\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de versiones';\n    this.changeTempVersion = this.changeTempVersion.bind(this);\n    this.onDragStart = this.onDragStart.bind(this);\n    this.onDragEnd = this.onDragEnd.bind(this);\n    this.onDragOver = this.onDragOver.bind(this);\n    this.onDrop = this.onDrop.bind(this);\n    this.onDropChangeIndex = this.onDropChangeIndex.bind(this);\n    this.onDragOverChange = this.onDragOverChange.bind(this);\n    this.onDragEndChange = this.onDragEndChange.bind(this);\n\n    this.addVersion = this.addVersion.bind(this);\n    this.processAddAlert = this.processAddAlert.bind(this);\n\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public componentWillMount() {\n    this.props.getVersionsAction();\n  }\n\n  public componentWillUnmount() {\n    // cancel request if component is inmounted\n    if (this.props.versions.source) {\n      this.props.versions.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n\n    const {versions, loading} = this.props.versions;\n\n    return (\n      <AppContainer title=\"\" cMenu=\"10\" cSubMenu=\"10.7\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Versiones <small>{versions.length}</small></h3>\n              <div className=\"pull-right box-tools\">\n                <button className=\"btn btn-sm btn-success\" onClick={this.addVersion}>Agregar</button>\n              </div>\n            </div>\n            <div className=\"box-body no-padding\">\n              <table className=\"table table-andes table-striped\">\n                <thead>\n                  <tr>\n                    <th className=\"middle\">Descripción</th>\n                    <th className=\"middle text-center\">iOS Version</th>\n                    <th className=\"middle text-center\">Android Version</th>\n                    <th className=\"middle\">Creada por</th>\n                    <th className=\"middle\">Fecha creación</th>\n                  </tr>\n                </thead>\n                <tbody>\n                {\n                  versions.length ?\n                    versions.map((version: any) => {\n                      return (\n                        <tr\n                          key={version._id}\n                          id={`alert-${version._id}`}\n                          className={'background-transition'}\n                        >\n                          <td className=\"middle\">{version.description}</td>\n                          <td className=\"middle text-center\">{version.ios}</td>\n                          <td className=\"middle text-center\">{version.android}</td>\n                          <td className=\"middle\">\n                            {\n                              version.createdBy ? version.createdBy.firstName + ' ' + version.createdBy.lastName : '-'\n                            }\n                          </td>\n                          <td className=\"middle\">{moment(version.createdAt).format('LLL')}</td>\n                        </tr>\n                      );\n                    }) : <tr>\n                      <td colSpan={5}>Aún no se han ingresado versiones</td>\n                    </tr>\n                }\n                </tbody>\n              </table>\n              <Row>\n                <div className=\"col-md-6\">\n                  <table className=\"table table-andes table-striped\">\n                    <thead>\n                      <tr>\n                        <th className=\"middle\">Nombre</th>\n                      </tr>\n                    </thead>\n                    <tbody>\n                      {\n                        this.state.users.map((user, index)=>{\n                          return (\n                            <tr\n                              draggable\n                              key={index}\n                              className={`pointer ${this.state.draggingLocation === index ? 'bg-aqua-active' : ''}`}\n                              style={{\n                                opacity: this.state.dragging === user || this.state.draggingLocation === index ? 0.5 : 1\n                              }}\n                              onDragStart = {(e) => this.onDragStart(e, user, index)}\n                              onDragEnter={this.onDragEnter}\n                              onDragEnd = {this.onDragEndChange}\n                              onDrop={(e) =>this.onDropChangeIndex(e, index)}\n                              onDragOver={(e)=>this.onDragOverChange(e, index)}\n                            >\n                              <td\n                              ><i className=\"fa fa-arrows-v text-muted font-md\" /> {\n                                this.state.draggingLocation === index ? this.state.dragging : user\n                              }</td>\n                            </tr>\n\n                          );\n                        })\n                      }\n                    </tbody>\n                  </table>\n                </div>\n                <div className=\"col-md-6\" style={{height: '150px', overflowY: 'auto'}}>\n                  <div\n                    onDragOver={this.onDragOver}\n                    onDrop={(e) =>this.onDrop(e, 'completed')}\n                    onDragEnter={this.onDragEnter}\n                    style={{width: 200, minHeight: 100, border: '1px solid #CCC'}}\n                  >\n                    completed\n                    {this.state.completed.map((item, index)=><div key={index}>{item}</div>)}\n                  </div>\n                  <div\n                    onDragOver={this.onDragOver}\n                    onDragEnter={this.onDragEnter}\n                    onDrop={(e) =>this.onDrop(e, 'incompleted')}\n                    style={{width: 200,  minHeight: 100, border: '1px solid #CCC'}}\n                  >\n                    incompleted\n                  </div>\n                </div>\n              </Row>\n            </div>\n            {\n              loading &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private onDragStart(ev: React.DragEvent<HTMLTableRowElement>, id:string, index: number) {\n    console.log(`onDragStart: ${id}`);\n    ev.dataTransfer.setData('id', id);\n    ev.dataTransfer.setData('type', 'type');\n    ev.dataTransfer.setData('index', index.toString());\n\n    ev.dataTransfer.dropEffect = 'move';\n\n    const dragIcon = document.createElement('img');\n    dragIcon.src = 'https://www.automotrizcumbre.cl/wp-content/uploads/2018/08/chevrolet-sail-sedan-detalles-personaliza-648x240-4-300x180.jpg';\n    dragIcon.width = 100;\n    ev.dataTransfer.setDragImage(dragIcon, -10, -10);\n\n    this.setState({\n      dragging: id\n    });\n  }\n\n  private onDragEnd(ev: React.DragEvent<HTMLTableRowElement>) {\n    console.log(`onDragEnd`);\n    this.setState({\n      dragging: ''\n    });\n  }\n\n  private onDragEnter(ev: React.DragEvent<HTMLElement>) {\n    console.log(`onDragEnter`);\n    ev.preventDefault();\n    ev.stopPropagation();\n  }\n\n  private onDragOver(ev: React.DragEvent<HTMLElement>) {\n    console.log(`onDragOver`);\n    ev.preventDefault();\n    ev.stopPropagation();\n  }\n\n  private onDragOverChange(ev: React.DragEvent<HTMLElement>, index: number) {\n    console.log(`onDragOverChange`);\n    ev.dataTransfer.dropEffect = 'move';\n    ev.preventDefault();\n    ev.stopPropagation();\n    this.setState({\n      draggingLocation: index\n    });\n  }\n\n  private onDragEndChange(ev: React.DragEvent<HTMLElement>){\n    console.log(`onDragEndChange`);\n    this.setState({\n      draggingLocation: -1,\n      dragging: ''\n    });\n  }\n\n  private onDrop(ev: React.DragEvent<HTMLElement>, cat: string){\n    const id = ev.dataTransfer.getData('id');\n    const type = ev.dataTransfer.getData('type');\n    console.log(`onDrop: id: ${id} cat: ${cat}`);\n    console.log(id);\n    if (cat === 'completed') {\n      this.setState({\n        completed: [id, ...this.state.completed]\n      });\n    } else {\n      alert(`${id} se a soltado en ${cat}`);\n\n    }\n  }\n\n  private onDropChangeIndex(ev: React.DragEvent<HTMLElement>, newIndex: number) {\n    let {users} = this.state;\n    let index = parseInt(ev.dataTransfer.getData('index'));\n    console.log(`onDropChangeIndex newIndex:${newIndex} index:${index}`);\n    const data = users[index];\n    if (newIndex > index) {\n      for (let i = 0; i < users.length; i++) {\n        if (i >= index && i < newIndex) {\n          users[i] = users[i + 1];\n        }\n      }\n    } else {\n      for (let i = users.length - 1; i >= 0; i--) {\n        if (i > newIndex && i <= index) {\n          console.log(`2 ${users[i]} -> ${users[i - 1]}`);\n          users[i] = users[i - 1];\n        }\n      }\n    }\n    users[newIndex] = data;\n    this.setState({\n      users\n    });\n  }\n\n\n  private addVersion() {\n    this.props.loadDataAction(\n      'Agregar Alerta',\n        <VersionFormView changeTempVersion={this.changeTempVersion} />\n      ,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-sm btn-primary\" onClick={this.processAddAlert}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private changeTempVersion(tempVersion: ITempVersion) {\n    this.setState({\n      tempVersion\n    });\n  }\n\n  private processAddAlert() {\n\n    const {tempVersion} = this.state;\n\n    if(tempVersion.ios.trim().length === 0)\n    {\n      swal('Agregar alerta', 'El campo nombre es requerido.', 'error');\n    }\n    else if(tempVersion.android.trim().length === 0)\n    {\n      swal('Agregar alerta', 'El campo nombre es requerido.', 'error');\n    }\n    else\n    {\n      statusFooterButttonsModal(true);\n      this.props.createVersionAction(tempVersion);\n    }\n  }\n}\n\nconst mapStateToProps = (state: { versions: IVersionsState }) => {\n  return {\n    versions: state.versions\n  };\n};\n\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer)),\n    getVersionsAction: () => dispatch(getVersionsAction()),\n    createVersionAction: (version: ITempVersion) => dispatch(createVersionAction(version))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(VersionListView);\n","import {AxiosError, AxiosResponse, CancelTokenSource} from 'axios';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport {IAlert} from '../../../../../src/app/interfaces/alert.interface';\nimport {IVersion} from '../../../../../src/app/interfaces/version.interface';\nimport {IUser} from '../../../../../src/app/interfaces/user.interface';\nimport ApiService from '../utils/axios';\nimport {showModal, statusFooterButttonsModal} from '../utils/common';\n\nexport interface IVersionsState {\n  versions: IVersion[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface ICancelRequest {\n  type: '/ALERTS/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/ALERTS/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/VERSIONS/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/VERSIONS/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface ICreateVersion {\n  type: '/VERSIONS/CREATE';\n  payload: {\n    version: IVersion;\n  };\n}\n\nexport function createVersion(version: IVersion): ICreateVersion {\n  return {\n    type: '/VERSIONS/CREATE',\n    payload: {\n      version\n    }\n  };\n}\n\nexport function createVersionAction(version: any) {\n  return (dispatch: Dispatch<VersionReduxAction>) => {\n    dispatch(isLoadingAction(true));\n    const api: ApiService = new ApiService();\n    console.log(\"-- version\", version)\n    api.createVersion(version)\n      .then((response: AxiosResponse) => {\n        const data = response.data;\n        statusFooterButttonsModal(false);\n        showModal(false);\n        dispatch(createVersion(data.version));\n        dispatch(isLoadingAction(false));\n        swal(response.data.message, {\n          icon: 'success'\n        });\n      })\n      .catch((err: AxiosError) => {\n        api.errorHandler(err);\n        dispatch(isLoadingAction(false));\n      });\n  };\n}\n\ninterface ILoadVersions {\n  type: '/VERSIONS/LOAD_DATA';\n  payload: {\n    versions: IVersion[]\n  };\n}\n\nexport function loadVersionsAction(versions: IVersion[]): ILoadVersions {\n  return {\n    type: '/VERSIONS/LOAD_DATA',\n    payload: {\n      versions\n    }\n  };\n}\n\nexport function getVersionsAction() {\n  return (dispatch: Dispatch<VersionReduxAction>) => {\n    const api: ApiService = new ApiService();\n    // dispatch(isLoadingAction(true));\n    dispatch(cancelRequestAction(api.getSource()));\n    api.getVersions()\n      .then((response: AxiosResponse) => {\n        const data = response.data;\n        dispatch(loadVersionsAction(data.versions));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport type VersionReduxAction =\n  ICancelRequest |\n  IIsLoading |\n  ILoadVersions |\n  ICreateVersion;\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {IUser} from '../../../../../../src/app/interfaces/user.interface';\n\ninterface IPropsType {\n  changeTempVersion: (tempVersion: ITempVersion) => void;\n}\n\ninterface ITempVersion {\n  ios: string;\n  android: string;\n  description: string;\n}\n\ninterface IStateType {\n  error: Error | null;\n  tempVersion: ITempVersion;\n  currentUser: string;\n}\n\nclass VersionFormView extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null,\n    currentUser: '',\n    tempVersion: {\n      description: '',\n      ios: '',\n      android: ''\n    }\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.onChangeDescription = this.onChangeDescription.bind(this);\n    this.onChangeiOS = this.onChangeiOS.bind(this);\n    this.onChangeAndroid = this.onChangeAndroid.bind(this);\n  }\n\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  componentDidUpdate() {\n    this.props.changeTempVersion(this.state.tempVersion);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    return (\n      <div className={'row'}>\n        <div className=\"col-md-12\">\n          <div className=\"form-group\">\n            <label>Descripción</label>\n            <input\n              type=\"text\"\n              className=\"form-control\"\n              maxLength={200}\n              onChange={this.onChangeDescription}\n            />\n          </div>\n        </div>\n        <div className=\"col-md-12\">\n          <div className=\"form-group\">\n            <label>iOS</label>\n            <input\n              type=\"text\"\n              className=\"form-control\"\n              maxLength={200}\n              onChange={this.onChangeiOS}\n            />\n          </div>\n        </div>\n        <div className=\"col-md-12\">\n          <div className=\"form-group\">\n            <label>Android</label>\n            <input\n              type=\"text\"\n              className=\"form-control\"\n              maxLength={200}\n              onChange={this.onChangeAndroid}\n            />\n          </div>\n        </div>\n      </div>\n    );\n  }\n\n  private onChangeDescription(e: React.ChangeEvent<HTMLInputElement>) {\n    this.setState({\n      tempVersion: {\n        ...this.state.tempVersion,\n        description: e.target.value.trim()\n      }\n    });\n  }\n\n  private onChangeiOS(e: React.ChangeEvent<HTMLInputElement>) {\n    this.setState({\n      tempVersion: {\n        ...this.state.tempVersion,\n        ios: e.target.value.trim()\n      }\n    });\n  }\n\n  private onChangeAndroid(e: React.ChangeEvent<HTMLInputElement>) {\n    this.setState({\n      tempVersion: {\n        ...this.state.tempVersion,\n        android: e.target.value.trim()\n      }\n    });\n  }\n\n}\n\nexport default VersionFormView;\n","import { routerMiddleware } from 'connected-react-router';\nimport * as createRavenMiddleware from 'raven-for-redux';\nimport * as Raven from 'raven-js';\nimport {applyMiddleware, createStore} from 'redux';\nimport createDebounce from 'redux-debounced';\nimport {composeWithDevTools} from 'redux-devtools-extension';\n// import LogerMiddleware from 'redux-logger';\nimport ThunkMiddleware from 'redux-thunk';\nimport {IWindow} from '../interfaces/window';\nimport createRootReducer from '../reducers/index.reducer';\nimport browserHistort from '../utils/history';\n\ndeclare let window: IWindow;\n\nexport const history = browserHistort;\n\nconst configureStore = () => {\n  let enhancers: any;\n  const middlewares: any[] = [routerMiddleware(history)];\n\n  if (process.env.NODE_ENV === 'development') {\n    middlewares.push(ThunkMiddleware);\n    // middlewares.push(LogerMiddleware);\n    middlewares.push(createDebounce());\n    const composeEnhancers = composeWithDevTools({trace: true, traceLimit: 10 });\n    enhancers = composeEnhancers(applyMiddleware(...middlewares));\n  } else {\n    middlewares.push(ThunkMiddleware);\n    middlewares.push(createDebounce());\n    Raven.config('https://7cb5eacf6f8249b888468a1b72bd7632@sentry.osacontrol.com/5').install();\n    const context = {\n        id: window.user._id,\n        name: `${window.user.firstName} ${window.user.lastName}`,\n        email: window.user.email\n    };\n    Raven.setUserContext(context);\n    Raven.setTagsContext({\n        environment: process.env.NODE_ENV\n    });\n    Raven.setExtraContext({\n        app: 'Andes'\n    });\n    middlewares.push(createRavenMiddleware(Raven));\n    enhancers = applyMiddleware(...middlewares);\n  }\n\n  return createStore(createRootReducer(history), enhancers);\n};\n\nexport default configureStore;\n","import { connectRouter } from 'connected-react-router';\nimport { combineReducers } from 'redux';\nimport { reducer as formReducer } from 'redux-form';\nimport { alertsReducer } from './alerts.reducer';\nimport { billingReducer } from './billing.reducers';\nimport { carriersReducer } from './carriers.reducer';\nimport { carsReducer } from './cars.reducer';\nimport { companiesReducer } from './companies.reducer';\nimport { dashboardReducer } from './dashboard.reducer';\nimport { dashboardDamagesReducer } from './dashboardDamages.reducer';\nimport { dashboardDercoReducer } from './dashboardDerco.reducer';\nimport { dashboardTimingReducer } from './dashboardTiming.reducer';\nimport { inventoriesReducer } from './inventory.reducer';\nimport { inventoriesDashboardReducer } from './inventoryDashboard.reducer';\nimport { labelsReducer } from './labels.reducer';\nimport { modalReducer } from './modal.reducer';\nimport { planningReducer } from './planning.reducer';\nimport { reasonsReducers } from './reasons.reducer';\nimport { regionsReducer } from './regions.reducer';\nimport { requestItemsReducers } from './requestItems.reducer';\nimport { requestsReducers } from './requests.reducer';\nimport { stockReducer } from './stock.reducer';\nimport { usersReducer } from './users.reducer';\nimport { requestStatusReducer } from './requestStatus.reducer';\nimport { requestChannelReducer } from './requestChannel.reducer';\nimport { paymentMethodReducer } from './paymentMethod.reducer';\nimport { venuesReducer } from './venues.reducer';\nimport { versionsReducer } from './versions.reducer';\nimport transmittalReducer from \"./transmittal.reducer\";\nimport { operationTypeReducer } from './operationType.reducer';\nimport { milestoneReducer } from './milestone.reducer';\nimport { milestoneTypeReducer } from './milestoneType.reducer';\nimport { formsReducer } from './form.reducer';\nimport { colorsReducer } from './color.reducer';\nimport {statsDashboardReducer} from \"./statsDashboard.reducer\";\n\nexport default (history: any) => combineReducers({\n  users: usersReducer,\n  cars: carsReducer,\n  forms: formsReducer,\n  colors: colorsReducer,\n  transmittal: transmittalReducer,\n  modal: modalReducer,\n  carriers: carriersReducer,\n  dashboard: dashboardReducer,\n  dashboardDamages: dashboardDamagesReducer,\n  dashboardTiming: dashboardTimingReducer,\n  billing: billingReducer,\n  dashboardDerco: dashboardDercoReducer,\n  inventories: inventoriesReducer,\n  inventoryDashboard: inventoriesDashboardReducer,\n  alerts: alertsReducer,\n  reasons: reasonsReducers,\n  versions: versionsReducer,\n  requestStatus: requestStatusReducer,\n  paymentMethod: paymentMethodReducer,\n  requestChannel: requestChannelReducer,\n  venues: venuesReducer,\n  companies: companiesReducer,\n  labels: labelsReducer,\n  requests: requestsReducers,\n  requestItems: requestItemsReducers,\n  operationType: operationTypeReducer,\n  milestone: milestoneReducer,\n  milestoneType: milestoneTypeReducer,\n  regions: regionsReducer,\n  stock: stockReducer,\n  statsDashboard: statsDashboardReducer,\n  planning: planningReducer,\n  form: formReducer,\n  router: connectRouter(history)\n});\n","import {AlertReduxAction, IAlertsState} from '../actions/alerts.actions';\n\nconst initialState: IAlertsState = {\n  alerts: [],\n  users: [],\n  loading: true,\n  source: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function alertsReducer(state = initialState, action: AlertReduxAction): IAlertsState {\n  switch (action.type) {\n    case '/ALERTS/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/ALERTS/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/ALERTS/DELETE':\n      return {\n        ...state,\n        alerts: state.alerts.filter((alert) => alert._id !== action.payload.id)\n      };\n    case '/ALERTS/CREATE':\n      return {\n        ...state,\n        alerts: [action.payload.alert, ...state.alerts]\n      };\n    case '/ALERTS/LOAD_DATA':\n      return {\n        ...state,\n        users: action.payload.users,\n        alerts: action.payload.alerts\n      };\n    default:\n      return state;\n  }\n}\n","import {BillingReduxAction, IBillingState} from \"../actions/billing.actions\";\n\nconst initialState: IBillingState = {\n  invoices: [],\n  source: null,\n  loading: true,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function billingReducer(state = initialState, action: BillingReduxAction): any {\n  switch (action.type) {\n    case '/BILLING/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/BILLING/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/BILLING/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/BILLING/LOAD_BILLING':\n      return {\n        ...state,\n        invoices: action.payload.invoices,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {CarrierReduxAction, ICarriersState} from '../actions/carriers.actions';\n\nconst initialState: ICarriersState = {\n  carriers: [],\n  tempCarrier: {\n    name: ''\n  },\n  loading: true,\n  source: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function carriersReducer(state = initialState, action: CarrierReduxAction): ICarriersState {\n  switch (action.type) {\n    case '/CARRIERS/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/CARRIERS/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/CARRIERS/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/CARRIERS/CHANGE_TEMP_CARRIER':\n      return {\n        ...state,\n        tempCarrier: action.payload.carrier\n      };\n    case '/CARRIERS/LOAD_CARRIERS':\n      return {\n        ...state,\n        carriers: action.payload.carriers,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import * as moment from 'moment';\nimport {ICar} from '../../../../../src/app/interfaces/car.interface';\nimport {CarReduxAction, ICarsState} from '../actions/cars.actions';\n\nconst initialState: ICarsState = {\n  cars: [],\n  car: null,\n  carEvents: {} ,\n  loading: true,\n  source: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function carsReducer(state = initialState, action: CarReduxAction): ICarsState {\n  switch (action.type) {\n    case '/CARS/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/CARS/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/CARS/LOAD_CARS':\n      return {\n        ...state,\n        cars: action.payload.cars,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    case '/CARS/LOAD_CAR':\n      return {\n        ...state,\n        car: action.payload.car,\n        carEvents: groupCarEvents(action.payload.car)\n      };\n    case '/CARS/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    default:\n      return state;\n  }\n}\n\nfunction groupCarEvents(car: ICar): any[] {\n  const events: any[] = [];\n  events.push({\n    _id: car._id,\n    createdAt: moment(car.createdAt).seconds(0),\n    typeEvent: 'created'\n  });\n  if (car.participants && car.participants.length) {\n    for (const participant of car.participants) {\n      events.push({\n        ...participant,\n        createdAt: moment(participant.createdAt),\n        typeEvent: 'revision'\n      });\n    }\n  }\n  if (car.inventories && car.inventories.length) {\n    for (const inventory of car.inventories) {\n      events.push({\n        ...inventory,\n        createdAt: moment(inventory.createdAt),\n        typeEvent: 'inventory'\n      });\n    }\n  }\n\n  return events\n    .sort((a, b) => {\n      return b.createdAt.unix() - a.createdAt.unix();\n    })\n    .reduce((acc: any, cur: any) => {\n    const key = moment(cur.createdAt).startOf('month').format('YYYY-MM-DD');\n    acc[key] = acc[key] || [];\n    acc[key].push(cur);\n    return acc;\n  }, {});\n}\n","import {ICompany} from '../../../../../src/app/interfaces/company.interface';\nimport {CompaniesReduxAction, ICompaniesState} from '../actions/companies.actions';\n\nconst initialState: ICompaniesState = {\n  companies: [],\n  tempCompany: {\n    name: '',\n    businessName: '',\n    rut: '',\n    imageURI: null,\n    image: null,\n    markerURI: null,\n    marker: null,\n    billing: {\n      active: false,\n      inventoryPrice: 0.0,\n      checklistPrice: 0.0,\n      requestPrice: 0.0\n    },\n    notifications:[]\n  },\n  loading: true,\n  source: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function companiesReducer(state = initialState, action: CompaniesReduxAction): ICompaniesState {\n  switch (action.type) {\n    case '/COMPANIES/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/COMPANIES/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/COMPANIES/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/COMPANIES/CHANGE_TEMP_COMPANY':\n      return {\n        ...state,\n        tempCompany: action.payload.company\n      };\n    case '/COMPANIES/CHANGE_COMPANY':\n      return {\n        ...state,\n        companies: state.companies.map((company: ICompany) => {\n          if (company._id === action.payload.company._id) {\n            company.name = action.payload.company.name;\n            company.businessName = action.payload.company.businessName;\n            company.rut = action.payload.company.rut;\n            company.billing = action.payload.company.billing;\n            company.notifications = action.payload.company.notifications;\n            company.image = action.payload.company.image;\n            company.marker = action.payload.company.marker;\n          }\n          return company;\n        })\n      };\n    case '/COMPANIES/DELETE_COMPANY':\n      return {\n        ...state,\n        companies: state.companies.filter((company: ICompany) => company._id !== action.payload.id),\n        pagination: {\n          ...state.pagination,\n          count: state.pagination.count - 1\n        }\n      };\n    case '/COMPANIES/LOAD_COMPANIES':\n      return {\n        ...state,\n        companies: action.payload.companies,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {DashboardReduxAction, IDashboardState} from '../actions/dashboard.actions';\n\nconst initialState: IDashboardState = {\n  loading: true,\n  source: null,\n  participants: [],\n  requests: [],\n  companies:[],\n  car: null,\n  carEvents: {} ,\n  forms: [],\n  searchForms: [],\n  participantsReceivedPerDate: [],\n  participantsSentPerDate: [],\n  participantPerRange: [],\n  carsPerDate: [],\n  planningPerDate: [],\n  planningProcessPerDate: [],\n  searchText: '',\n  searchFrom: '',\n  searchTo: '',\n  carsByVenue: [],\n  totalCars: 0,\n  loadingParticipant: null,\n  revisionStats: null,\n  venueStats: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function dashboardReducer(state = initialState, action: DashboardReduxAction): IDashboardState {\n  switch (action.type) {\n    case '/DASHBOARD/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/DASHBOARD/LOAD_PARTICIPANTS':\n      return {\n        ...state,\n        participants: action.payload.participants,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    case '/DASHBOARD/CHANGE_SEARCH':\n      return {\n        ...state,\n        searchText: action.payload.searchText\n      };\n    case '/DASHBOARD/CHANGE_RANGE':\n      return {\n        ...state,\n        searchFrom: action.payload.from,\n        searchTo: action.payload.to,\n      };\n    case '/DASHBOARD/LOADING_PARTICIPANT':\n      return {\n        ...state,\n        loadingParticipant: action.payload.loadingParticipant\n      };\n    case '/DASHBOARD/LOAD_PARTICIPANTS_PER_DATE':\n      return {\n        ...state,\n        companies: action.payload.companies,\n        participantsReceivedPerDate: action.payload.participantsReceivedPerDate,\n        participantsSentPerDate: action.payload.participantsSentPerDate,\n        carsPerDate: action.payload.carsPerDate,\n        planningPerDate: action.payload.planningPerDate,\n        planningProcessPerDate: action.payload.planningProcessPerDate,\n        totalCars: action.payload.totalCars,\n        carsByVenue: action.payload.carsByVenue,\n        participantPerRange: action.payload.participantPerRange\n      };\n    case '/DASHBOARD/LOAD_CAR':\n      return {\n        ...state,\n        car: action.payload.car,\n      };\n    case '/DASHBOARD/LOAD_REQUESTS_IN_CAR':\n      return {\n        ...state,\n        requests: action.payload.requests\n      };\n    case '/DASHBOARD/LOAD_PARTICIPANT_IN_CAR':\n      if (state.car && state.car.participants) {\n        return {\n          ...state,\n          car: {\n            ...state.car,\n            participants: [action.payload.participant, ...state.car.participants]\n          }\n        };\n      } else {\n        return state;\n      }\n    case '/DASHBOARD/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/DASHBOARD/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/DASHBOARD/LOAD_VENUES_STATS':\n      return {\n        ...state,\n        venueStats: action.payload.venuesStats\n      };\n    case '/DASHBOARD/LOAD_REVISION_STATS':\n      return {\n        ...state,\n        revisionStats: action.payload.revisionStats\n      };\n    case '/DASHBOARD/LOAD_FORMS':\n      return {\n        ...state,\n        forms: action.payload.forms\n      };\n    case '/DASHBOARD/CHANGE_FORM_SEARCH':\n      return {\n        ...state,\n        searchForms: action.payload.searchForms\n      };\n    default:\n      return state;\n  }\n}\n","import {DashboardDamagesReduxAction, IDashboardDamagesState} from \"../actions/dashboardDamages.actions\";\n\nconst initialState: IDashboardDamagesState = {\n  data: {},\n  venues: [],\n  loading: true\n};\n\nexport function dashboardDamagesReducer(state = initialState, action: DashboardDamagesReduxAction): IDashboardDamagesState {\n  switch (action.type) {\n    case '/DASHBOARD/DAMAGES/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/DASHBOARD/DAMAGES/LOAD_DATA':\n      return {\n        ...state,\n        data: action.payload.data\n      };\n    default:\n      return state;\n  }\n}\n","import {DashboardDercoReduxAction, IDashboardDercoState} from \"../actions/dashboardDerco.actions\";\n\nconst initialState: IDashboardDercoState = {\n  cleaning: {\n    loading: false,\n    days: [],\n    clean: [],\n    notClean: [],\n  }\n};\n\nexport function dashboardDercoReducer(state = initialState, action: DashboardDercoReduxAction): IDashboardDercoState {\n  switch (action.type) {\n    case '/DASHBOARD/CLEANING/IS_LOADING':\n      return {\n        ...state,\n        cleaning: {\n          ...state.cleaning,\n          loading: true\n        },\n      };\n    case '/DASHBOARD/CLEANING/LOAD_DATA_DAILY':\n      return {\n        ...state,\n        cleaning: {\n          ...action.payload.cleaning,\n          loading: false\n        },\n\n      };\n\n    default:\n      return state;\n  }\n}\n","import {DashboardTimingReduxAction, IDashboardTimingState} from '../actions/dashboardTiming.actions';\n\nconst initialState: IDashboardTimingState = {\n  data: {\n    months: [],\n    overdue: [],\n    ontime: []\n  },\n  perVenue: {},\n  venues: [],\n  venuesDict: {},\n  loading: true,\n  loadingPerVenue: false\n};\n\nexport function dashboardTimingReducer(state = initialState, action: DashboardTimingReduxAction): IDashboardTimingState {\n  switch (action.type) {\n    case '/DASHBOARD/TIMING/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/DASHBOARD/TIMING/LOAD_DATA':\n      const venuesDict: any = {};\n      action.payload.venues.forEach((v: any) => venuesDict[v._id] = v );\n      return {\n        ...state,\n        loading: false,\n        venues: action.payload.venues,\n        venuesDict,\n        data: action.payload.data\n      };\n    case '/DASHBOARD/TIMING/IS_LOADING_PER_VENUE':\n      return {\n        ...state,\n        loadingPerVenue: true\n      };\n    default:\n      return state;\n  }\n}\n","import * as unorm from 'unorm';\nimport {\n  IInventoryCar\n} from '../../../../../src/inventory/interfaces/inventory.interface';\nimport {IInventoryState, InventoryReduxAction} from '../actions/inventory.actions';\n\nconst initialState: IInventoryState = {\n  inventories: [],\n  inventorySettings: {\n    report: null,\n    leftoverDifferentVenue: false,\n    pending: \"\",\n    pendingClass: \"aqua\",\n    pendingColor: \"\",\n    found: \"\",\n    foundClass: \"green\",\n    foundColor: \"\",\n    missing: \"\",\n    missingClass: \"red\",\n    missingColor: \"\",\n    leftover: \"\",\n    leftoverClass: \"yellow\",\n    leftoverColor: \"\",\n    reported: \"\",\n    reportedClass: \"gray-dark\",\n    reportedColor: \"\"\n  },\n  loading: true,\n  inventoryCar: null,\n  source: null,\n  loadingDetail: true,\n  fetchingDetail: false,\n  summary: {\n    _id: '',\n    name: '',\n    status: '',\n    createdAt: null,\n    finalizedAt: null\n  },\n  detail: {\n    venues: [],\n    cars: []\n  },\n  labels: [],\n  detailByVenue: [],\n  detailByBrand: [],\n  carsTable: [],\n  cardTypes: [],\n  cardProperties: [],\n  selectedItems: {},\n  filter: {\n    text: '',\n    property: '',\n    type: '',\n    venues: [],\n    states: []\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport interface IFilterCar {\n  text: string;\n  type: string;\n  property: string;\n  venues: string[];\n  states: string[];\n}\n\nexport function inventoriesReducer(state = initialState, action: InventoryReduxAction): IInventoryState {\n  switch (action.type) {\n    case '/INVENTORIES/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/INVENTORIES/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/INVENTORIES/LOAD_DATA':\n      return {\n        ...state,\n        inventories: action.payload.inventories,\n        inventorySettings: action.payload.inventorySettings,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    case '/INVENTORIES/UPDATE_INVENTORY_CAR':\n      return {\n        ...state,\n        inventoryCar: action.payload.inventoryCar\n      };\n    case '/INVENTORIES/CHANGE_FILTER':\n      return {\n        ...state,\n        carsTable: processCars(state.detail.cars, state.selectedItems, action.payload.filter),\n        filter: action.payload.filter\n      };\n    case '/INVENTORIES/CHANGE_SELECTED':\n      const newSelected = processSelected(state.selectedItems, action.payload.item);\n      return {\n        ...state,\n        selectedItems: newSelected,\n        carsTable: processCars(state.detail.cars, newSelected, state.filter)\n      };\n    case '/INVENTORIES/LOADING_INVENTORY_DETAIL':\n      return {\n        ...state,\n        loadingDetail: action.payload.loadingDetail\n      };\n    case '/INVENTORIES/FETCHING_INVENTORY_DETAIL':\n      return {\n        ...state,\n        fetchingDetail: action.payload.fetchingDetail\n      };\n    case '/INVENTORIES/LOAD_INVENTORY_DATA':\n      const selectedItems = action.payload.resetFilter ? initialState.selectedItems : state.selectedItems;\n      const filter = action.payload.resetFilter ? initialState.filter : state.filter;\n      return {\n        ...state,\n        ...processPropertyCars(action.payload.detail.cars),\n        carsTable: processCars(action.payload.detail.cars, selectedItems, filter),\n        selectedItems,\n        filter,\n        labels: action.payload.labels,\n        summary: action.payload.summary,\n        inventorySettings: action.payload.inventorySettings,\n        detailByVenue: action.payload.detailByVenue,\n        detail: action.payload.detail,\n        detailByBrand: action.payload.detailByBrand\n      };\n    case '/INVENTORIES/ADD_COMMENT':\n      if (state.inventoryCar) {\n        return {\n          ...state,\n          inventoryCar: {\n            ...state.inventoryCar,\n            comments: [...state.inventoryCar.comments, action.payload.inventoryComment]\n          }\n        };\n      } else {\n        return state;\n      }\n    default:\n      return state;\n  }\n}\n\nfunction processSelected(selectedItems: any, item: string) {\n  let newSelectedItems = {...selectedItems};\n  if (newSelectedItems.hasOwnProperty(item)) {\n    delete (newSelectedItems as any)[item];\n  } else {\n    newSelectedItems = {\n      ...newSelectedItems,\n      [item]: true\n    };\n  }\n  return newSelectedItems;\n}\n\ninterface IPropertyCar {\n  cardProperties: string[];\n  cardTypes: string[];\n}\n\nfunction processPropertyCars(cars: IInventoryCar[]): IPropertyCar {\n  const propertyCars: IPropertyCar = {\n    cardProperties: [],\n    cardTypes: []\n  };\n  for (const car of cars) {\n    if (car.car?.property && !propertyCars.cardProperties.includes(car.car.property)) {\n      propertyCars.cardProperties.push(car.car.property);\n    }\n    if (car.car?.type && !propertyCars.cardTypes.includes(car.car.type)) {\n      propertyCars.cardTypes.push(car.car.type);\n    }\n  }\n  return propertyCars;\n}\n\nfunction processCars(cars: IInventoryCar[], selectedItems: { [key: string]: any }, filter: IFilterCar) {\n  const products: any[] = [];\n  // const missincars = [];\n  for (const car of cars) {\n    let add = true;\n    if (filter && filter.venues && filter.venues.length && car.venue) {\n      add = (filter.venues as any).includes(car.venue._id);\n      if (!add && car.venueFound) {\n        add = (filter.venues as any).includes(car.venueFound._id);\n      }\n    }\n    if (add && filter && filter.states && filter.states.length && car.status) {\n      add = (filter.states as any).includes(car.status);\n    }\n    if (add && filter && filter.property && filter.property.length) {\n      add = car.car.property === filter.property;\n    }\n    if (add && filter && filter.type && filter.type.length) {\n      add = car.car.type === filter.type;\n    }\n    if (add && filter && filter.text && filter.text.length) {\n      const result: boolean[] = filter.text.toLowerCase().split(' ').map((text) => (\n        unorm.nfd(`${car.car.vin}${car.car.brand}${car.car.denomination}${car.car.patent}${car.car.internalNumber}`)\n          .replace(/[\\u0300-\\u036f]/g, '')\n          .toLowerCase()\n          .includes(text.toLowerCase())\n      ));\n      add = result.every((element: boolean) => element);\n      /*add = `${car.car.vin}${car.car.brand}${car.car.denomination}${car.car.patent}`.normalize('NFD')\n        .replace(/[\\u0300-\\u036f]/g, '')\n        .toLowerCase()\n        .includes(filter.text.toLowerCase());*/\n    }\n    const patent: string = car.car?.patent ? car.car.patent : '';\n    // if (add && filter && filter && filter.type.length) {\n    //   if (filter.type === 'new') {\n    //     add = patent.length === 0;\n    //   } else if (filter.type === 'used') {\n    //     add = patent.length !== 0;\n    //   }\n    // }\n    if (add && (car as any).car?._id) {\n      products.push({\n        _id: (car as any)._id,\n        carID: (car as any).car._id,\n        vin: car.car.vin,\n        brand: car.car.brand,\n        denomination: car.car.denomination,\n        internalNumber: car.car.internalNumber,\n        label: car.label,\n        labelName: car.label && car.label.hasOwnProperty('name') ? car.label.name : 'z',\n        labelBy: car.labelBy,\n        color: car.car.color,\n        labelText: car.labelText,\n        venue: car.venue ? car.venue.name : '-',\n        files: car.files && car.files.length ? car.files : [],\n        images: car.images && car.images.length ? car.images : [],\n        comments: car.comments && car.comments.length ? car.comments : [],\n        countComments: car.comments && car.comments.length ? car.comments.length : 0,\n        venueFound: car.venueFound ? car.venueFound.name : '-',\n        patent,\n        inventoriedBy: car.inventoriedBy ? `${car.inventoriedBy.firstName} ${car.inventoriedBy.lastName}` : '-',\n        selected: selectedItems.hasOwnProperty((car as any)._id),\n        status: car.status,\n        option: car.status\n      });\n    } else {\n      // if(car.status !==\"pending\"){\n        // console.log('car', car);\n        // missincars.push(car)\n      // }\n    }\n  }\n  // console.log('missincars', missincars);\n  return products;\n}\n","import {\n  IInventoryDashboardState,\n  InventoryDashboardReduxAction\n} from '../actions/inventoryDashboard.actions';\n\nconst initialState: IInventoryDashboardState = {\n  filter: {\n    text: '',\n    property: '',\n    type: '',\n    venues: [],\n    states: []\n  },\n  inventorySettings: {\n    report: null,\n    leftoverDifferentVenue: false,\n    pending: \"\",\n    pendingClass: \"aqua\",\n    pendingColor: \"\",\n    found: \"\",\n    foundClass: \"green\",\n    foundColor: \"\",\n    missing: \"\",\n    missingClass: \"red\",\n    missingColor: \"\",\n    leftover: \"\",\n    leftoverClass: \"yellow\",\n    leftoverColor: \"\",\n    reported: \"\",\n    reportedClass: \"gray-dark\",\n    reportedColor: \"\"\n  },\n  venues: [],\n  monthlyReport: [],\n  loading: true\n};\n\nexport function inventoriesDashboardReducer(state = initialState, action: InventoryDashboardReduxAction): IInventoryDashboardState {\n  switch (action.type) {\n    case '/INVENTORY_DASHBOARD/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/INVENTORY_DASHBOARD/LOAD_DATA':\n      return {\n        ...state,\n        loading: false,\n        venues: action.payload.venues,\n        inventorySettings: action.payload.inventorySettings,\n        monthlyReport: action.payload.monthlyReport\n      };\n    case '/INVENTORY_DASHBOARD/LOAD_DATA_FILTERED':\n      return {\n        ...state,\n        inventorySettings: action.payload.inventorySettings,\n        filter: {\n          ...action.payload.filter,\n          venues: action.payload.filter.venues,\n        },\n        monthlyReport: action.payload.monthlyReport\n      };\n    default:\n      return state;\n  }\n}\n","import {ILabelsState, LabelsReduxAction} from '../actions/labels.actions';\n\nconst initialState: ILabelsState = {\n  labels: [],\n  inventorySettings: {\n    report: null,\n    leftoverDifferentVenue: false,\n    pending: \"\",\n    pendingClass: \"aqua\",\n    pendingColor: \"\",\n    found: \"\",\n    foundClass: \"green\",\n    foundColor: \"\",\n    missing: \"\",\n    missingClass: \"red\",\n    missingColor: \"\",\n    leftover: \"\",\n    leftoverClass: \"yellow\",\n    leftoverColor: \"\",\n    reported: \"\",\n    reportedClass: \"gray-dark\",\n    reportedColor: \"\"\n  },\n  loading: true,\n  tempLabel: {\n    _id: '',\n    description: '',\n    name: '',\n    color: '',\n    affected: [],\n    sendTo: '',\n    requireCustomText: false,\n    isExhibition: false,\n    active: true\n  },\n  source: null,\n  pagination: {\n     count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function labelsReducer(state = initialState, action: LabelsReduxAction): ILabelsState {\n  switch (action.type) {\n    case '/LABELS/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/LABELS/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/LABELS/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/LABELS/CHANGE_TEMP_LABEL':\n      return {\n        ...state,\n        tempLabel: action.payload.tempLabel\n      };\n    case '/LABELS/CREATE_LABEL':\n      return {\n        ...state,\n        labels: [action.payload.label, ...state.labels],\n        pagination: {\n          ...state.pagination,\n          count: state.pagination.count + 1\n        }\n      };\n    case '/LABELS/CHANGE_LABEL':\n      return {\n        ...state,\n        labels: state.labels.map((label) => {\n          if (label._id === action.payload.label._id) {\n            return action.payload.label;\n          }\n          return label;\n        })\n      };\n    case '/LABELS/DELETE_LABEL':\n      return {\n        ...state,\n        labels: state.labels.filter((label: any) => label._id !== action.payload.id),\n        pagination: {\n          ...state.pagination,\n          count: state.pagination.count - 1\n        }\n      };\n    case '/LABELS/LOAD_LABELS':\n      return {\n        ...state,\n        labels: action.payload.labels,\n        inventorySettings: action.payload.inventorySettings,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {IModalState, ModalReduxAction} from '../actions/modal.actions';\n\nconst initialState: IModalState = {\n  title: '',\n  body: null,\n  footer: null\n};\n\nexport function modalReducer(state = initialState, action: ModalReduxAction): IModalState {\n  switch (action.type) {\n    case '/MODAL/LOAD_DATA':\n      setTimeout(() => {\n        ($('#andesModal') as any).modal('show');\n      }, 100);\n      return {\n        ...state,\n        title: action.payload.title,\n        body: action.payload.body,\n        footer: action.payload.footer ? action.payload.footer : null\n      };\n    case '/MODAL/CLEAR':\n      return initialState;\n    default:\n      return state;\n  }\n}\n","import {IPlanningState, PlanningReduxAction} from \"../actions/planning.action\";\n\nconst initialState: IPlanningState = {\n  plannings: [],\n  loading: true,\n  source: null,\n  pagination: {\n     count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function planningReducer(state = initialState, action: PlanningReduxAction): IPlanningState {\n  switch (action.type) {\n    case '/PLANNING/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/PLANNING/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/PLANNING/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/PLANNING/LOAD_PLANNING':\n      return {\n        ...state,\n        plannings: action.payload.plannings,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {\n  IReasonsState,\n  ReasonsReduxActions,\n  REASON_CANCEL_REASON,\n  REASON_CHANGE_ORDER,\n  REASON_IS_LOADING,\n  REASON_LOAD_REASONS\n} from '../actions/reasons.types';\n\nconst initialState: IReasonsState = {\n  reasons: [],\n  reason: {},\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function reasonsReducers(state = initialState, action: ReasonsReduxActions): IReasonsState {\n  switch (action.type) {\n    case REASON_CANCEL_REASON:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case REASON_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case REASON_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case REASON_LOAD_REASONS:\n      return {\n        ...state,\n        reasons: action.payload.reasons,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {RegionReduxAction, IRegionsState} from '../actions/regions.actions';\n\nconst initialState: IRegionsState = {\n  regions: [],\n  tempRegion: {\n    name: '',\n    code: ''\n  },\n  loading: true,\n  source: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function regionsReducer(state = initialState, action: RegionReduxAction): IRegionsState {\n  switch (action.type) {\n    case '/REGIONS/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/REGIONS/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/REGIONS/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/REGIONS/CHANGE_TEMP_REGION':\n      return {\n        ...state,\n        tempRegion: action.payload.region\n      };\n    case '/REGIONS/LOAD_REGIONS':\n      return {\n        ...state,\n        regions: action.payload.regions,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {\n  IRequestItemsState,\n  RequestItemsReduxActions,\n  REQUEST_ITEMS_CANCEL_REQUEST,\n  REQUEST_ITEMS_CHANGE_FILTER,\n  REQUEST_ITEMS_CHANGE_ORDER,\n  REQUEST_ITEMS_CREATE_ITEM,\n  REQUEST_ITEMS_DELETE_ITEM,\n  REQUEST_ITEMS_IS_LOADING,\n  REQUEST_ITEMS_LOAD_CARRIERS,\n  REQUEST_ITEMS_LOAD_ITEM_STATUS,\n  REQUEST_ITEMS_LOAD_PROPERTIES,\n  REQUEST_ITEMS_LOAD_REASONS,\n  REQUEST_ITEMS_LOAD_REQUESTS_ITEMS,\n  REQUEST_ITEMS_LOAD_VENUES,\n  REQUEST_ITEMS_UPDATE_ITEM, REQUEST_ITEMS_LOAD_SETTINGS, REQUEST_ITEMS_LOAD_USERS\n} from '../actions/requestItems.types';\nimport { requestSettings } from '../components/Request/defaults';\nimport * as moment from 'moment';\n\nconst initialState: IRequestItemsState = {\n  requestItems: [],\n  reasons: [],\n  carriers: [],\n  venues: [],\n  users: [],\n  properties: [],\n  requestItemStatus: [],\n  requestItemStatusMin: 0,\n  requestItemStatusMax: 100,\n  loading: true,\n  source: null,\n  requestSettings,\n  filters: {\n    request: '',\n    ticket: '',\n    entry: '',\n    text: '',\n    sellerText: '',\n    venues: [],\n    users: [],\n    properties: [],\n    status: [],\n    from: moment().subtract(6, 'months'),\n    to: null\n  },\n  options: {\n    orderBy: 'meta.request.number',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function requestItemsReducers(state = initialState, action: RequestItemsReduxActions): IRequestItemsState {\n  switch (action.type) {\n    case REQUEST_ITEMS_CANCEL_REQUEST:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case REQUEST_ITEMS_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case REQUEST_ITEMS_LOAD_REASONS:\n      return {\n        ...state,\n        reasons: action.payload.reasons\n      };\n    case REQUEST_ITEMS_LOAD_CARRIERS:\n      return {\n        ...state,\n        carriers: action.payload.carriers\n      };\n    case REQUEST_ITEMS_LOAD_VENUES:\n      return {\n        ...state,\n        venues: action.payload.venues\n      };\n    case REQUEST_ITEMS_LOAD_USERS:\n      return {\n        ...state,\n        users: action.payload.users\n      };\n    case REQUEST_ITEMS_LOAD_PROPERTIES:\n        return {\n          ...state,\n          properties: action.payload.properties\n        };\n    case REQUEST_ITEMS_LOAD_SETTINGS:\n      return {\n        ...state,\n        requestSettings: action.payload.requestSettings\n      };\n    case REQUEST_ITEMS_LOAD_ITEM_STATUS:\n      return {\n        ...state,\n        requestItemStatus: action.payload.requestItemStatus,\n        requestItemStatusMin: action.payload.min,\n        requestItemStatusMax: action.payload.max\n      };\n    case REQUEST_ITEMS_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case REQUEST_ITEMS_CHANGE_FILTER:\n      return {\n        ...state,\n        filters: {\n          ...state.filters,\n          [action.payload.key]: action.payload.value\n        }\n      };\n    case REQUEST_ITEMS_LOAD_REQUESTS_ITEMS:\n      return {\n        ...state,\n        requestItems: action.payload.requestItems,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    case REQUEST_ITEMS_CREATE_ITEM:\n      return {\n        ...state,\n        requestItems: [action.payload.item, ...state.requestItems]\n      };\n    case REQUEST_ITEMS_UPDATE_ITEM:\n      return {\n        ...state,\n        requestItems: [...state.requestItems.map((item) => {\n          if (item._id === action.payload.item._id) {\n            return {\n              item,\n              ...action.payload.item\n            };\n          }\n          return item;\n        })]\n      };\n    case REQUEST_ITEMS_DELETE_ITEM:\n      return {\n        ...state,\n        requestItems: [...state.requestItems.filter((item) => {\n          return item._id !== action.payload.item._id;\n        })]\n      };\n    default:\n      return state;\n  }\n}\n","import * as moment from 'moment-timezone';\nimport {\n  IRequestsState,\n  REQUEST_CANCEL_REQUEST,\n  REQUEST_CHANGE_ORDER,\n  REQUEST_CREATE_REQUEST_ITEM_IN_DETAIL,\n  REQUEST_CREATE_REQUEST_ITEM_IN_LIST,\n  REQUEST_DELETE_REQUEST_IN_LIST,\n  REQUEST_DELETE_REQUEST_ITEM_IN_DETAIL,\n  REQUEST_DELETE_REQUEST_ITEM_IN_LIST,\n  REQUEST_IS_LOADING,\n  REQUEST_LOAD_CARRIERS, REQUEST_LOAD_ITEMS,\n  REQUEST_LOAD_REASONS,\n  REQUEST_LOAD_REQUEST,\n  REQUEST_LOAD_REQUEST_ITEM_STATUS,\n  REQUEST_LOAD_REQUESTS,\n  REQUEST_LOAD_SETTINGS,\n  REQUEST_TAB_STATUS,\n  REQUEST_UDPATE_REQUEST_ITEM_IN_DETAIL,\n  REQUEST_UDPATE_REQUEST_ITEM_IN_LIST,\n  RequestsReduxActions\n} from '../actions/requests.types';\nimport { requestSettings } from '../components/Request/defaults';\n\nconst initialState: IRequestsState = {\n  requests: [],\n  requestItems: [],\n  reasons: [],\n  carriers: [],\n  requestOpen: [],\n  requestItemsById: {},\n  requestItemStatus: [],\n  requestItemStatusMin: 0,\n  requestItemStatusMax: 100,\n  request: {},\n  loading: true,\n  source: null,\n  requestSettings,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function requestsReducers(state = initialState, action: RequestsReduxActions): IRequestsState {\n  switch (action.type) {\n    case REQUEST_CANCEL_REQUEST:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case REQUEST_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case REQUEST_LOAD_REASONS:\n      return {\n        ...state,\n        reasons: action.payload.reasons\n      };\n    case REQUEST_LOAD_CARRIERS:\n      return {\n        ...state,\n        carriers: action.payload.carriers\n      };\n    case REQUEST_LOAD_SETTINGS:\n      return {\n        ...state,\n        requestSettings: action.payload.requestSettings\n      };\n    case REQUEST_TAB_STATUS:\n      return {\n        ...state,\n        requestOpen: state.requestOpen.includes(action.payload.request)\n          ? [...state.requestOpen.filter(request => request !== action.payload.request)]\n          : [...state.requestOpen, action.payload.request]\n      };\n    case REQUEST_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case REQUEST_LOAD_REQUEST_ITEM_STATUS:\n      return {\n        ...state,\n        requestItemStatus: action.payload.requestItemStatus,\n        requestItemStatusMin: action.payload.min,\n        requestItemStatusMax: action.payload.max\n      };\n    case REQUEST_LOAD_REQUESTS:\n      return {\n        ...state,\n        requests: action.payload.requests,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    case REQUEST_CREATE_REQUEST_ITEM_IN_LIST:\n      return {\n        ...state,\n        requests: [...state.requests].map((request) => {\n          if (request._id === action.payload.idRequest) {\n            request.updatedAt = moment().toDate();\n            request.items = [...request.items, action.payload.item];\n          }\n          return request;\n        })\n      };\n    case REQUEST_LOAD_ITEMS:\n      return {\n        ...state,\n        requestItemsById: {\n          ...state.requestItemsById,\n          [action.payload.request]: action.payload.items\n        }\n      };\n    case REQUEST_UDPATE_REQUEST_ITEM_IN_LIST:\n      let updateItem: any = {};\n      if(state.requestItemsById.hasOwnProperty(action.payload.request)){\n        updateItem[action.payload.request] = state.requestItemsById[action.payload.request].map((item:any)=>{\n          if(item._id === action.payload.item._id){\n            return action.payload.item\n          }\n          return item;\n        })\n      }\n      return {\n        ...state,\n        requestItemsById: {\n          ...state.requestItemsById,\n          ...updateItem\n        }\n      };\n    case REQUEST_DELETE_REQUEST_ITEM_IN_LIST:\n      return {\n        ...state,\n        requests: [...state.requests].map((request) => {\n          if (request._id === action.payload.idRequest) {\n            request.updatedAt = moment().toDate();\n            request.items = request.items.filter((item) => {\n              return item._id !== action.payload.item._id;\n            });\n          }\n          return request;\n        })\n      };\n    case REQUEST_CREATE_REQUEST_ITEM_IN_DETAIL:\n      return {\n        ...state,\n        request: {\n          ...state.request,\n          items: [...state.request.items!, action.payload.item]\n        }\n      };\n    case REQUEST_UDPATE_REQUEST_ITEM_IN_DETAIL:\n      return {\n        ...state,\n        request: {\n          ...state.request,\n          items: [...state.request!.items!.map((item) => {\n            if (item._id === action.payload.item._id) {\n              return {\n                item,\n                ...action.payload.item\n              };\n            }\n            return item;\n          })]\n        }\n      };\n    case REQUEST_DELETE_REQUEST_ITEM_IN_DETAIL:\n      return {\n        ...state,\n        request: {\n          ...state.request,\n          items: [...state.request.items!.filter((item) => {\n            return item._id !== action.payload.item._id;\n          })]\n        }\n      };\n    case REQUEST_DELETE_REQUEST_IN_LIST:\n      return {\n        ...state,\n        requests: [...state.requests].filter((request) => {\n          return request._id !== action.payload.id;\n        })\n      };\n    case REQUEST_LOAD_REQUEST:\n      return {\n        ...state,\n        request: action.payload.request\n      };\n    default:\n      return state;\n  }\n}\n","import {IStockState, StockReducerAction} from \"../actions/stock.actions\";\nimport * as unorm from \"unorm\";\nimport {IInventoryCar} from '../../../../../src/inventory/interfaces/inventory.interface';\nimport * as moment from 'moment-timezone';\n\nconst initialState: IStockState = {\n  cars: [],\n  carsTable: [],\n  filter: {\n    text: '',\n    property: '',\n    type: '',\n    venues: [],\n    colors: [],\n    brands: [],\n    denominations: []\n  },\n  dataFilters:{\n    venues:[],\n    colors:[],\n    brands:[],\n    denominations:[],\n    types:[],\n    properties:[],\n  },\n  vinInStock: {},\n  searching: false,\n  message: \"\",\n  loading: true,\n  source: null\n};\n\nexport interface IFilterStock {\n  text: string;\n  type: string;\n  property: string;\n  venues: string[];\n  colors: string[];\n  brands: string[];\n  denominations: string[];\n}\n\n\nexport function stockReducer(state = initialState, action: StockReducerAction) {\n  switch (action.type) {\n    case '/STOCK/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/STOCK/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n     case '/STOCK/CHANGE_FILTER':\n      return {\n        ...state,\n        ...processCars(state.cars, action.payload.filter),\n        filter: action.payload.filter,\n        searching: isSearching(action.payload.filter)\n      };\n    case '/STOCK/LOAD':\n      return {\n        ...state,\n        cars: action.payload.cars,\n        ...processCars(action.payload.cars, state.filter),\n        dataFilters: processfilters(action.payload.cars),\n        message: action.payload.message\n      };\n    default:\n      return state;\n  }\n}\n\nfunction isSearching(filter: IFilterStock){\n  const {text, brands, venues, colors, denominations, property, type} = filter;\n  if(text.length || brands.length || venues.length || colors.length || denominations.length || property.length || type.length) {\n    return true\n  }\n  return false;\n\n}\n\nfunction processfilters(cars:IInventoryCar[]){\n  const venues: any[] = [],\n    colors: any[] = [],\n    brands: any[] = [],\n    denominations: any[] = [],\n    types: any[] = [],\n    properties: any[] = [];\n  const venuesKeys: string[] = [],\n    colorsKeys: string[] = [],\n    brandsKeys: string[] = [],\n    denominationsKeys: string[] = [],\n    typesKeys: string[] = [],\n    propertiesKeys: string[] = [];\n\n  for (const car of cars) {\n    const {color, property, type, brand, denomination} = car.car;\n    const {venueFound, venue} = car;\n    if (brand && brand.length && !brandsKeys.includes(brand)) {\n      brandsKeys.push(brand);\n      brands.push(brand);\n    }\n    if (color && color.length && !colorsKeys.includes(color)) {\n      colorsKeys.push(color);\n      colors.push(color);\n    }\n    if (denomination && denomination.length && !denominationsKeys.includes(denomination)) {\n      denominationsKeys.push(denomination);\n      denominations.push(denomination);\n    }\n    if (type && type.length && !typesKeys.includes(type)) {\n      typesKeys.push(type);\n      types.push(type);\n    }\n    if (property && property.length && !propertiesKeys.includes(property)) {\n      propertiesKeys.push(property);\n      properties.push(property);\n    }\n    if (venueFound && !venuesKeys.includes(venueFound._id)) {\n      venuesKeys.push(venueFound._id);\n      venues.push(venueFound);\n    }\n    if (venue && !venuesKeys.includes(venue._id)) {\n      venuesKeys.push(venue._id);\n      venues.push(venue);\n    }\n\n  }\n  return {\n    venues: venues.sort(function(a, b){\n      if(a.name < b.name) { return -1; }\n      if(a.name > b.name) { return 1; }\n      return 0;\n    }),\n    colors: colors.sort(),\n    brands: brands.sort(),\n    denominations: denominations.sort(),\n    types: types.sort(),\n    properties: properties.sort()\n  }\n}\n\nfunction processCars(cars: IInventoryCar[], filter: IFilterStock): { carsTable: any[]; vinInStock: any; } {\n  const data: any[] = [];\n  let vinInStock: any = {};\n  for (const car of cars) {\n    let add = true;\n    if (filter && filter.venues && filter.venues.length && car.venue) {\n      add = (filter.venues as any).includes(car.venue._id);\n      if (!add && car.venueFound) {\n        add = (filter.venues as any).includes(car.venueFound._id);\n      }\n    }\n    if (add && filter && filter.brands && filter.brands.length && car.car.brand) {\n      add = (filter.brands as any).includes(car.car.brand);\n    }\n    if (add && filter && filter.denominations && filter.denominations.length && car.car.denomination) {\n      add = (filter.denominations as any).includes(car.car.denomination);\n    }\n    if (add && filter && filter.colors && filter.colors.length && car.car.color) {\n      add = (filter.colors as any).includes(car.car.color);\n    }\n    if (add && filter && filter.property && filter.property.length) {\n      add = car.car.property === filter.property;\n    }\n    if (add && filter && filter.type && filter.type.length) {\n      add = car.car.type === filter.type;\n    }\n    if (add && filter && filter.text && filter.text.length) {\n      const result: boolean[] = filter.text.toLowerCase().split(' ').map((text) => (\n        unorm.nfd(`${car.car.vin}${car.car.brand}${car.car.color}${car.car.denomination}${car.car.patent}${car.car.internalNumber}`)\n          .replace(/[\\u0300-\\u036f]/g, '')\n          .toLowerCase()\n          .includes(text.toLowerCase())\n      ));\n      add = result.every((element: boolean) => element === true) === true;\n    }\n\n    const patent: string = car.car.patent ? car.car.patent : '';\n    if (add) {\n      const {vin} = car.car;\n      if (!vinInStock.hasOwnProperty(vin)) {\n        vinInStock[vin] = {\n        }\n      }\n      const venueFoundID = car.venueFound ? car.venueFound._id : '-';\n      let daysInVenue = null;\n      let receptionVenue = null;\n      if (car.car?.meta?.location?.venue && car.car.meta.location.venue._id === venueFoundID) {\n        receptionVenue = car.car.meta.location.checkedDate;\n        daysInVenue = moment().diff(moment(receptionVenue), 'days');\n      }\n\n      data.push({\n        _id: (car as any)._id,\n        carID: (car as any).car._id,\n        vin: car.car.vin,\n        brand: car.car.brand,\n        denomination: car.car.denomination,\n        internalNumber: car.car.internalNumber,\n        label: car.label,\n        labelName: car.label && car.label.hasOwnProperty('name') ? car.label.name : 'z',\n        labelBy: car.labelBy,\n        color: car.car.color,\n        labelText: car.labelText,\n        meta: car.car.meta,\n        venue: car.venue ? car.venue.name : '-',\n        images: car.images && car.images.length ? car.images : [],\n        comments: car.comments && car.comments.length ? car.comments : [],\n        countComments: car.comments && car.comments.length ? car.comments.length : 0,\n        venueFoundID,\n        venueFound: car.venueFound ? car.venueFound.name : '-',\n        receptionVenue,\n        daysInVenue,\n        patent,\n        inventoriedBy: car.inventoriedBy ? `${car.inventoriedBy.firstName} ${car.inventoriedBy.lastName}` : '-',\n        status: car.status,\n        option: car.status\n      });\n    }\n  }\n  return {\n    carsTable: data,\n    vinInStock\n  };\n}\n\n","import {\n  IUsersState,\n  UserReduxAction\n} from '../actions/users.actions';\n\nimport {IUser} from '../../../../../src/app/interfaces/user.interface';\n\nconst initialState: IUsersState = {\n  users: [],\n  venues: [],\n  companies: [],\n  searchText: '',\n  permissions: [],\n  forms: [],\n  channels: [],\n  loading: true,\n  tempUser: {\n    _id: '',\n    isAdmin: false,\n    isDriver: false,\n    firstName: '',\n    company: null,\n    lastName: '',\n    email: '',\n    settings: {},\n    userPermissions: [],\n    userForms: [],\n    venuesAccess: []\n  },\n  source: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function usersReducer(state = initialState, action: UserReduxAction): IUsersState {\n  switch (action.type) {\n    case '/USERS/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/USERS/LOAD_VENUES':\n      return {\n        ...state,\n        venues: action.payload.venues\n      };\n    case '/USERS/LOAD_PERMISSIONS':\n      return {\n        ...state,\n        permissions: action.payload.permissions\n      };\n    case '/USERS/CHANGE_SEARCH':\n      return {\n        ...state,\n        searchText: action.payload.searchText\n      };\n    case '/USERS/LOAD_FORMS':\n      return {\n        ...state,\n        forms: action.payload.forms\n      };\n    case '/USERS/LOAD_CHANNELS':\n      return {\n        ...state,\n        channels: action.payload.channels\n      };\n    case '/USERS/LOAD_COMPANIES':\n      return {\n        ...state,\n        companies: action.payload.companies\n      };\n    case '/USERS/CHANGE_TEMP_USER':\n      return {\n        ...state,\n        tempUser: action.payload.user\n      };\n    case '/USERS/CHANGE_USER':\n      return {\n        ...state,\n        users: state.users.map((user) => (user._id === action.payload.user._id ? action.payload.user : user))\n      };\n    case '/USERS/LOAD_USERS':\n      return {\n        ...state,\n        users: action.payload.users,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    case '/USERS/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/USERS/DELETE_USER':\n      return {\n        ...state,\n        users: state.users.filter((user: IUser) => user._id !== action.payload.id),\n        pagination: {\n          ...state.pagination,\n          count: state.pagination.count - 1\n        }\n      };\n    case '/USERS/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import { IRequestStatusState,\n  RequestStatusReduxActions,\n  REQUEST_CANCEL_STATUS,\n  REQUEST_CHANGE_ORDER,\n  REQUEST_IS_LOADING,\n  REQUEST_LOAD_STATUS\n} from '../actions/requestStatus.types';\n\nconst initialState: IRequestStatusState = {\n  status: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function requestStatusReducer(state = initialState, action: RequestStatusReduxActions): IRequestStatusState {\n  switch (action.type) {\n    case REQUEST_CANCEL_STATUS:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case REQUEST_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case REQUEST_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case REQUEST_LOAD_STATUS:\n      return {\n        ...state,\n        status: action.payload.status,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import { ISalesChannelState,\n  RequestChannelReduxActions,\n  REQUEST_CANCEL_CHANNEL,\n  REQUEST_CHANGE_ORDER,\n  REQUEST_IS_LOADING,\n  REQUEST_LOAD_CHANNEL\n} from '../actions/requestChannel.types';\n\nconst initialState: ISalesChannelState = {\n  channels: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function requestChannelReducer(state = initialState, action: RequestChannelReduxActions): ISalesChannelState {\n  switch (action.type) {\n    case REQUEST_CANCEL_CHANNEL:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case REQUEST_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case REQUEST_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case REQUEST_LOAD_CHANNEL:\n      return {\n        ...state,\n        channels: action.payload.channels,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {\n  IPaymentMethodState,\n  PAYMENT_METHOD_CANCEL,\n  PAYMENT_METHOD_CHANGE_ORDER,\n  PAYMENT_METHOD_IS_LOADING,\n  PAYMENT_METHOD_LOAD,\n  PaymentMethodReduxActions\n} from '../actions/paymentMethod.types';\n\nconst initialState: IPaymentMethodState = {\n  paymentMethods: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function paymentMethodReducer(state = initialState, action: PaymentMethodReduxActions): IPaymentMethodState {\n  switch (action.type) {\n    case PAYMENT_METHOD_CANCEL:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case PAYMENT_METHOD_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case PAYMENT_METHOD_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case PAYMENT_METHOD_LOAD:\n      return {\n        ...state,\n        paymentMethods: action.payload.paymentMethods,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {IVenue} from '../../../../../src/app/interfaces/venue.interface';\nimport {IVenuesState, VenueReduxAction} from '../actions/venues.actions';\n\nconst initialState: IVenuesState = {\n  venues: [],\n  allVenues: [],\n  companies: [],\n  carriers: [],\n  regions: [],\n  searchText: '',\n  loading: true,\n  source: null,\n  users: [],\n  tempVenue: {\n    _id: '',\n    lat: 0,\n    lng: 0,\n    name: '',\n    code: '',\n    abbreviation: '',\n    type: 'receiver',\n    responsible: [],\n    sendToDays: [],\n    sendTo: [],\n    shippingMaxDays: 5,\n    receiveFrom: [],\n    shippingCarriers: [],\n    receptionCarriers: []\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function venuesReducer(state = initialState, action: VenueReduxAction): IVenuesState {\n  switch (action.type) {\n    case '/VENUES/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/VENUES/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/VENUES/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/VENUES/CHANGE_SEARCH':\n      return {\n        ...state,\n        searchText: action.payload.searchText\n      };\n    case '/VENUES/LOAD_COMPANIES':\n      return {\n        ...state,\n        companies: action.payload.companies\n      };\n    case '/VENUES/LOAD_ALL_VENUES':\n      return {\n        ...state,\n        allVenues: action.payload.allVenues\n      };\n    case '/VENUES/LOAD_CARRIERS':\n      return {\n        ...state,\n        carriers: action.payload.carriers\n      };\n    case '/VENUES/LOAD_REGIONS':\n      return {\n        ...state,\n        regions: action.payload.regions\n      };\n    case '/VENUES/CHANGE_VENUE':\n      return {\n        ...state,\n        venues: state.venues.map((venue: IVenue) => {\n          if (venue._id === action.payload.venue._id) {\n            venue.name = action.payload.venue.name;\n            venue.code = action.payload.venue.code;\n            venue.abbreviation = action.payload.venue.abbreviation;\n            venue.company = action.payload.venue.company;\n            venue.type = action.payload.venue.type;\n            venue.sendToDays = action.payload.venue.sendToDays;\n            venue.sendTo = action.payload.venue.sendTo;\n            venue.shippingMaxDays = action.payload.venue.shippingMaxDays;\n            venue.receiveFrom = action.payload.venue.receiveFrom;\n          }\n          return venue;\n        })\n      };\n    case '/VENUES/CHANGE_TEMP_VENUE':\n      return {\n        ...state,\n        tempVenue: action.payload.venue\n      };\n    case '/VENUES/DELETE_VENUE':\n      return {\n        ...state,\n        venues: state.venues.filter((venue: IVenue) => venue._id !== action.payload.id),\n        pagination: {\n          ...state.pagination,\n          count: state.pagination.count - 1\n        }\n      };\n    case '/VENUES/LOAD_VENUES':\n      return {\n        ...state,\n        venues: action.payload.venues,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    case \"/VENUES/LOAD_USERS\":\n      return {\n        ...state,\n        users: action.payload.users\n      };\n    default:\n      return state;\n  }\n}\n","import {IVersionsState, VersionReduxAction} from \"../actions/versions.actions\";\n\nconst initialState: IVersionsState = {\n  versions: [],\n  loading: true,\n  source: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function versionsReducer(state = initialState, action: VersionReduxAction): IVersionsState {\n  switch (action.type) {\n    case '/VERSIONS/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/ALERTS/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/VERSIONS/CREATE':\n      return {\n        ...state,\n        versions: [action.payload.version, ...state.versions]\n      };\n    case '/VERSIONS/LOAD_DATA':\n      return {\n        ...state,\n        versions: action.payload.versions\n      };\n    default:\n      return state;\n  }\n}\n","import {\n  CANCEL_REQUEST_TRANSMITTAL,\n  CHANGE_ORDER_TRANSMITTAL, CREATE_TRANSMITTAL_ITEM_TRANSMITTAL,\n  DELETE_TRANSMITTAL_ITEM_TRANSMITTAL, DELETE_TRANSMITTAL_TRANSMITTAL,\n  FILTER_REQUEST_ITEMS_TRANSMITTAL,\n  ITransmittalActionTypes,\n  ITransmittalState,\n  LOAD_CARRIERS_TRANSMITTAL,\n  LOAD_DRIVERS_TRANSMITTAL, LOAD_MILESTONE_TYPES_TRANSMITTAL,\n  LOAD_REQUEST_ITEMS_TRANSMITTAL,\n  LOAD_TRANSMITTAL,\n  LOAD_VENUES_TRANSMITTAL,\n  LOADING_REQUEST_ITEMS_TRANSMITTAL,\n  LOADING_TRANSMITTAL,\n  TOOGLE_TAB_TRANSMITTAL,\n  UPDATE_TRANSMITTAL_ITEM_TRANSMITTAL,\n  UPDATE_TRANSMITTAL_TRANSMITTAL,\n  TRANSPORT_MILESTONE_LOAD_STATUS\n} from '../actions/transmittal.types';\nimport {ITransmittal} from '../../../../../src/distribution/interfaces/transmittal.interface';\n\nconst initialState: ITransmittalState<ITransmittal> = {\n  loading: true,\n  requestItemsLoading: true,\n  data: [],\n  carriers: [],\n  venues: [],\n  drivers: [],\n  milestoneTypes: [],\n  milestones: [],\n  transmittalOpen: [],\n  source: null,\n  requestItems: [],\n  requestItemsfilters: {\n    request: '',\n    entry: '',\n    text: '',\n    venues: [],\n    properties: [],\n    status: [],\n    from: null,\n    to: null\n  },\n  requestItemsPagination: {\n    count: 0,\n    page: 1,\n    pages: 0\n  },\n  options: {\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 0\n  }\n};\n\nexport default function transmittalReducer(state= initialState, action: ITransmittalActionTypes): ITransmittalState {\n  switch (action.type) {\n    case LOADING_TRANSMITTAL:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case LOAD_TRANSMITTAL:\n      return {\n        ...state,\n        data: action.payload.data,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    case DELETE_TRANSMITTAL_ITEM_TRANSMITTAL:\n      return  {\n        ...state,\n        data: state.data.map<ITransmittal>((transmittal: any) => {\n          if (transmittal._id === action.payload.transmittalItem?.transmittal) {\n            return {\n              ...transmittal,\n              items: transmittal.items.filter((item: any) => {\n                return item._id !== action.payload.transmittalItem._id;\n              })\n            };\n          }\n          return transmittal;\n        })\n      };\n    case DELETE_TRANSMITTAL_TRANSMITTAL:\n      return {\n        ...state,\n        data: state.data.filter((transmittal: any) => {\n          return transmittal._id !== action.payload.transmittal._id;\n        })\n      };\n    case UPDATE_TRANSMITTAL_TRANSMITTAL:\n      return {\n        ...state,\n        data: state.data.map<ITransmittal>((transmittal: any) => {\n          if (transmittal._id === action.payload.transmittal._id) {\n            return {\n              ...transmittal,\n              ...action.payload.transmittal\n            };\n          } else {\n            return transmittal;\n          }\n        })\n      };\n    case CREATE_TRANSMITTAL_ITEM_TRANSMITTAL:\n      return {\n        ...state,\n        data: state.data.map<ITransmittal>((transmittal: any) => {\n          if (transmittal._id === action.payload.transmittalItem?.transmittal) {\n            return {\n              ...transmittal,\n              items: [...transmittal.items, action.payload.transmittalItem]\n            };\n          }\n          return transmittal;\n        })\n      };\n    case UPDATE_TRANSMITTAL_ITEM_TRANSMITTAL:\n      return  {\n        ...state,\n        data: state.data.map<ITransmittal>((transmittal: any) => {\n          if (transmittal._id === action.payload.transmittalItem?.transmittal) {\n            return {\n              ...transmittal,\n              items: transmittal.items.map((item: any) => {\n                if (item._id === action.payload.transmittalItem._id) {\n                  return {\n                    ...item,\n                    ...action.payload.transmittalItem\n                  };\n                }\n                return item;\n              })\n            };\n          }\n          return transmittal;\n        })\n      };\n    case LOAD_CARRIERS_TRANSMITTAL:\n      return {\n        ...state,\n        carriers: action.payload.carriers,\n      };\n    case LOAD_DRIVERS_TRANSMITTAL:\n      return {\n        ...state,\n        drivers: action.payload.drivers,\n      };\n    case LOAD_MILESTONE_TYPES_TRANSMITTAL:\n      return {\n        ...state,\n        milestoneTypes: action.payload.milestoneTypes,\n      };\n    case LOAD_VENUES_TRANSMITTAL:\n      return {\n        ...state,\n        venues: action.payload.venues,\n      };\n    case TOOGLE_TAB_TRANSMITTAL:\n      return {\n        ...state,\n        transmittalOpen: state.transmittalOpen.includes(action.payload.transmittalId) ?\n          state.transmittalOpen.filter(id => id !== action.payload.transmittalId) :\n          [...state.transmittalOpen, action.payload.transmittalId]\n      };\n    case CHANGE_ORDER_TRANSMITTAL:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case CANCEL_REQUEST_TRANSMITTAL:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case LOADING_REQUEST_ITEMS_TRANSMITTAL:\n      return {\n        ...state,\n        requestItemsLoading: action.payload.requestItemsLoading\n      };\n    case FILTER_REQUEST_ITEMS_TRANSMITTAL:\n      return {\n        ...state,\n        requestItemsfilters: {\n          ...state.requestItemsfilters,\n          [action.payload.key]: action.payload.value\n        }\n      };\n    case LOAD_REQUEST_ITEMS_TRANSMITTAL:\n      return {\n        ...state,\n        requestItems: action.payload.requestItems,\n        requestItemsPagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    case TRANSPORT_MILESTONE_LOAD_STATUS:\n      return {\n        ...state,\n        milestones: action.payload.milestones\n      };\n    default:\n      return state;\n  }\n}\n","import { IOperationTypeState,\n  OperationTypeReduxActions,\n  OPERATION_TYPE_CANCEL_STATUS,\n  OPERATION_TYPE_CHANGE_ORDER,\n  OPERATION_TYPE_IS_LOADING,\n  OPERATION_TYPE_LOAD_STATUS\n} from '../actions/operationType.types';\n\nconst initialState: IOperationTypeState = {\n  operationTypes: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function operationTypeReducer(state = initialState, action: OperationTypeReduxActions): IOperationTypeState {\n  switch (action.type) {\n    case OPERATION_TYPE_CANCEL_STATUS:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case OPERATION_TYPE_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case OPERATION_TYPE_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case OPERATION_TYPE_LOAD_STATUS:\n      return {\n        ...state,\n        operationTypes: action.payload.operationTypes,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {\n  IMilestoneState,\n  MilestoneReduxActions,\n  MILESTONE_CANCEL_STATUS,\n  MILESTONE_CHANGE_ORDER,\n  MILESTONE_IS_LOADING,\n  MILESTONE_LOAD_STATUS,\n  MILESTONE_LOAD_FORMS,\n  MILESTONE_LOAD_REQUEST_STATUS,\n  MILESTONE_UDPATE_STATUS,\n  MILESTONE_LOAD_TYPES\n} from '../actions/milestone.types';\n\nconst initialState: IMilestoneState = {\n  milestones: [],\n  milestoneTypes: [],\n  requestStatus: [],\n  forms: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function milestoneReducer(state = initialState, action: MilestoneReduxActions): IMilestoneState {\n  switch (action.type) {\n    case MILESTONE_CANCEL_STATUS:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case MILESTONE_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case MILESTONE_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n     case MILESTONE_UDPATE_STATUS:\n      return {\n        ...state,\n        milestones: [...state.milestones.map((milestone) => {\n          if (milestone._id === action.payload.milestone._id) {\n            return {\n              milestone,\n              ...action.payload.milestone\n            };\n          }\n          return milestone;\n        })]\n      };\n    case MILESTONE_LOAD_FORMS:\n      return {\n        ...state,\n        forms: action.payload.forms\n      };\n    case MILESTONE_LOAD_TYPES:\n      return {\n        ...state,\n        milestoneTypes: action.payload.milestoneTypes\n      };\n    case MILESTONE_LOAD_REQUEST_STATUS:\n      return {\n        ...state,\n        requestStatus: action.payload.requestStatus\n      };\n    case MILESTONE_LOAD_STATUS:\n      return {\n        ...state,\n        milestones: action.payload.milestones,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import { IMilestoneTypeState,\n  MilestoneTypeReduxActions,\n  MILESTONE_TYPE_CANCEL_STATUS,\n  MILESTONE_TYPE_CHANGE_ORDER,\n  MILESTONE_TYPE_IS_LOADING,\n  MILESTONE_TYPE_LOAD_STATUS\n} from '../actions/milestoneType.types';\n\nconst initialState: IMilestoneTypeState = {\n  milestoneTypes: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function milestoneTypeReducer(state = initialState, action: MilestoneTypeReduxActions): IMilestoneTypeState {\n  switch (action.type) {\n    case MILESTONE_TYPE_CANCEL_STATUS:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case MILESTONE_TYPE_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case MILESTONE_TYPE_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case MILESTONE_TYPE_LOAD_STATUS:\n      return {\n        ...state,\n        milestoneTypes: action.payload.milestoneTypes,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import { IFormsState,\n  FormReduxActions,\n  FORM_CANCEL_STATUS,\n  FORM_CHANGE_ORDER,\n  FORM_IS_LOADING,\n  FORM_LOAD_STATUS,\n  FORM_LOAD_REQUEST_STATUS\n} from '../actions/form.types';\nimport { MILESTONE_LOAD_REQUEST_STATUS } from '../actions/milestone.types';\n\nconst initialState: IFormsState = {\n  forms: [],\n  requestStatus: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function formsReducer(state = initialState, action: FormReduxActions): IFormsState {\n  switch (action.type) {\n    case FORM_CANCEL_STATUS:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case FORM_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case FORM_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case FORM_LOAD_REQUEST_STATUS:\n      return {\n        ...state,\n        requestStatus: action.payload.requestStatus\n      };\n    case FORM_LOAD_STATUS:\n      return {\n        ...state,\n        forms: action.payload.forms,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {\n  IColorState,\n  ColorReduxActions,\n  COLOR_CANCEL,\n  COLOR_CHANGE_ORDER,\n  COLOR_IS_LOADING,\n  COLOR_LOAD,\n  COLOR_UDPATE, COLOR_CREATE, COLOR_DELETE\n} from '../actions/color.types';\n\nconst initialState: IColorState = {\n  colors: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function colorsReducer(state = initialState, action: ColorReduxActions): IColorState {\n  switch (action.type) {\n    case COLOR_CANCEL:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case COLOR_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case COLOR_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case COLOR_CREATE:\n      return {\n        ...state,\n        colors: [...state.colors, action.payload.color]\n      };\n     case COLOR_DELETE:\n       return {\n         ...state,\n         colors: [...state.colors.filter((color) => color._id !== action.payload.color)]\n       };\n     case COLOR_UDPATE:\n      return {\n        ...state,\n        colors: [...state.colors.map((color) => {\n          if (color._id === action.payload.color._id) {\n            return {\n              color,\n              ...action.payload.color\n            };\n          }\n          return color;\n        })]\n      };\n\n    case COLOR_LOAD:\n      return {\n        ...state,\n        colors: action.payload.colors,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {IStatsDashboardState, StatsDashboardReducerAction} from '../actions/statsDashboard.actions';\n\nconst initialState : IStatsDashboardState = {\n  loading: true,\n  studios: [],\n  users: [],\n  currentStudio: null,\n  tempStudio: {\n    _id: '',\n    users: [],\n    name: '',\n    type: '',\n    embedURL: '',\n    team: null\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\n\nexport function statsDashboardReducer(state: IStatsDashboardState = initialState, action: StatsDashboardReducerAction) {\n  switch (action.type) {\n    case '/STATS_DASHBOARD/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/STATS_DASHBOARD/LOAD_STUDIOS':\n      return {\n        ...state,\n        studios: action.payload.studios\n      };\n    case '/STATS_DASHBOARD/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/STATS_DASHBOARD/CHANGE_TEMP_STUDIO':\n      return {\n        ...state,\n        tempStudio: action.payload.tempStudio\n      };\n    case '/STATS_DASHBOARD/DELETE_USER':\n      return state;\n    case '/STATS_DASHBOARD/LOAD_STUDIOS_USERS':\n      return {\n        ...state,\n        users: action.payload.users\n      };\n    default:\n      return state;\n  }\n\n}\n\n","import { createBrowserHistory } from 'history';\n\nexport default createBrowserHistory({\n  basename: ''\n});\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport AppContainer from '../../container/AppContainer';\nimport Row from '../Utils/Row';\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\nimport {CompaniesReduxAction, ICompaniesState} from \"../../actions/companies.actions\";\nimport {connect} from \"react-redux\";\nimport {IWindow} from \"../../interfaces/window\";\n\ndeclare let window: IWindow;\n\nexport interface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<CompaniesReduxAction>;\n  dashboard: ICompaniesState;\n}\n\ninterface IStateType {\n  error: Error | null;\n  showDrilldown: boolean,\n  selectedDate: string | null,\n  from: Date,\n  to: Date,\n}\n\nexport class DashboardTimingView extends TrackingBasePage<IPropsType, IStateType> {\n  public title: string;\n  public cMenu  : string = \"1\";\n  public cSubMenu  : string = \"1.7\";\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Reporte personalizado';\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public getDashboardURL() : string{\n    return window.user.company.iFrameURL;\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    return (\n      <AppContainer title=\"\" cMenu={this.cMenu} cSubMenu={this.cSubMenu}>\n        <section className=\"content\">\n          <Row>\n            <div className=\"col-md-12\">\n              <div className=\"box\">\n                <div className=\"box-header with-border\"><h1 className=\"box-title\">Dashboard de análisis de datos</h1>\n                </div>\n                <div className=\"box-body\">\n                  <iframe src={this.getDashboardURL()} style={{width: \"100%\", minWidth: \"1000px\" ,minHeight: \"500px\", height: \"100vh\"}} allowFullScreen={true}  frameBorder={0} security={\"\"}/>\n                </div>\n              </div>\n            </div>\n          </Row>\n        </section>\n      </AppContainer>\n    );\n  }\n}\n\nconst mapStateToProps = (state: { dashboardTiming: ICompaniesState }) => {\n  return {\n    dashboard: state.dashboardTiming\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DashboardTimingView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo, Fragment } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { io } from \"socket.io-client\";\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport AppContainer from '../../../container/AppContainer';\nimport { IWindow } from '../../../interfaces/window';\nimport { hasPermission, parseReplicableURL } from '../../../utils/common';\nimport ImageLazyLoad from '../../Utils/ImageLazyLoad';\nimport Paginator from '../../Utils/Paginator';\nimport ShowIf from '../../Utils/ShowIf';\nimport TrackingBasePage from '../../Utils/TrackingBasePage';\nimport TransmittalActions from '../../../actions/transmittal.actions';\nimport { ITransmittalActionTypes, ITransmittalState } from '../../../actions/transmittal.types';\nimport TransmitalListDetail from './TransmitalListDetail';\nimport { Dispatch } from 'redux';\nimport ModalView from '../../Modal/ModalView';\nimport ApiService from '../../../utils/axios';\nimport * as moment from 'moment';\nimport Axios from 'axios';\nimport * as swal from 'sweetalert';\nimport { debounce } from 'throttle-debounce';\nimport {IMilestone} from \"../../../../../../../src/distribution/interfaces\";\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  router: any;\n  dispatch: Dispatch<ITransmittalActionTypes>;\n  transmittal: ITransmittalState;\n  transmittalActions: TransmittalActions;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n  number: string | undefined;\n}\n\ndeclare let window: IWindow;\n\nclass TransmittalListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  readonly state = {\n    error: null,\n    exporing: false,\n    number: undefined\n  };\n\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Transporte';\n    this.create = this.create.bind(this);\n    this.changeOrder = this.changeOrder.bind(this);\n    this.exportExcel = this.exportExcel.bind(this);\n    this.changePage = this.changePage.bind(this);\n    this.changeNumber = this.changeNumber.bind(this);\n    this.callChangeNumber = debounce(1000, this.callChangeNumber.bind(this));\n  }\n\n  public componentWillMount(): void {\n    const { orderBy, orderType } = this.props.transmittal.options;\n    const { page } = this.props.transmittal.pagination;\n    const {location: {query}} = this.props.router;\n    const { transmittalActions } = this.props;\n    window.scrollTo(0, 0);\n    const { number } = query;\n    this.setState({ number });\n    transmittalActions.getTransmittalsThunkAction({ nextPage: page, orderBy, orderType, number});\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: window.user.token\n      }\n    });\n\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {\n        room: `transmittal-list-${window.user.team._id}`\n      });\n    });\n\n    this.socket.on('CREATE_TRANSMITTAL_ITEM', (data: any): void => {\n      transmittalActions.createTransmittalItemAction(data.transmittalItem);\n      const $item = $(`#transmittal-item-${data.transmittalItem._id}`);\n      if ($item) {\n        $item.addClass('bg-green-active');\n      }\n      setTimeout(() => {\n        $item.removeClass('bg-green-active');\n      }, 300);\n    });\n\n    this.socket.on('UPDATE_TRANSMITTAL_ITEM', (data: any): void => {\n      transmittalActions.updateTransmittalItemAction(data.transmittalItem);\n      const $item = $(`#transmittal-item-${data.transmittalItem._id}`);\n      if ($item) {\n        $item.addClass('bg-aqua-active');\n        setTimeout(() => {\n          $item.removeClass('bg-aqua-active');\n        }, 300);\n      }\n    });\n\n    this.socket.on('UPDATE_TRANSMITTAL', (data: any): void => {\n      transmittalActions.updateTransmittalAction(data.transmittal);\n      const $item = $(`#transmittal-${data.transmittal._id}`);\n      if ($item) {\n        $item.addClass('bg-aqua-active');\n        setTimeout(() => {\n          $item.removeClass('bg-aqua-active');\n        }, 300);\n      }\n    });\n\n    this.socket.on('DELETE_TRANSMITTAL_ITEM', (data: any): void => {\n      const $item = $(`#transmittal-item-${data.transmittalItem._id}`);\n      if ($item) {\n        $item.addClass('bg-red-active');\n      }\n      setTimeout(() => {\n        transmittalActions.deleteTransmittalItemAction(data.transmittalItem);\n      }, 300);\n    });\n\n    this.socket.on('DELETE_TRANSMITTAL', (data: any): void => {\n      const $item = $(`#transmittal-${data.transmittal._id}`);\n      if ($item) {\n        $item.addClass('bg-red-active');\n      }\n      setTimeout(() => {\n        transmittalActions.deleteTransmittalAction(data.transmittal);\n        const { orderBy, orderType } = this.props.transmittal.options;\n        const { page } = this.props.transmittal.pagination;\n        transmittalActions.getTransmittalsThunkAction({ nextPage: page, orderBy, orderType, hideLoading: true });\n      }, 300);\n    });\n\n    this.socket.on('CREATE_TRANSMITTAL', (): void => {\n      const { page } = this.props.transmittal.pagination;\n      const { orderBy, orderType } = this.props.transmittal.options;\n      transmittalActions.getTransmittalsThunkAction({ nextPage: page, orderBy, orderType, hideLoading: true });\n    });\n\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    window.scrollTo(0, 0);\n  }\n\n  public componentDidUpdate(prevProps: IPropsType): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.transmittal.source) {\n      this.props.transmittal.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.emit('leave', { room: `distribution-list-${window.user.team._id}` });\n    this.socket.disconnect();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      pagination, loading, data, options: { orderBy, orderType }, milestones, milestoneTypes\n    } = this.props.transmittal;\n\n    let longestMilestones : IMilestone[] = []\n\n    for(let mType of milestoneTypes){\n      let tmp = milestones\n        .filter(m => m.type == mType._id && m.step == \"loadEvidence\");\n      if (tmp.length > longestMilestones.length)\n        longestMilestones = tmp.sort((a,b) => a.order - b.order);\n    }\n\n    const { exporing, number } = this.state;\n    return (\n      <AppContainer title='' cMenu='3' cSubMenu='3.4'>\n        <section className='content'>\n          <div className='box'>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>Transporte <small>{pagination.count}</small></h3>\n              <div className='pull-right box-tools'>\n                {\n                  hasPermission(window.user, 'addTransmittal') ?\n                    <button className='btn btn-sm btn-success' onClick={this.create}>\n                      <i className='fa fa-fw fa-plus' /> Crear orden\n                    </button>\n                    : null\n                }\n                <ShowIf condition={data.length > 0}>\n                  <button\n                    className='btn btn-sm btn-primary hidden-xs'\n                    onClick={this.exportExcel}\n                    disabled={exporing}\n                    style={{ marginLeft: '5px' }}\n                  >\n                    {\n                      exporing ? <Fragment><i className='fa fa-spin fa-spinner' /> Exportando</Fragment>\n                        : <Fragment><i className='fa fa-fw fa-download' /> Exportar</Fragment>\n                    }\n                  </button>\n                </ShowIf>\n              </div>\n            </div>\n            <div className={`box-body transmittal-list`}>\n              <div className=\"row\">\n                <div className=\"col-md-9\">\n                </div>\n                <div className=\"col-md-3\">\n                  <div\n                    className='input-group input-group-sm'\n                    style={{ padding: '10px' }}\n                  >\n                    <input\n                      type=\"text\"\n                      className=\"form-control pull-right\"\n                      onChange={(e) => {\n                        this.changeNumber(e.target.value)\n                      }}\n                      defaultValue={number}\n                      placeholder=\"Buscar OT ej: 452\"/>\n                    <div className=\"input-group-btn\">\n                      <button className=\"btn btn-default\"><i className=\"fa fa-search\"/></button>\n                    </div>\n                  </div>\n                </div>\n              </div>\n              <div className='table-responsive'>\n                <ShowIf condition={data.length > 0}>\n                <div className='row transmittal bg-primary'>\n                  <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1 center pointer head-sorted'\n                       onClick={() => this.changeOrder('_id')}\n                  >\n                    <strong>ID</strong> <i\n                    className={`fa ${orderBy === '_id' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} />\n                  </div>\n                  <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n                    <strong>Placa</strong>\n                  </div>\n                  <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n                    <strong>Chofer</strong>\n                  </div>\n                  <div className='flex-45 col-sm-2 col-xs-2 col-md-1 col-lg-1'>\n                    <strong>Transportista</strong>\n                  </div>\n                  <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n                    <strong>Nº Unidades</strong>\n                  </div>\n                  <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n                    <strong>Tipo</strong>\n                  </div>\n                  <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n                    <strong>Documentos</strong>\n                  </div>\n                  {\n                    longestMilestones.map((milestone: IMilestone) =>\n                      (<div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1' key={milestone._id}>\n                        <strong>{milestone.name}</strong>\n                      </div>))\n                  }\n                  <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n                    <strong>Evidencia descarga</strong>\n                  </div>\n                  <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1' />\n                </div>\n                {\n                  data.map((item: any) => (\n                    <TransmitalListDetail\n                      item={item}\n                      evidenceMilestones={longestMilestones}\n                      key={item._id}\n                    />\n                  ))\n                }\n              </ShowIf>\n                <ShowIf condition={!loading && data.length === 0}>\n                <div className='row'>\n                  <div className='col-md-12 text-center' style={{ paddingTop: '10px', paddingBottom: '10px' }}>\n                    <ImageLazyLoad\n                      url='/images/not_found.png'\n                      height={'200px'}\n                      style={{\n                        opacity: 0.5,\n                        maxHeight: '200px',\n                        marginBottom: '10px'\n                      }}\n                      replaceLoading={<i\n                        className={'fa fa-2x fa-circle-o-notch text-primary fa-spin'}\n                        style={{ padding: '30px' }}\n                      />}\n                    /><br />\n                    <strong>No hay información para mostrar</strong>\n                  </div>\n                </div>\n              </ShowIf>\n              </div>\n            </div>\n            {\n              pagination.pages > 1 &&\n              <div className='box-footer'>\n                <div className='row'>\n                  <div className='col-md-6' style={{ padding: '20px 15px' }}>\n                    <span className='react-bootstrap-table-pagination-total text-ellipsis'>\n                      &nbsp;&nbsp;Mostrando registros del {(pagination.page - 1) * 20 + 1} al {(pagination.page) * 20} de {pagination.count} registros.\n                      </span>\n                  </div>\n                  <div className='col-md-6'>\n                    <div className='text-right' style={{ marginRight: '15px' }}>\n                      <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                    </div>\n                  </div>\n                </div>\n              </div>\n            }\n            {\n              loading &&\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            }\n          </div>\n          <ModalView modalLarge={true} />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private changeNumber(number: string){\n    this.callChangeNumber(number);\n  }\n\n  private callChangeNumber(number: string){\n    const { options: { orderBy, orderType } } = this.props.transmittal;\n    this.setState({ number });\n    this.props.transmittalActions.getTransmittalsThunkAction({ nextPage: 1, orderBy, orderType, number});\n  }\n\n  private changeOrder(key: string) {\n    const {\n      options: { orderBy, orderType },\n      pagination: { page }\n    } = this.props.transmittal;\n    let newOrderType = orderType;\n    let newOrderBy = orderBy;\n    if (key === orderBy) {\n      newOrderType = orderType === 'descending' ? 'ascending' : 'descending';\n    } else {\n      newOrderBy = key;\n    }\n    this.props.transmittalActions.getTransmittalsThunkAction({ nextPage: page, orderBy:newOrderBy, orderType:newOrderType});\n  }\n\n  private create(): void {\n    this.props.history.push(parseReplicableURL('/transmittals/create/'));\n  }\n\n  private changePage(page: number): void {\n    const { options: { orderBy, orderType } } = this.props.transmittal;\n    this.props.transmittalActions.getTransmittalsThunkAction({ nextPage: page, orderBy, orderType});\n  }\n\n  public exportExcel(): void {\n    this.trackClick('Exportar');\n    this.setState({\n      exporing: true\n    });\n    const api: ApiService = new ApiService();\n    const instance = api.getInstance();\n    instance.defaults.responseType = 'blob';\n    instance\n      .get(`/transmittals/export-xls/`)\n      .then((response) => {\n        const blob = new Blob([response.data], {\n          type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'\n        });\n        const fileName = `${moment().format('YYYYMMDD')}-distribución.xlsx`;\n        if (typeof window.navigator.msSaveBlob !== 'undefined') {\n          // IE workaround for \"HTML7007: One or more blob URLs were\n          // revoked by closing the blob for which they were created.\n          // These URLs will no longer resolve as the data backing\n          // the URL has been freed.\"\n          window.navigator.msSaveBlob(blob, fileName);\n        } else {\n          const blobURL = URL.createObjectURL(blob);\n          const tempLink = document.createElement('a');\n          tempLink.style.display = 'none';\n          tempLink.href = blobURL;\n          tempLink.setAttribute('download', fileName);\n          // Safari thinks _blank anchor are pop ups. We only want to set _blank\n          // target if the browser does not support the HTML5 download attribute.\n          // This allows you to download files in desktop safari if pop up blocking\n          // is enabled.\n          if (typeof tempLink.download === 'undefined') {\n            tempLink.setAttribute('target', '_blank');\n          }\n          this.setState({\n            exporing: false\n          });\n          document.body.appendChild(tempLink);\n          tempLink.click();\n          document.body.removeChild(tempLink);\n          URL.revokeObjectURL(blobURL);\n        }\n      })\n      .catch((err) => {\n        this.setState({\n          exporing: false\n        });\n        if (!Axios.isCancel(err)) {\n          swal!('Exportar usuarios', 'Ha ocurrido un error al general el excel.', 'error');\n        }\n      });\n  }\n\n}\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState, router: any }) => {\n  return {\n    transmittal: state.transmittal,\n    router: state.router\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(TransmittalListView);\n","import * as React from 'react';\nimport { Dispatch } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport TransmittalActions from '../../../actions/transmittal.actions';\nimport { ITransmittalActionTypes, ITransmittalState } from '../../../actions/transmittal.types';\nimport { ITransmittalModel } from '../../../../../../../src/distribution/models/transmittal.model';\nimport TransmitalListItem from './TransmittalListItem';\nimport ShowIf from '../../Utils/ShowIf';\nimport { loadDataAction, ModalReduxAction } from '../../../actions/modal.actions';\nimport { IRequestItem } from '../../../../../../../src/request/interfaces/requestItem.interface';\nimport ApiService from '../../../utils/axios';\nimport { AxiosError } from 'axios';\nimport { hasPermission } from '../../../utils/common';\nimport { IWindow } from '../../../interfaces/window';\nimport DateRangePicker from '../../Utils/DateRangePicker';\nimport { getParticipant } from '../../../actions/dashboard.actions';\nimport { IParticipant } from '../../../../../../../src/form/interfaces/participant.interface';\nimport UploadTransmittalFile from './UploadTransmittalFile';\nimport AddItemsToTransmittal from '../TransmittalForms/AddItemsToTransmittal';\nimport { ICar } from '../../../../../../../src/app/interfaces/car.interface';\nimport { debounce } from 'throttle-debounce';\nimport {IMilestone} from \"../../../../../../../src/distribution/interfaces\";\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<ITransmittalActionTypes>;\n  transmittal: ITransmittalState;\n  item: ITransmittalModel;\n  evidenceMilestones: IMilestone[];\n  transmittalActions: TransmittalActions;\n  getParticipant(id: string): void;\n\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass TransmitalListDetail extends React.Component<IPropsType, IStateType> {\n\n  private readonly api: ApiService;\n\n  readonly state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.openDialogAddCar = this.openDialogAddCar.bind(this);\n    this.pushItem = this.pushItem.bind(this);\n    this.pushItemCar = this.pushItemCar.bind(this);\n    this.statusIcon = this.statusIcon.bind(this);\n    this.downloadFiles = this.downloadFiles.bind(this);\n    this.debouncedUpdateTransmittalThunkAction = debounce(2000, this.debouncedUpdateTransmittalThunkAction.bind(this));\n    this.api = new ApiService();\n  }\n\n  private debouncedUpdateTransmittalThunkAction(transmittal: any){\n    this.props.transmittalActions.updateTransmittalThunkAction(transmittal)\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { item: transmittal, transmittalActions, evidenceMilestones } = this.props;\n    const { carriers, drivers, milestoneTypes } = this.props.transmittal;\n    const open = this.props.transmittal.transmittalOpen.includes(transmittal._id);\n    return (\n      <React.Fragment>\n        <div id={`transmittal-${transmittal._id}`} className='row transmittal bg-transmittal-title background-transition'>\n          <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1 center head-sorted'>\n            <strong className='text-underline'>#{this.padNumber(transmittal.number)}</strong>&nbsp;\n          </div>\n          <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n            {\n              hasPermission(window.user, 'changeTransmittal') ?\n                (\n                  <input\n                    className='form-control input-sm'\n                    defaultValue={transmittal.transporter?.patent}\n                    onChange={(e) => {\n                      this.debouncedUpdateTransmittalThunkAction({\n                        _id: transmittal._id,\n                        'transporter.patent': e.target.value\n                      });\n                    }}\n                  />\n                ) :\n                (\n                  `${transmittal.transporter?.patent}`\n                )\n            }\n          </div>\n          <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1' style={{ position: 'static' }}>\n            {\n              hasPermission(window.user, 'changeTransmittal') ?\n                (\n                  <select\n                    className='form-control select-sm font-12' value={transmittal.transporter.driver?._id ?? ''}\n                    onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                      this.props.transmittalActions.updateTransmittalThunkAction({\n                        _id: transmittal._id,\n                        'transporter.driver': e.target.value\n                      });\n                    }}\n                  >\n                    {/*<option value='' disabled={true}>-</option>*/}\n                    {\n                      drivers.map((driver) => (\n                        <option key={driver._id} value={driver._id}>{`${driver.firstName} ${driver.lastName}`}</option>\n                      ))\n                    }\n                  </select>\n                  /*<BootstrapSelect\n                    noneSelectedText='Selecciona un chófer'\n                    displayItems={2}\n                    sm={true}\n                    selectedText='choferes seleccionadas.'\n                    selected={transmittal.transporter.driver ? [transmittal.transporter.driver._id] : []}\n                    autoClouse={true}\n                    allOption={false}\n                    search={true}\n                    options={drivers.map((driver: any) => ({\n                      value: driver._id,\n                      text: `${driver.firstName} ${driver.lastName}`\n                    }))}\n                    onClick={(e: string) => {\n                      this.props.transmittalActions.updateTransmittalThunkAction({\n                        _id: transmittal._id,\n                        'transporter.driver': e\n                      });\n                    }}\n                  />*/\n                ) :\n                (\n                  `${transmittal.transporter.driver.firstName} ${transmittal.transporter.driver.lastName}`\n                )\n            }\n            {/*{transmittal.transporter.driver._id}*/}\n          </div>\n          <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1' style={{ position: 'static' }}>\n            {\n              hasPermission(window.user, 'changeTransmittal') ?\n                (\n                  <select\n                    className='form-control select-sm font-12' value={transmittal.transporter.carrier?._id ?? ''}\n                    onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                      this.props.transmittalActions.updateTransmittalThunkAction({\n                        _id: transmittal._id,\n                        'transporter.carrier': e.target.value\n                      });\n                    }}\n                  >\n                    {/*<option value='' disabled={true}>-</option>*/}\n                    {\n                      carriers.map((carrier) => (\n                        <option key={carrier._id} value={carrier._id}>{`${carrier.name}`}</option>\n                      ))\n                    }\n                  </select>\n                  /*<BootstrapSelect\n                    noneSelectedText='Selecciona un transportista'\n                    displayItems={2}\n                    sm={true}\n                    selectedText='transportistas seleccionadas.'\n                    selected={transmittal.transporter.carrier ? [transmittal.transporter.carrier._id] : []}\n                    autoClouse={true}\n                    allOption={false}\n                    search={true}\n                    options={carriers.map((carrier: any) => ({\n                      value: carrier._id,\n                      text: carrier.name\n                    }))}\n                    onClick={(e: string) => {\n                      this.props.transmittalActions.updateTransmittalThunkAction({\n                        _id: transmittal._id,\n                        'transporter.carrier': e\n                      });\n                    }}\n                  />*/\n                ) :\n                (\n                  `${transmittal.transporter.carrier.name}`\n                )\n            }\n          </div>\n          <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n            {transmittal.items.length} unidades.\n          </div>\n          <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1' style={{ position: 'static' }}>\n            {\n              hasPermission(window.user, 'changeTransmittal') ?\n                (\n                  <select\n                    className='form-control select-sm font-12' value={transmittal.type?._id ?? ''}\n                    onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                      this.props.transmittalActions.updateTransmittalThunkAction({\n                        _id: transmittal._id,\n                        'type': e.target.value\n                      });\n                    }}\n                  >\n                    <option value='' disabled={true}>-</option>\n                    {\n                      milestoneTypes.map((milestoneType) => (\n                        <option key={milestoneType._id} value={milestoneType._id}>{`${milestoneType.name}`}</option>\n                      ))\n                    }\n                  </select>\n                  /*<BootstrapSelect\n                    noneSelectedText='Selecciona un transportista'\n                    displayItems={2}\n                    sm={true}\n                    selectedText='transportistas seleccionadas.'\n                    selected={transmittal.transporter.carrier ? [transmittal.transporter.carrier._id] : []}\n                    autoClouse={true}\n                    allOption={false}\n                    search={true}\n                    options={carriers.map((carrier: any) => ({\n                      value: carrier._id,\n                      text: carrier.name\n                    }))}\n                    onClick={(e: string) => {\n                      this.props.transmittalActions.updateTransmittalThunkAction({\n                        _id: transmittal._id,\n                        'transporter.carrier': e\n                      });\n                    }}\n                  />*/\n                ) :\n                (\n                  `${transmittal.type?.name}`\n                )\n            }\n\n          </div>\n          <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n           <UploadTransmittalFile transmittal={transmittal} />\n            <ShowIf condition={transmittal.files.length >= 1}>\n              <button\n                className='btn btn-xs btn-default'\n                onClick={() => this.downloadFiles(transmittal)}\n              >\n                <i\n                  className='fa fa-paperclip'\n                  data-toggle='tooltip'\n                  data-placement='top'\n                  title={`${transmittal.files.length} archivos adjuntos.`}\n                /> {`(${transmittal.files.length})`}\n              </button>\n            </ShowIf>\n          </div>\n\n          {\n            evidenceMilestones.map((milestone: IMilestone, index: number) => {\n              let tmp = transmittal.evidenceFullLoad.filter(e => {\n                if (e.milestone != undefined) {\n                  let is_in: Boolean = evidenceMilestones.filter(em => em._id == e.milestone).length > 0;\n                  return is_in ? e.milestone == milestone._id : index == 0;\n                } else\n                  return index == 0;\n              });\n              return (\n                <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1' key={`${transmittal._id}-${milestone._id}`}>\n                  {\n                    tmp.map((image: any, index: number) => (\n                      <div key={image._id} className={'text-center'} style={{ display: index === 0 ? '' : 'none' }}>\n                        <a href={decodeURI(image.file.url)}\n                           data-toggle='lightbox'\n                           data-gallery={`${transmittal._id}-${milestone._id}`}\n                           data-title={`#${this.padNumber(transmittal.number)}`}\n                           data-footer={`Conductor ${transmittal.transporter.driver ? `${transmittal.transporter.driver.firstName} ${transmittal.transporter.driver.lastName}` : ''} (${transmittal.transporter?.patent})`}\n                        >\n                          <button className='btn btn-xs btn-default'>\n                            <i className='fa fa-fw fa-image' /> {tmp.length}\n                          </button>\n                        </a>\n                      </div>\n                    ))\n                  }\n                </div>\n              );\n            })\n          }\n          <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n            {\n              transmittal?.revision ?\n                this.statusIcon(transmittal.revision) :\n                null\n            }\n          </div>\n          <div\n            className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1 chevron pointer'\n            onClick={() => transmittalActions.toogleTab(transmittal._id)}\n          >\n            {\n              open ? <i className='fa fa-chevron-up' /> : <i className='fa fa-chevron-down' />\n            }\n          </div>\n        </div>\n        <ShowIf condition={open}>\n          <div className='table-transmittal'>\n          <table className='table table-hover m-0'>\n            <thead>\n            <tr style={{ backgroundColor: '#f9f9f9' }}>\n              <th className='middle' style={{ width: '28px' }}>Solicitud</th>\n              <th className='middle' style={{ width: '100px' }}>VIN</th>\n              <th className='middle' style={{ width: '160px' }}>Modelo</th>\n              <th className='middle' style={{ width: '80px' }}>Factura</th>\n              <th className='middle' style={{ width: '80px' }}>Partida</th>\n              <th className='middle' style={{ width: '80px' }}>BL</th>\n              <th className='middle' style={{ minWidth: '100px' }}>Origen</th>\n              <th className='middle' style={{ minWidth: '100px' }}>Destino</th>\n              <th className='middle' style={{ width: '110px' }}>Fecha emisión</th>\n              <th className='middle' style={{ width: '110px' }}>Fecha arribo</th>\n              <th className='middle' style={{ width: '120px' }}>Observación</th>\n              <th className='middle' style={{ width: '40px' }}>Carga</th>\n              <ShowIf condition={hasPermission(window.user, 'changeTransmittal')}>\n                <th className='middle' style={{ width: '30px' }} />\n              </ShowIf>\n            </tr>\n            </thead>\n            <tbody>\n            {\n              transmittal.items.map((transmittalItem) => (\n                <TransmitalListItem\n                  item={transmittal}\n                  transmittalItem={transmittalItem}\n                  key={transmittalItem._id}\n                />\n              ))\n            }\n            <ShowIf condition={transmittal.items.length > 1}>\n              <tr className='no-striped'>\n                <td colSpan={8} className='middle text-right'>\n                  {/*Masivo*/}\n                </td>\n                <td className='middle'>\n                  <DateRangePicker\n                    className={'input-sm'}\n                    value={''}\n                    format={'DD-MM-YY'}\n                    onChange={(e) => {\n                      this.props.transmittalActions.updateTransmittalThunkAction({\n                        _id: transmittal._id,\n                        allLoadingDate: e?.toDate() ?? ''\n                      });\n                    }}\n                  />\n                </td>\n                <td className='middle'>\n                  <DateRangePicker\n                    className={'input-sm'}\n                    value={''}\n                    format={'DD-MM-YY'}\n                    onChange={(e) => {\n                      // allArrivalDate\n                      this.props.transmittalActions.updateTransmittalThunkAction({\n                        _id: transmittal._id,\n                        allArrivalDate: e?.toDate() ?? ''\n                      });\n                    }}\n                  />\n                </td>\n              </tr>\n            </ShowIf>\n            </tbody>\n          </table>\n          <ShowIf condition={hasPermission(window.user, 'changeTransmittal')}>\n            <div className='row'>\n              <div className='col-md-12 text-right m-b-10 m-t-10'>\n                <button className='btn btn-sm btn-success' onClick={this.openDialogAddCar}>\n                  <i className='fa fa-fw fa-plus' /> Agregar vehículo\n                </button>\n              </div>\n            </div>\n          </ShowIf>\n        </div>\n        </ShowIf>\n      </React.Fragment>\n    );\n  }\n\n  private statusIcon(revision: IParticipant) {\n    if (revision.hasDamages) {\n      return (\n        <button\n          className='btn btn-xs btn-default'\n          data-toggle='tooltip'\n          data-placement='top'\n          title={`Ver detalle`}\n          onClick={() => this.props.getParticipant(revision._id)}\n        >\n          <i className='fa fa-warning text-red' />\n        </button>\n      );\n    } else {\n      return (\n        <button\n          className='btn btn-xs btn-default'\n          data-toggle='tooltip'\n          data-placement='top'\n          title={`Ver detalle`}\n          onClick={() => this.props.getParticipant(revision._id)}\n        >\n          <i className='fa fa-check-circle text-primary' />\n        </button>\n      );\n    }\n  }\n\n  private openDialogAddCar() {\n    const { item: transmittal } = this.props;\n    this.props.loadDataAction(\n      `Agregar vehículo a orden #${this.padNumber(transmittal.number)}`,\n      <AddItemsToTransmittal onClickRequest={this.pushItem} onClickCar={this.pushItemCar} slimView={true} />,\n      <React.Fragment>\n        <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cerrar</button>\n      </React.Fragment>\n    );\n  }\n\n  private downloadFiles(transmittal: ITransmittalModel) {\n    window.open(`/transmittals/${transmittal._id}/download-files/`, '_blank');\n  }\n\n  private pushItemCar(car: ICar) {\n    const { item: transmittal } = this.props;\n    this.api.addTransmittalItem({\n      requestItem: null,\n      car: car._id,\n      request: null,\n      // origin: requestItem.origin?._id,\n      // destination: requestItem.destination?._id,\n      transmittal: transmittal._id\n    })\n      .then((): void => {})\n      .catch((err: AxiosError): void => {\n        this.api.errorHandler(err);\n      });\n  }\n\n\n  private pushItem(requestItem: IRequestItem) {\n    const { item: transmittal } = this.props;\n    this.props.transmittalActions.loadingRequestItemAction(true);\n    this.api.addTransmittalItem({\n      requestItem: requestItem._id,\n      car: requestItem.car._id,\n      request: requestItem.request._id,\n      origin: requestItem.origin?._id,\n      destination: requestItem.destination?._id,\n      transmittal: transmittal._id\n    })\n      .then((): void => {})\n      .catch((err: AxiosError): void => {\n        this.api.errorHandler(err);\n      });\n  }\n\n  private padNumber(n: number): string {\n    const s = '0000' + n;\n    return s.substr(s.length - 5);\n  }\n\n}\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState }) => {\n  return {\n    transmittal: state.transmittal\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions,\n    getParticipant: (id: string) => dispatch(getParticipant(id)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType | any>(mapStateToProps, mapDispatchToProps)(TransmitalListDetail);\n","import * as React from 'react';\nimport { Dispatch } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport * as moment from 'moment-timezone';\nimport TransmittalActions from '../../../actions/transmittal.actions';\nimport { ITransmittalActionTypes, ITransmittalState } from '../../../actions/transmittal.types';\nimport { ITransmittalItemModel } from '../../../../../../../src/distribution/models/transmittalItem.model';\nimport DateRangePicker from '../../Utils/DateRangePicker';\nimport BootstrapSelect from '../../Utils/BootstrapSelect';\nimport ShowIf from '../../Utils/ShowIf';\nimport * as swal from 'sweetalert';\nimport ApiService from '../../../utils/axios';\nimport { ITransmittalModel } from '../../../../../../../src/distribution/models/transmittal.model';\nimport { IParticipant } from '../../../../../../../src/form/interfaces/participant.interface';\nimport { getParticipant } from '../../../actions/dashboard.actions';\nimport { debounce } from 'throttle-debounce';\nimport { hasPermission } from '../../../utils/common';\nimport { IWindow } from '../../../interfaces/window';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<ITransmittalActionTypes>;\n  transmittal: ITransmittalState;\n  item: ITransmittalModel;\n  transmittalItem: ITransmittalItemModel;\n  transmittalActions: TransmittalActions;\n\n  getParticipant(id: string): void;\n}\n\ntype RecursivePartial<T> = {\n  [P in keyof T]?: RecursivePartial<T[P]>;\n};\n\n\ninterface IStateType {\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass TransmitalListItem extends React.Component<IPropsType, IStateType> {\n  private api: ApiService;\n  title: string;\n\n  readonly state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.delete = this.delete.bind(this);\n    this.statusIcon = this.statusIcon.bind(this);\n    this.debounceUpdateTransmittalItem = debounce(300, this.debounceUpdateTransmittalItem);\n    this.api = new ApiService();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { transmittalItem, transmittal: { venues } } = this.props;\n    return (\n      <tr id={`transmittal-item-${transmittalItem._id}`} className='background-transition'>\n        <td className={'middle'}>\n          <strong>\n            <ShowIf condition={!!transmittalItem?.request?.number}>\n              #{transmittalItem.request?.number}\n            </ShowIf>\n          </strong>\n        </td>\n        <td className={'middle'}>{transmittalItem.car.vin}</td>\n        <td className={'middle'}>{transmittalItem.car.brand} {transmittalItem.car.denomination}</td>\n        <td className={'middle-center'}>\n          <ShowIf condition={hasPermission(window.user, 'changeTransmittal')} alternative={transmittalItem.car.invoice}>\n            <input\n              type='text'\n              className='form-control input-sm'\n              defaultValue={transmittalItem.car.invoice}\n              onChange={(e) => {\n                this.debounceUpdateTransmittalItem({\n                  _id: transmittalItem._id,\n                  transmittal: transmittalItem.transmittal,\n                  car: {\n                    _id: transmittalItem.car._id,\n                    invoice: e.target.value\n                  }\n                });\n              }}\n            />\n          </ShowIf>\n        </td>\n        <td className={'middle-center'}>\n          <ShowIf condition={hasPermission(window.user, 'changeTransmittal')} alternative={transmittalItem.car.entry}>\n            <input\n              type='text'\n              className='form-control input-sm'\n              defaultValue={transmittalItem.car.entry}\n              onChange={(e) => {\n                this.debounceUpdateTransmittalItem({\n                  _id: transmittalItem._id,\n                  transmittal: transmittalItem.transmittal,\n                  car: {\n                    _id: transmittalItem.car._id,\n                    entry: e.target.value\n                  }\n                });\n              }}\n            />\n          </ShowIf>\n        </td>\n        <td className={'middle-center'}>\n          <ShowIf condition={hasPermission(window.user, 'changeTransmittal')} alternative={transmittalItem.car.bl}>\n            <input\n              type='text'\n              className='form-control input-sm'\n              defaultValue={transmittalItem.car.bl}\n              onChange={(e) => {\n                this.debounceUpdateTransmittalItem({\n                  _id: transmittalItem._id,\n                  transmittal: transmittalItem.transmittal,\n                  car: {\n                    _id: transmittalItem.car._id,\n                    bl: e.target.value\n                  }\n                });\n              }}\n            />\n          </ShowIf>\n        </td>\n        <td className={'middle'}>\n          <ShowIf condition={hasPermission(window.user, 'changeTransmittal')} alternative={transmittalItem.origin?.name}>\n            <select\n              className='form-control select-sm font-12' value={transmittalItem.origin?._id ?? ''}\n              onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                this.props.transmittalActions.updateTransmittalItemThunkAction({\n                  _id: transmittalItem._id,\n                  transmittal: transmittalItem.transmittal,\n                  origin: e.target.value\n                });\n              }}\n            >\n              {/*<option value='' disabled={true}>-</option>*/}\n              {\n                venues.map((venue) => (\n                  <option key={venue._id} value={venue._id}>{`${venue.name}`}</option>\n                ))\n              }\n            </select>\n            {/*<BootstrapSelect\n              noneSelectedText='Selecciona una sucursal'\n              displayItems={2}\n              sm={true}\n              selectedText='sucursales seleccionadas.'\n              selected={transmittalItem.origin ? [transmittalItem.origin._id] : []}\n              autoClouse={true}\n              allOption={false}\n              search={true}\n              options={venues.map((venue: any) => ({\n                value: venue._id,\n                text: venue.name\n              }))}\n              onClick={(e: string) => {\n                this.props.transmittalActions.updateTransmittalItemThunkAction({\n                  _id: transmittalItem._id,\n                  transmittal: transmittalItem.transmittal,\n                  origin: e\n                });\n              }}\n            />*/}\n          </ShowIf>\n        </td>\n        <td className={'middle'}>\n          <ShowIf condition={hasPermission(window.user, 'changeTransmittal')} alternative={transmittalItem.destination?.name}>\n            <select\n              className='form-control select-sm font-12' value={transmittalItem.destination?._id ?? ''}\n              onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                this.props.transmittalActions.updateTransmittalItemThunkAction({\n                  _id: transmittalItem._id,\n                  transmittal: transmittalItem.transmittal,\n                  destination: e.target.value\n                });\n              }}\n            >\n              {/*<option value='' disabled={true}>-</option>*/}\n              {\n                venues.map((venue) => (\n                  <option key={venue._id} value={venue._id}>{`${venue.name}`}</option>\n                ))\n              }\n            </select>\n            {/*<BootstrapSelect\n              noneSelectedText='Selecciona una sucursal'\n              displayItems={2}\n              sm={true}\n              selectedText='sucursales seleccionadas.'\n              selected={transmittalItem.destination ? [transmittalItem.destination._id] : []}\n              autoClouse={true}\n              allOption={false}\n              search={true}\n              options={venues.map((venue: any) => ({\n                value: venue._id,\n                text: venue.name\n              }))}\n              onClick={(e: string) => {\n                this.props.transmittalActions.updateTransmittalItemThunkAction({\n                  _id: transmittalItem._id,\n                  transmittal: transmittalItem.transmittal,\n                  destination: e\n                });\n              }}\n            />*/}\n          </ShowIf>\n        </td>\n        <td className={'middle'}>\n          <ShowIf\n            condition={hasPermission(window.user, 'changeTransmittal')}\n            alternative={transmittalItem.loadingDate ? moment(transmittalItem.loadingDate).format('DD-MM-YYYY') : '-'}\n          >\n            <DateRangePicker\n              className={'input-sm'}\n              value={transmittalItem.loadingDate}\n              format={'DD-MM-YY'}\n              onChange={(e) => {\n                this.props.transmittalActions.updateTransmittalItemThunkAction({\n                  _id: transmittalItem._id,\n                  transmittal: transmittalItem.transmittal,\n                  loadingDate: e?.toDate() ?? ''\n                });\n              }}\n            />\n          </ShowIf>\n        </td>\n        <td className={'middle'}>\n          <ShowIf\n            condition={hasPermission(window.user, 'changeTransmittal')}\n            alternative={transmittalItem.arrivalDate ? moment(transmittalItem.arrivalDate).format('DD-MM-YYYY') : '-'}\n          >\n            <DateRangePicker\n              className={'input-sm'}\n              value={transmittalItem.arrivalDate}\n              format={'DD-MM-YY'}\n              onChange={(e) => {\n                this.props.transmittalActions.updateTransmittalItemThunkAction({\n                  _id: transmittalItem._id,\n                  transmittal: transmittalItem.transmittal,\n                  arrivalDate: e?.toDate() ?? ''\n                });\n              }}\n            />\n          </ShowIf>\n        </td>\n        <td className={'middle'}>\n          <ShowIf\n            condition={hasPermission(window.user, 'changeTransmittal')}\n            alternative={transmittalItem.observation ?? '-'}\n          >\n            <input\n              className='form-control input-sm'\n              defaultValue={transmittalItem.observation}\n              onChange={(e) => {\n                this.debounceUpdateTransmittalItem({\n                  _id: transmittalItem._id,\n                  transmittal: transmittalItem.transmittal,\n                  observation: e.target.value\n                });\n              }}\n            />\n          </ShowIf>\n        </td>\n        {\n          transmittalItem.revisions.length ?\n            this.statusIcon(transmittalItem.revisions[0]) :\n            <td className={'middle'} />\n        }\n        <ShowIf condition={hasPermission(window.user, 'changeTransmittal')}>\n          <td className='middle-center text-red pointer' onClick={this.delete}>\n            <i className='fa fa-minus-circle' />\n          </td>\n        </ShowIf>\n      </tr>\n    );\n  }\n\n  private debounceUpdateTransmittalItem(transmittalItem: RecursivePartial<ITransmittalItemModel>) {\n    this.props.transmittalActions.updateTransmittalItemThunkAction(transmittalItem);\n  }\n\n  private statusIcon(revision: IParticipant) {\n    if (revision.hasDamages) {\n      return (\n        <td className={'middle pointer'} onClick={() => this.props.getParticipant(revision._id)}>\n          <i className='fa fa-warning text-red' />\n        </td>\n      );\n    } else if (revision.receptionConfirmation) {\n      return (\n        <td className={'middle pointer'} onClick={() => this.props.getParticipant(revision._id)}>\n          <i className='fa fa-check-circle text-primary' />\n        </td>\n      );\n    } else if (!revision.receptionConfirmation) {\n      return (\n        <td className={'middle pointer'} onClick={() => this.props.getParticipant(revision._id)}>\n          <i className='fa fa-close text-danger' />\n        </td>\n      );\n    }\n    return <td className={'middle'} />;\n  }\n\n  private delete() {\n    const { transmittalItem } = this.props;\n    const { item: transmittal } = this.props;\n    swal!({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar ${transmittalItem.car.brand} ${transmittalItem.car.denomination}, de la orden ${this.padNumber(transmittal.number)}.`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        const { transmittalItem } = this.props;\n        this.api.deleteTransmittalItem(transmittalItem);\n      }\n    });\n  }\n\n  private padNumber(n: number): string {\n    const s = '0000' + n;\n    return s.substr(s.length - 5);\n  }\n\n}\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState }) => {\n  return {\n    transmittal: state.transmittal\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions,\n    getParticipant: (id: string) => dispatch(getParticipant(id))\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType | any>(mapStateToProps, mapDispatchToProps)(TransmitalListItem);\n","import * as React from 'react';\nimport { RefObject } from 'react';\nimport { ITransmittalModel } from '../../../../../../../src/distribution/models/transmittal.model';\nimport ApiService from '../../../utils/axios';\nimport { AxiosError } from 'axios';\nimport ShowIf from '../../Utils/ShowIf';\n\ninterface IPropsType {\n  transmittal: ITransmittalModel;\n}\n\ninterface IStateType {\n  loading: boolean;\n  error: Error | null;\n}\n\nclass UploadTransmittalFile extends React.Component<IPropsType, IStateType> {\n\n  readonly inputFile: RefObject<HTMLInputElement>;\n  private readonly api: ApiService;\n\n  readonly state: IStateType = {\n    error: null,\n    loading: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.clickUploadFile = this.clickUploadFile.bind(this);\n    this.handleChangeInputFile = this.handleChangeInputFile.bind(this);\n    this.api = new ApiService();\n    this.inputFile = React.createRef();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading } = this.state;\n    return (\n      <button\n        className='btn btn-xs btn-default'\n        disabled={loading}\n        style={{ marginRight: '5px' }}\n        onClick={this.clickUploadFile}\n      >\n        <input\n          type='file'\n          ref={this.inputFile}\n          style={{ display: 'none' }}\n          onChange={this.handleChangeInputFile}\n        />\n        {\n          loading\n            ? (\n              <i className='fa fa-spinner fa-spin text-purple' />\n            )\n            : (\n              <i\n                className='fa fa-fw fa-cloud-upload'\n                data-toggle='tooltip'\n                data-placement='top'\n                title={`Cargar archivo`}\n              />\n            )\n        }&nbsp;Subir\n      </button>\n    );\n  }\n\n  private clickUploadFile() {\n    if (this.inputFile.current) {\n      this.inputFile.current.click();\n    }\n  }\n\n  private handleChangeInputFile(e: React.ChangeEvent<HTMLInputElement>) {\n    const { files } = e.target;\n    const { transmittal } = this.props;\n    if (files && files.length) {\n      const data = new FormData();\n      data.append('file', files[0]);\n      data.append('transmittal', transmittal._id);\n      this.setState({ loading: true });\n      this.api.uploadTransmittalFile(data)\n        .then((response) => {\n          this.setState({ loading: false });\n        })\n        .catch((err: AxiosError) => {\n          this.setState({ loading: false });\n          this.api.errorHandler(err);\n        });\n    }\n    this.inputFile.current!.value = '';\n  }\n}\n\nexport default UploadTransmittalFile;\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport * as moment from 'moment-timezone';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport TransmittalActions from '../../../actions/transmittal.actions';\nimport { ITransmittalActionTypes, ITransmittalState } from '../../../actions/transmittal.types';\nimport { Dispatch } from 'redux';\nimport { FieldArrayFieldsProps } from 'redux-form/lib/FieldArray';\nimport Paginator from '../../Utils/Paginator';\nimport { IRequestItem } from '../../../../../../../src/request/interfaces/requestItem.interface';\nimport { debounce } from 'throttle-debounce';\nimport { IUser } from '../../../../../../../src/app/interfaces/user.interface';\nimport { io } from \"socket.io-client\";\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport { IWindow } from '../../../interfaces/window';\nimport ShowIf from '../../Utils/ShowIf';\n\n\ninterface IExternarlPropsType {\n  fields?: FieldArrayFieldsProps<any>;\n  slimView?: boolean;\n\n  onClick(item: IRequestItem): void;\n}\n\ninterface IPropsType extends RouteComponentProps<{}>, IExternarlPropsType {\n  dispatch: Dispatch<ITransmittalActionTypes>;\n  transmittal: ITransmittalState;\n  transmittalActions: TransmittalActions;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass SearchCarInRequests extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null\n  };\n\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.changePage = this.changePage.bind(this);\n    this.getRequestItemDebounced = debounce(800, this.getRequestItemDebounced.bind(this));\n  }\n\n  public componentWillMount(): void {\n    this.props.transmittalActions.getRequestItemThunkAction(1);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: window.user.token\n      }\n    });\n\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {\n        room: `transmittal-list-${window.user.team._id}`\n      });\n    });\n\n    this.socket.on('CREATE_TRANSMITTAL_ITEM', (): void => {\n      const { requestItemsPagination } = this.props.transmittal;\n      this.props.transmittalActions.getRequestItemThunkAction(requestItemsPagination.page, true);\n    });\n\n    this.socket.on('DELETE_TRANSMITTAL_ITEM', (): void => {\n      const { requestItemsPagination } = this.props.transmittal;\n      this.props.transmittalActions.getRequestItemThunkAction(requestItemsPagination.page, true);\n    });\n    this.socket.on('DELETE_TRANSMITTAL', (): void => {\n      const { requestItemsPagination } = this.props.transmittal;\n      this.props.transmittalActions.getRequestItemThunkAction(requestItemsPagination.page, true);\n    });\n\n    this.socket.on('CREATE_TRANSMITTAL', (): void => {\n      const { requestItemsPagination } = this.props.transmittal;\n      this.props.transmittalActions.getRequestItemThunkAction(requestItemsPagination.page, true);\n    });\n  }\n\n  public componentWillUnmount(): void {\n    //cancel request if component is inmounted\n    if (this.props.transmittal.source) {\n      this.props.transmittal.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { transmittalActions, transmittal, fields, slimView } = this.props;\n    const { requestItems, requestItemsfilters, requestItemsPagination, requestItemsLoading } = transmittal;\n    const addedItems = fields?.getAll() ? fields.getAll().map(field => field._id) : [];\n    return (\n      <div className='row'>\n        <div className='col-md-12'>\n          <div className='table-container-overlay'>\n            <div className='row'>\n              <div className='col-md-8'>\n                <div className='form-group'>\n                  <label className='control-label'>\n                    Vehículo\n                  </label>\n                  <input\n                    type='text'\n                    className='form-control input-sm'\n                    placeholder='Busca por VIN, marca, modelo, material o nº de solicitud.'\n                    defaultValue={requestItemsfilters.text}\n                    onChange={(e) => {\n                      transmittalActions.filterRequestItemAction('text', e.target.value);\n                      this.getRequestItemDebounced();\n                    }}\n                  />\n                </div>\n              </div>\n              <div className='col-md-2'>\n                <div className='form-group'>\n                  <label className='control-label'>\n                    Nº Solicitudes\n                  </label>\n                  <input\n                    type='text'\n                    className='form-control input-sm'\n                    placeholder='Nº de solicitudes ejemplo: 2, 8, 10'\n                    defaultValue={requestItemsfilters.request}\n                    onChange={(e) => {\n                      transmittalActions.filterRequestItemAction('request', e.target.value);\n                      this.getRequestItemDebounced();\n                    }}\n                  />\n                </div>\n              </div>\n              <div className='col-md-2'>\n                <div className='form-group'>\n                  <label className='control-label'>\n                    Partida\n                  </label>\n                  <input\n                    type='text'\n                    className='form-control input-sm'\n                    placeholder='Nº de partida ejemplo: J-2136'\n                    defaultValue={requestItemsfilters.entry}\n                    onChange={(e) => {\n                      transmittalActions.filterRequestItemAction('entry', e.target.value);\n                      this.getRequestItemDebounced();\n                    }}\n                  />\n                </div>\n              </div>\n              <div className='col-md-12'>\n                <div className='table-responsive'>\n                  <table className='table table-xs table-hover' style={!slimView ? { minWidth: '1000px' } : {}}>\n                  <thead>\n                  <tr className='bg-primary' style={{ height: '45px' }}>\n                    <th className='middle-center' style={{ width: '45px' }}>ID Sol.</th>\n                    <th className='middle' style={{ width: '120px' }}>VIN</th>\n                    {\n                      slimView ?\n                        <React.Fragment>\n                          <th className='middle'> Vehículo</th>\n                        </React.Fragment>\n                        : <React.Fragment>\n                          <th className='middle'>Marca</th>\n                          <th className='middle'>Modelo</th>\n                          <th className='middle'>Color</th>\n                        </React.Fragment>\n                    }\n                    <th className='middle' style={{ width: '100px' }}>Partida</th>\n                    <th className='middle' style={{ width: '100px' }}>Factura</th>\n                    {\n                      slimView ?\n                        <React.Fragment>\n                          <th className='middle' style={{ width: '150px' }}>Solicitante</th>\n                        </React.Fragment>\n                        : <React.Fragment>\n                          <th className='middle' style={{ width: '150px' }}>Solicitante</th>\n                          <th className='middle' style={{ width: '150px' }}>Origen</th>\n                          <th className='middle' style={{ width: '150px' }}>Destino</th>\n                          <th className='middle' style={{ width: '100px' }}>Fecha</th>\n                        </React.Fragment>\n                    }\n                    <th className='middle' style={{ width: '28px' }} />\n                  </tr>\n                  </thead>\n                  <tbody>\n                  {\n                    requestItems\n                      .filter(item => !addedItems.includes(item._id))\n                      .map((item) => {\n                        return (\n                          <tr key={item._id}>\n                            <td className={`middle-center`}>\n                              #{item.request?.number}\n                            </td>\n                            <td className={`middle`}>\n                              {item.car?.vin}\n                            </td>\n                            {\n                              slimView ?\n                                <React.Fragment>\n                                  <td className='middle'>\n                                    <strong>{item.car?.brand}</strong> {item.car?.denomination}< br />\n                                    {item.car?.color}\n                                  </td>\n                                </React.Fragment> :\n                                <React.Fragment>\n                                  <td className={`middle`}>\n                                    {item.car?.brand}\n                                  </td>\n                                  <td className={`middle`}>\n                                    {item.car?.denomination}\n                                  </td>\n                                  <td className={`middle`}>\n                                    {item.car?.color}\n                                  </td>\n                                </React.Fragment>\n                            }\n\n                            <td className={`middle`}>\n                              {item.car?.entry ?? '-'}\n                            </td>\n                            <td className={`middle`}>\n                              {item.car?.invoice ?? '-'}\n                            </td>\n                            {\n                              slimView ?\n                                <React.Fragment>\n                                  <td className={`middle`}>\n                                    {this.createdBy(item.request?.createdBy) ?? '-'}<br />\n                                    {moment(item.request?.createdAt).format('DD/MM/YY') ?? '-'}\n                                  </td>\n                                </React.Fragment> :\n                                <React.Fragment>\n                                  <td className={`middle`}>\n                                    {this.createdBy(item.request?.createdBy) ?? '-'}\n                                  </td>\n                                  <td className={`middle`}>\n                                    {item.origin?.name ?? '-'}\n                                  </td>\n                                  <td className={`middle`}>\n                                    {item.destination?.name ?? '-'}\n                                  </td>\n                                  <td className={`middle`}>\n                                    {moment(item.request?.createdAt).format('DD/MM/YY') ?? '-'}\n                                  </td>\n                                </React.Fragment>\n                            }\n                            <td className={`middle`}>\n                              <ShowIf condition={!!item.car?.vin?.trim()}>\n                                <a\n                                  className='btn btn-success btn-xs'\n                                  href={'javascript:void(0);'}\n                                  onClick={() => this.props.onClick(item)}\n                                >\n                                  <i className='fa fa-plus' /> Agregar\n                                </a>\n                              </ShowIf>\n                            </td>\n                          </tr>\n                        );\n                      })\n                  }\n                  </tbody>\n                </table>\n                </div>\n              </div>\n            </div>\n            {\n              requestItemsPagination.pages > 1 &&\n              <div className='row'>\n                <div className='col-md-6' style={{ padding: '20px 15px' }}>\n              <span className='react-bootstrap-table-pagination-total text-ellipsis'>\n                &nbsp;&nbsp;Mostrando registros del {(requestItemsPagination.page - 1) * 20 + 1} al {(requestItemsPagination.page) * 20} de {requestItemsPagination.count} registros.\n              </span>\n                </div>\n                <div className='col-md-6'>\n                  <div className='text-right' style={{ marginRight: '15px' }}>\n                    <Paginator changePage={this.changePage} page={requestItemsPagination.page} pages={requestItemsPagination.pages} />\n                  </div>\n                </div>\n              </div>\n            }\n          </div>\n          {\n            requestItemsLoading &&\n            <div className='overlay' style={{\n              position: 'absolute',\n              top: 0,\n              left: 0,\n              height: '100%',\n              width: '100%',\n              zIndex: 50,\n              background: 'rgba(255,255,255,0.7)'\n            }}>\n              <i className='fa fa-spinner fa-spin text-purple' style={{\n                position: 'absolute',\n                top: '50%',\n                left: '50%',\n                marginLeft: '-15px',\n                marginTop: '-15px',\n                color: '#000',\n                fontSize: '30px'\n              }} />\n            </div>\n          }\n        </div>\n      </div>\n    );\n  }\n\n  private createdBy(createdBy: IUser): string | null {\n    return createdBy ? `${createdBy.firstName} ${createdBy.lastName}` : null;\n  }\n\n  private getRequestItemDebounced() {\n    this.props.transmittalActions.getRequestItemThunkAction(1, false);\n  }\n\n  private changePage(page: number): void {\n    // window.scrollTo(0, 0);\n    this.props.transmittalActions.getRequestItemThunkAction(page);\n  }\n\n}\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState }) => {\n  return {\n    transmittal: state.transmittal\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions\n  };\n};\n\n\nexport default connect<{}, {}, IExternarlPropsType | any>(mapStateToProps, mapDispatchToProps)(SearchCarInRequests);\n","import { Dispatch } from 'redux';\nimport * as React from 'react';\nimport { CarReduxAction, getCarsAction, ICarsState } from '../../../actions/cars.actions';\nimport { connect } from 'react-redux';\nimport { debounce } from 'throttle-debounce';\nimport Paginator from '../../Utils/Paginator';\nimport { ICar } from '../../../../../../../src/app/interfaces/car.interface';\nimport { FieldArrayFieldsProps } from 'redux-form/lib/FieldArray';\n\ninterface IExternarlPropsType {\n  slimView?: boolean\n  fields?: FieldArrayFieldsProps<any>;\n  onClick(item: ICar): void;\n}\n\ninterface IPropsType  extends IExternarlPropsType {\n  dispatch: Dispatch<CarReduxAction>;\n  cars: ICarsState;\n\n  getCarsAction(page: number, search?: string): CarReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  searchText: string;\n}\n\n\nclass SearchCarInCars extends React.Component<IPropsType, IStateType> {\n\n  readonly state: IStateType = {\n    error: null,\n    searchText: ''\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.changePage = this.changePage.bind(this);\n    this.onChangeSearch = this.onChangeSearch.bind(this);\n    this.debounceOnChangeSearch = debounce(300, this.debounceOnChangeSearch);\n  }\n\n  public componentWillMount() {\n    const { pagination } = this.props.cars;\n    this.props.getCarsAction(pagination.page);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, cars, pagination } = this.props.cars;\n    const { slimView, onClick, fields } = this.props;\n    const addedItems = fields?.getAll() ? fields.getAll().map(field => field.car.vin) : [];\n    return (\n      <div className='row'>\n        <div className='col-md-12'>\n          <div className='table-container-overlay'>\n            <div className='row'>\n              <div className='col-md-12'>\n                <div className='form-group'>\n                  <label className='control-label'>\n                    Vehículo\n                  </label>\n                  <input\n                    type='text'\n                    className='form-control input-sm'\n                    placeholder='Busca por VIN, marca, modelo o material.'\n                    onChange={this.onChangeSearch}\n                  />\n                </div>\n              </div>\n              <div className='col-md-12'>\n                <div className='table-responsive'>\n                  <table className='table table-xs table-hover' style={!slimView ? { minWidth: '1000px' } : {}}>\n                  <thead>\n                  <tr className='bg-primary' style={{ height: '45px' }}>\n                    <th className='middle' style={{ width: '120px' }}>VIN</th>\n                    {\n                      slimView ?\n                        <React.Fragment>\n                          <th className='middle'> Vehículo</th>\n                          <th className='middle'> Color</th>\n                        </React.Fragment>\n                        : <React.Fragment>\n                          <th className='middle'>Marca</th>\n                          <th className='middle'>Modelo</th>\n                          <th className='middle'>Color</th>\n                        </React.Fragment>\n                    }\n                    <th className='middle' style={{ width: '28px' }} />\n                  </tr>\n                  </thead>\n                  <tbody>\n                  {\n                    cars\n                      .filter(item => !addedItems.includes(item.vin))\n                      .map((car) => {\n                      return (\n                        <tr key={car._id}>\n                          <td className='middle' style={{ width: '120px' }}>{car.vin}</td>\n                          {\n                            slimView ?\n                              <React.Fragment>\n                                <td className='middle'>\n                                  <strong>{car?.brand}</strong> {car?.denomination}\n                                </td>\n                                <td className='middle'>\n                                  {car?.color}\n                                </td>\n                              </React.Fragment>\n                              : <React.Fragment>\n                                <td className='middle'>{car.brand}</td>\n                                <td className='middle'>{car.denomination}</td>\n                                <td className='middle'>{car.color}</td>\n                              </React.Fragment>\n                          }\n                          <td className='middle'>\n                            <a\n                              className='btn btn-success btn-xs'\n                              href={'javascript:void(0);'}\n                              onClick={() => onClick(car)}\n                            >\n                              <i className='fa fa-plus' /> Agregar\n                            </a>\n                          </td>\n                        </tr>\n                      );\n                    })\n                  }\n                  </tbody>\n                </table>\n                </div>\n              </div>\n            </div>\n            {\n              pagination.pages > 1 &&\n              <div className='row'>\n                <div className='col-md-6' style={{ padding: '20px 15px' }}>\n              <span className='react-bootstrap-table-pagination-total text-ellipsis'>\n                &nbsp;&nbsp;Mostrando registros del {(pagination.page - 1) * 20 + 1} al {(pagination.page) * 20} de {pagination.count} registros.\n              </span>\n                </div>\n                <div className='col-md-6'>\n                  <div className='text-right' style={{ marginRight: '15px' }}>\n                    <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                  </div>\n                </div>\n              </div>\n            }\n          </div>\n          {\n            loading &&\n            <div className='overlay' style={{\n              position: 'absolute',\n              top: 0,\n              left: 0,\n              height: '100%',\n              width: '100%',\n              zIndex: 50,\n              background: 'rgba(255,255,255,0.7)'\n            }}>\n              <i className='fa fa-spinner fa-spin text-purple' style={{\n                position: 'absolute',\n                top: '50%',\n                left: '50%',\n                marginLeft: '-15px',\n                marginTop: '-15px',\n                color: '#000',\n                fontSize: '30px'\n              }} />\n            </div>\n          }\n        </div>\n      </div>\n    );\n  }\n\n  private onChangeSearch(e: React.ChangeEvent<HTMLInputElement>): void {\n    e.preventDefault();\n    const value = e.target.value.trim();\n    this.setState({\n      searchText: value\n    });\n    this.debounceOnChangeSearch();\n  }\n\n  private debounceOnChangeSearch(): void {\n    const { searchText } = this.state;\n    if (searchText && searchText.length) {\n      this.props.getCarsAction(1, searchText);\n    } else {\n      this.props.getCarsAction(1);\n    }\n  }\n\n  private changePage(page: number): void {\n    const { searchText } = this.state;\n    this.props.getCarsAction(page, searchText);\n  }\n}\n\nconst mapStateToProps = (state: { cars: ICarsState }) => {\n  return {\n    cars: state.cars\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getCarsAction: (page: number, search?: string) => dispatch(getCarsAction(page, search))\n  };\n};\n\nexport default connect<{}, {}, IExternarlPropsType | any>(mapStateToProps, mapDispatchToProps)(SearchCarInCars);\n\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { Dispatch, ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { io } from \"socket.io-client\";\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport TransmittalActions from '../../actions/transmittal.actions';\nimport { ITransmittalActionTypes, ITransmittalState } from '../../actions/transmittal.types';\nimport TransmittalForm from './TransmittalForms/TransmittalForm';\nimport ShowIf from '../Utils/ShowIf';\nimport ApiService from '../../utils/axios';\nimport { AxiosError, AxiosResponse } from 'axios';\nimport * as swal from 'sweetalert';\nimport { imageStatus } from '../Utils/MultiUploadFiles';\nimport { ITransmittal } from '../../../../../../src/distribution/interfaces/transmittal.interface';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<ITransmittalActionTypes>;\n  transmittal: ITransmittalState;\n  transmittalActions: TransmittalActions;\n}\n\ninterface IStateType {\n  error: Error | null;\n  loading: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass TransmittalCreateView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  readonly state = {\n    error: null,\n    loading: false\n  };\n\n  private socket: Socket;\n\n  private readonly api: ApiService;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Crear orden de transporte';\n    this.processForm = this.processForm.bind(this);\n    this.cancel = this.cancel.bind(this);\n    this.api = new ApiService();\n  }\n\n  public componentWillMount(): void {\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: window.user.token\n      }\n    });\n\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {\n        room: `distribution-create-${window.user.team._id}`\n      });\n    });\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    window.scrollTo(0, 0);\n  }\n\n  public componentDidUpdate(prevProps: IPropsType): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.transmittal.source) {\n      this.props.transmittal.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.emit('leave', { room: `distribution-create-${window.user.team._id}` });\n    this.socket.disconnect();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { transmittalActions } = this.props;\n    const { loading } = this.props.transmittal;\n\n    return (\n      <AppContainer title='' cMenu='3' cSubMenu='3.4' cAction='Crear Order'>\n        <section className='content'>\n          <div className='box'>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>Crear orden de transporte</h3>\n            </div>\n            <div className='box-body'>\n              <TransmittalForm\n                initialValues={{\n                  files: [],\n                  items: []\n                }}\n                onSubmit={this.processForm}\n              />\n            </div>\n            <div className='box-footer text-right'>\n              <button\n                type='button'\n                className='btn btn-sm btn-default'\n                onClick={this.cancel}\n              >\n                Cancelar\n              </button>\n              <button\n                type='button'\n                className='btn btn-sm btn-primary'\n                disabled={this.state.loading}\n                style={{ marginLeft: '5px' }}\n                onClick={() => transmittalActions.submit('transmittalForm')}\n              >\n                <ShowIf condition={this.state.loading}>\n                  <i className='fa fa-spinner fa-spin ' />\n                </ShowIf> Crear\n              </button>\n            </div>\n            <ShowIf condition={loading || this.state.loading}>\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            </ShowIf>\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private cancel(): void {\n    this.props.history.push('/transmittals/');\n  }\n\n  private processForm(data: ITransmittal) {\n    const { history } = this.props;\n    const isUploadingFiles = data.files?.filter((file: any) => file.status !== imageStatus.complete).length;\n    const hasItemsLoaded = data.items?.length >= 1;\n    if (isUploadingFiles) {\n      swal!('Orden de transporte', 'Aún se estan cargando archivos, espera que terminen para enviar.', 'error');\n    } else if (!hasItemsLoaded) {\n      swal!('Orden de transporte', 'Debes agregar al menos un vehículo para poder crear una order.', 'error');\n    } else {\n      this.setState({ loading: true });\n      this.api.createTransmittals({\n        ...data,\n        items: data.items.map((item) => ({\n          ...item,\n          request: item.request?._id,\n          requestItem: (item as any).type === 'request' ? item?._id : null\n        })),\n        files: data.files.map((file) => file._id)\n      })\n        .then((response: AxiosResponse): void => {\n          swal('Orden de transporte', 'Se ha creado satisfactoriamente.', 'success')\n            .then(() => {\n              this.setState({ loading: false });\n              history.push('/transmittals/');\n            });\n        })\n        .catch((err: AxiosError): void => {\n          this.setState({ loading: false });\n          this.api.errorHandler(err);\n        });\n    }\n  }\n}\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState }) => {\n  return {\n    transmittal: state.transmittal\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(TransmittalCreateView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {Field, FieldArray, formValueSelector, InjectedFormProps, reduxForm} from 'redux-form';\nimport {ITransmittalState} from '../../../actions/transmittal.types';\nimport InputField from '../../Utils/forms/InputField';\nimport {inputStringRequired} from '../../Utils/forms/validations';\nimport MultiUploadFiles, {imageStatus} from \"../../Utils/MultiUploadFiles\";\nimport TransmittalActions from \"../../../actions/transmittal.actions\";\nimport tramittalRenderItem, {IRenderItemProps} from \"./renders/TramittalRenderItem\";\nimport BootstrapSelectField from \"../../Utils/forms/BootstrapSelectField\";\nimport ShowIf from '../../Utils/ShowIf';\nimport TextAreaField from \"../../Utils/forms/TextAreaField\";\n\n\ninterface IPropsType extends InjectedFormProps {\n  update: boolean;\n  transmittal: ITransmittalState;\n  formValues: any;\n  transmittalActions: TransmittalActions\n}\n\ninterface IStateType {\n  filesCache: any[];\n  error: Error | null;\n}\n\nclass Form extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    filesCache: [],\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n  public componentWillMount(): void {\n    this.props.transmittalActions.getFormBaseData();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {handleSubmit, valid, submitFailed, transmittal, formValues} = this.props;\n    const {filesCache} = this.state;\n    const filesCompleted = filesCache.filter((file: any) => file.status === imageStatus.complete);\n    const isUploadingFiles = filesCache.length > 0 && filesCompleted.length < filesCache.length;\n    return (\n      <form onSubmit={handleSubmit}>\n        <div className=\"row\">\n          <div className=\"col-md-12\">\n            <div className=\"row\">\n              <div className=\"col-md-6\">\n                <Field\n                  name=\"transporter.driver\"\n                  label=\"Chofer *\"\n                  component={BootstrapSelectField}\n                  validate={[inputStringRequired]}\n                  props={{\n                    noneSelectedText: \"Selecciona un chofer\",\n                    displayItems: 2,\n                    sm: true,\n                    selectedText: \"choferes seleccionadas.\",\n                    autoClouse: true,\n                    allOption: false,\n                    search: true,\n                    options: [\n                      ...transmittal.drivers.map((driver) => ({\n                        value: driver._id,\n                        text: `${driver.firstName} ${driver.lastName} - ${driver.company.name}`\n                      }))\n                    ],\n                    onClick: (value: string) => this.props.autofill('transporter.driver', value)\n                  }}\n                >\n                </Field>\n              </div>\n              <div className=\"col-md-6\">\n                <Field\n                  name=\"transporter.carrier\"\n                  label=\"Transportista *\"\n                  component={BootstrapSelectField}\n                  validate={[inputStringRequired]}\n                  props={{\n                    noneSelectedText: \"Selecciona un transportista\",\n                    displayItems: 2,\n                    selectedText: \"transportistas seleccionadas.\",\n                    autoClouse: true,\n                    sm: true,\n                    allOption: false,\n                    search: true,\n                    options: [\n                      ...transmittal.carriers.map((carrier) => ({\n                        value: carrier._id,\n                        text: carrier.name\n                      }))\n                    ],\n                    onClick: (value: string) => this.props.autofill('transporter.carrier', value)\n                  }}\n                >\n                </Field>\n              </div>\n            </div>\n          </div>\n          <div className=\"col-md-6\">\n            <Field\n              name=\"transporter.patent\"\n              label=\"Patente del camión\"\n              placeholder=\"ABCD12\"\n              type=\"text\"\n              component={InputField}\n              // validate={[inputStringRequired]}\n            />\n          </div>\n          <div className='col-md-6'>\n            <Field\n              name='type'\n              label='Tipo de transporte *'\n              component={BootstrapSelectField}\n              validate={[inputStringRequired]}\n              props={{\n                noneSelectedText: 'Selecciona un tipo',\n                displayItems: 2,\n                selectedText: 'tipo seleccionad0.',\n                autoClouse: true,\n                sm: true,\n                allOption: false,\n                search: true,\n                options: [\n                  ...transmittal.milestoneTypes.map((milestoneType) => ({\n                    value: milestoneType._id,\n                    text: milestoneType.name\n                  }))\n                ],\n                onClick: (value: string) => this.props.autofill('type', value)\n              }}\n            >\n            </Field>\n          </div>\n          <div className=\"col-md-12\">\n            <div className=\"form-group\">\n              <label className=\"control-label label-left\">Adjuntar Documentos</label>\n              <div>\n                <MultiUploadFiles\n                  url={'/api/v1/transmittals/upload-file/'}\n                  onChange={(files) => {\n                    this.setState({filesCache: files});\n                    this.props.autofill('files', files)\n                  }}\n                  files={filesCache}\n                />\n                <ShowIf condition={isUploadingFiles}>\n                  <p>\n                    Se están cargando sus archivos, llevamos {filesCompleted.length} de {filesCache.length} <i className=\"fa fa-spinner fa-spin\"/>.\n                  </p>\n                </ShowIf>\n              </div>\n            </div>\n          </div>\n          <div className=\"col-md-12 m-t-10\">\n            <h4>Unidades Cargadas ({formValues.items ? formValues.items.length : ''})</h4>\n          </div>\n          <FieldArray<IRenderItemProps>\n            name=\"items\"\n            component={tramittalRenderItem}\n            props={{\n              transmittal\n            }}\n          />\n          <div className=\"col-md-12 m-t-10\">\n            <Field\n              name={`observation`}\n              label=\"Observación\"\n              component={TextAreaField}\n              type=\"text\"\n              rows={4}\n              props={{\n                resize: 'none'\n              }}\n            />\n          </div>\n          {\n            submitFailed && !valid &&\n            <div className=\"col-md-12\">\n              <div\n                className=\"alert alert-danger m-t-20\"\n              >\n                Todos los campos con * son obligatorios\n              </div>\n            </div>\n          }\n        </div>\n      </form>\n    );\n  }\n}\n\nconst TransmittalForm = reduxForm({\n  form: 'transmittalForm'\n})(Form);\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState }) => {\n  const selector = formValueSelector('transmittalForm');\n  return {\n    formValues: selector(state, 'carrier', 'driver', 'files', 'items'),\n    transmittal: state.transmittal\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions\n  };\n};\n\nexport default connect<{ transmittal: ITransmittalState }, { dispatch: any }, IPropsType | {}>(mapStateToProps, mapDispatchToProps)(TransmittalForm);\n","import * as React from 'react';\nimport { Field, formValueSelector, WrappedFieldArrayProps } from 'redux-form';\nimport { inputStringRequired } from '../../../Utils/forms/validations';\nimport { ITransmittalState } from '../../../../actions/transmittal.types';\nimport TransmittalActions from '../../../../actions/transmittal.actions';\nimport { connect } from 'react-redux';\nimport BootstrapSelectField from '../../../Utils/forms/BootstrapSelectField';\nimport { IRequestItem } from '../../../../../../../../src/request/interfaces/requestItem.interface';\nimport InputField from '../../../Utils/forms/InputField';\nimport BootstrapSwitchField from '../../../Utils/forms/BootsrapSwitchField';\nimport ShowIf from '../../../Utils/ShowIf';\nimport AddItemsToTransmittal from '../AddItemsToTransmittal';\nimport { ICar } from '../../../../../../../../src/app/interfaces/car.interface';\nimport SelectField from '../../../Utils/forms/SelectField';\n\n\nexport interface IRenderItemProps {\n  transmittal: ITransmittalState;\n}\n\ninterface IPropsType extends WrappedFieldArrayProps<{}>, IRenderItemProps {\n  transmittalActions: TransmittalActions;\n  formValues: any;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n  openTabs: string[];\n  oneOrigin: boolean;\n  oneDestination: boolean;\n}\n\nclass TramittalRenderItem extends React.Component<IPropsType, IStateType> {\n\n  readonly state: IStateType = {\n    error: null,\n    exporing: false,\n    openTabs: [],\n    oneOrigin: true,\n    oneDestination: true\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.toogleTab = this.toogleTab.bind(this);\n    this.pushItem = this.pushItem.bind(this);\n    this.pushItemCar = this.pushItemCar.bind(this);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { fields, meta: { error, submitFailed }, transmittal } = this.props;\n    const { openTabs, oneOrigin, oneDestination } = this.state;\n    return (\n      <React.Fragment>\n        {\n          fields.length === 0 ?\n            <div className='col-md-12'>\n              <p\n                className='text-center text-muted'\n                style={{ padding: '20px 0' }}\n              >\n                No se han agregado unidades aún.\n              </p>\n            </div> :\n            <div className='col-md-12'>\n              <div className='table-responsive'>\n                <table className='table table-xs' style={{ minWidth: '1000px' }}>\n                <thead>\n                <tr className='bg-primary' style={{ height: '45px' }}>\n                  <th className='middle-center' style={{ width: '45px' }}>ID Sol.</th>\n                  <th className='middle' style={{ width: '120px' }}>VIN</th>\n                  <th className='middle'>Marca</th>\n                  <th className='middle'>Modelo</th>\n                  <th className='middle'>Color</th>\n                  <th className='middle' style={{ width: '100px' }}>Partida</th>\n                  <th className='middle' style={{ width: '100px' }}>Factura</th>\n                  <th className='middle' style={{ width: '150px' }}>Origen</th>\n                  <th className='middle' style={{ width: '150px' }}>Destino</th>\n                  <th className='middle' style={{ width: '40px' }} />\n                  <th className='middle' style={{ width: '28px' }} />\n                </tr>\n                </thead>\n                <tbody>\n                {\n                  fields.map((item, index) => {\n                    const value: IRequestItem = fields.get(index) as IRequestItem;\n                    const openTab = openTabs.includes(value._id);\n                    return (\n                      <React.Fragment key={value._id}>\n                        <tr>\n                          <td className={`middle-center`}>\n                            <ShowIf condition={!!value?.request?.number}>\n                              #{this.padNumber(value.request?.number)}\n                            </ShowIf>\n                          </td>\n                          <td className={`middle`}>\n                            {value.car?.vin}\n                          </td>\n                          <td className={`middle`}>\n                            {value.car?.brand}\n                          </td>\n                          <td className={`middle`}>\n                            {value.car?.denomination}\n                          </td>\n                          <td className={`middle`}>\n                            {value.car?.color}\n                          </td>\n                          <td className={`middle`}>\n                            {value.car?.entry ?? '-'}\n                          </td>\n                          <td className={`middle`}>\n                            {value.car?.invoice ?? '-'}\n                          </td>\n                          <td className={`middle form-group-no-margin`}>\n                            <Field\n                              name={`${item}.origin`}\n                              label='Origen *'\n                              component={SelectField}\n                              validate={[inputStringRequired]}\n                              props={{\n                                labelOff: true,\n                                disabled: true\n                              }}\n                            >\n                              <option value={\"\"} disabled={true} >Seleccione</option>\n                              {\n                                transmittal.venues.map((venue) => (\n                                  <option key={venue._id} value={venue._id}>{venue.name}</option>\n                                ))\n                              }\n                            </Field>\n                            {/*<Field\n                              name={`${item}.origin`}\n                              label='Origen *'\n                              component={BootstrapSelectField}\n                              validate={[inputStringRequired]}\n                              props={{\n                                noneSelectedText: 'Seleccione...',\n                                displayItems: 2,\n                                selectedText: 'origenes seleccionados.',\n                                autoClouse: true,\n                                sm: true,\n                                disabled: oneOrigin,\n                                labelOff: true,\n                                allOption: false,\n                                search: true,\n                                options: [\n                                  ...transmittal.venues.map((venue) => ({\n                                    value: venue._id,\n                                    text: venue.name\n                                  }))\n                                ],\n                                onClick: (value: string) => this.props.transmittalActions.autofill(`${item}.origin`, value)\n                              }}\n                            >\n                            </Field>*/}\n                          </td>\n                          <td className={`middle form-group-no-margin`}>\n                            <Field\n                              name={`${item}.destination`}\n                              label='Origen *'\n                              component={SelectField}\n                              validate={[inputStringRequired]}\n                              props={{\n                                labelOff: true,\n                                disabled: true\n                              }}\n                            >\n                              <option value={\"\"} disabled={true} >Seleccione</option>\n                              {\n                                transmittal.venues.map((venue) => (\n                                  <option key={venue._id} value={venue._id}>{venue.name}</option>\n                                ))\n                              }\n                            </Field>\n                            {/*<Field\n                              name={`${item}.destination`}\n                              label='Destino *'\n                              component={BootstrapSelectField}\n                              validate={[inputStringRequired]}\n                              props={{\n                                noneSelectedText: 'Seleccione...',\n                                displayItems: 2,\n                                selectedText: 'destinos seleccionados.',\n                                autoClouse: true,\n                                sm: true,\n                                right: true,\n                                disabled: oneDestination,\n                                labelOff: true,\n                                allOption: false,\n                                search: true,\n                                options: [\n                                  ...transmittal.venues.map((venue) => ({\n                                    value: venue._id,\n                                    text: venue.name\n                                  }))\n                                ],\n                                onClick: (value: string) => this.props.transmittalActions.autofill(`${item}.destination`, value)\n                              }}\n                            >\n                            </Field>*/}\n                          </td>\n                          <td className={`middle-center pointer`} onClick={() => this.toogleTab(value._id)}>\n                            {\n                              openTab ? <i className='fa fa-chevron-up' /> : <i className='fa fa-chevron-down' />\n                            }\n                          </td>\n                          <td className={`middle`}>\n                            <button\n                              type='button'\n                              className='btn btn-sm btn-danger'\n                              onClick={() => fields.remove(index)}\n                            >\n                              <i className='fa fa-trash' />\n                            </button>\n                          </td>\n                        </tr>\n                        {\n                          openTab ?\n                            <tr style={{ borderTop: 'none' }}>\n                              <td colSpan={11} className={'b-t-0'}>\n                                <table className={'table'} style={{ marginBottom: 0 }}>\n                                  <thead>\n                                  <tr style={{ backgroundColor: '#f9f9f9' }}>\n                                    <th className={'middle width-20'}>Cliente</th>\n                                    <th className={'middle width-20'}>BL</th>\n                                    <th className={'middle width-20'}>Tipo</th>\n                                    <th className={'middle width-20'}>Tipo Operación (Motivo)</th>\n                                    <th className={'middle width-20'}>Observación</th>\n                                  </tr>\n                                  </thead>\n                                  <tbody>\n                                  <tr>\n                                    <td className={'middle form-group-no-margin'}>\n                                      <Field\n                                        name={`${item}.car.client`}\n                                        type='text'\n                                        component={InputField}\n                                        props={{\n                                          labelOff: true\n                                        }}\n                                      />\n                                    </td>\n                                    <td className={'middle form-group-no-margin'}>\n                                      <Field\n                                        name={`${item}.car.bl`}\n                                        type='text'\n                                        component={InputField}\n                                        props={{\n                                          labelOff: true\n                                        }}\n                                      />\n                                    </td>\n                                    <td className={'middle'}>{value.car?.type ?? '-'}</td>\n                                    <td className={'middle'}>{value.reason?.name ?? '-'}</td>\n                                    <td className={'middle form-group-no-margin'}>\n                                      <Field\n                                        name={`${item}.observation`}\n                                        type='text'\n                                        component={InputField}\n                                        props={{\n                                          labelOff: true\n                                        }}\n                                      />\n                                    </td>\n                                  </tr>\n                                  </tbody>\n                                </table>\n                              </td>\n                            </tr> : null\n                        }\n                      </React.Fragment>\n                    );\n                  })\n                }\n                <tr>\n                  <td colSpan={7} />\n                  <td colSpan={2}>\n                    <div className='flex flex-row'>\n                      <div className='flex-1' style={{ paddingRight: '3px' }}>\n                        <ShowIf condition={false}>\n                          <Field\n                            name='oneOrigin'\n                            label='Un solo origen'\n                            type='checkbox'\n                            checked={oneOrigin}\n                            component={BootstrapSwitchField}\n                            onChange={(e: any) => {\n                              const { checked } = e.target;\n                              if (!checked) {\n                                this.props.transmittalActions.autofill(`all.origin`, null);\n                              }\n                              this.setState({\n                                oneOrigin: checked\n                              });\n                            }}\n                            validate={[]}\n                          />\n                        </ShowIf>\n                        <Field\n                          name={`all.origin`}\n                          label=''\n                          component={SelectField}\n                          validate={[inputStringRequired]}\n                          props={{\n                            labelOff: true,\n                          }}\n                          input={{\n                            defaultValue:\"\",\n                            onChange: (e:any) => {\n                              fields.forEach((item) => {\n                                this.props.transmittalActions.autofill(`${item}.origin`, e.target.value);\n                                this.props.transmittalActions.autofill(`all.origin`, e.target.value);\n                              });\n                            }\n                          }}\n                        >\n                          <option value={\"\"} disabled={true} >Seleccione</option>\n                          {\n                            transmittal.venues.map((venue) => (\n                              <option\n                                key={venue._id}\n                                value={venue._id}\n                              >\n                                {venue.name}\n                              </option>\n                            ))\n                          }\n                        </Field>\n                       {/* <Field\n                          name={`all.origin`}\n                          label=''\n                          component={BootstrapSelectField}\n                          props={{\n                            noneSelectedText: 'Seleccione...',\n                            displayItems: 2,\n                            selectedText: 'destinos seleccionados.',\n                            autoClouse: true,\n                            sm: true,\n                            disabled: !oneOrigin,\n                            labelOff: true,\n                            allOption: false,\n                            search: true,\n                            options: [\n                              ...transmittal.venues.map((venue) => ({\n                                value: venue._id,\n                                text: venue.name\n                              }))\n                            ],\n                            onClick: (value: string) => {\n                              fields.forEach((item) => {\n                                this.props.transmittalActions.autofill(`${item}.origin`, value);\n                                this.props.transmittalActions.autofill(`all.origin`, value);\n                              });\n                            }\n                          }}\n                        >\n                        </Field>*/}\n                      </div>\n                      <div className='flex-1' style={{ paddingLeft: '3px' }}>\n                        <ShowIf condition={false}>\n                          <Field\n                            name='oneDestination'\n                            label='Un solo destino'\n                            type='checkbox'\n                            checked={oneDestination}\n                            component={BootstrapSwitchField}\n                            onChange={() => {\n                              // const { checked } = e.target;\n                              // if (!checked) {\n                              //   this.props.transmittalActions.autofill(`all.destination`, null);\n                              // }\n                              // this.setState({\n                              //   oneDestination: checked\n                              // });\n                            }}\n                            validate={[]}\n                          />\n                        </ShowIf>\n                        <Field\n                          name={`all.destination`}\n                          label=''\n                          component={SelectField}\n                          validate={[inputStringRequired]}\n                          props={{\n                            labelOff: true,\n                          }}\n                          input={{\n                            defaultValue:\"\",\n                            onChange: (e:any) => {\n                              fields.forEach((item) => {\n                                this.props.transmittalActions.autofill(`${item}.destination`, e.target.value);\n                                this.props.transmittalActions.autofill(`all.destination`, e.target.value);\n                              });\n                            }\n                          }}\n                        >\n                          <option value={\"\"} disabled={true} >Seleccione</option>\n                          {\n                            transmittal.venues.map((venue) => (\n                              <option\n                                key={venue._id}\n                                value={venue._id}\n                              >\n                                {venue.name}\n                              </option>\n                            ))\n                          }\n                        </Field>\n                        {/*<Field\n                          name={`all.destination`}\n                          label=''\n                          component={BootstrapSelectField}\n                          props={{\n                            noneSelectedText: 'Seleccione...',\n                            displayItems: 2,\n                            selectedText: 'destinos seleccionados.',\n                            autoClouse: true,\n                            right: true,\n                            disabled: !oneDestination,\n                            sm: true,\n                            labelOff: true,\n                            allOption: false,\n                            search: true,\n                            options: [\n                              ...transmittal.venues.map((venue) => ({\n                                value: venue._id,\n                                text: venue.name\n                              }))\n                            ],\n                            onClick: (value: string) => {\n                              fields.forEach((item) => {\n                                this.props.transmittalActions.autofill(`${item}.destination`, value);\n                                this.props.transmittalActions.autofill(`all.destination`, value);\n                              });\n                            }\n                          }}\n                        >\n                        </Field>*/}\n                      </div>\n                    </div>\n                  </td>\n                </tr>\n\n                </tbody>\n              </table>\n              </div>\n            </div>\n        }\n        <div className='col-md-12' style={{ marginTop: '10px' }}>\n          <h4>Agregar Unidades</h4>\n        </div>\n        <div className='col-md-12'>\n          <AddItemsToTransmittal fields={fields} onClickRequest={this.pushItem} onClickCar={this.pushItemCar} />\n        </div>\n        {submitFailed && error && <span>{error}</span>}\n      </React.Fragment>\n    );\n  }\n\n  private pushItemCar(car: ICar) {\n    const { formValues } = this.props;\n    this.props.transmittalActions.pushItem({\n      _id: car._id,\n      car: car,\n      type: 'car',\n      request: null,\n      // reason: item.reason,\n      origin: formValues?.all?.origin,\n      // destination: formValues?.all?.destination ?? item.destination?._id\n      destination: formValues?.all?.destination\n    });\n  }\n\n  private pushItem(item: IRequestItem) {\n    const { formValues } = this.props;\n    this.props.transmittalActions.pushItem({\n      _id: item._id,\n      type: 'request',\n      car: {\n        ...item.car,\n        bl: item.car.bl ?? '',\n        client: item.car.client ?? ''\n      },\n      request: item.request,\n      reason: item.reason,\n      origin: formValues?.all?.origin,\n      // destination: formValues?.all?.destination ?? item.destination?._id\n      destination: formValues?.all?.destination\n    });\n  }\n\n  private toogleTab(id: string) {\n    const { openTabs } = this.state;\n    if (openTabs.includes(id)) {\n      this.setState({\n        openTabs: [...openTabs.filter(tab => tab !== id)]\n      });\n    } else {\n      this.setState({\n        openTabs: [...openTabs, id]\n      });\n    }\n  }\n\n  private padNumber(n: number): string {\n    const s = '000' + n;\n    return s.substr(s.length - 4);\n  }\n}\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState }) => {\n  const selector = formValueSelector('transmittalForm');\n  return {\n    formValues: selector(state, 'all.origin', 'all.destination'),\n    transmittal: state.transmittal\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions\n  };\n};\n\n\nexport default connect<{}, {}, IRenderItemProps>(mapStateToProps, mapDispatchToProps)(TramittalRenderItem);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Link } from 'react-router-dom';\nimport { Dispatch } from 'redux';\nimport { FormAction, submit } from 'redux-form';\nimport * as swal from 'sweetalert';\nimport { IOperationType } from '../../../../../../src/request/interfaces/operationType.interface';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport { IOperationTypeState, OperationTypeReduxActions } from '../../actions/operationType.types';\nimport {\n  createOperationTypeThunkAction,\n  deleteOperationTypeItemThunkAction,\n  getOperationTypesThunkAction,\n  updateOperationTypeThunkAction\n} from '../../actions/operationType.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { hasPermission, showModal, statusFooterButttonsModal } from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport OperationTypeForm from './OperationTypeForm';\nimport ShowIf from '../Utils/ShowIf';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<OperationTypeReduxActions | FormAction>;\n  operationType: IOperationTypeState;\n\n  getOperationTypeThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean): OperationTypeReduxActions;\n\n  createOperationTypeThunkAction(operationType: IOperationType): OperationTypeReduxActions;\n\n  updateOperationTypeThunkAction(operationType: IOperationType): OperationTypeReduxActions;\n\n  deleteOperationTypeThunkAction(operationType: IOperationType): OperationTypeReduxActions;\n\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass OperationTypeListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  private socket: Socket;\n  readonly state = {\n    error: null,\n    exporing: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado Tipo de operación';\n    this.changePage = this.changePage.bind(this);\n    this.createOperationType = this.createOperationType.bind(this);\n    this.processCreateOperationType = this.processCreateOperationType.bind(this);\n    this.updateReaon = this.updateReaon.bind(this);\n    this.processUpdateOperationType = this.processUpdateOperationType.bind(this);\n    this.deleteOperationType = this.deleteOperationType.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const { pagination } = this.props.operationType;\n    const { orderBy, orderType } = this.props.operationType.options;\n    this.props.getOperationTypeThunkAction(pagination.page, orderBy, orderType);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: { token: (window.user as any).token }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `operation-type-list-${window.user.team._id}` });\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update) {\n        const { pagination } = this.props.operationType;\n        const { orderBy, orderType } = this.props.operationType.options;\n        this.props.getOperationTypeThunkAction(pagination.page, orderBy, orderType, true);\n      }\n    });\n  }\n\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if (this.props.operationType.pagination !== prevProps.operationType.pagination) {\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.operationType.source) {\n      this.props.operationType.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, operationTypes, pagination } = this.props.operationType;\n    const canEdit = hasPermission(window.user, 'adminRequest');\n    const canDelete = hasPermission(window.user, 'adminRequest');\n    return (\n      <AppContainer title='' cMenu='3' cSubMenu='3.3' cAction='Tipos de operación'>\n        <section className='content'>\n          <div className='row'>\n            <div className='col-md-3'>\n              <div className='list-group'>\n                <Link to='/requests/settings/reasons/' className='list-group-item'>\n                  Motivos\n                </Link>\n                <Link to='/requests/settings/channels/' className='list-group-item'>\n                  Canales\n                </Link>\n                <Link to='/requests/settings/status/' className='list-group-item'>\n                  Estados\n                </Link>\n                <Link to='/requests/settings/operations-type/' className='list-group-item active'>\n                  Tipos de operación\n                </Link>\n                <Link to=\"/requests/settings/payment-methods/\" className=\"list-group-item\">\n                  Métodos de pago\n                </Link>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone-type/' className='list-group-item'>\n                    Tipos de hitos\n                  </Link>\n                </ShowIf>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone/' className='list-group-item'>\n                    Hitos\n                  </Link>\n                </ShowIf>\n              </div>\n            </div>\n            <div className='col-md-9'>\n              <div className='box'>\n                <div className='box-header with-border'>\n                  <h3 className='box-title'>Tipos de operación <small>{pagination.count}</small></h3>\n                  <div className='box-tools pull-right'>\n                    {\n                      hasPermission(window.user, 'addVenue') ?\n                        <button className='btn btn-sm btn-success'\n                                onClick={this.createOperationType}\n                        ><i className='fa fa-plus' /> Agregar</button>\n                        : null\n                    }\n                  </div>\n                </div>\n                <div className='box-body table-responsive no-padding'>\n                  <table className='table table-andes table-striped'>\n                    <thead>\n                    <tr>\n                      <th style={{ width: '98%' }} className='middle'>Nombre</th>\n                      {\n                        canEdit ?\n                          <th style={{ width: '1%' }} className='width-10' /> : null\n                      }\n                      {\n                        canDelete ?\n                          <th style={{ width: '1%' }} className='width-10' /> : null\n                      }\n                    </tr>\n                    </thead>\n                    <tbody>\n                    {\n                      operationTypes.map((item) => {\n                        return (\n                          <tr key={item._id}>\n                            <td className='middle'>{item.name}</td>\n                            {\n                              canEdit ?\n                                <td\n                                  className='middle text-blue pointer'\n                                  onClick={() => this.updateReaon(item)}\n                                >\n                                  <i className='fa fa-pencil' />\n                                </td> : null\n                            }\n                            {\n                              canDelete ?\n                                <td\n                                  className={canDelete ? 'middle text-red pointer' : 'middle text-muted not-allowed'}\n                                  // className={'middle text-red pointer'}\n                                  onClick={canDelete ? () => this.deleteOperationType(item) : undefined}\n                                >\n                                  <i className='fa fa-minus-circle' />\n                                </td> : null\n                            }\n                          </tr>\n                        );\n                      })\n                    }\n                    </tbody>\n                  </table>\n                </div>\n                {\n                  pagination.pages > 1 &&\n                  <div className='box-footer text-right'>\n                    <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                  </div>\n                }\n                {\n                  loading &&\n                  <div className='overlay'>\n                    <i className='fa fa-spinner fa-spin text-purple' />\n                  </div>\n                }\n              </div>\n            </div>\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private createOperationType(): void {\n    this.props.loadDataAction(\n      'Agregar tipo de operación',\n      <OperationTypeForm\n        initialValues={{ update: false }}\n        onSubmit={this.processCreateOperationType}\n      />,\n      <React.Fragment>\n        <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cancelar</button>\n        <button type='button' className='btn btn-sm btn-primary' onClick={() => this.props.dispatch(submit('operationTypeForm'))}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processCreateOperationType(operationType: any): void {\n    statusFooterButttonsModal(true);\n    this.props.createOperationTypeThunkAction(operationType);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private updateReaon(reason: any): void {\n    this.props.loadDataAction(\n      'Editar tipo de operación',\n      <OperationTypeForm\n        initialValues={{ update: false, ...reason }}\n        onSubmit={this.processUpdateOperationType}\n      />,\n      <React.Fragment>\n        <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cancelar</button>\n        <button type='button' className='btn btn-sm btn-primary' onClick={() => this.props.dispatch(submit('operationTypeForm'))}>Editar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processUpdateOperationType(operationType: any): void {\n    statusFooterButttonsModal(true);\n    this.props.updateOperationTypeThunkAction(operationType);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private deleteOperationType(operationType: IOperationType): void {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el tipo de operación: ${operationType.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteOperationTypeThunkAction(operationType);\n      }\n    });\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    const { orderBy, orderType } = this.props.operationType.options;\n    this.props.getOperationTypeThunkAction(page, orderBy, orderType);\n  }\n}\n\nconst mapStateToProps = (state: { operationType: IOperationTypeState }) => {\n  return {\n    operationType: state.operationType\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getOperationTypeThunkAction: (nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) => dispatch(getOperationTypesThunkAction(nextPage, orderBy, orderType, hideLoading)),\n    createOperationTypeThunkAction: (operationType: IOperationType) => dispatch(createOperationTypeThunkAction(operationType)),\n    updateOperationTypeThunkAction: (operationType: IOperationType) => dispatch(updateOperationTypeThunkAction(operationType)),\n    deleteOperationTypeThunkAction: (operationType: IOperationType) => dispatch(deleteOperationTypeItemThunkAction(operationType)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{ operationType: IOperationTypeState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(OperationTypeListView);\n","import Axios, { AxiosError, AxiosResponse, CancelTokenSource } from 'axios';\nimport { Dispatch } from 'redux';\nimport { IOperationType } from '../../../../../src/request/interfaces/operationType.interface';\nimport ApiService from '../utils/axios';\nimport {\n  OPERATION_TYPE_IS_LOADING,\n  OPERATION_TYPE_CHANGE_ORDER,\n  OPERATION_TYPE_CANCEL_STATUS,\n  OPERATION_TYPE_LOAD_STATUS,\n  OPERATION_TYPE_CREATE_STATUS,\n  OPERATION_TYPE_UDPATE_STATUS,\n  OPERATION_TYPE_DELETE_STATUS,\n  ICreateOperationType,\n  ICancelOperationType,\n  IIsLoadingOperationType,\n  ILoadOperationType,\n  IUpdateOperationType,\n  IDeleteOperationType,\n  IChangeOrderOperationType,\n  IOperationTypeState,\n  OperationTypeReduxActions\n} from './operationType.types';\n\nexport function cancelOperationTypeAction(source: CancelTokenSource): ICancelOperationType {\n  return {\n    type: OPERATION_TYPE_CANCEL_STATUS,\n    payload: {\n      source\n    }\n  };\n}\n\nexport function isLoadingOperationTypeAction(loading: boolean): IIsLoadingOperationType {\n  return {\n    type: OPERATION_TYPE_IS_LOADING,\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function loadOperationTypeAction(operationTypes: IOperationType[], count: number, pages: number, page: number): ILoadOperationType {\n  return {\n    type: OPERATION_TYPE_LOAD_STATUS,\n    payload: {\n      operationTypes,\n      count,\n      pages,\n      page\n    }\n  };\n}\n\n\nexport function createOperationTypeItemAction(operationType: IOperationType): ICreateOperationType {\n  return {\n    type: OPERATION_TYPE_CREATE_STATUS,\n    payload: {\n      operationType\n    }\n  };\n}\n\nexport function updateOperationTypeItemAction(operationType: IOperationType): IUpdateOperationType {\n  return {\n    type: OPERATION_TYPE_UDPATE_STATUS,\n    payload: {\n      operationType\n    }\n  };\n}\n\n\nexport function deleteOperationTypeAction(operationType: IOperationType): IDeleteOperationType {\n  return {\n    type: OPERATION_TYPE_DELETE_STATUS,\n    payload: {\n      operationType\n    }\n  };\n}\n\nexport function changeOrderOperationTypeAction(orderBy: string, orderType: string): IChangeOrderOperationType {\n  return {\n    type: OPERATION_TYPE_CHANGE_ORDER,\n    payload: {\n      orderBy,\n      orderType\n    }\n  };\n}\n\nexport function getOperationTypesThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) {\n  return (dispatch: Dispatch<OperationTypeReduxActions>, getState: () => { operationType: IOperationTypeState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(isLoadingOperationTypeAction(hideLoading ? false : true));\n    const page = nextPage ? nextPage : state.operationType.pagination.page;\n    dispatch(changeOrderOperationTypeAction(orderBy, orderType));\n    dispatch(cancelOperationTypeAction(api.getSource()));\n    Axios\n      .all([\n        api.getOperationTypes({ page, orderBy, orderType })\n      ])\n      .then(Axios.spread((operationTypes) => {\n        const { data } = operationTypes;\n        dispatch(loadOperationTypeAction(data.results, data.count, data.pages, page));\n        dispatch(isLoadingOperationTypeAction(false));\n      }))\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingOperationTypeAction(false));\n        api.errorHandler(err);\n      });\n  };\n\n}\n\nexport function createOperationTypeThunkAction(operationType: IOperationType) {\n  return (dispatch: Dispatch<OperationTypeReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.createOperationType(operationType)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateOperationTypeItemAction(idOperationType, data));\n      });\n  };\n}\n\nexport function updateOperationTypeThunkAction(operationType: IOperationType) {\n  return (dispatch: Dispatch<OperationTypeReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.updateOperationType(operationType)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateOperationTypeItemAction(idOperationType, data));\n      });\n  };\n}\n\nexport function deleteOperationTypeItemThunkAction(operationType: IOperationType) {\n  return (dispatch: Dispatch<OperationTypeReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.deleteOperationType(operationType)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateOperationTypeItemAction(idOperationType, data));\n      });\n  };\n}\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { Field, InjectedFormProps, reduxForm } from 'redux-form';\nimport { IReasonsState } from '../../actions/reasons.types';\nimport InputField from '../Utils/forms/InputField';\nimport { inputStringRequired } from '../Utils/forms/validations';\n\ninterface IPropsType extends InjectedFormProps {\n  update: boolean;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass Form extends React.Component<IPropsType, IStateType> {\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n  public render(): React.ReactElement<IPropsType> {\n    const { handleSubmit, valid , submitFailed} = this.props;\n    return (\n      <form onSubmit={handleSubmit}>\n        <div className=\"row\">\n          <div className=\"col-md-10\">\n            <Field\n              name=\"name\"\n              label=\"Nombre *\"\n              placeholder=\"Nombre\"\n              type=\"text\"\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>\n          {\n            submitFailed && valid === false &&\n            <div className=\"col-md-12\">\n              <div\n                className=\"alert alert-danger\"\n                style={{marginTop: '20px'}}\n              >\n                Todos los campos con * son obligatorios\n              </div>\n            </div>\n          }\n        </div>\n      </form>\n    );\n  }\n}\n\nconst OperationTypeForm = reduxForm({\n  form: 'operationTypeForm'\n})(Form);\n\nconst mapStateToProps = (state: { reasons: IReasonsState }) => {\n  return {\n    reasons: state.reasons\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{ reasons: IReasonsState }, { dispatch: any }, IPropsType | {}>(mapStateToProps, mapDispatchToProps)(OperationTypeForm);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo, RefObject } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport * as swal from 'sweetalert';\nimport * as XLSX from 'xlsx';\nimport { IRequestItemsState } from '../../actions/requestItems.types';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport ApiService from '../../utils/axios';\nimport ModalView from '../Modal/ModalView';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport ShowIf from '../Utils/ShowIf';\nimport Axios, { AxiosError } from 'axios';\nimport { IRequestSetting } from '../../../../../../src/app/interfaces/teamSetting.interface';\nimport { ISalesChannel } from '../../../../../../src/request/interfaces/salesChannel.interface';\nimport { IOperationType } from '../../../../../../src/request/interfaces/operationType.interface';\nimport { IReason } from '../../../../../../src/request/interfaces/reason.interface';\nimport { IVenue } from '../../../../../../src/app/interfaces/venue.interface';\nimport RequestImportForm from './RequestImportForm/RequestImportForm';\nimport { submit } from 'redux-form';\nimport { requestSettings } from './defaults';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  requestItems: IRequestItemsState;\n  dispatch: Dispatch<any>;\n}\n\ninterface IStateType {\n  error: Error | null;\n  requests: any[];\n  canDrop: boolean;\n  loading: boolean;\n  sending: boolean;\n  venues: IVenue[];\n  reasons: IReason[];\n  channels: ISalesChannel[];\n  operationTypes: IOperationType[];\n  requestSettings: IRequestSetting;\n}\n\ndeclare let window: IWindow;\n\nclass RequestUpdaterView extends TrackingBasePage<IPropsType, IStateType> {\n  public title: string;\n  readonly inputFile: RefObject<HTMLInputElement>;\n  readonly api: ApiService;\n\n  readonly state: IStateType = {\n    error: null,\n    canDrop: false,\n    loading: true,\n    sending: false,\n    requests: [],\n    venues: [],\n    reasons: [],\n    channels: [],\n    operationTypes: [],\n    requestSettings\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Importador de solicitudes';\n    this.inputFile = React.createRef();\n    this.clickUploadFile = this.clickUploadFile.bind(this);\n    this.handleDrop = this.handleDrop.bind(this);\n    this.dragOverHandler = this.dragOverHandler.bind(this);\n    this.dragEndHandler = this.dragEndHandler.bind(this);\n    this.dragLeaveHandler = this.dragLeaveHandler.bind(this);\n    this.handleChangeInputFile = this.handleChangeInputFile.bind(this);\n    this.downloadTemplate = this.downloadTemplate.bind(this);\n    this.parseRequestItem = this.parseRequestItem.bind(this);\n    this.processSettings = this.processSettings.bind(this);\n    this.sendCreate = this.sendCreate.bind(this);\n    this.checkSameVenue = this.checkSameVenue.bind(this);\n    this.api = new ApiService();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    window.scrollTo(0, 0);\n    const api: ApiService = new ApiService();\n    Axios\n      .all([\n        this.api.getOperationTypes({ page: 1, pageSize: 200 }),\n        this.api.getVenues({ page: 1, pageSize: 200, noPopulate: true }),\n        this.api.getSalesChannel({ page: 1, pageSize: 200 }),\n        this.api.getReasons({ page: 1, pageSize: 200 }),\n        this.api.getTeamSettings()\n      ])\n      .then(Axios.spread((\n        operationTypes,\n        venues,\n        channels,\n        reasons,\n        teamSettings\n      ) => {\n        this.setState({\n          requestSettings: teamSettings.data.request,\n          venues: venues.data.results,\n          reasons: reasons.data.results,\n          channels: channels.data.results,\n          operationTypes: operationTypes.data.results,\n          loading: false\n        });\n      }))\n      .catch((err: AxiosError) => {\n        api.errorHandler(err);\n      });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.requestItems.source) {\n      this.props.requestItems.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      loading, requests, sending, channels, operationTypes, reasons, venues\n    } = this.state;\n    return (\n      <AppContainer title='' cMenu='3' cSubMenu='3.2' cAction='Importador de solicitudes'>\n        <section className='content'>\n          <div className='box'>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>Importador de solicitudes</h3>\n              <div className='pull-right box-tools'>\n                <ShowIf condition={!requests.length}>\n                  <button\n                    className='btn btn-sm btn-primary'\n                    onClick={this.downloadTemplate}\n                    style={{ marginRight: '5px' }}>\n                    <i className='fa fa-fw fa-download' /> Descargar Formato\n                  </button>\n                </ShowIf>\n              </div>\n            </div>\n            <div className='box-body margin'>\n              {\n                requests.length ?\n                  <>\n                    <RequestImportForm\n                      channels={channels}\n                      operationTypes={operationTypes}\n                      reasons={reasons}\n                      venues={venues}\n                      onSubmit={this.sendCreate}\n                      initialValues={{\n                        requests: requests\n                      }}\n                    />\n                    <div className='row'>\n                      <div className='col col-md-6'>\n                        {/*  <strong>Total de :</strong> {requests.length}*/}\n                      </div>\n                      <div className='col-md-6 text-right'>\n                        <button className='btn btn-sm btn-primary' onClick={this.downloadTemplate}>\n                          <i className='fa fa-fw fa-download' /> Descargar Formato\n                        </button>\n                        <button className='btn btn-sm btn-default' onClick={this.clickUploadFile} style={{ marginLeft: '5px' }}>\n                          <i className='fa fa-fw fa-cogs' /> Cambiar configuración\n                        </button>\n                      </div>\n                    </div>\n                  </>\n                  :\n                  <div className='row'>\n                    <div className='col col-md-12'>\n                      <div className='form-group'>\n                        {/*<label>Días que serán importardos</label>*/}\n                        <div\n                          className='upload-file text-center pointer'\n                          onClick={this.clickUploadFile}\n                          onDrop={this.handleDrop}\n                          onDragOver={this.dragOverHandler}\n                          onDragEnd={this.dragEndHandler}\n                          onDragLeave={this.dragLeaveHandler}\n                          style={{\n                            backgroundColor: '#EEEEEE',\n                            border: this.state.canDrop ? '1px solid #979797' : '1px dashed #979797',\n                            padding: '100px 20px',\n                            color: this.state.canDrop ? '#aebccb' : '#6e7a89',\n                            borderRadius: '5px',\n                            marginBottom: '10px'\n                          }}>\n                          <i className='fa fa-2x fa-cloud-upload' /><br />\n                          Prueba a soltanto el excel aquí, o haz click para seleccionar el excel a cargar.\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n              }\n              <input\n                type='file'\n                onChange={this.handleChangeInputFile}\n                style={{ display: 'None' }}\n                ref={this.inputFile}\n                accept='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel'\n              />\n            </div>\n            <div className='box-footer text-right'>\n              <button\n                className='btn btn-sm btn-default'\n                onClick={() => this.props.history.push('/requests/vehicles/')}\n              >\n                Cancelar\n              </button>\n              <ShowIf condition={!!requests.length}>\n                <button\n                  className='btn btn-sm btn-primary'\n                  style={{ marginLeft: '5px' }}\n                  onClick={() => this.props.dispatch(submit('requestImportForm'))}\n                  disabled={sending}\n                >\n                  <ShowIf condition={sending} alternative={'Actualizar'}>\n                    <React.Fragment>\n                      <i className='fa fa-fw fa-spin fa-spinner' /> Actualizando...\n                    </React.Fragment>\n                  </ShowIf>\n                </button>\n              </ShowIf>\n            </div>\n            <ShowIf condition={loading || sending}>\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            </ShowIf>\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private clickUploadFile(): void {\n    if (this.inputFile.current) {\n      this.inputFile.current.click();\n    }\n  }\n\n  private handleDrop(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      if (dt.items.length) {\n        const file: File | null = dt.items[0].getAsFile();\n        if (file) {\n          this.processSettings(file);\n        }\n      }\n    } else {\n      if (dt.files.length) {\n        const file = dt.files[0];\n        this.processSettings(file);\n      }\n    }\n  }\n\n  private handleChangeInputFile(e: React.ChangeEvent<HTMLInputElement>): void {\n    const { files } = e.target;\n    if (files && files.length) {\n      this.processSettings(files[0]);\n    }\n  }\n\n  private dragOverHandler(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    this.setState({\n      canDrop: true\n    });\n  }\n\n  private dragEndHandler(e: React.DragEvent<HTMLDivElement>): void {\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      // Use DataTransferItemList interface to remove the drag data\n      for (let i = 0; i < dt.items.length; i++) {\n        dt.items.remove(i);\n      }\n    } else {\n      // Use DataTransfer interface to remove the drag data\n      e.dataTransfer.clearData();\n    }\n  }\n\n  private dragLeaveHandler(): void {\n    this.setState({\n      canDrop: false\n    });\n  }\n\n  private downloadTemplate(): void {\n    /* make the worksheet */\n    const ws = XLSX.utils.json_to_sheet([{\n      ['Numero solicitud']: '',\n      ['Partida']: '',\n      ['Tipo operacion']: '',\n      ['Canal']: '',\n      ['Motivo']: '',\n      ['Vendedor']: '',\n      ['Cliente']: '',\n      ['Origen']: '',\n      ['Destino']: '',\n      ['Factura']: '',\n      ['BL']: '',\n      ['Chasis']: '',\n      ['Motor']: '',\n      ['Marca']: '',\n      ['Modelo']: '',\n      ['Color']: '',\n      ['Tipo']: '',\n      ['Cilindrada']: '',\n      ['Traccion']: '',\n      ['Ano Comercial']: '',\n      ['Ano Fabricacion']: '',\n      ['Monto']: '',\n      ['Seguro']: '',\n      ['Peso']: '',\n      ['Gas']: '',\n      ['AP']: '',\n      ['Pais Origen']: '',\n      ['Observacion']: ''\n    }]);\n    /* add to workbook */\n    const wb = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(wb, ws, 'Propiedades');\n    /* generate an XLSX file */\n    XLSX.writeFile(wb, 'template_request_settings.xlsx');\n  }\n\n  private parseRequestItem(requestItem: any) {\n    const { venues, reasons } = this.state;\n    return {\n      ['reason']: reasons.find((reason) => {\n        return reason.name?.trim().toLowerCase() === requestItem['Motivo']?.trim().toLowerCase();\n      })?._id,\n      ['vin']: requestItem['Chasis'],\n      ['engineNumber']: requestItem['Motor'],\n      ['brand']: requestItem['Marca'],\n      ['denomination']: requestItem['Modelo'],\n      ['color']: requestItem['Color'],\n      ['type']: requestItem['Tipo'],\n      ['client']: requestItem['Cliente'],\n      ['entry']: requestItem['Partida'],\n      ['invoice']: requestItem['Factura'],\n      ['origin']: venues.find((venue) => {\n        return this.checkSameVenue(venue, requestItem['Origen']);\n        // return venue.name?.trim().toLowerCase() === requestItem['Origen']?.trim().toLowerCase();\n      })?._id,\n      ['destination']: venues.find((venue) => {\n        return this.checkSameVenue(venue, requestItem['Destino']);\n        // return venue.name?.trim().toLowerCase() === requestItem['Destino']?.trim().toLowerCase();\n      })?._id,\n      ['bl']: requestItem['BL'],\n      ['engineSize']: requestItem['Cilindrada'],\n      ['driveType']: requestItem['Traccion'],\n      ['businessYear']: requestItem['Ano Comercial'],\n      ['manufacturingYear']: requestItem['Ano Fabricacion'],\n      ['price']: requestItem['Monto'],\n      ['insurancePrice']: requestItem['Seguro'],\n      ['weight']: requestItem['Peso'],\n      ['gas']: requestItem['Gas'],\n      ['ap']: requestItem['AP'],\n      ['countryOrigin']: requestItem['Pais Origen'],\n      ['observation']: requestItem['Observacion']\n    };\n  }\n\n  private checkSameVenue(venueA: any, venueB: any){\n    const sameName = venueA.name?.trim().toLowerCase() === venueB?.trim().toLowerCase();\n    const foundCode = venueB?.length && (venueA.code?.trim().toLowerCase() === venueB?.trim().toLowerCase());\n    return sameName || foundCode\n  }\n\n  private processSettings(file: File): void {\n    this.setState({\n      loading: true\n    });\n    if (['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'].includes(file.type)) {\n      const reader = new FileReader();\n      const rABS = !!reader.readAsBinaryString;\n      reader.onload = (e: any) => {\n        const { channels, operationTypes } = this.state;\n        let data = e.target.result;\n        if (!rABS) {\n          data = new Uint8Array(data);\n        }\n        const workbook: XLSX.WorkBook = XLSX.read(data, {\n          type: rABS ? 'binary' : 'array',\n          cellDates: true\n        });\n        const excelData = 'Propiedades' in workbook.Sheets\n          ? XLSX.utils.sheet_to_json(workbook.Sheets.Propiedades)\n          : [];\n        if (excelData.length >= 1) {\n          const requestByNumber = excelData.reduce<any>((acc: any, cur: any) => {\n            const key = cur['Numero solicitud'];\n            if (!acc.hasOwnProperty(key)) {\n              acc[key] = {\n                ['number']: key,\n                ['sellerText']: cur['Vendedor'],\n                ['channel']: channels.find((channel) => {\n                  return channel.name?.trim().toLowerCase() === cur['Canal']?.trim().toLowerCase();\n                })?._id,\n                ['operationType']: operationTypes.find((operationType) => {\n                  return operationType.name?.trim().toLowerCase() === cur['Tipo operacion']?.trim().toLowerCase();\n                })?._id,\n                cars: [this.parseRequestItem(cur)]\n              };\n            } else {\n              acc[key] = {\n                ...acc[key],\n                cars: [...acc[key].cars, this.parseRequestItem(cur)]\n              };\n            }\n            return acc;\n          }, {});\n\n          this.setState({\n            loading: false,\n            requests: Object.values(requestByNumber)\n              .sort((a: any, b: any) => {\n                return a['number'].localeCompare(b['number'], 'en', { numeric: true });\n              })\n          }, () => {\n            console.log('this.state.requests', this.state.requests);\n          });\n        } else {\n          swal!(\n            'Importador de configuración',\n            `\"${file.name}\" no cumple con los requisitos mínimos o no tiene unidades.`,\n            'error'\n          );\n          this.setState({\n            loading: false\n          });\n        }\n      };\n      if (rABS) {\n        reader.readAsBinaryString(file);\n      } else {\n        reader.readAsArrayBuffer(file);\n      }\n      if (this.inputFile.current) {\n        this.inputFile.current.value = '';\n      }\n    }\n  }\n\n  private sendCreate(data: any): void {\n    const { history } = this.props;\n    this.setState({\n      sending: true\n    });\n    const api = new ApiService();\n    api.getSource();\n    api\n      .importRequests(data)\n      .then((response: any) => {\n        const { message } = response.data;\n        console.log('message', message);\n        history.push('/requests/vehicles/');\n        setTimeout(() => {\n          swal!('Importador de solicitudes', message, 'success');\n        }, 200);\n        this.setState({\n          sending: false\n        });\n      })\n      .catch((error) => {\n        if (error.status === 400) {\n          swal!('Importador de solicitudes', error.data.message, 'error');\n        } else {\n          api.errorHandler(error);\n        }\n        this.setState({\n          sending: false\n        });\n      });\n  }\n}\n\nconst mapStateToProps = (state: { requestItems: IRequestItemsState }) => {\n  return {\n    requestItems: state.requestItems\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(RequestUpdaterView);\n","import * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { FieldArray, formValueSelector, InjectedFormProps, reduxForm } from 'redux-form';\nimport * as Raven from 'raven-js';\nimport TransmittalActions from '../../../actions/transmittal.actions';\nimport { connect } from 'react-redux';\nimport RequestImportRenderItem, { IRequestImportRenderItemProps } from './renders/RequestImportRenderRequest';\nimport { ISalesChannel } from '../../../../../../../src/request/interfaces/salesChannel.interface';\nimport { IOperationType } from '../../../../../../../src/request/interfaces/operationType.interface';\nimport { IReason } from '../../../../../../../src/request/interfaces/reason.interface';\nimport { IVenue } from '../../../../../../../src/app/interfaces/venue.interface';\n\ninterface IPropsType extends InjectedFormProps {\n  channels: ISalesChannel[];\n  operationTypes: IOperationType[];\n  reasons: IReason[];\n  venues: IVenue[];\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass Form extends React.Component<IPropsType, IStateType> {\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { handleSubmit, channels, operationTypes, reasons, venues } = this.props;\n    return (\n      <form onSubmit={handleSubmit}>\n        <FieldArray<IRequestImportRenderItemProps>\n          name='requests'\n          component={RequestImportRenderItem}\n          props={{\n            channels,\n            operationTypes,\n            reasons,\n            venues\n          }}\n        />\n      </form>\n    );\n  }\n}\n\nconst RequestImportForm = reduxForm({\n  form: 'requestImportForm'\n})(Form);\n\nconst mapStateToProps = (state: { /*transmittal: ITransmittalState*/ }) => {\n  const selector = formValueSelector('transmittalForm');\n  return {\n    // formValues: selector(state, 'carrier', 'driver', 'files', 'items'),\n    // transmittal: state.transmittal\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions\n  };\n};\n\nexport default connect<{ /*transmittal: ITransmittalState*/ }, { dispatch: any }, any>(mapStateToProps, mapDispatchToProps)(RequestImportForm);\n","import * as React from 'react';\nimport { autofill, Field, FieldArray, formValueSelector, WrappedFieldArrayProps } from 'redux-form';\nimport { IRenderItemProps } from '../../../Transmittal/TransmittalForms/renders/TramittalRenderItem';\nimport { ITransmittalState } from '../../../../actions/transmittal.types';\nimport TransmittalActions from '../../../../actions/transmittal.actions';\nimport { connect } from 'react-redux';\nimport InputField from '../../../Utils/forms/InputField';\nimport BootstrapSelectField from '../../../Utils/forms/BootstrapSelectField';\nimport { inputStringRequired } from '../../../Utils/forms/validations';\nimport { ISalesChannel } from '../../../../../../../../src/request/interfaces/salesChannel.interface';\nimport { IOperationType } from '../../../../../../../../src/request/interfaces/operationType.interface';\nimport { Dispatch } from 'redux';\nimport RequestImportRenderRequestItem from './RequestImportRenderRequestItem';\nimport { IReason } from '../../../../../../../../src/request/interfaces/reason.interface';\nimport { IVenue } from '../../../../../../../../src/app/interfaces/venue.interface';\nimport ShowIf from '../../../Utils/ShowIf';\n\nexport interface IRequestImportRenderItemProps {\n  channels: ISalesChannel[];\n  operationTypes: IOperationType[];\n  reasons: IReason[];\n  venues: IVenue[];\n}\n\n\ninterface IPropsType extends WrappedFieldArrayProps<{}>, IRenderItemProps {\n  dispatch: Dispatch<any>;\n  channels: ISalesChannel[];\n  operationTypes: IOperationType[];\n  reasons: IReason[];\n  venues: IVenue[];\n  formValues: any;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass RequestImportRenderRequest extends React.Component<IPropsType, IStateType> {\n\n  public render(): React.ReactElement<IPropsType> {\n    const { fields, meta: { error, submitFailed, warning }, channels, operationTypes, reasons, venues } = this.props;\n    return (\n      <>\n        {\n          fields.map((item, index) => {\n            return (\n              <div className='row' key={index}>\n                <div className='col-md-3'>\n                  <Field\n                    name={`${item}.number`}\n                    label='Número de Solicitud'\n                    type='text'\n                    component={InputField}\n                    validate={[inputStringRequired]}\n                  />\n                </div>\n                <div className='col-md-3'>\n                  <Field\n                    name={`${item}.sellerText`}\n                    label='Vendedor'\n                    type='text'\n                    component={InputField}\n                  />\n                </div>\n                <div className='col-md-3'>\n                  <Field\n                    name={`${item}.channel`}\n                    label='Canal'\n                    component={BootstrapSelectField}\n                    validate={[]}\n                    props={{\n                      noneSelectedText: 'Seleccione...',\n                      displayItems: 2,\n                      autoClouse: true,\n                      sm: true,\n                      allOption: false,\n                      search: true,\n                      options: [\n                        ...channels.map((channel) => ({\n                          value: channel._id,\n                          text: channel.name\n                        }))\n                      ],\n                      onClick: (value: string) => {\n                        this.props.dispatch(\n                          autofill('requestImportForm', `${item}.channel`, value)\n                        );\n                      }\n                    }}\n                  >\n                  </Field>\n                </div>\n                <div className='col-md-3'>\n                  <Field\n                    name={`${item}.operationType`}\n                    label='Tipo operación'\n                    component={BootstrapSelectField}\n                    validate={[]}\n                    props={{\n                      noneSelectedText: 'Seleccione...',\n                      displayItems: 2,\n                      autoClouse: true,\n                      sm: true,\n                      allOption: false,\n                      search: true,\n                      options: [\n                        ...operationTypes.map((operationType) => ({\n                          value: operationType._id,\n                          text: operationType.name\n                        }))\n                      ],\n                      onClick: (value: string) => {\n                        this.props.dispatch(\n                          autofill('requestImportForm', `${item}.operationType`, value)\n                        );\n                      }\n                    }}\n                  >\n                  </Field>\n                </div>\n                <div className='col-md-12' style={{ paddingBottom: '20px', position: 'static' }}>\n                  <div className='table-responsive'>\n                    <table\n                      className='table table-striped table-sm'\n                      style={{\n                        minWidth: '3400px'\n                      }}\n                    >\n                      <thead>\n                      <tr>\n                        <th className='middle' style={{ width: '150px' }}>Motivo</th>\n                        <th className='middle' style={{ width: '150px' }}>Origen</th>\n                        <th className='middle' style={{ width: '150px' }}>Destino</th>\n                        <th className='middle'>Chasis</th>\n                        <th className='middle'>Motor</th>\n                        <th className='middle'>Marca</th>\n                        <th className='middle'>Modelo</th>\n                        <th className='middle'>Color</th>\n                        <th className='middle'>Tipo</th>\n                        <th className='middle'>Cliente</th>\n                        <th className='middle'>Partida</th>\n                        <th className='middle'>Factura</th>\n                        <th className='middle'>BL</th>\n                        <th className='middle'>Cilindrada</th>\n                        <th className='middle'>Tracción</th>\n                        <th className='middle'>Año Comercial</th>\n                        <th className='middle'>Año Fabricación</th>\n                        <th className='middle'>Monto</th>\n                        <th className='middle'>Seguro</th>\n                        <th className='middle'>Peso</th>\n                        <th className='middle'>Gas</th>\n                        <th className='middle'>AP</th>\n                        <th className='middle'>Pais Origen</th>\n                        <th className='middle'>Observacion</th>\n                      </tr>\n                      </thead>\n                      <tbody>\n                      <FieldArray<any>\n                        name={`${item}.cars`}\n                        component={RequestImportRenderRequestItem}\n                        props={{\n                          channels,\n                          operationTypes,\n                          reasons,\n                          venues\n                        }}\n                      />\n                      </tbody>\n                    </table>\n                  </div>\n                </div>\n              </div>\n            );\n          })\n        }\n      </>\n    );\n  }\n}\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState }) => {\n  const selector = formValueSelector('requestImportForm');\n  return {\n    formValues: selector(state, 'all.origin', 'all.destination'),\n    transmittal: state.transmittal\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions\n  };\n};\n\n\nexport default connect<{}, {}, IRequestImportRenderItemProps>(mapStateToProps, mapDispatchToProps)(RequestImportRenderRequest);\n","import * as React from 'react';\nimport { autofill, Field, formValueSelector, WrappedFieldArrayProps } from 'redux-form';\nimport { IRenderItemProps } from '../../../Transmittal/TransmittalForms/renders/TramittalRenderItem';\nimport { ITransmittalState } from '../../../../actions/transmittal.types';\nimport TransmittalActions from '../../../../actions/transmittal.actions';\nimport { connect } from 'react-redux';\nimport BootstrapSelectField from '../../../Utils/forms/BootstrapSelectField';\nimport { inputStringRequired } from '../../../Utils/forms/validations';\nimport { ISalesChannel } from '../../../../../../../../src/request/interfaces/salesChannel.interface';\nimport { IOperationType } from '../../../../../../../../src/request/interfaces/operationType.interface';\nimport { Dispatch } from 'redux';\nimport { IReason } from '../../../../../../../../src/request/interfaces/reason.interface';\nimport { IVenue } from '../../../../../../../../src/app/interfaces/venue.interface';\nimport InputField from '../../../Utils/forms/InputField';\n\nexport interface IRequestImportRenderItemProps {\n  channels: ISalesChannel[];\n  operationTypes: IOperationType[];\n  reasons: IReason[];\n  venues: IVenue[];\n}\n\n\ninterface IPropsType extends WrappedFieldArrayProps<{}>, IRenderItemProps {\n  dispatch: Dispatch<any>;\n  channels: ISalesChannel[];\n  operationTypes: IOperationType[];\n  reasons: IReason[];\n  venues: IVenue[];\n  formValues: any;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass RequestImportRenderRequestItem extends React.Component<IPropsType, IStateType> {\n\n  public render(): React.ReactElement<IPropsType> {\n    const { fields, meta: { error, submitFailed, warning }, reasons, venues } = this.props;\n    return (\n      <>\n        {\n          fields.map((item, index) => {\n            return (\n              <tr key={index}>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.reason`}\n                    label='Motivo'\n                    component={BootstrapSelectField}\n                    props={{\n                      noneSelectedText: 'Seleccione...',\n                      displayItems: 2,\n                      labelOff: true,\n                      autoClouse: true,\n                      sm: true,\n                      allOption: false,\n                      search: true,\n                      options: [\n                        ...reasons.map((reason) => ({\n                          value: reason._id,\n                          text: reason.name\n                        }))\n                      ],\n                      onClick: (value: string) => {\n                        this.props.dispatch(\n                          autofill('requestImportForm', `${item}.reason`, value)\n                        );\n                      }\n                    }}\n                  >\n                  </Field>\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.origin`}\n                    label='Motivo'\n                    component={BootstrapSelectField}\n                    validate={[inputStringRequired]}\n                    props={{\n                      noneSelectedText: 'Seleccione...',\n                      displayItems: 2,\n                      labelOff: true,\n                      autoClouse: true,\n                      sm: true,\n                      allOption: false,\n                      search: true,\n                      options: [\n                        ...venues.map((venue) => ({\n                          value: venue._id,\n                          text: venue.name\n                        }))\n                      ],\n                      onClick: (value: string) => {\n                        this.props.dispatch(\n                          autofill('requestImportForm', `${item}.origin`, value)\n                        );\n                      }\n                    }}\n                  >\n                  </Field>\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.destination`}\n                    label='Motivo'\n                    component={BootstrapSelectField}\n                    validate={[inputStringRequired]}\n                    props={{\n                      noneSelectedText: 'Seleccione...',\n                      displayItems: 2,\n                      labelOff: true,\n                      autoClouse: true,\n                      sm: true,\n                      allOption: false,\n                      search: true,\n                      options: [\n                        ...venues.map((venue) => ({\n                          value: venue._id,\n                          text: venue.name\n                        }))\n                      ],\n                      onClick: (value: string) => {\n                        this.props.dispatch(\n                          autofill('requestImportForm', `${item}.destination`, value)\n                        );\n                      }\n                    }}\n                  >\n                  </Field>\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.vin`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.engineNumber`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.brand`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.denomination`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.color`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.type`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.client`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.entry`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.invoice`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.bl`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.engineSize`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.driveType`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  {/* pasar a fecha*/}\n                  <Field\n                    name={`${item}.businessYear`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  {/* pasar a fecha*/}\n                  <Field\n                    name={`${item}.manufacturingYear`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.price`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.insurancePrice`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.weight`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.gas`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.ap`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.countryOrigin`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.observation`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n              </tr>\n            );\n          })\n        }\n      </>\n    );\n  }\n}\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState }) => {\n  const selector = formValueSelector('requestImportForm');\n  return {\n    formValues: selector(state, 'all.origin', 'all.destination'),\n    transmittal: state.transmittal\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions\n  };\n};\n\n\nexport default connect<{}, {}, IRequestImportRenderItemProps>(mapStateToProps, mapDispatchToProps)(RequestImportRenderRequestItem);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Link } from 'react-router-dom';\nimport { Dispatch } from 'redux';\nimport { FormAction } from 'redux-form';\nimport { IMilestone } from '../../../../../../src/distribution/interfaces/milestone.interface';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport { IMilestoneState, MilestoneReduxActions } from '../../actions/milestone.types';\nimport { getMilestonesThunkAction, updateMilestoneThunkAction } from '../../actions/milestone.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { showModal, statusFooterButttonsModal } from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport ShowIf from '../Utils/ShowIf';\nimport { IForm } from '../../../../../../src/form/interfaces/form.interface';\nimport { IRequestItemStatus } from '../../../../../../src/request/interfaces/requestItemStatus.interface';\nimport Checkbox from '../Utils/CheckBox';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<MilestoneReduxActions | FormAction>;\n  milestone: IMilestoneState;\n\n  getMilestoneThunkAction(milestoneType: string, nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean): MilestoneReduxActions;\n  // createMilestoneThunkAction(milestone: IMilestone): MilestoneReduxActions;\n  updateMilestoneThunkAction(milestone: IMilestone): MilestoneReduxActions;\n  // deleteMilestoneThunkAction(milestone: IMilestone): MilestoneReduxActions;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n  milestoneType: string;\n}\n\ndeclare let window: IWindow;\n\nclass MilestoneListView extends TrackingBasePage<IPropsType, IStateType> {\n  public title: string;\n\n  private socket: Socket;\n  readonly state = {\n    error: null,\n    milestoneType: '',\n    exporing: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado Hitos';\n    this.changePage = this.changePage.bind(this);\n    /*this.createMilestone = this.createMilestone.bind(this);\n    this.processCreateMilestone = this.processCreateMilestone.bind(this);*/\n    /*this.updateMilestone = this.updateMilestone.bind(this);*/\n    this.processUpdateMilestone = this.processUpdateMilestone.bind(this);\n    // this.deleteMilestone = this.deleteMilestone.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const { pagination } = this.props.milestone;\n    const { orderBy, orderType } = this.props.milestone.options;\n    const { milestoneType } = this.state;\n    this.props.getMilestoneThunkAction(milestoneType, pagination.page, orderBy, orderType);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: { token: (window.user as any).token }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `operation-type-list-${window.user.team._id}` });\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update) {\n        const { pagination } = this.props.milestone;\n        const { orderBy, orderType } = this.props.milestone.options;\n        const { milestoneType } = this.state;\n        this.props.getMilestoneThunkAction(milestoneType, pagination.page, orderBy, orderType, true);\n      }\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if (this.props.milestone.pagination !== prevProps.milestone.pagination) {\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.milestone.source) {\n      this.props.milestone.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, milestones, pagination, forms, requestStatus, milestoneTypes } = this.props.milestone;\n    const { milestoneType } = this.state;\n    // const canEdit = hasPermission(window.user, 'adminRequest');\n    // const canDelete = hasPermission(window.user, 'adminRequest');\n    return (\n      <AppContainer title='' cMenu='3' cSubMenu='3.3' cAction='Hitos'>\n        <section className='content'>\n          <div className='row'>\n            <div className='col-md-3'>\n              <div className='list-group'>\n                <Link to='/requests/settings/reasons/' className='list-group-item'>\n                  Motivos\n                </Link>\n                <Link to='/requests/settings/channels/' className='list-group-item'>\n                  Canales\n                </Link>\n                <Link to='/requests/settings/status/' className='list-group-item'>\n                  Estados\n                </Link>\n                <Link to='/requests/settings/operations-type/' className='list-group-item'>\n                  Tipos de operación\n                </Link>\n                <Link to=\"/requests/settings/payment-methods/\" className=\"list-group-item\">\n                  Métodos de pago\n                </Link>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone-type/' className='list-group-item'>\n                    Tipos de hitos\n                  </Link>\n                </ShowIf>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone/' className='list-group-item active'>\n                    Hitos\n                  </Link>\n                </ShowIf>\n              </div>\n            </div>\n            <div className='col-md-9'>\n              <div className='box'>\n                <div className='box-header with-border'>\n                  <h3 className='box-title'>Hitos <small>{pagination.count}</small></h3>\n                  <div className='box-tools pull-right'>\n                   {/* {\n                      hasPermission(window.user, 'addVenue') ?\n                        <button className='btn btn-sm btn-success'\n                                onClick={this.createMilestone}\n                        ><i className='fa fa-plus' /> Agregar</button>\n                        : null\n                    }*/}\n                  </div>\n                </div>\n                <div className='box-body table-responsive no-padding'>\n                  <div className='row' style={{padding: '10px'}}>\n                    {/*<div className='col-md-offset-8 col-md-4'>*/}\n                    <div className='col-md-5'>\n                      <div className={`form-group`} style={{margin: '0'}}>\n                        <label className='control-label'>Seleccione hito a configurar</label>\n                        <div className=\"input-group\">\n                        <select\n                          className='form-control select-sm font-12'\n                          onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                            this.setState({\n                              milestoneType: e.target.value\n                            }, () => {\n                              const { orderBy, orderType } = this.props.milestone.options;\n                              const { milestoneType } = this.state;\n                              this.props.getMilestoneThunkAction(milestoneType, 1, orderBy, orderType);\n                            });\n                          }}\n                        >\n                          <option key={''} value={''}>Seleccione</option>\n                          {\n                            milestoneTypes.map((milestoneType) => (\n                              <option key={milestoneType._id} value={milestoneType._id}>{milestoneType.name}</option>\n                            ))\n                          }\n                        </select>\n                          <div className='input-group-addon input-group-primary pointer'>\n                            <i className='fa fa-cogs' />\n                          </div>\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n                  <ShowIf condition={!loading && !!milestoneType?.length}>\n                    <table className='table table-andes table-striped'>\n                      <thead>\n                      <tr>\n                        <th className='middle' style={{ width: '20px' }}>Orden</th>\n                        <th className='middle'>Paso</th>\n                        <th className='middle'>Tipo</th>\n                        <th className='middle'>Formulario</th>\n                        <th className='middle'>Estado solicitudes</th>\n                        <th className='middle'>F. Arribo</th>\n                      </tr>\n                      </thead>\n                      <tbody>\n                      {\n                        milestones.map((item) => {\n                          return (\n                            <tr key={item._id}>\n                              <td className='middle-center'>{item.order}</td>\n                              <td className='middle'>{item.name}</td>\n                              <td className='middle'>\n                                <select\n                                  className='form-control select-sm font-12' value={item.kind}\n                                  onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                                    this.props.updateMilestoneThunkAction({\n                                      ...item,\n                                      kind: e.target.value\n                                    });\n                                  }}\n                                >\n                                  <option key={'form'} value={'form'}>Formulario</option>\n                                  <option key={'file'} value={'file'}>Archivo</option>\n                                </select>\n                              </td>\n                              <td className='middle'>\n                                <ShowIf condition={item.kind === 'form'}>\n                                  <select\n                                    className='form-control select-sm font-12' value={item.form?._id ?? ''}\n                                    onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                                      this.props.updateMilestoneThunkAction({\n                                        ...item,\n                                        form: e.target.value as unknown as IForm\n                                      });\n                                    }}\n                                  >\n                                    <option value='' disabled={true}>Seleccione</option>\n                                    {\n                                      forms.map((form) => (\n                                        <option key={form._id} value={form._id}>{`${form.name}`}</option>\n                                      ))\n                                    }\n                                  </select>\n                                </ShowIf>\n                              </td>\n                              <td className='middle'>\n                                <ShowIf condition={item.kind === 'form'}>\n                                  <select\n                                    className='form-control select-sm font-12' value={item.requestItemStatus?._id ?? ''}\n                                    onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                                      this.props.updateMilestoneThunkAction({\n                                        ...item,\n                                        requestItemStatus: e.target.value as unknown as IRequestItemStatus\n                                      });\n                                    }}\n                                  >\n                                    <option value={''}>Seleccione</option>\n                                    {\n                                      requestStatus.map((status) => (\n                                        <option key={status._id} value={status._id}>{`${status.name}`}</option>\n                                      ))\n                                    }\n                                  </select>\n                                </ShowIf>\n                              </td>\n                              <td className='middle'>\n                                <ShowIf condition={item.kind === 'form'}>\n                                  <Checkbox\n                                    active={item.updateItems.arrivalDate}\n                                    action={() => {\n                                      this.props.updateMilestoneThunkAction({\n                                        ...item,\n                                        updateItems: {\n                                          arrivalDate: !item.updateItems.arrivalDate\n                                        }\n                                      });\n                                    }}\n                                    classes='icheck-in-checkbox'\n                                    style={{ marginTop: '-4px', marginRight: '5px' }}\n                                  />\n                                </ShowIf>\n                              </td>\n                            </tr>\n                          );\n                        })\n                      }\n                      </tbody>\n                    </table>\n                  </ShowIf>\n                </div>\n                {\n                  pagination.pages > 1 &&\n                  <div className='box-footer text-right'>\n                    <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                  </div>\n                }\n                {\n                  loading &&\n                  <div className='overlay'>\n                    <i className='fa fa-spinner fa-spin text-purple' />\n                  </div>\n                }\n              </div>\n            </div>\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  /*private createMilestone(): void {\n    this.props.loadDataAction(\n      'Agregar tipo de operación',\n      <MilestoneForm\n        initialValues={{ update: false }}\n        onSubmit={this.processCreateMilestone}\n      />,\n      <React.Fragment>\n        <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cancelar</button>\n        <button type='button' className='btn btn-sm btn-primary' onClick={() => this.props.dispatch(submit('milestoneForm'))}>Grabar</button>\n      </React.Fragment>\n    );\n  }*/\n\n  /*private processCreateMilestone(milestone: any): void {\n    statusFooterButttonsModal(true);\n    this.props.createMilestoneThunkAction(milestone);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }*/\n\n  /*private updateMilestone(milestone: any): void {\n    this.props.loadDataAction(\n      'Editar hito',\n      <MilestoneForm\n        initialValues={{ update: false, ...milestone }}\n        onSubmit={this.processUpdateMilestone}\n      />,\n      <React.Fragment>\n        <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cancelar</button>\n        <button type='button' className='btn btn-sm btn-primary' onClick={() => this.props.dispatch(submit('milestoneForm'))}>Editar</button>\n      </React.Fragment>\n    );\n  }*/\n\n  private processUpdateMilestone(milestone: any): void {\n    statusFooterButttonsModal(true);\n    this.props.updateMilestoneThunkAction(milestone);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  /*private deleteMilestone(milestone: IMilestone): void {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el tipo de operación ${milestone.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteMilestoneThunkAction(milestone);\n      }\n    });\n  }*/\n\n  private changePage(page: number): void {\n    // change the page\n    const { orderBy, orderType } = this.props.milestone.options;\n    const {milestoneType} = this.state;\n    this.props.getMilestoneThunkAction(milestoneType, page, orderBy, orderType);\n  }\n}\n\nconst mapStateToProps = (state: { milestone: IMilestoneState }) => {\n  return {\n    milestone: state.milestone\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getMilestoneThunkAction: (milestoneType: string,nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) => dispatch(getMilestonesThunkAction(milestoneType, nextPage, orderBy, orderType, hideLoading)),\n    // createMilestoneThunkAction: (milestone: IMilestone) => dispatch(createMilestoneThunkAction(milestone)),\n    updateMilestoneThunkAction: (milestone: IMilestone) => dispatch(updateMilestoneThunkAction(milestone)),\n    // deleteMilestoneThunkAction: (milestone: IMilestone) => dispatch(deleteMilestoneItemThunkAction(milestone)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{ milestone: IMilestoneState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(MilestoneListView);\n","import Axios, { AxiosError, AxiosResponse, CancelTokenSource } from 'axios';\nimport { Dispatch } from 'redux';\nimport { IMilestone } from '../../../../../src/distribution/interfaces/milestone.interface';\nimport ApiService from '../utils/axios';\nimport {\n  MILESTONE_IS_LOADING,\n  MILESTONE_CHANGE_ORDER,\n  MILESTONE_CANCEL_STATUS,\n  MILESTONE_LOAD_STATUS,\n  MILESTONE_CREATE_STATUS,\n  MILESTONE_UDPATE_STATUS,\n  MILESTONE_DELETE_STATUS,\n  ICreateMilestone,\n  ICancelMilestone,\n  IIsLoadingMilestone,\n  ILoadMilestone,\n  IUpdateMilestone,\n  IDeleteMilestone,\n  IChangeOrderMilestone,\n  IMilestoneState,\n  MilestoneReduxActions,\n  MILESTONE_LOAD_FORMS,\n  MILESTONE_LOAD_REQUEST_STATUS,\n  ILoadRequestStatusMilestone,\n  ILoadFormsMilestone, ILoadTypesMilestone, MILESTONE_LOAD_TYPES\n} from './milestone.types';\nimport { IForm } from '../../../../../src/form/interfaces/form.interface';\nimport { IRequestStatus } from '../../../../../src/request/interfaces/requestStatus.interface';\nimport { IMilestoneType } from '../../../../../src/distribution/interfaces/milestoneType.interface';\n\nexport function cancelMilestoneAction(source: CancelTokenSource): ICancelMilestone {\n  return {\n    type: MILESTONE_CANCEL_STATUS,\n    payload: {\n      source\n    }\n  };\n}\n\nexport function isLoadingMilestoneAction(loading: boolean): IIsLoadingMilestone {\n  return {\n    type: MILESTONE_IS_LOADING,\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function loadMilestoneAction(milestones: IMilestone[], count: number, pages: number, page: number): ILoadMilestone {\n  return {\n    type: MILESTONE_LOAD_STATUS,\n    payload: {\n      milestones,\n      count,\n      pages,\n      page\n    }\n  };\n}\n\n\nexport function loadFormsMilestoneAction(forms: IForm[]): ILoadFormsMilestone {\n  return {\n    type: MILESTONE_LOAD_FORMS,\n    payload: {\n      forms\n    }\n  };\n}\n\nexport function loadTypesMilestoneAction(milestoneTypes: IMilestoneType[]): ILoadTypesMilestone {\n  return {\n    type: MILESTONE_LOAD_TYPES,\n    payload: {\n      milestoneTypes\n    }\n  };\n}\n\nexport function loadRequestStatusMilestoneAction(requestStatus: IRequestStatus[]): ILoadRequestStatusMilestone {\n  return {\n    type: MILESTONE_LOAD_REQUEST_STATUS,\n    payload: {\n      requestStatus\n    }\n  };\n}\n\n\nexport function createMilestoneAction(milestone: IMilestone): ICreateMilestone {\n  return {\n    type: MILESTONE_CREATE_STATUS,\n    payload: {\n      milestone\n    }\n  };\n}\n\nexport function updateMilestoneAction(milestone: IMilestone): IUpdateMilestone {\n  return {\n    type: MILESTONE_UDPATE_STATUS,\n    payload: {\n      milestone\n    }\n  };\n}\n\n\nexport function deleteMilestoneAction(milestone: IMilestone): IDeleteMilestone {\n  return {\n    type: MILESTONE_DELETE_STATUS,\n    payload: {\n      milestone\n    }\n  };\n}\n\nexport function changeOrderMilestoneAction(orderBy: string, orderType: string): IChangeOrderMilestone {\n  return {\n    type: MILESTONE_CHANGE_ORDER,\n    payload: {\n      orderBy,\n      orderType\n    }\n  };\n}\n\nexport function getMilestonesThunkAction(milestoneType: string, nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) {\n  return (dispatch: Dispatch<MilestoneReduxActions>, getState: () => { milestone: IMilestoneState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(isLoadingMilestoneAction(!hideLoading));\n    const page = nextPage ? nextPage : state.milestone.pagination.page;\n    dispatch(changeOrderMilestoneAction(orderBy, orderType));\n    dispatch(cancelMilestoneAction(api.getSource()));\n    Axios\n      .all([\n        api.getMilestones({ milestoneType, page, orderBy, orderType }),\n        api.getMilestoneTypes({ page: 1, pageSize: 200 }),\n        api.getForms(1, 200),\n        api.getRequestItemsStatus({ page:1, pageSize: 200 })\n      ])\n      .then(Axios.spread((milestones, types, forms, requestStatus) => {\n        const { data } = milestones;\n        dispatch(loadMilestoneAction(data.results, data.count, data.pages, page));\n        dispatch(loadTypesMilestoneAction(types.data.results));\n        dispatch(loadFormsMilestoneAction(forms.data.results));\n        dispatch(loadRequestStatusMilestoneAction(requestStatus.data.results));\n        dispatch(isLoadingMilestoneAction(false));\n      }))\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingMilestoneAction(false));\n        api.errorHandler(err);\n      });\n  };\n\n}\n\n/*export function createMilestoneThunkAction(milestone: IMilestone) {\n  return (dispatch: Dispatch<MilestoneReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.createMilestone(milestone)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateMilestoneAction(idMilestone, data));\n      });\n  };\n}*/\n\nexport function updateMilestoneThunkAction(milestone: IMilestone) {\n  return (dispatch: Dispatch<MilestoneReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.updateMilestone(milestone)\n      .then((response: AxiosResponse) => {\n        dispatch(updateMilestoneAction(response.data.data));\n      });\n  };\n}\n\n/*export function deleteMilestoneThunkAction(milestone: IMilestone) {\n  return (dispatch: Dispatch<MilestoneReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.deleteMilestone(milestone)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateMilestoneAction(idMilestone, data));\n      });\n  };\n}*/\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Link } from 'react-router-dom';\nimport { Dispatch } from 'redux';\nimport { FormAction, submit } from 'redux-form';\nimport * as swal from 'sweetalert';\nimport { IMilestoneType } from '../../../../../../src/distribution/interfaces/milestoneType.interface';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport { IMilestoneTypeState, MilestoneTypeReduxActions } from '../../actions/milestoneType.types';\nimport {\n  createMilestoneTypeThunkAction,\n  deleteMilestoneTypeItemThunkAction,\n  getMilestoneTypesThunkAction,\n  updateMilestoneTypeThunkAction\n} from '../../actions/milestoneType.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { hasPermission, showModal, statusFooterButttonsModal } from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport MilestoneTypeForm from './MilestoneTypeForm';\nimport ShowIf from '../Utils/ShowIf';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<MilestoneTypeReduxActions | FormAction>;\n  milestoneType: IMilestoneTypeState;\n\n  getMilestoneTypeThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean): MilestoneTypeReduxActions;\n\n  createMilestoneTypeThunkAction(milestoneType: IMilestoneType): MilestoneTypeReduxActions;\n\n  updateMilestoneTypeThunkAction(milestoneType: IMilestoneType): MilestoneTypeReduxActions;\n\n  deleteMilestoneTypeThunkAction(milestoneType: IMilestoneType): MilestoneTypeReduxActions;\n\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass MilestoneTypeListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  private socket: Socket;\n  readonly state = {\n    error: null,\n    exporing: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado Tipo de Hitos';\n    this.changePage = this.changePage.bind(this);\n    this.createMilestoneType = this.createMilestoneType.bind(this);\n    this.processCreateMilestoneType = this.processCreateMilestoneType.bind(this);\n    this.updateReaon = this.updateReaon.bind(this);\n    this.processUpdateMilestoneType = this.processUpdateMilestoneType.bind(this);\n    this.deleteMilestoneType = this.deleteMilestoneType.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const { pagination } = this.props.milestoneType;\n    const { orderBy, orderType } = this.props.milestoneType.options;\n    this.props.getMilestoneTypeThunkAction(pagination.page, orderBy, orderType);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: { token: (window.user as any).token }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `milestone-type-list-${window.user.team._id}` });\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update) {\n        const { pagination } = this.props.milestoneType;\n        const { orderBy, orderType } = this.props.milestoneType.options;\n        this.props.getMilestoneTypeThunkAction(pagination.page, orderBy, orderType, true);\n      }\n    });\n  }\n\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if (this.props.milestoneType.pagination !== prevProps.milestoneType.pagination) {\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.milestoneType.source) {\n      this.props.milestoneType.source.cancel('Milestone canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, milestoneTypes, pagination } = this.props.milestoneType;\n    const canEdit = hasPermission(window.user, 'adminRequest');\n    const canDelete = hasPermission(window.user, 'adminRequest');\n    return (\n      <AppContainer title='' cMenu='3' cSubMenu='3.3' cAction='Tipos de Hitos'>\n        <section className='content'>\n          <div className='row'>\n            <div className='col-md-3'>\n              <div className='list-group'>\n                <Link to='/requests/settings/reasons/' className='list-group-item'>\n                  Motivos\n                </Link>\n                <Link to='/requests/settings/channels/' className='list-group-item'>\n                  Canales\n                </Link>\n                <Link to='/requests/settings/status/' className='list-group-item'>\n                  Estados\n                </Link>\n                <Link to='/requests/settings/operations-type/' className='list-group-item'>\n                  Tipos de operación\n                </Link>\n                <Link to=\"/requests/settings/payment-methods/\" className=\"list-group-item\">\n                  Métodos de pago\n                </Link>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone-type/' className='list-group-item active'>\n                    Tipos de hitos\n                  </Link>\n                </ShowIf>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone/' className='list-group-item'>\n                    Hitos\n                  </Link>\n                </ShowIf>\n              </div>\n            </div>\n            <div className='col-md-9'>\n              <div className='box'>\n                <div className='box-header with-border'>\n                  <h3 className='box-title'>Tipos de Hitos <small>{pagination.count}</small></h3>\n                  <div className='box-tools pull-right'>\n                    {\n                      hasPermission(window.user, 'addVenue') ?\n                        <button className='btn btn-sm btn-success'\n                                onClick={this.createMilestoneType}\n                        ><i className='fa fa-plus' /> Agregar</button>\n                        : null\n                    }\n                  </div>\n                </div>\n                <div className='box-body table-responsive no-padding'>\n                  <table className='table table-andes table-striped'>\n                    <thead>\n                    <tr>\n                      <th style={{ width: '98%' }} className='middle'>Nombre</th>\n                      {\n                        canEdit ?\n                          <th style={{ width: '1%' }} className='width-10' /> : null\n                      }\n                      {\n                        canDelete ?\n                          <th style={{ width: '1%' }} className='width-10' /> : null\n                      }\n                    </tr>\n                    </thead>\n                    <tbody>\n                    {\n                      milestoneTypes.map((item) => {\n                        return (\n                          <tr key={item._id}>\n                            <td className='middle'>{item.name}</td>\n                            {\n                              canEdit ?\n                                <td\n                                  className='middle text-blue pointer'\n                                  onClick={() => this.updateReaon(item)}\n                                >\n                                  <i className='fa fa-pencil' />\n                                </td> : null\n                            }\n                            {\n                              canDelete ?\n                                <td\n                                  className={canDelete ? 'middle text-red pointer' : 'middle text-muted not-allowed'}\n                                  // className={'middle text-red pointer'}\n                                  onClick={canDelete ? () => this.deleteMilestoneType(item) : undefined}\n                                >\n                                  <i className='fa fa-minus-circle' />\n                                </td> : null\n                            }\n                          </tr>\n                        );\n                      })\n                    }\n                    </tbody>\n                  </table>\n                </div>\n                {\n                  pagination.pages > 1 &&\n                  <div className='box-footer text-right'>\n                    <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                  </div>\n                }\n                {\n                  loading &&\n                  <div className='overlay'>\n                    <i className='fa fa-spinner fa-spin text-purple' />\n                  </div>\n                }\n              </div>\n            </div>\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private createMilestoneType(): void {\n    this.props.loadDataAction(\n      'Agregar tipo de Hitos',\n      <MilestoneTypeForm\n        initialValues={{ update: false }}\n        onSubmit={this.processCreateMilestoneType}\n      />,\n      <React.Fragment>\n        <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cancelar</button>\n        <button type='button' className='btn btn-sm btn-primary' onClick={() => this.props.dispatch(submit('milestoneTypeForm'))}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processCreateMilestoneType(milestoneType: any): void {\n    statusFooterButttonsModal(true);\n    this.props.createMilestoneTypeThunkAction(milestoneType);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private updateReaon(reason: any): void {\n    this.props.loadDataAction(\n      'Editar tipo de Hitos',\n      <MilestoneTypeForm\n        initialValues={{ update: false, ...reason }}\n        onSubmit={this.processUpdateMilestoneType}\n      />,\n      <React.Fragment>\n        <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cancelar</button>\n        <button type='button' className='btn btn-sm btn-primary' onClick={() => this.props.dispatch(submit('milestoneTypeForm'))}>Editar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processUpdateMilestoneType(milestoneType: any): void {\n    statusFooterButttonsModal(true);\n    this.props.updateMilestoneTypeThunkAction(milestoneType);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private deleteMilestoneType(milestoneType: IMilestoneType): void {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el tipo de hito: ${milestoneType.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteMilestoneTypeThunkAction(milestoneType);\n      }\n    });\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    const { orderBy, orderType } = this.props.milestoneType.options;\n    this.props.getMilestoneTypeThunkAction(page, orderBy, orderType);\n  }\n}\n\nconst mapStateToProps = (state: { milestoneType: IMilestoneTypeState }) => {\n  return {\n    milestoneType: state.milestoneType\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getMilestoneTypeThunkAction: (nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) => dispatch(getMilestoneTypesThunkAction(nextPage, orderBy, orderType, hideLoading)),\n    createMilestoneTypeThunkAction: (milestoneType: IMilestoneType) => dispatch(createMilestoneTypeThunkAction(milestoneType)),\n    updateMilestoneTypeThunkAction: (milestoneType: IMilestoneType) => dispatch(updateMilestoneTypeThunkAction(milestoneType)),\n    deleteMilestoneTypeThunkAction: (milestoneType: IMilestoneType) => dispatch(deleteMilestoneTypeItemThunkAction(milestoneType)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{ milestoneType: IMilestoneTypeState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(MilestoneTypeListView);\n","import Axios, { AxiosError, AxiosResponse, CancelTokenSource } from 'axios';\nimport { Dispatch } from 'redux';\nimport { IMilestoneType } from '../../../../../src/distribution/interfaces/milestoneType.interface';\nimport ApiService from '../utils/axios';\nimport {\n  MILESTONE_TYPE_IS_LOADING,\n  MILESTONE_TYPE_CHANGE_ORDER,\n  MILESTONE_TYPE_CANCEL_STATUS,\n  MILESTONE_TYPE_LOAD_STATUS,\n  MILESTONE_TYPE_CREATE_STATUS,\n  MILESTONE_TYPE_UDPATE_STATUS,\n  MILESTONE_TYPE_DELETE_STATUS,\n  ICreateMilestoneType,\n  ICancelMilestoneType,\n  IIsLoadingMilestoneType,\n  ILoadMilestoneType,\n  IUpdateMilestoneType,\n  IDeleteMilestoneType,\n  IChangeOrderMilestoneType,\n  IMilestoneTypeState,\n  MilestoneTypeReduxActions\n} from './milestoneType.types';\n\nexport function cancelMilestoneTypeAction(source: CancelTokenSource): ICancelMilestoneType {\n  return {\n    type: MILESTONE_TYPE_CANCEL_STATUS,\n    payload: {\n      source\n    }\n  };\n}\n\nexport function isLoadingMilestoneTypeAction(loading: boolean): IIsLoadingMilestoneType {\n  return {\n    type: MILESTONE_TYPE_IS_LOADING,\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function loadMilestoneTypeAction(milestoneTypes: IMilestoneType[], count: number, pages: number, page: number): ILoadMilestoneType {\n  return {\n    type: MILESTONE_TYPE_LOAD_STATUS,\n    payload: {\n      milestoneTypes,\n      count,\n      pages,\n      page\n    }\n  };\n}\n\n\nexport function createMilestoneTypeItemAction(milestoneType: IMilestoneType): ICreateMilestoneType {\n  return {\n    type: MILESTONE_TYPE_CREATE_STATUS,\n    payload: {\n      milestoneType\n    }\n  };\n}\n\nexport function updateMilestoneTypeItemAction(milestoneType: IMilestoneType): IUpdateMilestoneType {\n  return {\n    type: MILESTONE_TYPE_UDPATE_STATUS,\n    payload: {\n      milestoneType\n    }\n  };\n}\n\n\nexport function deleteMilestoneTypeAction(milestoneType: IMilestoneType): IDeleteMilestoneType {\n  return {\n    type: MILESTONE_TYPE_DELETE_STATUS,\n    payload: {\n      milestoneType\n    }\n  };\n}\n\nexport function changeOrderMilestoneTypeAction(orderBy: string, orderType: string): IChangeOrderMilestoneType {\n  return {\n    type: MILESTONE_TYPE_CHANGE_ORDER,\n    payload: {\n      orderBy,\n      orderType\n    }\n  };\n}\n\nexport function getMilestoneTypesThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) {\n  return (dispatch: Dispatch<MilestoneTypeReduxActions>, getState: () => { milestoneType: IMilestoneTypeState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(isLoadingMilestoneTypeAction(!hideLoading));\n    const page = nextPage ? nextPage : state.milestoneType.pagination.page;\n    dispatch(changeOrderMilestoneTypeAction(orderBy, orderType));\n    dispatch(cancelMilestoneTypeAction(api.getSource()));\n    Axios\n      .all([\n        api.getMilestoneTypes({ page, orderBy, orderType })\n      ])\n      .then(Axios.spread((milestoneTypes) => {\n        const { data } = milestoneTypes;\n        dispatch(loadMilestoneTypeAction(data.results, data.count, data.pages, page));\n        dispatch(isLoadingMilestoneTypeAction(false));\n      }))\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingMilestoneTypeAction(false));\n        api.errorHandler(err);\n      });\n  };\n\n}\n\nexport function createMilestoneTypeThunkAction(milestoneType: IMilestoneType) {\n  return (dispatch: Dispatch<MilestoneTypeReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.createMilestoneType(milestoneType)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateMilestoneTypeItemAction(idMilestoneType, data));\n      });\n  };\n}\n\nexport function updateMilestoneTypeThunkAction(milestoneType: IMilestoneType) {\n  return (dispatch: Dispatch<MilestoneTypeReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.updateMilestoneType(milestoneType)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateMilestoneTypeItemAction(idMilestoneType, data));\n      });\n  };\n}\n\nexport function deleteMilestoneTypeItemThunkAction(milestoneType: IMilestoneType) {\n  return (dispatch: Dispatch<MilestoneTypeReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.deleteMilestoneType(milestoneType)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateMilestoneTypeItemAction(idMilestoneType, data));\n      });\n  };\n}\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { Field, InjectedFormProps, reduxForm } from 'redux-form';\nimport { IReasonsState } from '../../actions/reasons.types';\nimport InputField from '../Utils/forms/InputField';\nimport { inputStringRequired } from '../Utils/forms/validations';\n\ninterface IPropsType extends InjectedFormProps {\n  update: boolean;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass Form extends React.Component<IPropsType, IStateType> {\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n  public render(): React.ReactElement<IPropsType> {\n    const { handleSubmit, valid , submitFailed} = this.props;\n    return (\n      <form onSubmit={handleSubmit}>\n        <div className=\"row\">\n          <div className=\"col-md-10\">\n            <Field\n              name=\"name\"\n              label=\"Nombre *\"\n              placeholder=\"Nombre\"\n              type=\"text\"\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>\n          {\n            submitFailed && valid === false &&\n            <div className=\"col-md-12\">\n              <div\n                className=\"alert alert-danger\"\n                style={{marginTop: '20px'}}\n              >\n                Todos los campos con * son obligatorios\n              </div>\n            </div>\n          }\n        </div>\n      </form>\n    );\n  }\n}\n\nconst MilestoneTypeForm = reduxForm({\n  form: 'milestoneTypeForm'\n})(Form);\n\nconst mapStateToProps = (state: { reasons: IReasonsState }) => {\n  return {\n    reasons: state.reasons\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{ reasons: IReasonsState }, { dispatch: any }, IPropsType | {}>(mapStateToProps, mapDispatchToProps)(MilestoneTypeForm);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Link } from 'react-router-dom';\nimport { Dispatch } from 'redux';\nimport { FormAction, submit } from 'redux-form';\nimport * as swal from 'sweetalert';\nimport { IForm } from '../../../../../../src/form/interfaces/form.interface';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport { FormReduxActions, IFormsState } from '../../actions/form.types';\nimport {\n  createFormThunkAction,\n  deleteFormItemThunkAction,\n  getFormsThunkAction,\n  updateFormThunkAction,\n  updateFormWithoutThunkAction\n} from '../../actions/form.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { showModal, statusFooterButttonsModal } from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport FormSettingsForm from './FormForm';\nimport ShowIf from '../Utils/ShowIf';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport BootstrapSwitch from '../Utils/BootstrapSwitch';\n\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<FormReduxActions | FormAction>;\n  forms: IFormsState;\n\n  getFormThunkAction(nextPage: number, hideLoading?: boolean): FormReduxActions;\n\n  createFormThunkAction(form: IForm): FormReduxActions;\n\n  updateFormThunkAction(form: IForm): FormReduxActions;\n\n  updateFormWithoutThunkAction(form: IForm): FormReduxActions;\n\n  deleteFormThunkAction(form: IForm): FormReduxActions;\n\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass FormListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  private socket: Socket;\n  readonly state = {\n    error: null,\n    exporing: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado Formularios';\n    this.changePage = this.changePage.bind(this);\n    this.createForm = this.createForm.bind(this);\n    this.processCreateForm = this.processCreateForm.bind(this);\n    this.updateForm = this.updateForm.bind(this);\n    this.processUpdateForm = this.processUpdateForm.bind(this);\n    this.deleteForm = this.deleteForm.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const { pagination } = this.props.forms;\n    // const { orderBy, orderType } = this.props.form.options;\n    this.props.getFormThunkAction(pagination.page);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: { token: (window.user as any).token }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `forms-list-${window.user.team._id}` });\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update) {\n        const { pagination } = this.props.forms;\n        // const { orderBy, orderType } = this.props.form.options;\n        this.props.getFormThunkAction(pagination.page, true);\n      }\n    });\n  }\n\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if (this.props.forms.pagination !== prevProps.forms.pagination) {\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.forms.source) {\n      this.props.forms.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, forms, pagination } = this.props.forms;\n    const canEdit = true;\n    const canDelete = true;\n    return (\n      <AppContainer title='' cMenu='1' cSubMenu='1.10' cAction='Formularios'>\n        <section className='content'>\n          <div className='row'>\n            <div className='col-md-3'>\n              <div className='list-group'>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/requests/settings/forms/' className='list-group-item active'>\n                    Formularios\n                  </Link>\n                </ShowIf>\n              </div>\n            </div>\n            <div className='col-md-9'>\n              <div className='box'>\n                <div className='box-header with-border'>\n                  <h3 className='box-title'>Formularios <small>{pagination.count}</small></h3>\n                  <div className='box-tools pull-right'>\n                    <ShowIf condition={(process.env.NODE_ENV === 'development')}>\n                      <button\n                        className='btn btn-sm btn-success'\n                        onClick={this.createForm}\n                      >\n                        <i className='fa fa-plus' /> Agregar\n                      </button>\n                    </ShowIf>\n                  </div>\n                </div>\n                <div className='box-body table-responsive no-padding'>\n                  <table className='table table-andes table-striped'>\n                    <thead>\n                    <tr>\n                      <th style={{ width: '70%' }} className='middle'>Nombre</th>\n                      <th style={{ width: '16%' }} className='middle-center'>Activo</th>\n                      <th style={{ width: '15%' }} className='middle-center'>Triggers</th>\n                      <ShowIf condition={canEdit}>\n                        <th style={{ width: '1%' }} className='width-10' />\n                      </ShowIf>\n                      <ShowIf condition={canDelete}>\n                        <th style={{ width: '1%' }} className='width-10' />\n                      </ShowIf>\n                    </tr>\n                    </thead>\n                    <tbody>\n                    {\n                      forms.map((item) => {\n                        return (\n                          <tr key={item._id}>\n                            <td className='middle'>{item.name}</td>\n                            <td className='middle-center' style={{ paddingTop: '15px' }}>\n                              <BootstrapSwitch\n                                checked={item.active}\n                                onChange={() => {\n                                  this.props.updateFormWithoutThunkAction({\n                                    ...item,\n                                    active: !item.active\n                                  });\n                                }}\n                              />\n                            </td>\n                            <td className='middle-center'>\n                              {item.triggers?.length ?? 0}\n                            </td>\n                            <ShowIf condition={canEdit}>\n                              <td\n                                className='middle text-blue pointer'\n                                onClick={() => this.updateForm(item)}\n                              >\n                                <i className='fa fa-gears' />\n                              </td>\n                            </ShowIf>\n                            <ShowIf condition={canDelete}>\n                              <td\n                                className={'middle text-red pointer'}\n                                onClick={() => this.deleteForm(item)}\n                              >\n                                <i className='fa fa-minus-circle' />\n                              </td>\n                            </ShowIf>\n                          </tr>\n                        );\n                      })\n                    }\n                    </tbody>\n                  </table>\n                </div>\n                {\n                  pagination.pages > 1 &&\n                  <div className='box-footer text-right'>\n                    <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                  </div>\n                }\n                {\n                  loading &&\n                  <div className='overlay'>\n                    <i className='fa fa-spinner fa-spin text-purple' />\n                  </div>\n                }\n              </div>\n            </div>\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private createForm(): void {\n    this.props.loadDataAction(\n      'Agregar formulario',\n      <FormSettingsForm\n        initialValues={{ update: false }}\n        onSubmit={this.processCreateForm}\n      />,\n      <React.Fragment>\n        <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cancelar</button>\n        <button type='button' className='btn btn-sm btn-primary' onClick={() => this.props.dispatch(submit('formForm'))}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processCreateForm(form: any): void {\n    statusFooterButttonsModal(true);\n    this.props.createFormThunkAction(form);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private updateForm(form: any): void {\n    this.props.loadDataAction(\n      'Editar formulario',\n      <FormSettingsForm\n        initialValues={{ update: false, ...form }}\n        onSubmit={this.processUpdateForm}\n      />,\n      <React.Fragment>\n        <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cancelar</button>\n        <button type='button' className='btn btn-sm btn-primary' onClick={() => this.props.dispatch(submit('formForm'))}>Editar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processUpdateForm(form: any): void {\n    statusFooterButttonsModal(true);\n    this.props.updateFormThunkAction(form);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private deleteForm(form: IForm): void {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el formulario: ${form.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteFormThunkAction(form);\n      }\n    });\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    // const { orderBy, orderType } = this.props.form.options;\n    this.props.getFormThunkAction(page);\n  }\n}\n\nconst mapStateToProps = (state: { forms: IFormsState }) => {\n  return {\n    forms: state.forms\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getFormThunkAction: (nextPage: number, hideLoading?: boolean) => dispatch(getFormsThunkAction(nextPage, hideLoading)),\n    createFormThunkAction: (form: IForm) => dispatch(createFormThunkAction(form)),\n    updateFormThunkAction: (form: IForm) => dispatch(updateFormThunkAction(form)),\n    updateFormWithoutThunkAction: (form: IForm) => dispatch(updateFormWithoutThunkAction(form)),\n    deleteFormThunkAction: (form: IForm) => dispatch(deleteFormItemThunkAction(form)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{ forms: IFormsState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(FormListView);\n","import Axios, { AxiosError, AxiosResponse, CancelTokenSource } from 'axios';\nimport { Dispatch } from 'redux';\nimport { IForm } from '../../../../../src/form/interfaces/form.interface';\nimport ApiService from '../utils/axios';\nimport {\n  FORM_CANCEL_STATUS,\n  FORM_CHANGE_ORDER,\n  FORM_CREATE_STATUS,\n  FORM_DELETE_STATUS,\n  FORM_IS_LOADING,\n  FORM_LOAD_REQUEST_STATUS,\n  FORM_LOAD_STATUS,\n  FORM_UDPATE_STATUS,\n  FormReduxActions,\n  ICancelForm,\n  IChangeOrderForm,\n  ICreateForm,\n  IDeleteForm,\n  IFormsState,\n  IIsLoadingForm,\n  ILoadForm,\n  ILoadRequestStatusForm,\n  IUpdateForm\n} from './form.types';\nimport * as swal from 'sweetalert';\nimport { IRequestStatus } from '../../../../../src/request/interfaces/requestStatus.interface';\n\nexport function cancelFormAction(source: CancelTokenSource): ICancelForm {\n  return {\n    type: FORM_CANCEL_STATUS,\n    payload: {\n      source\n    }\n  };\n}\n\nexport function isLoadingFormAction(loading: boolean): IIsLoadingForm {\n  return {\n    type: FORM_IS_LOADING,\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function loadFormAction(forms: IForm[], count: number, pages: number, page: number): ILoadForm {\n  return {\n    type: FORM_LOAD_STATUS,\n    payload: {\n      forms,\n      count,\n      pages,\n      page\n    }\n  };\n}\n\n\nexport function createFormItemAction(form: IForm): ICreateForm {\n  return {\n    type: FORM_CREATE_STATUS,\n    payload: {\n      form\n    }\n  };\n}\n\nexport function updateFormItemAction(form: IForm): IUpdateForm {\n  return {\n    type: FORM_UDPATE_STATUS,\n    payload: {\n      form\n    }\n  };\n}\n\n\nexport function deleteFormAction(form: IForm): IDeleteForm {\n  return {\n    type: FORM_DELETE_STATUS,\n    payload: {\n      form\n    }\n  };\n}\n\nexport function changeOrderFormAction(orderBy: string, orderType: string): IChangeOrderForm {\n  return {\n    type: FORM_CHANGE_ORDER,\n    payload: {\n      orderBy,\n      orderType\n    }\n  };\n}\n\nexport function loadRequestStatusFormAction(requestStatus: IRequestStatus[]): ILoadRequestStatusForm {\n  return {\n    type: FORM_LOAD_REQUEST_STATUS,\n    payload: {\n      requestStatus\n    }\n  };\n}\n\nexport function getFormsThunkAction(nextPage: number, hideLoading?: boolean) {\n  return (dispatch: Dispatch<FormReduxActions>, getState: () => { form: IFormsState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(isLoadingFormAction(!hideLoading));\n    const page = nextPage ? nextPage : state.form.pagination.page;\n    // dispatch(changeOrderFormAction(orderBy, orderType));\n    dispatch(cancelFormAction(api.getSource()));\n    Axios\n      .all([\n        api.getForms(page),\n        api.getRequestItemsStatus({ page:1, pageSize: 200 })\n      ])\n      .then(Axios.spread((forms, requestStatus) => {\n        const { data } = forms;\n        dispatch(loadFormAction(data.results, data.count, data.pages, page));\n        dispatch(loadRequestStatusFormAction(requestStatus.data.results));\n        dispatch(isLoadingFormAction(false));\n      }))\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingFormAction(false));\n        api.errorHandler(err);\n      });\n  };\n\n}\n\nexport function createFormThunkAction(form: IForm) {\n  return (dispatch: Dispatch<FormReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.createForm(form)\n      .then((response: AxiosResponse) => {\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n      })\n      .catch((err: AxiosError) => {\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function updateFormThunkAction(form: IForm) {\n  return (dispatch: Dispatch<FormReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.updateForm(form)\n      .then((response: AxiosResponse) => {\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n      })\n      .catch((err: AxiosError) => {\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function updateFormWithoutThunkAction(form: IForm) {\n  return (dispatch: Dispatch<FormReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.updateForm(form)\n      .then()\n      .catch((err: AxiosError) => {\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function deleteFormItemThunkAction(form: IForm) {\n  return (dispatch: Dispatch<FormReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.deleteForm(form)\n      .then((response: AxiosResponse) => {\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n      })\n      .catch((err: AxiosError) => {\n        api.errorHandler(err);\n      });\n  };\n}\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { Field, FieldArray, InjectedFormProps, reduxForm } from 'redux-form';\nimport { IFormsState } from '../../actions/form.types';\nimport InputField from '../Utils/forms/InputField';\nimport { inputStringRequired } from '../Utils/forms/validations';\nimport FormTriggerRenderItem, { IFormTriggerRenderItemItemProps } from './renders/FormTriggerRender';\n\ninterface IPropsType extends InjectedFormProps {\n  update: boolean;\n  forms: IFormsState;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass Form extends React.Component<IPropsType, IStateType> {\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n  public render(): React.ReactElement<IPropsType> {\n    const { handleSubmit, valid , submitFailed, forms} = this.props;\n    return (\n      <form onSubmit={handleSubmit}>\n        <div className=\"row\">\n          <div className=\"col-md-12\">\n            <Field\n              name=\"name\"\n              label=\"Nombre *\"\n              placeholder=\"Nombre\"\n              type=\"text\"\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>\n          <div className='col-md-12'>\n            <FieldArray<IFormTriggerRenderItemItemProps>\n              name='triggers'\n              component={FormTriggerRenderItem}\n              props={{\n                forms\n              }}\n            />\n          </div>\n          {\n            submitFailed && !valid &&\n            <div className=\"col-md-12\">\n              <div\n                className=\"alert alert-danger\"\n              >\n                Todos los campos con * son obligatorios\n              </div>\n            </div>\n          }\n        </div>\n      </form>\n    );\n  }\n}\n\nconst FormForm = reduxForm({\n  form: 'formForm'\n})(Form);\n\nconst mapStateToProps = (state: { forms: IFormsState }) => {\n  return {\n    forms: state.forms\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{ forms: IFormsState }, { dispatch: any }, IPropsType | {}>(mapStateToProps, mapDispatchToProps)(FormForm);\n","import * as React from 'react';\nimport { Field, formValueSelector, WrappedFieldArrayProps } from 'redux-form';\nimport { connect } from 'react-redux';\nimport { IFormsState } from '../../../actions/form.types';\nimport InputField from '../../Utils/forms/InputField';\nimport { inputStringRequired } from '../../Utils/forms/validations';\nimport CheckBoxField from '../../Utils/forms/CheckBoxField';\nimport SelectField from '../../Utils/forms/SelectField';\nimport { KindTrigger } from '../../../../../../../src/form/models/trigger.model';\nimport FormFileTriggerRender from './TriggersTypes/FormFileTriggerRender';\nimport FormEmailTriggerRender from './TriggersTypes/FormEmaiTriggerRender';\nimport FormRequestTriggerRender from './TriggersTypes/FormRequestTriggerRender';\nimport ShowIf from '../../Utils/ShowIf';\nimport FormIntegrationTriggerRender from './TriggersTypes/FormIntegrationTriggerRender';\nimport * as uuid from 'uuid';\n\n\nexport interface IFormTriggerRenderItemItemProps {\n  forms: IFormsState;\n}\n\ninterface IPropsType extends WrappedFieldArrayProps<{}>, IFormTriggerRenderItemItemProps {\n  formValues: any;\n}\n\ninterface IStateType {\n  error: Error | null;\n  openTabs: string[];\n}\n\nclass FormTriggerRender extends React.Component<IPropsType, IStateType> {\n\n  readonly state: IStateType = {\n    error: null,\n    openTabs: []\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { fields, meta: { error, submitFailed }, forms } = this.props;\n    const { openTabs } = this.state;\n    return (\n      <React.Fragment>\n        <h4>Triggers</h4>\n        <ShowIf condition={!fields?.length}>\n          <div className='row'>\n            <div className='col-md-12'>\n              <p\n                className='text-center text-muted'\n                style={{ padding: '20px 0' }}\n              >\n                No hay triggers para agregar uno <a href='javascript:void(0)'\n                                                    onClick={() => fields.push({\n                                                      tid: uuid.v4(),\n                                                      enabled: true,\n                                                      config: { method: 'post' }\n                                                    })}>haz click aquí.</a>\n              </p>\n            </div>\n          </div>\n        </ShowIf>\n        {\n          fields.map((item, index) => {\n            const value: any = fields.get(index);\n            const openTab = openTabs.includes(value._id ?? value.tid);\n            return (\n              <div className='row' key={index} style={{paddingTop: '10px'}}>\n                <div className='col-md-4' style={{backgroundColor: '#fff'}}>\n                  <Field\n                    name={`${item}.name`}\n                    label='Nombre *'\n                    placeholder='Nombre'\n                    type='text'\n                    component={InputField}\n                    validate={[inputStringRequired]}\n                  />\n                </div>\n                <div className='col-md-4' style={{backgroundColor: '#fff'}}>\n                  <Field\n                    name={`${item}.kind`}\n                    label='Tipo *'\n                    component={SelectField}\n                    validate={[inputStringRequired]}\n                  >\n                    <option value={''} disabled={true}>Seleccione</option>\n                    <option key={KindTrigger.file} value={KindTrigger.file}>Archivo</option>\n                    <option key={KindTrigger.email} value={KindTrigger.email}>Correo</option>\n                    <option key={KindTrigger.request} value={KindTrigger.request}>Estado solicitudes</option>\n                    <option key={KindTrigger.integration} value={KindTrigger.integration}>Integraciones</option>\n                  </Field>\n                </div>\n                <div className='col-md-2' style={{backgroundColor: '#fff', paddingBottom: '13px'}}>\n                  <Field\n                    name={`${item}.enabled`}\n                    label='Activo'\n                    placeholder='Activo'\n                    type='checkbox'\n                    component={CheckBoxField}\n                    props={{\n                      style: {\n                        marginBottom: 0,\n                        marginTop: '30px'\n                      }\n                    }}\n                    validate={[]}\n                  />\n                </div>\n                <div\n                  className={`col-md-2 pointer text-right`}\n                  style={{ paddingTop: '30px', paddingBottom: '10px', backgroundColor: '#fff' }}\n                >\n                  <ul className=\"list-inline\">\n                    <li onClick={() => fields.remove(index)} style={{padding: '0 10px'}}>\n                      <i className='fa fa-minus-circle text-red' />\n                    </li>\n                    <li onClick={() => this.toogleTab(value._id ?? value.tid)} style={{padding: '0 10px'}}>\n                      {\n                        openTab ? <i className='fa fa-chevron-up' /> : <i className='fa fa-chevron-down' />\n                      }\n                    </li>\n                  </ul>\n                </div>\n                <ShowIf condition={openTab}>\n                  <div\n                    className='col-md-12'\n                    style={{ backgroundColor: '#f4f4f4', paddingTop: '10px', paddingBottom: '10px' }}\n                  >\n                    <ShowIf condition={KindTrigger.file === value.kind}>\n                      <FormFileTriggerRender item={item} />\n                    </ShowIf>\n                    <ShowIf condition={KindTrigger.email === value.kind}>\n                      <FormEmailTriggerRender item={item} value={value} />\n                    </ShowIf>\n                    <ShowIf condition={KindTrigger.request === value.kind}>\n                      <FormRequestTriggerRender item={item} forms={forms} />\n                    </ShowIf>\n                    <ShowIf condition={KindTrigger.integration === value.kind}>\n                      <FormIntegrationTriggerRender item={item} />\n                    </ShowIf>\n                    <ShowIf condition={!value.kind}>\n                      <span className={\"text-muted\"}>Seleccione un tipo</span>\n                    </ShowIf>\n                  </div>\n                </ShowIf>\n              </div>\n            );\n          })\n        }\n        <div className='row' style={{padding: '15px 0'}}>\n          <div className='col-md-12 text-right'>\n            <button\n              className='btn btn-sm btn-success'\n              onClick={() => fields.push({\n                tid: uuid.v4(),\n                enabled: true,\n                config: { method: 'post' } }\n              )}\n            >\n              <i className='fa fa-plus' /> Agregar trigger\n            </button>\n          </div>\n        </div>\n        {submitFailed && error && <span>{error}</span>}\n      </React.Fragment>\n    );\n  }\n\n  private toogleTab(id: string) {\n    const { openTabs } = this.state;\n    if (openTabs.includes(id)) {\n      this.setState({\n        openTabs: [...openTabs.filter(tab => tab !== id)]\n      });\n    } else {\n      this.setState({\n        openTabs: [...openTabs, id]\n      });\n    }\n  }\n}\n\nconst mapStateToProps = (state: { forms: IFormsState }) => {\n  const selector = formValueSelector('formTypeForm');\n  return {\n    formValues: selector(state, 'all.origin', 'all.destination'),\n    forms: state.forms\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IFormTriggerRenderItemItemProps>(mapStateToProps, mapDispatchToProps)(FormTriggerRender);\n","import * as mongoose from 'mongoose';\nimport { IFormTrigger, ITriggerConfig } from '../interfaces/form.interface';\n\nexport enum KindTrigger {\n  file = 'file',\n  email = 'email',\n  request = 'request',\n  integration = 'integration',\n}\n\nexport const kindsTrigger = [\n  KindTrigger.file,\n  KindTrigger.email,\n  KindTrigger.request,\n  KindTrigger.integration\n];\n\nexport enum IntegrationType {\n  http = 'http',\n  sap = 'sap',\n  conecta = 'conecta',\n  integration = 'integration',\n}\n\nexport const integrationTypes = [\n  IntegrationType.http,\n  IntegrationType.sap,\n  IntegrationType.conecta\n];\n\nexport interface ITriggerConfigModel extends ITriggerConfig, mongoose.Types.Subdocument {}\nexport const triggerConfigSchema = new mongoose.Schema({\n  fullname: {\n    type: mongoose.Schema.Types.Mixed\n  },\n  email: {\n    type: mongoose.Schema.Types.Mixed\n  },\n  signature: {\n    type: mongoose.Schema.Types.ObjectId\n  },\n  subject: {\n    type: String\n  },\n  responsible: {\n    type: Boolean,\n    default: false\n  },\n  filename: {\n    type: String\n  },\n  template: {\n    type: String\n  },\n\n  integrationType: {\n    type: String,\n    enum: integrationTypes\n  },\n  header: {\n    type: String\n  },\n  url: {\n    type: String\n  },\n  method: {\n    type: String\n  },\n  body: {\n    type: String\n  },\n\n requestItemStatus: {\n    type: mongoose.Schema.Types.ObjectId,\n    ref: 'RequestItemStatus'\n  },\n});\n\n\nexport interface IFormTriggerModel extends IFormTrigger, mongoose.Document {}\nexport const formTriggerSchema = new mongoose.Schema({\n  name: {\n    type: String,\n    required: true,\n    trim: true\n  },\n  description: {\n    type: String,\n    trim: true\n  },\n\n  kind: {\n    type: String,\n    enum: kindsTrigger\n  },\n\n  enabled: {\n    type: Boolean,\n    default: true\n  },\n\n  config: triggerConfigSchema\n});\n\nconst FormTrigger = mongoose.model<IFormTriggerModel>('FormTrigger', formTriggerSchema);\n\nexport default FormTrigger;\n","import * as React from 'react';\nimport { Field } from 'redux-form';\nimport InputField from '../../../Utils/forms/InputField';\nimport { inputStringRequired } from '../../../Utils/forms/validations';\n\ninterface IPropsType {\n  item: string;\n}\n\ninterface IStateType {\n}\n\nclass FormFileTriggerRender extends React.Component<IPropsType, IStateType> {\n  public render(): React.ReactElement<IPropsType> {\n    const { item } = this.props;\n    return (\n      <div className={`row`}>\n        <div className='col-md-10'>\n          <Field\n            name={`${item}.config.filename`}\n            label='Nombre del archivo'\n            placeholder='voucher.pdf'\n            type='text'\n            component={InputField}\n            validate={[inputStringRequired]}\n          />\n        </div>\n        <div className='col-md-10'>\n          <Field\n            name={`${item}.config.template`}\n            label='Template del archivo'\n            placeholder='vouchers/client-sell.pug'\n            type='text'\n            component={InputField}\n            validate={[inputStringRequired]}\n          />\n        </div>\n        <div className='col-md-10'>\n          <Field\n            name={`${item}.config.signature`}\n            label='ID Signature question (Si desea utilizarla en el template)'\n            placeholder='618ad37fdf7f091efa6c6633'\n            type='text'\n            component={InputField}\n            validate={[]}\n          />\n        </div>\n      </div>\n    );\n  }\n}\n\nexport default FormFileTriggerRender;\n","import * as React from 'react';\nimport { Field } from 'redux-form';\nimport InputField from '../../../Utils/forms/InputField';\nimport { inputStringRequired } from '../../../Utils/forms/validations';\nimport CheckBoxField from \"../../../Utils/forms/CheckBoxField\";\n\ninterface IPropsType {\n  item: string;\n  value: any;\n}\n\ninterface IStateType {\n}\n\nclass FormEmailTriggerRender extends React.Component<IPropsType, IStateType> {\n  public render(): React.ReactElement<IPropsType> {\n    const { item, value } = this.props;\n    return (\n      <div className={`row`}>\n        <div className='col-md-10'>\n          <Field\n            name={`${item}.config.subject`}\n            label='Asunto del correo'\n            placeholder='ACTA DE ENTREGA '\n            type='text'\n            component={InputField}\n            validate={[inputStringRequired]}\n          />\n        </div>\n        <div className='col-md-10'>\n          <Field\n            name={`${item}.config.template`}\n            label='Template del correo'\n            placeholder='vouchers/client-sell.pug'\n            type='text'\n            component={InputField}\n            validate={[inputStringRequired]}\n          />\n        </div>\n        <div className='col-md-10'>\n          <Field\n            name={`${item}.config.responsible`}\n            label='Enviar a responsables de sucursales'\n            type='checkbox'\n            component={CheckBoxField}\n            validate={[]}\n          />\n        </div>\n        { !value.config.responsible ?\n          <>\n          <div className='col-md-10'>\n            <Field\n              name={`${item}.config.fullname`}\n              label='ID pregunta con nombre / campo del usuario que responde / nombre fijo'\n              placeholder=''\n              type='text'\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>\n          <div className='col-md-10'>\n            <Field\n              name={`${item}.config.email`}\n              label='ID pregunta con email / campo del usuario que responde / email fijo'\n              placeholder='example@email.com'\n              type='text'\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>\n        </> : null }\n      </div>\n    );\n  }\n}\n\nexport default FormEmailTriggerRender;\n","import * as React from 'react';\nimport { Field } from 'redux-form';\nimport { inputStringRequired } from '../../../Utils/forms/validations';\nimport SelectField from '../../../Utils/forms/SelectField';\nimport { IFormsState } from '../../../../actions/form.types';\nimport { connect } from 'react-redux';\nimport { IFormTriggerRenderItemItemProps } from '../FormTriggerRender';\n\ninterface IPropsType {\n  item: string;\n  forms: IFormsState;\n}\n\ninterface IStateType {\n}\n\nclass FormRequestTriggerRender extends React.Component<IPropsType, IStateType> {\n  public render(): React.ReactElement<IPropsType> {\n    const { item, forms: {requestStatus} } = this.props;\n    return (\n      <div className={`row`}>\n        <div className='col-md-10'>\n          <Field\n            name={`${item}.config.requestItemStatus`}\n            label='Tipo *'\n            component={SelectField}\n            validate={[inputStringRequired]}\n          >\n            <option value={''} disabled={true}>Seleccione</option>\n            {\n              requestStatus.map((status) => (\n                <option key={status._id} value={status._id}>{status.name}</option>\n              ))\n            }\n          </Field>\n        </div>\n      </div>\n    );\n  }\n}\n\nconst mapStateToProps = (state: { forms: IFormsState }) => {\n  return {\n    forms: state.forms\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IFormTriggerRenderItemItemProps>(mapStateToProps, mapDispatchToProps)(FormRequestTriggerRender);\n","import * as React from 'react';\nimport { Field } from 'redux-form';\nimport InputField from '../../../Utils/forms/InputField';\nimport { inputStringRequired } from '../../../Utils/forms/validations';\nimport TextAreaField from '../../../Utils/forms/TextAreaField';\nimport SelectField from '../../../Utils/forms/SelectField';\n\ninterface IPropsType {\n  item: string;\n}\n\ninterface IStateType {\n}\n\nclass FormIntegrationTriggerRender extends React.Component<IPropsType, IStateType> {\n  public render(): React.ReactElement<IPropsType> {\n    const { item } = this.props;\n    return (\n      <div className={`row`}>\n        <div className='col-md-10'>\n          <Field\n            name={`${item}.config.url`}\n            label='URL'\n            placeholder='https://api.osacontrol.com'\n            type='text'\n            component={InputField}\n            validate={[inputStringRequired]}\n          />\n        </div>\n        <div className='col-md-10'>\n           <Field\n            name={`${item}.config.method`}\n            label='Tipo *'\n            component={SelectField}\n            validate={[inputStringRequired]}\n          >\n            <option value={''} disabled={true}>Seleccione</option>\n            <option value={'post'}>post</option>\n          </Field>\n        </div>\n        <div className='col-md-10'>\n          <Field\n            name={`${item}.config.header`}\n            label='Header'\n            placeholder='Authorization: API-KEY 71fMfsbE6PRamEZrK5iw6TiD1iN416yM'\n            type='text'\n            component={InputField}\n            validate={[]}\n          />\n        </div>\n        <div className='col-md-10'>\n          <Field\n            name={`${item}.config.body`}\n            label='Payload'\n            placeholder='{\"action\": \"hook\"}'\n            component={TextAreaField}\n            type='text'\n            rows={4}\n            props={{\n              resize: 'none'\n            }}\n          />\n        </div>\n      </div>\n    );\n  }\n}\n\nexport default FormIntegrationTriggerRender;\n","import * as React from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { IInventoryState } from '../../actions/inventory.actions';\nimport ApiService from '../../utils/axios';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport RequestForm from './RequestForms/RequestForm';\nimport { AxiosError } from 'axios';\nimport * as swal from 'sweetalert';\nimport { getFormValues } from 'redux-form';\nimport { IWindow } from '../../interfaces/window';\ndeclare let window: IWindow;\n\ninterface IPropsType extends RouteComponentProps<{}> {\n  router: any;\n}\n\ninterface IStateType {\n  error: Error | null;\n  created: boolean;\n}\n\nclass RequestCreateIntegration extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  readonly api: ApiService;\n\n  readonly state: IStateType = {\n    error: null,\n    created: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Crear solicitud';\n    this.handleSubmit = this.handleSubmit.bind(this);\n    this.api = new ApiService();\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    $('body')\n      .removeClass('skin-purple')\n      .css({ 'background-color':'#ecf0f5' });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    let { location: { query } } = this.props.router;\n    query = Object.fromEntries(\n      Object.entries<string>(query).map(([key, value]) =>\n        // Modify key here\n        [`${key}`, decodeURIComponent(value)]\n      )\n    );\n    const {created} = this.state;\n    return (\n      <RequestForm\n        onSubmit={this.handleSubmit}\n        query={query}\n        created={created}\n        initialValues={{\n          conectaID: query['6154722a94bba10012230aae'] || query['conectaID'],\n          // sellerText: query.sellerText,\n          sellerText: `${window.user.firstName} ${window.user.lastName}`,\n          // channel:\n          venue: window.user.venue._id,\n          customerInformation: {\n            rut: query.hasOwnProperty('5bf2de35caf8ef7096105c22') ? query['5bf2de35caf8ef7096105c22'] : '',\n            name: query.hasOwnProperty('5bf2de35caf8ef7096105c21') ? query['5bf2de35caf8ef7096105c21'] : '',\n            email: query.hasOwnProperty('60b9232164adc90013a79b45') ? query['60b9232164adc90013a79b45'] : ''\n          },\n          advancePaymentInformation: {\n            method: '',\n            number: '',\n            files: []\n          },\n          cars: []\n        }}\n      />\n    );\n  }\n\n  private handleSubmit(values: any) {\n    this.api\n      .createRequest({\n        cars: values.cars,\n        channel: values.channel,\n        operationType: values.operationType,\n        venue: values.venue,\n        sellerText: values.sellerText,\n        advancePaymentInformation: values.advancePaymentInformation,\n        customerInformation: values.customerInformation,\n        deliveryVenue: values.deliveryVenue,\n        deliveryAddress: values.deliveryAddress,\n        deliveryDate: values.deliveryDate,\n        conectaID: values.conectaID,\n      })\n      .then((response) => {\n        const { data } = response.data;\n        this.setState({\n          created: true\n        });\n        swal!('Orden creada!', `La orden ha sido creada satisfactoriamente con el Nº${data.number}!`, 'success', {\n          button: false,\n          closeOnClickOutside: false,\n          closeOnEsc: false\n        });\n        window.scrollTo(0, 0);\n      })\n      .catch((err: AxiosError): void => {\n        this.api.errorHandler(err);\n      });\n  }\n}\n\nconst mapStateToProps = (state: { inventories: IInventoryState, router: any }) => {\n  return {\n    inventories: state.inventories,\n    router: state.router\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(RequestCreateIntegration);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { arrayPush, Field, FieldArray, FormErrors, getFormSyncErrors, getFormValues, InjectedFormProps, reduxForm, submit } from 'redux-form';\nimport { AxiosError, default as Axios } from 'axios';\nimport * as moment from 'moment';\nimport { IReason } from '../../../../../../../src/request/interfaces/reason.interface';\nimport { IColor } from '../../../../../../../src/app/interfaces/color.interface';\nimport { ISalesChannel } from '../../../../../../../src/request/interfaces/salesChannel.interface';\nimport { IPaymentMethod } from '../../../../../../../src/request/interfaces/paymentMethod.interface';\nimport { IOperationType } from '../../../../../../../src/request/interfaces/operationType.interface';\nimport ApiService from '../../../utils/axios';\nimport BootstrapSelectField from '../../Utils/forms/BootstrapSelectField';\nimport { inputStringRequired } from '../../Utils/forms/validations';\nimport InputField from '../../Utils/forms/InputField';\nimport { IRenderItemProps } from '../../Request/RequestForms/renders/RequestCarRender';\nimport RequestCarRender from './renders/RequestCarRender';\nimport * as uuid from 'uuid';\nimport DateRangePickerField from '../../Utils/forms/DateRangePickerField';\nimport { DecoratedFormProps } from 'redux-form/lib/reduxForm';\nimport InputHiddenField from '../../Utils/forms/InputHiddenField';\nimport ShowIf from '../../Utils/ShowIf';\nimport { IRequestSetting } from '../../../../../../../src/app/interfaces';\nimport * as  swal from 'sweetalert';\nimport MultiUploadFiles, { imageStatus } from '../../Utils/MultiUploadFiles';\nimport { requestSettings } from '../defaults';\n\ninterface IPropsType extends InjectedFormProps {\n  formValues: any;\n  syncErrors: any;\n  dispatch: any;\n  created: boolean;\n  query: Dictionary<string>;\n}\n\ninterface IStateType {\n  filesCache: Dictionary<any>;\n  error: Error | null;\n  venues: any[];\n  reasons: IReason[];\n  colors: IColor[];\n  channels: ISalesChannel[];\n  paymentMethods: IPaymentMethod[];\n  operationTypes: IOperationType[];\n  requestSettings: IRequestSetting;\n  loading: boolean;\n  exist: boolean;\n}\n\nclass Form extends React.Component<IPropsType, IStateType> {\n\n  readonly api: ApiService;\n  readonly state: IStateType = {\n    filesCache: {},\n    error: null,\n    venues: [],\n    reasons: [],\n    colors: [],\n    channels: [],\n    paymentMethods: [],\n    operationTypes: [],\n    requestSettings,\n    loading: false,\n    exist: false,\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.loadBaseData = this.loadBaseData.bind(this);\n    this.addCarToForm = this.addCarToForm.bind(this);\n    this.updateFileCache = this.updateFileCache.bind(this);\n    this.api = new ApiService();\n  }\n\n  private updateFileCache(filesCache: Dictionary<any>){\n    this.setState({filesCache})\n  }\n\n  public componentWillMount(): void {\n    window.scrollTo(0, 0);\n    this.loadBaseData();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { handleSubmit, valid, submitFailed, query, syncErrors, formValues, created, submitting } = this.props;\n    const { venues, channels, reasons, colors, loading, exist, filesCache, paymentMethods, requestSettings } = this.state;\n    const uploadingFiles = !!Object.values(filesCache).filter((files: any) => {\n      return !!files.filter((file: any) => file.status !== imageStatus.complete).length;\n    }).length;\n    return (\n      <React.Fragment>\n        <div className='container-fluid' style={{ position: 'relative', minHeight: '100vh', padding: '0 0 150px 0' }}>\n          <form onSubmit={handleSubmit}>\n            <div className='row' style={{ padding: '0 20px' }}>\n              <div className='col-md-12'>\n                <div className='row'>\n                  <div className='col-md-12'>\n                    <h3>Crear solicitud</h3>\n                  </div>\n                  <div className='col-md-12'>\n                    <div className='box'>\n                      <div className='box-header with-border'>\n                        <h3 className='box-title'>Información de venta</h3>\n                      </div>\n                      <div className='box-body create-request' style={{ paddingBottom: '0' }}>\n                        <div className='row'>\n                          <div className='col-md-12'>\n                            <table className='table-sm' style={{ width: '100%' }}>\n                              <tbody>\n                              <tr>\n                                <td className={'middle'} style={{ width: '30%' }}>\n                                  <Field\n                                    name='sellerText'\n                                    label='Vendedor *'\n                                    type='text'\n                                    props={{\n                                      readOnly: true\n                                    }}\n                                    component={InputField}\n                                    validate={[inputStringRequired]}\n                                  />\n                                </td>\n                                <td className={'middle'} style={{ width: '25%', maxWidth: '25%' }}>\n                                  <Field\n                                    name='venue'\n                                    label='Sucursal *'\n                                    // labelOff={true}\n                                    component={BootstrapSelectField}\n                                    validate={[inputStringRequired]}\n                                    props={{\n                                      disabled: true,\n                                      noneSelectedText: 'Seleccione...',\n                                      displayItems: 2,\n                                      selectedText: 'sucursal seleccionadas.',\n                                      autoClouse: true,\n                                      sm: true,\n                                      allOption: false,\n                                      search: true,\n                                      options: [\n                                        ...venues.map((venue) => ({\n                                          value: venue._id,\n                                          text: venue.name\n                                        }))\n                                      ],\n                                      onClick: (value: string) => {\n                                        if(formValues.venue === value){\n                                          this.props.autofill('venue', \"\");\n                                        } else{\n                                          this.props.autofill('venue', value);\n                                        }\n                                      }\n                                    }}\n                                  >\n                                  </Field>\n                                </td>\n                                <td className={'middle'} style={{ width: '25%', maxWidth: '25%' }}>\n                                  <Field\n                                    name='channel'\n                                    label='Canal'\n                                    component={BootstrapSelectField}\n                                    validate={[inputStringRequired]}\n                                    props={{\n                                      disabled: true,\n                                      noneSelectedText: 'Seleccione...',\n                                      displayItems: 2,\n                                      selectedText: 'canales seleccionadas.',\n                                      autoClouse: true,\n                                      sm: true,\n                                      allOption: false,\n                                      search: true,\n                                      options: [\n                                        ...channels.map((channel) => ({\n                                          value: channel._id,\n                                          text: channel.name\n                                        }))\n                                      ],\n                                      onClick: (value: string) => {\n                                        if (formValues.channel === value) {\n                                          this.props.autofill('channel', '');\n                                        } else {\n                                          this.props.autofill('channel', value);\n                                        }\n                                      }\n                                    }}\n                                  >\n                                  </Field>\n                                </td>\n                                <td className={'middle'} style={{ width: '20%' }}>\n                                  <Field\n                                    name='conectaID'\n                                    // labelOff={true}\n                                    label='ID Cotización Conecta *'\n                                    type='text'\n                                    props={{\n                                      readOnly: true\n                                    }}\n                                    component={InputField}\n                                    // validate={[inputStringRequired]}\n                                  />\n                                </td>\n                              </tr>\n                              </tbody>\n                            </table>\n                          </div>\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n                  <div className='col-md-12'>\n                    <div className='box'>\n                      <div className='box-header with-border'>\n                        <h3 className='box-title'>Información del cliente</h3>\n                      </div>\n                      <div className='box-body create-request' style={{ paddingBottom: '0' }}>\n                        <table className='table-xs' style={{ width: '100%' }}>\n                          <tbody>\n                          <tr>\n                            <td className={'middle'} style={{ width: '200px' }}>\n                              <Field\n                                name='customerInformation.rut'\n                                label='RUT *'\n                                type='text'\n                                props={{\n                                  readOnly: query.hasOwnProperty('5bf2de35caf8ef7096105c22')\n                                }}\n                                component={InputField}\n                                validate={[inputStringRequired]}\n                              />\n                            </td>\n                            <td className={'middle'}>\n                              <Field\n                                name='customerInformation.name'\n                                label='Nombre Completo *'\n                                type='text'\n                                props={{\n                                  readOnly: query.hasOwnProperty('5bf2de35caf8ef7096105c21')\n                                }}\n                                component={InputField}\n                                validate={[inputStringRequired]}\n                              />\n                            </td>\n                            <td className={'middle'} style={{ width: '30%' }}>\n                              <Field\n                                name='customerInformation.email'\n                                label='Correo Electrónico *'\n                                type='text'\n                                props={{\n                                  readOnly: query.hasOwnProperty('60b9232164adc90013a79b45')\n                                }}\n                                component={InputField}\n                                validate={[inputStringRequired]}\n                              />\n                            </td>\n                          </tr>\n                          </tbody>\n                        </table>\n                      </div>\n                    </div>\n                  </div>\n                  <div className='col-md-12'>\n                    <div className='box'>\n                      <div className='box-header with-border'>\n                        <h3 className='box-title'>Datos del anticipo o la orden de compra</h3>\n                      </div>\n                      <div className='box-body create-request' style={{ paddingBottom: '0' }}>\n                        <div className='row'>\n                          <div className='col-md-12'>\n                            <table className='table-xs' style={{ width: '100%' }}>\n                          <tbody>\n                          <tr>\n                            <td className={'middle form-group-no-margin'} style={{ width: '35%' }}>\n                              <Field\n                                name='advancePaymentInformation.method'\n                                label='Método de Pago *'\n                                component={BootstrapSelectField}\n                                validate={[inputStringRequired]}\n                                props={{\n                                  noneSelectedText: 'Seleccione...',\n                                  displayItems: 2,\n                                  selectedText: 'sucursal seleccionadas.',\n                                  autoClouse: true,\n                                  sm: true,\n                                  allOption: false,\n                                  search: true,\n                                  options: [\n                                    ...paymentMethods.map((paymentMethod) => ({\n                                      value: paymentMethod._id,\n                                      text: paymentMethod.name\n                                    }))\n                                  ],\n                                  onClick: (value: string) => {\n                                    if (formValues.advancePaymentInformation.method === value) {\n                                      this.props.autofill('advancePaymentInformation.method', '');\n                                    } else {\n                                      this.props.autofill('advancePaymentInformation.method', value);\n                                    }\n                                  }\n                                }}\n                              >\n                              </Field>\n                            </td>\n                            <td className={'middle form-group-no-margin'} style={{ width: '35%' }}>\n                              <Field\n                                name='advancePaymentInformation.number'\n                                label='Nº de Ticket u Orden de Compra *'\n                                type='text'\n                                component={InputField}\n                                validate={[inputStringRequired]}\n                              />\n                            </td>\n                          </tr>\n                          <tr>\n                            <td className={'middle form-group-no-margin'}>\n                              <div\n                                className={`form-group ${submitFailed && !valid && !formValues?.advancePaymentInformation?.files?.length ? 'has-error' : ''}`}>\n                                <label className='control-label text-ellipsis'>Comprobante de Ticket u OC *</label>\n                                <Field\n                                  name={`advancePaymentInformation.files`}\n                                  type='hidden'\n                                  labelOff={true}\n                                  component={InputHiddenField}\n                                  validate={[inputStringRequired]}\n                                />\n                                <MultiUploadFiles\n                                  url={'/api/v1/requests/upload-file/'}\n                                  className={submitFailed && !valid && !formValues?.advancePaymentInformation?.files?.length ? 'multi-upload-errors' : ''}\n                                  onChange={(files) => {\n                                    const lastFile = files.length ? [files[files.length - 1]] : [];\n                                    this.updateFileCache({\n                                      ...filesCache,\n                                      ['payment']: lastFile\n                                    });\n                                    this.props.autofill('advancePaymentInformation.files', lastFile);\n                                  }}\n                                  files={filesCache.hasOwnProperty('payment') ? filesCache['payment'] : []}\n                                />\n                                <ShowIf condition={submitFailed && !valid && !formValues?.advancePaymentInformation?.files?.length}>\n                                  <span className='help-block text-red'>Este campo es requerido</span>\n                                </ShowIf>\n                              </div>\n                            </td>\n                            <td className={'middle form-group-no-margin'}>\n                              <div\n                                className={`form-group ${submitFailed && !valid && !formValues?.advancePaymentInformation?.files?.length ? 'has-error' : ''}`}>\n                                <label className='control-label text-ellipsis'>Subir Carta de Reserva *</label>\n                                <Field\n                                  name={`advancePaymentInformation.letters`}\n                                  type='hidden'\n                                  labelOff={true}\n                                  component={InputHiddenField}\n                                  validate={[inputStringRequired]}\n                                />\n                                <MultiUploadFiles\n                                  url={'/api/v1/requests/upload-file/'}\n                                  className={submitFailed && !valid && !formValues?.advancePaymentInformation?.letters?.length ? 'multi-upload-errors' : ''}\n                                  onChange={(files) => {\n                                    const lastFile = files.length ? [files[files.length - 1]] : [];\n                                    this.updateFileCache({\n                                      ...filesCache,\n                                      ['letter']: lastFile\n                                    });\n                                    this.props.autofill('advancePaymentInformation.letters', lastFile);\n                                  }}\n                                  files={filesCache.hasOwnProperty('letter') ? filesCache['letter'] : []}\n                                />\n                                <ShowIf condition={submitFailed && !valid && !formValues?.advancePaymentInformation?.letters?.length}>\n                                  <span className='help-block text-red'>Este campo es requerido</span>\n                                </ShowIf>\n                              </div>\n                            </td>\n                          </tr>\n                          </tbody>\n                            </table>\n                          </div>\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n                  <div className='col-md-12'>\n                    <div className='box'>\n                      <div className='box-header with-border'>\n                        <h3 className='box-title'>Datos de entrega</h3>\n                      </div>\n                      <div className='box-body create-request' style={{ paddingBottom: '0' }}>\n                        <div className='row'>\n                          <div className='col-md-12'>\n                            <table className='table-xs' style={{ width: '100%' }}>\n                              <tbody>\n                              <tr>\n                                <td className={'middle'} style={{ width: '25%' }}>\n                                  <Field\n                                    name='deliveryVenue'\n                                    label='Sucursal'\n                                    // labelOff={true}\n                                    component={BootstrapSelectField}\n                                    // validate={[inputStringRequired]}\n                                    props={{\n                                      noneSelectedText: 'Seleccione...',\n                                      displayItems: 2,\n                                      selectedText: 'transportistas seleccionadas.',\n                                      autoClouse: true,\n                                      sm: true,\n                                      allOption: false,\n                                      search: true,\n                                      options: [\n                                        ...venues.map((venue) => ({\n                                          value: venue._id,\n                                          text: venue.name\n                                        }))\n                                      ],\n                                      onClick: (value: string) => {\n                                        if(formValues.deliveryVenue === value){\n                                          this.props.autofill('deliveryVenue', null);\n                                        } else{\n                                          this.props.autofill('deliveryVenue', value);\n                                        }\n                                      }\n                                    }}\n                                  >\n                                  </Field>\n                                </td>\n                                <td className={'middle'} style={{ width: '50%' }}>\n                                  <Field\n                                    name='deliveryAddress'\n                                    // labelOff={true}\n                                    label='Dirección'\n                                    type='text'\n                                    component={InputField}\n                                    // validate={[inputStringRequired]}\n                                  />\n                                </td>\n                                <td className={'middle'} style={{ width: '25%' }}>\n                                  <Field\n                                    name='deliveryDate'\n                                    // labelOff={true}\n                                    label='Fecha'\n                                    type='text'\n                                    component={DateRangePickerField}\n                                    props={{\n                                      className: 'input-sm',\n                                      format: 'DD-MM-YYYY',\n                                      startDate: moment().add(1, 'days').startOf('day'),\n                                      onChange: (e: any) => {\n                                        this.props.autofill('deliveryDate', e?.toDate() ?? '');\n                                      }\n                                    }}\n                                  />\n                                </td>\n                              </tr>\n                              </tbody>\n                            </table>\n                          </div>\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n                  <div className='col-md-12'>\n                    <div className='box'>\n                      <div className='box-header with-border'>\n                        <h3 className={submitFailed && !valid && !formValues.cars.length ? 'text-red box-title' : 'box-title'}>Unidades</h3>\n                      </div>\n                      <div className='box-body create-request no-padding'>\n                        <div className='row'>\n                          <FieldArray<IRenderItemProps>\n                            name='cars'\n                            component={RequestCarRender}\n                            props={{\n                              reasons,\n                              colors,\n                              requestSettings,\n                              updateFileCache: this.updateFileCache,\n                              filesCache,\n                              loading,\n                              syncErrors,\n                              submitFailed,\n                              formValues,\n                              valid,\n                              query,\n                              autofill: this.props.autofill\n                            }}\n                          />\n                          <div className='col-md-12 text-right' style={{ padding: ' 30px' }}>\n                            <button\n                              className='btn btn-success btn-sm'\n                              type='button'\n                              onClick={this.addCarToForm}\n                            >\n                              <i className='fa fa-plus' /> Agregar vehículo\n                            </button>\n                          </div>\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n                  {/*{\n                    submitFailed && !valid &&\n                    <div className='col-md-12'>\n                      <div\n                        className='alert alert-danger m-t-20'\n                      >\n                        Todos los campos con * son obligatorios\n                      </div>\n                    </div>\n                  }*/}\n                  <div className='col-md-12 text-right'>\n                    <ShowIf condition={uploadingFiles}>\n                      <p className={\"text-muted text-left\"}>Espere a que se terminen de subir las imágenes para crear la solicitud.</p>\n                    </ShowIf>\n                    <button\n                      type={'button'}\n                      disabled={submitting || uploadingFiles}\n                      onClick={submitting || !valid || uploadingFiles ? () => this.props.dispatch(submit('requestForm')) : () => {\n                        swal({\n                          title: '¿Estás seguro?',\n                          text: `Vas a crear esta solicitud.`,\n                          icon: 'warning',\n                          dangerMode: true,\n                          buttons: {\n                            cancel: 'Cancelar' as any,\n                            confirm: {\n                              text: 'Sí'\n                            }\n                          }\n                        }).then((willCReate: any) => {\n                          if (willCReate) {\n                            this.props.dispatch(submit('requestForm'));\n                          }\n                        });\n                      }}\n                      className='btn btn-primary btn-sm'\n                    >\n                      {submitting && <i className='fa fa-fw fa-spinner fa-spin' />} Crear solicitud\n                    </button>\n                  </div>\n                  <Field\n                    name={`cars_error`}\n                    type='hidden'\n                    labelOff={true}\n                    component={InputHiddenField}\n                  />\n                </div>\n              </div>\n            </div>\n          </form>\n          <div className='text-muted text-center' style={{ position: 'absolute', bottom: '0', height: '30px', width: '100%' }}>\n            Copyright (c) {moment().format('YYYY')} <a href='http://www.osacontrol.com' target='_blank'>OSA SPA</a>. All rights reserved.\n          </div>\n        </div>\n        <ShowIf condition={loading}>\n          {/*<ShowIf condition={true}>*/}\n          <div style={{\n            position: 'absolute',\n            top: '0',\n            height: '100%',\n            width: '100vw',\n            backgroundColor: 'rgba(246,246,246,0.4)',\n            display: 'flex',\n            flexDirection: 'column',\n            alignItems: 'center',\n            paddingTop: '400px'\n            // justifyContent: 'center'\n          }}>\n            <p><i className='fa fa-3x fa-circle-o-notch text-primary fa-spin' /></p>\n            {/*<p style={{ padding: '20px', fontSize: '1.7rem'}}><strong>Cargando datos</strong></p>*/}\n          </div>\n        </ShowIf>\n        <ShowIf condition={created}>\n          <div style={{\n            position: 'absolute',\n            top: '0',\n            height: '100%',\n            width: '100vw',\n            backgroundColor: 'rgba(246,246,246,0.4)',\n            display: 'flex',\n            flexDirection: 'column',\n            alignItems: 'center',\n            paddingTop: '400px'\n            // justifyContent: 'center'\n          }}>\n          </div>\n        </ShowIf>\n        <ShowIf condition={exist}>\n          <div style={{\n            position: 'absolute',\n            top: '0',\n            height: '100%',\n            width: '100vw',\n            backgroundColor: 'rgba(246,246,246,0.4)',\n            display: 'flex',\n            flexDirection: 'column',\n            alignItems: 'center',\n            paddingTop: '400px'\n            // justifyContent: 'center'\n          }}>\n          </div>\n        </ShowIf>\n      </React.Fragment>\n    );\n  }\n\n  private addCarToForm() {\n    const { query } = this.props;\n    const { material } = query;\n    const { reasons } = this.state;\n    let data: any = {\n      key: uuid.v4(),\n      reason: '5fe0930aa9683b0f8a6e0e42',\n      brand: query.brand,\n      denomination: query.denomination,\n      material: material.substr(material.length > 6 ? material.length - 6 : 0),\n      answersbkp: [],\n      answers: [],\n      files: []\n    };\n    const salfaReason = reasons\n      .find((reason) => reason._id === '5fe0930aa9683b0f8a6e0e42');\n    if (salfaReason) {\n      salfaReason.questions\n        .forEach((question) => {\n          data.answersbkp.push(query[question._id]);\n          if (query[question._id]) {\n            data.answers.push({\n              questionId: question._id,\n              question: question.name,\n              answer: query[question._id]\n            });\n          }\n        });\n    }\n    this.props.dispatch(arrayPush('requestForm', 'cars', data));\n  }\n\n  private loadBaseData() {\n    const {  query } = this.props;\n    const conectaID = query['6154722a94bba10012230aae'] || query['conectaID'];\n    this.setState({ loading: true });\n    Axios\n      .all([\n        this.api.getCompanyVenues(),\n        this.api.getReasons({ page: 1, pageSize: 200 }),\n        this.api.getColors({ page: 1, pageSize: 200 }),\n        this.api.getSalesChannel({ page: 1, pageSize: 200 }),\n        this.api.getTeamSettings(),\n        this.api.getOperationTypes({ page: 1, pageSize: 200 }),\n        this.api.getPaymentMethods({ page: 1, pageSize: 200 }),\n        this.api.validateContectaID(conectaID)\n      ])\n      .then(Axios.spread((venues, reasons, colors, channels, teamSettings, operationTypes, paymentMethods, validateContecta) => {\n        if(validateContecta.data?.error){\n          this.setState({ exist: true });\n          swal!('Solicitud ya creada para esta cotización', `ID de cotización conecta ${conectaID} ya se encuentra asociado en la solicitud ${validateContecta.data.number}.`, 'warning', {\n            button: false,\n            closeOnClickOutside: false,\n            closeOnEsc: false\n          });\n        }\n        this.props.autofill('channel', teamSettings.data?.user?.defaultChannel);\n        this.setState({\n          venues: venues.data.results,\n          colors: colors.data.results,\n          reasons: reasons.data.results.map((reason: any) => {\n            // disable questions and extra files\n            reason.questions = [];\n            reason.file = {\n              '_id': '62521d050cf69800277f2686',\n              'active': false,\n              'required': false\n            };\n            return reason;\n          }),\n          channels: channels.data.results,\n          paymentMethods: paymentMethods.data.results,\n          requestSettings: teamSettings.data.request,\n          operationTypes: operationTypes.data.results,\n          loading: false\n        });\n        this.addCarToForm();\n      }))\n      .catch((err: AxiosError): void => {\n        this.api.errorHandler(err);\n      });\n  }\n}\n\nconst validate = (values: any, props: DecoratedFormProps<FormData, any, string>): FormErrors<FormData, string> => {\n  const errors: any = {};\n  if (values.deliveryAddress?.length && !values.deliveryVenue?.length) {\n    errors.deliveryVenue = 'Este campo es requerido';\n  }\n  if (!values.cars?.length) {\n    errors.cars_error = 'Este campo es requerido';\n  }\n  return errors;\n};\n\nconst RequestForm = reduxForm<any, any, any>({\n  form: 'requestForm',\n  validate\n})(Form);\n\nconst mapStateToProps = (state: any) => {\n  return {\n    formValues: getFormValues('requestForm')(state),\n    syncErrors: getFormSyncErrors('requestForm')(state),\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, { dispatch: any }, IPropsType | any>(mapStateToProps, mapDispatchToProps)(RequestForm);\n","import * as React from 'react';\nimport { Field, getFormMeta, getFormSyncErrors, WrappedFieldArrayProps } from 'redux-form';\nimport { connect } from 'react-redux';\nimport InputField from '../../../Utils/forms/InputField';\nimport { inputStringRequired } from '../../../Utils/forms/validations';\nimport ShowIf from '../../../Utils/ShowIf';\nimport MultiUploadFiles, { imageStatus } from '../../../Utils/MultiUploadFiles';\nimport { IReason } from '../../../../../../../../src/request/interfaces/reason.interface';\nimport BootstrapSelectField from '../../../Utils/forms/BootstrapSelectField';\nimport InputHiddenField from '../../../Utils/forms/InputHiddenField';\n\n\nexport interface IRenderItemProps {\n}\n\ninterface IPropsType extends WrappedFieldArrayProps<{}>, IRenderItemProps {\n  reasons: any[],\n  colors: any[];\n  syncErrors: any;\n  formValues: any;\n  updateFileCache: any;\n  filesCache: Dictionary<any>\n  query: any;\n  requestSettings: any;\n  submitFailed: any;\n  valid: any;\n  loading: boolean;\n  autofill(field: string, value: any): void;\n}\n\n\ninterface IStateType {\n  error: Error | null;\n  openTabs: string[];\n  reasonSelectedState: Dictionary<string>;\n}\n\nclass RequestCarRender extends React.Component<IPropsType, IStateType> {\n\n  readonly state: IStateType = {\n    error: null,\n    openTabs: [],\n    reasonSelectedState: {}\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.toogleTab = this.toogleTab.bind(this);\n  }\n\n\n  public render(): React.ReactElement<IPropsType> {\n    const { fields, submitFailed, valid, reasons, colors, syncErrors, query, formValues, loading, filesCache, requestSettings } = this.props;\n    const { openTabs, reasonSelectedState } = this.state;\n    return (\n      <React.Fragment>\n        {\n          fields.length === 0 ?\n            <ShowIf condition={!loading}>\n              <div className='col-md-12'>\n                <p\n                  className={submitFailed && !valid && !formValues.cars.length ? 'text-red text-center' : ' text-muted text-center'}\n                  style={{ padding: '60px 0px  30px 0px', margin: '0' }}\n                >\n                  {submitFailed && !valid && !formValues.cars.length ? 'Debes agregar al menos un unidad.' : 'No se han agregado unidades aún.'}\n                </p>\n              </div>\n            </ShowIf> :\n            <div className='col-md-12'>\n              {\n                fields.map((item, index) => {\n                  const value: any = fields.get(index) as any;\n                  const openTab = openTabs.includes(value.key);\n                  const reasonSelected: IReason | undefined = reasons.find((reason: IReason) => reason._id === reasonSelectedState[index] || reason._id === value.reason);\n                  let uploadingFiles = 0;\n                  let archivos = 0;\n                  if (filesCache.hasOwnProperty(index)) {\n                    uploadingFiles = filesCache[index].filter((file: any) => file.status !== imageStatus.complete).length;\n                    archivos = filesCache[index].length;\n                  }\n                  let hasErrors = 0;\n                  let hasFileErrors = 0;\n                  if (syncErrors?.cars?.length > index) {\n                    hasErrors = syncErrors?.cars[index]?.answersbkp?.filter((msg: any) => msg).length ?? 0;\n                  }\n                  if (reasonSelected && reasonSelected.file.active && archivos === 0) {\n                    hasErrors++;\n                    hasFileErrors++;\n                  }\n                  return (\n                    <div key={value.key}>\n                      <table className='table-sm' style={{ width: '100%', backgroundColor: '#f6f6f6', borderTop: '1px solid #e5e3e3' }}>\n                        <tbody>\n                        <tr>\n                          <td className={`middle-center`}>\n                            #<strong>{this.padNumber(index + 1)}</strong>\n                          </td>\n                          <td className={`middle form-group-no-margin`}>\n                            <Field\n                              name={`${item}.brand`}\n                              label='Marca *'\n                              type='text'\n                              props={{\n                                readOnly: true\n                              }}\n                              component={InputField}\n                              validate={[inputStringRequired]}\n                            />\n                          </td>\n                          <td className={`middle form-group-no-margin`}>\n                            <Field\n                              name={`${item}.denomination`}\n                              label='Modelo *'\n                              type='text'\n                              props={{\n                                readOnly: true\n                              }}\n                              component={InputField}\n                              validate={[inputStringRequired]}\n                            />\n                          </td>\n                          <td className={`middle form-group-no-margin`}>\n                            <Field\n                              name={`${item}.material`}\n                              label='Material *'\n                              type='text'\n                              props={{\n                                readOnly: true\n                              }}\n                              component={InputField}\n                              validate={[inputStringRequired]}\n                            />\n                          </td>\n                          <td className={`middle form-group-no-margin`}>\n                            {\n                              colors.length ?\n                                <Field\n                                  name={`${item}.color`}\n                                  label='Color *'\n                                  component={BootstrapSelectField}\n                                  validate={[inputStringRequired]}\n                                  props={{\n                                    noneSelectedText: 'Seleccione...',\n                                    displayItems: 2,\n                                    selectedText: 'sucursal seleccionadas.',\n                                    autoClouse: true,\n                                    sm: true,\n                                    allOption: false,\n                                    search: true,\n                                    options: [\n                                      ...colors.map((color) => ({\n                                        value: color.name,\n                                        text: color.name\n                                      }))\n                                    ],\n                                    onClick: (value: string) => {\n                                      this.props.autofill(`${item}.color`, value);\n                                    }\n                                  }}\n                                >\n                                </Field>\n                                :\n                                <Field\n                                  name={`${item}.color`}\n                                  label='Color *'\n                                  type='text'\n                                  component={InputField}\n                                  validate={[inputStringRequired]}\n                                />\n                            }\n                          </td>\n                          <ShowIf condition={requestSettings.secondColorOption}>\n                            <td className={`middle form-group-no-margin`}>\n                              {\n                                colors.length ?\n                                  <Field\n                                    name={`${item}.secondColorOption`}\n                                    label='Color 2'\n                                    component={BootstrapSelectField}\n                                    // validate={[inputStringRequired]}\n                                    props={{\n                                      noneSelectedText: 'Seleccione...',\n                                      displayItems: 2,\n                                      selectedText: 'sucursal seleccionadas.',\n                                      autoClouse: true,\n                                      sm: true,\n                                      allOption: false,\n                                      search: true,\n                                      options: [\n                                        ...colors.map((color) => ({\n                                          value: color.name,\n                                          text: color.name\n                                        }))\n                                      ],\n                                      onClick: (value: string) => {\n                                        this.props.autofill(`${item}.secondColorOption`, value);\n                                      }\n                                    }}\n                                  >\n                                  </Field>\n                                  :\n                                  <Field\n                                    name={`${item}.secondColorOption`}\n                                    label='Color *'\n                                    type='text'\n                                    component={InputField}\n                                    // validate={[inputStringRequired]}\n                                  />\n                              }\n                            </td>\n                          </ShowIf>\n                          <ShowIf condition={requestSettings.thirdColorOption}>\n                            <td className={`middle form-group-no-margin`}>\n                              {\n                                colors.length ?\n                                  <Field\n                                    name={`${item}.thirdColorOption`}\n                                    label='Color 3'\n                                    component={BootstrapSelectField}\n                                    // validate={[inputStringRequired]}\n                                    props={{\n                                      noneSelectedText: 'Seleccione...',\n                                      displayItems: 2,\n                                      selectedText: 'sucursal seleccionadas.',\n                                      autoClouse: true,\n                                      sm: true,\n                                      allOption: false,\n                                      search: true,\n                                      options: [\n                                        ...colors.map((color) => ({\n                                          value: color.name,\n                                          text: color.name\n                                        }))\n                                      ],\n                                      onClick: (value: string) => {\n                                        this.props.autofill(`${item}.thirdColorOption`, value);\n                                      }\n                                    }}\n                                  >\n                                  </Field>\n                                  :\n                                  <Field\n                                    name={`${item}.thirdColorOption`}\n                                    label='Color *'\n                                    type='text'\n                                    component={InputField}\n                                    // validate={[inputStringRequired]}\n                                  />\n                              }\n                            </td>\n                          </ShowIf>\n                          <td className={`middle form-group-no-margin`}>\n                            <Field\n                              name={`${item}.reason`}\n                              label='Motivo *'\n                              // labelOff={true}\n                              component={BootstrapSelectField}\n                              validate={[inputStringRequired]}\n                              props={{\n                                noneSelectedText: 'Seleccione...',\n                                displayItems: 2,\n                                selectedText: 'sucursal seleccionadas.',\n                                autoClouse: true,\n                                sm: true,\n                                disabled: true,\n                                allOption: false,\n                                search: true,\n                                options: [\n                                  ...reasons.map((reason) => ({\n                                    value: reason._id,\n                                    text: reason.name\n                                  }))\n                                ],\n                                onClick: (value: string) => {\n                                  this.setState({\n                                    reasonSelectedState: {\n                                      ...this.state.reasonSelectedState,\n                                      [index]: value\n                                    }\n                                  });\n                                  this.props.autofill(`${item}.reason`, value);\n                                }\n                              }}\n                            >\n                            </Field>\n                          </td>\n                          <td className={`middle-center`} style={{ width: '50px', paddingTop: '19px' }}>\n                            <button\n                              type='button'\n                              className='btn btn-sm btn-danger'\n                              onClick={() => {\n                                fields.remove(index);\n                              }}\n                            >\n                              <i className='fa fa-trash' />\n                            </button>\n                          </td>\n                          <ShowIf condition={!!(reasonSelected && reasonSelected.questions.length)}>\n                            <td\n                              className={`middle-center pointer`}\n                              style={{ width: '40px', padding: '10px 20px 7px 3px' }}\n                              onClick={() => this.toogleTab(value.key)}\n                            >\n                              {\n                                openTab ? <i className='fa fa-chevron-up' /> : <i className='fa fa-chevron-down' />\n                              }\n                            </td>\n                          </ShowIf>\n                        </tr>\n                        </tbody>\n                      </table>\n                      <ShowIf condition={!!hasErrors}>\n                        <div style={{ padding: '5px 10px ' }} className={submitFailed && !valid?'text-sm bg-red text-primary':'text-sm bg-warning text-warning'}>\n                          <i className='fa fa-fw fa-info-circle'/> Quedan {hasErrors} datos adicionales obligatorios sin completar.\n                        </div>\n                      </ShowIf>\n                      <div\n                        className='form-horizontal form-group-no-margin table-sm'\n                        style={{ backgroundColor: 'rgba(251, 251, 251, 1)', padding: '30px 20px', display: openTab ? '' : 'none' }}>\n                        <ShowIf condition={!!(reasonSelected && reasonSelected.questions.length)}>\n                          {\n                            reasonSelected?.questions.map((question, index) => {\n                              return (\n                                <div className='form-group' key={question._id}>\n                                  <label\n                                    htmlFor='color'\n                                    className='col-sm-3 col-lg-2 control-label label-left text-ellipsis'\n                                  >\n                                    {question.name} {question.required ? '*' : ''}\n                                  </label>\n                                  <div className='col-sm-8 col-lg-8 form-group-no-margin'>\n                                    <Field\n                                      name={`${item}.answersbkp[${index}]`}\n                                      type='text'\n                                      sm\n                                      props={{\n                                        onChange: (e: any) => {\n                                          this.props.autofill(`${item}.answersbkp[${index}]`, e.target.value);\n                                          this.props.autofill(`${item}.answers[${index}]`, {\n                                            questionId: question._id,\n                                            answer: e.target.value\n                                          });\n                                        },\n                                        readOnly: query.hasOwnProperty(question._id)\n                                      }}\n                                      labelOff={true}\n                                      component={InputField}\n                                      validate={question.required ? [inputStringRequired] : []}\n                                    />\n                                  </div>\n                                  <div className='col-md-1 col-lg-2' />\n                                </div>\n                              );\n                            })\n                          }\n                        </ShowIf>\n                        <ShowIf condition={!!(reasonSelected && reasonSelected.file.active)}>\n                          <div className='form-group'>\n                            <label className='col-sm-3 col-lg-2 control-label label-left'>Archivos *</label>\n                            <div className={`col-sm-8 col-lg-8`}>\n                              <Field\n                                name={`${item}.files`}\n                                type='hidden'\n                                labelOff={true}\n                                component={InputHiddenField}\n                                validate={reasonSelected?.file?.required ? [inputStringRequired] : []}\n                              />\n                              <MultiUploadFiles\n                                url={'/api/v1/requests/upload-file/'}\n                                className={submitFailed && !valid && !!hasFileErrors ? 'multi-upload-errors' : ''}\n                                onChange={(filesStorage) => {\n                                  // console.log('filesStorage.onChange', filesStorage)\n                                  this.props.updateFileCache({\n                                    ...filesCache,\n                                    [index]: filesStorage\n                                  });\n                                  // this.setState({\n                                  //   files: {\n                                  //     ...this.state.files,\n                                  //     [index]: filesStorage\n                                  //   }\n                                  // });\n                                  this.props.autofill(`${item}.files`, filesStorage);\n                                }}\n                                files={filesCache[index] ?? []}\n                              />\n                              <ShowIf condition={submitFailed && !valid && !!hasFileErrors}>\n                                <span className=\"help-block text-red\">Este campo es requerido</span>\n                              </ShowIf>\n                            </div>\n                            <div className='col-md-1 col-lg-2' />\n                          </div>\n                        </ShowIf>\n                      </div>\n                      <ShowIf condition={!!uploadingFiles}>\n                        <div style={{ padding: '5px 10px ' }} className='text-sm bg-primary text-primary '>\n                          <i className='fa fa-fw fa-spinner fa-spin' /> Subiendo {uploadingFiles} archivos de {archivos}\n                        </div>\n                      </ShowIf>\n                      {/*<ShowIf condition={!!hasErrors && !openTab}>*/}\n                    </div>\n                  );\n                })\n              }\n            </div>\n        }\n      </React.Fragment>\n    );\n  }\n\n  private toogleTab(key: string) {\n    const { openTabs } = this.state;\n    if (openTabs.includes(key)) {\n      this.setState({\n        openTabs: [...openTabs.filter(tab => tab !== key)]\n      });\n    } else {\n      this.setState({\n        openTabs: [...openTabs, key]\n      });\n    }\n  }\n\n  private padNumber(n: number): string {\n    const s = '000' + n;\n    return s.substr(s.length - 3);\n  }\n}\n\nconst mapStateToProps = (state: any) => {\n  return {\n    // formValues: getFormValues('requestForm')(state),\n    syncErrors: getFormSyncErrors('requestForm')(state),\n    meta: getFormMeta('requestForm')(state)\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\n\nexport default connect<{}, {}, IRenderItemProps>(mapStateToProps, mapDispatchToProps)(RequestCarRender);\n","import * as moment from 'moment-timezone';\nimport * as React from 'react';\nimport { CSSProperties, InputHTMLAttributes, RefObject } from 'react';\n\ninterface IPropsType {\n  onChange?: (e: moment.Moment | null) => void;\n  input: InputHTMLAttributes<any>\n  label: string;\n  labelOff?:boolean;\n  type: string\n  help: string\n  placeholder: string;\n  meta: {\n    touched: boolean;\n    error: string;\n    warning: string;\n  }\n  className?: string;\n  format?: string;\n  style?: CSSProperties;\n  value?: any;\n  startDate?: any\n  todayHighlight?: boolean\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass DateRangePickerField extends React.Component<IPropsType, IStateType> {\n\n  readonly input: RefObject<HTMLInputElement>;\n  readonly inputGroup: RefObject<HTMLInputElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.input = React.createRef();\n    this.inputGroup = React.createRef();\n    this.clickCalendar = this.clickCalendar.bind(this);\n  }\n\n  public componentDidMount() {\n    const { format } = this.props;\n    $(this.input.current!).datepicker({\n      autoclose: true,\n      language: 'es',\n      todayHighlight: !!this.props.todayHighlight,\n      orientation: 'bottom auto',\n      clearBtn: true,\n      startDate: this.props.startDate,\n      format: {\n        toDisplay: (date) => {\n          return moment(date).utc().format(format ?? 'DD-MM-YY');\n        },\n        toValue: (date) => {\n          return moment(date, format ?? 'DD-MM-YY').utc().toDate();\n        }\n      }\n    });\n    $(this.input.current!).on('changeDate', () => {\n      if (typeof (this.props.onChange) === 'function') {\n        const date = moment(this.input.current!.value, format ?? 'DD-MM-YY', true);\n        if (date.isValid()) {\n          this.props.onChange(date);\n        } else {\n          this.props.onChange(null);\n        }\n      }\n    });\n  }\n\n  public componentWillUnmount() {\n    $(this.input.current!).datepicker('destroy');\n  }\n\n  private clickCalendar() {\n    $(this.input.current!).datepicker('show');\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      format, input,\n      label,\n      labelOff,\n      placeholder,\n      type,\n      help,\n      meta: { touched, error, warning }\n    } = this.props;\n    return (\n      <div className={`form-group ${touched && error ? 'has-error' : warning ? 'has-warning' : ''}`}>\n        {!labelOff ? <label className='control-label  text-ellipsis'>{label}</label> : null}\n        <div className='input-group'>\n          <input\n            ref={this.input}\n            type='text'\n            value={input.value?.toString().length ? moment(input.value as string).format(format ?? 'DD-MM-YY') : ''}\n            className={`form-control ${this.props.className ?? ''}`}\n            onClick={this.clickCalendar}\n            onChange={() => {\n            }}\n            style={{ ...this.props.style }}\n          />\n          <span className='input-group-addon pointer' onClick={this.clickCalendar}>\n          <i className='fa fa-calendar' />\n        </span>\n        </div>\n        {\n          touched &&\n          ((error && <span className='help-block'>{error}</span>) ||\n            (warning && <span className='help-block'>{warning}</span>)) || <span className='help-block'>&nbsp;</span>\n        }\n      </div>\n    );\n  }\n}\n\nexport default DateRangePickerField;\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport { FormAction, submit } from 'redux-form';\nimport { IColor } from '../../../../../../src/app/interfaces/color.interface';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport { ColorReduxActions, IColorState } from '../../actions/color.types';\nimport { createColorThunkAction, deleteColorThunkAction, getColorsThunkAction, updateColorThunkAction } from '../../actions/color.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { hasPermission } from '../../utils/common';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport Paginator from '../Utils/Paginator';\nimport ColorForm from './ColorsFormView';\nimport ModalView from '../Modal/ModalView';\nimport * as moment from 'moment';\nimport * as swal from 'sweetalert';\nimport { io } from \"socket.io-client\";\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<ColorReduxActions | FormAction>;\n  colors: IColorState;\n\n  getColorThunkAction(colorType: string, nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean): ColorReduxActions;\n\n  createColorThunkAction(color: IColor): ColorReduxActions;\n  updateColorThunkAction(color: IColor): ColorReduxActions;\n  deleteColorThunkAction(color: IColor): ColorReduxActions;\n\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass ColorListView extends TrackingBasePage<IPropsType, IStateType> {\n  private socket: Socket;\n\n  public title: string;\n  readonly state = {\n    error: null,\n    colorType: '',\n    exporing: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado Colores';\n    this.changePage = this.changePage.bind(this);\n    this.createColor = this.createColor.bind(this);\n    this.processCreateColor = this.processCreateColor.bind(this);\n    this.updateColor = this.updateColor.bind(this);\n    this.processUpdateColor = this.processUpdateColor.bind(this);\n    this.deleteColor = this.deleteColor.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const { pagination } = this.props.colors;\n    const { orderBy, orderType } = this.props.colors.options;\n    const { colorType } = this.state;\n    this.props.getColorThunkAction(colorType, pagination.page, orderBy, orderType);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: { token: (window.user as any).token }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `color-list-${window.user.team._id}` });\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update) {\n        const { pagination } = this.props.colors;\n        const { orderBy, orderType } = this.props.colors.options;\n        const { colorType } = this.state;\n        this.props.getColorThunkAction(colorType, pagination.page, orderBy, orderType, true);\n      }\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if (this.props.colors.pagination !== prevProps.colors.pagination) {\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.colors.source) {\n      this.props.colors.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, colors, pagination } = this.props.colors;\n    // const isDevelopment = process.env.NODE_ENV === 'development';\n    const isDevelopment = false;\n    const canCreate = hasPermission(window.user, 'addColor') || isDevelopment;\n    const canUpdate = hasPermission(window.user, 'changeColor') || isDevelopment;\n    const canDelete = hasPermission(window.user, 'deleteColor') || isDevelopment;\n    return (\n      <AppContainer title='' cMenu='10' cSubMenu='10.10' cAction='Colors'>\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\"><h3 className=\"box-title\">Colores <small>{pagination.count}</small></h3>\n              {\n                canCreate ?\n                  <div className=\"box-tools pull-right\">\n                    <button className=\"btn btn-sm btn-success\" onClick={this.createColor}><i className=\"fa fa-plus\" /> Agregar</button>\n                  </div>\n                  : null\n              }\n            </div>\n            <div className=\"box-body no-padding\">\n              <table className=\"table table-andes table-striped\">\n                <thead>\n                  <tr>\n                    <th style={{width: '60%'}} className=\"middle\">Nombre</th>\n                    <th style={{width: '20%'}} className=\"middle hidden-xs\">Modificado</th>\n                    {\n                      canUpdate ?\n                        <th style={{width: '1%'}} className=\"width-10\"/> : null\n                    }\n                    {\n                      canDelete ?\n                        <th style={{width: '1%'}} className=\"width-10\"/> : null\n                    }\n                  </tr>\n                </thead>\n                <tbody>\n                {\n                  !loading && !colors.length ?\n                    <tr>\n                      <td\n                        colSpan={2 + (canUpdate ? 1 : 0) + (canDelete ? 1 : 0)}\n                      >\n                        No se han creado colores\n                      </td>\n                    </tr>\n                    : null\n                }\n                {\n                  colors.map((color)=>{\n                    return (\n                      <tr\n                          key={color._id}\n                          id={`color-${color._id}`}\n                          className={'background-transition'}\n                        >\n                        <td className=\"middle\">{color.name}</td>\n                        <td className='middle hidden-xs'>{moment(color.updatedAt).format('LLL')}</td>\n                        {\n                          canUpdate ?\n                            <td\n                              className='middle text-blue pointer'\n                              onClick={() => this.updateColor(color)}\n                            >\n                              <i className='fa fa-pencil' />\n                            </td> : null\n                        }\n                        {\n                          canDelete ?\n                            <td\n                              className={'middle text-red pointer'}\n                              onClick={() => this.deleteColor(color)}\n                            ><i className='fa fa-minus-circle' /></td> : null\n                        }\n                      </tr>\n                    )\n                  })\n                }\n                </tbody>\n              </table>\n            </div>\n             {\n              pagination.pages > 1 &&\n                <div className=\"box-footer text-right\">\n                  <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                </div>\n            }\n            {\n              loading &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private createColor(): void {\n    this.props.loadDataAction(\n      'Agregar Color',\n      <ColorForm\n        onSubmit={this.processCreateColor}\n      />,\n      <React.Fragment>\n        <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cancelar</button>\n        <button\n          type='button' className='btn btn-sm btn-primary'\n          onClick={() => this.props.dispatch(submit('colorForm'))}\n        >\n          Grabar\n        </button>\n      </React.Fragment>\n    );\n  }\n\n  private processCreateColor(color: any){\n    this.props.createColorThunkAction(color);\n  }\n\n  private updateColor(color: any): void {\n    this.props.loadDataAction(\n      'Editar Color',\n      <ColorForm\n        initialValues={color}\n        onSubmit={this.processUpdateColor}\n      />,\n      <React.Fragment>\n        <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cancelar</button>\n        <button\n          type='button' className='btn btn-sm btn-primary'\n          onClick={() => this.props.dispatch(submit('colorForm'))}\n        >\n          Grabar\n        </button>\n      </React.Fragment>\n    );\n  }\n\n  private processUpdateColor(color: any): void {\n    this.props.updateColorThunkAction(color);\n  }\n\n  private deleteColor(color: any): void {\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el color ${color.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete: any) => {\n      if (willDelete) {\n        this.props.deleteColorThunkAction(color);\n      }\n    });\n    // this.props.updateColorThunkAction(color);\n  }\n\n\n  private changePage(page: number): void {\n    // change the page\n    const { orderBy, orderType } = this.props.colors.options;\n    const { colorType } = this.state;\n    this.props.getColorThunkAction(colorType, page, orderBy, orderType);\n  }\n}\n\nconst mapStateToProps = (state: { colors: IColorState }) => {\n  return {\n    colors: state.colors\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getColorThunkAction: (colorType: string, nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) => dispatch(getColorsThunkAction(colorType, nextPage, orderBy, orderType, hideLoading)),\n    createColorThunkAction: (color: IColor) => dispatch(createColorThunkAction(color)),\n    updateColorThunkAction: (color: IColor) => dispatch(updateColorThunkAction(color)),\n    deleteColorThunkAction: (color: IColor) => dispatch(deleteColorThunkAction(color)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{ colors: IColorState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(ColorListView);\n","import Axios, { AxiosError, AxiosResponse, CancelTokenSource } from 'axios';\nimport { Dispatch } from 'redux';\nimport { IColor } from '../../../../../src/app/interfaces/color.interface';\nimport ApiService from '../utils/axios';\nimport {\n  COLOR_IS_LOADING,\n  COLOR_CHANGE_ORDER,\n  COLOR_CANCEL,\n  COLOR_LOAD,\n  COLOR_CREATE,\n  COLOR_UDPATE,\n  COLOR_DELETE,\n  ICreateColor,\n  ICancelColor,\n  IIsLoadingColor,\n  ILoadColor,\n  IUpdateColor,\n  IDeleteColor,\n  IChangeOrderColor,\n  IColorState,\n  ColorReduxActions\n} from './color.types';\nimport { showModal, statusFooterButttonsModal } from '../utils/common';\nimport * as swal from 'sweetalert';\n\nexport function cancelColorAction(source: CancelTokenSource): ICancelColor {\n  return {\n    type: COLOR_CANCEL,\n    payload: {\n      source\n    }\n  };\n}\n\nexport function isLoadingColorAction(loading: boolean): IIsLoadingColor {\n  return {\n    type: COLOR_IS_LOADING,\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function loadColorAction(colors: IColor[], count: number, pages: number, page: number): ILoadColor {\n  return {\n    type: COLOR_LOAD,\n    payload: {\n      colors,\n      count,\n      pages,\n      page\n    }\n  };\n}\n\n\nexport function createColorAction(color: IColor): ICreateColor {\n  return {\n    type: COLOR_CREATE,\n    payload: {\n      color\n    }\n  };\n}\n\nexport function updateColorAction(color: IColor): IUpdateColor {\n  return {\n    type: COLOR_UDPATE,\n    payload: {\n      color\n    }\n  };\n}\n\n\nexport function deleteColorAction(color: IColor): IDeleteColor {\n  return {\n    type: COLOR_DELETE,\n    payload: {\n      color\n    }\n  };\n}\n\nexport function changeOrderColorAction(orderBy: string, orderType: string): IChangeOrderColor {\n  return {\n    type: COLOR_CHANGE_ORDER,\n    payload: {\n      orderBy,\n      orderType\n    }\n  };\n}\n\nexport function getColorsThunkAction(colorType: string, nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) {\n  return (dispatch: Dispatch<ColorReduxActions>, getState: () => { color: IColorState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(isLoadingColorAction(!hideLoading));\n    const page = nextPage ? nextPage : state.color.pagination.page;\n    dispatch(changeOrderColorAction(orderBy, orderType));\n    dispatch(cancelColorAction(api.getSource()));\n    Axios\n      .all([\n        api.getColors({ page })\n      ])\n      .then(Axios.spread((colors) => {\n        const { data } = colors;\n        dispatch(loadColorAction(data.results, data.count, data.pages, page));\n        dispatch(isLoadingColorAction(false));\n      }))\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingColorAction(false));\n        api.errorHandler(err);\n      });\n  };\n\n}\n\nexport function createColorThunkAction(color: IColor) {\n  return (dispatch: Dispatch<ColorReduxActions>) => {\n    const api: ApiService = new ApiService();\n    statusFooterButttonsModal(true);\n    api.createColor(color)\n      .then((response: AxiosResponse) => {\n        const { data } = response;\n        dispatch(createColorAction(data.result));\n         swal(response.data.message, {\n          icon: 'success'\n        });\n        statusFooterButttonsModal(false);\n        showModal(false);\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function updateColorThunkAction(color: IColor) {\n  return (dispatch: Dispatch<ColorReduxActions>) => {\n    const api: ApiService = new ApiService();\n    statusFooterButttonsModal(true);\n    api.updateColor(color)\n      .then((response: AxiosResponse) => {\n        const { data } = response;\n        swal(response.data.message, {\n          icon: 'success'\n        });\n        dispatch(updateColorAction(data.result));\n        statusFooterButttonsModal(false);\n        showModal(false);\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function deleteColorThunkAction(color: IColor) {\n  return (dispatch: Dispatch<ColorReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.deleteColor(color)\n      .then((response: AxiosResponse) => {\n        const { data } = response;\n        dispatch(deleteColorAction(data.id));\n      });\n  };\n}\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { Field, InjectedFormProps, reduxForm } from 'redux-form';\nimport { IReasonsState } from '../../actions/reasons.types';\nimport InputField from '../Utils/forms/InputField';\nimport { inputStringRequired } from '../Utils/forms/validations';\n\ninterface IPropsType extends InjectedFormProps {\n  update: boolean;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass Form extends React.Component<IPropsType, IStateType> {\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n  public render(): React.ReactElement<IPropsType> {\n    const { handleSubmit, valid , submitFailed} = this.props;\n    return (\n      <form onSubmit={handleSubmit}>\n        <div className=\"row\">\n          <div className=\"col-md-12\">\n            <Field\n              name=\"name\"\n              label=\"Nombre *\"\n              placeholder=\"Nombre\"\n              type=\"text\"\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>\n          {\n            submitFailed && valid === false &&\n            <div className=\"col-md-12\">\n              <div\n                className=\"alert alert-danger\"\n                style={{marginTop: '20px'}}\n              >\n                Todos los campos con * son obligatorios\n              </div>\n            </div>\n          }\n        </div>\n      </form>\n    );\n  }\n}\n\nconst ColorForm = reduxForm({\n  form: 'colorForm'\n})(Form);\n\nconst mapStateToProps = (state: { reasons: IReasonsState }) => {\n  return {\n    reasons: state.reasons\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{ reasons: IReasonsState }, { dispatch: any }, IPropsType | {}>(mapStateToProps, mapDispatchToProps)(ColorForm);\n","import {RouteComponentProps} from \"react-router\";\nimport {Dispatch} from \"redux\";\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\nimport AppContainer from \"../../container/AppContainer\";\nimport * as React from \"react\";\nimport {ErrorInfo} from \"react\";\nimport * as Raven from \"raven-js\";\nimport {connect} from \"react-redux\";\nimport {\n  getMyStudiosAction,\n  IStatsDashboardState,\n  StatsDashboardReducerAction\n} from \"../../actions/statsDashboard.actions\";\nimport {StatsDashboardTypes} from \"../../../../../../src/stats/models/studio.model\";\nimport {IStudio} from \"../../../../../../src/stats/interfaces/studio.interface\";\nimport Row from \"../Utils/Row\";\n\ninterface IPropsType extends RouteComponentProps<{ }> {\n  dispatch: Dispatch<StatsDashboardReducerAction>;\n  dashboard: IStatsDashboardState;\n  getMyStudiosAction(type?: StatsDashboardTypes): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  menu: string;\n  cSubmenu: string;\n  type: StatsDashboardTypes;\n  tab: String;\n}\n\nclass DashboardStatsView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n  state = {\n    error: null,\n    menu: \"\",\n    cSubmenu: \"\",\n    tab: \"0\",\n    type: StatsDashboardTypes.UNIT_CONTROL,\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = \"Dashboard de Estadísticas\";\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    this.props.getMyStudiosAction(this.state.type)\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any) {\n    if (prevProps.dashboard.loading && !this.props.dashboard.loading && this.props.dashboard.studios.length > 0){\n      this.setState({\n        tab: this.props.dashboard.studios[0]._id as String\n      })\n    }\n  }\n\n  private changeTab(name: string): void {\n    this.setState({\n      tab: name\n    });\n  }\n\n\n  render() {\n    const {studios, loading} = this.props.dashboard;\n    const { tab } = this.state;\n    const selectedStudio : IStudio | undefined = studios.find((studio: IStudio) => studio._id === tab);\n    return <AppContainer title=\"\" cMenu={this.state.menu} cSubMenu={this.state.cSubmenu}>\n      <section className=\"content\">\n        <div className=\"box\">\n          <div className=\"box-header with-border\">\n            <h3 className=\"box-title\">Dashboard de Estadísticas</h3>\n          </div>\n          <div className=\"box-body\">\n            {\n              loading &&\n              <div className=\"overlay\">\n                <i className=\"fa fa-spinner fa-spin text-purple\"/>\n              </div>\n            }\n            {\n              !loading && studios.length == 0 &&\n              <div className=\"row\">\n                <div className=\"col-md-12\">\n                  <p>No se han encontrado resultados.</p>\n                </div>\n              </div>\n            }\n            {!loading && studios.length > 0 &&\n              <div className=\"col-md-12 col-lg-12\">\n                <div className=\"box box-solid\">\n                  <ul className=\"nav nav-pills nav-justified\">\n                    {\n                      studios.map((studio: any) => {\n                        return (\n                          <li className={tab === studio._id ? 'active' : ''} key={studio._id}>\n                          <a\n                            href=\"javascript:void(0);\"\n                            className={tab === studio._id ? 'background-transition' : ''}\n                            style={{borderTop: '0', marginBottom: '0'}}\n                            onClick={() => this.changeTab(studio._id)}\n                          >{studio.name}</a>\n                        </li>\n                        )\n                      })\n                    }\n                  </ul>\n                </div>\n              </div>\n            }\n            { selectedStudio &&\n              <Row>\n                <div className=\"col-md-12\">\n                  <div className=\"box\">\n                    <div className=\"box-header with-border\"><h1 className=\"box-title\">Dashboard de análisis de datos</h1>\n                    </div>\n                    <div className=\"box-body\">\n                      <iframe src={selectedStudio.embedURL} style={{width: \"100%\", minWidth: \"1000px\" ,minHeight: \"500px\", height: \"100vh\"}} allowFullScreen={true}  frameBorder={0} security={\"\"}/>\n                    </div>\n                  </div>\n                </div>\n              </Row>\n            }\n          </div>\n        </div>\n      </section>\n    </AppContainer>\n  }\n}\n\nconst mapStateToProps = (state: { statsDashboard: IStatsDashboardState }) => {\n  return {\n    dashboard: state.statsDashboard,\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getMyStudiosAction: (type?: StatsDashboardTypes) => dispatch(getMyStudiosAction(type))\n  };\n};\n\n\nclass InventoryDashboardStatsView extends DashboardStatsView {\n  state = {\n    error: null,\n    loading: true,\n    menu: \"2\",\n    cSubmenu: \"2.5\",\n    type: StatsDashboardTypes.INVENTORY,\n    tab: \"\",\n  };\n}\n\nclass UnitControlDashboardStatsView extends DashboardStatsView {\n  state = {\n    error: null,\n    loading: true,\n    menu: \"1\",\n    cSubmenu: \"1.7\",\n    type: StatsDashboardTypes.UNIT_CONTROL,\n    tab: \"\",\n  };\n}\n\nclass DistributionDashboardStatsView extends DashboardStatsView {\n  state = {\n    error: null,\n    loading: true,\n    menu: \"3\",\n    cSubmenu: \"3.5\",\n    type: StatsDashboardTypes.DISTRIBUTION,\n    tab: \"\",\n  };\n}\n\nclass PlanificationDashboardStatsView extends DashboardStatsView {\n  state = {\n    error: null,\n    loading: true,\n    menu: \"3\",\n    cSubmenu: \"3.5\",\n    type: StatsDashboardTypes.PLANIFICATION,\n    tab: \"\",\n  };\n}\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DashboardStatsView);\nlet VInventoryDashboardStatsView =  connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(InventoryDashboardStatsView);\nlet VUnitControlDashboardStatsView = connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(UnitControlDashboardStatsView);\nlet VDistributionDashboardStatsView = connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DistributionDashboardStatsView);\nlet VPlanificationDashboardStatsView = connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(PlanificationDashboardStatsView);\nexport { VInventoryDashboardStatsView, VUnitControlDashboardStatsView, VDistributionDashboardStatsView, VPlanificationDashboardStatsView };\n","import {RouteComponentProps} from \"react-router\";\nimport {Dispatch} from \"redux\";\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\nimport AppContainer from \"../../container/AppContainer\";\nimport * as React from \"react\";\nimport {ErrorInfo} from \"react\";\nimport * as Raven from \"raven-js\";\nimport {connect} from \"react-redux\";\nimport {\n  changeTempStudioAction, createStudioAction, deleteStudioAction, editStudioAction,\n  getStudiosAction,\n  IStatsDashboardState, ITempStudio, loadStudioUsersAction,\n  StatsDashboardReducerAction\n} from \"../../actions/statsDashboard.actions\";\nimport {DashboardTypesDictionary, StatsDashboardTypes} from \"../../../../../../src/stats/models/studio.model\";\nimport {IStudio} from \"../../../../../../src/stats/interfaces/studio.interface\";\nimport {hasPermission} from \"../../utils/common\";\nimport * as moment from \"moment\";\nimport Paginator from \"../Utils/Paginator\";\nimport ModalView from \"../Modal/ModalView\";\nimport {IWindow} from \"../../interfaces/window\";\nimport {loadDataAction, ModalReduxAction} from \"../../actions/modal.actions\";\nimport {RegionReduxAction} from \"../../actions/regions.actions\";\nimport * as swal from 'sweetalert';\nimport StudioFormView from \"./StudioFormView\";\n\ninterface IPropsType extends RouteComponentProps<{ }> {\n  dispatch: Dispatch<StatsDashboardReducerAction>;\n  dashboard: IStatsDashboardState;\n  getStudiosAction(type?: StatsDashboardTypes | null): void;\n  loadStudioUsers(): void;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n  changeTempStudioAction(studio: ITempStudio): void;\n  deleteStudio(studio: IStudio): void;\n  processCreateStudio(): void;\n  processEditStudio(): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  type: StatsDashboardTypes | null;\n}\n\ndeclare let window: IWindow;\n\nclass DashboardStatsListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n  state = {\n    error: null,\n    type: null,\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = \"Configuración de Studios\";\n\n    this.processEditStudio = this.processEditStudio.bind(this);\n    this.createStudio = this.createStudio.bind(this);\n    this.processCreateStudio = this.processCreateStudio.bind(this);\n    this.deleteStudio = this.deleteStudio.bind(this);\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    this.props.getStudiosAction(this.state.type);\n    this.props.loadStudioUsers();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  private showStudioModal(studio?: IStudio): void {\n    this.props.changeTempStudioAction(studio ?? {\n      name: \"\",\n      team: window.user.team._id,\n      _id: '',\n      embedURL: '',\n      type: '',\n      users: []\n    });\n    setTimeout(() => {\n      this.props.loadDataAction(\n        studio ? 'Editar Studio' : 'Agregar Studio',\n        <StudioFormView\n          changeTempStudioAction={this.props.changeTempStudioAction}\n          users={this.props.dashboard.users}\n          types={Object.keys(DashboardTypesDictionary).map(key => {\n            return {id: key, name: DashboardTypesDictionary[key]}\n          })}\n          dashboard={this.props.dashboard}\n        />,\n        <React.Fragment>\n          <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n          <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={studio ? this.processEditStudio : this.processCreateStudio}>Grabar</button>\n        </React.Fragment>\n      );\n    }, 400);\n  }\n\n  public createStudio(studio: IStudio){\n\n  }\n\n  private processCreateStudio(): void {\n    const {tempStudio} = this.props.dashboard;\n    if (!tempStudio.name || !tempStudio.name.trim()) {\n      swal('Agregar Studio', 'El nombres es requerido', 'error');\n    } else if (!tempStudio.embedURL || !tempStudio.embedURL.trim()){\n      swal('Agregar Studio', 'El URL es requerido', 'error');\n    } else {\n      this.props.processCreateStudio();\n    }\n  }\n\n  private processEditStudio(): void {\n    const {tempStudio} = this.props.dashboard;\n    if (!tempStudio.name || !tempStudio.name.trim()) {\n      swal('Editar Studio', 'El nombres es requerido', 'error');\n    } else if (!tempStudio.embedURL || !tempStudio.embedURL.trim()){\n      swal('Editar Studio', 'El URL es requerido', 'error');\n    } else {\n      this.props.processEditStudio();\n    }\n  }\n\n  private deleteStudio(studio: IStudio) {\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el Dashboard: ${studio.name || ''}`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete: any) => {\n      if (willDelete) {\n        this.props.deleteStudio(studio);\n      }\n    });\n  }\n\n  private changePage(page: number): void {\n  }\n\n\n  public render(): React.ReactElement<IPropsType> {\n    const {studios, loading, pagination} = this.props.dashboard;\n\n    return (\n      <AppContainer title=\"\" cMenu=\"10\" cSubMenu=\"10.11\" cAction=\"Listado\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Studios <small>{pagination.count}</small></h3>\n              <div className=\"box-tools pull-right\">\n                {\n                  hasPermission(window.user, 'addStatsDashboard') ?\n                    <button className=\"btn btn-sm btn-success\" onClick={() => this.showStudioModal()}><i className=\"fa fa-plus\" />  Agregar</button>\n                    : null\n                }\n              </div>\n            </div>\n            <div className=\"box-body no-padding\">\n              <table className=\"table table-andes table-striped\">\n                <thead>\n                <tr>\n                  <th style={{width: '30%'}} className=\"middle\">Nombre</th>\n                  <th style={{width: '30%'}} className=\"middle\">Tipo</th>\n                  <th style={{width: '20%'}} className=\"middle hidden-xs\">Modificado</th>\n                  {\n                    hasPermission(window.user, 'changeStatsDashboard') ?\n                      <th style={{width: '1%'}} className=\"width-10\"/> : null\n                  }\n                  {\n                    hasPermission(window.user, 'deleteStatsDashboard') ?\n                      <th style={{width: '1%'}} className=\"width-10\"/> : null\n                  }\n                </tr>\n                </thead>\n                <tbody>\n                {\n                  !loading && !studios.length?\n                    <tr>\n                      <td\n                        colSpan={2 + (hasPermission(window.user, 'deleteStatsDashboard') ? 1 : 0) +( hasPermission(window.user, 'changeStatsDashboard') ? 1 : 0)}\n                      >\n                        No se han creado análisis estadisticos\n                      </td>\n                    </tr>\n                    :null\n                }\n                {\n                  studios.map((studio: IStudio) => {\n                    return (\n                      <tr\n                        key={studio._id}\n                        id={`studio-${studio._id}`}\n                        className={'background-transition'}\n                      >\n                        <td className=\"middle\">{studio.name}</td>\n                        <td className=\"middle\">{DashboardTypesDictionary[studio.type]}</td>\n                        <td className=\"middle hidden-xs\">{moment(studio.updatedAt).format('LLL')}</td>\n                        {\n                          hasPermission(window.user, 'changeStatsDashboard') ?\n                            <td\n                              className=\"middle text-blue pointer\"\n                              onClick={() => this.showStudioModal(studio)}\n                            >\n                              <i className=\"fa fa-pencil\"/>\n                            </td> : null\n                        }\n                        {\n                          hasPermission(window.user, 'deleteStatsDashboard') ?\n                            <td\n                              className={'middle text-red pointer'}\n                              onClick={() => this.deleteStudio(studio)}\n                            ><i className=\"fa fa-minus-circle\"/></td> : null\n                        }\n                      </tr>\n                    );\n                  })\n                }\n                </tbody>\n              </table>\n            </div>\n            {\n              pagination.pages > 1 &&\n              <div className=\"box-footer text-right\">\n                <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n              </div>\n            }\n            {\n              loading &&\n              <div className=\"overlay\">\n                <i className=\"fa fa-spinner fa-spin text-purple\"/>\n              </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>)\n  }\n}\n\nconst mapStateToProps = (state: { statsDashboard: IStatsDashboardState }) => {\n  return {\n    dashboard: state.statsDashboard,\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getStudiosAction: (type?: StatsDashboardTypes) => dispatch(getStudiosAction(type)),\n    changeTempStudioAction: (studio: ITempStudio) => dispatch(changeTempStudioAction(studio)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer)),\n    deleteStudio: (studio: IStudio) => dispatch(deleteStudioAction(studio._id)),\n    loadStudioUsers: () => dispatch(loadStudioUsersAction()),\n    processCreateStudio: () => dispatch(createStudioAction()),\n    processEditStudio: () => dispatch(editStudioAction()),\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DashboardStatsListView);\n\n","import * as React from \"react\";\nimport {RouteComponentProps} from \"react-router\";\nimport {Dispatch} from \"redux\";\nimport {\n  IStatsDashboardState, ITempStudio,\n} from \"../../actions/statsDashboard.actions\";\nimport {IWindow} from \"../../interfaces/window\";\nimport {IBaseVenue, IUser, IVenue} from \"../../../../../../src/app/interfaces\";\nimport {IStudio} from \"../../../../../../src/stats/interfaces/studio.interface\";\nimport {ErrorInfo} from \"react\";\nimport * as Raven from \"raven-js\";\nimport {connect} from \"react-redux\";\n\ninterface IPropsType {\n  dashboard: IStatsDashboardState;\n  users: IUser[];\n  types: any[];\n  changeTempStudioAction(studio: ITempStudio): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass StudioFormView extends React.Component<IPropsType, IStateType>{\n\n  readonly state = {\n    error: null,\n    selectedUsers: []\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidMount() {\n    const chosenOptions = {\n      no_results_text: 'Sin resultados para:'\n    };\n\n    ($('#id-types') as any).chosen(chosenOptions).change((e: React.ChangeEvent<HTMLSelectElement>) => {\n      this.chooseType(e.target.value);\n    });\n\n    ($('#id-users') as any).chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n        this.addUser(e.target.value);\n      });\n  }\n\n\n\n  componentDidUpdate() {\n    $('#id-users').trigger('chosen:updated');\n    $('#id-types').trigger('chosen:updated');\n  }\n\n  private chooseType(type: string) {\n    const {changeTempStudioAction} = this.props;\n    const {tempStudio} = this.props.dashboard;\n    changeTempStudioAction({...tempStudio, type});\n  }\n\n  private addUser(id: string) {\n    let user = this.props.users.find((user: IUser) => user._id === id);\n    const {tempStudio} = this.props.dashboard;\n    let {users} = tempStudio;\n    if (user != undefined && !users.find((u: IUser) => u._id === user!!._id)) {\n      users.push(user);\n      this.props.changeTempStudioAction({\n          ...tempStudio,\n          users\n        }\n      )\n    }\n  }\n\n  private deleteUser(user: IUser){\n    const {tempStudio} = this.props.dashboard;\n    this.props.changeTempStudioAction({\n      ...tempStudio,\n      users: tempStudio.users.filter((u: IUser) => u._id !== user._id)\n      }\n    )\n  }\n\n  public render() {\n    const { changeTempStudioAction, users, types } = this.props;\n    const { tempStudio } = this.props.dashboard;\n\n    return (\n      <React.Fragment>\n        <ul className=\"nav nav-tabs\" style={{marginBottom: '15px'}}>\n          <li className=\"active\"><a data-toggle=\"tab\" href=\"#general\">General</a></li>\n        </ul>\n        <div className=\"tab-content\">\n          <div id=\"general\" className=\"tab-pane fade in active\">\n            <div className=\"row\">\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>Nombre</label>\n                  <input\n                    type=\"text\"\n                    name=\"name\"\n                    className=\"form-control\"\n                    maxLength={50}\n                    defaultValue={tempStudio ? tempStudio.name : undefined}\n                    onChange={(e: React.ChangeEvent<HTMLInputElement>) => changeTempStudioAction({\n                      ...tempStudio,\n                      name: e.target.value})}\n                  />\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>URL</label>\n                  <input\n                    type=\"text\"\n                    name=\"embedURL\"\n                    className=\"form-control\"\n                    maxLength={50}\n                    defaultValue={tempStudio ? tempStudio.embedURL : undefined}\n                    onChange={(e: React.ChangeEvent<HTMLInputElement>) => changeTempStudioAction({\n                      ...tempStudio,\n                      embedURL: e.target.value})}\n                  />\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label htmlFor=\"id-types\">Tipo</label>\n                  <select\n                    className=\"chosen-select form-control\"\n                    id=\"id-types\"\n                    name=\"type\"\n                    defaultValue={tempStudio ? tempStudio.type : undefined}\n                    onChange={(e: React.ChangeEvent<HTMLSelectElement>) => changeTempStudioAction({\n                      ...tempStudio,\n                      type: e.target.value})}\n                    data-placeholder={'Seleccione...'}\n                  >\n                    <option value=\"\" />\n                    {\n                      types.map((type) => (\n                        <option key={type.id} value={type.id}>{type.name}</option>\n                      ))\n                    }\n                  </select>\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label htmlFor=\"id-users\">Usuarios</label>\n                  <select\n                    id=\"id-users\"\n                    className=\"chosen-select form-control\"\n                    style={{minWidth: '200px'}}\n                    onChange={undefined}\n                    data-placeholder={'Seleccione...'}\n                  >\n                    <option value=\"\" />\n                    {\n                      users.filter(user => !tempStudio.users.find(u => u._id == user._id)).map((user) => {\n                        return (\n                          <option key={user._id} value={user._id}>{user.firstName} {user.lastName}</option>\n                        );\n                      })\n                    }\n                  </select>\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <table className=\"table table-striped\">\n                  <thead>\n                  <tr>\n                    <th style={{width: '90%'}}>Name</th>\n                    <th style={{width: '10%'}}/>\n                  </tr>\n                  </thead>\n                  <tbody>\n                  {\n                    tempStudio.users.length ? tempStudio.users.map((user: IUser) => {\n                        return (\n                          <tr key={user._id}>\n                            <td>{user.firstName} {user.lastName}</td>\n                            <td\n                              className=\"text-center text-red pointer\"\n                              onClick={() => this.deleteUser(user)}\n                            >\n                              <i className=\"fa fa-minus-circle\"/>\n                            </td>\n                          </tr>\n                        );\n                      }) :\n                      <tr>\n                        <td colSpan={2}>Aún no se han seleccionado usuarios.</td>\n                      </tr>\n                  }\n                  </tbody>\n                </table>\n              </div>\n            </div>\n          </div>\n        </div>\n      </React.Fragment>\n    );\n  }\n}\n\n\nconst mapStateToProps = (state: { statsDashboard: IStatsDashboardState }) => {\n  return {\n    dashboard: state.statsDashboard\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(StudioFormView);\n"],"sourceRoot":""}
